QuestStoryData = { v = 1, built = "2026-11-20 17:52", q = {
[2]={a={"강력한 히포그리프 뾰족발톱이 쓰러졌어요.","그 발톱은 승리를 보여 주는 증거가 된대요.","토막나무 주둔지의 세나니 썬더하트에게 보여 달래요."},c={"정말 대단해요! 이 발톱을 얻기는 쉽지 않았을 거예요.","뾰족발톱은 벌목장 일꾼들을 오랫동안 괴롭혔대요.","이제 모닥불 곁에서 그 용기를 노래할 거래요."}},
[8]={a={"캘빈 몬테그가 편지 한 통을 들고 있어요.","편지는 브릴에 있는 여관주인 리니에게 가야 해요.","그러니 그 편지를 리니에게 전해 달래요."},c={"리니는 편지를 받고 데스넬의 어머니 소식이라 기뻐해요.","그러고는 당신에게 무뚝뚝하게 나가라고 해요."},nx=590,nt="A Rogue's Deal"},
[10]={a={"선임측량사 피즐도저의 수석 조수가 사막에서 실종됐어요.","마지막 보고에는 이상한 곤충이 수없이 나타났대요.","모래지옥 협곡에 가서 슈섕크를 찾아 달라고 부탁해요."},nx=110,nt="Insect Part Analysis"},
[23]={a={"강력한 곰 우르산고우스가 쓰러졌어요.","앞발에 작은 초승달 문장이 있는데 뜻은 아무도 몰라요.","그 앞발을 세나니 썬더하트에게 가져가 달래요."},c={"우르산고우스의 앞발이네요! 정말 대단한 솜씨예요.","초승달 문양은 밤의 요정에게 훈련받은 흔적인 것 같대요.","예전엔 이 지역에서 손꼽히던 곰이었대요."}},
[24]={a={"빠르던 흑호 샤둠브라가 쓰러졌어요.","이 머리는 이번 사냥의 멋진 전리품이래요.","세나니 썬더하트에게 보여 주면 사냥을 인정해 준대요."},c={"토막나무 주둔지에서 난폭하기로 유명했대요.","서쪽 해안으로 나가는 길이 아주 위험했대요.","덕분에 그 위험이 사라졌대요."}},
[25]={a={"마스토크 윌리히스는 운송 행렬이 멈춰서 걱정이에요.","호수의 정령들이 지나는 이들을 마구 공격한대요.","미스트랄 호수 정령을 처치하고 전망대를 살펴봐 달래요."},c={"호수를 뒤흔든 자가 있다는 소문을 들었대요.","얼라이언스를 살필 관측지를 만들 수도 있대요.","운송 행렬도 이제 한결 수월해질 거래요."}},
[27]={a={"투락 룬토템은 나의 성장을 지켜봐 왔대요.","이제 물을 다루는 수중 형상을 배울 차례래요.","달숲의 밤의 안식처에서 덴드리트 스타블레이즈를 만나래요."},c={"덴드리트 스타블레이즈가 수중 형상을 알려 준대요.","먼저 물속 압박을 견디는 시험을 치러야 해요."},nx=28,nt="Trial of the Lake"},
[28]={a={"덴드리트 스타블레이즈가 첫 번째 시험을 내줬어요.","제단 구슬은 금방 썩어서 서둘러야 한대요.","엘룬아라 호수에서 구슬을 찾아 레물로스의 제단에 가져가래요."},nx=30,nt="Trial of the Sea Lion"},
[30]={a={"타자리가 두 번째 시험을 내줬어요.","바다표범의 펜던트가 두 조각으로 쪼개져 있대요.","조각을 찾아 합쳐서 덴드리트 스타블레이즈에게 가져가래요."},c={"덴드리트 스타블레이즈가 시험을 마친 나를 축하해요.","민첩성과 인내 중 어느 하나만으론 안 된대요.","이 가르침을 잘 기억하라고 당부해요."},nx=31,nt="Aquatic Form"},
[31]={a={"덴드리트 스타블레이즈가 기본 수업을 다 끝냈대요.","이제 수중 형상을 배울 차례래요.","썬더 블러프에서 투락 룬토템에게 펜던트를 보이래요."}},
[32]={a={"선임측량사 피즐도저가 보고서를 건네줘요.","생물과 역사에 밝은 학자에게 가져가라고 해요.","오그리마의 질지빈 드럼로어에게 전해 달래요."},c={"질지빈은 이 생물들을 전에도 상대해 봤대요.","이 곤충은 silithid라고 불러요.","호드와 얼라이언스 모두의 큰 위협이래요."}},
[63]={a={"이슬렌 워터시어 말로는 근처 정령들이 이제 말을 안 한대요.","타락한 물의 현신을 쓰러뜨려 연못을 정화해야 한대요.","그 팔보호구와 순수한 물을 화로 위에 올려 달래요."},c={"팔보호구를 화로 위에 올리고 물을 불에 부어요.","물이 탁탁 튀자 이슬렌 워터시어에게 배운 주문을 외우기 시작해요."},nx=100,nt="Call of Water"},
[77]={a={"길버라딘 선체이서에게 드란 드로퍼스가 찾는 포장 재료가 있어요.","추가로 리플을 가져오면 포장을 도와주겠대요.","굼벵이 바위굴 근처 상자에서 리플을 구해 달래요."},c={"길버라딘은 리플이 상하지 않아서 기뻐해요.","마법 없이 빈 포장재로 술병을 포장한대요.","오래 남을 술 보물로 만들겠대요."},nx=81,nt="Ripple Delivery"},
[81]={a={"길버라딘 선체이서가 리플을 술통에 잘 담아 뒀어요.","드란이 부탁한 병도 따로 챙겨 뒀대요.","오그리마의 고물상에 술통을 가져다 달래요."},c={"드란 드로퍼스는 술통 속 리플이 다 있다고 확인해요.","보수를 주며 일을 잘했다고 칭찬해요.","여분의 리플은 특별한 날 샴페인과 마시겠대요."}},
[82]={a={"선임측량사 피즐도저가 곤충의 정체를 알고 싶어해요.","곤충들이 물웅덩이의 물을 다 빨아 먹고 있대요.","맹독의 둥지에서 곤충 부위를 구해 연금술사 페슬저그에게 맡겨 달래요."},c={"연금술사 페슬저그는 이 곤충을 처음 본다고 해요.","곤충이 외부의 힘에 조종되는 것 같대요.","선임측량사 피즐도저에게 바로 가 보라고 해요."},nx=10,nt="The Scrimshank Redemption"},
[96]={a={"하급 물의 현신이 물의 결정을 가져가라고 해요.","물은 생명이고 부패는 생명을 멈춘대요.","그 결정을 불모의 땅 이슬렌 워터시어에게 가져다 달래요."},c={"이슬렌 워터시어가 증거를 보고 잘했다고 칭찬해요.","물 토템을 주며 다음 시험은 한참 뒤라고 해요.","샤먼 교관을 찾아가 주문을 더 배우라고 권해요."}},
[99]={a={"달라 던위버는 아루갈의 마법을 연구하고 있어요.","장작나무 마을 사람들은 밤이면 늑대인간으로 변한대요.","마법 족쇄를 가져와 달라고 부탁해요."},c={"달라는 당신의 끈기를 칭찬하며 고마워해요.","당신이 모은 지식으로 아루갈이 무너지고 마법도 풀릴 거래요."},nx=98298,nt="Arugal's Folly"},
[100]={a={"주문을 마치자 빛이 터지고 타락한 영혼이 사라졌대요.","그 여파로 감각이 압도됐대요.","은빛소나무 숲의 하급 물의 현신과 대화해 달래요."},nx=96,nt="Call of Water"},
[103]={a={"그레이슨 선장은 서부 몰락지대 등대의 불을 맡게 됐어요.","등대 불을 지킬 사람이 없어서 배들이 위험하대요.","허수아비 괴물들을 처치하고 기름 주머니를 구해 달래요."},c={"그레이슨은 당신 덕분에 해안 암초 근처에 등불이 켜진대요.","그레이슨은 자신처럼 죽는 사람이 없길 바란대요."}},
[104]={a={"선장 그레이슨은 암초에 배가 부서져 목숨을 잃었대요.","늙은 거먹눈 멀록이 등대지기 가족을 해쳤대요.","그 멀록을 처치하고 비늘 하나를 가져다 달래요."},c={"늙은 거먹눈 멀록이 드디어 쓰러졌군요.","한 목숨은 떠났지만 더 많은 목숨을 지켰을지도 몰라요.","덕분에 대해도 한결 안전해졌대요."}},
[105]={a={"고위집행관 델링턴이 안돌할을 되찾으려 해요.","그곳 폐허에 소환사 아라즈라는 리치가 있대요.","아라즈를 없애고 성물함 조각을 증거로 가져오래요."}},
[110]={a={"선임측량사 피즐도저는 슈섕크의 일을 정리하는 중이에요.","곤충들 때문에 더 큰 피해가 생길 것 같대요.","연금술사 페슬저그에게 곤충 분석이 끝났는지 물어봐 달래요."},c={"페슬저그는 분석 결과가 아주 불안하다고 해요.","곤충이 외부의 힘에 조종당하는 게 맞대요.","곤충들은 닥치는 대로 파괴하도록 바뀌었대요."},nx=113,nt="Insect Part Analysis"},
[113]={a={"연금술사 페슬저그가 곤충 분석 보고서를 건네요.","이 위협은 칼림도어 전체로 번질 수 있대요.","피즐도저에게 보여 주고 사본을 받아 달래요."},c={"피즐도저는 보수를 주며 보고서를 고마워해요.","정보를 아끼지만 페슬저그의 추천이라 허락했대요.","지금 사본을 만들어 준다고 해요."}},
[136]={a={"샌더 선장이 바다에 수장됐을 거래요.","이제 보물은 당신 것이니 단서를 찾으래요.","먼저 서쪽 해안 난파선 근처에서 사물함을 찾아 달래요."},c={"사물함을 열자 모래와 물만 나왔어요.","그런데 작은 게가 집게에 단서를 물고 튀어나와요."},nx=138,nt="Captain Sander's Hidden Treasure"},
[138]={a={"샌더 선장의 보물 단서가 적힌 글이에요.","이번에는 정동쪽 절벽 길을 따라가래요.","낡은 굴뚝 잔해 근처의 낡은 통에서 다음 단서를 찾으래요."},nx=139,nt="Captain Sander's Hidden Treasure"},
[139]={a={"부서진 통 안에서 또 다른 양피지가 나왔어요.","양피지에는 여기서 북쪽으로 가라고 적혀 있대요.","해안 절벽의 풍차 옆 낡은 단지를 살펴보래요."},c={"보물 찾는 당신에게 대박이 가까워졌다고 해요."},nx=140,nt="Captain Sander's Hidden Treasure"},
[140]={a={"낡은 단지 안에서 또 다른 단서가 나왔어요.","종이에서 위스키 냄새가 나고 잉크도 번졌대요.","서쪽 바다로 헤엄쳐 가서 보물 상자를 찾으래요."},c={"당신이 상자를 억지로 열고 보물을 챙겼어요.","샌더 선장의 보물을 찾은 걸 축하한대요."}},
[152]={a={"그레이슨 선장은 해안에 가라앉은 난파선을 걱정해요.","선원들이 안전히 닿도록 해안의 위험을 없애야 해요.","해안을 어지럽히는 멀록들을 처치해 달래요."},c={"그레이슨은 당신의 전투 실력이 대단하다고 칭찬해요.","덕분에 서부 몰락지대 해안이 더 안전해졌대요."}},
[185]={a={"아제크 루아크는 어릴 때 아버지에게 호랑이 사냥을 배웠어요.","어린 호랑이는 추적하기 쉬워서 연습하기 좋대요.","야영지 근처의 어린 호랑이를 사냥해 보래요."},c={"잘하셨어요. 이제 다음 단계로 넘어가도 된대요."},nx=186,nt="Tiger Mastery"},
[186]={a={"아제크 루아크가 훈련을 계속하자고 해요.","이번엔 다 자란 가시덤불 호랑이가 상대래요.","그 호랑이를 사냥해서 실력을 보여 달래요."},nx=187,nt="Tiger Mastery"},
[187]={a={"아제크 루아크가 이제 진짜 시험을 준비했대요.","덩치큰 가시덤불 호랑이는 찾기도 어렵고 사납대요.","그 호랑이를 사냥하면 최종 심사를 받게 된대요."},c={"정말 대단해요. 거의 준비가 끝났대요."},nx=188,nt="Tiger Mastery"},
[188]={a={"아제크 루아크는 오랫동안 신달이라는 호랑이를 쫓아왔대요.","아무도 못 잡은 신달을 잡아 보래요.","신달의 앞발을 증거로 가져오라고 해요."},c={"정말 대단해요! 이제 진정한 호랑이 사냥 대가가 됐대요."}},
[189]={a={"케복의 대원들이 정글 트롤에게 계속 당하고 있어요.","경비병을 많이 잃어서 남작 레빌가즈께 설명할 길이 없대요.","붉은머리부족 트롤의 귀를 가져오면 보상하겠대요."},c={"아, 좋아요. 당장은 조금 도움이 되겠네요.","아직 계셨어요? 보상을 잊고 있었네요.","자, 이걸 받으세요. 충분할 거예요."},nx=209,nt="Skullsplitter Tusks"},
[190]={a={"얼가딘 경이 원정대에 들어오려면 실력을 증명하래요.","쫓아가기만도 힘든 새끼 퓨마부터 시작한대요.","새끼 퓨마를 사냥해 실력을 보여 달라고 해요."},nx=191,nt="Panther Mastery"},
[191]={a={"얼가딘 경이 이제 한 단계 어려운 임무를 내줬어요.","다 자란 퓨마는 새끼보다 훨씬 힘들대요.","그 퓨마를 사냥해 실력을 보여 달래요."},nx=192,nt="Panther Mastery"},
[192]={a={"얼가딘 경이 이제 가장 어려운 과제를 내놨어요.","그림자퓨마는 정글에서 제일 위험한 짐승이래요.","그 그림자퓨마를 쓰러뜨려 실력을 증명해 달래요."},nx=193,nt="Panther Mastery"},
[193]={a={"얼가딘 경이 퓨마 사냥 실력을 거의 인정했대요.","정글에 바그테라라는 거대한 퓨마가 어슬렁거린대요.","그 바그테라를 처치하고 송곳니를 가져다 달래요."},c={"거대한 바그테라가 드디어 쓰러졌어요."}},
[194]={a={"헤멧 네싱워리가 사냥 실력을 시험해 보겠대요.","가시덤불랩터가 어디 있는지는 알려 주지 않는대요.","정글에 들어가 가시덤불랩터를 사냥해 보래요."},nx=195,nt="Raptor Mastery"},
[195]={a={"헤멧 네싱워리가 다음 시험을 내놓았대요.","이번엔 지독한 채찍꼬리랩터가 상대래요.","정글에 들어가 채찍꼬리랩터를 사냥해 보래요."},c={"전리품을 벽난로 위에 걸 만하네요."},nx=196,nt="Raptor Mastery"},
[196]={a={"헤멧 네싱워리가 다음 사냥 과제를 내줘요.","줄무늬정글랩터는 찾기도 잡기도 아주 어렵대요.","그놈들을 잡으면 최고의 사냥을 알려 준대요."},c={"헤멧 네싱워리가 진정한 랩터 사냥꾼이라고 좋아해요."},nx=197,nt="Raptor Mastery"},
[197]={a={"헤멧 네싱워리가 당신의 실력을 칭찬해요.","헤멧도 못 잡은 포악한 랩터 테디스가 있대요.","테디스를 잡고 발톱을 가져와 달라고 해요."},c={"헤멧이 랩터 사냥의 대가라고 부르며 좋아해요."},nx=208,nt="Big Game Hunter"},
[201]={a={"크라젝이 사냥꾼 무리의 야영지 소식을 들었대요.","그 무리에 헤멧 네싱워리도 있다는데 조심해야 한대요.","야영지를 살펴보고 무슨 일인지 알아봐 달래요."},c={"제 정보가 역시 맞았군요.","그들이 우리 좋은 제품을 쓸 일이 있을지도 모르겠네요.","그들이 우리 사업을 방해하지는 않을 것 같아요."}},
[208]={a={"헤멧 네싱워리가 당신을 동료 사냥꾼으로 인정해요.","헤멧은 오래전부터 야수왕 뱅갈라시를 쫓아왔대요.","야수왕 뱅갈라시의 머리를 가져와 달라고 해요."},c={"다른 사냥꾼이 실패한 일을 해냈다고 축하해요.","이제 함께하는 동료로서 실력을 인정한대요."}},
[209]={a={"케복은 남쪽 섬에 보낼 호랑이 송곳니가 모자라요.","비슷한 재료로 가짜 송곳니를 만들 수 있대요.","백골가루부족 트롤의 어금니를 많이 가져다 달래요."},c={"케복은 일을 잘했다며 고맙다고 해요.","어금니 손질이 조금 아쉽다고도 해요.","덕분에 생산량이 늘겠다고 기뻐해요."}},
[213]={a={"겔리즈가 큰 일을 벌여서 케복이 골치래요.","투자개발회사 지질학자들이 파란 수정에 큰 관심이래요.","그 수정 견본을 어떻게든 구해 오래요."},c={"이 수정을 이렇게 갈아 낸 걸 보니 연료나 촉매로 쓰려는 것 같대요.","그 이상은 잘 모르겠어요.","견본은 수석 화학자에게 보내야 한대요."}},
[216]={a={"엉겅퀴일족 펄볼그들이 호드의 확장로를 막고 있어요.","동쪽 엉겅퀴 마을이 토막나무 주둔지로 가는 길을 막아요.","엉겅퀴 마을의 펄볼그들을 솎아 내 달래요."},c={"잘하셨어요! 이제 적에게 막히지 않는 길을 쓸 수 있겠어요.","잿빛 골짜기에서 호드의 세력이 커지고 있대요.","오늘 수고한 만큼 보상이 있을 거예요."},nx=6621,nt="King of the Foulweald"},
[220]={a={"브린 말로는 이슬렌이 임무를 더 줄 거래요.","브린이 준 물병이 그 임무에 꼭 필요하대요.","이제 이슬렌 워터시어를 찾아가 보래요."},c={"이슬렌 워터시어가 브린이 축복한 물병을 알아보네요.","이 물로 만든 것으로 은빛소나무 숲의 정령을 보게 된대요.","남은 물방울은 준비되면 알려 주겠대요."}},
[232]={a={"연금술사 진게가 왕립 연금술 학회의 일을 맡겨요.","옆방 연금술사 키버의 연구가 쓸모 있을 수 있대요.","구입주문서를 알렉산드로 루카에게 전해 달래요."},c={"루카는 진게가 직접 찾아오지 않아 서운해해요.","그래도 진게를 위해 분석 도구를 준비해 주겠대요."},nx=238,nt="Errand for Apothecary Zinge"},
[235]={a={"징집관 고를라취가 젊은 모험가들을 모으고 있대요.","불모의 땅 북쪽 잿빛 골짜기에 호드 기지가 있대요.","토막나무 주둔지의 세나니 썬더하트를 만나 보래요."},c={"새 개척지에 잘 오셨어요.","잿빛 골짜기는 젊은 모험가가 실력을 증명할 땅이래요.","사냥에 필요한 것들을 기꺼이 알려 준대요."},nx=6383,nt="The Ashenvale Hunt"},
[238]={a={"알렉산드로 루카가 분석 도구를 준비해 뒀어요.","진게는 이걸 빨리 받고 싶어 할 거래요.","언더시티의 진게에게 도구를 가져다 달래요."},nx=243,nt="Into the Field"},
[243]={a={"연금술사 진게가 사막에서 할 일을 맡겨요.","바실리스크, 전갈, 하이에나의 근육 조직을 시험해야 한대요.","가젯잔의 선임기술자 빌지위즐에게 동력원을 부탁해요."},c={"빌지위즐은 동력원이 남아돈다고 말해요.","가젯잔에서는 공짜가 없다며 값을 받겠대요."},nx=379,nt="Slake That Thirst"},
[264]={a={"클라리스 포스터의 남편은 십자군 임무 때문에 떠났어요.","남편이 자기보다 임무를 먼저 여겨서 화가 나 있어요.","클라리스의 펜던트를 유리브의 무덤에 놓아 달래요."},c={"유리브의 묘비 위에서 펜던트 보석이 흐려졌대요.","차가운 바람이 불고 잠시 주위가 조용해졌대요."}},
[338]={a={"바닐 스톤팟은 네싱워리 주인님 소설의 교정을 맡았어요.","돌풍에 원고가 날려 여기저기 흩어졌대요.","정글에 흩어진 낱장을 모아 달래요."},c={"덕분에 큰 골칫거리를 덜었어요.","곧 네싱워리 주인님의 책을 도서관에서 보게 되겠네요."}},
[339]={a={"바닐 스톤팟이 첫 장을 완성하려고 해요.","빠진 쪽이 아직 정글 어딘가에 흩어져 있대요.","흩어진 쪽들을 찾아 가져다 달래요."},c={"드디어 첫 장이 완성됐어요."}},
[340]={a={"바닐 스톤팟이 둘째 장을 완성하려고 해요.","바람에 날린 쪽 중 일부가 아직 정글에 있대요.","그 쪽들을 찾아 가져다 달래요."},c={"둘째 장도 드디어 완성됐어요."}},
[341]={a={"바닐 스톤팟이 셋째 장을 완성하려고 해요.","셋째 장의 빠진 쪽들이 아직 어딘가에 있대요.","그 쪽들을 찾아서 가져다 달래요."},c={"셋째 장이 온전하게 다시 합쳐졌어요."}},
[342]={a={"바닐 스톤팟이 마지막 넷째 장을 완성하려고 해요.","이 장에도 빠진 쪽이 조금 남았대요.","남은 쪽을 찾아서 가져다 달래요."},c={"넷째 장도 이제 준비가 끝났어요."}},
[348]={a={"핀 피즈라켓이 가시덤불 골짜기 열병에 걸렸어요.","치료하려면 흉포한 모크의 심장을 먹어야 한대요.","남쪽 곶 동굴의 의술사 운바그와를 찾아 달래요."},c={"핀은 힘이 돌아오는 것을 느껴요.","여기가 무법항이냐며 놀라요.","아직 몸에 힘이 완전하지는 않대요."}},
[351]={a={"금속 알 장치에서 오글소프라는 목소리가 들려요.","그의 유도 로봇이 모래지옥 협곡 근처에 떨어졌대요.","이 탐지기를 로봇에게 가져다 달래요."},c={"탐지기를 넣자 로봇이 일어나려고 움직여요.","그런데 로봇은 큰 수리가 필요하대요.","로봇을 좀 더 지켜봐 줄 수 있냐고 물어요."},nx=648,nt="Rescue OOX-17/TN!"},
[354]={a={"콜만 파딩은 예전에 아가만드 밀농장에서 일했대요.","아가만드 가문이 자기들을 언데드로 만들었다고 원망해요.","아가만드 가문을 처치하고 그들의 유골을 가져와 달래요."},c={"콜만은 복수가 달콤하지 않냐고 묻는대요.","아가만드 가문이 죽기 전에 두려움을 알았기를 바란대요."},nx=355,nt="Speak with Sevren"},
[355]={a={"콜만 파딩은 이제 복수를 마쳤대요.","그런데 아가만드 밀농장은 모든 포세이큰에게 위협이래요.","집정관 세브렌이 당신을 만나고 싶어 한대요."},c={"콜만이 아가만드 밀농장에서 잘 싸웠다고 칭찬했대요.","포세이큰은 다시 한번 당신의 재능이 필요하대요."},nx=408,nt="The Family Crypt"},
[356]={a={"리니아는 보루 뒤쪽이 공격당할까 걱정해요.","가끔 스컬지가 경계를 몰래 빠져나온대요.","동쪽을 순찰하며 보이는 스컬지를 처치해 달래요."},c={"리니아는 당신 덕분에 스컬지를 막을 수 있다고 칭찬해요.","집행관 자이건드에게 표창을 보내겠다고 해요."},nx=99156,nt="Rear Guard Patrol"},
[357]={a={"청명 호수 섬에 마술사 한 명이 살고 있대요.","그는 자유의지가 있는 포세이큰이지만 다가가면 공격한대요.","그의 마법책을 훔쳐 베소르에게 가져다 달래요."},c={"베소르는 이 책이 군터 아카누스의 것이라며 놀라요.","군터는 살아서도 강령술사였고 죽어서 더 강해졌대요."},nx=366,nt="Return the Book"},
[358]={a={"집정관 세브렌은 역병 때 죽은 주민들의 묘지를 걱정해요.","스컬지가 썩은가죽 놀들을 보내 시체를 모으고 있대요.","놀들을 처치하고 그들의 불변의 영액을 가져다 달래요."},c={"세브렌은 연금술사들이 그 액체를 연구할 거라고 해요.","그 액체에 스컬지를 이길 비밀이 있을지도 모른대요."}},
[359]={a={"집정관 세브렌은 동쪽 초소의 최근 소식이 궁금해요.","스컬지가 보루를 빠져나왔는지 알고 싶어 해요.","동쪽 초소의 리니아에게 가서 이야기를 들어 달래요."},c={"리니아는 보루 수비대가 대부분의 스컬지를 막고 있대요.","가끔 스컬지가 빠져나와 발니르 농장 근처에 나타난대요."},nx=360,nt="Return to the Magistrate"},
[360]={a={"죽음의경비병 리니아가 정보를 얻었대요.","세브렌이 최대한 빨리 보고받기를 원한대요.","돌아가는 길에 스컬지가 보이면 처치해 달래요."},c={"세브렌은 스컬지가 보루를 빠져나왔다는 소식에 걱정해요.","그래도 리치 왕에게 굴복하지 않겠다고 다짐해요."}},
[361]={a={"이 편지는 투르만 아가만드가 쓴 편지예요.","이베트 파딩에게 쓴 편지인데 아직 전해지지 않았어요.","이베트 파딩을 찾아 이 편지를 전해 달래요."},c={"이베트는 투르만이 함께 떠나지 않은 걸 안타까워해요.","편지를 전해 줘서 고맙지만 이제 과거는 끝났대요."}},
[362]={a={"콜만 파딩은 아가만드 가문의 유골을 모으고 있어요.","아가만드 밀농장 가는 길에서 데블린의 중얼거림이 들린대요.","데블린을 처치하고 그 유골을 가져다 달래요."},c={"콜만은 데블린의 유골을 벽난로 선반 위에 올려 둘 거래요.","아가만드 가문이 무너져 마음이 조금 따뜻해졌대요."},nx=355,nt="Speak with Sevren"},
[363]={a={"장의사 모르도는 당신이 제때 깨어났다며 반가워해요.","이제 리치 왕의 노예가 아닌 포세이큰이 됐대요.","언덕 아래 성당의 사비스에게 찾아가 얘기를 들으래요."},c={"사비스는 당신이 놀랐을 거라며 상황을 설명해 주려 해요.","리치 왕에게서 풀려나 실바나스 여왕을 따르게 됐대요."},nx=364,nt="The Mindless Ones"},
[364]={a={"사비스는 포세이큰이 스컬지 군대와 전쟁 중이라고 해요.","넋 나간 좀비들이 마을 동쪽에 쳐들어왔대요.","옛 동료라도 가차 없이 처치해 달래요."},c={"사비스는 스컬지를 포섭하지 못해 안타까워해요.","그들이 따르지 않으니 처치할 수밖에 없대요."}},
[365]={a={"죽음의경비병 시머는 당신을 풋내기라고 부르며 놀려요.","서쪽 농장에는 붉은십자군이 순찰을 돌아요.","그들이 아끼는 호박을 훔쳐 연금술사 요한에게 가져다 달래요."},nx=407,nt="Fields of Grief"},
[366]={a={"베소르는 옛 친구 군터가 살아 있어 기뻐해요.","베소르는 책에 주문을 걸어 자신이 자유로움을 알리려 했대요.","군터의 은거지에 찾아가 그의 마법책을 돌려 달래요."},c={"군터는 책을 훔친 사람이 당신이었냐며 놀라요.","베소르가 살아 있다면 그도 리치 왕에게서 벗어났을지 모른대요."},nx=409,nt="Proving Allegiance"},
[367]={a={"연금술사 요한은 실바나스 여왕의 명을 받았대요.","아서스의 스컬지 군대를 무너뜨릴 새 역병을 연구 중이래요.","짐승의 피가 필요하다며 암흑사냥개 피를 가져다 달래요."},c={"요한은 당신이 잘해 줘서 고맙다고 해요."},nx=368,nt="A New Plague"},
[368]={a={"연금술사 요한은 실험을 하며 재료가 더 필요하다는 걸 알았대요.","북쪽이나 서쪽 해안에 멀록이 많다고 해요.","멀록을 처치하고 썩은지느러미멀록 비늘을 가져다 달래요."},c={"요한은 그 비늘이 딱 필요했던 재료라며 좋아해요."},nx=369,nt="A New Plague"},
[369]={a={"요한은 오래된 책에서 고대 역병 이야기를 찾았대요.","그 역병의 병원체가 검은그물거미 독에 있다고 해요.","동쪽 티리스팔 숲의 흉포한 거미 독을 가져다 달래요."},c={"요한은 이 독이 딱 맞다며 기뻐해요.","이제 새 치명적인 병원체를 시험할 준비가 됐대요."},nx=492,nt="A New Plague"},
[370]={a={"아렌이 보낸 전략 문서에 붉은십자군 위치가 있대요.","붉은십자군 대장 페린이 브릴 남서쪽 폐허 탑에 있대요.","페린과 그 부하들을 처치하고 보고해 달래요."},nx=371,nt="At War With The Scarlet Crusade"},
[371]={a={"붉은십자군이 발니르 농장 근처 폐탑에서 습격해 온대요.","대장 바콘이 이끄는 부대가 습격을 계속하고 있대요.","바콘과 붉은십자군 수사들을 처치해 달래요."},c={"바콘이 죽으면 붉은십자군의 진격이 한동안 느려질 거래요.","하지만 다른 위협도 다가오고 있대요."},nx=372,nt="At War With The Scarlet Crusade"},
[372]={a={"붉은십자군이 파올의 안식처 너머 북쪽 폐탑에서 공격해 와요.","무자비한 대장 멜라케가 이 부대를 이끌고 있대요.","멜라케와 그의 경호원들을 처치해 달래요."}},
[374]={a={"버제스는 티리스팔 숲에 붉은십자군이 가득하다고 해요.","바리마트라스가 붉은십자군을 모두 쓸어버리길 원한대요.","충성의 증거로 붉은십자군 반지를 가져다 달래요."},c={"버제스는 바리마트라스가 자랑스러워할 거라고 해요.","당신이 지도자들을 잘 모신다고 칭찬해요."}},
[375]={a={"그레첸 데드마는 역병이 혈관을 타고 퍼져 너무 추워해요.","실바나스 군대의 시체 운반 가방을 수선해 왔대요.","담요를 만들 그늘박쥐 모피와 실을 구해 달래요."},c={"그레첸은 당신의 노력에 고마워하고 있어요.","언젠가 실바나스가 당신의 용기를 알아주길 바란대요."}},
[376]={a={"수련사제 엘레스는 부상자를 돌보고 갑옷을 만들어요.","좀비와 싸울 당신을 위해 갑옷을 만들어 주려 해요.","남쪽의 늑대와 박쥐에서 앞발과 날개를 구해 달래요."},c={"엘레스는 이 갑옷이 당신에게 도움이 되길 바란대요."},nx=6395,nt="Marla's Last Wish"},
[379]={a={"선임기술자 빌지위즐은 동력원을 줄 수 있다고 해요.","그는 마실 것을 원하고 있어요.","동쪽 사막유랑단 유목민에게 물주머니를 구해 달래요."}},
[380]={a={"집행관 아렌은 금이 부족해 걱정이에요.","북서쪽 금광에 거미가 가득해 채굴을 할 수 없대요.","거미들을 처치해서 광산을 다시 쓰게 해 달래요."},c={"아렌은 시작은 좋다면서도 완전히 치우려면 몇 달은 걸린대요.","다른 일도 맡길 수 있을 거래요."},nx=381,nt="The Scarlet Crusade"},
[381]={a={"아렌은 광산 일이 잘 되어 가서 고마워해요.","정찰병이 데스넬 남동쪽에 붉은십자군 야영지가 있다고 해요.","붉은십자군의 완장을 모아 와 달래요."},c={"아렌은 붉은십자군이 이성적으로 들어주지 않는다며 답답해해요.","빛에 눈이 먼 바보들이라고 비웃어요."},nx=382,nt="The Red Messenger"},
[382]={a={"브릴의 상관이 붉은십자군 전령 소식을 보내왔대요.","그 전령이 중요한 정보를 지니고 있다고 해요.","전령 메븐 코갈을 처치하고 정보를 가져다 달래요."},c={"아렌은 전령이 가진 문서를 뒤적이며 살펴봐요.","그중 붉은십자군 지휘관들의 배치 지도가 쓸모 있을 것 같대요."},nx=383,nt="Vital Intelligence"},
[383]={a={"아렌은 붉은십자군의 문서를 입수했대요.","이 정보를 브릴의 자이건드에게 전해 달래요.","데스넬 북쪽 길을 따라가다 버려진 장원을 지나게 된대요."},c={"자이건드는 이 정보가 아주 좋다며 기뻐해요.","지휘관들을 한 번에 처치하면 붉은십자군의 사기가 꺾일 거래요."}},
[398]={a={"브릴에서 구더기눈의 현상금이 걸렸어요.","구더기눈은 리치 왕의 군대를 위해 시체를 훔쳐 왔대요.","그를 처치한 뒤 그 앞발을 자이건드에게 보여 달래요."},c={"브릴 사람들은 구더기눈의 죄가 마침내 갚아졌다고 해요.","브릴을 대신해 고맙다고 하네요."}},
[404]={a={"스컬지가 브릴 서쪽 오래된 다리 근처를 오염시켰대요.","그곳엔 썩어 문드러진 망자와 시체가 가득하대요.","보이는 망자들을 물리치고 썩은 발톱을 가져다 달래요."},c={"딜링거는 잘했다며 칭찬해요.","그 자리에 함께하지 못해 아쉽다고 해요."},nx=426,nt="The Mills Overrun"},
[405]={a={"집정관 세브렌이 스컬지를 상대할 요원을 찾고 있대요.","언더시티의 베소르 아이스샤드가 요원을 보내라고 명했대요.","세브렌의 명령서를 베소르 아이스샤드에게 전해 달래요."},c={"베소르 아이스샤드는 세브렌이 보낸 요원이라는 걸 알아봤어요.","그래도 맡길 일에 맞는 사람인지는 두고 봐야겠대요."},nx=357,nt="The Lich's Identity"},
[407]={a={"연금술사 요한이 줄무늬 호박에 최신 처방을 했대요.","사로잡힌 붉은십자군 광신도가 갤로우 선술집 지하실에 갇혀 있대요.","이 줄무늬 호박을 그 광신도에게 가져다 달래요."},c={"사로잡힌 붉은십자군 광신도가 드디어 먹을 것이 생겼다며 반가워해요.","달콤한 호박이라며 맛있게 먹고 있어요."}},
[408]={a={"아가만드 밀농장이 스컬지의 본거지가 되었대요.","대장 다르골이 아가만드 가문 조상을 언데드로 되살리려 한대요.","아가만드 납골당에서 다르골을 막고 해골을 가져오래요."},c={"집정관 세브렌은 자네 덕에 스컬지에게 큰 타격을 줬다고 칭찬해요.","포세이큰뿐 아니라 적들도 이 승리를 알게 될 거래요."}},
[409]={a={"군터 아카누스는 자네가 리치 왕의 부하가 아니라는 말을 들었대요.","그래도 스컬지의 적이라는 증거가 있어야 믿겠대요.","섬 남쪽 제단에서 릴리스 네파라를 처치해 달래요."},c={"군터 아카누스는 릴리스 네파라를 처치해 스컬지의 적임을 증명했다고 해요.","자기 말고도 리치 왕에게서 벗어난 이가 있어 놀랐대요."},nx=411,nt="The Prodigal Lich Returns"},
[411]={a={"군터 아카누스는 오랜 친구 베소르 아이스샤드와 할 말이 많대요.","지옥의 보석으로 베소르와 교신할 수 있게 된대요.","언더시티의 베소르에게 지옥의 보석을 가져다 달래요."},c={"베소르 아이스샤드가 우리 편에 서기로 했대요.","그 소식이 어둠의 여왕에게 전해질 거래요."}},
[421]={a={"아루갈이 마법을 마구 써서 은빛소나무 숲 성채가 엉망이 됐대요.","노련한 전사가 가서 아루갈의 뒤처리를 해야 한대요.","달의분노일족 백발전사를 처치해 실력을 보여 달래요."},c={"달라 던위버는 자네가 잘 도와줬다고 칭찬해요.","은빛소나무 숲의 아루갈 저주를 없앨 때 도움이 될 거래요."},nx=422,nt="Arugal's Folly"},
[422]={a={"달라 던위버는 아루갈이 어떻게 마법을 썼는지 알아내려 해요.","아루갈이 처음 머문 발간 농장에 마법책이 있었대요.","그 책에서 아루갈의 치료법 주문서를 찾아 달래요."},c={"달라 던위버가 찾던 바로 그 주문이라며 기뻐해요.","어둠의 여왕의 뜻을 따르면 포세이큰 속에서 앞길이 창창할 거래요."},nx=423,nt="Arugal's Folly"},
[423]={a={"아루갈이 마법 물건으로 약한 마법을 강화했대요.","그 물건을 조사하려면 달의분노일족의 마법 족쇄가 필요하대요.","북쪽과 동쪽에서 달의분노일족을 처치해 달래요."},c={"달라 던위버는 이 정도 양으로 충분할지 걱정해요.","그래도 족쇄를 잘 모아 왔다고 칭찬해요."},nx=424,nt="Arugal's Folly"},
[424]={a={"아루갈의 마법이 남동쪽 언덕의 심원 광산까지 퍼졌대요.","광산 우두머리 은빛갈기 그림슨이 타락했대요.","그림슨을 처치하고 그 해골을 가져다 달래요."},c={"달라 던위버는 자네 덕에 광산을 얻게 됐다며 기뻐해요.","은빛소나무 숲과 아제로스 곳곳으로 퍼질 때 큰 힘이 된대요."},nx=99,nt="Arugal's Folly"},
[425]={a={"레인 요릭의 오빠 쿠인이 포악한 이바르에게 심하게 다쳤대요.","이바르가 다시 올지 몰라 오빠의 회복이 불안하대요.","헛간에 숨어 기회를 엿보는 이바르를 처치해 달래요."},c={"레인 요릭이 고맙다며 상관에게 보고할 때 자네를 넣겠대요.","자네의 공을 보고서에 적겠다고 해요."}},
[426]={a={"스컬지가 아가만드 밀농장에 기지를 세우려 한대요.","기지가 생기면 티리스팔의 다른 지역을 공격할 거래요.","밀농장 스컬지를 처치하고 늑골과 저주받은 해골을 모아 오래요."},c={"딜링거는 자네의 노력이 전쟁에서 느껴진다고 해요.","고맙다는 말은 안 해도 경비병들이 이름을 기억하겠대요."}},
[427]={a={"집행관 아렌의 문서 덕분에 붉은십자군의 위치를 알게 됐대요.","리치 왕의 군대가 밤마다 늘고 있어 걱정이래요.","솔리덴 농장 너머 서쪽 탑에서 붉은십자군 전사를 처치해 달래요."},c={"자이건드가 아주 훌륭하다며 자네의 전투 실력을 인정해요."},nx=370,nt="At War With The Scarlet Crusade"},
[428]={a={"고위집행관 하드렉이 죽음의추적자 둘과 연락이 끊겼대요.","쿠인 요릭과 레인 요릭이 스컬지에게 당했을까 봐 걱정이래요.","은빛소나무 숲 북쪽 농장부터 수색해 달래요."},c={"레인 요릭이 제때 찾아 줘서 반가워해요."},nx=429,nt="Wild Hearts"},
[429]={a={"레인 요릭의 오빠 쿠인이 포악한 이바르에게 심하게 다쳤대요.","연금술사는 검은늑대 심장으로 치료 물약을 만든대요.","검은늑대 심장을 모아 연금술사 렌퍼럴에게 가져다 달래요."},c={"렌퍼럴은 죽음의추적자들이 실패한 게 걱정이래요.","곧 물약을 주고 조제법도 알려 준대요."},nx=430,nt="Return to Quinn"},
[430]={a={"연금술사 렌퍼럴이 쿠인 요릭을 위한 물약을 만들었대요.","렌퍼럴은 바쁘다며 자리를 떠났대요.","이 물약을 이바르 호박밭의 쿠인 요릭에게 가져다 달래요."},c={"쿠인 요릭은 물약을 마시고 효과가 느껴진다고 해요.","곧 다시 움직일 수 있겠다며 큰 도움을 받았대요."},nx=425,nt="Ivar the Foul"},
[435]={a={"죽음의추적자 엘런드가 문밖의 굶주린 늑대들 때문에 나가지 못해요.","레인 요릭에게 보고서를 전하려면 보호가 필요하대요.","늑대를 물리치고 엘런드를 레인 요릭에게 데려다 달래요."},c={"레인 요릭은 엘런드가 무사해서 안도했대요.","자네 도움 덕분이라며 고마워해요."},nx=449,nt="The Deathstalkers' Report"},
[437]={a={"썩은가죽일족이 죽음의 농장을 본거지로 삼았대요.","밴시 나이트래쉬가 마법으로 번번이 우리 공격을 막는대요.","나이트래쉬를 처치하고 그 정수를 가져다 달래요."},nx=438,nt="The Decrepit Ferry"},
[438]={a={"고위집행관 하드렉이 오래된 나루터에 스컬지 소굴이 생겼다고 해요.","그 나루터는 썩은가죽일족이 삼엄하게 지킨대요.","가서 스컬지가 그곳에 있는 이유를 알아 오래요."},c={"배 안에는 천에 싸인 시체들이 잔뜩 쌓여 있어요.","로다미어 호수 건너 펜리스 섬에 맞은편 나루터가 있어요."},nx=439,nt="Rot Hide Clues"},
[439]={a={"시체 더미 사이로 여자의 손이 나와 있어요.","반지에 델리아에게라고 새겨져 있어요.","이 반지를 고위집행관 하드렉에게 가져가 달래요."},c={"하드렉은 이 반지의 여자가 최근에 죽었을 거라고 해요.","썩은가죽일족이 그 시체들을 펜리스 섬으로 옮긴 것 같대요."},nx=443,nt="Rot Hide Ichor"},
[440]={a={"고위집행관 하드렉이 델리아에게 반지를 준 사람을 찾아보래요.","브릴의 집정관 세브렌이 최근 사망 기록을 가지고 있을 거래요.","세브렌에게 델리아의 반지를 가져가 달래요."},c={"세브렌은 델리아가 얼마 전까지 브릴에 살았다고 해요.","자네 말이 맞다면 썩은가죽일족이 시체를 훔쳤을 거래요."},nx=441,nt="Raleigh and the Undercity"},
[441]={a={"델리아에게는 언더시티에 사는 남편 랠리가 있대요.","브릴에 살던 델리아가 이 반지의 주인이라면 랠리가 알 거래요.","언더시티 상업 지구의 랠리에게 반지를 가져가 달래요."},c={"랠리는 이 반지가 아내 것이라며 알아봤어요.","아내의 죽음이나 시체를 도둑맞은 일에는 아무 감정이 없대요.","그래도 복수하고 싶은 마음은 남아 있대요."},nx=530,nt="A Husband's Revenge"},
[442]={a={"이제 스컬지의 본거지인 펜리스 섬을 칠 때래요.","쑤울을 처치하는 임무라 위험하지만 꼭 성공해야 한대요.","쑤울의 머리카락을 고위집행관에게 가져가 달래요."},c={"쑤울을 쓰러뜨린 건 작은 일이 아니래요.","그때 나온 힘이 공동묘지까지 느껴졌대요.","그 소식이 퍼져서 이제 더 중요한 존재가 됐대요."}},
[443]={a={"고위집행관 하드렉은 썩은가죽 놀을 조종하는 배후가 누군지 알아야 한대요.","연금술사들은 놀의 몸에서 나오는 이상한 액체에 답이 있다고 봐요.","펜리스 섬 놀에게서 영액을 모아 렌퍼럴에게 가져다 달래요."},c={"렌퍼럴은 이 영액으로 썩은가죽 놀의 본성을 알게 될 거래요.","약점이 있다면 그것도 알 수 있을 거래요."},nx=444,nt="Rot Hide Origins"},
[444]={a={"렌퍼럴이 영액을 분석해 보니 흑마법과 강령술이 쓰인 것 같대요.","언더시티에 있는 베소르 아이스샤드의 지식이 도움이 될 거래요.","영액 견본을 베소르 아이스샤드에게 가져다 달래요."},c={"베소르 아이스샤드는 이 물질에 강한 주문이 걸려 있다고 봐요.","오래전 주문들이 보인다며 점술 주문을 걸어 보려 해요."},nx=446,nt="Thule Ravenclaw"},
[445]={a={"연금술사 요한이 연구 결과를 동료에게 나눠 주려 해요.","왕립 연금술 학회 회원으로서 지식을 나누는 게 의무래요.","은빛소나무 숲 공동묘지의 연금술사 렌퍼럴에게 전해 달래요."},c={"렌퍼럴은 요한이 연구 결과를 보내 준 게 고맙대요.","은빛소나무 숲에 새 소식이 많아 다른 지역 연구는 잊고 있었대요.","은빛소나무 숲에 더 머물러 달라고 부탁해요."}},
[446]={a={"이 영액은 옛 동료 까마귀발톱 쑤울이 만든 거래요.","쑤울은 스컬지와 손잡고 썩은가죽일족을 이끈대요.","이 두루마리를 렌퍼럴에게 다시 가져다 달래요."},c={"렌퍼럴은 두루마리에 강한 마법이 담겼다고 놀라요.","펜리스 섬에서 쑤울을 칠 때 좋은 무기가 될 거래요."},nx=448,nt="Report to Hadrec"},
[447]={a={"아서스 군대의 병력이 압도적이라 걱정이래요.","거미 피와 불곰 심장의 독을 섞으면 치명적인 비약이 된대요.","땅거미 점액과 불곰 심장을 수석 연금술사 파라넬에게 가져가래요."},c={"파라넬은 렌퍼럴이 자네를 보내 줘서 잘됐다고 반가워해요.","이 샘플들이 쓸모가 있을 거라며 바로 연구를 시작한대요."},nx=450,nt="A Recipe For Death"},
[448]={a={"렌퍼럴이 펜리스 섬을 치기 전에 하드렉에게 보고하래요.","하드렉이 필요한 정보나 장비를 줄지도 모른대요.","고위집행관 하드렉에게 가서 보고해 달래요."},c={"하드렉은 베소르의 말이 맞다면 쑤울을 서둘러 막아야 한대요.","이 일을 돕도록 무기고에서 무언가 가져가도 된대요."},nx=442,nt="Assault on Fenris Isle"},
[449]={a={"쿠인 요릭의 상처는 아직 낫지 않았대요.","포세이큰이 은빛소나무 숲을 차지하는 데 꼭 필요한 정보래요.","공동묘지의 고위집행관 하드렉에게 보고서를 전해 달래요."},c={"하드렉은 은빛소나무 숲의 스컬지가 생각보다 많았다고 해요.","죽음의추적자를 도운 일이 값지다며 칭찬하겠대요."},nx=3221,nt="Speak with Renferrel"},
[450]={a={"수석 연금술사 파라넬은 베랄드의 연구가 중요하다고 해요.","연금술사 베랄드는 아루갈의 저주로 꼭두각시가 됐대요.","장작나무 마을 여관의 베랄드 일지를 렌퍼럴에게 가져다 달래요."},nx=451,nt="A Recipe For Death"},
[451]={a={"일지에 따르면 호수 괴물의 이끼가 쓸모 있을지도 모른대요.","그 괴물들은 로다미어 호수의 섬에 살고 있대요.","이끼와 굳어진 종양을 수석 연금술사 파라넬에게 가져다 달래요."},c={"파라넬은 베랄드를 잃은 건 큰 손실이라고 안타까워해요.","그래도 베랄드의 연구는 어둠의 여왕을 돕는 데 쓸모가 있대요."}},
[452]={a={"아루갈이 원로들을 꼭두각시로 만들어 마을을 조종한대요.","원로들이 없으면 마을 주민들도 풀려날 거래요.","혼자선 못 이기니 원로들을 함께 처단하자고 해요."},c={"페를레이아는 자네가 어둠의 여왕의 제자처럼 싸웠다고 칭찬해요.","원로들이 죽으면 그림자송곳니 성채에서 아루갈을 몰아낼 수 있대요."}},
[460]={a={"말하는 머리는 까마귀발톱 쑤울의 옛 부관 알라리크라고 해요.","쑤울의 주문 때문에 살지도 죽지도 못하게 됐대요.","펜리스 요새 마구간 앞에 묻힌 자기 몸으로 데려가 달래요."},c={"알라리크는 몸이 무사해서 다행이라고 해요.","썩은가죽 놀들이 몸을 망가뜨리지 않아 안심했대요."},nx=461,nt="The Hidden Niche"},
[461]={a={"성채 안에 쑤울이 소중한 물건을 숨긴 비밀 벽감이 있대요.","그 벽감에는 자네에게 쓸모 있는 물건도 있대요.","남서쪽 탑의 먼지투성이 선반 뒤로 자신을 데려가 달래요."},c={"알라리크는 벽감이 열렸다며 자신을 여기 두라고 해요.","썩은가죽 놀들이 찾지 못하게 벽감을 단단히 닫아 달래요."},nx=491,nt="Wand to Bethor"},
[477]={a={"앰버밀은 달라란 마법사들의 도움으로 저항을 이어 가요.","달라란 마법사들이 힐스브래드에서 마차로 상자를 실어 나른대요.","상자의 내용물을 빼 와 달래요."},c={"상자 안에는 조심스럽게 싸인 물건들이 들어 있어요.","맨 위에는 은빛소나무 숲이 그려진 누런 지도 뭉치가 있어요.","그 아래에는 신비한 마법 펜던트가 있어요."},nx=478,nt="Maps and Runes"},
[479]={a={"달라 던위버가 마법사들의 마법 근원을 찾고 있대요.","마법사와 수호병들이 펜던트를 나르니 빼앗아야 한대요.","앰버밀로 가서 달라란 펜던트를 빼앗아 와 달래요."},c={"달라 던위버가 마법 작업이 꽤 진행됐다고 알아냈대요.","강력한 마법사가 마법 에너지를 이끌고 있어 서둘러 막아야 한대요."},nx=480,nt="The Weaver"},
[480]={a={"달라란 대마법사 아테릭이 초원 에너지 원천을 되살리고 있대요.","지금 막지 않으면 놈들의 계획이 성공할 거래요.","그 대마법사를 처치하고 지팡이를 가져다 달래요."},c={"대마법사들의 마법이 흩어지고 에너지가 잠들었대요.","놈들에게 큰 타격을 줬지만 방심은 하면 안 된대요.","앞으로의 계획도 세워야 한대요."}},
[481]={a={"어둠의사제 알리스터가 펜던트를 달라 던위버에게 가져가 보래요.","달라 던위버가 마술사들의 계획을 밝혀 줄지도 모른대요.","공동묘지의 달라 던위버에게 룬문자 펜던트를 가져다 달래요."},c={"달라 던위버는 이 펜던트가 강력한 유물이라고 봐요.","이 펜던트는 마법사들이 마법 에너지를 다룰 때 쓰던 물건이래요.","앰버밀로 많이 보내는 걸 보니 큰 계획이 있는 것 같대요."},nx=482,nt="Dalaran's Intentions"},
[482]={a={"달라 던위버는 앰버밀에 잠든 초원 에너지의 원천이 있대요.","마법사들이 그 에너지를 깨워 큰 목적에 쓰려는 것 같대요.","이 정보를 어둠의사제 알리스터에게 전해 달래요."},c={"알리스터는 나쁜 소식이라며 달라의 말을 믿는다고 해요.","그동안 마법사들의 진행을 늦춰야 한대요."},nx=479,nt="Ambermill Investigations"},
[485]={a={"금속 알 장치에서 오글소프 오브노티쿠스의 목소리가 들려요.","그의 유도 로봇이 동부 내륙지 강 시작점 근처에 떨어졌대요.","이 탐지기를 로봇에게 가져다 달래요."},c={"탐지기를 넣자 로봇이 일어나려고 움직여요.","그런데 로봇은 큰 수리가 필요하대요.","로봇을 좀 더 지켜봐 줄 수 있냐고 물어요."},nx=836,nt="Rescue OOX-09/HL!"},
[491]={a={"쑤울이 옛날 두 친구와 마법봉을 함께 만들었대요.","쑤울이 그 봉을 훔쳐 펜리스 요새에 숨겼대요.","옛 친구 베소르 아이스샤드에게 가져다 달래요."},c={"베소르는 쑤울이 결합된 마법봉을 가졌다니 놀랐대요.","힘을 쓰지 않아서 다행이래요.","찾아 줘서 고맙다고 해요."}},
[492]={a={"연금술사 요한이 음료를 특별히 만들었대요.","갤로우 선술집 지하실에 산악경비대 포로가 갇혀 있대요.","그 음료를 포로에게 전해 달래요."},c={"산악경비대 포로는 드디어 마실 게 왔다고 반가워해요.","랩소디 몰트만큼은 아니겠지만 뭐든 좋대요."}},
[493]={a={"연금술사 렌퍼럴은 어둠의 여왕님 명령으로 새 역병을 연구해요.","학회 안에서 정보를 나누면 더 빨리 성공한대요.","연금술사 라이던에게 연구 결과를 전해 달래요."},c={"정말 훌륭한 결과라고 해요.","렌퍼럴의 연구를 빨리 살펴보고 싶대요."}},
[494]={a={"죽음의추적자 레시가 힐스브래드 마을을 조사하러 왔어요.","그 전갈은 서쪽에서 까마귀 울음이 부른다는 내용이래요.","타렌 밀농장으로 가서 다살리아에게 전하래요."}},
[495]={a={"무그톨의 오우거 부대가 알터랙으로 왕관을 찾으러 갔대요.","그런데 왕관에 욕심을 내다 실바나스 여왕님께 맞섰대요.","타렌 밀농장의 멜리사라에게 이 소식을 전해 달래요."},c={"샬린드라가 보냈군요. 쓸데없는 말은 하지 않겠어요.","무그톨은 골칫거리라 빠르고 확실히 처리할 거래요."},nx=518,nt="The Crown of Will"},
[496]={a={"연금술사 라이던은 독극물 연구를 계속하고 있대요.","그 재료를 모을 시간이 없대요.","회색곰 혀와 이끼거미 수액을 구해 달래요."},c={"이 재료들은 완벽하대요.","덕분에 비참한 하루에 작은 기쁨이 생겼대요."},nx=499,nt="Elixir of Suffering"},
[498]={a={"크루스크와 오크 전사들이 던홀드 요새를 수색하다 습격당했대요.","크루스크만 간신히 탈출했고 드럴과 토그타르는 붙잡혔대요.","강 건너 던홀드 요새에 가서 그들을 구해 달래요."},c={"인간들이 우리 전사들을 노예로 만들려 했대요.","골디르는 다른 곳으로 끌려갔대요.","어디 있는지 아직 몰라서 단서가 생기면 알려 준대요."},nx=533,nt="Infiltration"},
[499]={a={"연금술사 라이던이 괴로움의 비약을 완성했대요.","그 독약을 조수 개구리 움피에게 먹여 보래요.","독약이 어떤 효과가 있는지 확인해 보려는 거래요."}},
[501]={a={"연금술사 라이던은 새 역병이 퍼지기를 바란대요.","산사자 피로 가장 강한 독을 만들 수 있대요.","산사자 피를 좀 가져다 달래요."},nx=502,nt="Elixir of Pain"},
[502]={a={"연금술사 라이던이 고통의 비약을 새로 만들었대요.","먼저 효과를 시험해 봐야 한대요.","농부 레이의 개 스탠리에게 먹여 달래요."}},
[503]={a={"골디르는 비밀결사대에 너무 오래 잡혀 있대요.","문서를 보면 북쪽 알터랙 산맥의 대규모 기지에 있을 거래요.","그를 구해서 타렌 밀농장의 크루스크에게 돌아가래요."},c={"대족장님 명령으로 듀로타에서 원정대를 이끌었대요.","이곳에서 붙잡혀 일을 강요당했대요.","지금 무리를 이끄는 이에게 중요한 정보를 전해 달래요."},nx=506,nt="Blackmoore's Legacy"},
[506]={a={"골디르가 앨리덴 페레놀드라는 비밀결사대 우두머리를 만났대요.","그는 오크들을 노예로 삼을 계획을 털어놨대요.","그 정보를 타렌 밀농장의 크루스크에게 전해 달래요."},c={"그 인간들 참 뻔뻔하대요.","오크는 절대 굴복하지 않을 거래요.","대족장님이 찾는 장신구도 찾아야 한대요."},nx=507,nt="Lord Aliden Perenolde"},
[507]={a={"크루스크는 앨리덴 페레놀드 경을 없애야 한대요.","그의 영지는 로다미어 호수 근처에 있대요.","처치한 뒤 대족장이 원하는 펜던트를 찾아 오래요."},nx=508,nt="Taretha's Gift"},
[508]={a={"엘리사는 옛 추억을 더는 간직하고 싶지 않대요.","타레사의 펜던트를 기꺼이 내주겠대요.","소란 없이 조용히 가 달래요."},c={"작은 물건 하나에 대족장님이 왜 그리 신경 쓰는지 모르겠대요.","그래도 대족장님 명령이라면 따르겠대요.","잘하셨어요. 대족장님도 기뻐하실 거래요."}},
[509]={a={"타렌 밀농장의 연금술사 라이던이 새 비약을 곧 완성한대요.","어둠의 여왕이 죽음과 역병을 퍼뜨리길 원한대요.","네산더 농장에서 진흙주둥이꽃을 모아다 달래요."},c={"진흙주둥이꽃 냄새가 정말 고약하대요.","그래도 쓸모는 있다고 해요."},nx=513,nt="Elixir of Agony"},
[513]={a={"연금술사 라이던은 지루하던 참에 진흙주둥이꽃을 받아 반가워해요.","꽃으로 합성물을 만든 뒤 부패 콜로이드 용액을 섞어야 한대요.","합성물을 언더시티의 수석 연금술사 파라넬에게 전해 달래요."},nx=515,nt="Elixir of Agony"},
[515]={a={"수석 연금술사 파라넬이 합성물을 보고 감탄했어요.","활성화하려면 강한 재생의 물약과 비늘, 눈이 필요하대요.","재료를 모아 연금술사 라이던에게 가져다 달래요."},c={"실험 생각에 신이 나서 들떠 있대요.","함께 이 땅에 죽음과 역병을 퍼뜨릴 거래요."},nx=517,nt="Elixir of Agony"},
[516]={a={"공동묘지의 어둠의사제 알리스터가 중요한 정보를 얻었어요.","리치 왕의 언데드 무리가 우리를 치려고 숨어 있대요.","베렌의 동굴에서 놈들을 찾아 처치해 달래요."},c={"이런 정보가 계속 들어오면 언데드를 금방 몰아낼 거래요."}},
[517]={a={"연금술사 라이던이 새 비약의 시험 준비를 마쳤어요.","개구리 대신 드워프들에게 역병을 시험하려 해요.","던 가록에서 신디거 스타우트 맥주통을 훔쳐 와 달래요."},c={"이제 드디어 행동에 나설 준비가 됐대요."},nx=524,nt="Elixir of Agony"},
[518]={a={"타렌 밀농장의 멜리사라가 무그톨을 단죄하려 해요.","산사태 오우거들이 알터랙 폐허를 짓밟았대요.","먼저 놈들의 전력을 약화시켜 달래요."},c={"눈밭이 오우거들의 피로 붉게 물들었대요.","산사태 오우거들의 기세가 완전히 꺾일 때까지 멈출 수 없대요."},nx=519,nt="The Crown of Will"},
[519]={a={"무그톨의 부관은 타르그, 무크라케, 글롬무스예요.","이유는 모르지만 오우거들은 무그톨에게 충성을 다한대요.","그 부관들을 처치하고 증거를 가져와 달래요."},c={"멜리사라는 오우거 냄새가 원래 지독하대요.","무그톨 머리를 가져오면 넷을 장대에 걸겠대요."},nx=520,nt="The Crown of Will"},
[520]={a={"부관들을 처치했으니 이제 무그톨만 남았대요.","무그톨은 왕관을 쉽게 내놓지 않을 거래요.","무그톨을 처치하고 머리카락과 의지의 왕관을 가져오래요."},c={"멜리사라는 일을 잘했다며 칭찬해요.","무그톨의 머리는 알터랙 폐허 가장 높은 곳에 걸린대요.","Deathguard가 산사태일족의 잔당을 쓸어버린대요."},nx=521,nt="The Crown of Will"},
[521]={a={"이제 의지의 왕관을 언더시티의 샬린드라에게 가져가래요.","샬린드라가 실바나스 여왕에게 왕관을 전해 줄 거래요.","무그톨처럼 왕관을 사사로이 쓰지 말라고 경고해요."},c={"샬린드라는 이렇게 단순한 물건이 큰 힘을 가졌다고 놀라요.","이 왕관이 서툰 손에 있었다고 말해요.","실바나스 여왕에게 전하고 공을 알리겠대요."}},
[524]={a={"고위집행관 다살리아가 농부 포로들을 연금술사 라이던에게 맡겼어요.","포로 중 스톰윈드 군사 전략가가 숨어 있다고 의심했대요.","오염된 맥주통을 농부들 방의 양탄자 위에 놓아 달래요."}},
[527]={a={"고위집행관 다살리아는 바리마트라스의 직속 부관이에요.","인간들이 쳐들어오지 못하게 힐스브래드 마을을 노린대요.","힐스브래드 북쪽 농장을 치고 농부 레이와 게츠도 처치해 달래요."},c={"힐스브래드 전선에서 잘 싸웠다는 보고가 들어왔대요."},nx=528,nt="Battle of Hillsbrad"},
[528]={a={"고위집행관 다살리아가 힐스브래드 주민들의 공포를 반겨요.","소작농들이 과수원으로 숨으려 남쪽으로 피난 중이래요.","힐스브래드 농장으로 가서 숨은 농부들을 처단해 달래요."},c={"힐스브래드 마을을 죽음이 점점 조이고 있대요.","전투도 순조롭게 진행되고 있대요."},nx=529,nt="Battle of Hillsbrad"},
[529]={a={"고위집행관 다살리아가 힐스브래드의 뜻밖의 저항을 알렸어요.","마을 대장장이가 주민들에게 무기를 대고 있대요.","대장장이 베링턴과 견습들을 처치하고 철괴 상자를 찾아 달래요."},c={"임무를 솜씨 좋게 끝냈다고 칭찬했대요."},nx=532,nt="Battle of Hillsbrad"},
[530]={a={"랠리 앤드리언은 아내를 옛 친구 발드레드에게 잃었대요.","이제 슬픔보다 복수하고 싶은 마음뿐이래요.","발드레드를 처치하고 증거로 장갑을 가져와 달래요."},c={"그가 바란 건 오직 아내의 복수였대요.","이 장갑은 친구의 배신을 기억하는 증표로 간직하겠대요."}},
[532]={a={"고위집행관 다살리아는 힐스브래드가 곧 함락될 거라 봐요.","집정관 번사이드를 중심으로 인간들이 저항을 이어 간대요.","번사이드와 원로들을 처치하고 선언문을 부수고 기록부를 빼내 달래요."},nx=539,nt="Battle of Hillsbrad"},
[533]={a={"크루스크는 붙잡힌 골디르의 행방을 찾고 있어요.","수색 범위가 여기서 북쪽 비밀결사대 야영지로 좁혀졌대요.","그곳에 가서 정보를 최대한 모아 와 달래요."},c={"이제 골디르가 잡힌 곳을 알아냈대요.","경비가 예전만큼 철저하지 않기를 바란대요."},nx=503,nt="Gol'dir"},
[535]={a={"심복 발릭이 큰 부상을 입고 죽어 가고 있어요.","죽기 전에 사우스쇼어 스타우트 맥주를 원한대요.","맥주를 가져가면 알고 싶은 정보를 알려 준대요."},c={"죽기 직전에 맛본 것 중 가장 달콤하대요.","이건 죽으면 쓸모없으니 가져가라고 해요."}},
[539]={a={"고위집행관 다살리아가 얼라이언스의 청금석 광산을 노려요.","그 광산은 얼라이언스 무기에 쓸 철광석을 대는 곳이래요.","광산 남쪽에서 현장감독 본즈와 광부들을 처치해 달래요."},c={"어둠의 여왕은 군대에 무기를 댈 새 광산이 생겨 기뻐하겠대요."},nx=541,nt="Battle of Hillsbrad"},
[541]={a={"고위집행관 다살리아는 드워프들이 인간을 돕는 걸 못마땅해해요.","드워프들이 던 가록에 병영을 세웠대요.","던 가록을 포위 공격하고 부대장 아이언힐을 처치해 달래요."},c={"전장에서 보여 준 활약은 최고 칭찬을 받을 만하대요."},nx=550,nt="Battle of Hillsbrad"},
[544]={a={"학자 워딘 보이드글레어는 연구용 유물을 도둑맞았대요.","배신자들이 언더시티 비밀 금고의 유물을 훔쳐 달아났대요.","로다미어 포로수용소에서 유물을 되찾아 달래요."},c={"이 유물들을 무척 그리워했대요.","배신자들도 벌을 받았다니 다행이래요."},nx=545,nt="Dalaran Patrols"},
[545]={a={"학자 워딘 보이드글레어는 폐허에 보물이 있을지 궁금해해요.","달라란 마법사들과 노예 바위 정령들이 그곳을 순찰 중이래요.","순찰하는 놈들을 처치하고 다시 돌아와 달래요."},c={"이제 폐허를 조심히 뒤져 봐도 안전하대요."},nx=92434,nt="Blood in the Streets"},
[546]={a={"타렌 밀농장의 죽음의경비병 삼사는 해골을 모으는 중이에요.","보초만 서느라 힐스브래드 전투에 못 나가 부럽대요.","힐스브래드 사람들의 해골을 모아 가져다 달래요."},c={"해골이 정말 아름답다며 기뻐했대요.","약속대로 보상을 주겠대요."}},
[547]={a={"죽음의경비병 험버트는 야영지에서 장비를 도둑맞았어요.","던 가록의 드워프 정찰병들이 검을 가져간 것 같대요.","던 가록에서 험버트의 검을 되찾아 돌려 달래요."},c={"소중한 검을 되찾아 마음이 놓인대요."}},
[549]={a={"실바나스 여왕의 명으로 비밀결사대 대원들이 현상수배됐어요.","비밀결사대가 던홀드 요새 폐허에 모여 있대요.","대원들을 처치하고 증거를 고위집행관 다살리아에게 가져다 달래요."},c={"이 속도면 비밀결사대는 금방 사라지겠대요."},nx=566,nt="WANTED: Baron Vardus"},
[550]={a={"고위집행관 다살리아가 힐스브래드 전투의 활약을 추천서에 적었어요.","최고 사령부가 인정하도록 쓴 추천서래요.","그 봉인된 추천서를 언더시티의 바리마트라스에게 전해 달래요."},c={"힐스브래드에서의 활약이 언더시티까지 빨리 알려졌대요.","당신 덕에 인간들도 무너질 수 있다는 게 보였대요."}},
[552]={a={"수련사 사이반드는 스승 헬쿨라를 잃고 복수하려 해요.","인간 폭도가 스승을 죽이고 사우스쇼어 묘지에 묻었대요.","설인에게서 헬쿨라의 마법봉을 되찾아 가져다 달래요."},nx=553,nt="Helcular's Revenge"},
[553]={a={"수련사 사이반드가 복수를 위해 마법봉을 건네줬어요.","마법봉에 아젤과 베라즈, 우젤의 불꽃 힘을 넣어야 한대요.","다 채운 마법봉을 사우스쇼어 헬쿨라의 무덤에 꽂아 달래요."},c={"땅에서 커다란 울림이 퍼져 나왔대요."}},
[556]={a={"관리인 벨바릴은 학자 보이드글레어가 돌을 연구하고 싶어할 거래요.","달라란 마법사들은 징표의 돌로 정령을 조종한대요.","닳은 징표의 돌을 모아 벨바릴에게 가져다 달래요."},c={"돌은 마법이 조금 바랬지만 쓸만하대요.","연구 초반 실험에는 이런 돌이 좋대요."},nx=557,nt="Bracers of Binding"},
[557]={a={"관리인 벨바릴은 학자 보이드글레어가 팔보호구도 곧 필요할 거래요.","팔보호구는 정령의 손목에 채워 마법사를 따르게 하는 물건이래요.","달라란 폐허에서 대지 결속의 팔보호구를 모아 달래요."}},
[566]={a={"고위집행관 다살리아의 명으로 남작 바르두스에게 현상수배가 붙었어요.","비밀결사대의 고위 간부라 알터랙 산맥 고원에서 목격됐대요.","그를 처치한 증거를 다살리아에게 가져다 달래요."},c={"바르두스가 죽어서 비밀결사대 지도자가 줄었대요.","이제 그들의 저항도 오래가지 않을 거래요."}},
[567]={a={"고위집행관 다살리아가 힐스브래드 위험 인물들에게 현상금을 걸었어요.","살인과 보급품 약탈 혐의를 받는 자들이래요.","숨은 이들을 찾아 처치하고 증거를 가져와 달래요."}},
[568]={a={"사령관 아그로고쉬는 스토나드까지의 보급로를 지켜야 해요.","정글의 짐승들이 보급로 지키는 일을 방해하고 있대요.","그롬골 밖의 채찍꼬리랩터를 솎아 달래요."},nx=569,nt="The Defense of Grom'gol"},
[569]={a={"사령관 아그로고쉬는 보급 짐마차가 계속 습격당하고 있대요.","오우거 무리가 그롬골 남동쪽 미즈자 폐허를 차지했대요.","미즈자 폐허로 가서 오우거들을 몰아내 달래요."},nx=97386,nt="The Offense of Grom'gol"},
[570]={a={"예언자 모크타르딘은 정글 마법으로 특별한 물건을 만들려 해요.","그의 의식이 효과를 보여 이제 강력한 마법을 쓸 수 있대요.","그림자퓨마 발톱과 온전한 암호랑이의 송곳니를 가져다 달래요."},c={"정글을 잘 아는 당신 덕에 좋은 재료를 얻었대요.","호드를 위해 희생된 짐승들에게 정령도 감사하겠대요."},nx=572,nt="Mok'thardin's Enchantment"},
[571]={a={"예언자 모크타르딘은 마법 재료를 찾고 있어요.","깃털과 발톱, 송곳니를 묶을 마법의 밧줄이 필요하대요.","덩치큰 고릴라의 힘줄을 가져다 달래요."},c={"모크타르딘은 이 힘줄이 아주 완벽하다고 칭찬해요.","곧 노력한 보람이 나올 거래요."},nx=573,nt="Mok'thardin's Enchantment"},
[572]={a={"모크타르딘은 강력한 마법 물건을 만들려 해요.","줄무늬정글랩터의 깃털도 필요하대요.","그롬골 남쪽에서 랩터 깃털을 모아 달래요."},c={"모크타르딘이 훌륭하다며 바로 준비하겠대요."},nx=571,nt="Mok'thardin's Enchantment"},
[573]={a={"모크타르딘에게 마지막 재료가 하나 남았대요.","남쪽 서부 해안 절벽 위에 신성한 샘이 있대요.","샘물을 가져오려면 나가 탐험가들과 싸워야 한대요."}},
[575]={a={"무법항의 가죽 세공꾼 드리즐릭은 자기 가죽 제품을 자랑해요.","땜장이 조합장 리들복스가 장화를 주문했대요.","가시덤불 골짜기 강가에서 민물악어 가죽을 구해 달래요."},c={"이 가죽이면 됐대요.","안쪽이라 품질은 크게 상관없대요."},nx=577,nt="Some Assembly Required"},
[576]={a={"애꾸눈 디지는 마법 유리 눈이 없으면 아무것도 못 해요.","붉은해적단이 밤에 그의 눈을 빼앗아 갔대요.","무법항 쪽으로 간 눈을 되찾아 달래요."},c={"디지는 눈을 찾아 줘서 놀라고 기뻐해요.","이제 다시 앞이 보인다며 좋아해요."}},
[577]={a={"드리즐릭은 장화 기본 형태는 잡았지만 가죽이 모자라대요.","안감은 안 보이니 두껍고 값싼 악어 가죽이면 된대요.","나즈페리티 호수에서 무쇠턱 악어 가죽을 구해 달래요."},c={"드리즐릭의 장화가 소시지 같대요.","속이 뭔지는 너무 깊이 묻지 말래요."},nx=628,nt="Excelsior"},
[580]={a={"위스키 슬림은 폭풍이 치던 날 술을 마시고 있었어요.","큰 파도에 선장의 퍼플리버보스 포트 와인병이 바다로 빠졌대요.","선장이 화낼 테니 술병을 찾아 달래요."},c={"선장의 술을 찾아 줘서 슬림이 고마워해요.","밖에 폭풍이 올 것 같다며 술병 하나로 몸을 데우겠대요."}},
[581]={a={"님보야는 족장의 막내아들 예니쿠를 찾고 있어요.","예니쿠는 붉은머리부족에게 잡혀 있을 것 같대요.","북쪽의 붉은머리부족을 처치하고 어금니를 가져다 달래요."},c={"이 정도면 붉은머리부족을 사냥할 힘이 있대요.","붉은머리부족 사냥은 아직 끝나지 않았대요."},nx=582,nt="Headhunting"},
[582]={a={"님보야는 예니쿠가 살았는지 확인하고 싶어 해요.","쭈그러든 해골 중에 예니쿠의 것이 없는지 봐야 한대요.","북쪽 해안을 따라 인간사냥꾼을 처치해 달래요."},c={"이 해골들을 살펴서 예니쿠가 아닌지 확인하겠대요."},nx=584,nt="Bloodscalp Clan Heads"},
[583]={a={"바닐 스톤팟이 가시덤불 골짜기에 온 당신을 반겨요.","헤멧 네싱워리는 유명한 전쟁 영웅이자 사냥의 대가래요.","가서 그와 대화해 보라고 해요."},c={"그는 아주 큰 짐승을 사냥하려고 왔대요.","실력을 증명하면 그 사냥에 끼워 준대요."},nx=194,nt="Raptor Mastery"},
[584]={a={"님보야는 예니쿠를 찾을 단서가 아직 없대요.","붉은머리부족 족장과 의술사만 진실을 알 것 같대요.","간줄라와 공포의 네즐뤼크를 처치해 머리카락을 가져와 달래요."},c={"간줄라와 공포의 네즐뤼크의 머리카락을 가마솥에 넣었어요."}},
[585]={a={"가마솥 속 네즐뤼크는 검은창부족 아이의 행방을 안대요.","대가로 백골가루부족의 전리품 해골을 훔쳐 오라고 해요.","발리아마, 지아타자이, 줄맘웨의 전리품을 가져다 달래요."},c={"이것들이면 황천에서 부릴 노예들을 얻겠대요.","당신 덕에 마음이 풀렸대요."}},
[586]={a={"가마솥 속 간줄라의 머리가 분노를 쏟아 내요.","분노를 달래려면 백골가루부족의 사나운 놈들을 쓰러뜨려야 해요.","족장 학살자 아나텍의 망가진 갑옷을 가져오래요."},c={"간줄라는 믿기 싫지만 인정할 수밖에 없대요.","아나텍이 쓰러져 분노가 가라앉았대요.","언젠가 다시 맞붙자며 기다리겠대요."},nx=588,nt="The Fate of Yenniku"},
[587]={a={"디그는 항구에 올 때마다 코담배를 찾는대요.","붉은해적단이 약초 장수의 물건을 빼앗아 갔대요.","빼앗긴 코담배 일부를 가져와 달래요."}},
[588]={a={"공포의 네즐뤼크가 예니쿠 소식을 전해요.","예니쿠는 추방자 잔질이라는 의술사에게 붙잡혔대요.","검은창부족의 킨윌레이를 찾아가 보래요."},c={"추방자 잔질이 예니쿠를 잡았다니 놀라요.","그렇다면 남은 희망은 아주 작대요.","그래도 희망은 희망이라고 해요."},nx=589,nt="The Singing Crystals"},
[589]={a={"킨윌레이는 예니쿠를 구할 방법을 찾고 있어요.","전설에 따르면 깊은 곳에 마음의 눈이 있대요.","남동쪽 수정 광산에서 푸른 수정을 구해 달래요."},c={"킨윌레이는 수정이 잘 만들어졌다며 기뻐해요.","마음의 눈이 어디 있는지 알아냈대요.","그리고 그것을 지키는 자도 알게 됐대요."},nx=591,nt="The Mind's Eye"},
[590]={a={"캘빈 몬태그는 빚진 게 없다고 화를 내요.","편지도 모른다며 돈을 달라는 말에 발끈해요.","싸움을 걸며 덤벼 보라고 해요."},c={"캘빈 몬태그는 쉬운 상대인 줄 알았는데 놀랐대요.","약속한 돈은 말보다 적은데 거짓말한 탓이래요."}},
[591]={a={"마음의 눈은 오우거 마법사 마이조스가 가지고 있대요.","그는 사악하고 마법이 아주 강하대요.","그에게서 마음의 눈을 빼앗아 오라고 부탁해요."},c={"킨윌레이는 당신의 힘을 전설처럼 칭송해요.","마이조스를 쓰러뜨려 영혼의 세계로 보냈대요.","이제 눈을 우리 뜻대로 다루는 의식을 치르겠대요."},nx=592,nt="Saving Yenniku"},
[592]={a={"킨윌레이가 마음의 눈을 영혼의 보석으로 바꿨대요.","예니쿠는 추방자 잔질과 아보라즈의 폐허에 있대요.","예니쿠를 기절시켜 영혼을 가둔 보석을 님보야에게 가져가래요."},c={"님보야는 예니쿠를 잔질의 지배에서 구했다며 기뻐해요.","부족은 당신의 이름을 노래로 남기겠대요."}},
[594]={a={"쪽지가 든 병에 누군가 도움을 청하는 글이 있어요.","남쪽 바다 섬에서 하늘갈기고릴라에게 붙잡혀 있대요.","제발 도와 달라고 간절히 부탁해요."},c={"공주 푸바는 당신이 자신을 구하러 왔냐고 물어요."},nx=630,nt="Message in a Bottle"},
[595]={a={"일등항해사 크래즈가 정찰병을 찾고 있어요.","붉은해적단이 가시덤불 골짜기 남쪽에 모였다는 소식이 있대요.","무법항 북쪽 작은 만을 조사해 달래요."},c={"작은 배 안에서 지도 한 장과 동전을 발견해요.","지도에는 급히 쓴 글이 적혀 있어요."},nx=597,nt="The Bloodsail Buccaneers"},
[596]={a={"킨윌레이는 님보야를 돕기 위해 그롬골에 보내졌대요.","적의 전리품을 모으면 그들에 맞설 힘이 생긴대요.","북쪽 붉은머리부족 트롤에게서 피묻은 뼈목걸이를 모아 달래요."},c={"이 목걸이를 달여서 주인들의 영혼을 약하게 만든대요.","당신에게 진 빚을 이걸로 갚겠대요."}},
[597]={a={"지도에는 무법항에 빨간 X 표시가 있어요.","이곳에 야영지를 세우고 조용히 있으라는 글이 있어요.","크래즈에게 가서 조사 결과를 보고해 달래요."},c={"크래즈는 정찰에서 돌아온 당신을 알아봐요."},nx=599,nt="The Bloodsail Buccaneers"},
[598]={a={"킨윌레이는 남동쪽의 백골가루부족과 오랫동안 싸워 왔대요.","검은창부족은 그들과 계속 부딪히고 있대요.","백골가루부족을 사냥해 부서진 뼈목걸이를 가져오래요."},c={"킨윌레이는 당신의 힘이 대단하다며 칭찬해요.","백골가루부족이 당신 앞에서 쉽게 쓰러졌다고 해요."}},
[599]={a={"붉은해적단이 무법항을 공격하려 한대요.","일등항해사 크래즈는 이 일이 심각하다고 봐요.","함장 시혼에게 즉시 보고해 달래요."},c={"시혼은 붉은해적단이 무법항을 공격한다니 비웃어요.","이 정보로 함대에 큰 도움을 줬대요.","검은바다 해적단이 고맙다고 해요."},nx=604,nt="The Bloodsail Buccaneers"},
[600]={a={"크랭크 피즐버브는 정직하게 돈 벌기가 힘들대요.","투자개발회사가 정글에서 사업을 벌이고 있어서래요.","그 회사가 캐는 노래하는 수정을 빼앗아 달래요."},c={"수정을 받고 크랭크가 아주 기뻐해요.","투자개발회사가 정글을 잘못 골랐다고 해요."}},
[604]={a={"함장 시혼이 함대를 위해 중요한 임무를 맡기려 해요.","붉은해적단이 거친 해안에 남부 사령부를 세웠어요.","그곳을 급습해 놈들이 무슨 일을 꾸미는지 알아 오래요."},c={"시혼은 이제 놈들의 계획을 알았다며 좋아해요.","그 바보들이 곶 바로 앞에 닻을 내렸대요."},nx=608,nt="The Bloodsail Buccaneers"},
[605]={a={"크랭크 피즐버브는 수정을 파는 중개상이에요.","투자개발회사가 수정을 독점해서 구하기 힘들대요.","바실리스크를 사냥해 노래하는 수정을 구해 달래요."},c={"이 정도면 아주 좋다며 몫을 챙겨 줬어요.","거래해서 즐거웠다고 하네요."},nx=600,nt="Venture Company Mining"},
[606]={a={"\"바다늑대\" 맥킨리는 도박 빚을 안 갚는 게 제일 싫대요.","겁쟁이 필립이 지난주 카드 게임 빚을 아직 안 갚았어요.","안개계곡고릴라 내장을 필립에게 가져가 겁을 주래요."},c={"필립이 내장을 보고 놀라 누가 보냈냐고 묻네요.","어디서 났는지는 알고 싶지 않대요."},nx=607,nt="Return to MacKinley"},
[607]={a={"겁쟁이 필립은 맥킨리에게 빚을 갚을 생각이었대요.","술에 취해 길을 잃어서 늦었다고 해요.","빚이 든 주머니를 맥킨리에게 전해 달래요."},c={"맥킨리는 필립이 얼마나 떨었는지 묻고 웃어요.","이제 도와준 당신이 보수를 받을 차례래요."},nx=609,nt="Voodoo Dues"},
[608]={a={"함장 시혼이 붉은해적단의 뻔뻔함에 화가 났어요.","붉은해적단이 공격 계획을 세워 먼저 치려 해요.","노련한 병사들과 가서 놈들의 지휘부를 암살해 달래요."}},
[609]={a={"\"바다늑대\" 맥킨리는 아직 받을 돈이 많이 남았대요.","세 사람은 몇 달째 빚을 안 갚고 있대요.","그들의 물건을 받아 맥킨리에게 가져다 달래요."},c={"맥킨리는 물건을 좋은 값에 팔 수 있어 기뻐해요.","잃으면 안 될 것은 걸지 말라고 전하래요."},nx=613,nt="Cracking Maury's Foot"},
[613]={a={"마우리가 의족에 자물쇠를 채워 놓아 열 수가 없대요.","그 안에 맥킨리가 받을 돈이 들어 있대요.","모쉬오그일족 오우거에게서 열쇠를 찾아 달래요."},c={"열쇠를 찾아와 맥킨리가 크게 고마워해요.","보상을 건네며 수고했다고 해요."}},
[617]={a={"선원 블로즈는 일거리를 찾는 당신에게 일을 주려 해요.","그의 친구 그로이는 아키리스 갈대를 비싸게 사요.","그 갈대 묶음을 모아 가져다 달래요."},c={"갈대를 잘 모아 와서 블로즈가 칭찬하네요.","나가에게는 미안하지만 다들 먹고살아야 한대요."},nx=623,nt="Akiris by the Bundle"},
[621]={a={"추방자 잔질은 자기 일족에게 쫓겨난 신세래요.","잔질은 정글 식물 혼합물로 남의 의지를 약하게 한대요.","그 혼합물 견본을 가져오면 쓸모를 찾아보겠대요."},c={"크랭크가 좋다며 보수를 주네요.","비밀을 지킨 보답으로 덤도 준대요."}},
[624]={a={"쪽지 속 수수께끼가 당신에게 말을 걸어요.","죽음의 고개 동쪽 다리 밑에 무언가 기다린대요.","그 수수께끼를 풀어 보래요."},c={"젖은 두루마리에 다음 단서가 들어 있대요."},nx=625,nt="Cortello's Riddle"},
[625]={a={"젖은 두루마리에 쓰인 또 다른 수수께끼예요.","먼지진흙 습지대 남서쪽 동굴에 단서가 있대요.","그 단서를 찾아 수수께끼를 풀어 보래요."},nx=626,nt="Cortello's Riddle"},
[626]={a={"곰팡이 슨 두루말이가 또 수수께끼를 내요.","동부 내륙지 큰 폭포 밑 물속에 보물이 있대요.","그 보물을 찾아 수수께끼를 풀어 보래요."},c={"상자를 열어 보니 뭔가 나온대요."}},
[628]={a={"드리즐릭은 가죽 제품을 만드는 사람이에요.","바다악어 가죽이 튼튼해서 겉감에 제격이래요.","덩치큰 바다악어 가죽을 구해 달라고 부탁해요."},c={"덕분에 주문을 예정보다 일찍 끝냈대요.","여분으로 한 켤레를 더 챙겨 줬어요."}},
[629]={a={"킨윌레이는 검은창부족 사람이에요.","썩은내 산호초 폐허에 옛 서판이 있는데 신성하대요.","서판 조각을 가져다 오그리마에 모시고 싶대요."},c={"좋은 조각이라며 신성한 곳에 두겠대요.","그리렉의 힘과 명예를 떠올리게 해 준대요.","검은창부족과 우정이 깊어졌다고 하네요."}},
[630]={a={"공주 푸바가 밀림의왕 무클라에게 잡혀 있대요.","짐승들이 사슬로 묶어 못 달아나게 한대요.","무클라를 처치하고 족쇄 열쇠를 찾아 달래요."},c={"푸바는 큰 수치에서 구해 줘서 고맙대요.","용기를 기리는 징표를 건네요."}},
[635]={a={"손에 쥔 수정이 고동치기 시작해요.","머릿속에 환영이 보이고 그곳으로 끌리는 것 같대요.","아라시 고원 북쪽 산에서 환영 속 수정을 찾아 달래요."},c={"수정 안에 살아 있는 힘이 갇힌 듯 고동쳐요."}},
[638]={a={"님보야는 볼진의 명령을 전하고 있어요.","토라스 트롤베인은 죽고 스트롬가드는 폐허가 됐어요.","전설의 검 트롤칼라를 빼앗는 일을 도와 달래요."},c={"볼진이 맡긴 일이 어려울 거래요.","그래서 도와주는 게 꼭 필요하대요."},nx=639,nt="Sigil of Strom"},
[639]={a={"젠구는 트롤칼라를 손에 넣으려고 애쓰고 있어요.","첫 인장은 스트롬가드의 비밀결사대 손에 있대요.","스트롬의 인장을 찾아 젠구에게 가져다 달래요."},c={"잘했다며 좋은 출발이라고 칭찬했어요.","트롤칼라를 꺼내려면 인장을 더 모아야 한대요."},nx=640,nt="The Broken Sigil"},
[640]={a={"토라스 트롤베인의 무덤은 여러 인장으로 지켜져 있어요.","첫 인장은 얻었지만 나머지는 스트롬가드 민병대가 지켜요.","소라딘의 인장 조각을 찾아 토건에게 가져다 달래요."},c={"조각이 다 있어서 다시 만들기 쉽대요.","눈을 감고 있는 게 좋겠다고 해요."},nx=641,nt="Sigil of Thoradin"},
[641]={a={"토건이 소라딘의 인장을 완벽하게 복원했어요.","이제 트롤베인의 무덤 봉인을 풀 수 있대요.","해머폴의 젠구에게 가져다 달래요."},c={"트롤칼라를 꺼내는 데 절반쯤 왔대요.","마지막 인장은 어디 있는지 아직 모른대요.","그래도 찾아낼 거라고 믿는대요."},nx=643,nt="Sigil of Arathor"},
[642]={a={"미즈라엘은 땅속에 갇힌 대지의 공주래요.","이 수정 결정으로만 지상 세계와 말할 수 있대요.","마른수염 골짜기 코볼트에게서 결정 파편을 빼앗아 달래요."},c={"수정을 작동시켜 주니 벌써 기운이 나대요.","그래도 자유에는 아직 멀었다고 하네요."},nx=651,nt="Stones of Binding"},
[643]={a={"인간 왕자가 기병을 이끌고 아라시 고원을 떠돌아요.","왕자가 인장을 부관 밸러콜에게 맡겼대요.","부관 밸러콜을 찾아 처치하고 인장을 가져와 달래요."},c={"기병 대장을 잃으면 스트롬가드 방어군이 크게 흔들려요.","인장 하나만 더 있으면 트롤칼라를 얻는대요."},nx=644,nt="Sigil of Trollbane"},
[644]={a={"젠구는 트롤베인의 무덤을 열 마지막 인장을 찾고 있어요.","왕자 갈렌 트롤베인이 그 인장을 갖고 있대요.","스트롬가드 예배당의 왕자를 처치하고 인장을 가져오래요."},c={"젠구는 이제 백성이 트롤베인에게 시달리지 않는다고 기뻐해요.","인장이 모여 트롤칼라를 손에 넣게 됐대요."},nx=645,nt="Trol'kalar"},
[645]={a={"모은 인장들이 하나로 합쳐졌대요.","그 인장이면 트롤베인 무덤의 봉인을 깰 수 있대요.","스트롬가드의 트롤베인 무덤에서 트롤칼라를 가져오래요."},c={"이그네우스의 인장이 무덤 문양과 맞닿아 번쩍였대요.","돌 손이 쥐고 있던 전설의 검이 풀려났대요."},nx=646,nt="Trol'kalar"},
[646]={a={"트롤베인의 무덤에서 돌 칼집 속 트롤칼라가 풀려났어요.","지금 그 검을 손에 쥐고 있어요.","해머폴의 젠구에게 가져가 달래요."},c={"젠구는 가장 큰 무기가 이제 우리 손에 있다고 해요.","당신 덕분에 큰 도움을 받았다며 고마워해요.","검은 님보야에게 보내겠다고 약속해요."}},
[648]={a={"유도 로봇 OOX-17/TN을 다시 작동시키려면 시간이 필요해요.","넓고 안전한 곳에서 긴 이륙 준비를 해야 한대요.","스팀휘들 항구까지 호위한 뒤 무법항에서 보고해 달래요."},c={"오글소프는 로봇을 구해 줘서 정말 고맙대요.","덕분에 시간과 돈을 많이 아꼈다고 해요.","원하는 물건을 하나 골라 가지라고 해요."}},
[649]={a={"드란 드로퍼스가 좋은 술 리플을 찾고 있어요.","버려진 호드 전초기지에 벌꿀 리플이 숨겨져 있대요.","포장된 리플을 가져다 달래요."},c={"말톤은 리플을 원래 포장으로 팔면 값을 더 받는대요.","포장해 줄 사람은 동부 내륙지의 술꾼 하이 엘프래요."},nx=650,nt="Ripple Recovery"},
[650]={a={"말톤이 리플을 포장해 줄 엘프를 소개해요.","길버라딘 선체이서는 냄새만 맡아도 술을 알아맞혀요.","리플을 포장해서 돌아오라고 해요."},nx=77,nt="A Sticky Situation"},
[651]={a={"오색 결정이 땅속에 묶여 있대요.","봉인석들은 아라시 고원 곳곳에 흩어져 있대요.","다른 봉인석의 열쇠를 모아 내부 봉인석에 가져가 달래요."},c={"봉인석을 다 열었다며 미즈라엘이 기뻐해요.","족쇄가 느슨해져서 자유가 가까워졌대요.","자기를 구해 준 은인이래요."},nx=652,nt="Breaking the Keystone"},
[652]={a={"내부 봉인석이 풀려 몸이 조금 자유로워졌대요.","아직 족쇄가 남아 있고 열쇠는 포즈루크가 갖고 있대요.","포즈루크에게서 마법봉을 빼앗아 쐐기돌을 열어 달래요."},c={"당신이 마법봉을 쐐기돌에 꽂자 땅이 흔들렸대요."},nx=653,nt="Myzrael's Allies"},
[654]={a={"동력원을 켜자 분석 도구가 빛나며 떨렸어요.","선임기술자 빌지위즐에 따르면 자료 모을 시간이 정해져 있대요.","타나리스 사막에서 자료를 모아 빌지위즐에게 돌아가래요."},c={"빌지위즐이 동력원을 금방 빼 준대요.","이제 자료를 잃을 걱정 없이 쓸 수 있대요."},nx=864,nt="Return to Apothecary Zinge"},
[655]={a={"고르멀은 오랫동안 이곳에 갇혀 절망 속에 살았대요.","대족장 둠해머가 뒤에서 창에 찔려 쓰러졌대요.","해머폴의 토건과 얘기해 보래요."},c={"고르멀은 둠해머의 죽음에서 아직 못 벗어났대요.","탈출 때 남겨져 몇 년을 홀로 떠돌았대요."},nx=672,nt="Raising Spirits"},
[656]={a={"실성한 텔두린은 미즈라엘이 힘을 되찾기 전에 막아야 한대요.","미즈라엘은 거인들이 묶어 둔 존재래요.","그녀를 물리치고 족쇄를 결정에 묶어 두래요."},c={"족쇄를 결정에 두르자 땅 밑에서 괴상한 울음이 들렸대요.","결정이 따뜻함 대신 위협적인 맥박을 내요.","땅 밑의 것이 지상에 악의를 품은 것 같대요."}},
[662]={a={"메이든즈 폴리호와 실버파인 스피릿호가 암초에 가라앉았대요.","그 배의 항해일지와 해도가 남의 손에 들어가면 안 돼요.","일등항해사 닐즐릭스가 그 기록을 되찾아 달래요."},c={"정보가 안전해서 무법항 지휘부가 안심하겠대요.","잘했다며 칭찬해 줬어요."}},
[663]={a={"망꾼 롤로는 늘 바다를 살피는 사람이에요.","메이든즈 폴리호와 실버파인 스피릿호가 바다 밑에 가라앉았대요.","여기 머물 거면 셰익스 오브린과 얘기해 보래요."},c={"바다가 울렁이더니 물이 빠지고 배들이 암초에 부딪쳤대요.","그냥 암초가 아니라 바다 밑에 뭔가 있는 것 같대요.","선원들을 도와주면 후하게 보상한대요."}},
[664]={a={"선장 스틸구트는 배를 잃고 겨우 살아남았대요.","비수가시일족 나가들이 생존자를 모두 죽였대요.","그 짐승들을 처치해 달라고 부탁해요."},c={"잘했다며 그 놈들은 벌을 받아 마땅하대요.","배와 선원은 돌아오지 않지만 위로가 된대요."}},
[665]={a={"학자 피즐솔프는 오브린 선장을 도와 보물을 찾으려 해요.","그 동굴은 저주가 걸려 가까이 가면 습격을 받는대요.","피즐솔프가 힘을 채울 동안 지켜 달라고 부탁해요."},c={"고글이 이제 완벽하게 작동한대요.","잘했다고 칭찬해 줬어요."},nx=666,nt="Sunken Treasure"},
[666]={a={"발명가 드랙슬게이지는 보석이 돌처럼 굳었다고 해요.","고글의 힘으로 보석을 쉽게 찾을 수 있대요.","보석을 찾아 오고 고글을 돌려 달래요."},c={"정말 훌륭하다며 칭찬했어요.","오브린 선장이 아주 기뻐할 거래요."},nx=668,nt="Sunken Treasure"},
[667]={a={"셰익스 오브린은 비수가시일족의 공격을 앞두고 있어요.","나가는 잔인해서 그가 죽을 때까지 공격할 거래요.","배 위에서 대포로 나가를 몰아내며 그를 지켜 달래요."},c={"공격을 버텨 냈다며 셰익스가 기뻐해요.","당신 없이는 못 했을 거라며 고마워해요.","당신은 더 큰 일을 할 사람이라고 해요."}},
[668]={a={"발명가 드랙슬게이지는 보석을 찾으면 바로 가져오래요.","해적들과 지내 보니 그 보물은 오래 들면 위험하대요.","보석을 셰익스 오브린에게 가져다 달래요."},c={"꼬마 노움들이 쓸모를 증명했대요.","이래서 데리고 있었던 보람이 있다고 해요."},nx=669,nt="Sunken Treasure"},
[669]={a={"셰익스 오브린은 이곳을 빠져나가기 어렵대요.","조수가 낮고 짐승들이 계속 노려서 움직이기 힘들대요.","함장 시혼에게 보물 소식을 알리고 표본을 전해 달래요."},c={"역시 셰익스 오브린이라며 흐뭇해해요.","그가 이 임무에 맞는 선장이었다고 하네요."},nx=670,nt="Sunken Treasure"},
[670]={a={"함장 시혼의 함대는 보급품을 채울 때까지 무법항에 묶여 있대요.","곳곳에 심각한 문제가 생겨 극비 문서를 보내야 한대요.","셰익스 오브린에게 편지를 훔쳐 보지 말고 전해 달래요."},nx=667,nt="Death From Below"},
[671]={a={"토건은 지난 밤 이상한 기운을 느꼈대요.","서쪽 북부습곡 장원에 악마를 부른 흔적이 있대요.","조사하게 혈석 아뮬렛을 가져다 달라고 부탁해요."},c={"그 무리의 속셈을 알아내려면 시간이 걸린대요.","어두운 악마 마법과 얽혀 있어 걱정된대요."},nx=673,nt="Foul Magics"},
[672]={a={"토건은 한 사람을 달래려 했지만 통하지 않았대요.","새로 찾은 주술을 보여 주면 희망을 되찾을지도 모른대요.","고원랩터 눈을 가져다 달라고 부탁해요."},c={"이 눈을 준 랩터들의 영혼이 힘을 준대요.","이 아뮬렛을 지닌 사람에게 힘이 깃든대요."},nx=674,nt="Raising Spirits"},
[673]={a={"스트롬가드 성벽 안에 아주 강한 흑마법사가 있대요.","그 흑마법사가 마법 유물로 악마를 대량으로 불러낸대요.","마레즈 코울을 찾아 처치하고 물건을 가져다 달래요."},c={"이 수정구를 부수면 밤잠을 편히 잘 수 있대요.","끔찍했던 악마의 힘을 떠올리게 한대요."}},
[674]={a={"고르멀은 한때 용사의 열정을 품었던 전사래요.","토건은 랩터의 힘이 그 열정을 되살릴지 보고 싶대요.","랩터 발톱 아뮬렛을 고르멀에게 가져다 달래요."},c={"이게 뭐냐며 닦은 뼈일 뿐이라고 해요.","장신구 하나로 호드가 영광을 되찾겠냐고 해요."},nx=675,nt="Raising Spirits"},
[675]={a={"고르멀은 아뮬렛을 땅에 던져 버렸어요.","토건이 보낸 사람이냐며 자비를 이해할 수 없대요.","토건에게 돌아가 얘기해 보라고 해요."},c={"아뮬렛의 힘이 부족해서 효과가 없었대요.","그래도 주술의 힘을 보이면 예전의 모습을 되찾을 거래요."},nx=701,nt="Guile of the Raptor"},
[676]={a={"탈로우는 해머폴 기지가 공격받고 있다고 해요.","스트롬가드 북동쪽 오우거 고분을 먼저 치라고 해요.","실력을 증명한 뒤 해머폴의 드럼 펠에게 보고해 달래요."},c={"해머폴을 도울 만큼 강한가 보네요.","탈로우가 시험하려고 보낸 것 같대요.","싸움이 더 필요하니 쉬고 다시 오라고 해요."},nx=677,nt="Call to Arms"},
[677]={a={"마른나무껍질 트롤과 돌주먹 오우거가 우리를 몰아내려 한대요.","오우거들은 우리를 먹잇감으로 보고 있대요.","남쪽 마른나무껍질 트롤을 닥치는 대로 처치하라고 해요."},c={"옷에 전쟁의 흔적이 묻고 땀이 흐르네요.","아주 좋다며 칭찬해요."},nx=678,nt="Call to Arms"},
[678]={a={"드럼 펠은 전투 실력이 탁월하다고 칭찬해요.","돌주먹일족 소굴은 남서쪽 드워프 다리 쪽에 있대요.","그곳의 강한 투사와 사제를 쓰러뜨리고 돌아오래요."},c={"코도만큼 강하다며 칭찬해요.","전투를 좋아하는 모습이 종족의 자랑이래요."},nx=679,nt="Call to Arms"},
[679]={a={"드럼 펠은 이제 짐승들의 우두머리를 해치울 때라고 해요.","침략자들은 스트롬가드 폐허에 소굴을 만들었대요.","돌주먹일족 우두머리와 주술사를 찾아 처치해 달래요."},c={"종족의 자랑이라며 칭찬해요.","위협이 많이 줄어 고원에서 번성할 거래요."}},
[680]={a={"무그톨의 부하 오르칼라가 코린 펠의 남편을 미워한대요.","점을 쳐 보니 오르칼라가 함정을 꾸미고 있는 것 같대요.","오르칼라를 대신 없애 달라고 부탁해요."},c={"큰 도움을 줘서 고맙다고 해요.","남편의 목숨과 해머폴이 하루 더 지켜졌대요."}},
[687]={a={"게릭 본그립은 텔두린이 실성해 떠났다고 해요.","텔두린이 미즈라엘의 두루마리를 훔쳐 달아났대요.","황야의 땅에서 텔두린을 찾아 두루마리를 되찾아 달래요."},c={"텔두린이 정신없이 떠들며 인사를 해요.","가끔은 미쳐 있는 게 유일한 위로래요."},nx=692,nt="The Lost Fragments"},
[688]={a={"미즈라엘이 드디어 자유를 얻었다며 기뻐해요.","미즈라엘은 거인들과 싸우려고 힘을 모으고 있대요.","해머폴의 자루크와 얘기해 보라고 해요."},c={"미즈라엘이 찾아올 사람을 미리 알려 줬대요.","지상으로 데려오려면 할 얘기가 많대요."},nx=687,nt="Theldurin the Lost"},
[692]={a={"미즈라엘의 두루마리는 바위 정령들이 찢어 버렸대요.","조각을 모으면 다시 붙일 수 있을지도 모른대요.","찢어진, 구겨진, 그을린 두루마리 조각을 모아 가져다 달래요."},c={"조각을 찾아와 텔두린이 고마워해요.","미즈라엘을 막을 유일한 기회일지 모른대요.","이제 조각을 다시 붙여 볼 거래요."},nx=656,nt="Summoning the Princess"},
[698]={a={"다르는 동쪽 해변 전초 기지에 보급품을 모으고 있대요.","톡카르는 보초와 요리로 바빠서 고기를 못 보냈대요.","슬픔의 늪의 톡카르에게 톱니악어 고기를 가져다 달래요."},c={"오늘 밤 불에 구울 고기가 생겨서 좋대요.","덕분에 밤을 더 편하게 보낼 것 같대요."},nx=699,nt="Lack of Surplus"},
[699]={a={"톡카르는 멀록의 위협 속에 이곳을 지키고 있어요.","쉴 틈이 거의 없어서 도움이 필요하대요.","무쇠턱 톱니악어 발톱을 가져다 주면 무기로 보답한대요."},c={"톡카르는 당신이 무사한 것을 보고 반가워해요.","발톱이 잘 쓰일 거라며 바로 무기를 만들겠대요."},nx=1422,nt="Threat From the Sea"},
[701]={a={"토건은 고르멀에게 랩터의 기민함을 주는 물건을 만들려 해요.","그러려면 남서쪽의 랩터 심장이 필요하대요.","식인 고원랩터에게서 랩터 심장을 구해 달래요."},c={"이 심장들이면 딱 맞는대요.","랩터들의 힘과 영혼을 수정구에 담을 거래요."},nx=702,nt="Guile of the Raptor"},
[702]={a={"토건이 랩터의 힘을 담은 수정구를 완성했대요.","고르멀의 영혼을 일깨우면 새 삶의 목표가 생길 거래요.","토건의 수정구를 고르멀에게 전해 달래요."},c={"이번엔 흥미로운 걸 가져왔다고 해요.","수정구에서 이상한 힘이 나온대요."},nx=847,nt="Guile of the Raptor"},
[703]={a={"리글퍼즈는 대머리수리 날개 구이를 제일 좋아해요.","재료는 다 있는데 대머리수리 날개만 없대요.","대머리수리 날개를 구해 주면 조리법을 알려 준대요."},c={"그 날개로 바로 요리를 시작한대요.","직접 만들어 보라고 조리법도 줬대요."}},
[705]={a={"리글퍼즈는 황야의 땅에서 섬광탄으로 야생 동물을 쫓아요.","섬광탄 재료인 푸른 진주 가루가 거의 떨어졌대요.","썩은내 산호초의 푸른 진주를 구해 달래요."},c={"이거면 아주 좋겠다며 가루를 만들 거래요.","썩은 고기를 먹는 짐승들이 조심해야 할 거래요."},nx=1559,nt="Flash Bomb Recipe"},
[709]={a={"실성한 텔두린이 멸망이 다가온다고 소리쳐요.","놈들에 대해 더 알면 막을 수 있을지도 모른대요.","울다만 깊은 곳의 상자에서 류네의 서판을 찾아 달래요."},c={"행운이 따랐다며 고마워해요.","아직 구할 수 있을지도 모른대요."}},
[710]={a={"로트윌 베리아투스는 황야의 땅에서 정령 연구를 하고 있어요.","새 공격 주문을 시험하려면 작은 돌조각이 필요하대요.","서쪽 하급 바위 정령에게서 돌조각을 구해 달래요."},c={"돌조각이 쓸 만하다며 고마워해요.","모래가 예상보다 많다며 중얼거려요."},nx=711,nt="Study of the Elements: Rock"},
[711]={a={"로트윌 베리아투스는 황야의 땅에서 실험을 하고 있어요.","작은 돌조각은 시험하는 데 시간이 걸린대요.","그래서 바위 정령에게서 큰 돌조각을 구해 달래요."},c={"정말 대단하다며 감탄했어요.","여럿이 할 일을 혼자 해냈다고 해요."},nx=712,nt="Study of the Elements: Rock"},
[712]={a={"로트윌 베리아투스는 족쇄의 힘을 재려고 해요.","그 힘을 재려면 큰 바위 정령의 팔보호구가 필요하대요.","남서쪽 오우거 근처의 바위 정령에게서 구해 달래요."}},
[713]={a={"로트윌 베리아투스는 정령을 제어할 족쇄를 만들고 있어요.","족쇄를 강하게 하려면 냉기 오일이 필요하대요.","알터랙의 브로킨에게 배워서 가져다 달래요."},c={"완벽한 냉각제라며 아주 기뻐해요.","마법사들이 크게 놀랄 거래요."},nx=714,nt="Gyro... What?"},
[714]={a={"로트윌 베리아투스는 실험으로 정신이 없어요.","작지만 꼭 필요한 재료가 아직 남았대요.","태엽장치를 구해다 주면 실험을 끝낼 수 있대요."},c={"태엽장치를 받고 아주 기뻐했어요.","그런데 실험은 아직 조금 더 걸린대요."},nx=715,nt="Liquid Stone"},
[715]={a={"루시앙 토셀렌치는 로트윌 밑에서 물약을 연구했어요.","로트윌이 정령을 부르면 물약이 곧 필요해진대요.","물약을 구해 주면 조제법을 알려 준대요."},c={"아주 기뻐하며 고맙다고 했어요.","이 물약들은 황야의 땅을 지날 때 유용할 거래요."}},
[716]={a={"루시앙 토셀렌치가 당신에게 줄 팔보호구를 만들고 있대요.","로트윌을 위해 모은 돌로 만들 수 있대요.","대장장이의 청동 무늬 팔보호구를 가져다 달래요."},c={"루시앙이 팔보호구를 건네며 한번 껴 보래요."}},
[728]={a={"실성한 텔두린은 석판만으로는 답이 부족하대요.","오래전 쓰인 야그인의 법전에 우리를 지킬 지식이 있대요.","언더시티의 관리인 벨두거에게 가서 법전을 받아 달래요."},c={"표식을 함부로 드러내지 말래요.","우리 맹세를 못 믿거나 실패를 바라는 자들이 있대요."},nx=736,nt="The Star, the Hand and the Heart"},
[734]={a={"로트윌 베리아투스는 족쇄 만들기에 몰두해 있어요.","로트윌에게 꼭 필요한 기어가 있대요.","루시앙 토셀렌치에게 가서 그 기어를 받아 오래요."},nx=777,nt="This Is Going to Be Hard"},
[736]={a={"관리인 벨두거가 야그인의 법전을 주겠다고 해요.","대신 강력한 물건들을 가져오라고 해요.","물건 이름은 말하기 어려워 노트에 적어 준대요."},nx=737,nt="Forbidden Knowledge"},
[737]={a={"게릭 본그립이 귀한 법전을 맡겨 준대요.","법전에는 많은 진실이 담겨 있지만 위험하대요.","적의 손에 넘어가지 않게 조심해 달래요."},c={"법전을 받고 희망이 보인다며 기뻐해요.","그들이 풀려나면 다 끝이라고 걱정해요."}},
[742]={a={"포고꾼 윈드스트라이더가 젊은 모험가들에게 외쳐요.","호드가 불모의 땅 북쪽에 전초 기지를 세웠대요.","잿빛 골짜기 사냥에 나서려면 세나니 썬더하트를 찾아가래요."},c={"세나니 썬더하트는 새 개척지에 온 걸 환영한대요.","여기 주둔지를 둘러보고 조람 해안도 가 보래요.","사냥에 대해 알고 싶으면 기꺼이 알려 준대요."},nx=6383,nt="The Ashenvale Hunt"},
[743]={a={"루울 이글탈론은 멀고어에서 가르치는 전사예요.","성난바람하피는 멀고어의 천적이라 실력을 가늠하기 좋대요.","남동쪽 성난바람하피를 잡아 실력을 보라고 해요."},c={"루울이 잘했다고 칭찬해요.","이제 먼 곳으로 떠날 준비가 잘 됐대요.","앞길에 순풍이 불기를 빌어 줘요."}},
[744]={a={"이얀 이글탈론의 형님이 곧 의식을 치러요.","형님의 머리 장식에 쓸 깃털이 부족하대요.","썬더 블러프 북쪽 하피에게서 깃털을 모아 달래요."},c={"이얀은 도와줘서 고맙다고 해요.","형님께 머리 장식을 드리면 제 할 일은 끝난대요."}},
[745]={a={"바인 블러드후프는 이 땅이 대립으로 상처 입었다고 해요.","회색갈기일족 놀들이 바위굴에 살며 야생동물을 죽여요.","이제 대화로는 안 되니 막아 달래요."}},
[746]={a={"북서쪽에서 드워프들이 발굴 준비를 하고 있대요.","드워프들은 땅속에 비밀이 묻혀 있다고 믿는대요.","드워프 도구를 모아 부숴서 가져다 달래요."},c={"바인은 고맙다고 해요.","이제 멀고어의 짐승들이 진정될 거래요.","드워프들도 땅을 파헤쳐선 안 된다는 걸 알게 될 거래요."}},
[747]={a={"그룰 호크윈드는 당신의 풍모가 전도유망하다고 해요.","마을에 고기가 거의 떨어지고 깃털도 필요하대요.","근처 초원타조를 사냥해 물자를 채워 달래요."},c={"나라체 타우렌들이 고마워한대요.","당신은 가능성이 많다고 칭찬해요."}},
[748]={a={"멀 썬더혼은 고블린들이 신성한 우물을 더럽혔다고 화내요.","우물을 정화하려면 정화의 토템상이 필요하대요.","초원늑대 앞발과 초원타조 발톱을 구해 달래요."},c={"멀 썬더혼은 잘했다고 칭찬해요.","이 재료로 정화의 토템상에 힘을 담겠대요."},nx=754,nt="Winterhoof Cleansing"},
[749]={a={"모린 클라우드스토커의 무리가 짐마차를 공격했대요.","불을 질렀지만 상자가 남았을지도 모른대요.","가서 보급상자 안에 뭐가 있는지 확인해 달래요."},c={"상자 겉면에 투자개발회사 광산 부서 도장이 찍혀 있어요.","상자 메모에는 중앙 공장에서 처리될 거라고 적혀 있어요."},nx=751,nt="The Ravaged Caravan"},
[750]={a={"그룰 호크윈드는 사냥이 마을의 생존과 이어진다고 해요.","아이들 옷과 천막을 고칠 가죽이 필요하대요.","남쪽 언덕의 산지퓨마 모피를 구해 와 달래요."},c={"나라체 타우렌들이 이 물자에 고마워한대요.","사냥 솜씨라면 언젠가 썬더 블러프에서 존경받을 거래요."},nx=780,nt="The Battleboars"},
[751]={a={"보급상자를 열자 광석과 광물이 가득 차 있어요.","광석 위에 종이 뭉치가 단단히 묶여 있었대요.","그 문서를 모린 클라우드스토커에게 가져가 달래요."},c={"모린은 투자개발회사가 자원을 빼앗으려 한다고 확인했대요.","이제 대책을 세워야 한대요."}},
[752]={a={"족장 호크윈드의 어머니가 아침에 물을 길러 나갔대요.","나라체 남동쪽 우물에 간 뒤로 꽤 시간이 지났대요.","가서 어머니를 찾아 무슨 일이 있는지 봐 달래요."},c={"대모 호크윈드는 늙은 나를 도우려고 여기까지 왔냐며 놀라요.","참 착하다고 감탄해요."},nx=753,nt="A Humble Task"},
[753]={a={"대모 호크윈드는 몸이 예전 같지 않다고 해요.","그래도 부족을 위한 일은 아직 할 수 있대요.","우물의 물병을 나라체 야영지 족장에게 가져다 달래요."},c={"족장 호크윈드는 대모의 부탁으로 온 걸 알아봐요.","남을 돕는 마음이 좋아 썬더 블러프에서 자랑스러울 거래요."},nx=755,nt="Rites of the Earthmother"},
[754]={a={"멀 썬더혼이 윈터후프 정화의 토템상을 완성했대요.","우물은 남동쪽에 있고 고블린들이 지키고 있대요.","토템상으로 우물을 정화해 달래요."},c={"멀 썬더혼은 우물 근처 짐승들이 벌써 물을 마신다고 해요.","땅을 위해 큰 일을 했고 타우렌에게도 큰 일이래요."},nx=756,nt="Thunderhorn Totem"},
[755]={a={"족장 호크윈드는 당신이 열심히 배우는 걸 칭찬해요.","대지모신의 의식은 세 가지인데 첫 번째는 힘의 의식이래요.","예언자 그레이텅에게 족장이 보냈다고 전해 달래요."},c={"예언자 그레이텅은 족장이 보냈냐고 되물어요.","대지모신의 의식은 쉬운 일이 아니래요."},nx=757,nt="Rite of Strength"},
[756]={a={"멀 썬더혼은 썬더혼 정화의 토템상을 만들려 해요.","토템에는 멀고어 포식자들의 발톱이 필요하대요.","긴발톱 초원늑대와 평원퓨마의 발톱을 구해 달래요."},nx=758,nt="Thunderhorn Cleansing"},
[757]={a={"예언자 그레이텅이 첫 번째 시험을 내려요.","칼날가시 협곡의 뾰족털일족이 사냥꾼을 습격해요.","그들의 허리띠를 나라체 야영지 족장에게 가져가 달래요."},c={"족장 호크윈드는 첫 번째 시험을 통과했다고 해요.","부족이 자랑스러워할 거래요."},nx=763,nt="Rites of the Earthmother"},
[758]={a={"멀 썬더혼이 썬더혼 정화의 토템상을 완성했대요.","마을 북쪽 썬더혼 우물에 정화가 필요하대요.","그 우물에서 토템상으로 의식을 치러 달래요."},c={"멀 썬더혼은 조상이 꿈에 나타났다고 해요.","우물 근처에서 한 일을 칭찬하며 감사의 선물을 준대요."},nx=759,nt="Wildmane Totem"},
[759]={a={"멀 썬더혼은 정화할 우물이 하나 남았다고 해요.","그 우물을 정화하려면 우두머리 초원늑대의 이빨이 필요하대요.","북쪽에서 사냥해 이빨을 가져다 달래요."},c={"멀 썬더혼은 아주 잘했다고 칭찬해요.","땅이 바친 희생이 느껴져 슬프면서도 자랑스럽대요."},nx=760,nt="Wildmane Cleansing"},
[760]={a={"멀 썬더혼은 우물 두 곳을 정화한 일이 유명하대요.","이제 와일드메인 정화의 토템상이 완성됐대요.","썬더 블러프 북쪽 우물에서 마지막 의식을 치러 달래요."},c={"멀 썬더혼은 우물을 정화해 땅을 살렸다고 해요.","블러드후프 마을이 고마워한대요.","멀고어의 물이 영원히 깨끗하기를 바란대요."},nx=98435,nt="Thunderhorn's Report"},
[761]={a={"하큰 윈드토템은 검독수리 깃털을 실력의 상징으로 여겨요.","검독수리는 교활해서 찾기도 잡기도 어렵대요.","검독수리 깃털을 가져와 명예를 높여 달래요."}},
[763]={a={"족장 호크윈드는 시험 두 가지가 더 남았다고 해요.","바인 블러드후프에게 가면 장로들의 신임을 얻을 수 있대요.","호크윈드의 토템을 바인에게 가져가 달래요."},c={"바인은 족장 호크윈드의 소식이라며 반가워해요.","목각을 보니 당신은 특별한 사람이래요."},nx=767,nt="Rite of Vision"},
[764]={a={"모린 클라우드스토커는 투자개발회사가 너무 빨리 커진다고 해요.","그들이 우리 땅에서 작업하는 걸 용납할 수 없대요.","광산에 가서 우리의 뜻을 분명히 전해 달래요."},c={"모린은 투자개발회사가 이 신호를 무시하지 못할 거래요.","이제 타우렌을 얕보지 못할 거래요."}},
[765]={a={"짐마차에서 가져온 문서로 투자개발회사 계획을 알게 됐대요.","그 계획을 세운 사람이 감독관 피즈스프로켓이래요.","그를 처치하고 서류철을 가져다 달래요."},c={"모린은 피즈스프로켓이 죽었다는 소식에 화가 조금 가라앉았대요.","그의 물건을 살펴 투자개발회사의 앞일을 알아본대요.","애써 줘서 고맙대요."}},
[766]={a={"마우르 레인콜러는 마즈라나체에게 어깨를 물렸어요.","물린 상처가 감염되지 않게 약을 만들어야 한대요.","초원늑대 심장 등 재료를 서둘러 구해 달래요."},c={"마우르는 고맙다며 치료제를 만들 수 있겠대요.","덕분에 감염을 막고 결국 낫게 될 거래요.","당신에게 목숨을 빚졌다고 해요."}},
[767]={a={"바인 블러드후프는 예언의 의식을 권해요.","타우렌에게 대지는 가장 신성한 부양자래요.","마을의 정신적 지도자 잘만 투문과 대화해 달래요."},c={"잘만 투문은 당신이 올 줄 알았다고 해요.","대지모신의 의식을 거치려는 사람은 금방 알아본대요."},nx=771,nt="Rite of Vision"},
[768]={a={"베렌 톨스트라이더는 가죽으로 옷과 갑옷을 만들어요.","사냥해 온 짐승 가죽으로 만들어 준다고 해요.","얇은 가죽을 모아 베렌에게 가져다 달래요."},c={"베렌은 가죽이 아주 좋다고 감탄해요.","이걸로 좋은 가죽 제품을 만들 수 있대요.","보답으로 이걸 받으라고 건네요."}},
[769]={a={"베렌 톨스트라이더는 멀고어 코도를 동경한대요.","가죽 세공을 아는 이에게 자루 만드는 법을 알려줘요.","거래에 쓸 재료를 구해 오라고 해요."},c={"베렌은 가죽 세공에 관심 가져 줘서 뿌듯하대요.","고맙다고 해요."}},
[770]={a={"해진 유령울음늑대 가죽에 불타는 군단과 싸운 상처가 남았어요.","블러드후프 마을에 유령울음늑대의 죽음을 아는 이가 있을지도 몰라요.","그 이야기를 아는 사람을 찾아 달래요."},c={"스코른 화이트클라우드는 유령울음늑대를 이겼냐며 놀라요.","사냥을 그만둔 자기 무기 하나를 써 보라고 건네요.","유령울음늑대의 영혼이 드디어 평안하기를 바란대요."}},
[771]={a={"잘만 투문은 예언의 물을 만들 재료를 찾고 있어요.","우물돌은 우물 주변에, 대지열매는 큰 나무 밑에 있대요.","우물돌과 대지열매를 모아 가져다 달래요."},c={"잘만 투문은 재료를 잘 모았다고 칭찬해요.","지금 바로 예언의 물을 끓여 준대요."},nx=772,nt="Rite of Vision"},
[772]={a={"잘만 투문이 예언의 물을 건네줘요.","그 물을 부족의 불 앞에서 마시면 예언이 보인대요.","예언이 보이면 따라가 보라고 해요."},nx=773,nt="Rite of Wisdom"},
[773]={a={"예언자 와이즈러너는 지혜의 의식이 남았다고 해요.","예언의 물을 마신 사람만 선조의 가호를 받을 수 있대요.","썬더 블러프 동쪽 붉은 바위 언덕에서 고대의 영혼을 찾아 달래요."},c={"고대의 영혼은 당신의 노력을 높이 샀대요.","썬더 블러프를 지키는 임무를 당신에게 넘긴대요.","지혜의 의식을 통과했으니 자랑스럽게 들어가라고 해요."},nx=775,nt="Journey into Thunder Bluff"},
[775]={a={"고대의 영혼은 당신이 존경받을 자격이 있다고 해요.","대지모신의 의식을 해낼 만한 능력이 있대요.","썬더 블러프 높은 벼랑의 케른 블러드후프를 찾아가래요."},c={"케른 블러드후프는 집 앞까지 찾아온 걸 반겨요."},nx=776,nt="Rites of the Earthmother"},
[776]={a={"케른 블러드후프는 당신이 썬더 블러프에서 지위를 얻었다고 해요.","지위를 지키려면 사냥 실력을 계속 보여야 한대요.","멀고어의 코도 알라치아를 잡아 뿔을 가져다 달래요."}},
[777]={a={"루시앙 토셀렌치가 기어를 건네주고 있어요.","그는 덮개 뒤에 몸을 숨기겠다고 해요.","기어를 로트윌에게 가져다 달래요."},nx=778,nt="This Is Going to Be Hard"},
[778]={a={"로트윌 베리아투스가 드디어 족쇄를 완성했대요.","이제 강력한 정령을 불러내 보이려 해요.","팜레터 수호정령을 물리치고 족쇄를 가져와 달래요."}},
[780]={a={"동쪽 칼날가시 협곡의 전투멧돼지가 사냥터를 침범했대요.","그 멧돼지들은 뾰족털 가시멧돼지들이 조련시켰대요.","멧돼지를 잡아 주둥이와 갈비살을 가져다 달래요."},c={"그룰 호크윈드는 아주 훌륭하다고 칭찬해요.","이 재료로 좋은 스튜를 만들 수 있대요.","뾰족털일족에게 좋은 교훈이 될 거래요."}},
[781]={a={"지도를 꼼꼼히 살펴보니 뾰족털 대족장의 계획이 있대요.","나라체 야영지를 대대적으로 포위 공격할 계획이래요.","이 정보를 족장 호크윈드에게 가져다 달래요."},c={"족장 호크윈드는 정말 놀랍고 걱정된다고 해요.","블러드후프 마을에 도움을 청해 공격을 막겠대요.","당신 덕분에 많은 타우렌의 목숨을 구했대요."}},
[782]={a={"고른은 호드의 명예를 되찾으려 해요.","토그룬이 배신해 대지의 봉인을 가져가 버렸대요.","보프 야영지에 가서 봉인을 되찾아 오래요."},c={"토그룬이 죽어 오우거들이 혼란에 빠질 거래요.","이제 대지의 봉인으로 레슬로 협곡의 감옥을 열 수 있대요."},nx=793,nt="Broken Alliances"},
[784]={a={"가르톡 말로는 인간들이 우리 땅을 넘보고 있대요.","부대장 베네딕트가 타이라가드 요새를 되찾으려 해요.","남쪽으로 가서 침략자들을 처단해 달래요."},c={"가르톡 말로는 당신의 용기 소문이 빨리 퍼졌대요.","타이라가드 요새에서 거둔 승리가 오그리마에서 칭송받을 거래요."},nx=825,nt="From The Wreckage...."},
[786]={a={"콜카르 켄타우로스들이 서쪽 능선을 넘어 공격해 와요.","트롤과 오크를 노리는 공격 계획을 세웠대요.","병사들과 함께 콜카르 바윗골에 가서 계획서를 없애 달래요."},c={"라르 말로는 이 공격을 막아 전사들의 피를 아꼈대요.","이 어려운 때가 끝나기 전에 피가 더 흐를 거래요.","당신이 사람들을 잘 도왔다고 칭찬해요."}},
[788]={a={"고르넥이 당신의 몸을 풀어줄 일을 맡기려 해요.","불모의 땅은 아직 위험하대요.","북쪽의 점박이멧돼지를 잡아 달래요."},c={"고르넥은 제법 잘했다고 해요.","앞으로는 멧돼지보다 훨씬 강한 적과 싸울 거래요.","그래서 다음 시련에 대비할 보호막이 필요하대요."}},
[789]={a={"고르넥은 전갈 독침에 쓰러지는 사람이 많다고 해요.","그 독으로 만드는 해독약을 미리 준비해 두고 있대요.","북서쪽 일꾼전갈의 꼬리를 가져와 용기를 증명해 달래요."},c={"전갈과 싸우며 얻을 중요한 교훈이 있대요.","작은 적도 크고 강한 적도 당신을 위험에 빠뜨릴 수 있대요.","이제 가르칠 건 없지만 잘했다고 칭찬해요."}},
[790]={a={"하나주아는 골짜기에서 전갈에게 크게 다쳤대요.","사르코스라는 전갈에게 당해 명예를 잃었대요.","남쪽 언덕의 그 전갈을 쓰러뜨려 달래요."},c={"하나주아는 자기가 입힌 상처를 보고 조금 뿌듯해해요.","죽게 되면 그 작은 자부심이 남는 전부래요.","이룬 일이 적다는 생각에 화가 난대요."},nx=804,nt="Sarkoth"},
[791]={a={"펄 스콘브로우는 나이 때문에 전투에서 물러났어요.","지금은 칼바위 언덕 감시탑에서 침략자를 살피고 있어요.","소지품을 담을 가방을 만들려고 천 조각을 부탁해요."},c={"펄 스콘브로우는 이 가방이 전장에서 쓸모 있을 거래요.","호드를 위해 싸우려는 당신의 기개를 높이 산대요."}},
[792]={a={"주리타 파게이즈는 시험의 골짜기에서 나를 지도하러 왔대요.","불타는칼날단이 악마 하수인을 내보내 혼란을 일으키려 해요.","하수인을 많이 처치하고 돌아오래요."},nx=794,nt="Burning Blade Medallion"},
[793]={a={"고른은 레슬로 협곡의 검은 비룡들을 풀어 주려 해요.","봉인을 풀려면 기둥 속 마법석을 빼내야 한대요.","블랙래쉬와 헤마투스를 처치하고 굴레를 가져오래요."},c={"검은 비룡들이 검은바위 오크와 손잡고 있대요.","이제 서쪽 검은바위 첨탑을 노릴 차례래요."}},
[794]={a={"주리타 파게이즈는 점을 쳐서 강한 힘이 숨은 곳을 봤대요.","불타는칼날단 소굴 깊숙이 메달이 있고 흑마법이 지키고 있대요.","메달을 찾아 가져와 달래요."},c={"주리타는 메달을 찾았다고 기뻐하며 칭찬해요.","시험의 골짜기에서 이 무리를 뿌리 뽑는 데 도움이 됐대요.","그들이 우리 땅에서 또 노리는 게 있을까 걱정이래요."},nx=805,nt="Report to Sen'jin Village"},
[804]={a={"하나주아는 당신이 해준 일에 크게 감동했대요.","하지만 혼자서는 동굴 막사로 돌아갈 수 없대요.","고르넥에게 하나주아의 상황을 전해 달래요."},c={"고르넥은 그 짐승이 사르코스라고 알아봤대요.","하나주아에게 바로 도움을 보내겠다고 해요.","사르코스를 쓰러뜨린 건 자랑스러운 일이래요."}},
[805]={a={"시험의 골짜기에서 불타는칼날단 일이 끝났대요.","그 악이 더 큰 위협을 알리는 게 아닐지 걱정이래요.","센진 마을의 장로 가드린에게 이 소식을 전해 달래요."},c={"가드린 말로는 지금은 보고가 좋지 않은 때래요.","센진 마을엔 없지만 메아리 섬에 악이 뿌리내렸대요.","오크를 돕고 싶지만 우리도 도움이 필요하대요."}},
[806]={a={"오르그닐 소울스카는 악이 퍼지기 전에 막으려 해요.","천둥 골짜기에 피즐 다크스톰이라는 고블린 흑마법사가 있대요.","그를 찾아 쓰러뜨리고 발톱을 가져와 달래요."},c={"오르그닐은 해냈다며 반가워해요.","당신 덕에 듀로타에서 악의 세력 하나가 사라졌대요."},nx=828,nt="Margoz"},
[808]={a={"장로 가드린은 꿈에서 형 민시나의 목소리를 들었대요.","형은 잘라제인에게 잡혀 죽었고 영혼은 해골에 갇혔대요.","메아리 섬의 마법진에서 해골을 찾아 가져다 달래요."},c={"가드린은 민시나를 구해 줘서 고맙다고 해요.","형의 영혼을 속박에서 구해 줬대요."}},
[809]={a={"네루 파이어블레이드는 마력이 부른 타락을 연구해 왔대요.","가져온 목걸이를 보고 걱정이 사실이었다고 확인했대요.","씨앗을 부숴야 한다며 아크젤로스를 찾아가래요."},c={"아크젤로스는 네루가 그걸 원한다니 이상하다고 해요.","그래도 씨앗을 없애고 싶다면 방법을 알려 주겠대요."},nx=924,nt="The Demon Seed"},
[812]={a={"리나그는 맹독전갈에 깊이 찔려 독이 퍼지고 있어요.","이대로면 한 시간도 못 버틸 것 같대요.","오그리마의 코간에게 해독약을 받아 와 달래요."},c={"리나그는 목숨을 구해 줘서 고맙다고 해요.","보상을 건네며 여행에 도움이 되길 바란대요.","코간이 더 많은 의식을 시킬 거라며 한숨을 쉬어요."}},
[815]={a={"요리사 토르카는 아침 식사 준비를 깜빡 잊을 뻔했대요.","붉은발톱랩터 알이 있어야 내일 음식을 만들 수 있대요.","메아리 섬에 가서 그 알을 구해 와 달래요."},c={"토르카는 약하지만 덜렁대진 않는다고 해요.","얼른 비키라며 보상을 건네줘요."}},
[816]={a={"미샤 토크렌의 아들 크론이 며칠 전부터 돌아오지 않았어요.","크론은 분노의 강으로 악어 사냥을 떠났대요.","크론의 흔적이라도 찾아 달라고 부탁해요."},c={"미샤는 아들이 죽은 걸 알고 이제야 슬퍼할 수 있대요.","크론에게 주려던 선물이라며 당신에게 건네요.","이제는 차마 볼 수 없다고 해요."}},
[817]={a={"벨린 팡은 듀로타 호랑이 가죽으로 모포와 갑옷을 만든대요.","사람이 늘어 가죽이 모자라대요.","남쪽 섬에 있는 호랑이 가죽을 가져와 달래요."},c={"덕분에 계절이 바뀌어도 사람들이 춥지 않을 거래요.","벨린 팡은 기뻐하며 고맙다고 해요."}},
[818]={a={"보르날은 눈이 나빠져서 연금술에 기대고 있대요.","자격 있는 트롤이나 오크가 없어 제자를 받지 않았대요.","마크루라의 온전한 눈과 붉은톱니게 점액을 구해 달래요."}},
[819]={a={"첸의 빈 술통 한쪽에 꼬리표가 붙어 있어요.","꼬리표에는 첸 스톰스타우트라는 이름이 적혀 있어요.","그 술통을 아는 사람을 찾아 달래요."},c={"드론은 이게 첸 스톰스타우트의 술통이라고 알아봤어요.","첸은 오래전 렉사르와 함께 다녔대요.","오랫동안 소식을 못 들었는데 가져와 줘서 고맙대요."},nx=821,nt="Chen's Empty Keg"},
[821]={a={"드론의 스승이 첸의 양조 비법을 전해 줬대요.","스톰스타우트는 독한 술이라 수고할 가치가 있대요.","불모의 땅 동물들에게서 재료를 구해 달래요."},c={"드론은 이런 술을 다시 만들 줄 몰랐다며 웃어요.","재료를 가져와 준 덕에 옛 추억이 떠올랐대요.","그 추억이 마음을 따뜻하게 한대요."}},
[823]={a={"센진 마을에도 걱정거리가 많다고 장로 가드린이 말해요.","불타는칼날단 소식은 모두에게 나쁜 소식일 거래요.","칼바위 언덕의 오르그닐 소울스카에게 이 일을 알려 달래요."},c={"오르그닐은 무슨 보고냐며 들을 준비를 해요."},nx=806,nt="Dark Storms"},
[824]={a={"마스토크 윌리히스는 속세의 고리회 일원을 알고 있대요.","그 구슬의 뜻은 제네우 생크리만 알 수 있대요.","조람가르 전초기지에 가서 구슬을 보여 달래요."},c={"이 구슬은 아주 불길하대요.","고리회에서 제대로 연구하겠다고 약속했어요."}},
[825]={a={"가르톡의 정찰병이 난파선 소식을 전해 왔어요.","난파선이 타이라가드 요새 동쪽 해안에 남아 있대요.","잔해를 뒤져 얼라이언스가 쓰는 도구를 찾아 달래요."},c={"가르톡은 회수 임무를 잘 해냈다고 칭찬해요.","그 도구는 다음 수송대 편에 오그리마로 보낸대요."}},
[826]={a={"의술사 잘라제인은 동쪽 메아리 섬에 살고 있대요.","그는 트롤을 육지로 보내 사람들을 잡아간대요.","잘라제인과 그를 따르는 트롤들을 쓰러뜨려 달래요."},c={"잘라제인이 사라져서 이제 부족이 편히 잘 수 있대요.","우리 부족이 당신에게 큰 빚을 졌대요.","아프면 뒤에 있는 봄베이를 찾아가 보래요."}},
[827]={a={"마르고즈는 불타는칼날단이 해골 바위굴에 숨어 있다고 해요.","그들은 동굴에서 이글거리는 목걸이로 살을 태운대요.","그 숭배자들을 쓰러뜨리고 목걸이를 모아 달래요."},c={"마르고즈는 이 목걸이 안에 불타는칼날단의 비밀이 있다고 해요.","그 비밀을 꼭 밝혀내겠대요."},nx=829,nt="Neeru Fireblade"},
[828]={a={"주술사 마르고즈가 불타는칼날단의 음모를 알고 있대요.","해골 바위굴에 이교도 무리가 숨어 있다고 했대요.","해골 바위굴에 가기 전에 마르고즈를 만나 보래요."},c={"마르고즈는 듀로타에서 당신의 활약이 전해졌다고 해요.","실력과 명성이 커지고 있대요.","바른 길을 걷는다면 미래가 크게 빛날 거래요."},nx=827,nt="Skull Rock"},
[829]={a={"마르고즈는 이 목걸이가 악마의 도구라고 해요.","그 기원은 주술사의 능력 밖이라 알 수 없대요.","흑마법사인 네루 파이어블레이드에게 가져가 달래요."},c={"네루는 이걸 어디서 구했냐고 묻대요.","마르고즈가 보냈냐고 묻고는 자세히 살펴보겠대요."},nx=809,nt="Ak'Zeloth"},
[830]={a={"낡은 봉투를 열자 공문서가 나와요.","프라우드무어 함장의 인장이 찍혀 있어 중요해 보여요.","칼바위 언덕의 가르톡에게 가져가 보래요."},c={"가르톡은 이건 좋지 않은 징조라고 해요.","이 정보를 알려 준 건 현명했다고 칭찬해요."},nx=831,nt="The Admiral's Orders"},
[831]={a={"가르톡은 인간들을 믿으면 안 된다고 해요.","함장이 죽은 뒤에도 그 계획이 남아 있는 것 같대요.","오그리마 스랄의 요새에 있는 나즈그렐에게 가져가 달래요."},c={"나즈그렐은 대족장에게 인간을 믿지 말라고 여러 번 말했대요.","당신은 호드를 명예롭게 섬겼다고 칭찬해요.","지금 바로 스랄에게 이 일을 의논하러 간대요."}},
[832]={a={"이글거리는 그림자의 눈에서 목소리가 흘러나와요.","가즈우즈에게 해골 바위굴에서 뭔가 찾았냐고 다그쳐요.","이 눈을 네루 파이어블레이드에게 가져가 달래요."},c={"네루는 목소리가 자기 이름을 불렀다며 이상하게 여겨요.","이 눈을 준 무리의 이름이 자기 이름과 비슷하대요.","이 일을 알려 줘서 고맙고 더 연구해 보겠대요."}},
[833]={a={"붉은 바위 언덕은 용맹한 타우렌이 묻히는 신성한 묘지예요.","약탈자 무리가 묘지를 황폐하게 만들고 있대요.","현자 레인토템은 늙어서 직접 못 나서니 당신이 몰아내 달래요."}},
[834]={a={"레즐락은 가즈로의 부하로 듀로타에 왔대요.","마지막 짐마차를 하피들에게 빼앗겼대요.","보급품을 되찾아 레즐락에게 가져다 달래요."},c={"레즐락은 보급품을 되찾아 줘서 좋아해요.","이제 짐 나를 사람만 구하면 일을 다시 할 수 있대요."},nx=835,nt="Securing the Lines"},
[835]={a={"레즐락은 짐마차를 모두 잃을까 봐 직접 나서기로 했대요.","모래바람 협곡의 하피들을 없애면 길이 안전해진대요.","그래서 당신에게 도와 달라고 부탁해요."},c={"이제 하피가 짐마차를 괴롭히지 않아 안심된대요.","레즐락 말로는 톱니항의 두목을 찾아가 보래요.","보수도 꼭 챙겨 준다고 해요."}},
[836]={a={"유도 로봇 OOX-09/HL은 다시 작동하려면 시간이 필요해요.","넓고 안전한 해안에서 긴 이륙 준비를 해야 한대요.","전망대 절벽 너머 해안까지 호위한 뒤 무법항에서 보고해 달래요."},c={"오글소프는 로봇을 구해 줘서 크게 고마워해요.","시간과 제작비를 많이 아꼈다고 해요.","원하는 물건을 골라 가지라고 해요."}},
[837]={a={"일부 땅에는 서슬갈기 가시멧돼지가 아직 버티고 있대요.","가르톡은 서슬갈기일족을 더 둘 수 없다고 해요.","가시덤불이 보이는 서쪽 야영지로 가서 쫓아 달래요."},c={"가시멧돼지가 소굴에서 쫓겨났다고 전해요.","그들의 건물은 불태워도 된대요.","듀로타 국경을 지키는 데 한 걸음 가까워졌대요."}},
[838]={a={"고위집행관 델링턴이 당신이 임무를 잘 해낸다며 맡기래요.","스칼로맨스 문은 올바른 열쇠가 있어야 열린대요.","연금술사 디더스를 찾아가 열쇠 이야기를 나눠 보래요."},nx=964,nt="Skeletal Fragments"},
[840]={a={"타크린 패스시커는 당신이 꽤 강해 보인다고 해요.","그의 친구 카르갈이 불모의 땅에서 일할 신병을 모집한대요.","징병 추천서를 카르갈에게 가져가 서명을 받아 보래요."},c={"카르갈은 타크린이 보낸 사람이냐고 반가워해요.","추천서에 서명해 주겠지만 크로스로드에 사람이 필요하대요."},nx=842,nt="Crossroads Conscription"},
[842]={a={"카르갈은 서명한 추천서를 크로스로드로 가져가라고 해요.","셀그라 다크쏜은 말을 빙빙 돌리는 주술사래요.","그러니 직접 가서 판단해 보래요."},c={"셀그라 다크쏜은 호드에서 할 일이 많다고 해요.","스랄은 여성도 남성과 동등하다고 선언했대요.","그래도 무례하게 굴면 가만두지 않겠대요."}},
[843]={a={"갠 스톤스파이어는 옛 고향이 망가져 슬퍼하고 있어요.","바엘 모단의 드워프들이 우리 땅을 망치고 있대요.","드워프들을 몰아내고 카즈고름의 보고서도 가져다 달래요."},c={"발굴조사단장 카즈고름은 자업자득이라고 해요.","그 죽음이 다른 자들에게 경고가 될 거래요."},nx=846,nt="Revenge of Gann"},
[844]={a={"동쪽 초원타조가 보급 식량을 훔쳐 먹는대요.","당신의 첫 사냥감이라 쉬운 상대래요.","초원타조의 부리를 가져와 달래요."},c={"셀그라는 이제 보급로를 지키기 쉬워졌대요.","다음 상대는 초원타조보다 더 사납대요."},nx=845,nt="The Zhevra"},
[845]={a={"얼룩말은 초원타조보다 조금 더 까다로운 짐승이래요.","셀그라는 강한 상대 전에 얼룩말부터 잡으래요.","북쪽이나 남쪽에서 얼룩말 발굽을 모아 와 달래요."},c={"셀그라는 얼룩말의 다리 힘이 엄청나다고 해요.","타우렌도 주저앉힐 만큼 발차기가 세대요.","당신도 힘이 있으니 진짜 도전을 받을 준비가 됐냐고 물어요."},nx=903,nt="Prowlers of the Barrens"},
[846]={a={"갠 스톤스파이어는 드워프들에게 되갚아 주고 싶어 해요.","드워프들이 폭약으로 땅을 계속 파헤친대요.","요새 병사들에게 재료를 얻어 와 달래요."},c={"아주 부지런하다며 칭찬했어요.","드워프들을 놀라게 할 준비가 곧 끝날 거래요."},nx=849,nt="Revenge of Gann"},
[847]={a={"고르멀은 토건이 보여 준 주술사의 힘에 놀랐어요.","잠시뿐이지만 토건의 말을 들어 보겠대요.","토건에게 크게 감동했다고 전해 달래요."},c={"마법이 풀리면 고르멀과 이야기하겠대요.","고르멀을 산 자의 세계로 돌려보내 줘서 고맙대요."}},
[848]={a={"불모의 땅 오아시스에는 신비한 힘이 흘러나온대요.","그 물을 마신 동식물이 생기를 얻고 바뀌기도 해요.","오아시스 버섯 포자를 헬브림에게 가져다 달래요."},c={"헬브림은 좋은 표본이라며 효능이 강하다고 해요.","약속은 지킨다며 보상을 건네줘요."},nx=853,nt="Apothecary Zamah"},
[849]={a={"갠 스톤스파이어가 폭탄을 완성했대요.","그 비행기는 드워프들의 힘을 상징하는 기계래요.","이 명예로운 임무를 맡아 달래요."},c={"정말 잘했다며 칭찬했어요.","썬더 블러프에서 영웅으로 존경받을 거래요."}},
[850]={a={"렉타르 데스게이트는 켄타우로스에게 오래 시달려 왔어요.","콜카르 켄타우로스가 지도자 밑에 뭉쳐 위협이 커졌대요.","그 지도자를 막아 달라고 부탁해요."},c={"렉타르 데스게이트는 잘했다고 칭찬해요.","켄타우로스는 대개 단순하지만 지도자는 위험하대요.","바라크 코도베인이 죽어서 다행이라고 해요."},nx=851,nt="Verog the Dervish"},
[851]={a={"광신자 베로그는 불모의 땅 곳곳을 떠돌아 찾기 어려워요.","본거지 천막 근처에서 유인할 수 있을지도 모른대요.","위험하지만 그를 끌어내 달라고 부탁해요."},c={"렉타르 데스게이트가 아주 잘했다고 해요.","경비병들이 죽은 오아시스 쪽에서 소란을 봤대요.","아마 당신 덕분일 거라며 용기를 칭찬해요."},nx=852,nt="Hezrul Bloodmark"},
[852]={a={"렉타르 데스게이트가 콜카르 최고 지도자 얘기를 해요.","그가 죽으면 콜카르족이 흩어져 위협이 줄 거래요.","그를 막아 줄 수 있냐고 물어요."},c={"렉타르 데스게이트가 당신을 높이 칭찬해요.","켄타우로스는 규율이 없지만 여전히 사납대요.","그들을 물리쳐 당신의 용기가 증명됐대요."},nx=4021,nt="Counterattack!"},
[853]={a={"연금술사 헬브림이 포자를 유액으로 정제했어요.","이 유액은 효력이 오래 못 가서 서둘러야 한대요.","동료 연금술사 자마에게 가져다 달라고 부탁해요."},c={"자마는 헬브림이 모으던 포자라고 알아봐요.","헬브림이 당신 도움을 받았냐고 물어요.","유액이 아직 효력이 있어 빨리 옮긴 것 같대요."}},
[854]={a={"키르제 스턴혼은 당신이 올 줄 미리 봤대요.","오크들과 얽힌 처지라 도움이 필요하대요.","교차로에 있는 톨크를 찾아가 달라고 해요."},c={"톨크는 썬더 블러프에서도 도우러 와서 반갑대요.","다시 한번 환영한다고 해요."}},
[855]={a={"렉타르 데스게이트는 켄타우로스 무리가 골칫거리래요.","그래서 콜카르 지역에서 할 현상금 임무가 있대요.","콜카르 지역 켄타우로스에게서 팔보호구를 모아 달래요."},c={"렉타르 데스게이트가 솜씨가 좋다고 칭찬해요.","살아남은 켄타우로스가 겁에 질렸을 거래요.","하지만 그들이 물러나지 않을 것 같아 안타깝대요."}},
[857]={a={"추방자 피글리는 장군 트윈브레이드에게 쫓겨났대요.","트윈브레이드가 달의 눈물을 요새 깊이 숨겼대요.","그 달의 눈물을 되찾아 달래요."},c={"드디어 그 힘을 되찾았다며 좋아해요."}},
[858]={a={"위즐크랭크는 벌목기 안에 꼼짝없이 갇혔어요.","열쇠가 필요한 줄 모르고 올라탔대요.","관제탑 꼭대기 관리자에게서 열쇠를 가져와 달래요."},nx=863,nt="The Escape"},
[860]={a={"멜로르 스톤후프가 사냥꾼의 길을 얘기해요.","불모의 땅 야수들은 사나워서 사냥하면 많이 배운대요.","크로스로드의 셀그라 다크쏜을 찾아가 보라고 해요."},c={"셀그라 다크쏜은 당신의 눈빛이 열정적이라고 해요.","사냥은 잡고 죽이는 것만이 아니라고 가르친대요.","이제 여정이 시작된다고 해요."},nx=844,nt="Plainstrider Menace"},
[861]={a={"스코른 화이트클라우드는 당신이 모험을 좋아하는 걸 알아봐요.","타우렌에게 사냥은 최고의 영예라고 해요.","썬더 블러프의 멜로르 스톤후프를 만나 보라고 권해요."},c={"멜로르 스톤후프는 스코른 화이트클라우드를 존경한대요.","스코른 화이트클라우드가 보냈다면 사냥꾼 정신이 있대요.","사냥꾼의 길을 걸을 준비가 된 것 같대요."},nx=860,nt="Sergra Darkthorn"},
[862]={a={"그럽은 배가 고파서 맛있는 스튜를 만들어 주겠대요.","바엘 모단의 드워프들이 들쥐를 다 먹어 치운대요.","남쪽에서 들쥐를 잡아 고기를 가져와 달래요."},c={"보통은 쥐 고기를 잘 안 먹는대요.","배고파 보여서 스튜를 만들어 줬대요."}},
[863]={a={"위즐크랭크는 벌목기를 몰면서 배우려 해요.","버튼과 레버뿐이라 어렵지 않을 거래요.","준비가 되면 함께 가 달라고 부탁해요."},c={"스퍼터밸브는 부서진 벌목기 시제품에서 건질 게 있길 바란대요.","위즐크랭크가 있는 곳으로 회수팀을 바로 보낸대요.","수고했다며 보상도 챙겨 준대요."}},
[864]={a={"선임기술자 빌지위즐이 동력원을 안전하게 빼냈대요.","안에 든 자료는 그대로 남아 있대요.","봉인된 분석 도구를 언더시티의 진게에게 가져다 달래요."},c={"진게는 자료를 바로 분석하겠다고 해요.","당신이 쓸모 있다며 물건과 동전을 줘요.","이 일이 끝나지 않았으니 가끔 들러 달래요."}},
[865]={a={"메보크 미지릭스는 불모의 땅 랩터가 유난히 영리하대요.","뿔을 갈아 음료를 만들어 큰돈을 벌 생각이래요.","온전한 랩터 뿔을 구해다 달라고 부탁해요."},c={"메보크 미지릭스는 뿔을 얻어 기뻐해요.","이제 뿔을 갈아 포도주와 섞으면 된대요."},nx=1491,nt="Smart Drinks"},
[866]={a={"메보크 미지릭스는 불모의 땅 향초가 독특하다고 해요.","오아시스 물 때문인 것 같아 그 차이를 연구하고 싶대요.","약초 채집에 능하면 뿌리 표본을 모아 달래요."},c={"메보크 미지릭스는 표본이 아주 좋다며 기뻐해요.","이 뿌리로 자라게 해서 숨은 쓸모를 찾아보겠대요.","찾으면 제일 먼저 알려 주고 또 부탁하겠대요."}},
[867]={a={"달소크 스위프트대거는 하피들이 보급품을 오래 습격했대요.","이제 하피들의 숨통을 조여야 할 때래요.","북서쪽 하피 무리를 상대해 달라고 해요."},c={"달소크 스위프트대거는 가져온 것이 아주 마음에 든대요.","앞으로도 당신의 일을 기대한대요."},nx=875,nt="Harpy Lieutenants"},
[868]={a={"코란은 오그리마에서 크로스로드로 파견됐어요.","거인의 들판에 사는 벌레 같은 생물은 지능이 높은 듯해요.","발각되지 않게 언덕에서 알을 모아 달래요."},c={"알과 도구를 가져와서 아주 기뻐해요.","잘했다며 보상을 주겠대요."}},
[869]={a={"가즈록은 경비탑에서 은을 도둑맞았대요.","잡힌 도둑이 랩터였다니 가즈록이 놀랐어요.","앞으로 도둑질 못 하게 랩터들을 없애 달래요."},c={"가즈록은 랩터들을 없애 줘서 고맙대요.","당신은 쓸모 있는 사람이라고 칭찬해요."},nx=3281,nt="Stolen Silver"},
[870]={a={"통가 룬토템은 불모의 땅에 새 오아시스가 생겼다고 해요.","드루이드들이 땅속에서 솟는 힘을 어렴풋이 느꼈대요.","그 힘의 근원을 찾아 와 달라고 부탁해요."},c={"통가 룬토템은 땅이 갈라져 가스가 나온다니 이상하대요.","우리 질문의 답일지도 모르지만 아직 확신은 없대요.","그래도 단서라서 찾아 줘 고맙다고 해요."},nx=877,nt="The Stagnant Oasis"},
[871]={a={"톨크는 서슬갈기일족이 보급로를 계속 공격한대요.","지휘관이 누군지 정찰병이 알아보는 중이래요.","듀로타 쪽에서 그들을 손봐 달래요."},c={"톨크는 잘했다며 칭찬해요.","건방진 가시멧돼지들도 이제 호드의 힘을 알 거래요."},nx=872,nt="The Disruption Ends"},
[872]={a={"톨크의 정찰병이 듀로타 짐마차 습격을 목격했대요.","범인은 서슬갈기일족이고 크리니그 스날스나웃이 이끈대요.","그를 쓰러뜨려 달라고 부탁해요."},c={"톨크는 잘했다고 칭찬해요.","크리니그가 죽었으니 짐마차 습격이 크게 줄 거래요.","당신 같은 사람을 둬서 호드가 자랑스러울 거래요."}},
[873]={a={"마렌 스카이시어는 이샤 아와크를 두려워하지 않아요.","이샤 아와크는 해안의 지배자라서 사람들이 무서워해요.","바다로 헤엄쳐 가서 그를 찾아보래요."},c={"이제 이샤 아와크와 하나가 됐대요.","언젠가 볼 줄 아는 눈이 될 거래요."}},
[874]={a={"조른 스카이시어는 사냥꾼이라면 어디든 쫓아가야 한대요.","누이 마렌 스카이시어는 해안에서 물짐승을 사냥해요.","그러니 해안을 조심해서 마렌을 찾아가 보래요."},c={"조른 스카이시어가 보냈냐고 물어요.","사냥꾼의 길을 더 걸을 준비가 됐냐고 해요."},nx=873,nt="Isha Awak"},
[875]={a={"달소크 스위프트대거가 다시 찾아온 당신을 반겨요.","메마른 언덕의 하피 부대장들이 조무래기를 이끈대요.","그들을 혼내서 호드에 대든 대가를 알려 달래요."},c={"달소크 스위프트대거는 훌륭한 솜씨라며 기뻐해요.","호드에서 크게 성공할 것 같대요."},nx=876,nt="Serena Bloodfeather"},
[876]={a={"달소크 스위프트대거는 하피들이 호드 짐마차를 공격한다고 해요.","붉은깃털 세레나는 렉사르가 처치한 블러드페더의 자매래요.","세레나를 처치하고 증거를 가져다 달래요."},c={"잘했다며 기뻐하고 보상을 주겠대요.","하피 소동을 잠재워 줘서 고맙대요."},nx=1060,nt="Letter to Jin'Zil"},
[877]={a={"통가 룬토템은 다른 오아시스에도 틈이 있을지 궁금해해요.","틈이 오아시스 생명의 근원인지 시험해 보고 싶대요.","죽은 씨앗을 죽은 오아시스에 심어 보고 알려 달래요."},c={"통가 룬토템은 발견이 놀랍다고 감탄해요.","오아시스 아래 무언가가 생명을 만들 수 있대요.","더 연구해 봐야 한다고 해요."},nx=880,nt="Altered Beings"},
[878]={a={"뻐드렁니는 서슬갈기일족의 편에 서 있어요.","서슬갈기와 뾰족털 모두 땅의 힘을 쓰는 부족이래요.","북쪽의 뾰족털 정신적 지도자들을 처치해 달래요."},c={"뻐드렁니는 부족을 도왔는데 버림받았대요.","감옥에 갇힌 채 아무도 구하러 오지 않았대요."},nx=5052,nt="Blood Shards of Agamaggan"},
[879]={a={"뻐드렁니의 일족 몇이 습격을 이끌고 있대요.","그들은 잔인하고 교활해서 평화를 깨뜨린대요.","나크, 쿠즈, 로크 오크베인을 처치해 달래요."},c={"이렇게 끝나는 게 차라리 낫대요.","뻐드렁니를 버린 자들이 원망스러운 것 같아요."},nx=906,nt="Betrayal from Within"},
[880]={a={"통가 룬토템은 당신이 찾은 것이 정말 놀랍대요.","틈이 오아시스 물을 마시는 짐승에게 어떤 영향을 줄지 알고 싶대요.","무쇠턱거북의 등껍질을 가져다 달라고 부탁해요."},c={"통가 룬토템은 고맙다고 해요.","짐승을 살피면 그 지역에 대해 많이 알 수 있대요.","필요 없으니 이 동전을 쓰라고 줘요."}},
[881]={a={"셀그라 다크쏜은 사바나 사자 무리의 왕 얘기를 해요.","그 왕 에체야키는 몰래 다가와 빠르게 사냥한대요.","그를 뿔피리로 불러내 상대해 보라고 해요."},c={"셀그라 다크쏜은 에체야키를 이긴 걸 칭찬해요.","사냥은 끝났지만 그의 정신이 당신 곁에 남았대요.","아직 갈 길이 머니 잘 걸어가라고 해요."},nx=905,nt="The Angry Scytheclaws"},
[882]={a={"조른 스카이시어가 가장 사나운 랩터 얘기를 해요.","이샤무헤일은 사냥 자체가 좋아서 사냥한대요.","그 랩터를 쫓아 사냥을 떠나 보라고 해요."},c={"조른 스카이시어는 이 송곳니가 작은 증표지만 뜻은 깊대요.","이샤무헤일의 힘이 당신에게 있다고 해요.","그 힘을 절제해서 쓰라고 당부해요."},nx=907,nt="Enraged Thunder Lizards"},
[886]={a={"대드루이드 하뮬 룬토템은 이상한 기운이 흘러든다고 해요.","그 근원을 찾으러 보낸 통가 룬토템에게 도움이 필요하대요.","불모의 땅 크로스로드에 있는 통가를 찾아가 달래요."},c={"통가 룬토템은 썬더 블러프 동료들이 당신을 보낸 게 현명했대요.","혼자서는 이 수수께끼를 풀 수 없었대요.","당신의 도움으로 답을 찾길 바란대요."},nx=870,nt="The Forgotten Pools"},
[887]={a={"가즈로는 교역선 걱정에 마음이 편하지 않대요.","남쪽바다 해적단이 바로 남쪽에 기지를 세웠대요.","그레즐릭 부제독이 안 한다면 당신이 도와줄 수 있냐고 물어요."},c={"가즈로는 잘했다고 해요.","해적들이 다른 데로 떠나면 좋겠대요.","이제 도둑맞은 물건도 찾아야 한대요."},nx=890,nt="The Missing Shipment"},
[888]={a={"가즈로는 해적에게 뺏긴 물건을 되찾고 싶대요.","관측소를 돌리려면 작은 렌즈가 더 필요하대요.","해적 야영지에서 장화와 렌즈를 찾아 달래요."},c={"가즈로는 물건을 되찾아서 한시름 놨대요.","당신 같은 사람이 일을 도와주면 좋겠대요.","일이 필요하면 보수를 잘 준다는 걸 기억하래요."}},
[890]={a={"가즈로는 무법항에서 보낸 뱃짐을 오래 기다리고 있어요.","해적이 가로챈 것 같지만 혹시 몰라 확인하려 해요.","부두주임 디지위그에게 장부를 전해 달라고 부탁해요."},c={"부두주임 디지위그는 가즈로가 보냈냐며 기록을 살펴봐요.","가즈로의 뱃짐을 엉뚱한 데 보내지 않았는지 확인해요.","아마 드리즐릭의 장화를 기다리고 있을 거래요."},nx=892,nt="The Missing Shipment"},
[891]={a={"선장 탈로타스 브라이트썬의 함대가 피해를 입었대요.","그들은 헛된 망상에 빠져 보이는 건 다 쏜대요.","무역 해안을 따라 가서 그들의 휘장을 모아 와 달래요."},c={"얼라이언스의 대포 소리가 멈췄대요.","이제 죽은 자들의 시신을 거두는 일만 남았대요."}},
[892]={a={"부두주임 디지위그가 기록을 꼼꼼히 확인했대요.","잘못 보낸 짐은 없고 해적이 가로챈 것 같대요.","가즈로에게 이 소식을 전해 달라고 부탁해요."},c={"가즈로는 해적 짓이었을 거라고 해요.","디지위그는 믿을 만해서 속이지 않았을 거래요.","그럼 되찾을 물건이 있으니 같이 어떠냐고 물어요."},nx=888,nt="Stolen Booty"},
[893]={a={"테터낵 스틸포지는 서슬갈기일족의 무기에 관심이 많아요.","서슬갈기일족이 최근 꽤 괜찮은 무기를 만들기 시작했대요.","정찰꾼, 점쟁이, 광전사의 무기를 구해 와 달래요."},c={"정말 훌륭한 무기들이라며 감탄했어요.","적을 얕보면 안 된다고 했어요."},nx=1153,nt="A New Ore Sample"},
[894]={a={"스퍼터밸브는 투자개발회사가 북쪽에 연구 시설을 세웠대요.","거기서 사모플랜지라는 걸 실험하는데 정체를 모른대요.","그걸 구해다 달라고 부탁해요."},c={"제어 장치에는 버튼과 레버, 깜빡이는 불빛이 어지러워요.","장치는 정상 범위에서 돌아가고 밸브들이 열려 있어요.","제어판 오른쪽 아래에는 작은 열쇠 구멍이 있어요."},nx=900,nt="Samophlange"},
[895]={a={"가즈로가 현상수배 공고를 냈어요.","롱쇼어 남작은 남쪽바다 해적단 함대를 이끈대요.","신원을 알아볼 증거를 가져오래요."}},
[896]={a={"부두주임 디지위그는 항구의 소식을 죄다 안대요.","진흙늪 북동쪽 광산에서 주먹만 한 에메랄드가 나왔대요.","그걸 팔아 이익을 반반 나누자고 해요."},c={"디지위그는 에메랄드가 엄청 크다며 좋아해요.","반반씩 나눌 테니 걱정 말래요.","거래해서 기분 좋다고 해요."}},
[897]={a={"벌레처럼 생긴 이 생명체는 자연에 속하지 않아 보여요.","불모의 땅의 생태계에도 속하지 않는대요.","조른 스카이시어에게 이걸 전해 달래요."},c={"이 짐승의 정체는 알 수 없대요.","불길한 앞날을 예고하는 것 같아 걱정이래요."}},
[898]={a={"길사레즈 파이어바우는 테라모어 사람들에게 갇혀 있었어요.","그는 밀주를 나르던 선원일 뿐이라고 억울해해요.","톱니항으로 무사히 돌아가게 도와 달래요."}},
[899]={a={"만크릭은 매일 해가 질 때까지 야수를 찾아다녀요.","뾰족털 가시멧돼지를 처치해도 성이 차지 않는대요.","많이 처치하고 어금니를 가져다 달래요."},c={"내 부탁을 진지하게 들어줘서 고맙대요.","가시멧돼지도 아파 보니 조금은 웃음이 난대요."}},
[900]={a={"제어 장치는 밸브들이 열린 채 돌아가고 있대요.","눈금을 보니 밸브를 다 잠가야 끌 수 있을 것 같대요.","연료 제어 밸브와 압력 조절 밸브를 잠가 달래요."},c={"밸브가 잠기자 불빛이 점점 흐려져요.","이제 스위치를 돌려 장치를 끌 수 있대요."},nx=901,nt="Samophlange"},
[901]={a={"제어 장치가 완전히 꺼져서 제어판을 열 수 있대요.","이제 사모플랜지를 꺼내려면 열쇠만 있으면 된대요.","땜장이 스니글즈에게 열쇠를 구해 달라고 해요."},c={"열쇠를 돌리자 제어 장치의 잠금이 풀려요.","위쪽 빨간 불이 꺼지고 전원이 모두 빠져나가요."},nx=902,nt="Samophlange"},
[902]={a={"제어 장치의 덮개를 열자 전선과 관이 얽혀 있어요.","쓸데없어 보이는 부품들 사이에서 사모플랜지를 꺼내야 해요.","그걸 톱니항의 스퍼터밸브에게 가져다 달라고 해요."},c={"스퍼터밸브는 사모플랜지가 좀 흥미롭다고 해요.","다른 곳에 보내 분해하고 연구하게 한대요.","그 전에 자기도 한번 살펴본대요."},nx=3921,nt="Wenikee Boltbucket"},
[903]={a={"셀그라 다크쏜은 이제 센 사자들을 상대할 때래요.","굶주린 사자들은 강하고 교활해서 조심해야 한대요.","크로스로드 남서쪽 풀숲에서 사자를 찾아가래요."},c={"셀그라 다크쏜은 당신이 열심히 사냥했다고 해요.","이제 그중 가장 강한 놈과 맞설 때라고 해요."},nx=881,nt="Echeyakee"},
[905]={a={"셀그라 다크쏜은 사냥이 점점 깊어진다고 해요.","이번엔 열대초원랩터의 소굴까지 들어가야 한대요.","랩터 무리에게 두려워하지 않는다는 걸 보여 달래요."},c={"셀그라 다크쏜은 일을 끝냈냐고 물어요.","죽이는 짐승들의 목숨도 생각해 보래요.","이런 살육은 해결보다 문제를 더 키울 거래요."},nx=3261,nt="Jorn Skyseer"},
[906]={a={"감옥에 갇혀서도 축복을 빌어 주겠대요.","해골을 보면 톨크가 일족의 일을 알 거래요.","크로스로드의 톨크에게 이 해골을 가져다 달래요."},c={"로크를 직접 처치했다니 놀랍대요.","크로스로드 사람들은 그 힘을 존중하는 게 좋대요."}},
[907]={a={"조른 스카이시어는 거대한 천둥도마뱀 얘기를 꺼내요.","걸을 때마다 땅이 울릴 만큼 몸집이 커서 조심해야 해요.","남쪽 천둥도마뱀을 물리치고 돌아와 달라고 해요."},c={"조른 스카이시어는 승리의 증거를 가져와 기쁘대요.","뼈도 다치지 않고 돌아와서 다행이래요."},nx=913,nt="Cry of the Thunderhawk"},
[912]={a={"가루바위 트로그 진영을 오래 연구해 온 이가 있어요.","그 지식을 정리해 뒀는데 진영을 뚫을 사람이 필요해요.","용감하게 진영을 뚫고 큰 피해를 줘 보라고 권해요."}},
[913]={a={"조른 스카이시어는 이제 천둥매를 상대할 때라고 해요.","천둥매는 사나운 야수래요.","천둥매를 찾아 날개를 증거로 가져다 달래요."},c={"이제 떠날 때가 됐다고 해요.","진정한 사냥꾼은 자랑스럽게 길을 계속 걷는대요."},nx=874,nt="Mahren Skyseer"},
[914]={a={"나라 와일드메인은 꿈에 나오는 얼굴 때문에 괴로워해요.","송곳니의 드루이드들이 비뚤어진 야망으로 땅을 바꾸려 해요.","지도자들을 처치하고 꿈의 보석을 가져다 달래요."},c={"지도자들을 처치해 줘서 정말 고맙대요.","이제 그들의 얼굴이 꿈에 나오지 않는대요."}},
[924]={a={"아크젤로스는 불타는 군단의 강력한 도구에 대해 말해요.","씨앗은 공포의 안개봉우리 동굴에 놓여 있대요.","마법석으로 씨앗과의 연결을 끊어 달래요."},c={"아크젤로스는 악마의 씨앗이 파괴됐다고 알려요.","씨앗이 부서지며 강한 힘의 파동이 퍼졌대요.","Neeru가 보수를 보내며 고맙다고 전했대요."}},
[959]={a={"기중기 기사 비글퍼즈가 짐을 부리다 사고가 났대요.","광기의 매글리시가 오래 묵은 포트 와인을 훔쳐 달아났대요.","통곡의 동굴에 가서 와인을 되찾아 달래요."},c={"비글퍼즈는 하마터면 일자리를 잃을 뻔했대요.","와인은 가즈로에게 바로 선물하겠대요.","잘했다고 칭찬해요."}},
[962]={a={"연금술사 자마는 언더시티의 왕립 연금술 학회에서 왔어요.","불뱀꽃은 통곡의 동굴 가장 깊은 곳에서만 자라요.","그 불뱀꽃을 구해 달라고 부탁해요."},c={"자마는 표본이 훌륭하다며 잘했다고 해요."}},
[964]={a={"연금술사 디더스가 해골 열쇠를 만들려고 해요.","열쇠에는 해골에서 얻은 뼈조각이 필요하대요.","안돌할 안팎의 해골에서 뼈조각을 모아 달래요."},c={"디더스는 뼈조각을 열쇠 재료로 쓸 수 있다고 해요.","다음으로 거푸집이 필요하고 타나리스에 아는 대장장이가 있대요.","그는 값을 가장 많이 주는 쪽에 일한대요."},nx=5514,nt="Mold Rhymes With..."},
[969]={a={"의술사 마우아리가 행운의 부적을 만들어 준대요.","부적을 만들려면 서리망치거인 조각이 필요하대요.","남쪽 얼음 거인에게서 조각을 가져다 달래요."},c={"마우아리가 지금 부적을 만들어 주겠대요.","잠깐만 기다리라고 해요."},nx=975,nt="Cache of Mau'ari"},
[974]={a={"크래클은 온천의 열이 어디서 오는지 궁금해해요.","불기둥 마루의 화산 온도를 재려고 해요.","가장 뜨거운 곳을 찾아 온도를 재 달래요."},c={"크래클은 화산 온도와 온천 사이 관계가 보인대요.","계산을 다시 확인해 봐야겠다고 해요."},nx=980,nt="The New Springs"},
[975]={a={"의술사 마우아리가 특별한 부적을 만들어 주려고 해요.","부적을 지니면 사냥감이 특별한 물건을 떨어뜨린대요.","그 물건은 에코라고 하니 찾으면 가져다 달래요."},c={"의술사 마우아리가 부적을 건네며 늘 지니라고 해요.","이제 여명의 설원에 돌아가 무엇을 찾는지 보래요."}},
[977]={a={"우미 럼플스니커가 기계설인의 부품을 덮으려고 해요.","얼음엉겅퀴 설인의 큰 뿔이면 딱 맞겠대요.","부러지지 않은 좋은 뿔을 가져다 달래요."},nx=5163,nt="Are We There, Yeti?"},
[980]={a={"크래클은 북쪽 여명의 설원에도 온천이 있대요.","그런데 근처에 화산이 없어서 이상하대요.","여명의 설원에 가서 도노바 스노우덴과 얘기해 달래요."},c={"도노바가 크래클의 말이 사실이라고 해요."},nx=4842,nt="Strange Sources"},
[992]={a={"가젯잔 수자원개발회사의 선임측량사 피즐도저예요.","유목민들이 우물을 차지해 새 물을 찾아야 한대요.","슬픈모래 감시탑 근처 웅덩이에서 물 견본을 받아 와 달래요."},c={"피즐도저는 벌레 괴물에게 습격당했다니 큰일이래요.","사막의 물을 빨아들이는 괴물 보고가 있었대요.","처음엔 유목민의 장난인 줄 알았대요."},nx=82,nt="Noxious Lair Investigation"},
[1000]={a={"포고꾼 윈드스트라이더가 세나리온 의회 소식을 전해요.","칼림도어의 위험한 미개척지를 탐험할 사람을 찾는대요.","대드루이드 하뮬 룬토템을 찾아가 보래요."},c={"대드루이드 하뮬 룬토템은 당신의 명성을 들었대요.","당신을 보니 의회가 도움을 받을 거라 믿음이 생긴대요.","종족을 가리지 않고 함께 일하면 잘될 거래요."},nx=1123,nt="Rabine Saturna"},
[1004]={a={"선구자 발타자드가 세나리온 의회 소식을 전해요.","칼림도어의 위험한 미개척지를 탐험할 사람을 찾는대요.","대드루이드 하뮬 룬토템을 찾아가 보래요."},nx=1123,nt="Rabine Saturna"},
[1013]={a={"관리인 벨두거는 우르의 책을 모으고 싶어 해요.","우르는 스컬지가 오기 전 달라란의 가장 훌륭한 마법사였대요.","그림자송곳니 성채에서 그 책을 찾아 가져다 달래요."},c={"이 책은 소장품에 좋은 보탬이 된대요.","우르는 양심 때문에 진짜 힘을 얻지 못했대요."}},
[1014]={a={"아루갈이 아직 그림자송곳니 성채에 살고 있대요.","아루갈이 있는 한 은빛소나무 숲을 차지할 수 없대요.","아루갈을 처치하고 머리카락을 증거로 가져다 달래요."},c={"은빛소나무 숲이 드디어 자유로워졌대요.","끈기 있게 해낸 공에 보상을 준대요."}},
[1018]={a={"징집관 고를라취가 세나리온 의회 소식을 전해요.","칼림도어의 위험한 미개척지를 탐험할 사람을 찾는대요.","대드루이드 하뮬 룬토템을 찾아가 보래요."},c={"대드루이드 하뮬 룬토템은 당신의 명성을 들었대요.","당신을 보니 의회가 도움을 받을 거라 믿음이 생긴대요.","종족을 가리지 않고 함께 일하면 잘될 거래요."},nx=1123,nt="Rabine Saturna"},
[1036]={a={"\"꽃미남\" 던컨이 당신 얘기를 들었대요.","함장 피랠론이 특별 임무를 맡길 사람을 찾는대요.","주홍빛 장막호에 가서 함장과 얘기해 보래요."},nx=4621,nt="Avast Ye, Admiral!"},
[1048]={a={"바리마트라스는 붉은십자군 때문에 골치가 아파요.","붉은십자군이 티리스팔 숲을 어지럽히고 있대요.","종교재판관 화이트메인과 부관들을 처치해 달래요."},c={"바리마트라스가 어둠의 여왕을 잘 섬겼다고 칭찬해요.","쉽지 않은 일이었는데 잘 해냈대요.","당신의 끈기는 오래 기억될 거래요."}},
[1049]={a={"현자 트루스시커는 포세이큰과 맺은 동맹을 걱정해요.","포세이큰은 속임수가 많은 역사를 가졌대요.","붉은십자군 수도원에서 타락의 개요를 찾아 달래요."},c={"책이 정말 있었다며 반가워해요.","썬더 블러프를 위해 큰 도움을 줬대요."}},
[1051]={a={"보렐 센구츠는 심문관 비샤스에게 고문을 당했대요.","비샤스가 보렐의 결혼 반지를 빼앗아 자기 아내에게 줬대요.","낸시를 처치하고 반지를 모니카에게 돌려 달래요."},c={"보렐 센구츠는 이제 떠났대요.","그를 대신해 복수해 줘서 고맙대요."}},
[1058]={a={"의술사 진질은 갇혀 있는 엘프들을 보고 신나 해요.","엘프들에게 숲의 마법을 맛보여 주고 싶대요.","그러려면 재료가 필요하니 돌발톱 봉우리에서 구해 달래요."}},
[1060]={a={"의술사 진질은 달소크 스위프트대거의 오랜 벗이래요.","하피들은 원래 불모의 땅이 아닌 돌발톱 산맥에서 왔대요.","위험하지만 이 편지를 진질에게 전해 달래요."},c={"달소크 스위프트대거의 편지라 반가워해요.","붉은깃털 세레나가 죽어서 좋은 소식이래요."}},
[1061]={a={"조르 론트리는 돌발톱 산맥의 정령들이 화났다고 해요.","고블린들이 땅을 약탈하고 불태워서 땅이 울부짖어요.","호드 주술사 시리스 스톤브레이크를 만나 달래요."},c={"시리스는 당신을 보고 좋다며 반가워해요.","약탈하는 고블린들을 막을 실력이 필요하대요."},nx=1062,nt="Goblin Invaders"},
[1062]={a={"시리스 스톤브레이크는 고블린 투자개발회사 문제를 알려요.","회사가 나무를 베고 숲을 태워서 정령들이 괴로워한대요.","그들을 막고 호드의 힘을 보여 달래요."},c={"시리스는 용감했다며 칭찬해요.","정령들을 달래려면 타우렌 원로의 지혜가 필요할 수도 있대요.","투자개발회사 사람들을 몰아낸 건 좋은 첫걸음이래요."}},
[1063]={a={"시리스 스톤브레이크는 돌발톱 산맥의 정령을 지키려 해요.","마가타 그림토템은 나이 많고 지혜로운 족장이래요.","썬더 블러프의 마가타에게 산맥의 위험을 전해 달래요."},c={"마가타는 인사하며 조언을 구하러 왔냐고 물어요."},nx=1064,nt="Forsaken Aid"},
[1064]={a={"마가타 그림토템은 돌발톱 산맥의 상황이 마음 아프대요.","땅을 치유하려면 먼저 퍼진 질병을 없애야 한대요.","포세이큰의 연금술사 자마에게 도움을 구하래요."},c={"마가타가 미리 소식을 전했다며 반겨요.","포세이큰도 돌발톱 산맥을 돕고 싶어 한대요."},nx=1065,nt="Journey to Tarren Mill"},
[1065]={a={"연금술사 자마는 투자개발회사를 몰아낼 방법을 찾고 있어요.","동료 라이던이 그 일에 알맞은 도구를 가졌대요.","자마의 쪽지를 타렌 밀농장의 라이던에게 전해 달래요."},c={"라이던은 먼 곳에서 쪽지를 보낸 걸 보니 급한 일인가 봐요.","라이던은 무엇을 해야 할지 알겠다며 기뻐해요."},nx=1066,nt="Blood of Innocents"},
[1066]={a={"연금술사 라이던은 투자개발회사를 순하게 만들 독약을 만들려 해요.","독약을 만들려면 순결한 피가 필요한데 구하기 어렵대요.","던홀드 요새의 비밀결사대에게서 구해 달래요."},c={"비밀결사대가 힘든 일을 대신 해 줬대요.","이제 조제하는 동안 잠시 기다려 달래요."},nx=1067,nt="Return to Thunder Bluff"},
[1067]={a={"연금술사 라이던이 독약을 완성했대요.","투자개발회사에 쓰면 좋은 결과가 날 거래요.","쓰기 전에 연금술사 자마에게 먼저 보여 달래요."},c={"라이던이 만든 독약이라니 아주 좋대요.","투자개발회사에 아주 효과가 좋을 거래요."},nx=1086,nt="The Flying Machine Airport"},
[1068]={a={"시리스 스톤브레이크는 정령의 목소리를 듣는 주술사예요.","칼바람 바위산에서 사람 모양의 기계들이 나무를 쓰러뜨렸대요.","그 기계들을 꼭 부숴 달래요."},c={"기계가 사라져 정령들이 많이 진정됐대요.","투자개발회사가 이 산을 떠나기를 바란대요."}},
[1069]={a={"무법항에서 거미 알 오믈렛이 새로 유행하고 있대요.","거미 알이 부족한 걸 기회로 삼으려 한대요.","칼바람 바위산에서 동굴이끼거미 알을 모아 달래요."},c={"알을 가져와서 정말 고맙대요.","덕분에 이 거래를 성사시킬 수 있었대요."}},
[1086]={a={"연금술사 자마가 독가스통을 다 만들었어요.","투자개발회사에 작은 비행장이 있을 것 같대요.","그 비행장을 찾아 독가스통을 놓고 와 달래요."},c={"비행장을 찾았군요! 고블린들이 꽤 놀랐을 거래요.","독가스가 그들 본부까지 퍼지길 바란대요.","그들은 더 나쁜 짓도 했으니 죄책감은 버리래요."}},
[1087]={a={"브랠린 파이어핸드는 이 땅이 정말 싫대요.","나이트 엘프 드루이드들이 마법의 흐름을 막고 있대요.","그들을 처치하는 일을 도와 달래요."},c={"마법의 힘이 몸을 타고 흐르는 게 느껴진대요.","나이트 엘프는 이 힘을 거절하다니 어리석대요."},nx=1088,nt="Ordanus"},
[1088]={a={"브랠린 파이어핸드는 마법의 눈으로 오르다누스를 찾았대요.","그가 나무 꼭대기에서 이미 다른 곳으로 옮겼대요.","오르다누스의 머리 장식을 가져다 달래요."},c={"오르다누스는 예전에 잘난 척이 심했대요.","이제는 머리도 높이 들지 못하게 됐네요.","약속한 보상을 준대요."},nx=1089,nt="The Den"},
[1089]={a={"드루이드들이 돌발톱 봉우리에 갈퀴발톱굴을 지었대요.","강한 마력이 담긴 물건을 많이 보관해 뒀대요.","굴 입구 등불 속 문지기의 열쇠를 찾아 달래요."},c={"열쇠를 꽂자 빛 속에서 물건들이 나타났대요."}},
[1090]={a={"피즈닉은 한때 여기서 2인자였대요.","게렌조가 온 뒤로 광산으로 쫓겨났대요.","그가 광석 표본을 구할 동안 망을 봐 달래요."},c={"표본을 구해서 다행이에요. 주목을 받았을지도 몰라요.","이제 지즈 피직스에게 빨리 가져가야 해요."},nx=1092,nt="Gerenzo's Orders"},
[1092]={a={"피즈닉은 이제 여기서 빠져나갈 생각이래요.","여기서 벌어진 일이 곧 윗선에 알려질 거래요.","광석 표본을 지즈 피직스에게 가져가 달래요."},c={"피즈닉을 남기길 잘했다고 하네요.","Undermine의 기술자들이 이 광석에 관심이 많을 거래요.","자기 몫도 조금 챙길 생각이래요."}},
[1093]={a={"지즈 피직스는 스퍼터밸브에게 고용됐대요.","투자개발회사가 거대한 벌목 기계를 만들었대요.","슈퍼 절단기 6000 설계도를 훔쳐 달래요."},c={"이게 그 설계도군요! 좋아요.","노움의 생각은 도저히 이해가 안 된대요."},nx=1094,nt="Further Instructions"},
[1094]={a={"지즈 피직스가 해고되기 전에 정보를 모았대요.","봉투에 내부 문서와 기술 자료가 들었대요.","불모의 땅 톱니항의 스퍼터밸브에게 전해 달래요."},c={"지즈 피직스는 믿기 어렵지만 정보는 쓸 만하대요.","투자개발회사가 만든 개량품을 우리도 써 왔대요."},nx=1095,nt="Further Instructions"},
[1095]={a={"스퍼터밸브는 게렌조 때문에 걱정이 많대요.","교역 군주들은 라즈덩크와 게렌조의 관계를 싫어한대요.","게렌조를 처치하라는 명령을 지즈 피직스에게 전해 달래요."},c={"게렌조를 처치한다니 저도 찬성이에요.","게렌조는 놈리건에서 비밀 연구를 맡았던 기술자래요.","그 연구는 실패해서 폭발해 버렸대요."},nx=1096,nt="Gerenzo Wrenchwhistle"},
[1096]={a={"지즈 피직스는 게렌조를 만난 적이 있대요.","게렌조는 몸에 기계를 이식했고 팔다리 일부도 기계래요.","그를 처치해 주면 넉넉히 사례하겠대요."},c={"기계팔을 보니 노움다운 발상이네요.","이제 게렌조는 활동을 못 하게 됐네요."}},
[1098]={a={"고위집행관 하드렉이 그림자송곳니 성채 공격을 준비해요.","정보를 모으러 간 죽음의추적자들이 여러 날째 소식이 없대요.","죽음의추적자 아다만트와 빈센트를 찾아 달래요."},c={"빈센트는 쓰러진 채 숨이 끊겼대요.","아다만트가 보고서를 하드렉에게 보낸대요.","빈센트 손에는 작은 장신구가 쥐어져 있었대요."}},
[1102]={a={"아울드 스톤스파이어는 조상의 땅에서 쫓겨난 일을 용서 못 해요.","타우렌은 불모의 땅 남부에서 살다 쫓겨났대요.","서슬깃 차를가의 심장을 가져다 달래요."},c={"가시덩굴 우리의 그 무리도 이제 고통을 알게 됐네요.","사악한 짐승들은 벌을 받아 마땅하대요.","복수를 도와줘서 고맙대요."}},
[1104]={a={"피즐 브라스볼츠는 로켓 자동차 연구에 빠져 있어요.","새 연료에 쓸 특별한 재료가 필요하대요.","소금 평원의 전갈 독을 구해 달래요."},c={"이 독이면 잘 될 것 같대요. 고마워요!","그런데 연구 노트가 어디 갔는지 모르겠대요."},nx=1106,nt="Martek the Exiled"},
[1105]={a={"위즐 브라스볼츠는 형 피즐의 연료가 걱정돼요.","연료가 너무 강해 탱크를 튼튼히 하고 싶대요.","단단한 거북 등껍질을 가져다 달래요."}},
[1106]={a={"피즐 브라스볼츠가 새 자동차 엔진을 만들고 있어요.","피스톤이 강도가 약해 번번이 실패했대요.","황야의 땅에 있는 망명자 마르텍에게 편지를 전해 달래요."},c={"피즐이 보냈다니 도와줄게요.","피즐은 강한 피스톤을 원하는군요.","피즐의 차는 바퀴 달린 화산이 되겠네요."},nx=1108,nt="Indurium"},
[1107]={a={"위즐 브라스볼츠의 로켓 자동차는 너무 빨라 위험해요.","마찰에 부서지지 않도록 합성물을 만들려 해요.","썩은내 산호초의 딱딱한 꼬리 지느러미를 구해 달래요."},c={"고마워요! 이걸 갈아서 합성물을 만들면 돼요.","이제 차가 빨라서 망가질 일은 없겠네요.","부딪히지만 않으면 안전하대요."}},
[1108]={a={"망명자 마르텍은 황야의 땅에 금속이 아주 많대요.","인듀리움은 열과 압력에 강하다고 알려졌대요.","바위동굴 트로그가 가진 인듀리움 조각을 가져다 달래요."},c={"좋아요, 이걸로 충분하겠어요.","이제 열을 가해서 어떻게 버티는지 봐야겠어요."},nx=1137,nt="News for Fizzle"},
[1109]={a={"수석 연금술사 파라넬은 할 일이 너무 많대요.","희귀한 재료는 가시덩굴 우리의 박쥐에게서 나온대요.","가시덩굴 조분석을 가져다 달래요."},c={"훌륭하네요! 이제 실험을 시작할 수 있겠어요."},nx=1113,nt="Hearts of Zeal"},
[1110]={a={"크레이블 콜비어드는 경주 때마다 사고가 난대요.","소금 평원에 로켓 자동차 부품이 흩어져 있대요.","그 부품을 모아 가져오면 후하게 쳐준대요."},c={"와, 쓸 만한 게 많네요! 고마워요.","잘 찾으면 남의 불행에서도 이익을 얻을 수 있대요."}},
[1111]={a={"크레이블 콜비어드는 사람들이 원하는 물건을 구해 줘요.","노움들이 주문한 부품이 일주일 전 톱니항에 도착했대요.","톱니항의 부두주임 디지위그에게 부품주문서를 보여 달래요."},c={"아, 크레이블의 부품이군요. 잘 왔어요.","며칠이나 밖에 있어서 녹슬까 봐 걱정했대요."},nx=1112,nt="Parts for Kravel"},
[1112]={a={"부두주임 디지위그가 크레이블의 부품을 갖고 있어요.","그런데 크레이블이 외상값을 아직 갚지 않았대요.","짐을 전하면서 외상값부터 갚으라고 전해 달래요."},c={"잘됐네요! 이제 노움들에게 전해야 해요.","그런데 먼저 작은 물건 하나를 빼내려고 해요."},nx=1114,nt="Delivery to the Gnomes"},
[1113]={a={"수석 연금술사 파라넬은 상반되는 화학 물질을 실험하려 해요.","독극물과 섞으면 어떤 결과가 나올지 궁금해해요.","붉은십자군 수도원의 열정의 증거를 가져다 달래요."},c={"이렇게 많이 가져와서 정말 훌륭하네요!"}},
[1114]={a={"크레이블 콜비어드는 필요한 부품을 모두 챙겼대요.","피즐 브라스볼츠가 오랫동안 목 빠지게 기다렸대요.","이 정밀한 부품을 피즐에게 가져다 달래요."},c={"드디어 왔네요! 제가 주문한 부품이에요.","이 부품이면 충분해요. 고마워요!"},nx=1115,nt="The Rumormonger"},
[1115]={a={"크레이블 콜비어드는 이제 고블린을 위해 일해 보겠대요.","나즈 스팀보일에게 다른 이름이 있다는 소문이 있대요.","무법항의 크라젝을 만나 정보를 얻어 달래요."},c={"나즈 스팀보일이요? 소금 평원의 경주 조종사 맞죠?","알아볼 수는 있지만 쉽지도 빠르지도 싸지도 않대요."},nx=1116,nt="Dream Dust in the Swamp"},
[1116]={a={"나즈 스팀보일의 정보는 구하기 쉽지 않대요.","크라젝은 정보원들과 연락하느라 바쁘대요.","슬픔의 늪의 용들에게서 꿈가루를 구해 달래요."},c={"꿈가루를 찾았군요! 늪은 어땠어요?","거기서는 따뜻한 밥 먹기도 힘들었을 거래요."},nx=1117,nt="Rumors for Kravel"},
[1117]={a={"크라젝은 귀한 엘프 와인까지 써서 정보를 얻었대요.","나즈 스팀보일에 관한 편지를 적어 줬대요.","이 편지는 어디서 구했는지 아무에게도 말하지 말래요."},c={"오호, 아주 흥미로운 내용이네요.","나즈 스팀보일이 비밀을 지키려고 꽤 큰돈을 낼 거래요."},nx=1118,nt="Back to Booty Bay"},
[1118]={a={"크레이블 콜비어드가 새 계획을 세우고 있대요.","위험하지만 성공하면 둘 다 큰돈을 번대요.","무법항의 크랭크 피즐버브에게 편지를 전해 달래요."},c={"크랭크 피즐버브는 크레이블의 큰 계획을 알겠대요.","크레이블의 음흉한 면이 마음에 든대요.","잔질의 혼합물이 쓸 만할지 궁금해해요."}},
[1119]={a={"크랭크 피즐버브가 새 술을 만들었대요.","잔질의 혼합물을 섞어 멍텅구리 스타우트를 만들었대요.","크레이블에게 가져다주고 효과를 알려 달래요."},c={"크레이블은 피즐버브가 제대로 해냈다며 기뻐해요.","다음에 피즐버브를 만나면 기억하겠대요.","당신도 잘하고 있어서 둘 다 큰돈을 벌 거래요."}},
[1120]={a={"크레이블이 멍텅구리 스타우트를 정비공에게 먹이려 해요.","노움 정비주임에게 맥주를 갖다 달래요.","맥주 맛이 변할 수 있으니 서두르래요."},c={"노움 정비주임이 맥주를 받고 고마워해요.","경주를 앞두고 술은 안 되지만 조금은 괜찮대요.","이 맥주가 그리 독하지는 않을 거래요."},nx=1122,nt="Report Back to Fizzlebub"},
[1121]={a={"크레이블이 멍텅구리 스타우트를 정비공에게 먹이려 해요.","고블린 정비주임에게 맥주를 갖다 달래요.","맥주 맛이 변할 수 있으니 서두르래요."},c={"고블린 정비주임이 술을 보고 반가워해요.","조금쯤은 마셔도 괜찮겠다고 해요."},nx=1122,nt="Report Back to Fizzlebub"},
[1122]={a={"크레이블은 맥주 실험이 성공해 기뻐해요.","다음 경주를 위해 맥주를 더 얻고 싶대요.","무법항의 크랭크 피즐버브에게 쪽지를 전해 달래요."},c={"피즐버브가 쪽지를 읽고 실험이 성공했다고 해요.","더 원하면 알려 달래요.","그럼 잔질의 혼합물을 더 모아 오라고 할게요."}},
[1123]={a={"대드루이드 하뮬 룬토템이 라빈 사투르나 얘기를 꺼내요.","라빈은 운고로 서쪽의 먼 황무지 탐험을 도울 사람을 찾아요.","나이트헤이븐에 가서 라빈과 얘기해 보래요."},c={"라빈 사투르나가 수호자 레물로스를 대신해 환영한대요.","세나리온 의회를 도우려는 마음이 고맙대요.","이곳에서 당신은 친구들과 함께 있대요."},nx=1124,nt="Wasteland"},
[1124]={a={"라빈 사투르나가 실리더스 얘기를 꺼내요.","누군가 옛날 나이트 엘프가 싸운 사악한 힘을 깨우려는 것 같대요.","용사의 안식처에서 라요 스타스트라이크에게 편지를 전해 달래요."},c={"라빈 사투르나가 보냈냐며 라요가 당신을 반겨요.","옛 일을 겪진 않았지만 이 사막은 으스스하대요.","세나리온 의회가 오래전에 사라진 위협을 끝낼 수 있대요."},nx=1125,nt="The Spirits of Southwind"},
[1125]={a={"라요 스타스트라이크가 마파람 마을 이야기를 해요.","옛 나이트 엘프 거점이던 마을이 실리시드에게 무너졌대요.","마을을 살펴 고통받는 영혼들을 풀어 달래요."},c={"라요는 근처 소굴이 마을을 무너뜨렸다고 짐작했대요.","그 말이 맞았다며 소굴이 위험하다고 해요.","영혼을 풀어 준 일에 고마워하며 또 도와 달래요."},nx=1126,nt="Hive in the Tower"},
[1126]={a={"라요 스타스트라이크가 마파람 마을의 소굴을 걱정해요.","실리시드는 말벌 떼가 감싼 탑에 가장 많대요.","그래서 탑에 올라가 소굴을 들쑤셔 달래요."},c={"라요 스타스트라이크는 찾은 물건이 상자처럼 생겼대요.","안에 책이 있는 것 같다고 해요.","옛날 기록이라면 무엇인지 알아낼 방법이 있대요."},nx=6844,nt="Umber, Archivist"},
[1130]={a={"조른 스카이시어가 멜로르 스톤후프의 말을 전해요.","멜로르 스톤후프가 활약을 듣고 일을 맡기려 한대요.","썬더 블러프 수렵의 봉우리에서 멜로르를 만나 보래요."},c={"이렇게 왔군요. 먼 땅으로 떠날 준비가 됐나요?","준비가 됐다면 잘 들어 보라고 해요."},nx=1131,nt="Steelsnap"},
[1131]={a={"멜로르 스톤후프가 저주받은 짐승 이야기를 해요.","버섯구름 봉우리의 무쇠이빨 하이에나가 짐승들을 해쳐요.","그 하이에나를 찾아 처치해 달래요."},c={"무쇠이빨 하이에나를 쓰러뜨려 끔찍한 오염이 사라졌대요.","그것이 오늘의 교훈이래요."},nx=1136,nt="Frostmaw"},
[1136]={a={"멜로르 스톤후프가 이제 먼 땅으로 떠날 때라고 해요.","알터랙 산맥의 서리갈기 설인은 좀처럼 모습을 안 드러내요.","설인을 꾀는 법이 적힌 두루마리를 주며 갈기를 가져오래요."},c={"서리갈기 설인을 찾아 쓰러뜨리려면 힘과 꾀가 모두 필요했대요.","사냥꾼의 길은 대지모신의 모든 땅으로 이어진대요."}},
[1137]={a={"망명자 마르텍은 인듀리움이 피스톤에 쓸 만하다고 봐요.","하지만 조각으로는 부족해서 울다만에서 광석을 캐야 해요.","피즐 브라스볼츠에게 이 얘기를 전해 달래요."},c={"돌아왔군요! 마르텍을 만났나요?","그가 도와줄 수 있는지 빨리 말해 달래요."},nx=1190,nt="Keeping Pace"},
[1144]={a={"수입업자 윌릭스는 오래 갇혀 있었대요.","메보크 미지릭스가 청엽수 줄기를 비싸게 산다고 해서 왔대요.","여기서 나갈 수 있도록 도와 달래요."},c={"고마워요, 친구! 약속한 대로 보답할게요."}},
[1145]={a={"코란은 여행자들이 가져온 알을 살펴보고 있대요.","이 곤충이 생각보다 훨씬 위험한 것 같대요.","오그리마의 벨그롬 록마울에게 쪽지를 전해 달래요."},c={"코란에게서 온 쪽지군요. 그는 오래 충직했어요.","크로스로드 일은 어떻게 되고 있는지 궁금했대요."},nx=1146,nt="The Swarm Grows"},
[1146]={a={"벨그롬 록마울도 코란과 같은 생각이래요.","사냥꾼이 버섯구름 봉우리에서 초주검이 되어 돌아왔대요.","버섯구름 봉우리의 목타르 크린에게 전해 달래요."},c={"더 큰 위협도 있대요. 그중 하나가 부대를 무너뜨렸대요.","벨그롬의 소식을 기다리며 이곳을 지키고 있대요."},nx=1147,nt="The Swarm Grows"},
[1147]={a={"목타르 크린은 벨그롬이 곤충을 큰 위협으로 본대요.","남은 부대는 지쳐서 싸우기 힘들대요.","남쪽 발굴 현장의 실리시드를 대신 처치해 달래요."},c={"그 진액이 묻어 오히려 멋져 보이지만 냄새가 심해요.","그 냄새만으로도 곤충과 싸운 증거래요. 고마워요!"}},
[1148]={a={"금이 간 실리시드 등껍질은 아주 단단해요.","이 짐승이 아주 진화된 종이라는 걸 알게 됐대요.","실리시드 재료를 코란에게 가져다 달래요."},c={"잘 가져왔네요. 이 표본으로 곤충의 정체를 알 것 같아요.","거인의 들판 알과 함께라면 원하는 것도 알아낼 거래요."},nx=1184,nt="Parts of the Swarm"},
[1149]={a={"도른 플레인스토커는 육체와 정신, 영혼을 시험한대요.","첫 번째는 믿음의 시험이라고 해요.","믿음이 있다면 높은 판자에서 뛰어내려 보래요."},c={"보장도 없이 뛰어내린 걸 보니 용기가 대단하대요.","준비가 됐다면 다음 시험이 기다린대요."},nx=1150,nt="Test of Endurance"},
[1150]={a={"도른 플레인스토커가 이제 몸의 힘을 시험하려 해요.","높새바람 봉우리 서쪽 하피 동굴의 보급품을 부수라고 해요.","그렌카 블러드스크리치를 처치하고 발톱을 가져다 달래요."},c={"그렌카 블러드스크리치는 트롤 중에서도 강했대요.","믿음과 인내를 보였으니 이제 새로운 시험이 남았대요."},nx=1151,nt="Test of Strength"},
[1151]={a={"도른 플레인스토커가 힘을 시험할 차례래요.","고대 신들이 떠나자 정령들은 세상에서 사라졌대요.","버섯구름 봉우리의 로크알림을 찾아 처치해 달래요."},c={"힘과 용기를 보여 시험을 통과했대요.","이제 이 의식을 마칠 마지막 시험만 남았대요."},nx=1152,nt="Test of Lore"},
[1152]={a={"도른 플레인스토커와의 시간이 거의 끝났대요.","지혜의 시험은 브라우그 딤스피릿이 맡고 있대요.","토굴길 근처에서 브라우그 딤스피릿을 찾아 달래요."},c={"도른이 자질을 알아보고 이곳에 보냈대요.","여러 종족이 함께 세상의 고통을 만들었대요."},nx=1154,nt="Test of Lore"},
[1153]={a={"테터낵 스틸포지는 대족장님의 일을 맡고 있어요.","버섯구름 봉우리 여행자들이 희귀한 광석을 얻었는데 안 판대요.","그 광석 견본을 구해 달라고 부탁해요."},c={"좋은 견본이라며 아주 기뻐해요.","튼튼하면 대족장님께 드릴 무기를 만든대요."}},
[1154]={a={"브라우그 딤스피릿은 도른의 시험을 통과한 나에게 다음 시험을 내요.","그 책은 잿빛 골짜기 남쪽 도르다닐 아래에 있대요.","그 책을 찾아 읽고 질문에 답해 달래요."},c={"이게 그가 말했던 책이래요.","다시 찾아가면 질문을 하겠대요."},nx=6627,nt="Test of Lore"},
[1159]={a={"브라우그 딤스피릿은 지혜의 시험 첫 단계를 통과한 나를 칭찬해요.","파쿠알 핀탈라스는 역병 전에 인간들의 역사가였대요.","로데론의 폐허에 있는 파쿠알 핀탈라스를 찾아가래요."},c={"브라우그 딤스피릿이 보냈다는 말을 믿지 못하겠대요.","나를 가짜 모험가로 의심하면서도 시험을 허락해요."},nx=1160,nt="Test of Lore"},
[1160]={a={"파쿠알 핀탈라스는 지식이 힘보다 중요하대요.","티리스팔 숲 북쪽 수도원 도서관에 책이 있대요.","언데드 위협의 기원이라는 책을 가져와 달래요."},c={"그가 찾아 달라던 책이 맞대요.","책을 충분히 공부하면 질문을 하고 시험이 끝난대요."},nx=6628,nt="Test of Lore"},
[1164]={a={"지나비 칼로는 역병과 전쟁으로 모든 걸 잃었어요.","케나타 가족은 잘 살면서 마지막 귀중품까지 훔쳐 갔대요.","다비리 농장에 가서 그들을 처치해 달래요."},c={"복수를 해 줘서 고맙다며 고개를 숙여요.","이제 돈 되는 일에 힘을 쏟을 수 있대요."}},
[1166]={a={"대군주 모크모로크가 옛집에 물건을 두고 왔대요.","그로그주와 코담배통, 금고를 남쪽에서 찾아야 해요.","화염의 둥지와 돌망치일족 폐허를 찾아보래요."},c={"모크모로크는 그 물건들이 많이 그립대요.","당신이 착하다며 이제 좋아한대요."}},
[1168]={a={"타르그는 검은용들 때문에 아내를 잃었대요.","오우거들은 싸워야 한다며 복수를 원해요.","검은용군단과 싸우는 오우거를 도와 달래요."},c={"타르그가 검은용 군대를 많이 쓰러뜨린 당신에게 고마워해요.","당신이 용감하다며 타르그가 기뻐해요."}},
[1169]={a={"드라즈질브는 옛 고향을 침략한 무리를 알아내려 해요.","화염 새끼용의 심장과 혓바닥이 필요하대요.","그걸로 악의 뿌리를 추적하겠대요."},c={"드라즈질브는 심장과 혓바닥을 모으는 일이 위험했겠대요.","이제 신비한 마법을 깊이 파고들어 침략의 근원을 찾겠대요."},nx=1170,nt="The Brood of Onyxia"},
[1170]={a={"드라즈질브는 오닉시아 무리가 마을을 침략했대요.","검은용군주 데스윙의 딸이 왜 왔는지 걱정이래요.","대군주 모크모로크에게 당장 알려 달래요."},c={"모크모로크는 용 얘기는 듣기 싫대요.","여기가 좋고 여기엔 용이 없다고 해요."},nx=1171,nt="The Brood of Onyxia"},
[1171]={a={"대군주 모크모로크가 혼자 있고 싶대요.","드라즈질브에게 자기들은 여기 남는다고 전해 달래요.","여기엔 검은용이 없다는 말도 전하래요."},c={"드라즈질브는 모크모로크를 게으른 겁쟁이라고 불러요.","렉사르가 떠난 뒤 권력에 빠져 명령만 한대요.","이제 무언가 해야 한다고 해요."},nx=1172,nt="The Brood of Onyxia"},
[1172]={a={"드라즈질브는 오닉시아의 새끼들이 퍼진 게 걱정이래요.","먼지진흙 습지대 남쪽 용의 둥지로 가 달래요.","오닉시아의 알을 찾아 부숴 달래요."},c={"드라즈질브는 오닉시아가 알을 다시 낳기까지 시간이 걸린대요.","모크모로크는 우리를 이끌기엔 부족하대요.","힘으로 몰아내야 새 지도자를 세울 수 있대요."},nx=1173,nt="Challenge Overlord Mok'Morokk"},
[1173]={a={"대군주 모크모로크가 당신에게 싸움을 걸어요.","힘센 척하며 실컷 두들겨 주겠대요.","이긴 뒤 드라즈질브에게 소식을 전해 달래요."},c={"드라즈질브는 모크모로크가 겁먹은 아이처럼 도망쳤대요.","당신이 큰일을 해냈다며 고마워해요.","이제 새 지도자를 뽑아 옛 고향을 되찾을 수 있대요."}},
[1175]={a={"경주로관리인 제린은 소금 평원의 경주로를 맡고 있어요.","경주 중에 짐승이 경주로에 들어올까 봐 걱정해요.","바실리스크를 좀 처치해 달라고 부탁해요."},c={"경주로 위에서 잡으면 안 된대요.","사체가 썩는 데 오래 걸려 치우기 싫대요."}},
[1176]={a={"포직은 경주용차를 조금씩 손보고 있어요.","독수리 뼈는 강도와 무게의 균형이 완벽하대요.","소금 평원에서 가벼운 독수리 뼈를 구해 달래요."},c={"바로 팀원들을 시켜 작업하겠대요."},nx=1178,nt="Goblin Sponsorship"},
[1177]={a={"머드크러쉬 더트피트는 배가 고픈 덩치 큰 오우거예요.","먹을 걸 안 주면 잡아먹겠다고 해요.","진흙아가미 멀록의 머리를 가져다 달래요."},c={"물고기 머리를 아주 좋아한대요.","이제 나를 잡아먹지 않겠대요."}},
[1178]={a={"포직의 경주팀을 후원하는 가즈로가 있어요.","가즈로가 연료 조절 장치를 보낸다더니 소식이 없대요.","톱니항에 가서 가즈로에게 물어봐 달래요."},c={"포직이 보냈냐며 반가워해요.","포직은 예전에 존경받는 수리공이었대요.","경주차를 만들려고 일을 그만뒀대요."},nx=1180,nt="Goblin Sponsorship"},
[1180]={a={"가즈로는 포직에게 연료 조절 장치를 약속했대요.","레빌가즈가 무법항에서 보냈다는데 사라진 것 같대요.","무법항 부두주임 로즈길을 만나 짐 기록을 확인해 보래요."},c={"톱니항으로 간 마지막 배는 신발 짐이었대요.","경주차 부품은 하나도 없었대요."},nx=1181,nt="Goblin Sponsorship"},
[1181]={a={"부두주임 로즈길은 배 기록에서 단서를 못 찾았어요.","남작 레빌가즈가 그 일을 가장 잘 안대요.","부두 건너 선술집 꼭대기 층에 있으니 찾아가래요."},c={"그 일은 알지만 도와줄 수는 없대요.","설계도를 찾으러 간 부하들도 빈손이었대요."},nx=1182,nt="Goblin Sponsorship"},
[1182]={a={"남작 레빌가즈는 포직을 돕고 있어요.","나즈페리티 호수의 벌목기에 새 연료 조절 장치가 있대요.","감독관 코즐 집의 설계도를 찾아 달래요."},nx=1183,nt="Goblin Sponsorship"},
[1183]={a={"남작 레빌가즈는 연료조절장치 설계도를 얻었어요.","포직이 경주 기록을 갱신하길 기대한대요.","설계도를 포직에게 전해 달래요."},c={"이미 조립돼 있길 바랐지만 괜찮대요.","설계를 처음부터 고쳐서 곧 달겠대요."},nx=1186,nt="The Eighteenth Pilot"},
[1184]={a={"코란은 자기 연구가 진척되고 있대요.","목타르가 버섯구름 봉우리에서 잘 따르고 있대요.","오그리마에 가서 벨그롬 록망치에게 전해 달래요."},c={"당신의 노력에 고마워하고 있대요.","대족장님께 당신 이름도 전하겠대요.","코란에게 이 생물들 소식을 들으면 다시 오래요."}},
[1186]={a={"포직은 새 연료 조절 장치 작업으로 바빠요.","래저릭은 경주용차를 개조하고 싶어 하는 열여덟 번째 조종사예요.","팀을 더 돕고 싶다면 래저릭을 찾아가래요."},c={"포직을 도와주던 분이냐고 물어요.","나도 예전엔 정비를 도왔는데 지금은 조종사래요."},nx=1187,nt="Razzeric's Tweaking"},
[1187]={a={"래저릭은 포직이 만든 경주차를 직접 손봐요.","부스터를 실은 비행선이 먼지진흙 습지대에 추락한 것 같대요.","그 시포리움 부스터를 찾아다 달래요."},nx=1188,nt="Safety First"},
[1188]={a={"래저릭이 받은 시포리움 부스터에 문제가 있어요.","쉬리브가 안전장치를 켜 놔서 힘이 줄어든대요.","가젯잔 기즈모리움에서 안전장치를 빼 달래요."},c={"쉬리브는 래저릭이 안전장치 탓을 한다고 억울해해요.","이 부스터는 거의 다 시포리움 폭약이래요.","이미 더 세게 개조해 뒀는데 래저릭은 만족을 모른대요."},nx=1189,nt="Safety First"},
[1189]={a={"쉬리브가 래저릭이 부탁한 대로 부스터를 고쳤대요.","시동을 걸 때 작은 실수라도 하면 잿더미가 된대요.","래저릭에게 조심하라고 전해 달래요."}},
[1190]={a={"포직은 브라스볼츠 형제의 차가 빨라졌다고 해요.","설계는 그대로인데 새 자재를 찾은 것 같대요.","자멕이 주의를 돌리면 리즐의 설계도를 빼내 달래요."},c={"급하게 휘갈긴 두루마리에 정제 설계가 적혀 있어요.","어떤 원재료를 정제하는 설계래요."},nx=1194,nt="Rizzle's Schematics"},
[1194]={a={"리즐의 설계도에는 인듀리움 광석으로 부품을 강화하는 방법이 있어요.","광석은 황야의 땅 울다만 드워프 발굴지에서 나온 것 같대요.","인듀리움 광석 견본을 포직에게 가져가 달래요."},c={"포직은 인듀리움이 흥미롭다며 살펴봐요.","열을 견디는 광석이면 노움들의 성능 향상을 설명하대요.","견본으로 시험은 해 보지만 더 많이 필요하대요."}},
[1195]={a={"버섯구름 봉우리의 갈라크 켄타우로스가 유물을 지켜요.","잔겐 스톤후프는 그 유물을 꼭 찾고 싶어 해요.","나이트 엘프의 달샘 물을 떠다 달래요."},c={"이 물이면 그 요청에 딱 맞겠대요.","이걸 그에게 전해 달래요."},nx=1196,nt="The Sacred Flame"},
[1196]={a={"라우 클리프러너는 높새바람 봉우리에 있어요.","그에게 필요한 건 달샘 물이 든 약병이래요.","약병을 그에게 전해 달래요."},c={"이 약병의 물이면 딱 맞는대요.","드리아드와 켄타우로스는 조상이 같대요.","그래서 그 물로 영원한 불꽃을 뚫을 수 있대요."},nx=1197,nt="The Sacred Flame"},
[1197]={a={"라우 클리프러너는 물로 불꽃을 잠시 누를 수 있대요.","불꽃은 갈래발굽 소굴 안에 있어 경비가 삼엄해요.","북쪽 갈래발굽 바윗골에서 갈래 발굽을 찾아 달래요."},c={"갈래 발굽에서 이상한 기운이 느껴진대요.","이걸 연구하면 켄타우로스에 대해 새로 알게 될 거래요."}},
[1201]={a={"나지르 블러드파이크는 담쟁이 마을에 있는 호드 사람이에요.","얼라이언스 첩보원들이 마을 동쪽에서 우리를 염탐하고 있대요.","그 첩보원들을 찾아 처치해 달래요."},c={"첩보원들이 똑똑해도 호드의 눈은 못 피한대요."},nx=1202,nt="The Theramore Docks"},
[1202]={a={"첩보원 둘이 배에서 서류를 훔치려다 들켰대요.","서류는 바다에 던져졌고 되찾지 못했어요.","테라모어 부두 밑 물속 상자에서 서류를 찾아 달래요."},c={"정말 어려운 임무였는데 잘 해냈대요.","윗사람들이 그 서류를 아주 귀하게 여긴대요."}},
[1203]={a={"늪지눈알 자를은 무언가를 잘라야 한대요.","그럴 때 쓸 특별한 검이 필요하대요.","달의 강철 브로드소드를 찾아 달라고 부탁해요."},c={"좋은 검이라며 아주 고마워해요.","지금 당장 써 보고 싶지만 나중에 쓰겠대요."}},
[1205]={a={"멜로르 스톤후프가 늙은 악어 이야기를 해요.","붉은눈늪지악어가 늙은 몸으로 큰 고통을 겪고 있대요.","악어가 안식을 얻도록 이빨을 가져다 달래요."},c={"멜로르가 사냥이 쉽지 않았을 거라며 고마워해요.","악어의 고통이 드디어 끝났다니 다행이래요."},nx=97378,nt="Mirrorscale"},
[1206]={a={"늪지눈알 자를은 눈알 주스를 좋아해요.","특히 암흑안개 거미의 눈이 맛있대요.","서쪽 암흑안개 거미굴에서 눈을 가져다 달래요."},c={"눈을 가져와서 아주 신이 났어요.","쳐다보는 눈알은 맨 마지막에 먹는대요."},nx=1203,nt="Jarl Needs a Blade"},
[1218]={a={"늪지눈알 자를은 늪지 요리를 좋아해요.","요리를 하려면 독특한 양념이 필요하대요.","독특한 양념을 구해다 달래요."},c={"아, 바로 이 양념이래요!","이제 늪지 스튜를 나눠 준대요."},nx=1206,nt="Jarl Needs Eyes"},
[1221]={a={"메보크 미지릭스는 청엽수 줄기를 찾고 있어요.","청엽수 줄기는 세계적인 별미인데 아주 귀하대요.","가시덩굴 우리에서 줄기를 찾아 달래요."},c={"줄기를 구해 와서 아주 좋아해요.","지인들에게 큰돈을 받고 팔 수 있대요."}},
[1238]={a={"푸석푸석한 흙더미 속에서 오크의 손이 나왔어요.","관 안에는 테라모어를 염탐한 보고서가 있었어요.","담쟁이 마을의 나지르 블러드파이크에게 전해 달래요."},c={"우리 요원이 테라모어를 염탐하던 보고서래요.","그 요원이 늪에서 죽은 것 같아 걱정된대요."},nx=1239,nt="The Severed Head"},
[1239]={a={"흙을 파니 거칠어 보이는 오크 가면이 나왔어요.","가면의 입술이 으르렁대듯 굳어 있어요.","나지르 블러드파이크에게 혼이 깃든 오크의 가면을 가져가래요."},c={"이건 우리 요원의 머리래요.","얼라이언스가 죽였는지 알아내야 한대요."},nx=1240,nt="The Troll Witchdoctor"},
[1240]={a={"나지르 블러드파이크는 마그 나이트아이의 죽음이 궁금해요.","트롤의 마법으로만 알아낼 수 있대요.","가면을 가시덤불 골짜기의 킨윌레이에게 가져가래요."},c={"이 오크의 영혼이 이 세상에 묶여 있대요.","끝내지 못한 일 때문에 화가 나 있대요."},nx=1261,nt="Marg Speaks"},
[1251]={a={"그늘 쉼터 여관의 무너진 굴뚝에 철제 방패가 붙어 있어요.","여관 전체를 휩쓴 불에 검게 그을린 방패예요.","그 방패를 떼어서 담쟁이 마을의 크로그에게 가져가래요."},c={"사람들이 벽난로에 이런 방패를 걸까요?","여관을 태운 자들이 걸어 둔 걸지도 모른대요."},nx=1321,nt="The Black Shield"},
[1261]={a={"죽은 마그가 가마솥에서 말을 걸어요.","마그는 얼라이언스 병사의 펜던트를 훔쳤대요.","진흙껍질에게 죽어서 펜던트를 찾아 달래요."},c={"이 펜던트를 얼라이언스 병사가 찼냐며 놀라요.","마그가 죽은 이유는 알겠지만 새 수수께끼가 생겼대요."},nx=1262,nt="Report to Zor"},
[1262]={a={"나지르 블러드파이크는 보석 펜던트의 주인을 알고 싶어 해요.","펜던트는 귀족의 물건이래요.","오그리마의 조르 론트리에게 가져가 달래요."},c={"오크는 이런 보석을 탐내지 않을 거래요.","사람들은 탐낼 거라며 펜던트를 연구하겠대요."},nx=7541,nt="Service to the Horde"},
[1268]={a={"그늘 쉼터 여관의 잔해에서 발굽 자국이 이어져 있어요.","여관 잔해에서는 아직도 연기가 나고 있어요.","수상한 자국을 담쟁이 마을의 크로그에게 보고해 달래요."},c={"여관 주인의 부인과 아이도 죽었대요.","카고로가 발자국을 따라가 찾을 거래요."}},
[1269]={a={"잔해 밑에서 테라모어 경비병 휘장이 반짝였어요.","휘장에는 부관 파발 리테라는 이름이 있어요.","담쟁이 마을의 크로그에게 리테의 배지를 가져다 달래요."},c={"그 사람은 탈영해서 숲에 숨었대요.","오그론을 보내 그를 쫓게 했대요."},nx=1273,nt="Questioning Reethe"},
[1270]={a={"말썽꾼 이그나츠는 짐승들에게 둘러싸였대요.","톱니항의 메보크 미지릭스가 진흙콩 잎을 원한대요.","잎을 찾는 동안 그의 뒤를 지켜 달래요."},c={"이그나츠가 당신이 도와줬다고 하네요.","그는 당신에게 준다며 늪으로 떠났대요."}},
[1273]={a={"오그론이 리테를 드디어 찾아냈대요.","늪에 오래 숨어 지내서 리테를 걱정했대요.","같이 가서 리테를 심문하자고 해요."},c={"리테가 더는 늪을 떠돌지 않게 됐대요.","이 단서로는 아무것도 알아내지 못했대요."}},
[1276]={a={"크로그는 썬더 블러프의 대장장이 모사른을 기억해 냈어요.","리테에게선 쓸만한 단서가 없었대요.","타락의 철제 방패를 모사른에게 보여 달래요."},c={"맞아요, 이건 내가 만든 방패래요.","만든 방패가 너무 많아서 기억 못 한대요."}},
[1321]={a={"크로그는 타락의 철제 방패를 살펴봤어요.","겉으로는 이상한 점이 보이지 않는대요.","대장장이 도골에게 보여 달라고 부탁해요."},c={"좋은 방패지만 도골에게는 필요 없대요.","도골은 방패를 만들 뿐 사지 않는대요."},nx=1322,nt="The Black Shield"},
[1322]={a={"대장장이 도골은 방패의 글씨를 읽고 싶어 해요.","테두리 글씨는 불에 타서 잘 안 보여요.","산성 독주머니를 구해다 달래요."},c={"이 거미는 너무 커서 싫대요.","받은 주머니를 찢어서 방패에 붓겠대요."},nx=1323,nt="The Black Shield"},
[1323]={a={"도골이 방패 글씨를 닦아 보고 있어요.","글씨가 '모사른'이라는 이름처럼 보인대요.","크로그에게 가서 그 이름을 물어봐 달래요."},c={"모사른이라는 이름이 익숙하대요.","떠오를지도 모르지만 중요하지 않을 거래요."}},
[1358]={a={"진게의 동료 연금술사 헬브림이 로데론 독소를 연구 중이래요.","렌퍼럴이 보낸 늑대 심장 견본에 관심이 클 거래요.","늑대 심장 견본을 불모의 땅의 헬브림에게 전해 달래요."},c={"보고가 맞다면 독에 대한 지식이 더 늘 수 있대요.","좋은 전달이었다며 보상을 받을 만하다고 해요."}},
[1359]={a={"연금술사 렌퍼럴이 늑대 심장을 살펴보고 놀랐어요.","심장의 독이 늑대 자신에게도 치명적이래요.","남겨 둔 늑대 심장 견본을 진게에게 가져다 달래요."},nx=1358,nt="Sample for Helbrim"},
[1361]={a={"호드 전사 렉타르 데스게이트가 대원을 모집하고 있어요.","잊혀진 땅은 전쟁으로 고통받는 곳이라 준비가 필요해요.","불모의 땅에서 그를 찾아가 만나 보래요."},c={"네, 대원을 모집하고 있어요.","임무는 잊혀진 땅의 켄타우로스를 상대하는 거래요."},nx=1362,nt="The Kolkar of Desolace"},
[1362]={a={"콜카르 켄타우로스는 잊혀진 땅에 살고 있어요.","그들 군대가 불모의 땅 곳곳에 퍼져 있대요.","침묵의 초소의 펠굴 투커츠를 만나 보래요."},c={"렉타르 데스게이트 명령으로 왔군요?","싸움이 얼마나 끝날지 몰라도 길 거래요."}},
[1365]={a={"잊혀진 땅에는 콜카르 말고도 많은 부족이 살아요.","그들은 서로 싸우지만 손을 잡으면 아주 위험하대요.","우두머리 칸 데즈헤파를 처치해 달래요."},c={"잘했어요. 이 빠른 행동이 콜카르에게 힘을 보여 줬대요.","다른 부족들도 이제 함부로 못 움직일 거래요."},nx=1366,nt="Centaur Bounty"},
[1366]={a={"켄타우로스들에게 이미 겁을 줬대요.","이제 녀석들에게 우리 힘을 보여 줄 차례래요.","어느 부족이든 상관없으니 귀걸이를 모아 달래요."},c={"이제 켄타우로스들도 당신의 이름을 알 거래요.","호드의 깃발을 든 사람이라는 것도요."}},
[1367]={a={"구르다 와일드메인이 켄타우로스를 물리칠 방법을 찾고 있어요.","켄타우로스는 서로 미워하니 그 증오를 이용하려는 거래요.","마그람과 손을 잡으려면 숙적 겔키스를 처치해 달래요."},c={"겔키스는 당신 이름만 들어도 두려워하대요.","마그람처럼 강한지는 두고 봐야겠대요."},nx=1369,nt="Broken Tears"},
[1368]={a={"구르다 와일드메인이 켄타우로스를 물리칠 방법을 찾대요.","켄타우로스는 서로 미워하니 그 증오를 이용하려는 거래요.","겔키스와 손을 잡으려면 숙적 마그람을 처치해 달래요."},c={"땅이 내게 말해 줬어요. 마그람을 많이 쓰러뜨렸다고요.","겔키스의 친구라면 들어요. 할 일이 더 있어요."},nx=1370,nt="Stealing Supplies"},
[1369]={a={"와루그는 겔키스가 어리석다고 생각해요.","겔키스는 테라드라스가 자기들을 지켜 준다고 믿는대요.","마을 동굴의 테라드라스의 눈물을 부수고 조각을 가져다 달래요."},c={"눈물을 가져왔군요! 이제 겔키스는 깨닫겠군요.","마그람이 지배하게 될 거래요. 도와줘서 고맙대요."},nx=1371,nt="Gizmo for Warug"},
[1370]={a={"전쟁 중에도 고기는 힘이 된대요.","마그람도 싸움을 위해 고기를 모아 둔대요.","동쪽 마그람 마을을 습격해 고기를 빼앗아 달래요."},c={"좋아요. 멀리서 마그람 마을의 배고픈 소리가 들리는 것 같아요.","이 고기는 겔키스가 가져가 오래 싸울 거래요."},nx=1373,nt="Ongeku"},
[1371]={a={"오래전 작은 노움이 마차를 끌고 잊혀진 땅에 왔대요.","마차에 있던 나무로 만든 사람이 자꾸 손을 흔들었대요.","고급 표적 허수아비를 새로 구해다 달래요."},c={"맞아요, 바로 이거예요! 다시 움직이게 할게요.","그걸 보면 웃음이 나요."},nx=1375,nt="Khan Shaka"},
[1372]={a={"죽음의추적자 즈레더스가 인간 첩보원을 봤대요.","오크 동맹이 그를 스토나드로 끌고 갔대요.","파우스틴과 함께 진실의 물약을 만들어 달래요."},c={"연금술사 파우스틴은 첩보원이 큰 골칫거리라고 해요.","스토나드의 오크들이 그 첩보원의 말을 듣고 싶어 한대요.","그래서 스토나드에 진실의 물약을 보내기로 했대요."},nx=1383,nt="Nothing But The Truth"},
[1373]={a={"현자 우텍은 아직 더 증명해야 한다고 말해요.","땅이 속삭인 붉은 수정 드레니시스트 파편이 필요하대요.","슬픔의 늪에서 온게쿠가 쥔 파편을 구해 달래요."},c={"맞아요, 땅이 속삭인 바로 그 파편이에요.","이 마법으로 겔키스의 적을 물리칠 거래요."},nx=1374,nt="Khan Jehn"},
[1374]={a={"현자 우텍에게 땅이 전해 준 소식이 있대요.","마그람이 약해지고 있다는 소식이래요.","마그람의 우두머리 칸 젠을 처치해 달래요."},c={"칸 젠은 강했지만 어리석었어요. 자기 힘만 믿었죠.","마그람은 우두머리 없이 쓰러질 거래요."},nx=1380,nt="Khan Hratha"},
[1375]={a={"와루그가 당신을 마음에 들어 해요.","당신이 마그람을 돕고 있어서래요.","겔키스 우두머리 칸 샤카를 처치해 달래요."},c={"칸 샤카가 죽었대요! 머리를 창끝에 걸어 두겠대요.","마그람의 힘을 보여 주겠대요."},nx=1381,nt="Khan Hratha"},
[1380]={a={"현자 우텍이 마라우돈일족을 물리치자고 해요.","칸 흐라사가 열쇠 조각을 갖고 있대요.","칸 흐라사를 처치하고 열쇠 조각을 가져와 달래요."}},
[1381]={a={"와루그가 마라우돈일족을 무너뜨리자고 해요.","겔키스 우두머리가 죽어서 이제 차례래요.","칸 흐라사를 처치하고 열쇠 조각을 가져다 달래요."},c={"칸 흐라사가 죽었다며 와루그가 기뻐해요.","이제 마그람이 켄타우로스 중 가장 강하대요.","다른 이들이 짓밟혀도 당신은 살려 주겠대요."}},
[1383]={a={"연금술사 파우스틴이 새 물약을 생각해 냈대요.","흑표범 심장과 우두머리 늪괴물 곰팡이가 필요하대요.","깊은바다거인의 종양도 구해 와 달래요."},c={"파우스틴이 재료를 받고 반가워해요.","첩보원이 회복해서 오크들의 심문을 받을 수 있대요.","진실의 물약을 준비할 테니 잠깐 기다리래요."},nx=1388,nt="Nothing But The Truth"},
[1388]={a={"연금술사 파우스틴이 진실의 물약을 만들었대요.","즈레더스가 물약을 쓰는 법을 알려 준대요.","진실의 물약을 즈레더스에게 가져다 달래요."},c={"죽음의추적자 즈레더스는 파우스틴이 좋은 걸 만들 줄 알았대요.","당신이 큰 도움을 줬다고 해요.","이제 본격적으로 일을 시작하자고 해요."},nx=1391,nt="Nothing But The Truth"},
[1389]={a={"막투르의 형제들은 고된 여정 탓에 미쳐 버렸대요.","그들이 신성한 드레니시스트 수정을 훔쳐 갔대요.","드레노어 성역에 가서 수정을 되찾아 달래요."},c={"고마워요. 우리가 큰 빚을 졌어요."},nx=93464,nt="The Visiting Mage"},
[1391]={a={"즈레더스는 진실의 물약을 맥주에 타 먹일 계획이래요.","첩보원은 술 앞에서 망설이지 않을 거래요.","스토나드에 가서 이 맥주를 전해 달래요."},c={"첩보원 마크슨이 술을 줘서 고맙다고 해요.","며칠 동안 술을 못 마셨대요.","마시고 나면 알아낸 걸 말해 주겠대요."}},
[1392]={a={"곤봉잡이 노보루가 피난처의 드레나이를 괴롭혀 왔대요.","그의 곤봉은 드레나이들이 겪은 고통의 상징이래요.","그 곤봉을 피난처의 우두머리에게 가져다 달래요."},c={"노보루의 곤봉을 가져왔군요? 그가 죽었나요?","피난처에게 기쁜 날이래요. 당신이 친구라 다행이에요."}},
[1393]={a={"갈렌 굿워드가 짐승들에게 쫓기고 있대요.","보물은 금고 안에 있고 자기만 열 방법을 안대요.","그를 무사히 빼내 달라고 부탁해요."},c={"금고 열쇠 구멍은 검은 수지로 막혀 있었어요.","갈렌이 말한 바닥의 숨은 걸쇠를 찾아 열었대요."}},
[1394]={a={"파쿠알 핀탈라스가 당신의 시험 과정을 지켜봤대요.","도른 플레인스토커가 당신의 변화를 느낄 거래요.","버섯구름 봉우리의 도른 플레인스토커에게 돌아가 달래요."},c={"전보다 강해지고 깨달음을 얻은 모습이 기쁘대요.","시험을 끝까지 치렀으니 보상을 받아야 한대요."}},
[1418]={a={"날쌘돌이 헬그럼은 연락이 자주 끊기는 게 걱정이래요.","카르가스의 정찰 대장 니카 블러드스카의 보고가 필요하대요.","황야의 땅으로 가서 니카 블러드스카를 만나 달래요."},c={"헬그럼이 보고서를 원한다고요? 며칠 전 전령을 보냈는데.","전령이 실패했나 봐요. 다음엔 더 잘하길 바라요."},nx=1420,nt="Report to Helgrum"},
[1419]={a={"바위산코요테 때문에 카르가스 식량이 자주 털린대요.","바위산코요테는 사나울 뿐 아니라 대담하기도 하대요.","이 도둑들을 사냥해서 턱뼈를 가져다 달래요."},c={"턱뼈를 이렇게 많이 모았군요. 이제 식량을 못 훔칠 거예요.","황야의 땅에서도 살아남을 것 같대요."}},
[1420]={a={"니카 블러드스카가 헬그럼에게 보낼 보고서를 썼대요.","길을 잃으면 적에게 잡힐 수도 있으니 조심하래요.","그 보고서를 스토나드의 날쌘돌이 헬그럼에게 전해 달래요."},c={"고마워요. 얼라이언스도 문제가 많은 것 같대요.","공통의 적이 있을지도 모르겠대요."}},
[1422]={a={"톡카르가 당신의 무기를 만들고 있대요.","카타르가 해안 순찰을 도와줄 일손을 찾는대요.","술 대신 카타르를 만나 보래요."},c={"카타르가 조용히 해 보라고 해요.","바다 너머로 물고기 인간들의 소리가 들린대요."},nx=1426,nt="Threat From the Sea"},
[1424]={a={"펠제룰은 대족장의 명령으로 조사를 나왔대요.","아탈학카르 신전이 가라앉아 이상한 일이 벌어졌대요.","눈물의 연못 주변에서 아탈라이 유물을 모아 달래요."},c={"펠제룰이 아탈라이 유물을 열심히 모은 당신을 칭찬해요."},nx=1429,nt="The Atal'ai Exile"},
[1426]={a={"카타르는 바다와 바다 생물을 싫어해요.","늪지멀록들을 처치해 주면 좋겠대요.","가장 강한 멀록에 맞서 볼 수 있냐고 물어요."},c={"카타르는 당신이 멀록들의 피로 바다를 물들였대요.","멀록들이 고통을 알게 됐다며 기뻐해요.","더 처치하고 싶으면 돌아오면 또 보상한대요."},nx=1427,nt="Threat From the Sea"},
[1427]={a={"카타르는 쉬기 전에 톡카르와 다시 얘기해 보라고 해요.","톡카르가 당신이 없는 동안 무기를 몇 개 만든 것 같대요.","준비되면 물고기 인간들에게 그 무기를 시험해 보래요."},nx=1428,nt="Continued Threat"},
[1428]={a={"카타르는 물고기 인간을 미워하는 당신이 마음에 든대요.","해변에서 놈들을 더 찾아 실컷 싸우고 오래요.","싸움을 마치고 돌아오면 보상을 얘기하자고 해요."}},
[1429]={a={"펠제룰은 정찰병이 가져온 두루마리를 보고 있어요.","아탈라이 사제에 대한 판결문인데, 사제는 먼 북쪽으로 추방됐대요.","그 추방된 트롤을 찾아 유물의 쓰임을 알아봐 달래요."},c={"추방된 아탈라이트롤은 예언자 잠말란이 신도들을 정해진 운명으로 이끈대요.","학카르가 신전으로 돌아왔는지 궁금해해요."},nx=1444,nt="Return to Fel'Zerul"},
[1430]={a={"다르의 손님들은 육즙 많은 게살을 찾는대요.","특히 괴물게의 살이 인기가 좋대요.","해안에서 괴물게 집게발을 구해 와 달래요."},c={"다르는 이거면 완벽하다며 기뻐해요.","여행길에 가져갈 샘플도 하나 챙기래요."}},
[1431]={a={"크라벤 드록이 중요한 이야기가 있다며 목소리를 낮춰요.","인간과의 전쟁이 스랄의 인내심까지 시험하고 있대요.","오그리마 서쪽 출구 근처의 켈드란을 만나 보래요."},c={"켈드란이에요. 마법을 배운 사람이죠.","크라벤 드록이 보낸 일은 섬세해야 하지만 도울 수 있대요."},nx=1432,nt="Alliance Relations"},
[1432]={a={"켈드란이 호드가 불타는 군단과 맺은 조약을 걱정해요.","켈드란의 대원들은 잊혀진 땅 침묵의 초소에 있대요.","타카타 스틸블레이드를 찾아가 달래요."},c={"오그리마 소식을 가져오셨군요. 반가워요.","악마의 기운이 이곳을 뒤덮고 있어 걱정이래요."},nx=1433,nt="Alliance Relations"},
[1433]={a={"타카타 스틸블레이드는 불타는칼날단을 걱정하고 있대요.","켈드란이 마우린 본스플리터를 이곳에 보냈대요.","마우린 본스플리터를 만나 계획을 들어 보래요."},c={"마우린 본스플리터예요. 도움은 늘 반가워요.","불타는칼날단을 없앨 계획을 설명해 주겠대요."},nx=1435,nt="The Burning of Spirits"},
[1434]={a={"사티로스가 불타는칼날단과 손을 잡았대요.","스랄께서도 이들의 위협을 걱정하신대요.","북동쪽으로 가서 사티로스들을 물리치고 돌아와 달래요."},c={"명예와 헌신을 보여 줬군요. 고마워요.","잊혀진 땅 작전이 끝나면 대족장님도 알아주실 거래요."},nx=1436,nt="Alliance Relations"},
[1435]={a={"마우린 본스플리터가 특별한 보석을 건네요.","칼날단이 쓰러지기 직전 보석을 쓰면 영혼이 담긴대요.","영혼이 담긴 보석을 마우린에게 가져다 달래요."},c={"잘 돌아왔군요. 보석은 안전한 곳에 두겠대요.","이제 임무는 끝났어요. 타카타 스틸블레이드를 만나 보래요."}},
[1436]={a={"잊혀진 땅의 전투가 순조롭게 진행되고 있대요.","대족장님이 고향으로 돌려보내 줄지도 모른대요.","오그리마의 켈드란에게 우리가 한 일을 보고해 달래요."},c={"잊혀진 땅에서 큰 성과를 거두고 돌아왔군요. 고마워요.","스랄은 호드와 얼라이언스의 평화를 바란대요. 빚을 졌어요."}},
[1444]={a={"추방된 아탈라이트롤은 예언자 잠말란 때문에 신전에서 쫓겨났대요.","그 예언이 부족을 파멸로 이끌까 걱정했대요.","펠제룰에게 돌아가 이 얘기를 전해 달래요."},c={"펠제룰은 오랜만이라며 여행이 잘됐기를 바란대요.","추방된 아탈라이트롤에게 무엇을 알아냈냐고 물어요."},nx=1445,nt="The Temple of Atal'Hakkar"},
[1445]={a={"펠제룰은 예언자 잠말란의 예언이 걱정된대요.","추방자가 말한 마법 주물이 이 사태의 열쇠일지도 모른대요.","아탈학카르 신전에 들어가 주물을 손에 넣어 달래요."}},
[1446]={a={"추방된 아탈라이트롤은 부족에게 쫓겨나 고향이 없대요.","그 예언이 거짓일지도 모른다고 경고했는데 쫓겨났대요.","예언자 잠말란을 처치하고 머리카락을 가져다 달래요."}},
[1470]={a={"벤야 말선드는 흑마법을 가르치는 스승이에요.","지식으로 혼돈의 마법과 존재를 다스린대요.","먼저 덜그럭거리는 해골의 머리를 가져오래요."},c={"벤야는 당신이 종복을 부리는 법을 익힐 능력이 있대요.","종복은 몸은 약해도 힘과 영리함이 쓸모 있대요.","이 가르침은 다시 말하지 않을 테니 잘 들으래요."}},
[1471]={a={"카렌딘 할가르는 아래쪽 소환의 원을 가리켜요.","그곳에서 속박되지 않은 보이드워커를 불러낼 수 있대요.","소환의 룬으로 불러내 제압한 뒤 돌아와 달래요."},c={"카렌딘은 보이드워커를 부르는 주문을 알려 준대요.","보이드워커의 힘을 이제 당신이 다룰 수 있대요.","현명하게 쓰라고 당부해요."}},
[1472]={a={"카렌딘 할가르는 서큐버스를 우리 세계로 불러오려 해요.","서큐버스는 선하고 순수한 남자의 마음에 끌린대요.","사원의 고드릭 파산을 찾아가 미끼를 구해 달래요."},c={"카렌딘이 보냈다니 반가워요.","눈은 멀었지만 이제 전에 못 보던 게 보인대요."},nx=1476,nt="Hearts of the Pure"},
[1473]={a={"카렌딘 할가르는 당신이 소환을 배울 준비가 됐대요.","에갈린의 흑마법서는 Scarlet Crusade가 훔쳐 서쪽 탑에 숨겼대요.","흑마법서를 되찾아 카렌딘에게 가져다 달래요."},c={"카렌딘은 흑마법서를 되찾아 반가워해요.","Perrine은 이 책의 진짜 힘을 몰랐던 것 같대요.","주문의 짜임과 힘을 끌어내는 법을 보래요."},nx=1471,nt="The Binding"},
[1474]={a={"카렌딘 할가르는 이 심장으로 문을 열려 해요.","당신의 힘은 이제 강해져서 서큐버스를 이길 수 있대요.","서큐버스를 제압하고 순수한 심장을 가져다 달래요."},c={"또 해냈군요. 이만큼 재능 있는 흑마법사는 오랜만이에요.","이제 서큐버스를 부르는 주문을 가르쳐 줄게요."}},
[1476]={a={"고드릭 파선은 선한 남자들을 오래 찾았대요.","달린 포지라이트와 코마 빌라드를 찾았대요.","그 사람들의 심장을 카렌딘 할가르에게 가져다 달래요."},c={"좋은 남자의 심장도 이렇게 보면 다 같아 보이죠.","이 심장이면 충분해요. 서큐버스가 끌릴 거예요."},nx=1474,nt="The Binding"},
[1478]={a={"아제론 카갈은 카렌딘 할가르가 당신을 보고 싶대요.","카렌딘이 직접 가르치는 일은 흔치 않대요.","언더시티 마법 지구에서 카렌딘을 만나 달래요."},c={"카렌딘은 아제론이 당신을 찾아서 다행이라고 해요.","잡담은 줄이고 훈련에 집중하자고 해요.","배울 것이 아직 많이 남았대요."},nx=1473,nt="Creature of the Void"},
[1480]={a={"찢어진 악마의 가죽을 펼치니 붉은 글씨가 보여요.","맨 아래에는 서명 같은 기호가 새겨져 있어요.","마우린 본스플리터에게 이 가죽을 가져다 달래요."},c={"이 룬은 오래된 언어로 된 계약서인 것 같대요.","서명은 제왕 아즈레토크의 것이래요."},nx=1481,nt="The Corrupter"},
[1481]={a={"마우린 본스플리터가 악마 군주를 찾을 방법이 있대요.","방벽을 깨려면 특별한 사티로스 가죽이 필요하대요.","그림자추적자 머릿가죽을 잊혀진 땅 북동쪽 유적지에서 구해 달래요."},c={"그림자추적자도 당신을 쓰러뜨리지 못했군요.","이 머릿가죽이면 주문 준비가 거의 끝났대요."},nx=1482,nt="The Corrupter"},
[1482]={a={"마우린 본스플리터에게 예언의 수정구가 필요해요.","해안 북서쪽 산호초에 나가족이 살고 있대요.","뱀갈퀴 나가족을 조심해서 수정구를 구해 달래요."},c={"예언의 수정구네요! 정말 아름다워요.","이제 이 악마 군주가 무엇인지 같이 알아보죠."},nx=1484,nt="The Corrupter"},
[1483]={a={"스퍼터밸브는 투자개발회사에 빼앗긴 고블린들을 되찾으려 해요.","지즈 피직스가 땜장이 조합에 일자리를 부탁했대요.","칼바람 바위산 서쪽에 있는 지즈 피직스를 찾아가 달래요."},c={"투자개발회사 윗사람도 가혹했지만 스퍼터밸브가 제일 악랄해요.","도와주러 왔다면 할 일이 있어요."},nx=1093,nt="Super Reaper 6000"},
[1484]={a={"마우린 본스플리터는 악마가 생각보다 위험하다고 해요.","타카타 스틸블레이드의 자존심이 상할 수 있대요.","그에게 허락을 받고 악마를 처치하고 싶다고 말해 달래요."},c={"마우린과 악마 군주 사이의 일을 봤어요.","그 악마가 마우린 본스플리터보다 강해 보여 걱정이래요."},nx=1488,nt="The Corrupter"},
[1485]={a={"루잔은 흑마법사들이 호드의 의심을 받아 왔다고 해요.","많은 흑마법사가 혼자 숨어 마법을 연구해요.","북동쪽 동굴의 악마의 하수인 머리를 가져오래요."},c={"흑마법사는 여러 존재를 부르는 법을 배운대요.","여러 존재는 모두 쓸모 있는 도구래요.","작은 종복이라도 만만치 않은 적이었대요."},nx=1499,nt="Vile Familiars"},
[1486]={a={"날팍은 통곡의 동굴에 이상한 짐승들이 나타났대요.","나랄렉스가 악몽에 빠진 뒤 생긴 짐승이래요.","그 짐승의 돌연변이 통가죽을 구해 달래요."},c={"날팍은 가죽을 모아 준 노고를 알아준대요."}},
[1487]={a={"에브루는 통곡의 동굴에 타락한 짐승이 나타나 걱정이래요.","나랄렉스의 꿈이 악몽으로 바뀌었대요.","통곡의 동굴에 가서 그 기이한 짐승들을 없애 달래요."},c={"나랄렉스의 신도로서 용기에 감사해요.","이 일이 불모의 땅을 되살리는 첫걸음이래요. 고마워요."}},
[1488]={a={"타카타 스틸블레이드도 제왕 아즈레토크를 막아야 한대요.","아즈레토크가 불타는칼날단을 손아귀에 넣으려 한대요.","병력을 모아 남쪽에서 악마 군주를 처치해 달래요."},c={"모두를 위한 큰 승리예요. 정말 고마워요.","이제 이곳에서도 안전한 고향을 가질 수 있겠어요."}},
[1489]={a={"통가 룬토템은 가져온 등껍질에 처음 보는 오염이 있대요.","오아시스의 물이 땅을 혼란스럽게 하는 것 같대요.","대드루이드 하뮬 룬토템에게 조언을 구해 달래요."},c={"하뮬은 반갑다며 힘을 단단히 모으라고 해요.","맡길 일이 아주 위험하대요."},nx=1490,nt="Nara Wildmane"},
[1490]={a={"대드루이드 하뮬 룬토템이 꿈에서 드루이드들을 봤대요.","그들은 한때 숭고한 목표가 있었지만 길을 잃었대요.","천막에 있는 나라 와일드메인을 찾아가 보래요."},c={"나라는 통곡의 동굴 드루이드들을 잘 안대요.","그들의 뒤틀리고 비늘진 얼굴을 직접 봤대요.","그들을 막아 달래요."},nx=914,nt="Leaders of the Fang"},
[1491]={a={"메보크 미지릭스는 영리해지는 음료를 만들려 해요.","랩터 뿔은 안 통해서 통곡의 정수를 찾았대요.","서쪽 통곡의 동굴 외형질 생물을 잡아 정수를 모아 달래요."},c={"메보크는 정수를 얻어 기뻐하며 고마워해요.","돈을 벌면 더 보내 주겠다고 약속해요."}},
[1492]={a={"연금술사 헬브림은 동부 왕국의 동료에게 보낼 상자가 있대요.","마지막 짐마차가 떠나서 곤란하대요.","단단히 잠긴 상자를 디지위그에게 전해 달래요."},c={"디지위그는 작은 상자라서 배에 실을 수 있대요.","다음 물때에 배가 떠난대요.","장부에 적어 두었으니 걱정 말래요."}},
[1498]={a={"우제크 말로는 전사의 가장 중요한 임무는 보호래요.","수호자가 되려면 먼저 기개를 증명해야 한대요.","듀로타 천둥 골짜기 짐승의 그을린 비늘을 가져와 달래요."},nx=1502,nt="Thun'grim Firegaze"},
[1499]={a={"루잔은 당신이 경험을 쌓기를 바란대요.","주리타 파게이즈가 동굴의 짐승을 줄이는 일을 하고 있대요.","그녀에게 임프 일을 도왔다고 말해 달래요."},nx=794,nt="Burning Blade Medallion"},
[1501]={a={"오그리마의 간룰 블러드아이는 흑마법사가 거의 남지 않았대요.","불타는 칼날단이 훔친 베르가의 서판이 해골 바위굴에 있대요.","서판을 되찾아 오라고 부탁해요."},c={"간룰은 서판을 되찾아 와서 잘했다고 해요.","불타는 칼날단에게도 피해를 줬기를 바란대요.","칼날단은 흑마법사 모두에게 큰 해악이래요."},nx=1504,nt="The Binding"},
[1502]={a={"우제크는 전사에게 좋은 무기가 꼭 필요하다고 해요.","툰그림 파이어게이즈는 드문 솜씨를 가진 오크 장인이래요.","크로스로드 동쪽 언덕 위의 그를 찾아가 보래요."},c={"툰그림 파이어게이즈는 불을 오래 봐서 눈이 흐려졌대요.","그래도 뭔가 원하는 게 보인대요.","여기까지 왔으니 무엇을 원하는지 짐작할 수 있대요."},nx=1503,nt="Forged Steel"},
[1503]={a={"서슬갈기 가시멧돼지가 툰그림 야영지를 털었대요.","철 상자를 훔쳐 갔고 안에는 단조된 강철 주괴가 있대요.","가시멧돼지 야영지에서 그 철 상자를 찾아 달래요."}},
[1504]={a={"간룰 블러드아이는 서판에 소환의 문양이 있다고 해요.","네루 파이어블레이드의 천막 안 원에서 보이드워커를 부르래요.","보이드워커를 물리치고 문양을 가져와 달래요."},c={"간룰은 비슷한 보이드워커 소환법을 알려 준대요.","당신이 기대에 잘 맞춰 왔다고 칭찬해요.","앞으로 더 힘든 일이 남았으니 우쭐하지 말래요."}},
[1505]={a={"크랑 스톤후프는 위대한 전사도 겸손히 배운대요.","우제크는 수없이 많은 전투를 치른 노련한 전사래요.","전초 기지에서 젊은 전사들을 가르치는 그를 만나래요."},nx=1498,nt="Path of Defense"},
[1506]={a={"오페크는 간룰 블러드아이가 당신을 바로 보고 싶대요.","간룰은 원로 흑마법사들과 Cleft of Shadow에 있대요.","간룰을 만나러 가 보라고 해요."},c={"간룰은 오페크가 당신을 찾을지 걱정했대요.","이제 흑마법 훈련을 더 가르칠 때라고 해요.","하던 일은 잠시 미루라고 해요."},nx=1501,nt="Creature of the Void"},
[1507]={a={"간룰 블러드아이가 소환 마법을 배울 때가 왔대요.","서큐버스는 사랑과 헌신이 담긴 물건으로 유인한대요.","오래된 흑마법사 카줄에게 가 보래요."},c={"아직 길이 낯설지만 큰 재능이 보여요.","그 재능을 헛되이 쓰지 말래요."},nx=1508,nt="Blind Cazul"},
[1508]={a={"눈이 먼 카줄이 당신에게 길을 알려 주겠대요.","오그리마 절벽에 사는 잔카자는 돌아올 짝을 기다리고 있대요.","잔카자를 찾아가 달래요."},c={"소식을 가져왔나요? 며칠 전 돌아왔어야 했어요.","그런데 아무 소식도 듣지 못했어요."},nx=1509,nt="News of Dogran"},
[1509]={a={"잔카자의 짝 Dogran이 교차로로 임무를 떠났대요.","돌아와야 할 날이 지났는데도 소식이 없대요.","교차로의 가즈로그에게 소식을 물어봐 달래요."},c={"잔카자의 짝 맞죠? 소식은 들었지만 전하기 어려워요.","죽지는 않았지만 다쳐서 quilboar의 포로가 됐대요."},nx=1510,nt="News of Dogran"},
[1510]={a={"도그란은 타우라조 야영지에서 크게 다쳤어요.","상처가 곪아서 먼저 치료해야 옮길 수 있대요.","말라카진의 트롤에게 치유의 술을 구해 달래요."},c={"도그란은 끝내 살아나지 못했대요.","고블린들 손에 당했다고 하네요."},nx=1511,nt="Ken'zigla's Draught"},
[1511]={a={"켄지글라가 치유의 술을 미리 준비해 뒀어요.","한 번에 다 주면 안 되고 나눠 줘야 한대요.","그런트 로그마르에게 술을 전해 달래요."},c={"드디어 왔군요! 도그란이 많이 기다렸어요.","그런트들 대부분 식량을 구하러 나가 있대요."},nx=1515,nt="Dogran's Captivity"},
[1512]={a={"그런트 도그란은 몸이 불편해 괴로워해요.","젊은 잔카자가 자기 때문에 고통받을까 걱정해요.","진흙 투성이 목걸이를 간룰 블러드아이에게 전해 달래요."},c={"이걸로 충분하다면 믿을게요.","목걸이를 직접 닦아 준대요."},nx=1513,nt="The Binding"},
[1513]={a={"간룰 블러드아이는 도그란 일을 잔카자에게 알려야 해요.","당신의 마법 실력을 믿는대요.","도그란의 목걸이로 서큐버스를 불러 제압해 달래요."},c={"해냈군요! 내 제자답다고 생각했어요.","이제 제압한 서큐버스를 부리는 법을 알려 준대요.","그 슬픔은 어른들에게 맡기고 기억해 두래요."}},
[1515]={a={"그런트 로그마르는 더 보낼 인력이 없대요.","도그란이 북쪽 가시멧돼지 야영지에 갇혀 있대요.","켄지글라의 술을 도그란에게 직접 가져다 달래요."},c={"술 맛은 끔찍하지만 힘이 솟는대요.","이제 절뚝거리며 도망칠 만큼 힘이 생겼대요.","하지만 다리와 팔은 평생 잃게 됐대요."},nx=1512,nt="Love's Gift"},
[1516]={a={"카나가 어스콜러는 나의 힘이 강해졌다고 해요.","준비가 되면 대지의 원소가 내 일부가 된대요.","북쪽의 하급 지옥사냥개 발굽을 가져오래요."},c={"카나가 어스콜러가 준비가 됐다고 칭찬해요.","대지는 모든 것의 바탕이고 인내를 준대요.","이제 정기를 만들어 줄 테니 받으래요."},nx=1517,nt="Call of Earth"},
[1517]={a={"카나가 어스콜러가 정기라는 음료를 설명해요.","정기는 영혼을 원소에 묶고 신성한 곳에서만 마셔요.","남서쪽 정기 바위를 찾아 거기서 마시래요."},c={"하급 대지의 현신이 나를 반긴대요.","겸손히 대지 앞에 서면 이 의식은 통과래요.","다른 원소들은 그렇게 얌전하지 않대요."},nx=1518,nt="Call of Earth"},
[1518]={a={"하급 대지의 현신이 거친 석영을 건네요.","이 조약돌이 토템의 심장이 될 거래요.","시험의 골짜기 카나가 어스콜러에게 가져가래요."},c={"카나가 어스콜러가 토템을 만들어 주겠대요.","토템은 주문의 초점이 되고 대지와 이어진대요.","지혜를 얻으면 대지의 능력이 더 열린대요."}},
[1519]={a={"예언자 레이븐페더는 내가 이미 지혜롭다고 해요.","대지의 가르침은 시험을 거쳐야 받을 수 있대요.","동쪽 뾰족털일족 주술사에게서 의식의 물약을 구해 오래요."},c={"예언자 레이븐페더가 나를 준비됐다고 해요.","대지는 존중해야 나를 지켜 준대요.","이제 정기를 만들어 주겠대요."},nx=1520,nt="Call of Earth"},
[1520]={a={"예언자 레이븐페더가 정기라는 음료를 알려 줘요.","정기는 영혼을 원소에 묶어 주는 음료래요.","코도 바위를 찾아 정기를 마시라고 해요."},c={"하급 대지의 현신이 나를 반긴대요.","겸손히 대지 앞에 서면 이 의식은 통과래요.","다른 원소들은 그렇게 얌전하지 않대요."},nx=1521,nt="Call of Earth"},
[1521]={a={"하급 대지의 현신이 거친 석영을 건네요.","이 조약돌이 토템의 심장이 될 거래요.","나라체 야영지의 예언자 레이븐페더에게 가져가래요."},c={"예언자 레이븐페더가 토템을 만들어 주겠대요.","토템은 주문의 초점이 되고 대지와 이어진대요.","지혜가 쌓이면 트레이너가 알려 준대요."}},
[1522]={a={"시안 파이어워더는 나의 대지 실력이 강하다고 봤대요.","크라날 피스가 불의 원소를 가르칠 수 있대요.","불모의 땅에서 크라날 피스를 찾아가래요."},nx=1524,nt="Call of Fire"},
[1523]={a={"사니스 프레임위버가 오랜만에 나를 시험하려 해요.","불의 원소를 알려면 파괴와 혼돈도 알아야 한대요.","불모의 땅에서 크라날 피스를 찾아가래요."},nx=1524,nt="Call of Fire"},
[1524]={a={"크라날 피스는 불의 토템을 쓸 힘은 있지만 덜 준비됐대요.","듀로타 성난남녘 강 옆 오솔길로 높은 봉우리에 올라가래요.","희미한 불꽃의 제단 텔프 줄람에게 횃불을 전하래요."},nx=1525,nt="Call of Fire"},
[1525]={a={"텔프 줄람은 내가 영원의 불꽃을 얻으러 온 걸 알아요.","나를 불에 묶을 정기를 만들려면 재료가 필요해요.","칼바위 언덕 근처에서 불붙인 타르와 시약 주머니를 구해 오래요."},c={"텔프 줄람이 이 재료들이 좋다고 해요.","불은 파괴뿐 아니라 생명과 창조도 뜻한대요.","서로 반대되는 힘은 함께여야 의미가 있대요."},nx=1526,nt="Call of Fire"},
[1526]={a={"텔프 줄람이 불의 정기를 완성했대요.","이제 불꽃과 마주할 차례래요.","산 정상의 하급 불의 현신을 빨리 쓰러뜨리래요."},c={"불씨를 넣자 화로에 새하얀 불꽃이 피어올라요.","정기의 마법이 몸을 타고 흐르는 게 느껴져요.","횃불 끝을 화로에 넣자 바로 불이 붙어요."},nx=1527,nt="Call of Fire"},
[1527]={a={"영원의 불꽃 횃불을 들고 화로를 떠나요.","바람에 불꽃이 흔들리며 마음이 설레요.","불모의 땅에서 크라날 피스에게 횃불을 가져가래요."},c={"크라날 피스가 내 기운이 횃불보다 밝다고 해요.","계속 가면 원소를 다스리고 사람들을 이끌게 된대요.","그리고 새 토템을 선물로 준대요."}},
[1528]={a={"시안 파이어워더는 내가 불의 힘에 강하다고 봤대요.","이슬렌 워터시어가 물의 원소를 가르칠 수 있대요.","분노의 강을 따라 남쪽으로 가라고 해요."},c={"이슬렌 워터시어가 물의 순수함을 배울 때라고 해요.","지금까지 온 길이 더 멀리 가게 힘을 준대요.","첫걸음은 내가 떼어야 한대요."},nx=1530,nt="Call of Water"},
[1529]={a={"사니스 프레임위버가 오랜만에 나를 시험하려 해요.","이제 물의 순수함을 배울 때가 됐대요.","동쪽 해안 어부 오두막의 이슬렌 워터시어를 찾래요."},c={"이슬렌 워터시어가 물의 순수함을 배울 때라고 해요.","바람과 땅과 불을 거쳐 온 길이 힘을 줘요.","첫걸음은 내가 떼어야 한대요."},nx=1530,nt="Call of Water"},
[1530]={a={"이슬렌 워터시어는 물이 곧 소생을 뜻한다고 해요.","하지만 물이 오염되면 모든 것을 황폐하게 만든대요.","불모의 땅 남쪽 깊은 곳에 사는 브린을 찾아가 보래요."},c={"브린은 무엇을 물으려는지 짐작하는 눈치예요.","가시멧돼지가 사방에 있는데 왜 여기 사느냐고 해요.","여기까지 찾아온 이유는 둘 다 알 거라고 해요."},nx=1535,nt="Call of Water"},
[1531]={a={"시안 파이어워더는 내가 바람의 부름에 응할 준비가 됐대요.","프레이트 클라우드시어가 바람의 부름을 도와줄 수 있대요.","버섯구름 봉우리 동쪽 굴에서 그녀를 찾으래요."},c={"프레이트 클라우드시어가 바람의 토템을 주겠대요.","주문을 집중하고 바람의 정령을 부를 힘을 준대요.","준비되면 다시 와서 더 훈련하래요."},nx=79360,nt="Elemental Aid"},
[1532]={a={"사니스 프레임위버가 나의 성장을 자랑스러워해요.","바람의 원소는 다루기 어렵지만 나를 믿는대요.","버섯구름 봉우리 동쪽에서 프레이트 클라우드시어를 찾래요."},c={"프레이트 클라우드시어가 바람의 토템을 주겠대요.","주문을 집중하고 바람의 정령을 부를 힘을 준대요.","준비되면 다시 와서 더 훈련하래요."},nx=79360,nt="Elemental Aid"},
[1534]={a={"브린이 이슬렌에게 가져갈 마지막 물을 구해 달래요.","잿빛 골짜기 별가루의 폐허에 작은 샘이 있대요.","그 샘물을 빈 파란색 물주머니에 담아 오래요."},nx=220,nt="Call of Water"},
[1535]={a={"브린 말로는 깨우침을 얻으려면 가장 순수한 물을 찾아야 한대요.","브린의 집 아래 연못에서 빈 갈색 물주머니를 채워 달래요.","그 물을 다시 가져와 달래요."},c={"연못 물을 뜨려 했다면 피를 볼 수도 있었대요.","가시멧돼지는 모든 생명이 이어져 있다는 걸 모르는 것 같대요.","그들이 뭉치면 좋을 텐데 브린은 아쉬워해요."},nx=1536,nt="Call of Water"},
[1536]={a={"브린은 옛날 힐스브래드 구릉지에 간 적이 있대요.","타렌 밀농장 한가운데 신선한 샘물 우물이 있대요.","빈 빨간색 물주머니에 그 물을 담아 가져다 달래요."},nx=1534,nt="Call of Water"},
[1560]={a={"투가는 저녁거리를 구하러 나갔다가 길을 잃었대요.","아내 토르타가 스팀휘들 항구 남쪽에서 기다리고 있대요.","토르타에게 데려다 달라고 부탁해요."}},
[1656]={a={"안투르 팰로우는 힘의 의식을 치르는 중이래요.","지쳐서 아버지가 맡긴 모피를 옮길 수 없대요.","블러드후프 마을 여관에 모피 묶음을 대신 전해 달래요."},c={"카우스는 모피가 빨리 와서 고맙다고 해요.","모피는 머무는 손님의 담요가 된대요.","여관은 언제든 열려 있으니 쉬어 가래요."}},
[1690]={a={"선임기술자 빌지위즐은 가젯잔 수자원개발회사에서 일해요.","사막유랑단이 우물을 거의 다 빼앗아 물이 곧 바닥날 판이래요.","동쪽의 사막유랑단 녀석들을 처단해 달래요."},c={"빌지위즐은 사막유랑단이 줄어 우물을 되찾을 궁리를 할 수 있대요.","그래도 유랑단과의 싸움은 아직 멀었다고 해요."},nx=1691,nt="More Wastewander Justice"},
[1691]={a={"빌지위즐은 이번엔 더 강한 사막유랑단을 상대하라고 해요.","그들은 동쪽과 남동쪽에 있고 아주 지독하대요.","사막유랑단 도적, 암살자, 어둠마법사를 처치해 달래요."},c={"빌지위즐은 아주 잘했다며 이제 유랑단을 공격할 수 있대요.","아직이라면 양수기기사 루글룬켓에게 가 보래요."}},
[1707]={a={"양수기기사 루글룬켓이 중요한 일을 맡기고 싶대요.","물주머니는 원래 우리 물인데 사막유랑단이 훔쳐 갔대요.","사막에서 물주머니를 구해 가져다 달래요."},c={"루글룬켓은 물주머니를 많이 찾을수록 재앙에서 멀어진대요.","물주머니를 가져올 때마다 보상을 주겠대요."}},
[1712]={a={"바람의감시자 바스라는 오랜 세월 이곳을 지켜봤대요.","사이클로니안을 쓰러뜨릴 강자를 아직 못 찾았대요.","양피지에 적힌 물건을 모아 가져오래요."},nx=1713,nt="The Summoning"},
[1713]={a={"바스라는 사이클로니안을 소환할 의식을 준비했대요.","소환되면 물리치고 소용돌이의 눈을 꺼내야 한대요.","소용돌이의 눈을 가져오면 무기에 힘을 넣겠대요."},c={"바스라는 해냈다며 기뻐해요.","사이클로니안을 물리치고 소용돌이의 눈을 얻었대요."},nx=1792,nt="Whirlwind Weapon"},
[1718]={a={"토름 레이지토템이 나의 명성이 커졌다고 말해요.","톱니항 남쪽 격투의 섬에서 전사들이 겨룬대요.","섬의 교관 클라녹 맥클라우드와 대화해 보래요."},c={"클라녹 맥클라우드가 격투의 섬에 온 나를 반겨요.","섬이 마음에 들었으면 좋겠대요."},nx=1719,nt="The Affray"},
[1719]={a={"클라녹 맥클라우드는 광전사의 자세를 배우려면 격투에서 이기라고 해요.","격투의 섬에서 트위기 플랫헤드가 도전자를 내보낼 거래요.","마지막에 싸움꾼 윌을 꺾고 시간 안에 돌아와 달래요."},c={"클라녹 맥클라우드는 시험을 통과했다며 칭찬해요.","훌륭한 전사라서 가르치게 돼 영광이래요."},nx=1791,nt="The Windwatcher"},
[1740]={a={"도안 카르한은 악마의 영혼이 갇힌 수정구를 연구해요.","수정구가 깨져서 조각들이 여기저기 흩어졌대요.","조각을 찾아 가져다주면 다시 맞춰 보겠대요."},c={"다행히 조각이 거의 다 모였대요.","원하는 모습으로 수정구를 다시 완성해 준대요."}},
[1791]={a={"클라녹 맥클라우드 말로는 광폭 태세를 배웠으니 무기가 필요하대요.","바람의감시자 바스라는 솜씨 좋은 무기 제작자이자 주술사래요.","타렌 밀농장 동쪽 강을 따라 북쪽으로 찾아가라고 해요."},c={"먼 길을 왔다며 눈에 불꽃이 보인다고 해요.","강력한 무기를 찾는 거냐고 물어요.","그쪽 일을 도와주는 대신 자기 일도 도와 달래요."},nx=1712,nt="Cyclonian"},
[1795]={a={"스트라드 파선은 지옥사냥개를 소환하려 해요.","지옥사냥개는 아주 강한 적이라고 경고해요.","비밀의 고서로 지옥사냥개를 불러 제압해 달래요."}},
[1796]={a={"미네라 보이드렌더가 마법의 황금 혈로브를 만들려 해요.","그 로브가 전투에서 더 강해질 첫 물건이래요.","아카나의 로브를 가져다 달래요."},c={"이 정도면 아주 좋대요.","마법 물건은 좋은 바탕에서 시작해야 한대요."},nx=4781,nt="Components for the Enchanted Gold Bloodrobe"},
[1799]={a={"미네라 보이드렌더가 다음 일을 맡기려 해요.","잊혀진 땅에서 지옥의 보주를 찾아야 한대요.","보주를 먼지진흙 습지대의 타베사에게 가져가래요."},c={"미네라가 보냈다니 알겠대요.","잠시 손님으로 머물러도 좋대요.","당신에게도 타락이 가까이 있는 것 같대요."},nx=4961,nt="Cleansing of the Orb of Orahil"},
[1801]={a={"스트라드 파선은 비밀의 고서를 잃어버렸대요.","조라 애니슨이 고대 서적을 잘 안대요.","언더시티에 있는 조라 애니슨을 찾아가 보래요."},c={"지도는 현실을 어림잡은 그림일 뿐이래요.","진실은 책과 이야기 속에 있대요."},nx=1803,nt="Tome of the Cabal"},
[1803]={a={"조라 애니슨은 비밀의 고서를 찾고 있대요.","떨어진 반쪽은 버섯구름 봉우리에 있다는 소문이래요.","곰팡이 슨 고서와 너덜너덜한 필사본을 가져다 달래요."},c={"이제 완전한 비밀의 고서가 손에 들어왔대요.","잠깐 책장을 넘겨 보게 해 달래요."},nx=1805,nt="Tome of the Cabal"},
[1805]={a={"조라 애니슨은 이 고서를 흥미롭게 읽었대요.","스트라드가 정신 집중의 마법봉을 찾으라고 했대요.","복원된 고서와 마법봉을 톱니항의 스트라드에게 가져다 달래요."},c={"고서와 마법봉을 잘 가져왔네요.","젊은 흑마법사가 지옥사냥개에 도전하는 건 오랜만이래요."},nx=1795,nt="The Binding"},
[1818]={a={"오스틸 드 몽 말로는 죽음의경비병 딜링거가 일거리를 준비했대요.","어둠의 여왕님께 가치를 증명하려면 바로 찾아가래요.","브릴 서쪽 끝 공동 묘지 근처 초소에 있대요."},c={"임무를 받으러 왔냐며 좋다고 해요.","중요한 임무라서 전투 실력과 포세이큰을 지키는 각오를 시험한대요."},nx=1819,nt="Ulag the Cleaver"},
[1819]={a={"죽음의경비병 딜링거는 사로잡은 역병 병사를 연구해 왔대요.","학살자 울라그는 자유로운 의지가 있지만 아직 리치 왕에게 묶였대요.","이제 학살자 울라그를 풀어 주고 처치해 달래요."},nx=1820,nt="Speak with Coleman"},
[1820]={a={"딜링거 말로는 이제 여왕님의 신하에게 가치를 보일 때래요.","콜만 파딩은 포세이큰의 적들에게 복수할 전사를 기다린대요.","브릴 동쪽 갤로우 선술집에서 그를 찾아가 보래요."},c={"콜만 파딩은 전투 실력이 필요하다고 해요.","형편은 넉넉지 않지만 일이 자기와 포세이큰 모두에게 도움이 된대요.","해내면 보상은 두 배래요."},nx=1821,nt="Agamand Heirlooms"},
[1821]={a={"콜만 파딩은 자신을 죽게 한 아가만드 가문을 원망해요.","그 가문에 남은 가보를 빼앗아 오라고 해요.","아가만드 가문의 묘지에 가서 가보를 가져다 달래요."},c={"콜만 파딩은 가보를 다 찾아와서 기뻐해요.","이제 아가만드 가문에 남은 명예와 기억도 사라졌대요.","그 가문은 정말 끝났다고 말해요."},nx=1822,nt="Heirloom Weapon"},
[1823]={a={"토름 레이지토템이 나를 실력 있는 전사라고 해요.","루가 레이지토템의 시험을 치를 준비가 됐는지 묻대요.","불모의 땅 타우라조 야영지에서 루가를 찾으래요."},c={"루가 레이지토템이 시험을 받으러 왔냐고 물어요."},nx=1824,nt="Trial at the Field of Giants"},
[1824]={a={"루가 레이지토템은 시련을 치르려면 거인의 들판으로 가라고 해요.","그곳 곤충 무리가 불모의 땅에 새로 온 게 못마땅하대요.","아직 꿈틀거리는 더듬이를 서둘러 가져와 달래요."},c={"루가 레이지토템은 잘했다며 칭찬해요.","거인의 들판 시련을 통과해 전사의 길을 한 걸음 나아갔대요."},nx=1825,nt="Speak with Thun'grim"},
[1825]={a={"루가 레이지토템 말로는 호드를 위한 활약이 소문났대요.","툰그림 파이어게이즈가 갑옷을 하나 만들어 주고 싶대요.","지금 바로 크로스로드 동쪽 야영지를 찾아가 보래요."},c={"툰그림은 찾아와 줘서 좋다고 해요.","둘이 나눌 얘기가 많다고 해요."},nx=1838,nt="Brutal Armor"},
[1838]={a={"툰그림 파이어게이즈가 용맹한 이야기를 듣고 갑옷을 만들려 해요.","갑옷 만들기도 하나의 임무라서 호드 대장장이들의 도움이 필요하대요.","두루마리의 재료를 가져오면 첫 조각을 만들어 준대요."},c={"툰그림은 요구한 걸 다 가져왔다며 이제 자기 몫을 하겠대요."},nx=1848,nt="Brutal Hauberk"},
[1839]={a={"트롤 대장장이 울라엘렉이 투사 건틀릿을 만들어 줄 거래요.","그는 검은창 동료들과 듀로타 센진 마을에 살아요.","울라엘렉이 기다리고 있으니 찾아가 보래요."},c={"울라엘렉은 툰그림이 소식을 전했다며 반겨요.","정령들이 지켜봤는데 적들이 많이 쓰러졌대요."},nx=1842,nt="Satyr Hooves"},
[1840]={a={"옴 스톤후프는 솜씨로 존경받는 장인이래요.","그가 투사 투구를 만들어 줄 거래요.","썬더 블러프 중앙 토템 옆 연못가에서 찾아보래요."},c={"옴 스톤후프는 툰그림에게 들었다며 투구를 원하냐고 물어요.","자신을 옴이라고 소개하며 인사해요."},nx=1844,nt="Chimaeric Horn"},
[1841]={a={"벨로라 나이틀리는 죽기 전 최고의 갑옷 장인이었대요.","죽고 나서도 실력은 줄지 않았대요.","언더시티 교역 구역에서 벨로라를 찾아가 보래요."},c={"벨로라는 다리 갑옷을 찾아왔냐며 반갑게 맞아요.","농담을 던졌는데 재밌었는지 자기도 모르겠대요.","웃는 감각도 숨을 멈춘 무렵 잃었대요."},nx=1846,nt="Dragonmaw Shinbones"},
[1842]={a={"울라엘레크는 잔인한 건틀릿을 만들어 줄 수 있대요.","건틀릿에 쓸 마법은 사티로스 발굽에 있대요.","잿빛 골짜기의 사티로스 발굽을 가져오래요."},c={"울라엘레크가 발굽을 받고 기뻐해요.","사티로스가 골짜기 힘을 빨아들인 것처럼 발굽의 힘을 쓰겠대요."},nx=1843,nt="Brutal Gauntlets"},
[1844]={a={"오름 스톤후프가 투구를 만들어 주겠대요.","Charred Vale은 한때 푸르렀지만 더럽혀졌대요.","그곳의 키메라 우두머리를 처치해 번개 뿔을 가져오래요."},c={"오름 스톤후프가 나의 가치와 결의를 인정해요.","이제 투구는 내 것이 된대요."},nx=1845,nt="Brutal Helm"},
[1846]={a={"벨로라 나이틀리는 투사 다리보호구를 만들 뼈가 필요하대요.","저습지의 용아귀 오크들이 튼튼하고 두꺼운 정강이뼈를 가졌대요.","맨손으로 부러지는 뼈는 쓸 수 없으니 꼭 시험해 보래요."},c={"벨로라는 뼈가 모두 튼튼해 보인다며 흡족해해요.","오크들이 불평 많이 했냐고 농담을 던져요.","웃지 않는 걸 보고 요즘 농담이 재미없나 싶대요."},nx=1847,nt="Brutal Legguards"},
[1858]={a={"테르조크가 타잔의 가방을 열어 달라고 해요.","열쇠는 술꾼 조수 Gamon이 갖고 있대요.","조용히 열쇠를 빼 가방 속 물건을 가져오래요."},c={"테르조크가 나를 흥미롭다며 인정해요.","나를 Shattered Hand의 새 단원으로 삼겠대요."}},
[1859]={a={"카플라크가 나의 전투 실력에 대해 들었대요.","가끔 몰래 하는 일도 마다하지 않을 거라 해요.","오그리마의 테르조크에게 제안을 들으러 가래요."},nx=1963,nt="The Shattered Hand"},
[1881]={a={"케인 파이어송 말로는 아나스타샤 하트웰이 맡길 임무가 있대요.","포세이큰 마법사들을 위한 첫 임무라서 재능 있는 자에게 맡긴대요.","언더시티 마법 지구에서 아나스타샤를 만나 보래요."},c={"아나스타샤 하트웰은 부름에 응한 걸 현명하다고 칭찬해요.","다음 말을 잘 들으면 더 현명하겠다고 해요."},nx=1882,nt="The Balnir Farmstead"},
[1882]={a={"아나스타샤 하트웰은 역병이 티리스팔에 얼마나 퍼졌는지 알고 싶어 해요.","티리스팔 동쪽 발니르 농장 정원에 금어초가 있대요.","그 금어초를 모아 가져다 달래요."}},
[1883]={a={"센진 마을의 부족 마법사 운투와가 도움을 청해요.","듀로타의 마법 흐름에 방해 요소가 있다고 해요.","운투와와 얘기해서 어떻게든 도와 달래요."},c={"운투와가 도움 요청에 응해 준 나에게 감사해요.","이제 이 일을 감당할 수 있기를 바란대요."},nx=1884,nt="Ju-Ju Heaps"},
[1884]={a={"메아리 섬의 흑마법사 잘라제인이 마법 흐름을 흐트러뜨렸대요.","오염된 우상 주주 해골로 동식물을 타락시킨대요.","주주 해골을 부수고 센진 마을의 운투와에게 돌아오래요."}},
[1885]={a={"마리언 콜은 칼카드님이 관심 가진 자를 보고 뜻밖이래요.","겉모습으로 사람을 판단할 순 없다고 해요.","가능한 빨리 메넷 칼카드를 찾아가 보래요."},nx=1886,nt="The Deathstalkers"},
[1886]={a={"메넷 칼카드는 죽음의추적자가 되려면 실력을 증명하라고 해요.","이 일은 목숨이 위험할 수 있어서 자세한 건 모르는 게 낫대요.","전령 아스토르 하드렌의 소지품을 구해 오래요."},c={"메넷 칼카드는 첫 시험을 통과했다고 칭찬해요.","안드론이 눈치채지 않으면 전령으로 믿게 할 수 있을 거래요."},nx=1898,nt="The Deathstalkers"},
[1898]={a={"메넷 칼카드는 바리마트라스님이 안드론을 의심한다고 해요.","다른 단체를 돕는 증거를 찾아오라고 하셨대요.","연금술 실험실 근처 상점에서 안드론을 만나 보래요."},nx=1899,nt="The Deathstalkers"},
[1899]={a={"안드론 건트는 고용주가 찾는 정보가 담긴 장부를 가졌대요.","장부는 그의 뒤 책장에 있대요.","그 장부를 메넷 칼카드에게 전하고 안부도 전해 달래요."},nx=1978,nt="The Deathstalkers"},
[1918]={a={"쓰러진 정령에게서 빛나는 물구슬이 나왔어요.","구슬 속 물에도 미스트랄 호수를 더럽힌 게 있을 거래요.","토막나무 주둔지의 마스토크 윌리히스에게 가져가래요."},c={"이런 물건을 나에게 가져오다니요.","그래도 Earthen Ring이 필요할지도 모른대요.","Earthen Ring이 누군지 아느냐고 묻네요."},nx=824,nt="Je'neu of the Earthen Ring"},
[1943]={a={"아나스타샤 하트웰은 트롤 마법사 다이노가 도움을 원한다고 해요.","다이노는 오그리마 검은장미 오두막에 있대요.","그녀를 찾아가 도와 달래요."},nx=1944,nt="Waters of Xavian"},
[1944]={a={"다이노는 사비안의 물에 큰 마법의 힘이 있대요.","사티로스가 옛 도시를 차지해 마법사를 싫어한대요.","사비안 폭포의 물을 병에 담아 가져오래요."},c={"다이노가 사비안 견본을 받고 고마워해요.","사티로스가 별로 방해하지 않았냐고 물어요.","이 견본을 바로 연구하겠대요."},nx=1945,nt="Laughing Sisters"},
[1945]={a={"다이노가 새 로브를 만들어 주겠대요.","재료로 미소띤 자매의 머리카락이 필요하대요.","라이네나무 은신처 근처에서 구해 킬할라에게 가져가래요."},c={"킬할라가 이 머리카락으로 로브를 짤 수 있대요.","미소띤 자매가 죽어야 했던 게 안타깝대요."},nx=1946,nt="Nether-lace Garment"},
[1947]={a={"울신 굴이 내가 마법사 지팡이를 받을 때라고 해요.","먼저 먼지진흙 습지대의 은둔자 타베사와 얘기해야 한대요.","테라모어 서쪽 오두막의 타베사를 찾아가래요."},c={"타베사가 방해하지 말고 잠시 기다리래요."}},
[1948]={a={"타베사가 마법사의 지팡이를 만들 재료를 부탁해요.","지팡이에는 희귀한 재료와 마력을 담을 그릇이 필요해요.","양피지 목록대로 재료를 정확히 가져오래요."},c={"타베사가 비취와 벼락 맞은 나뭇가지를 잘 구했대요.","번개가 토템 막대를 칠 때 너무 가까웠던 것 같대요.","번개를 맞는 건 행운이라고 해요."}},
[1949]={a={"타베사는 지팡이를 만들려면 책의 구절을 읽어야 한대요.","그 책은 학자 틸스에게서 직접 받아야 한대요.","소금 평원에서 틸스를 찾아가 얘기해 보래요."},nx=1950,nt="Get the Scoop"},
[1950]={a={"학자 틸스의 책은 마법으로 잠긴 금고에 있대요.","그런데 금고를 여는 주문을 잊어버렸대요.","조수를 찾아 데려오거나 주문을 알아 달래요."},nx=1951,nt="Rituals of Power"},
[1951]={a={"학자 틸스가 노름 빚 때문에 책을 팔았대요.","책은 붉은십자군 수도원 도서관에 있을 거래요.","그 책을 찾아 먼지진흙 습지대의 타베사에게 가져다 달래요."}},
[1953]={a={"울신 굴이 타베사와 얘기할 때가 됐대요.","타베사는 먼지진흙 습지대의 은둔자래요.","테라모어 서쪽 오두막으로 찾아가 달래요."},c={"타베사가 보주나 지팡이를 원하냐고 물어요.","과정이 위험해서 누군가 죽을 수도 있대요.","그래도 만드는 걸 도와주겠다고 해요."},nx=1954,nt="The Infernal Orb"},
[1954]={a={"타베사는 보주를 만들 첫 단계가 필요하대요.","불타는칼날단 흑마법사들이 보주 안에 악마를 묶어 뒀대요.","잊혀진 땅에서 소환사의 보주를 빼앗아 오래요."},c={"타베사가 보주를 보고 좋다가 말을 바꿨어요.","그러니 정신을 차리라고 나무라요."},nx=1955,nt="The Exorcism"},
[1955]={a={"타베사가 보주 안의 악마를 쫓아내려고 해요.","쫓아낸 뒤 악마를 재빨리 물리쳐야 한대요.","가장 강한 마법을 준비해 악마와 싸워 달래요."},c={"타베사가 악마에게 교훈을 줬다며 칭찬해요.","다음엔 큰 친구들을 데려올지도 모른대요."},nx=1956,nt="Power in Uldaman"},
[1956]={a={"타베사가 악마를 없앴으니 마력원천이 필요하대요.","가장 강한 마력원천은 보통 오래되고 얻기 힘들대요.","울다만의 흑요석 파수꾼을 물리쳐 달래요."},c={"타베사가 잘했다며 기뻐해요.","동료들이 못 할 거라고 했었대요."},nx=1957,nt="Mana Surges"},
[1957]={a={"타베사가 빈 보주에 힘을 채울 준비를 마쳤어요.","마력의 균열에서 마력의 폭풍이 쏟아져 나온대요.","균열이 닫히기 전에 폭풍을 물리쳐 달래요."},c={"타베사가 해냈다며 기뻐해요.","잠깐 의심했지만 대부분은 믿었대요."},nx=1958,nt="Celestial Power"},
[1959]={a={"케인 파이어송 말로는 언더시티 마법사들이 전갈을 보냈대요.","도시 안에 마법 장애가 생겨 조사할 호드 마법사를 찾는대요.","언더시티 마법 지구의 아나스타샤 하트웰을 찾아가 보래요."},c={"아나스타샤는 도시에서 마법 장애가 맞다고 해요.","그 원인이 나쁜지 좋은지는 아직 모른대요.","먼저 정보를 더 모아야 해서 이제 임무를 맡기겠대요."},nx=1960,nt="Investigate the Alchemist Shop"},
[1960]={a={"아나스타샤 하트웰은 연금술 상점 근처에 이상한 기운이 느껴진대요.","보이지 않는 마법 생물들이 상점을 돌아다니고 있대요.","그 생물들을 잡아 와 달라고 부탁해요."},c={"아나스타샤는 잘했다고 칭찬하며 생물들을 연구하겠대요.","이 생물들이 왜 언더시티에 나타났는지 밝혀낼 거래요.","마법의 공격이라면 더 큰 일에 대비해야 한대요."},nx=1961,nt="Gathering Materials"},
[1961]={a={"아나스타샤가 첫 마법사의 로브를 입을 때가 됐대요.","은빛소나무 숲의 달라란 마법사들에게서 마나석을 모아야 해요.","마나석과 리넨을 조셉 그레고리안에게 가져다 달래요."},c={"조셉은 리넨이 아주 좋은 재료라고 해요.","마나석에 로브를 만들 힘이 있는지 곧 알게 된대요."},nx=1962,nt="Spellfire Robes"},
[1963]={a={"테르조크는 대족장의 방식이 너무 신중하대요.","그는 으스러진 손으로 호드의 자부심을 되찾고 싶대요.","톱니항 근처의 타잔을 처치하고 가방을 가져다 달래요."},nx=1858,nt="The Shattered Hand"},
[1978]={a={"메넷 칼카드가 비밀결사대 얘기에 크게 놀랐대요.","알터랙의 지배자들이 세력을 많이 잃은 것 같대요.","이 소식을 바리마트라스에게 직접 전해 달래요."},c={"메넷은 죽음의추적자들이 이 일을 잘 해냈다고 해요.","나도 칭찬받을 만하다고 했대요.","앞으로도 이런 일을 맡기고 싶다고 해요."}},
[1998]={a={"메넷 칼카드에게 바리마트라스가 보낸 편지가 왔어요.","펜윅 타트로스는 은빛소나무 숲의 죽은 자들을 이끄는 자래요.","그를 처치해 달라고 부탁해요."},nx=1999,nt="Tools of the Trade"},
[1999]={a={"메넷 칼카드가 중요한 문서 얘기를 꺼내요.","달라란의 상황을 적은 문서가 앰버밀에 있대요.","에스텔 젠드리에게 도구를 받고 문서를 찾아 달래요."},c={"메넷은 자물쇠 따는 솜씨가 훌륭하다고 칭찬해요.","예상보다 훨씬 빨리 배웠다며 놀라워해요.","이 일에서 크게 성공할 거라고 믿는대요."}},
[2161]={a={"우코르는 식량 보따리를 들고 시험의 골짜기에 갔대요.","그곳은 음식이 필요 없었고 돌아가는 길의 짐승이 무섭대요.","칼바위 언덕 여관주인 그로스크에게 짐을 전해 달래요."},c={"그로스크는 음식을 돌려줘서 고맙다고 해요.","음료를 대접하며 여관에서 쉬어 가라고 해요."}},
[2202]={a={"카르가스의 자칼 모스멜드는 새 식물을 연구하고 있어요.","울다만 발굴 현장 깊은 곳에 자홍버섯이 무리 지어 자란대요.","자홍버섯을 찾아 가져다 달래요."},c={"자칼 모스멜드는 자홍버섯이 흥미로운 연구 대상이라고 해요.","약속대로 복원의 비약을 맛보라고 해요."},nx=2203,nt="Badlands Reagent Run II"},
[2203]={a={"자칼 모스멜드는 당신에게 조리법을 주고 싶어 해요.","하지만 그러려면 위험한 일을 먼저 해야 한대요.","화염의 수호비룡의 피를 빈 병에 채워 가져오래요."},c={"자칼 모스멜드는 같은 연금술사로서 당신을 치하한대요.","조리법을 건네며 행운을 빌어 준대요."}},
[2258]={a={"이름난 연금술사 자칼 모스멜드가 도움을 청해요.","비축해 둔 재료가 부족하대요.","황야의 짐승에게서 재료를 구해 와 달래요."},c={"이 정도면 당분간은 쓸 수 있겠대요.","울다만 깊은 곳의 재료도 구해 줄 수 있냐고 묻네요."},nx=2202,nt="Uldaman Reagent Run"},
[2278]={a={"노르간논의 원반이 보물의 방 가운데 놓여 있어요.","원반을 만지자 바위감시자가 나타나 지식의 파수꾼이라고 해요.","고대 지식을 배우고 원반을 가동해 달래요."},c={"원반에서 희미한 울림이 들려요.","바위감시자는 원반 합성이 끝났으니 개인 사본을 받으라고 해요."}},
[2280]={a={"노르간논의 원반을 다시 만지자 가방이 무거워졌어요.","안에는 작은 원반이 들어 있었어요.","그 원반을 썬더 블러프의 현자에게 가져가 달래요."},c={"현자 트루스시커는 원반에 오랜 비밀이 느껴진대요.","이걸 가져온 건 현명한 일이었대요."},nx=2440,nt="The Platinum Discs"},
[2283]={a={"드란 드로퍼스가 배짱 있으면 일을 맡기겠대요.","황야의 땅 울다만에서 죽은 성기사가 값진 목걸이를 갖고 있었대요.","그 목걸이를 찾아 오그리마로 가져다 달래요."},c={"드란 드로퍼스는 목걸이에서 보석이 빠졌다며 화를 내요.","아직 일이 끝나지 않았대요."},nx=2284,nt="Necklace Recovery, Take 2"},
[2284]={a={"드란 드로퍼스는 보석이 울다만 어딘가에 있을 거래요.","성기사의 유해에 보석이 남아 있을지도 모른대요.","울다만 깊은 곳에서 보석을 찾아 목걸이에 다시 붙여 달래요."},c={"성기사의 유해에서 일지가 나왔어요.","사람의 말로 쓰였지만 번역해야 알 수 있대요."},nx=2318,nt="Translating the Journal"},
[2318]={a={"성기사의 일지는 번역을 해야 읽을 수 있어요.","번역할 사람이 있을 만한 가장 가까운 곳은 카르가스래요.","카르가스에서 찾아보는 게 좋겠대요."},c={"자칼 모스멜드는 당신이 목걸이 때문에 온 걸 안다고 해요.","번역은 자기밖에 못 한다며 더 좋은 제안을 해요."},nx=2338,nt="Translating the Journal"},
[2338]={a={"자칼 모스멜드는 목걸이 마법을 되살릴 지혜가 있대요.","목걸이를 연구하고 싶다며 잠시 빌려 달래요.","그 대가로 일지를 번역해 주겠대요."},c={"자칼 모스멜드는 좋은 거래를 알아본 당신을 믿었대요.","마법으로 일지를 바로 번역해 주겠대요."},nx=2339,nt="Find the Gems and Power Source"},
[2339]={a={"자칼 모스멜드는 일지를 번역해 내용을 알아냈대요.","목걸이를 되살릴 마력원천이 필요하대요.","울다만의 가장 강한 피조물을 처치해 보래요."},nx=2340,nt="Deliver the Gems"},
[2340]={a={"자칼 모스멜드는 마력원천이 통하면 보석을 주겠대요.","오그리마로 가서 드란 드로퍼스와 거래를 끝내래요.","이 거래는 아무에게도 말하지 말래요."},c={"드란 드로퍼스는 목걸이와 보석이 다 있다며 좋아해요.","약속대로 수고비를 주고 나중에 다시 오라고 해요."},nx=2341,nt="Necklace Recovery, Take 3"},
[2341]={a={"드란 드로퍼스와 말톤 드로퍼스가 고물을 두고 다퉈요.","거래의 절반은 끝났대요.","카르가스의 자칼 모스멜드를 찾아가 보래요."},c={"자칼 모스멜드는 마력원천이 기대 이상이었다고 해요.","당신 몫의 목걸이를 만들고 특별한 선물도 준대요."}},
[2342]={a={"패트릭 가레트는 박쥐 우리를 청소하는 신세래요.","울다만 남쪽 대전당의 궤짝에 가문의 무기가 있대요.","그 보물을 찾아 언더시티로 가져다 달래요."},c={"패트릭 가레트는 드디어 가문의 무기를 들었다며 기뻐해요.","박쥐들에게 떨라며 으름장을 놔요."}},
[2378]={a={"메넷 칼카드가 이제 바깥으로 모험을 떠날 때라고 해요.","죽음의추적자에게는 검은손 도적단 안에 동지들이 있대요.","오그리마에 있는 셴툴을 찾아가 보래요."},c={"셴툴은 동맹이 보낸 사람이 이 정도냐며 실망해요."},nx=2379,nt="Zando'zan"},
[2379]={a={"셴툴이 당신의 결심만으로는 부족하대요.","앞의 난관을 넘으려면 훈련이 필요하대요.","그림자 틈의 잔도잔을 찾아가 훈련받으래요."},nx=2382,nt="Wrenix of Ratchet"},
[2380]={a={"카플라크는 당신이 아직 은신 실력이 부족하다고 해요.","그런데 셴툴이 당신을 이름으로 찾았대요.","오그리마의 그림자 틈으로 셴툴을 만나러 가래요."},c={"으스러진 손은 Thrall이 바꾸려는 것에도 경계해야 한대요.","머릿수만으로는 부족하고 은신과 기만을 익혀야 한대요."},nx=2379,nt="Zando'zan"},
[2381]={a={"비운의 레닉스가 보낸 도적들이 모두 갈가리 찢겨 돌아왔대요.","남쪽바다 해적단의 보물이 해적선 타이드 레이저호에 있대요.","해적선에 가서 그 보물을 훔쳐 오래요."},c={"레닉스는 믿기 힘든 솜씨라며 크게 놀라요.","재주가 있거나 아주 운 좋은 사람이라고 해요.","나보다 잘 쓸 거라며 몫을 나눠 줘요."}},
[2382]={a={"잔도잔이 너무 많은 말을 해 버렸대요.","잔도잔이 그날이 왔다고 했대요.","톱니항의 비참한 레닉스를 찾아가 달래요."},nx=2381,nt="Plundering the Plunderers"},
[2383]={a={"고르넥은 당신이 없는 동안 양피지가 왔대요.","상급 전사 프랑이 보낸 것 같대요.","양피지를 읽고 시험의 골짜기의 프랑을 찾아가 달래요."},c={"프랑이 양피지를 보낸 게 맞대요.","강해지면 다시 와서 전사의 길을 배우라고 해요."}},
[2418]={a={"리글퍼즈는 울다만의 신기한 마법석을 연구했어요.","비밀을 알려 준 뒤 드워프들이 그를 쫓아냈대요.","두 종류의 마법석을 가져다 달래요."},c={"찾아와서 정말 고맙대요.","이 돌로 장치를 오래 돌릴 수 있을 거래요."}},
[2440]={a={"현자 트루스시커는 원반을 가져온 당신에게 사례를 하겠대요.","사례 보증 서류를 썬더 블러프의 베나 윈터후프에게 가져가래요.","그러면 현자의 특별한 물건과 비약을 받을 수 있대요."},c={"베나 윈터후프는 현자가 당신을 아주 마음에 들어 했대요.","그 대신 치유 비약이나 마나 비약 중 고를 수 있대요."},nx=2965,nt="Portents of Uldum"},
[2458]={a={"셴툴이 비밀 요원인 감독관 피줄을 만나라고 해요.","투자개발회사가 큰 계획을 세우고 있대요.","진흙늪 북쪽 탑에서 피줄을 찾아가 달래요."},nx=2478,nt="Mission: Possible But Not Probable"},
[2460]={a={"셴툴은 으스러진 손 도적에게 꼭 필요한 경례가 있대요.","이 경례가 조직원을 알아보는 유일한 방법이래요.","보고 배운 뒤 셴툴에게 직접 해 보래요."},c={"셴툴이 잘했다며 이제 다음 단계로 가도 된대요."},nx=2458,nt="Deep Cover"},
[2478]={a={"감독관 피줄이 독이 퍼진 탑에 들어가 달라고 해요.","현장감독 실릭시즈에게서 탑 열쇠를 훔쳐야 한대요.","총감독 갤리윅스를 없애고 혼합물을 셴툴에게 가져가 달래요."},nx=2479,nt="Hinott's Assistance"},
[2479]={a={"셴툴은 당신을 고칠 사람은 서지뿐이래요.","잔질의 혼합물 견본을 들고 가야 한대요.","타렌 밀농장의 서지 히노트에게 전해 달래요."},c={"서지가 당신이 창백해 보인다며 놀라요.","풍기는 고약한 냄새가 뭔지 꼭 알아야겠대요."},nx=2480,nt="Hinott's Assistance"},
[2480]={a={"서지 히노트는 독의 효과에 놀랐대요.","잔질이라는 사람은 들어본 적이 없대요.","해독제를 만드는 동안 기다려 달래요."},c={"해독제가 다 됐대요.","이걸 마시면 퍼지는 광기가 멈춘대요.","다만 풍기는 냄새는 없애지 못한대요."}},
[2521]={a={"수집가 굼이샤는 완전무결한 드레니시스트 구슬을 모으고 있어요.","드레나이들이 이 구슬을 찾아 헤매다 끔찍한 최후를 맞았대요.","저주받은 땅에서 구슬을 찾으면 가져오래요."},c={"굼이샤는 믿을 수 없다며 놀라워해요.","이제 고향으로 돌아갈 길이 열릴지도 모른대요."}},
[2581]={a={"혈법사 드라지알은 칼송곳니하이에나 턱의 힘을 알고 싶대요.","그 턱이 토륨 강철도 물어뜯는다는 얘기가 있대요.","저주받은 땅에서 칼송곳니하이에나 턱을 구해 달래요."},c={"드라지알은 당신에게서 칼송곳니하이에나의 기운이 느껴진대요.","재료가 부족해 한 알만 만들었대요."}},
[2583]={a={"혈법사 드라지알은 멧돼지가 왜 강한지 알고 싶어 해요.","잿빛갈기멧돼지와 지옥멧돼지는 상처를 거의 입지 않는대요.","분석할 재료를 가져다 달래요."},c={"드라지알은 당신에게 멧돼지의 기운이 깃들었다고 해요.","당신도 이 짐승들처럼 상처를 안 입는다고 믿냐고 물어요."}},
[2585]={a={"혈법사 드라지알은 스콜포크의 민첩함을 알약으로 만들고 싶어 해요.","그러려면 먼저 견본을 만들어야 한대요.","스콜포크 집게발과 독수리 모래주머니를 구해 달래요."},c={"드라지알은 이 견본 분석이 가장 어려웠다고 해요.","남은 소금을 혀 밑에 올려 보라고 해요.","잠깐 기분이 좋아지고 아주 민첩해진대요."}},
[2601]={a={"혈법사 린노어는 붉은바위 바실리스크의 뇌를 연구하려고 해요.","바실리스크는 일부 인간형 생물보다 생각이 복잡해 보인대요.","바실리스크 뇌를 모아 와 달래요."},c={"린노어는 놀라워하며 붉은바위 바실리스크 맛보기를 줘요.","마음에 들면 대가를 치르고 더 만들 수 있대요."}},
[2603]={a={"혈법사 린노어는 독수리가 병을 어떻게 견디는지 연구해요.","독수리가 병든 시체도 뜯어 먹는 걸 봤대요.","독수리 모래주머니와 칼송곳니하이에나 턱을 구해 달래요."}},
[2605]={a={"마린 노겐포저는 너무 목이 말라 해결책을 찾고 있어요.","이슬먹는 덤불나무괴물은 몸속 샘에 물을 저장한대요.","선인장 밭에서 가득 찬 이슬샘을 구해 달래요."},c={"마린 노겐포저는 기뻐하며 어서 달라고 해요."},nx=2606,nt="In Good Taste"},
[2606]={a={"마린 노겐포저는 자기 음료 맛이 끔찍하다고 해요.","친구 스프링클은 훌륭한 요리사래요.","스프링클에게 음료를 마시기 쉽게 해 달라고 전해 달래요."},nx=2641,nt="Sprinkle's Secret Ingredient"},
[2621]={a={"호드 영웅의 넋은 자기 판단을 크게 후회하고 있어요.","명령을 기다렸어야 했는데 서두른 게 화근이었대요.","스토나드의 파견사령관 루아그를 찾아가 명령서를 알아봐 달래요."},nx=2622,nt="The Missing Orders"},
[2622]={a={"파견사령관 루아그는 명령서를 왜 찾냐며 의아해해요.","명령서를 나르던 전령들이 멀록에게 습격당했대요.","그 일을 알고 싶으면 벤고르와 얘기해 보래요."},nx=2623,nt="The Swamp Talker"},
[2623]={a={"벤고르는 명령서를 들고 가다 멀록에게 습격당했대요.","수다쟁이 늪지멀록이 명령서를 낚아챘대요.","그 대족장의 명령서를 되찾아 호드 영웅의 넋에게 가져가래요."},c={"호드 영웅의 넋은 상황이 생각보다 훨씬 나쁘다고 해요.","무모하게 굴지만 않았어도 부하들이 살았을 텐데 한탄해요.","부하들을 도와 달래요."}},
[2641]={a={"스프링클은 맛을 살리는 비밀 재료가 있대요.","그건 물속에서만 자라는 제비수염버섯이래요.","동부 내륙지의 작은 호수에서 구해 와 달래요."},c={"스프링클은 맛있어 보인다며 장난치듯 웃어요.","알고 보니 당신을 놀린 거래요."},nx=2661,nt="Delivery for Marin"},
[2661]={a={"스프링클이 제비수염 가루를 건네며 부탁해요.","마린에게 가루를 주면 그가 자기에게 빚을 지게 된대요.","마린 노겐포저에게 가루를 가져다 달래요."},c={"마린 노겐포저는 제비수염 가루를 한번 써 보겠대요.","이보다 맛이 더 나빠질 리 없다고 해요."},nx=2662,nt="Noggenfogger Elixir"},
[2662]={a={"마린 노겐포저는 자신 있는 비약을 만들고 있어요.","가루를 이슬에 섞는 중이래요.","잠시 뒤에 다시 와서 말을 걸어 달래요."},c={"마린 노겐포저는 비약이 정말 훌륭하다며 기뻐해요.","당신이 방해된다며 옆으로 비키라고 해요.","스프링클이 빚 얘기를 했다며 농담꾼이라고 웃어요."}},
[2681]={a={"호드 영웅의 넋은 부하들이 끝없는 고통에 갇혀 있다고 해요.","라젤리크와 그 부하들을 혼자서는 이기기 힘들대요.","실력 있는 모험가들과 돌을 부숴 부하들을 풀어 달래요."},c={"호드 영웅의 넋은 가엾은 영혼들이 드디어 쉬게 됐다고 해요.","아직 할 일이 많이 남았대요."},nx=2702,nt="Heroes of Old"},
[2701]={a={"하사관 선드 스플릿후프가 옛 유물을 건네요.","이 물건이 불타는 군단과 싸우는 데 도움이 되길 바래요.","유령의 금고를 열어 보상을 받아 가래요."},c={"빛이 번쩍여 잠시 눈이 부셔요."},nx=2721,nt="Kirith"},
[2721]={a={"호드 영웅의 넋은 아직 행방을 모르는 부하가 있대요.","키리스 부관은 저주받은 땅에서 실종됐대요.","그가 어떻게 됐는지 알고 싶대요."},nx=2743,nt="The Cover of Darkness"},
[2741]={c={"알을 기계에 넣자 삐 소리가 났대요.","알의 무게를 재고 포장까지 했대요.","정말 빠른 서비스라고 하네요."}},
[2742]={a={"린지가 도끼를 잃고 쿠엘다닐 오두막에 갇혔대요.","당신이 자기 일족을 좋아하지 않아도 부탁한대요.","이곳에서 꺼내 주면 보답하겠대요."},c={"이 서판이 린지가 말한 비밀인 것 같대요.","낯선 문양이 가득해 무슨 내용인지 못 읽겠대요.","오란 스네이크레이드가 더 알려 줄지도 모른대요."},nx=2782,nt="Rin'ji's Secret"},
[2743]={a={"키리스의 영혼은 시간이 없다며 바로 본론을 꺼내요.","라젤리크를 지키는 마력의 무리를 없애야 한대요.","트레보르에게 돌아가 무엇이 필요한지 알려 주래요."},nx=2744,nt="The Demon Hunter"},
[2744]={a={"호드 영웅의 넋 말로는 저주받은 땅에서 그들이 죽지 않는대요.","아뮬렛 조각이 그들에게 불멸을 준대요.","아즈샤라의 악마사냥꾼 로라무스 탈리뻬데스가 도와줄 수 있대요."},nx=3141,nt="Loramus"},
[2751]={a={"오모쉬 집안은 대대로 망치를 들어 왔대요.","오로크에게는 자식도 친척도 없어 비법이 끊길 판이래요.","비법을 이어 갈 실력을 보여 달래요."},c={"오모쉬의 전설은 이어질지도 모른대요.","당신이 진짜 대장장이라는 걸 증명했대요."},nx=2752,nt="On Iron Pauldrons"},
[2752]={a={"오로크 오모쉬는 당신의 열의를 알아봤대요.","오모쉬 집안의 기술을 더 가르쳐 준대요.","모루에서 청동 무기를 만들어 가져오래요."},c={"오로크가 아주 자랑스러워한대요.","이제 철제 견갑 만드는 법을 배우래요."},nx=2753,nt="Trampled Under Foot"},
[2753]={a={"오로크는 당신의 온몸이 쑤신다는 걸 알아요.","오모쉬 집안을 위해 조금만 더 참으래요.","녹색 철제 방어구를 만들어 가져다 달래요."},nx=2754,nt="Horns of Frenzy"},
[2754]={a={"오로크 오모쉬가 마지막 가르침을 준비했대요.","가르침을 받으려면 먼저 재료를 가져와야 한대요.","튼튼한 철제 마울, 은도금 청동 장화와 건틀릿을 가져오래요."},nx=2755,nt="Joys of Omosh"},
[2755]={a={"오로크 오모쉬가 집안의 마지막 비밀을 알려 준대요.","대대로 내려오는 기쁨의 춤이래요.","그 춤을 눈여겨보고 따라 배우래요."},c={"오로크가 오랜만에 춤을 췄대요.","이제 직접 배워 보래요."}},
[2756]={a={"무쇠모루 아투르크는 Thrall이 평화를 바란다고 한탄해요.","옛 적들도 이제는 지친 눈으로 지켜볼 뿐이래요.","강철 흉갑과 투구를 가져와 달래요."},c={"당신도 대족장만 따르는 순한 양일 뿐이래요.","Thrall의 명령으로 여기서 초보를 가르친대요.","잘 보고 배우라고 해요."},nx=2757,nt="Booty Bay or Bust!"},
[2757]={a={"옥스는 무법항 대장간에 있는 사람을 소개해 줘요.","그 사람은 미스릴에 대해 잘 안대요.","이 표장을 맥개번에게 보여 달래요."},c={"드디어 Mithril Order에 어울리는 사람이 왔대요."},nx=2760,nt="The Mithril Order"},
[2760]={a={"무법항까지 온 신참은 많지 않대요.","이 표장보다 훨씬 귀한 물건도 많다고 해요.","전설의 대장장이 갈반에게 펜던트를 보여 달래요."},c={"오랜만에 자격 있는 사람이 왔대요.","이제 Mithril Order 입단식을 시작한대요."}},
[2761]={a={"전설의 대장장이 갈반은 대장장이도 광부여야 한대요.","채광을 모르면 대장 기술도 완성될 수 없대요.","철과 미스릴 주괴를 가져오면 바지 만드는 법을 가르쳐 준대요."},c={"성실함이 흠잡을 데 없다고 갈반이 칭찬해요.","이제 갈반의 광물 지식을 조금씩 알아 간대요.","이걸 받아서 최대한 많이 배우래요."},nx=2764,nt="Galvan's Finest Pupil"},
[2762]={a={"갈반은 진은이 미스릴보다 튼튼하다는 말에 동의해요.","그런데 이름과 달리 진은은 진짜가 아니래요.","미스릴 주괴와 진은 주괴를 가져와 달래요."}},
[2763]={a={"갈반은 귀한 보석을 다루는 일이 가장 중요하대요.","황수정은 마법 속성을 크게 높여 준대요.","미스릴 주괴와 황수정을 가져와 달래요."},c={"황수정의 빛에 눈을 떼기 힘들대요.","황수정은 정말 훌륭한 보석이래요.","잘 주목해서 배우라고 해요."}},
[2764]={a={"전설의 대장장이 갈반은 수업을 마치려면 가젯잔에 가라고 해요.","갈반의 수제자 트렌튼 라이트해머가 가젯잔에 있대요.","그에게 화려한 미스릴 도의 비법을 배워 보래요."},c={"트렌튼 라이트해머는 갈반이 보냈냐며 놀라요.","스승의 다른 제자를 만나서 큰 영광이래요."}},
[2765]={a={"갈반은 당신이 처음부터 제자감인 줄 알았대요.","당신은 맥개번에게 마법 장신구를 내주고 찾아왔대요.","이제 대장기술 보상을 받으라고 해요."},c={"맥개번에게 준 것보다 강한 장신구를 받아요.","건강하게 잘 쓰라고 갈반이 말해요."}},
[2766]={a={"오글소프 오브노티쿠스의 유도 로봇이 불시착했대요.","로봇은 거친흉터 골짜기 근처 동굴에 있대요.","이 조난 탐지기를 로봇에게 가져가 달래요."},c={"탐지기를 넣자 로봇이 웅웅거리며 간신히 일어섰대요.","작동은 하지만 크게 수리해야 하고 옮기기엔 너무 무겁대요.","오글소프는 방법이 있다며 조금 더 지켜봐 달래요."},nx=2767,nt="Rescue OOX-22/FE!"},
[2767]={a={"로봇 안에서 오글소프 오브노티쿠스의 목소리가 나와요.","이륙하려면 잊혀진 해안의 부두로 옮겨야 한대요.","부두까지 호위한 뒤 무법항으로 와서 알려 달래요."},c={"오글소프는 당신이 로봇을 구한 은인이라고 해요.","시간과 돈을 많이 아꼈대요.","이 중에서 원하는 물건을 고르래요."}},
[2768]={a={"선임기술자 빌지위즐의 막대를 하사관 블라이가 훔쳐 갔대요.","그 막대가 없으면 새 우물 자리를 찾을 수 없대요.","블라이를 줄파락에서 찾아 막대를 되찾아 달래요."},c={"빌지위즐은 막대를 찾아서 잘했다고 칭찬해요.","블라이와 싸워야 했는지 궁금해해요.","블라이 일당을 크게 혼쭐냈으면 좋겠대요."}},
[2770]={a={"위즐 브라스볼츠는 줄파락 트롤들이 가즈릴라를 부른다고 해요.","가즈릴라의 비늘에는 에너지가 넘쳐 흐른대요.","그 전기를 자기 차에 쓰고 싶으니 비늘을 가져와 달래요."},c={"위즐이 비늘을 구해 와서 정말 기뻐해요.","얼른 이걸로 작업하고 싶어 한대요.","가즈릴라를 봤냐며 소문만큼 큰지 궁금해해요."}},
[2771]={a={"트렌튼 라이트해머는 당신과 기술을 나누려 해요.","스승이 처음부터 이렇게 계획했던 것 같대요.","미스릴 코이프와 어깨보호구를 가져와 달래요."},c={"트렌튼이 공정한 거래라며 흡족해해요.","잘 보고 배우라고 해요."}},
[2772]={a={"트렌튼 라이트해머는 작년 대장장이 선수권에서 우승했대요.","올해 대회에는 투자개발회사 벌목기가 나온대요.","바지 만드는 법을 가르쳐 주면 장화 만드는 법을 알려 준대요."},c={"이제 누가 다리를 노려도 끄떡없을 거래요.","당신에게 세상이 발밑에 놓일 거라고 해요."}},
[2773]={a={"트렌튼 라이트해머는 주변에서 미스릴 천재로 불린대요.","사실 그는 화려한 미스릴 장갑 만드는 법을 모른대요.","장갑 만드는 법을 가르쳐 주면 흉갑 기술을 보여 준대요."}},
[2781]={a={"가젯잔 수자원개발회사가 칼리프 스콜피드스팅을 현상수배했대요.","그는 사막유랑단 두목으로 회사 직원을 죽이고 자원을 빼앗았대요.","그의 머리카락을 선임기술자 빌지위즐에게 가져오면 큰 현상금을 준대요."},c={"빌지위즐은 드디어 정의가 실현됐다고 기뻐해요.","사막유랑단에게 큰 타격을 줬다고 칭찬해요.","회사 이름으로 현상금을 기쁘게 준대요."}},
[2782]={a={"서판에는 마른나무껍질부족 트롤의 독특한 문양이 가득해요.","아주 값진 물건일 수도, 아닐 수도 있대요.","언더시티 마법 지구의 오란 스네이크레이드가 해독할지도 모른대요."},c={"오란 스네이크레이드는 서판이 꽤 특이하다고 해요.","어디서 찾았냐고 궁금해해요."},nx=8273,nt="Oran's Gratitude"},
[2822]={a={"장도르 스위프트스트라이더는 가죽 세공에 큰 자부심이 있대요.","얼마 전 두꺼운 설인 가죽을 찾았대요.","그 가죽을 가져오면 가죽 제품을 골라 주겠대요."},c={"설인 가죽은 특별히 다루면 철처럼 단단해진대요.","무두질 방법을 찾아 품질을 한 단계 높이겠대요.","당신 덕에 큰 도움을 받았다며 제품을 고르래요."},nx=7734,nt="Improved Quality"},
[2841]={a={"노움이 우리 벌목기보다 나은 장치를 만들었대요.","설계도는 멕기니어 텔마플러그의 금고에 있대요.","금고 암호를 알아내 설계도를 가져다 달래요."},c={"해낼 줄 알았다고 기뻐하네요.","이제 노움 기술을 우리 벌목기에 쓸 거래요."}},
[2842]={a={"소빅과 스쿠티가 순간이동기 6000을 만들었대요.","놈리건까지 가장 빠르고 안전한 방법이래요.","무법항의 스쿠티를 찾아가 보래요."},c={"정말 멋진 장치죠?","예전엔 폭발도 했지만 이제 다 고쳤대요."},nx=2843,nt="Gnomer-gooooone!"},
[2843]={a={"응답장치만 있으면 발판에서 바로 놈리건에 간대요.","돌아올 때는 놈리건의 발판을 밟으면 된대요.","응답장치 크기를 맞추는 동안 기다려 달래요."},c={"다 됐어요.","준비되면 발판에 올라서면 된대요."}},
[2846]={a={"타베사는 예전에 심연의 티아라를 갖고 있었대요.","유체술사 벨라타가 부하를 보내 티아라를 훔쳐 갔대요.","줄파락에서 벨라타에게 티아라를 되찾아 달래요."},c={"타베사는 티아라를 되찾아서 기뻐해요.","벨라타는 이제 티아라를 갖고 있지 않대요.","전에 쌀쌀맞았다면 신경 쓰지 말래요."}},
[2854]={a={"장도르는 당신의 가죽 세공 실력이 빨리 늘었다고 해요.","야생 가죽 방어구 만드는 법을 알고 있대요.","먼저 두꺼운 가죽을 가져오면 자세히 얘기하겠대요."},c={"장도르는 당신이 제자가 돼서 기쁘대요.","야생 가죽 기술을 익히면 찾는 사람이 많을 거래요.","그럼 어디서부터 시작할지 묻고 있어요."}},
[2855]={a={"장도르는 야생 가죽 어깨보호구 도안을 가르쳐 준대요.","이 도안은 야생덩굴을 꿰매 강한 효과를 더한대요.","두꺼운 방어구 키트와 야생덩굴을 가져오면 된대요."},c={"방어구 키트가 품질이 좋다고 장도르가 말해요.","당신은 이 도안을 얻을 자격이 있대요.","이 도안이 당신에게도 보상을 가져다주길 바란대요."}},
[2856]={a={"장도르가 야생 가죽 조끼 도안을 가르쳐 준대요.","야생덩굴이 엮여 몸통을 강하게 지켜 준대요.","거북 껍질 흉갑과 장갑, 야생덩굴을 가져오래요."},c={"장도르는 가져온 장비가 훌륭하다고 칭찬해요.","정성을 다한 솜씨가 느껴진대요.","그래서 야생 가죽 조끼 도안을 얻게 됐대요."}},
[2857]={a={"장도르가 야생 가죽 투구 도안을 가르쳐 준대요.","야생덩굴이 투구에 강한 효과를 무작위로 더한대요.","밤하늘 튜닉과 머리띠, 야생덩굴을 가져오래요."},c={"가져온 밤하늘 장비가 요구한 것과 딱 맞대요.","가죽 세공사로서 당연한 솜씨라고 칭찬해요.","이 도안을 아무 대가 없이 준대요."}},
[2858]={a={"장도르는 당신의 야생 가죽 지식이 늘었다고 해요.","야생 가죽 장화는 발을 편하게 하고 소리가 적대요.","밤하늘 바지, 장화, 야생덩굴을 더 가져오래요."},c={"당신은 전문가처럼 완성품을 만들었대요.","이 도안을 얻을 자격이 있대요.","장도르가 축하한다고 말해요."}},
[2859]={a={"장도르가 더 복잡한 기술인 다리보호구를 알려 준대요.","야생 가죽 다리보호구는 가죽 장비 중 가장 튼튼하대요.","거북 껍질 투구, 팔보호구, 야생덩굴을 가져오래요."}},
[2860]={a={"장도르는 가르칠 것을 다 가르쳤대요.","마지막 도안은 장도르의 스승인 우나만 줄 수 있대요.","썬더 블러프의 우나에게 장도르의 편지를 전해 달래요."},c={"우나는 장도르가 보내서 왔냐며 반가워해요.","장도르가 제자를 두었다니 기쁘대요.","야생 가죽 망토 도안을 주니 잘 활용하래요."},nx=5148,nt="Tribal Leatherworking"},
[2861]={a={"아나스타샤 하트웰 말로는 타베사가 트롤과 문제가 있대요.","상대는 줄파락의 모래 트롤이래요.","타베사를 찾아가 얘기를 듣고 친구도 데려가래요."},c={"타베사는 트롤에게 따질 일이 있대요.","따질 게 한두 가지가 아니래요.","같이 해 줄 수 있냐고 묻고 있어요."},nx=2846,nt="Tiara of the Deep"},
[2862]={a={"놀들이 모자케 야영지를 끊임없이 위협한대요.","요즘 놀들의 공격이 더 거세졌대요.","덩굴발일족 갈기를 가져오면 후하게 보상하겠대요."},c={"이건 좋은 시작이라며 당신의 솜씨를 칭찬해요.","놀들이 북쪽으로 세력을 넓히려고 공격이 늘었대요.","놀을 완전히 물리칠 계획이 있대요."},nx=2863,nt="Alpha Strike"},
[2863]={a={"아도겐 스위프트스트라이더는 놀 우두머리들을 빨리 치려 해요.","빠르게 쳐서 놀들 사이에 혼란을 일으키려 해요.","제한 시간 안에 우두머리를 처치하고 돌아오래요."},c={"요청한 대로 해내서 고맙다고 해요.","놀들이 야영지를 공격하기 전에 한 번 더 생각할 거래요.","왜 놀들이 저렇게 흥분했는지 알아내야 한대요."},nx=2902,nt="Woodpaw Investigation"},
[2864]={a={"크라젝의 사촌 트란렉이 곤란한 처지래요.","몇 주 전 왕쇠똥구리 껍질을 보내기로 했는데 아직이래요.","빨리 보내라고 트란렉에게 전해 달래요."},nx=2865,nt="Scarab Shells"},
[2865]={a={"트란렉은 타나리스의 왕쇠똥구리 껍질이 아주 단단하대요.","껍질을 가져오면 서식지를 알려 주겠대요.","줄파락에 무리가 있으니 온전한 껍질을 가져오래요."},c={"트란렉은 껍질을 가져와서 정말 기뻐해요.","정말 큰 도움이 됐다고 고마워해요."}},
[2872]={a={"스톨리는 \"바다늑대\" 맥킨리에게 특별한 럼주를 빚졌대요.","스팀휘들 항구 럼주가 무법항보다 독하다고 자랑했대요.","스톨리가 럼주 주기를 꺼려해서 대신 얘기해 달래요."},c={"스톨리는 맥킨리와 얘기했냐고 묻고 있어요.","럼주를 안 주려는 게 아니라 줄 럼주가 없대요."},nx=2873,nt="Stoley's Shipment"},
[2873]={a={"스톨리는 럼주가 다 떨어져서 내기 술이 없대요.","쿠에르고 선장이 뱃짐을 훔쳐 해적 마을에 숨겼대요.","남쪽 성벽 마을에서 뱃짐을 찾아와 달래요."},c={"뱃짐을 가져다줘서 고맙대요.","이제 맥킨리와 내기를 제대로 정리할 수 있대요."},nx=2874,nt="Deliver to MacKinley"},
[2874]={a={"스톨리가 다시 도와줘서 고맙다고 해요.","스톨리의 병에 든 럼주를 맥킨리에게 가져가래요.","그래야 맥킨리가 무법항 술에 대한 믿음을 버린대요."},c={"맥킨리가 끔찍한 맛에 놀라면서도 좋아해요.","빚진 돈은 스톨리가 가져도 된대요.","칼림도어 럼주는 자갈처럼 걸쭉하고 용암처럼 타오른대요."}},
[2875]={a={"앙드레 파이어비어드는 스팀휘들 항구와 가젯잔에서 죄를 지었대요.","누구든 그를 잡을 때 치명적인 힘을 써도 된대요.","데려올 수 없으면 머리카락을 보안과장 빌지위즐에게 가져가래요."},c={"앙드레는 결국 재판을 받게 됐대요.","여기 서명하면 보수를 준대요.","작은 글씨는 신경 쓰지 말래요."}},
[2876]={a={"이 두루마리에는 스팀휘들 항구와 무법항의 뱃짐 운송 일정이 적혀 있대요.","일부 항해에는 X 표시와 \"대단한 전리품\" 메모가 있대요.","스팀휘들 항구에서 이 문서를 보고 싶어 할 거래요."},c={"배 출발과 도착 시간이 자세히 적힌 목록이래요.","해적 선장이 가졌다면 신이 났을 거래요.","해적에게서 빼앗아 줘서 고맙대요."}},
[2902]={a={"놀들은 분명 전투 계획서 같은 걸 갖고 있을 거래요.","그 계획을 알면 놀들이 왜 흥분했는지 알 수 있대요.","덩굴발일족 야영지에서 계획서를 찾아오래요."},c={"지도를 보니 아도겐이 원하는 전투 계획서가 맞대요.","화살표 대부분이 야영지 북쪽이 아니라 남쪽을 향해요.","정체불명의 벌레에게 입은 피해를 나타내는 것 같대요."},nx=2903,nt="The Battle Plans"},
[2903]={a={"덩굴발일족 전투계획서를 찾았으니 가져가기만 하면 돼요.","계획서로 놀들이 무엇을 노리는지 알 수 있을 거래요.","아도겐이나 야영지 사람이 뜻을 알아낼 수 있대요."},c={"아도겐은 이게 바로 필요했던 거라고 해요.","글씨는 잘 못 읽어도 전투 계획은 알아본대요.","놀들은 남쪽의 다른 적과도 싸우고 있는 것 같대요."}},
[2904]={a={"케르노비는 검은무쇠단에게 붙잡혀 크게 맞았대요.","그 거대한 장치에도 검은무쇠단이 얽혔대요.","출구까지 호위하고 무법항 스쿠티에게 알려 달래요."},c={"케르노비를 무사히 데려와 줘서 고맙대요.","이걸로 멕기니어 텔마플러그를 이길 수 있을 거래요."}},
[2932]={a={"님보야는 마른나무껍질부족이 스랄님을 배신했다고 화를 내요.","동부 내륙지에서 마른나무껍질 트롤을 잡아 해골을 모으래요.","님보야의 창을 그들 마을에 꽂으래요."}},
[2933]={a={"독병에는 사악한 녹색 독이 들어 있대요.","마을에 독병이 많아서 마른나무껍질부족이 중요하게 여기는 것 같대요.","타렌 밀농장의 연금술사가 견본을 원할지도 모른대요."},nx=2934,nt="Undamaged Venom Sac"},
[2934]={a={"라이던은 가져온 독보다 신선한 독이 필요하대요.","그 독은 동부 내륙지 거미에게서 나왔을 거래요.","샤드라알로 근처 거미를 잡아 온전한 독주머니를 가져오래요."},c={"라이던은 독이 아주 신선하다고 기뻐해요.","틀림없이 아주 독할 거래요."},nx=2935,nt="Consult Master Gadrin"},
[2935]={a={"라이던은 혈거미 독이 처음 것보다 약하다고 해요.","마른나무껍질부족이 어디서 독을 구하는지 알아야 한대요.","센진 마을의 장로 가드린에게 물어보래요."},c={"가드린은 마른나무껍질 거미 독을 원하냐고 물어요.","듣기 싫은 얘기가 있으니 앉으래요."},nx=2936,nt="The Spider God"},
[2936]={a={"장로 가드린은 마른나무껍질부족이 거미 신을 숭배한다고 해요.","그 신의 독을 얻으려면 신을 불러내야 한대요.","순교자 데카를 물리치고 서판에서 이름을 알아 달래요."},c={"그 이름은 속삭여서만 불러야 한대요.","그 이름을 양피지에 적어 소환 주문을 만들어 준대요."},nx=2937,nt="Summoning Shadra"},
[2937]={a={"장로 가드린이 양피지를 건네줘요.","이걸 샤드라알로 제단에서 읽으면 거미 신 샤드라가 나온대요.","그 제단에서 이 양피지를 읽어 달래요."},nx=2938,nt="Venom to the Undercity"},
[2938]={a={"연금술사 라이던은 이 독이 아주 대단하다고 해요.","토끼 여럿을 한 방울로 죽일 만큼 강하대요.","언더시티의 수석 연금술사 파라넬에게 견본을 전해 달래요."}},
[2945]={a={"검은무쇠단 드워프의 시체에서 꼬질꼬질한 반지가 나왔어요.","찌꺼기가 두껍게 덮여 끼울 수가 없대요.","찌꺼기를 없앨 방법을 찾아 달래요."},c={"삐까뻔쩍세척기 5200에 반지를 넣었어요.","기계가 요란하게 돌더니 빨간 리본 상자가 나왔대요."}},
[2949]={a={"상자 속에는 반짝이는 반지가 있었대요.","반지 안쪽에 '노...'로 시작하는 글자가 새겨져 있대요.","반지를 간직할지 주인을 찾을지 정하래요."},c={"놈리건에서 온 반지라니 흥미롭대요.","검은무쇠단이 가졌다면 조사해 볼 만하대요."},nx=2950,nt="Nogg's Ring Redo"},
[2950]={a={"노그는 이 반지가 자기 것은 아니래요.","검은무쇠단 정보가 도움이 됐다고 해요.","은괴와 태마노를 가져오면 반지를 손봐 준대요."},c={"반지를 전보다 더 좋게 다듬었대요.","노움들이 갑자기 잘하게 된 이유를 알 것 같대요."}},
[2951]={a={"저항하는 노움들 사이에 세척기가 눈에 띄어요.","귀중품의 찌꺼기를 깨끗이 닦아 준다고 적혀 있어요.","꼬질꼬질한 물건을 넣어 보래요."},c={"꼬질꼬질한 물건과 동전을 넣었어요.","기계가 요란하게 흔들리며 돌아가기 시작했어요."}},
[2954]={a={"노르간논의 바위감시자가 울둠 입구를 지키고 있어요.","울둠의 원반이 없으면 안으로 들여보내지 않는대요.","먼저 바위감시자의 숨은 이야기를 알아보래요."},c={"울둠 대좌를 건드리면 원반을 돌려준대요.","울둠의 원반을 세트에 넣으면 안으로 들어갈 수 있대요."}},
[2965]={a={"현자 트루스시커는 울다만에서 찾은 것을 두고 논의 중이래요.","드루이드 나라 와일드메인과 의논하고 있었대요.","장로의 봉우리에서 감시자의 골짜기 얘기를 들어 달래요."},c={"감시자의 골짜기는 타나리스 사막 깊은 곳에 있대요.","원반 글자에 나온 울둠은 실제로 있대요.","울둠에 가 봐 달래요."},nx=2966,nt="Seeing What Happens"},
[2966]={a={"나라 와일드메인이 현자 트루스시커와 함께 부탁해요.","작은 원반을 울둠의 봉인된 문에 가져가 보래요.","위험할 수 있으니 대비하고, 알아낸 뒤 다시 와 달래요."},c={"울둠 대좌에 닿자 가방 속 원반이 울리며 빛나요.","울둠의 문 앞에 또 다른 바위감시자가 나타났대요.","울둠의 원반을 끼우고 다시 열어 보래요."},nx=2954,nt="The Stone Watcher"},
[2967]={a={"울둠 대좌를 다시 건드리니 원반이 가방에 돌아왔어요.","바위감시자 이야기를 알아내고 원반도 되찾았어요.","썬더 블러프로 가서 나라 와일드메인에게 보고해 달래요."},c={"원반들은 전체 세트의 일부일 뿐이래요.","울둠의 원반을 찾으면 울둠 안으로 들어갈 수 있대요.","나라 와일드메인은 기쁜지 무서운지 모르겠대요."},nx=2968,nt="A Future Task"},
[2968]={a={"나라 와일드메인이 난감해하고 있어요.","울둠의 원반이 필요한데 어디 있는지 몰라요.","현자 트루스시커에게 이 일을 보고해 달래요."},c={"현자 트루스시커는 원반이 있을 곳을 좁힐 때까지 기다리자고 해요.","쓴 경비에 조금 더 얹어 사례금을 준대요.","곧 다시 들러 달래요."}},
[2973]={a={"크루엑 스컬스플리터는 오그리마의 명을 받고 페랄라스에 왔어요.","아내 코린에게 요정용 날개로 장식한 망토를 만들어 주려 해요.","모자케 야영지 서쪽 화살요정용 날개를 구해 달래요."},c={"이 날개면 코린의 망토를 만들고도 남는대요.","페랄라스는 만만한 곳이 아닌데 잘해 냈대요."},nx=2974,nt="A Grim Discovery"},
[2974]={a={"크루엑 스컬스플리터는 그림토템부족을 드디어 찾았대요.","벨그롬 장로님이 그 부족에 관심이 많고 현상금도 걸었대요.","이번엔 그 뿔을 되도록 많이 모아 오래요."},c={"뿔이 좋다며 잘했다고 칭찬해요.","오그리마에 돌아가 벨그롬 장로님께 전한대요.","두 번이나 도와줘서 표식을 준대요."},nx=2976,nt="A Grim Discovery"},
[2975]={a={"로크 올한은 골두니 오우거 때문에 땅이 상한다고 해요.","녀석들이 페랄라스에서 세력을 넓히기 전에 몰아내야 한대요.","강을 따라 북쪽 골두니 전초기지로 가 달래요."},c={"잘했다고 칭찬해요.","시간이 지나면 땅이 회복될 거래요.","포기하지 말자고 해요."},nx=2980,nt="The Ogres of Feralas"},
[2976]={a={"크루엑 스컬스플리터는 현상금 얘기를 흘린 걸 후회해요.","수고한 당신에게 그림토템부족 뿔 상자를 준대요.","명예의 골짜기 벨그롬 록마울에게 가 보래요."},c={"벨그롬 록마울은 그림토템부족 얘기에 흥미를 보여요.","페랄라스에서 사냥하다 만났냐고 물어요.","얘기를 들려주면 보상금을 내준대요."}},
[2978]={a={"더럽혀진 두루마리에 회합이나 의식이 그려져 있어요.","로크 올한이 골두니일족에게 뜻이 있는지 궁금해할 거래요.","모자케 야영지의 로크 올한에게 가져가 달래요."},c={"이 두루마리를 골두니 전초기지에서 찾았냐고 놀라요."},nx=2979,nt="Dark Ceremony"},
[2979]={a={"두루마리가 암흑 의식의 계획서인 것 같대요.","그 의식은 골두니일족 오우거 대마법사들이 치르는 것 같대요.","대마법사를 찾아 수정구를 빼앗아 오래요."},nx=3002,nt="The Gordunni Orb"},
[2980]={a={"로크 올한은 당신이 진정한 투사임을 증명했다고 해요.","높은벌 폐허에서 골두니일족을 몰아내 달래요.","이번 오우거들은 전보다 훨씬 강하대요."},c={"믿음직한 동맹이라고 해요."}},
[2981]={a={"벨그롬 록마울은 페랄라스가 실력을 증명할 곳이라고 해요.","골두니 오우거가 늘어 동맹을 위협하기 전에 막아야 해요.","모자케 야영지의 로크 올한을 찾아가 보래요."},c={"벨그롬 록마울이 보냈다니 때마침 잘 왔대요.","상황을 설명하고 해낼 수 있을지 고르게 해요."},nx=2975,nt="The Ogres of Feralas"},
[2983]={a={"스워트는 당신이 이제 더 큰 힘을 배울 때라고 해요.","불의 원소는 대가를 치러야 얻을 수 있대요.","불모의 땅의 크라날 피스를 찾아가 달래요."},c={"크라날이 스워트가 보냈냐고 물어요.","이제 불의 가르침을 받을 준비가 됐대요.","힘은 쉽게 얻지만 손을 멈출 줄 알아야 한대요."},nx=1524,nt="Call of Fire"},
[2984]={a={"나름 스카이체이서는 이제 파괴의 힘을 배울 때라고 해요.","불의 원소는 대가를 치르면 얻을 수 있대요.","불모의 땅의 크라날 피스를 찾아가 달래요."},c={"크라날이 나름이 보냈냐고 물어요.","이제 불의 가르침을 받을 준비가 됐대요.","힘은 쉽게 얻지만 손을 멈출 줄 알아야 한대요."},nx=1524,nt="Call of Fire"},
[2985]={a={"스워트는 당신이 이제 물의 순수함을 배울 때라고 해요.","이슬렌 워터시어는 동쪽 해안의 낚시 오두막에 있대요.","불모의 땅에서 이슬렌 워터시어를 찾아가 달래요."},c={"바람이 다가오고 땅은 굳건하대요.","이제 물의 순수함을 배울 때래요.","첫걸음은 당신이 떼야 한대요."},nx=1530,nt="Call of Water"},
[2986]={a={"나름 스카이체이서는 이제 물을 배울 때라고 해요.","이슬렌 워터시어는 동쪽 해안 낚시 오두막에 있대요.","불모의 땅에서 이슬렌 워터시어를 찾아가 달래요."},c={"바람이 다가오고 땅은 굳건하대요.","이제 물의 순수함을 배울 때래요.","첫걸음은 당신이 떼야 한대요."},nx=1530,nt="Call of Water"},
[2987]={a={"올윈 기즈믹은 페랄라스에 온 지 얼마 안 됐대요.","골두니 오우거가 흥미로운 광석을 땅에 묻어 둔대요.","삽을 줄 테니 북쪽 전초기지에서 코발트를 캐 달래요."},c={"완벽하다며 기뻐해요.","이 코발트를 비싸게 팔 사람을 찾겠대요.","수고했다며 뭔가를 건네준대요."}},
[2995]={a={"오란 스네이크레이드는 깊은골짜기 일족이 동맹 맺는 걸 막으려 해요.","쿠엘다닐 오두막에 연락 문서가 보관돼 있대요.","동부 내륙지에 가서 그 문서를 모두 없애 달래요."},c={"깊은골짜기는 잃은 정보를 되찾느라 바쁠 거래요.","그 사이 연락망을 더 완전히 막을 수 있대요."}},
[2996]={a={"간룰 블러드아이는 이제 다른 스승에게 배우라고 해요.","스트라드 파선은 더 강한 소환을 가르쳐 준대요.","톱니항에서 스트라드 파선을 찾아가 보래요."},c={"톱니항은 오늘도 참 바빠 보여요.","당신 눈에 증오가 보인다며 잘됐다고 해요."},nx=1801,nt="Tome of the Cabal"},
[3001]={a={"카렌딘 할가르는 이제 다른 이에게 배우라고 해요.","스트라드 파선은 인간이지만 얕보면 안 된대요.","톱니항에서 스트라드 파선을 찾아가 보래요."},c={"톱니항은 오늘도 참 바빠 보여요.","당신 눈에 증오가 보인다며 잘됐다고 해요."},nx=1801,nt="Tome of the Cabal"},
[3002]={a={"로크 올한은 수정구가 무엇을 할 수 있는지 다 말할 수 없대요.","오그리마에 수정구를 설명해 줄 마법사가 있대요.","그 마법사에게 수정구를 가져다 달래요."},c={"수정구가 아주 강하지만 아주 위험하대요."}},
[3042]={a={"트렌튼 라이트해머가 담금질용 경화제를 찾고 있어요.","줄파락의 성난모래부족이 사암으로 만든대요.","그 경화제를 넉넉히 가져다주면 후하게 사례한대요."},c={"경화제가 아주 좋다며 감탄해요.","이렇게 많으니 쓰는 데 며칠은 걸리겠대요.","사례금을 건네준대요."}},
[3062]={a={"탈로 쏜후프는 에다나 헤이트탈론을 완전한 악으로 봐요.","에다나는 서쪽 폐허에 사는 하피들의 여왕이래요.","그녀와 맞서 싸워 검은 심장을 가져다 달래요."},c={"에다나가 정말 죽었다는 걸 이제 알게 됐대요.","당신이 해준 일을 기억하려고 이 심장을 간직하겠대요."}},
[3063]={a={"탈로 쏜후프는 소싯적에 아주 능숙한 사냥꾼이었대요.","하피들에게 습격당한 뒤로 증오가 끓어오른대요.","서쪽 까마귀바람 폐허의 하피들에게 복수해 달래요."},c={"고맙다며 늙은 타우렌의 마음이 편해졌대요."}},
[3065]={a={"고르넥이 당신이 없는 동안 서판이 왔대요.","상급 전사 프랑이 보낸 것 같대요.","서판을 읽고 시험의 골짜기의 프랑을 찾아가 달래요."},c={"이곳은 전사의 길을 배우기에 맞대요.","궁금한 건 주변 사람에게 물어보래요.","준비되면 대가를 내고 훈련받으러 오래요."}},
[3082]={a={"고르넥이 당신이 없는 동안 서판이 왔대요.","사냥꾼 조련사 젠샨이 보낸 것 같대요.","서판을 읽고 시험의 골짜기의 젠샨을 찾아가 달래요."},c={"젠샨이 사냥꾼의 길을 가르쳐 준대요.","부족이 사냥꾼을 존경하고 큰 역할을 맡을 거래요.","준비되면 젠샨을 찾아오라고 해요."}},
[3083]={a={"고르넥이 암호화된 서판이 도착했다고 알려요.","도적 조련사 르와그가 보낸 것 같대요.","서판을 읽고 시험의 골짜기의 르와그를 찾아가 달래요."},c={"르와그는 당신을 자기 밑에서 가르치겠대요.","기술을 날카롭게 갈고닦으라고 해요.","준비되면 언제든 찾아오라고 해요."}},
[3084]={a={"고르넥이 당신이 없는 동안 서판이 왔대요.","주술사 조련사 시크리크가 보낸 것 같대요.","서판을 읽고 시험의 골짜기의 시크리크를 찾아가 달래요."},c={"원소가 우리에게 힘을 준다는 건 아시겠죠.","주술사는 마을 사람들이 지혜와 보호를 구하는 지도자래요.","힘을 얻으면 와서 더 배우라고 해요."}},
[3085]={a={"고르넥이 당신이 없는 동안 서판이 왔다고 해요.","상급 사제 켄자이가 보낸 것 같대요.","서판을 읽고 동굴 막사 밖의 켄자이를 찾아가 달래요."},c={"시험할수록 영혼을 더 잘 다루게 될 거래요.","그럼 켄자이가 더 강한 능력을 가르칠지도 모른대요.","단, 영혼들이 동의해야 한대요."}},
[3086]={a={"고르넥이 당신이 없는 동안 서판이 왔대요.","상급 마법사 마이아가 보낸 것 같대요.","서판을 읽고 막사 입구의 마이아를 찾아가 달래요."},c={"당신은 이 행성에서 가장 강한 존재 중 하나래요.","하지만 보이지 않는 마법을 조심하라고 해요.","참을성 있게 굴다가 준비되면 돌아오래요."}},
[3087]={a={"고르넥이 당신이 없는 동안 양피지가 왔대요.","사냥꾼 조련사 젠샨이 보낸 것 같대요.","양피지를 읽고 시험의 골짜기의 젠샨을 찾아가 달래요."},c={"젠샨은 마을 사람들의 부탁을 들어주라고 해요.","그 부탁들이 기술을 시험하고 위험을 알려 줄 거래요.","자주 젠샨을 찾아오라고 해요."}},
[3088]={a={"고르넥이 당신이 없는 동안 양피지가 왔대요.","상급 도적 르와그가 보낸 것 같대요.","암호화된 양피지를 읽고 르와그를 찾아가 달래요."}},
[3089]={a={"고르넥이 당신이 없는 동안 양피지가 왔대요.","상급 주술사 시크리크가 보낸 것 같대요.","룬으로 새겨진 양피지를 읽고 시크리크를 찾아가 달래요."},c={"당신은 조상들이 소통하는 통로가 될 거래요.","원소의 힘을 부리고 적을 쉽게 쓰러뜨릴 수 있대요.","필요할 때마다 와서 새 주문을 배우라고 해요."}},
[3090]={a={"고르넥은 당신이 없는 사이 오래된 양피지가 왔다고 해요.","상급 흑마법사 나르톡이 보낸 것 같대요.","시간 날 때 읽고 나르톡과 이야기해 보래요."},c={"나르톡은 이제 당신도 우리 편이 됐다고 해요.","힘이 있어도 어리석으면 죽은 것과 같대요.","주문을 배우고 싶으면 다시 찾아오래요."}},
[3091]={a={"그룰 호크윈드는 조금 전 전령이 당신을 찾았대요.","전사 조련사 하루트가 보낸 쪽지 같대요.","쪽지를 읽고 나라체 야영지의 하루트를 찾아가 달래요."},c={"부족에서 누구나 맡은 역할이 있대요.","자만하지 말고 같은 의식을 거쳐야 한대요.","준비되면 돌아와 훈련받으라고 해요."}},
[3092]={a={"그룰 호크윈드는 조금 전 전령이 당신을 찾았대요.","사냥꾼 조련사 랑카가 보낸 쪽지 같대요.","쪽지를 읽고 붉은구름 고원의 랑카 파샷을 찾아가 달래요."},c={"랑카는 당신을 준비시키는 게 자기 임무래요.","길들이기와 총 쏘기 같은 기술을 가르친대요.","부족을 잘 섬기면 존경받을 거래요."}},
[3093]={a={"그룰 호크윈드 말로는 방금 전령이 찾아왔대요.","상급 주술사 밀라 던스트라이더가 보낸 것 같대요.","쪽지가 짧으니 얼른 읽어 보래요."},c={"밀라 던스트라이더는 앞으로 자주 만날 거래요.","만날 때마다 더 강하고 준비된 모습이길 바란대요.","이제 나가서 실력을 시험해 보래요."}},
[3094]={a={"그룰 호크윈드 말로는 전령이 방금 나를 찾았대요.","상급 드루이드 가트 미스트러너가 보낸 것 같대요.","쪽지가 짧으니 얼른 읽어 보래요."},c={"냉대는 신경 쓰지 말고 Earthmother의 가르침에 집중하래요.","지혜가 자라면 아는 것을 더 가르쳐 준대요.","헌신하는 사람에게 Earthmother가 놀라운 힘을 준대요."}},
[3095]={a={"어둠의사제 사비스가 간결한 두루마리가 도착했다고 해요.","다날 스턴의 인장이 찍혀 있어 중요한 일 같대요.","두루마리를 읽고 데스넬의 다날 스턴을 찾아가 달래요."},c={"다날 스턴은 실력이 늘면 언제든 찾아오라고 해요.","수업료는 조금만 받고 많은 것을 가르쳐 준대요.","앞으로 실바나스에게 이런 힘의 전사가 필요하대요."}},
[3096]={a={"어둠의사제 사비스가 암호화된 두루마리가 왔다고 해요.","도적 교관 데이비드 트리아스의 인장이 찍혀 있대요.","두루마리를 읽고 데스넬의 데이비드 트리아스를 찾아가 달래요."},c={"데이비드는 여관에서 새로운 얼굴을 살피며 지낸대요.","말썽 없이 지내면 몇 가지 기술을 가르쳐 준대요.","실력이 되면 언제든 와서 새 기술을 배우라고 해요."}},
[3097]={a={"어둠의사제 사비스가 성스러운 두루마리가 도착했다고 해요.","어둠의사제 듀스텐의 인장이 찍혀 있어 중요한 일 같대요.","두루마리를 읽고 데스넬 교회의 듀스텐을 찾아가 달래요."},c={"듀스텐은 우리가 의지만으로 살아남았다고 말해요.","약한 자들이 기대고 병든 자들도 주인이라 부를 거래요.","실력이 늘면 다시 찾아와 더 큰 힘을 배우래요."}},
[3098]={a={"어둠의사제 사비스가 상형 문자로 된 두루마리가 왔다고 해요.","상급 마법사 이자벨라의 인장이 찍혀 있대요.","두루마리를 읽고 데스넬 교회의 이자벨라를 찾아가 달래요."},c={"이자벨라는 힘을 키워 자주 찾아오라고 해요.","타락이 굶주린 늑대처럼 따라다니지만 막을 수 있대요.","마음을 내주지 않으면 타락에 지배당하지 않는대요."}},
[3099]={a={"어둠의사제 사비스는 당신이 떠난 사이 두루마리가 왔대요.","맥시밀리언의 인장이 찍혀 중요한 일 같대요.","떠나기 전에 오래된 두루마리를 읽어 보래요."},c={"주인이 누구든 노예는 여전히 노예라고 해요.","흑마법사들은 생물을 부리려고 그 힘을 원한대요.","맥시밀리언은 당신의 동맹이 되겠대요."}},
[3121]={a={"의술사 우제리는 이곳 일을 시작하려고 물건이 필요해요.","네루 파이어블레이드가 물약을 만들어 뒀대요.","약초와 바꾸기로 한 구겨진 가면을 오그리마로 가져가 달래요."},c={"네루 파이어블레이드는 우제리가 이걸 보내기를 기다렸대요.","우제리의 실험용 약초 혼합물을 건네줘요."},nx=3122,nt="Return to Witch Doctor Uzer'i"},
[3122]={a={"네루 파이어블레이드가 약초 주머니를 건네요.","페랄라스의 의술사 우제리에게 가져가 달래요.","가면에 만족한다는 말도 전해 달래요."},c={"이 약초면 뮤세크 단지를 준비할 수 있대요.","주문이 얼마나 효과 있을지 곧 알게 될 거래요.","잠시만 기다려 달래요."}},
[3123]={a={"의술사 우제리가 당신의 능력을 시험하려 해요.","생물을 가둘 수 있는 단지를 건네줘요.","동부 내륙지 올빼미야수를 잡아 단지에 담아 달래요."},c={"폭력적으로 죽으면 뮤세크가 빠져나가 복수할 수 있대요.","당신이 줄여 담으면 뮤세크가 빠져나가지 못해요.","이제 뮤세크를 마음대로 쓸 수 있대요."},nx=3124,nt="Hippogryph Muisek"},
[3124]={a={"의술사 우제리가 당신을 믿고 또 부탁할 일이 있대요.","공작날개 히포그리프를 잡아 뮤세크 단지에 담아 달래요.","그 히포그리프는 남쪽 높은벌에 있대요."},c={"뮤세크를 놓치면 더 큰 생물의 모습이 될 수 있대요.","그러면 그 복수에서 절대 안전할 수 없대요.","위험한 일을 잘 해냈다고 칭찬해요."},nx=3125,nt="Faerie Dragon Muisek"},
[3125]={a={"의술사 우제리는 나약해 보여도 영혼이 강한 요정용을 원해요.","요정용은 나이트 엘프의 동지라 호드도 그 힘을 써야 한대요.","뮤세크 단지를 건네고 서쪽에서 요정용을 잡아 달래요."},c={"요정용의 영적인 힘을 쓸 수 있게 됐대요.","그럼 또 다른 일도 부탁하고 싶대요."},nx=3126,nt="Treant Muisek"},
[3126]={a={"의술사 우제리의 다음 목표는 숲을 떠도는 숲정령이래요.","나이트 엘프는 호드에 맞서려고 나무정령을 동지로 받아들였대요.","떠도는 숲정령을 잡아 뮤세크 단지에 담아 달래요."},c={"뮤세크 모으기가 거의 끝났다며 고마워해요."},nx=3127,nt="Mountain Giant Muisek"},
[3127]={a={"의술사 우제리의 마지막 부탁은 북서쪽에 있는 적이래요.","산악거인은 불타는 군단 때 나이트 엘프를 도우러 내려왔대요.","그 거대한 힘을 얻으려고 뮤세크를 담아 오래요."},c={"이제 가능성이 아주 커졌다며 기대해요.","모은 재료로 뮤세크를 원하는 대로 가둘 수 있대요."}},
[3128]={a={"의술사 우제리가 일을 마치려면 재료가 필요해요.","쪼개진 통나무와 질긴 힘줄, 금속 파편이 필요하대요.","다른 일을 하면서 함께 모아 달래요."},c={"재료와 뮤세크를 합치면 바라던 결과가 나올 거래요."}},
[3129]={a={"의술사 우제리는 무기에 뮤세크를 넣는 게 까다롭대요.","재료와 뮤세크가 다 모여 의식을 시작할 수 있대요.","잠시 기다려 달래요."},c={"약속대로 무기를 고르게 해 줘요.","생물들의 뮤세크가 무기 안에 봉인됐대요.","그 힘을 잘 쓰라고 해요."}},
[3161]={a={"마본 리벳시커는 과학자이자 보물 사냥꾼이래요.","옛 트롤들이 가즈리디안으로 장신구를 만들었대요.","그 재료를 더 모아 연구하고 싶으니 찾아 달래요."},c={"이 장신구는 연구에 딱 맞는다며 기뻐해요.","도와줘서 고맙다며 자기 투구를 돌려받을 수 있냐고 해요."}},
[3221]={a={"고위집행관 하드렉이 렌퍼럴이 당신을 찾았다고 해요.","렌퍼럴은 당신이 준 늑대 심장 이야기를 하고 싶대요.","그를 만나 보라고 해요."},c={"렌퍼럴은 앞서 가져온 늑대 심장에 대한 문제가 있대요."},nx=1359,nt="Zinge's Delivery"},
[3261]={a={"셀그라 다크쏜은 더 가르칠 게 없다고 해요.","조른 스카이시어는 남쪽 타우라조 야영지에 있대요.","가서 앞으로 어떻게 할지 물어보래요."},c={"조른은 사냥꾼의 길을 걸으러 왔냐고 물어요.","좋다며 이제 시작하자고 해요."},nx=882,nt="Ishamuhale"},
[3281]={a={"가즈록은 랩터를 잡았지만 은화는 아직이래요.","은화는 톱니항 남쪽 랩터 서식지에 있을 것 같대요.","랩터 서식지에서 도둑맞은 은화를 찾아 달래요."},c={"가즈록은 랩터가 소굴에 은화를 숨긴 걸 알고 놀라요.","랩터가 은화를 원했다니 믿기 어렵대요.","경비병들은 다음 달 월급을 당신 덕이라고 해요."}},
[3301]={a={"통가 룬토템의 아내 무라는 은빛소나무 숲에 갔대요.","무라는 병들어 죽어 가는 숲을 되살리려 한대요.","불모의 땅에서 얻은 등껍질을 무라에게 전해 달래요."},c={"무라는 등껍질 안에서 빛이 나서 놀라워해요.","이 등껍질에 은빛소나무 숲을 살릴 비밀이 있을지 모른대요."}},
[3321]={a={"트렌튼 라이트해머는 당신이 많이 애썼다고 해요.","그래서 작은 보상을 주려고 한대요.","이 장신구가 당신을 이곳에 데려온 물건이래요."},c={"Mithril Order의 대장장이로 인정한대요."}},
[3341]={a={"앤드류 브로넬은 가시덩굴 구릉 상황이 심각해졌대요.","가시멧돼지는 스컬지와 손잡고 혹한의 암네나르에게 지배당해요.","혹한의 암네나르를 끝장내 달래요."},c={"리치의 충성은 흔들리지 않는대요.","그런 충성은 파멸만 가져온다고 전하래요."}},
[3362]={a={"트란렉은 덤불나무 골짜기에 들어가고 싶어해요.","덤불나무괴물들이 골짜기에 진을 쳐 못 들어가요.","그 괴물들을 좀 처치해 달래요."}},
[3369]={a={"팔라 세이지윈드는 조각에서 악몽을 봤대요.","이 조각은 에메랄드의 꿈에서 나왔대요.","대드루이드 하뮬 룬토템에게 조각을 전해 달래요."},c={"팔라가 보내서 왔냐고 묻네요.","이런 얘기는 함부로 하면 안 된대요.","에메랄드의 꿈은 생각과 다르대요."}},
[3373]={a={"보석을 만지니 에라니쿠스의 목소리가 울려요.","트롤이 신을 다시 모시지 못하게 하려다 실패했대요.","이 보석을 정수의 샘에 넣어 악을 씻어 달래요."},c={"보석을 넣자 저주받은 신의 타락이 샘마저 더럽혔대요.","에라니쿠스는 고통스러워하며 살려 달라고 애원해요.","녹색용군단을 찾아 자기를 도와 달래요."},nx=3374,nt="The Essence of Eranikus"},
[3374]={a={"서약의 돌을 쓰자 이타리우스가 마음속으로 말을 걸어요.","에라니쿠스의 타락한 영혼을 구하는 일을 돕자고 해요.","먼저 속박하던 보석을 이타리우스에게 넘겨 달래요."},c={"이제 선택이 시작됐대요.","지금까지 선택은 옳았지만 앞으로 행동이 중요하대요.","앞으로의 행동에 따라 계속될지 정해진대요."},nx=3512,nt="In Eranikus' Own Words"},
[3376]={a={"용사 윈드페더는 타우렌이 계속된 전쟁으로 힘들다고 해요.","칼날가시 협곡의 뾰족털 가시멧돼지가 전쟁을 벌이고 있대요.","그 우두머리 족장 뾰족어금니를 처치해 달래요."}},
[3379]={a={"이글거리는 협곡의 거미는 그늘 거미줄의 원천이래요.","밀렵꾼 무리가 거미를 마구 죽이고 있대요.","밀렵꾼을 찾아 끝장내 달래요."},c={"잘했다고 칭찬하며 아직 못 본 그늘 직물이래요."},nx=3385,nt="The Undermarket"},
[3380]={a={"의술사 우제리는 편히 쉬지 못하는 영혼들 얘기를 해요.","땅속 깊이 묻힌 가라앉은 사원 얘기를 들었대요.","마본 리벳시커를 타나리스에서 찾아가 보래요."},c={"마본 리벳시커는 가라앉은 사원을 직접 봤대요.","더 듣고 싶냐며 흥미로운 얘기를 꺼내요."},nx=3444,nt="The Stone Circle"},
[3382]={a={"선장 바네사 벨티스는 안전한 정박지를 찾고 있었어요.","해가 지자마자 나가들이 배를 공격했대요.","다시 올 수 있으니 함께 맞서 달라고 부탁해요."},c={"선장 바네사 벨티스는 정말 고맙다고 했어요.","가장 치열한 전투였다며 선원을 더 살리지 못해 아쉬워해요.","지평선 정찰함의 생존 승객들에게 말을 걸어 보라고 해요."}},
[3385]={a={"닐리스 로크라브는 암거래상단에게 화가 나 있어요.","대상 코빅이 이글거리는 협곡에서 검은무쇠단과 가까이 지내요.","코빅과 딸깍이를 처치하고 대상의 가방을 가져와 달래요."},c={"닐리스는 암거래상단에게 큰 타격을 입혔다고 해요.","지도부도 부하를 더 보내기 전에 두 번 생각할 거래요.","가방에는 쓸 만한 게 없으니 가져도 된대요."},nx=3402,nt="The Undermarket"},
[3402]={a={"닐리스 로크라브가 심부름을 부탁해요.","대상 코빅을 물리쳤다는 소식을 비즈클릭이 반길 거래요.","가젯잔의 비즈클릭에게 직접 소식을 전해 달래요."},c={"비즈클릭은 코빅이 죽었다니 믿기지 않는대요.","그동안 암거래로 정직한 상인들을 괴롭혀 왔대요.","당신에게 큰 보상을 주겠다고 약속해요."}},
[3442]={a={"칼라란 윈드블레이드는 적의 감시탑을 노려야 한대요.","감시탑을 불태우려면 횃불이 필요하대요.","화염의 심장과 골렘 기름을 모아 오라고 해요."},nx=3443,nt="Forging the Shaft"},
[3443]={a={"완전무결한 불꽃에는 자루가 필요하대요.","검은무쇠단이 쓰는 토륨 도금 단검으로 자루를 만들 수 있대요.","토륨 도금 단검을 모아 칼라란 윈드블레이드에게 가져다 달래요."},nx=3452,nt="The Flame's Casing"},
[3444]={a={"마본 리벳시커는 가라앉은 사원에 다녀온 적이 있어요.","최근 뱀 문양이 새겨진 둥근 돌을 찾아 톱니항으로 보냈대요.","그 돌을 가져와 주면 더 자세히 말해 준대요."},c={"마본 리벳시커는 이 돌이 맞다고 확인해요.","이제 기억이 하나둘 떠오른대요."}},
[3446]={a={"마본 리벳시커는 석상을 밀었다가 함정에 걸렸어요.","방 바닥의 제단이 학카르의 것이었던 것 같대요.","돌무리를 가라앉은 사원의 제단에 가져다 달래요."},c={"돌무리를 틈에 끼우니 단단히 맞물렸대요.","이제 제단을 더 살펴보라고 권해요."}},
[3447]={a={"마본 리벳시커는 기억이 흐릿하대요.","가라앉은 사원의 석상들이 더 큰 보물의 비밀을 간직한 것 같대요.","중심 제단의 불빛이 무슨 뜻인지 알아봐 달래요."},c={"신상의 눈 장식을 옆으로 밀자 안이 보였대요.","석상 안에 있던 아탈라이 보물이 당신 것이 됐대요."}},
[3452]={a={"칼라란 윈드블레이드에게 횃불의 마지막 재료가 필요해요.","북서쪽 산의 황혼의망치단 야영지에 상징이 있대요.","라그나로스의 상징을 가져와 달래요."},c={"상징에서 나쁜 마력이 느껴진대요.","이 일에 딱 맞는 물건이래요."},nx=3453,nt="The Torch of Retribution"},
[3462]={a={"칼라란 윈드블레이드가 자신을 대신할 사람을 소개해요.","견습기사 몰트레이크가 응보의 횃불 쓰는 법을 자세히 가르쳐 준대요.","몰트레이크를 찾아가 얘기해 보라고 해요."},c={"몰트레이크는 공격할 준비가 됐냐고 물어요."},nx=3463,nt="Set Them Ablaze!"},
[3463]={a={"몰트레이크는 감시탑을 불태울 방법을 알려 줘요.","탑이 타면 경비병이 초소에 못 올라가 방어가 무너져요.","탑 안에서 횃불을 쓰되 검은무쇠단 경비병을 조심하래요."},c={"몰트레이크는 정말 영광스러운 광경이라고 해요.","그 광경이 영광스럽지 않으냐고 되물어요."},nx=3481,nt="Trinkets..."},
[3501]={a={"수집가 굼이샤는 드레니시스트 구슬을 원해요.","완전한 구슬은 찾기 힘들지만 부서진 조각은 땅에서 찾을 수 있대요.","불완전한 드레니시스트 조각을 가져오면 보상을 준대요."}},
[3504]={a={"벨그롬 록마울은 블러드 엘프 여자에게 속았어요.","그녀를 지키러 보낸 전사들이 모두 죽고 말았대요.","복수를 위해 발로르모크의 아그토르를 찾아가래요."},c={"아그토르는 그들이 워낙 강해서 돌아온 이가 없대요.","지원군이 왔으니 아직 방법이 있을지 모른대요.","같이 그녀를 벌하러 갈 거냐고 물어요."},nx=3505,nt="Betrayed"},
[3505]={a={"아그토르 블러드피스트가 복수의 첫걸음을 제안해요.","아즈샤라 북부 반도 남쪽 절벽에서 그녀의 일꾼들을 처치하래요.","그다음 학자 림토리의 야영지를 찾으라고 해요."},c={"책장을 넘기다 얇은 검은 비단 띠가 끼워진 쪽이 나왔대요.","그림 속 배치가 주변의 수정, 원과 닮았대요."},nx=3506,nt="Betrayed"},
[3506]={a={"고서를 읽어 보니 수정 하나가 원을 만든 자와 이어져 있어요.","다른 수정은 훨씬 더 사악한 존재와 이어져 있대요.","학자 림토리를 처치하고 머리카락을 아그토르에게 가져가래요."},c={"아그토르는 해냈다며 크게 기뻐해요.","벨그롬도 좋아할 거래요.","우리 전사들의 영혼이 드디어 평안해질 거래요."},nx=3507,nt="Betrayed"},
[3507]={a={"아그토르 블러드피스트가 벨그롬에게 가 보라고 해요.","벨그롬이 직접 그 머리카락을 보고 싶어 한대요.","오그리마의 벨그롬 록마울을 찾아가 달래요."}},
[3508]={a={"로라무스 탈리뻬데스는 당신 종족의 무모함을 본받을 만하대요.","라젤리크 부하의 보호막을 깨려면 희귀한 유물이 필요해요.","움직이지 말고 깨우침의 의식이 끝나길 기다려 달래요."},c={"그 짐승의 이름을 찾아야 한대요."},nx=3509,nt="The Name of the Beast"},
[3509]={a={"로라무스 탈리뻬데스는 악마 군주를 해칠 무기를 만들려 해요.","무기에는 악마의 진짜 이름이 새겨져야 한대요.","아즈샤라의 제왕 아크코로크를 찾아가 보래요."},c={"아크코로크는 악마 군주라는 말에 웃어요.","먼저 아크코로크를 도와야 정보를 준대요."},nx=3510,nt="The Name of the Beast"},
[3510]={a={"아크코로크의 아이들이 헤타에라에게 죽었대요.","헤타에라는 스스로 바다의 제왕이라 부르는 가짜 신이래요.","헤타에라를 쓰러뜨리고 머리를 가져가면 이름을 알려 준대요."},c={"아크코로크의 지혜를 나눌 만한 자를 드디어 만났대요."},nx=3511,nt="The Name of the Beast"},
[3511]={a={"아크코로크는 악마 군주 파멸자 라젤리크의 이름을 알려 준대요.","그 전에 머리에서 피를 빼내 담금질 재료를 만들어야 해요.","담금질 재료와 이름을 로라무스 탈리뻬데스에게 가져다 달래요."},c={"담금질 재료가 무기 제작에 필요한 독기를 더해 준대요.","무기를 만드는 마지막 단계가 한 번 남았대요."},nx=3602,nt="Azsharite"},
[3512]={a={"이타리우스는 보석으로 에라니쿠스와 대화할 방법을 찾고 있어요.","에라니쿠스는 악몽에 갇혀 죽음과 잠 사이에 있대요.","여명의 설원 동쪽의 영매 엄브런스를 찾아가 달래요."},c={"엄브런스는 이타리우스가 현명하게 보냈다고 해요.","엄브런스는 지금은 직접 도울 수 없다고 해요.","점술 도구를 되찾아야 에라니쿠스를 도울 수 있대요."}},
[3513]={a={"공문처럼 보이는 룬문자 두루마리가 있어요.","나이트 엘프와 관련됐다면 잿빛 골짜기 쪽 전초기지로 가야 한대요.","불모의 땅 북쪽 방어탑으로 가져다 달래요."},c={"오호, 이건 어디서 찾았냐고 묻네요."},nx=3514,nt="Horde Presence"},
[3514]={a={"이 두루마리는 열쇠지기 린타리엘의 전령에게서 나왔대요.","호드는 린타리엘의 전령을 용납하지 않겠대요.","갈퀴발톱굴 우두머리를 쓰러뜨리고 호드 깃발을 세워 달래요."},c={"정말 강하네요, 고마워요.","린타리엘을 쓰러뜨린 건 큰 일이래요.","이제 연합군 전령이 줄어들 거래요."}},
[3517]={a={"제디가는 아즈샤라에서 나름의 거래를 해 왔대요.","엘다라스 폐허에 명가 마법사들의 이름을 딴 서판이 있대요.","서판을 모아 제디가에게 가져오라고 해요."},c={"제디가는 서판 상태가 아주 좋다며 기뻐해요.","이 서판이면 관련된 모두에게서 좋은 값을 받을 거래요.","지체하지 말고 돈을 벌러 가자고 해요."}},
[3518]={a={"첫 번째 서판은 썬더 블러프의 타우렌 마가타에게 가야 해요.","마가타는 타우렌과 포세이큰의 동맹을 지지하는 장로예요.","베스아마라 서판을 마가타에게 가져다 달래요."},c={"마가타는 드디어 베스아마라 서판이 왔다며 반가워해요.","제디가가 무사해서 다행이라고 해요.","베스아마라는 명가의 영향력 있는 연금술사였대요."},nx=3562,nt="Magatha's Payment to Jediga"},
[3520]={a={"예킨야는 페랄라스 계곡천둥매의 영혼을 찾고 있어요.","계곡천둥매의 영혼은 고대 신과 이어져 있대요.","나뭇가지로 영혼을 불러내 모아서 돌아오래요."},c={"예킨야는 이제 더 말해 줄 때가 됐대요.","트롤들에게는 죽은 신 학카르가 언젠가 돌아온다는 예언이 있대요.","예킨야는 믿지 않지만 학카르의 정수는 큰 힘이 있대요."},nx=3527,nt="The Prophecy of Mosh'aru"},
[3523]={a={"벨리스트라즈는 구해 줘서 고맙다고 해요.","스컬지가 가시멧돼지와 손잡아 이런 참사가 났대요.","위험하지만 벨리스트라즈의 계획을 도와 달래요."},c={"정말 잘됐다고 기뻐하네요.","할 일이 많지만 잘 해내면 이길 수 있대요."},nx=3525,nt="Extinguishing the Idol"},
[3525]={a={"가시멧돼지가 무서운 우상을 화덕처럼 쓴대요.","벨리스트라즈가 그 우상의 불을 끄려 해요.","우상까지 호위하고 의식하는 동안 지켜 달래요."},c={"벨리스트라즈는 떠나고 불타는 화로만 남았어요.","불 속에 붉은 용이 나타나 말을 걸었어요.","당신들이 영웅이라며 보상을 내렸대요."}},
[3526]={a={"그레이엄 반 탈렌은 고블린 기계공학을 추천해요.","기계공학은 노움과 고블린 두 갈래로 나뉜대요.","가젯잔의 닉스에게 설명서를 가져가 보라고 해요."},c={"닉스 스프로켓스프링은 현명한 선택이라고 칭찬해요.","고블린 기계공학은 침착한 손이 필요하대요.","귀를 쫑긋 세우고 배워 보라고 해요."},nx=3638,nt="The Pledge of Secrecy"},
[3527]={a={"예킨야는 모쉬아루의 고대 예언이 필요하대요.","그 예언은 가젯잔 서쪽 줄파락에 나뉘어 적혀 있대요.","서판을 찾아 예킨야에게 가져오라고 해요."},c={"예킨야는 이 고대 서판을 하나로 합쳐 연구하겠대요.","당신에게 진 빚이 점점 커진대요."},nx=4787,nt="The Ancient Egg"},
[3528]={a={"예킨야는 학카르 화신의 정수를 모으려 해요.","학카르의 알을 가라앉은 사원의 성소로 가져가래요.","화신을 물리쳐 정수를 알에 담아 오라고 해요."},c={"학카르의 정수를 모았고 알에서 기운이 느껴진대요.","학카르가 다시 태어나면 무슨 짓을 할지 걱정이래요.","알을 안전하게 지켜 악한 손에 들어가지 않게 하겠대요."},nx=5065,nt="The Lost Tablets of Mosh'aru"},
[3541]={a={"제디가가 오그리마의 친구 제스리몬을 소개해요.","제스리몬은 골목길에 살아서 높은 건물 쪽을 찾아야 한대요.","진야엘 서판을 가져가면 후하게 값을 쳐준대요."},nx=3563,nt="Jes'rimon's Payment to Jediga"},
[3542]={a={"제디가가 언더시티의 안드론 건트를 소개해요.","언더시티 마법사들이 명가의 신비술을 연구하려 한대요.","마크리 서판을 가져다주고 사례금을 받아 오래요."},nx=3564,nt="Andron's Payment to Jediga"},
[3561]={a={"제디가가 위험한 인물에게 서판을 전하라고 해요.","대마법사 실렘은 아즈샤라를 내려다보는 언덕 위 탑에 살아요.","북쪽에서 경호원 사나스를 찾아 탑으로 가라고 해요."},c={"실렘은 샤엘하이 서판을 오랫동안 연구하고 싶었대요.","제디가에게 일을 잘했다고 전해 달래요.","제디가가 요구한 값을 치를 만한 가치가 있대요."},nx=3565,nt="Xylem's Payment to Jediga"},
[3562]={a={"마가타 그림토템은 제디가가 돌아오기를 기다려요.","마가타는 제디가가 일을 잘 끝마쳐서 기뻐해요.","마가타의 쪽지를 제디가에게 전해 달래요."},c={"마가타는 제디가가 생각보다 합리적이었다고 해요.","대신 보낸 사람 때문에 벌을 받을까 걱정했대요.","그녀가 그 서판을 정말 원했나 보다고 궁금해해요."}},
[3563]={a={"제스리몬은 제디가와 한 거래에 만족하고 있어요.","오그리마로 빨리 돌아오면 후하게 대접하겠대요.","제스리몬의 쪽지를 제디가에게 전해 달래요."}},
[3565]={a={"대마법사 실렘은 사례금을 주겠다고 해요.","제디가가 애타게 기다리고 있을 거라고 해요.","실렘의 쪽지를 제디가에게 가져가 달래요."},c={"제디가는 실렘이 말썽 없이 끝낸 게 놀랍대요.","실렘을 믿어도 될지도 모른다고 생각해요.","당신의 몫을 건네며 도와줘서 고맙다고 해요."}},
[3568]={a={"연금술사 큘리는 몸이 안 좋은 타우렌을 살피고 있어요.","그녀는 엘다라스 폐허의 웅덩이 물을 마시고 탈이 났대요.","해안의 웅덩이 물을 약병에 채워 가져오라고 해요."},nx=3569,nt="Seeping Corruption"},
[3569]={a={"연금술사 큘리가 테레사 윈드송에게 약을 전하라고 해요.","약을 마셔 봐야 나을지 알 수 있대요.","큘리의 비약을 언더시티의 테레사에게 가져다 달래요."},c={"테레사는 큘리가 너무 친절해서 오히려 불안하대요.","사제와 주술사도 도울 수 없어서 달리 방법이 없대요.","대지의 어머니가 자신을 지켜 주길 바란대요."},nx=3570,nt="Seeping Corruption"},
[3601]={a={"킴야엘은 블러드 엘프에게 고용됐다가 배신당했어요.","블러드 엘프가 킴야엘의 장비를 아직 가지고 있대요.","혼자서는 되찾을 수 없으니 장비를 찾아 달라고 해요."},c={"블러드 엘프를 제대로 혼내 줬다며 좋아해요.","블러드 엘프는 믿을 수 없다고 투덜대요.","수고비로 준 물건이 쓸모 있을 거래요."},nx=5534,nt="Kim'jael's \"Missing\" Equipment"},
[3602]={a={"로라무스 탈리뻬데스는 무기에 쓸 아즈샤리트가 필요해요.","절벽거인의 배설물이 굳어 생긴 튼튼한 수정이래요.","남쪽에서 아즈샤리트를 모으면 지옥사냥개가 돕는대요."},c={"로라무스는 아즈샤라의 일이 끝났다고 해요.","이제 다음 단계에 쓸 부품을 만들겠대요."},nx=3621,nt="The Formation of Felbane"},
[3621]={a={"로라무스 탈리뻬데스는 무기를 만들 준비가 됐대요.","담금질한 아즈샤리트로 악마의 힘을 다룰 대장장이가 필요하대요.","가시덤불 골짜기의 갈반을 찾아가 달래요."},c={"갈반은 재료를 얻기가 얼마나 힘들었을지 짐작된다고 해요.","아즈샤라에서 살아 돌아오는 이는 드물다고 해요."},nx=3625,nt="Enchanted Azsharite Fel Weaponry"},
[3625]={a={"갈반은 무기를 만드느라 시간이 걸린대요.","퇴마 저주의 힘은 일정 시간이 지나야 다시 쓸 수 있대요.","파멸자 라젤리크와 부하들에게 기회가 오면 바로 쓰래요."},nx=3626,nt="Return to the Blasted Lands"},
[3626]={a={"갈반은 구원의 때가 가까웠다고 해요.","새 무기를 들고 저주받은 땅으로 돌아가야 해요.","호드 영웅의 넋에게 마지막 지시를 받아 오라고 해요."},c={"갈반은 당신이 단단해 보인다고 해요.","파멸자 라젤리크와 그 부하들을 맞설 준비가 됐냐고 물어요."},nx=3627,nt="Uniting the Shattered Amulet"},
[3627]={a={"호드 영웅의 넋이 파멸자 라젤리크와 맞서려 해요.","먼저 파멸자 라젤리크의 심복 무리를 쓰러뜨려야 한대요.","아뮬렛 조각을 다 모아 돌아오래요."},c={"파멸자 라젤리크의 아뮬렛이 다시 완성됐대요.","라젤리크는 지휘 체계가 흐트러진 걸 느꼈대요.","그는 당신이 자기를 노리고 온다는 걸 안대요."},nx=3628,nt="You Are Rakh'likh, Demon"},
[3628]={a={"파멸자 라젤리크의 소굴은 저주받은 땅 산꼭대기에 있대요.","아뮬렛을 지니면 소굴을 드나들 수 있대요.","파멸자 라젤리크를 쓰러뜨리고 뿔을 가져다 달래요."},c={"오늘은 영원히 기억될 날이래요.","저주받은 땅의 악마 군주가 드디어 쓰러졌대요."}},
[3631]={a={"제브로스트는 아직 준비가 덜 됐다고 봐요.","스트라드 파선이 당신을 급히 보고 싶어 해요.","톱니항 위의 탑으로 서둘러 찾아가래요."},nx=4490,nt="Summon Felsteed"},
[3633]={a={"팅커위즈가 고급 기계공학은 두 갈래라고 해요.","고블린 쪽은 강력한 폭발물을 쓴대요.","고블린을 배우려면 설명서를 닉스 스프로켓스프링에게 가져가래요."},c={"닉스 스프로켓스프링이 잘 찾아왔다고 칭찬해요.","고블린 기계공학은 강한 마음과 차분한 손이 필요하대요.","귀 기울여 들으면 배울 게 있을 거래요."},nx=3638,nt="The Pledge of Secrecy"},
[3635]={a={"그레이엄 반 탈렌이 고급 기계공학은 두 갈래라고 해요.","노움의 발명품은 제대로 작동하는 일이 드물대요.","금속 서진을 배우려면 설명서를 무법항에 가져가래요."},c={"오글소프 오브노티쿠스는 잘 찾아왔다고 해요.","지식은 놈리건 지배층도 막지 못한대요.","자기가 떠나자 놈리건은 최고 기술자를 잃었대요."},nx=3642,nt="The Pledge of Secrecy"},
[3637]={a={"팅커위즈가 고급 기계공학은 두 분야로 나뉜대요.","노움은 세상을 바꾼다는 장치를 만들지만 잘 안 된대요.","금속 서진을 배우려면 설명서를 무법항에 가져가래요."},c={"오글소프 오브노티쿠스는 잘 찾아왔다고 해요.","지식은 놈리건 지배층도 막지 못한대요.","자기가 떠나자 놈리건은 최고 기술자를 잃었대요."},nx=3642,nt="The Pledge of Secrecy"},
[3638]={a={"닉스 스프로켓스프링이 고블린 기계공학을 소개해요.","고블린 기계공학은 돈이 되고 폭발력도 강하대요.","서약서에 서명한 뒤 다시 와서 얘기하래요."},nx=3639,nt="Show Your Work"},
[3639]={a={"닉스 스프로켓스프링이 당신의 작품을 보고 싶대요.","실력은 인정하지만 고블린 기술을 살펴보려 해요.","안전장치를 잠근 폭탄류를 가져오면 회원권을 준대요."},c={"고블린 기술자 회원권을 처음으로 받았대요.","회원권은 기간이 지나면 만료돼 교관에게 다시 내야 해요.","회원권이 없으면 새 설계도는 못 배우지만 알던 건 그대로래요."}},
[3642]={a={"오글소프 오브노티쿠스가 노움 기계공학을 소개해요.","노움 기술자가 되면 고블린 기계공학은 못 배운대요.","서약서에 서명한 뒤 다시 와서 얘기하래요."},nx=3643,nt="Show Your Work"},
[3643]={a={"오글소프 오브노티쿠스가 당신의 작품을 보고 싶대요.","실력은 인정하지만 노움 기술의 특성을 찾으려 해요.","미스릴관과 조준경, 허수아비를 가져오면 회원권을 준대요."},c={"노움 기술자 회원권을 처음으로 받았대요.","회원권이 만료되면 노움 교관에게 다시 내야 해요.","회원권이 없으면 새 설계도는 못 배우지만 알던 건 그대로래요."}},
[3761]={a={"운고로 분화구 흙에는 마법의 힘이 많대요.","세나리온 의회가 이 흙을 많이 조사하려 해요.","운고로 황야에서 흙을 모아 게드에게 가져다 달래요."},c={"게드는 흙 옮기는 걸 돕지 말라고 해요.","대드루이드 하뮬 룬토템이 다시 보자고 해요.","다음 일에는 약초학 지식이 도움이 된대요."},nx=3782,nt="Morrowgrain Research"},
[3762]={a={"여관주인 팔라가 노련한 모험가를 찾고 있대요.","세나리온 의회가 중요한 연구를 하고 있대요.","대드루이드 하뮬 룬토템을 장로의 봉우리에서 만나 보래요."},c={"대드루이드 하뮬 룬토템이 도와줘서 반갑대요.","이 일이 위험하지 않다고는 말할 수 없대요.","그래도 위험에 익숙해 보인다고 해요."},nx=3761,nt="Un'Goro Soil"},
[3782]={a={"대드루이드 하뮬 룬토템이 여명초를 연구하고 있대요.","여명초는 거의 알려지지 않은 수수께끼 약초래요.","씨앗 교환권을 바샤나 룬토템에게 가져가래요."},c={"바샤나 룬토템이 교환권으로 씨앗 꾸러미를 준대요.","씨앗은 비싸서 도와주는 사람이 일부 부담하래요.","여명초를 가져오면 보상이 비용보다 훨씬 크대요."},nx=3786,nt="Morrowgrain Research"},
[3783]={a={"우미 럼플스니커가 비밀 계획을 세웠대요.","친구들을 놀래 줄 기계설인을 만들 거래요.","남동쪽 설인들에게서 두꺼운 모피를 구해 달래요."},c={"우미 럼플스니커가 모피가 완벽하다고 좋아해요.","이제 순조롭게 출발했대요."},nx=977,nt="Are We There, Yeti?"},
[3784]={a={"여관주인 노먼이 노련한 모험가를 찾고 있대요.","세나리온 의회가 중요한 연구를 하고 있대요.","대드루이드 하뮬 룬토템을 장로의 봉우리에서 만나 보래요."},nx=3761,nt="Un'Goro Soil"},
[3786]={a={"바샤나 룬토템이 늘푸른 주머니를 건네줘요.","씨앗에 운고로 토양을 넣어 여명초를 키우래요.","여명초를 충분히 구하면 장로의 봉우리로 와 달래요."},c={"바샤나 룬토템이 잘했다고 칭찬해요.","여명초는 대드루이드에게 직접 전하겠대요.","여명초가 계속 필요하니 더 키워 와 달래요."}},
[3801]={a={"프랑클론 포지라이트는 돌다지 건축 방식을 만든 사람이래요.","그는 당신의 도움이 절실하대요.","도와주면 저주받은 도시 깊은 곳의 열쇠를 준대요."},nx=3802,nt="Dark Iron Legacy"},
[3802]={a={"파이너스 다크바이어가 무쇠지옥을 가지고 있대요.","석상에 망치를 두면 열쇠가 든 칸이 열린대요.","무쇠지옥을 타우릿산의 제단에 가져다 달래요."},c={"무쇠지옥이 석상 손에 딱 맞게 들어가요.","석상 밑동에 작은 칸이 열린대요."}},
[3821]={a={"탈트라크 프라우드터스크의 아내가 연락이 끊겼대요.","샤니 프라우드터스크가 수상한 의식을 조사하러 갔대요.","불타는 평원에 가서 그녀를 찾아봐 달래요."},c={"샤니 프라우드터스크가 탈트라크를 가엾어해요.","임무가 끝나면 부모님 집에 가기로 했대요.","이제 그 계획은 다 무너졌대요."},nx=3822,nt="Krom'Grul"},
[3822]={a={"샤니 프라우드터스크의 부대원들이 모두 죽었대요.","크롬그룰이 샤니를 고문해 죽였대요.","크롬그룰을 처치하고 코걸이를 탈트라크 프라우드터스크에게 돌려 달래요."},c={"탈트라크 프라우드터스크가 주저앉아 흐느껴요.","그녀가 없으니 반지는 아무 의미가 없대요.","반지는 가지든 버리든 상관없대요."}},
[3844]={a={"난파된 나룻배가 물가에 있어요.","나룻배가 여기 어떻게 왔는지 확실하지 않대요.","연못을 둘러보고 나룻배 주인의 단서를 찾아 달래요."},c={"연못 바닥에 물에 젖은 작은 배낭이 있대요."},nx=3845,nt="It's a Secret to Everybody"},
[3845]={a={"작은 배낭을 물가로 건져 냈대요.","배낭 속 물건을 보면 주인을 더 알 수 있을지 몰라요.","배낭 물건을 살펴 주인에게 돌려 달래요."},c={"링쿠가 물건을 보고 낯익다고 해요.","다만 확실하지는 않대요."},nx=3908,nt="It's a Secret to Everybody"},
[3881]={a={"윌리덴 마샬이 독립 원정대를 이끌고 있대요.","분화구를 얕봐서 주둔지에 중요한 보급품을 두고 왔대요.","식량 상자와 탐사 장비를 가져다 달래요."},c={"식량 상자와 탐사 장비를 모두 되찾았대요.","원정대와 자기들 목숨을 구했다고 고마워해요.","이제 당신은 우리 친구래요."}},
[3882]={a={"스파크 닐마이너는 땅 파는 일을 좋아하지 않아요.","공포의 터에서 죽은 공룡 뼈를 파기로 했대요.","살아 있는 공룡의 뼈를 가져와도 된대요."},c={"스파크 닐마이너가 이 뼈면 충분하다고 좋아해요.","짐승을 해쳤는지는 알고 싶지 않대요.","입 다물고 있으라며 보상을 건네요."}},
[3883]={a={"홀라니에 마샬이 고리쉬를 조사하고 있대요.","고리쉬는 운고로에 원래 살던 곤충이 아니래요.","고리쉬집 벽면 견본을 채취해 가져다 달래요."},c={"홀라니에 마샬이 이 정도면 충분하다고 해요.","당신 덕분에 연구를 할 수 있었대요.","보상을 더 주고 싶지만 줄 게 많지 않대요."}},
[3884]={a={"구겨진 일지를 발견했대요.","일지는 윌리덴 마샬의 것이라고 적혀 있대요.","분화구 북쪽에서 윌리덴 마샬에게 일지를 돌려 달래요."},c={"윌리덴 마샬이 자기 일지라며 반가워해요.","잃어버린 줄 알았는데 돌려받아 고맙대요."}},
[3901]={a={"어둠의사제 사비스는 당신이 포세이큰에 가능성을 보였다고 해요.","덜그럭거리는 해골은 좀비보다 강하대요.","그 해골 수를 줄여 다시 증명해 달래요."},c={"사비스는 당신이 자유를 누릴 자격이 있다고 해요.","많은 이들이 반대하겠지만 우리는 다시 묶이지 않는대요.","보상을 받고 갈 길을 가라고 해요."}},
[3902]={a={"죽음의경비병 살테인은 쓸모 있는 일을 찾는 이에게 말해요.","곧 더 깨어날 시체들에게 줄 장비를 모으려 해요.","데스넬에서 쓸만한 물건을 찾아 달래요."},c={"살테인은 당신이 쓸모없지 않다며 칭찬해요.","모은 물건 중 좋은 것 하나를 보상으로 준대요."}},
[3906]={a={"장로들이 자연의 기운이 흐트러진 걸 느꼈대요.","검은무쇠단 드워프들이 사악한 영혼을 불러냈대요.","검은바위 산 채석장에서 멸망의 파이론을 처치해 달래요."},c={"썬더하트는 이럴 수가 없다며 놀라요.","파이론을 쓰러뜨린 게 끝이 아니래요.","검은바위 산 깊은 곳에 더 악한 기운이 있대요."},nx=3907,nt="Disharmony of Fire"},
[3907]={a={"당신 주변에서 사악한 기운이 느껴진대요.","검은바위 나락에 숨어 사악함을 부리는 자가 있대요.","불의군주 인센디우스를 찾아 그 주인을 알아내 달래요."},c={"썬더하트가 쿠르니야의 서판을 움켜쥐고 놀라요.","라그나로스가 여기 있다니 옛 신의 장군이래요.","검은바위 산 깊은 곳은 더 조심하래요."}},
[3908]={a={"링쿠는 어떻게 여기 왔는지 기억이 안 난대요.","검을 보니 뭔가 기억나는 것 같대요.","여명의 설원 도노바 스노우덴에게 검을 가져가 달래요."},c={"도노바 스노우덴이 이 검을 단련할 수 있대요.","작업하는 동안 링쿠가 왜 늦었는지 말해 달래요.","링쿠는 원래 잊어버리는 사람이 아니래요."},nx=3909,nt="The Videre Elixir"},
[3909]={a={"도노바 스노우덴은 링쿠가 기억을 잃었다는 말에 놀라요.","검은 아직 덜 완성됐고 앞날의 비약이 필요하대요.","페랄라스 북쪽에서 그레간 브루스퓨를 찾아 달래요."},c={"도노바 스노우덴이 한 병을 써서 확인하겠대요.","보니 이게 바로 그 비약이래요."},nx=3912,nt="Meet at the Grave"},
[3912]={a={"앞날의 비약을 마시면 보통 볼 수 없는 자와 말할 수 있대요.","링쿠의 검과 함께 가젯잔 밖 무덤에서 비약을 마시래요.","다른 모습으로 북쪽 산의 바위틈에서 개리얀을 찾으래요."},nx=3913,nt="A Grave Situation"},
[3913]={a={"개리얀이 묘지에 눈에 띄는 묘비가 있다고 해요.","그 묘비 안에 비밀이 숨겨져 있대요.","묘비를 밀어 비밀을 알아보래요."},c={"묘비를 밀자 밑에 작은 홈이 드러나요.","그 홈에 링쿠의 검을 넣으니 딱 맞아요."},nx=3914,nt="Linken's Sword"},
[3914]={a={"눈부신 빛이 번쩍하고 검이 변신했대요.","검을 다시 집을 수 있게 됐대요.","링쿠의 명검을 링쿠에게 가져다 달래요."},nx=3941,nt="A Gnome's Assistance"},
[3921]={a={"스퍼터밸브가 사모플랜지를 망가뜨린 것 같대요.","지하광산 동료들이 그 물건에 관심을 보였대요.","부서진 사모플랜지를 웨니키 볼트버킷에게 가져가 달래요."},c={"웨니키는 사모플랜지가 뭔지 모르지만 신기해해요.","안에서 정교한 톱니 소리가 나서 고쳐 보고 싶대요."},nx=3922,nt="Nugget Slugs"},
[3922]={a={"웨니키 볼트버킷은 사모플랜지를 고칠 재료가 떨어졌대요.","동쪽 진흙늪의 연장통에 용접용 철괴가 있을 거래요.","용접용 철괴를 모아 돌아와 달래요."},c={"웨니키는 철괴를 얻어 기뻐하며 이제 작업을 하겠대요."},nx=3923,nt="Rilli Greasygob"},
[3923]={a={"웨니키 볼트버킷이 사모플랜지를 고치려다 실패했대요.","더 손보면 오히려 나빠질까 봐 걱정이래요.","오그리마의 릴리 그리지가브에게 가져가 달래요."},nx=3924,nt="Samophlange Manual"},
[3924]={a={"릴리 그리지가브는 사모플랜지를 고치려면 설명서가 필요해요.","경쟁자였던 사장 코퍼플러그가 설명서를 쥐고 있었대요.","돌무더기 광산에서 설명서를 가져와 달래요."},c={"릴리는 설명서를 얻어 와서 기뻐했어요.","톱니항의 스퍼터밸브도 보상을 주고 싶대요."}},
[3941]={a={"링쿠가 중요한 일을 기억하지 못한대요.","마샬의 야영지 동굴에 J.D. 콜리라는 노움이 있대요.","J.D. 콜리에게 링쿠 일을 아는지 물어봐 달래요."},c={"J.D. 콜리가 잠깐 기다리라고 해요.","새 수정 조합을 시험하고 있대요."},nx=3942,nt="Linken's Memory"},
[3942]={a={"J.D. 콜리는 링쿠가 처음 왔을 때 이상한 말을 했대요.","링쿠는 에리단 블루윈드를 만나야 한다고 했대요.","악령의 숲 남부에서 에리단 블루윈드를 찾아가 보래요."},nx=4084,nt="Silver Heart"},
[3961]={a={"링쿠가 여기 온 이유는 불바람을 없애려는 거였대요.","J.D. 콜리는 링쿠가 장치에 관심 없는 걸 봤대요.","아쿠에멘타스의 은토템을 링쿠에게 가져다 달래요."},c={"링쿠가 J.D. 콜리가 도와줬냐고 물어요."},nx=3962,nt="It's Dangerous to Go Alone"},
[3962]={a={"링쿠는 불바람과 싸우러 왔던 걸 기억했대요.","이제 영웅은 링쿠가 아니라 당신이래요.","불바람을 쓰러뜨리고 황금 불길을 가져오래요."},c={"링쿠가 황금 불길은 고향에 돌려보내겠대요.","당신이 없었다면 자기가 누군지도 몰랐을 거래요.","고마워서 선물을 주겠대요."}},
[3981]={a={"명사수 갈라마브의 동료 가르갈이 화살에 맞았대요.","쪽지에 고르샤크 사령관의 서명이 있었대요.","검은바위 나락에서 사령관 고르샤크를 찾아 달래요."},c={"고르샤크가 시간이 없으니 잘 들으래요.","이건 기밀이라 당신에게만 말한대요."},nx=3982,nt="What Is Going On?"},
[3982]={a={"사령관 고르샤크는 스랄의 도움으로 이곳에 왔대요.","일부러 잡혀서 아이언포지 공주의 정보를 모으고 있대요.","경비병이 오니 고르샤크를 지켜 달래요."},c={"고르샤크가 아슬아슬했다고 해요.","경비병들이 당신이 있다는 걸 알아챘대요.","더 많은 경비병이 올 거래요."},nx=4001,nt="What Is Going On?"},
[4001]={a={"고르샤크는 맞은편 감방의 카란과 말을 많이 못 했대요.","카란에게 해칠 뜻이 없다고 설득했대요.","카란에게 공주 정보를 얻어 스랄에게 전해 달래요."},c={"이건 호드가 세상 정세를 바꿀 기회래요.","이번 임무는 실패하면 안 된대요."},nx=4002,nt="The Eastern Kingdoms"},
[4002]={a={"스랄이 당신이 좋은 정보를 가져왔다고 칭찬해요.","드워프를 도우면 동부 왕국과 관계가 좋아진대요.","임무를 맡을 준비가 됐는지 묻대요."},c={"이제 되돌릴 수 없대요."},nx=4003,nt="The Royal Rescue"},
[4003]={a={"스랄이 검은무쇠단 드워프들을 공격하려 해요.","공주 모이라 브론즈비어드가 제왕에게 잡혀 있대요.","제왕을 없애고 공주를 구해 달래요."},nx=4004,nt="The Princess Saved?"},
[4004]={a={"모이라 공주는 남편을 잃고 몹시 화가 났어요.","뱃속 아이는 아버지 없이 태어날 거래요.","스랄에게 돌아가 이 일을 전하라고 해요."}},
[4005]={a={"에리단 블루윈드가 보급품 가방을 들고 타나리스로 가 달래요.","불바람과 싸울 토템이 필요하대요.","해적단 소굴의 돌 원 안에서 책을 읽어 달래요."},c={"J.D. 콜리는 불바람을 알고 있대요.","분화구 가운데 있어서 다들 거리를 둬요.","가까이 가면 바위길에서 밀려난대요."},nx=3961,nt="Linken's Adventure"},
[4021]={a={"콜카르 무리가 복수하러 불모의 땅에 왔대요.","지금 서쪽에서 이 감시탑을 향해 오고 있대요.","장군 크롬자르를 쓰러뜨리고 깃발 조각을 가져오래요."},c={"콜카르를 물리쳤다고 기뻐하네요.","그 일을 Thrall에게 꼭 전하겠대요."}},
[4022]={a={"용군단이 이글거리는 협곡에서 한 일을 알고 있대요.","키루스 테레펜터스가 그 일을 직접 확인하려 해요.","검은용군단 허물을 키루스에게 보여 달래요."},c={"키루스는 허물을 자세히 살펴봤대요.","쓸모없지는 않다고 인정했대요."},nx=4024,nt="A Taste of Flame"},
[4024]={a={"키루스 테레펜터스는 불의 정수를 맛보고 싶어 해요.","검은바위 나락에 사는 밸가르는 순수한 화염으로 된 존재래요.","밸가르를 처치하고 불의 일부를 가져다 달래요."},c={"키루스는 불의 정수를 냉큼 받아 갔대요.","보상을 챙겨 얼른 떠나라고 해요."}},
[4061]={a={"제사장 테오도라 뮬바다니아는 기계들을 조사하고 있어요.","기계들이 불타는 평원에서 들어오는 것 같대요.","불타는 평원의 바위 골렘에게서 원소 파편을 구해 달래요."},c={"제사장 테오도라 뮬바다니아가 파편을 하나씩 살펴봤대요.","파편 바닥에 이니셜이 새겨져 있대요."},nx=4062,nt="The Rise of the Machines"},
[4062]={a={"파편에 G.L.A.라는 약자가 새겨져 있대요.","그 아래 계급 표시는 낮은 계급인 것 같대요.","동쪽 야영지의 로트윌 베리아투스에게 견본을 가져가 달래요."},c={"로트윌 베리아투스는 얼굴이 하얗게 질렸대요.","그는 이 표시를 알아본대요."},nx=4063,nt="The Rise of the Machines"},
[4063]={a={"로트윌 베리아투스는 예전에 아젤마크를 직접 처치했대요.","이 일이 아젤마크의 솜씨 같아서 걱정이래요.","검은바위 나락의 아젤마크를 없애 달래요."},c={"로트윌 베리아투스는 머리가 살이 아니라 기계래요.","아젤마크를 본뜬 또 다른 기계래요.","아젤마크가 쓰러져도 또 다른 자가 그 자리를 채울 거래요."}},
[4081]={a={"장군 고어투스가 사령관 앵거포지의 세력을 없애라고 해요.","앵거포지의 부하들은 카르가스 원정대를 대량 학살한 자들이래요.","검은바위 나락에서 앞줄을 무너뜨리면 포상을 준대요."},c={"첫 공격으로 앵거포지가 꽤 당황할 거래요.","고어투스는 할 일이 많다며 가라고 해요.","현상수배 게시판에서 다른 일을 확인하래요."},nx=4082,nt="KILL ON SIGHT: High Ranking Dark Iron Officials"},
[4082]={a={"암살단장 렉스로트가 고위 관리들의 위치를 알아냈대요.","그들은 잠긴 문 너머에서 우리 군대를 없앨 훈련을 하고 있대요.","검은바위 나락에 가서 그들을 없애라고 해요."},nx=4122,nt="Grark Lorkrub"},
[4084]={a={"에리단 블루윈드는 당신의 친구가 찾던 것을 안다고 해요.","운고로 분화구 중심에 불바람이라는 악이 있대요.","악령의 숲에서 은백색 발톱과 강철나무 심장을 구해 오래요."},nx=4005,nt="Aquementas"},
[4102]={a={"메이베스 리버브리즈는 악령의 숲 식물들을 걱정해요.","정화하는 법을 알지만 믿을 만한 사람에게만 알려 준대요.","북쪽 강철나무 굴에서 핏빛 호박석을 가져오래요."},c={"메이베스 리버브리즈는 이 호박석으로 타락을 이길 길을 찾겠대요.","정령을 쓰러뜨린 일로 당신을 믿게 됐대요.","이제 악령의 숲을 정화할 때가 왔대요."}},
[4120]={a={"탈로 쏜후프는 적을 잘 아는 게 사냥꾼에게 중요하대요.","악령의 숲 곰과 늑대들이 오염돼 미쳐 버렸대요.","악령의 숲에 가서 그 야수들과 직접 싸워 보래요."},c={"탈로는 야수들이 정신없이 사납대요.","부패에 대해 더 알아보라고 해요.","늘 적을 잘 알아야 한대요."}},
[4121]={a={"그랄크 로크럽은 포로가 되었는데도 당신을 비웃어요.","경비가 삼엄한 검은바위 요새에 숨어들긴 어렵대요.","그랄크를 불타는 평원과 검은바위 산 너머로 호송해 달래요."},nx=4132,nt="Operation: Death to Angerforge"},
[4122]={a={"렉스로트는 반역자 그랄크 로크럽을 쫓고 있대요.","그랄크는 검은바위 오크들에게 중요한 정보를 흘렸대요.","그를 찾아 족쇄를 채워 검은바위 산으로 데려가 달래요."},nx=4121,nt="Precarious Predicament"},
[4123]={a={"맥스워트 우버글린트는 오래전부터 보석 하나를 찾아 왔어요.","검은무쇠단이 주먹만 한 산의 정수를 금고에 넣고 잠갔대요.","그 보석을 힘으로 빼앗아 가져다 달래요."},c={"맥스워트는 보석을 보고 크게 감탄했대요.","상상보다 훨씬 아름답다며 보상을 건넸대요."}},
[4132]={a={"장군 고어투스가 마지막 임무를 맡기려 해요.","사령관 앵거포지가 우리 군대를 대량 학살한 자래요.","앵거포지를 처단하고 고어투스에게 돌아가 달래요."},c={"고어투스는 악당이 드디어 처단됐다며 기뻐해요.","당신은 정말 대단하다고 칭찬해요.","충성의 상징으로 이 메달을 준대요."}},
[4133]={a={"어둠마법사 비비안 라그레이브가 도움이 필요하대요.","검은바위 나락 검은무쇠단이 만드는 술 소문을 쫓고 있어요.","카르가스에 가서 비비안을 찾아가 얘기해 보래요."},c={"비비안 라그레이브는 와 줘서 고맙다고 해요.","여기는 멋은 있지만 편의 시설이 부족하대요."},nx=4134,nt="Lost Thunderbrew Recipe"},
[4134]={a={"어둠마법사 비비안 라그레이브가 술 제조법을 찾고 있어요.","헐레이 블랙브레스가 썬더브루 맥주 제조법을 훔쳤다는 소문이래요.","검은바위 나락에서 그 제조법을 빼앗아 가져다 달래요."},c={"비비안은 제조법을 연구소에 보내 연구하겠대요.","언젠가 이 술이 드워프들을 상대로 쓰일지도 모른대요.","비비안은 그게 아주 재미있다고 해요."}},
[4136]={a={"유카 스크류스피곳의 동생 리블리는 늘 집안 돈을 날렸대요.","무법항의 레빌가즈 남작이 리블리에게 현상금을 걸었대요.","검은바위 나락에 숨은 리블리를 찾아 달래요."},c={"유카는 리블리를 찾았다니 아주 기뻐해요.","동생이 조용히 따라오지 않았던 게 아쉽대요.","당신 덕분에 집안이 행복해졌대요."}},
[4145]={a={"라리온은 무이긴 때문에 길을 잃었다고 화가 나 있어요.","무이긴이 보낸 식물 괴물들이 자꾸 괴롭힌대요.","무이긴의 보급을 끊게 붉은꽃잎 식물들을 사냥해 달래요."},c={"라리온은 도와줘서 고맙지만 나쁜 소식이 있대요."},nx=4147,nt="Marvon's Workshop"},
[4146]={a={"리브 리즐픽스가 잡초 구제장치를 만들었대요.","장치를 쓰려면 아탈라이 아지랑이라는 연료가 필요해요.","아탈학카르 신전에서 연료를 모아 라리온에게 가져가 달래요."},nx=4148,nt="Bloodpetal Zapper"},
[4147]={a={"라리온은 무이긴이 그 식물을 기르고 있다는 걸 알아냈어요.","이번엔 대화보다 싸우는 게 낫대요.","톱니항의 마본 리벳시커에게 도움을 청하라고 해요."},c={"리브는 마본이 오래전에 타나리스로 떠났다고 해요.","고대 트롤 유적을 연구하러 갔대요.","그럼 무엇이 필요한지 묻는대요."},nx=4146,nt="Zapper Fuel"},
[4148]={a={"라리온은 무이긴 쪽 해충들 때문에 골치 아파요.","구제장치를 맞추려면 대상 생물의 표본이 필요하대요.","분화구에 가서 붉은꽃잎 싹을 모아 오래요."},c={"라리온은 장치가 잘 맞을 것 같아 흡족해해요.","해충을 보면 망설이지 말고 장치를 쓰래요."}},
[4201]={a={"지배인 나그마라는 병사 락노트에게 퇴짜를 맞았어요.","락노트의 마음을 여는 물약을 만들려고 해요.","재료를 모아 가득 찬 약병을 가져다 달래요."}},
[4243]={a={"카르나 렘트레블은 가장 아끼는 발명품을 잃었어요.","기계 유인원 에이미 01과 연락이 끊겼대요.","운고로 분화구 버섯 바위굴에서 에이미를 찾아 달래요."},c={"에이미 01을 살펴보니 어깨와 머리가 찌그러져 있어요.","전원도 들어오지 않는 상태래요."},nx=4244,nt="Chasing A-Me 01"},
[4244]={a={"에이미 01의 계기판에 수리 방법이 적혀 있어요.","미스릴 형틀을 갈아 끼우면 고칠 수 있을지도 모른대요.","미스릴 형틀을 찾아 에이미에게 돌아가 달래요."},c={"에이미 01의 낡은 형틀을 새 미스릴 형틀로 바꿨어요.","이제 전원을 껐다가 다시 켜기만 하면 된대요."},nx=4245,nt="Chasing A-Me 01"},
[4245]={a={"에이미 01을 카르나 렘트레블에게 데려가야 해요.","전원을 켜면 무슨 일이 벌어질지 모른대요.","운고로 분화구에서 에이미 01을 호위해 달래요."},c={"카르나는 에이미 01이 다시 움직여서 기뻐해요.","찌그러진 자국은 조금만 고치면 된대요."}},
[4284]={a={"J.D. 콜리는 분화구 곳곳의 수정에 힘이 있을 것 같대요.","여러 실험을 했지만 아직 아무것도 알아내지 못했대요.","여러 색 수정을 모아 와 달래요."},c={"J.D. 콜리는 이제 실험을 계속하겠대요.","도와줘서 고맙다고 해요."}},
[4285]={a={"J.D. 콜리는 수정탑 소문이 사실이라고 믿어요.","북쪽 어딘가에 수정탑이 있다고 들었대요.","그 수정탑의 위치를 찾아 달래요."},c={"J.D. 콜리는 소문이 사실이라고 믿는대요."}},
[4287]={a={"J.D. 콜리는 분화구에서 이상한 수정탑 소문을 들었대요.","그 수정탑이 모은 수정들과 관련 있을 것 같대요.","분화구 동쪽에서 그 수정탑을 찾아 달래요."},c={"운고로는 정말 이상한 곳이라고 해요.","분화구에 들어서면 다른 세상 같대요."}},
[4288]={a={"J.D. 콜리는 아직 실험에 성공하지 못했대요.","소문의 수정탑을 찾으면 실험에 도움이 될지도 모른대요.","분화구 서쪽에서 수정탑을 찾아 달래요."},c={"분화구 가장자리에는 숨은 곳이 많대요.","꾸불꾸불한 길도 살펴보라고 해요."}},
[4289]={a={"토르와 패스파인더는 이 분화구가 특별하다고 여겨요.","북쪽의 운고로 고릴라들이 힘을 시험할 상대래요.","그 가죽을 가져와 힘을 증명해 달래요."},c={"토르와 패스파인더는 당신의 힘을 인정했대요.","가죽은 부족의 옷으로 쓰겠대요.","대지모신께 감사 기도를 올리자고 해요."},nx=4301,nt="The Mighty U'cha"},
[4290]={a={"토르와 패스파인더의 형이 라르코르위에게 목숨을 잃었대요.","그 형은 라르코르위의 사냥감에서 고기를 몰래 뜯었대요.","라르코르위가 잡은 사냥감에서 고기를 훔쳐 오래요."},c={"토르와 패스파인더는 고기를 좋다고 받았대요.","라르코르위가 요즘 잘 먹는다며 이상하다고 해요.","맞설 준비가 될 때까지 고기를 보관해 준대요."},nx=4291,nt="The Scent of Lar'korwi"},
[4291]={a={"토르와 패스파인더는 라르코르위를 유인할 계획을 세웠대요.","라르코르위는 짝을 여럿 두는 가장 힘센 수컷이래요.","서쪽 알 근처 암컷에게서 페로몬샘을 가져와 달래요."},c={"토르와 패스파인더는 샘이 좋다며 흡족해해요.","이제 라르코르위를 끌어낼 수 있겠대요.","그의 눈을 보면 죽음을 알게 될 거래요."},nx=4292,nt="The Bait for Lar'korwi"},
[4292]={a={"토르와 패스파인더는 이번 계획이 가장 어려울 거래요.","북쪽 산길의 큰 뼈들 근처에 고기를 놓으래요.","라르코르위를 물리친 뒤 머리를 가져오라고 해요."}},
[4293]={a={"연금술사 퓰리는 악령의 숲 진흙괴물을 조사하려 해요.","스컬지의 공격 뒤로 진흙괴물이 땅 위로 올라왔대요.","악령의 숲 진흙괴물 샘플을 모아 와 달래요."},c={"연금술사 퓰리는 샘플이 아주 좋다고 해요.","전에 들은 짐작이 맞았을지도 모른대요.","더 조사해야 한다고 해요."}},
[4294]={a={"연금술사 퓰리는 운고로 분화구의 진흙괴물을 조사하고 싶대요.","운고로는 아무 손길도 닿지 않은 순수한 곳이래요.","운고로의 진흙괴물 샘플을 모아 와 달래요."},c={"퓰리는 샘플들의 순수함에 깜짝 놀랐대요.","고대의 신들의 흔적을 떠올리게 한대요.","더 조사해 봐야 한대요."}},
[4296]={a={"맥스워트 우버글린트는 일곱 현자의 전설을 쫓아 왔대요.","그는 일곱 현자의 지식으로 부자가 되고 싶어 해요.","타우릿산의 폐허에서 서판 글을 베껴 와 달래요."},c={"맥스워트는 서판을 찾아 베낀 솜씨에 감탄해요.","약속한 보수를 건넸대요."}},
[4300]={a={"제스리몬은 검은손 도적단에 도움을 청해요.","운고로 분화구에 흰 발톱을 가진 라바사우루스가 있대요.","흰 발톱을 가져오면 값을 후하게 쳐준대요."},c={"제스리몬은 발톱이 쓸 만하다며 고마워해요.","그 발톱으로 당신을 위한 무기를 만들지도 모른대요."}},
[4301]={a={"토르와 패스파인더가 운고로에서 큰 고릴라를 보았대요.","북쪽에 사는 우차는 덩치가 아주 커서 위험하대요.","우차를 물리치고 가죽을 가져와 달래요."}},
[4321]={a={"J.D. 콜리가 수정탑 정보를 듣고 재미있어 해요.","계산을 좀 해야 해서 답을 바로 못 준대요.","잠시 뒤에 다시 찾아와 달라고 해요."},c={"J.D. 콜리는 계산을 마치고 도표가 맞기를 바란대요.","모든 내용을 정리한 설명서를 건네줘요.","이제 수정에 대한 질문에 답해 줄 수 있대요."}},
[4324]={a={"요르바 스크류스피곳의 남동생 리블리가 쓸모가 생겼대요.","여동생 유카가 리블리를 찾다 불타는 평원까지 갔대요.","용병의 도움이 필요하니 유카를 만나 달래요."},c={"유카는 정말로 동생 리블리를 찾고 있었대요.","리블리를 다 못 데려오면 머리만이라도 괜찮대요."},nx=4136,nt="Ribbly Screwspigot"},
[4402]={a={"갈가르는 시험의 골짜기가 너무 더워 지쳤대요.","특제 선인장 사과 별미를 만들고 싶은데 사과가 없대요.","선인장 근처에서 선인장 사과를 따다 달래요."},c={"갈가르가 약속한 선인장 사과 별미를 만들어 줬어요.","덤으로 뭔가를 조금 더 챙겨 준대요."}},
[4449]={a={"나무 간이화장실 안에 갇힌 사람이 있대요.","검은무쇠단 지질학자들이 문을 잠가 가뒀대요.","지질학자들을 혼내 주고 비단 옷감도 구해 달래요."},c={"나무 간이화장실 안의 사람이 정말 고맙대요.","이제 지질학자들이 다시 올 걱정은 없대요."},nx=4450,nt="Ledger from Tanaris"},
[4450]={a={"나무 간이화장실 안의 사람이 임무를 하나 부탁해요.","크린클 굿스틸이 이글거리는 협곡 등에서 물건을 찾고 있대요.","장부를 받아 물건을 모아 크린클 굿스틸에게 가져다 달래요."},c={"크린클 굿스틸은 물건이 빠짐없이 다 있다며 기뻐해요.","잘 모아 와서 고맙다고 해요."}},
[4451]={a={"열쇠 머리에 검은무쇠단 간이 화장실용이라고 새겨졌어요.","무슨 뜻인지, 어디에 쓰는지 알 수 없대요.","이글거리는 협곡을 뒤져 열쇠의 쓸모를 찾아 달래요."},c={"로키드가 열쇠를 찾았다며 고마워해요.","열쇠로 문을 열어 자기를 꺼내 달래요."}},
[4489]={a={"카알 소울리퍼는 당신의 힘이 커진 걸 알아봤어요.","그래서 이제 보상을 받을 때가 됐대요.","톱니항 위쪽의 스트라드 파선을 찾아가래요."},c={"스트라드 파선이 다시 와 줘서 비꼬듯 반겨요.","힘을 쫓는 당신은 불나방 같다고 해요."},nx=4490,nt="Summon Felsteed"},
[4490]={a={"스트라하드 파르산은 노력한 당신에게 보상을 주려 해요.","하지만 앞으로 지옥마 소환은 훨씬 어려워진대요.","이제 이 힘을 받아 쓰라고 해요."},c={"행운을 빌고 다음에 또 보자고 해요."}},
[4491]={a={"링고 스타가 열사병에 걸린 것 같아요.","이 지역을 조사하다 더위를 견딜 수 없었대요.","마샬의 야영지 스프래글 프록에게 데려다 달래요."},c={"스프래글 프록은 링고가 지쳤지만 무사해서 기뻐해요.","링고를 찾아 줘서 고맙다고 해요."}},
[4492]={a={"친구 링고가 남쪽 화산에 갔는데 오래 안 와요.","스프래글 프록이 많이 걱정하고 있대요.","불기둥 마루에서 링고를 찾아 달라고 부탁해요."},c={"링고 스타는 누군가 찾아 줘서 정말 기뻐해요."},nx=4491,nt="A Little Help From My Friends"},
[4494]={a={"질지빈 드럼로어는 실리시드가 큰 위협이라고 걱정해요.","실리시드의 힘이 운고로 분화구에서 나오는 것 같대요.","가젯잔의 연금술사 페슬저그에게 이 얘기를 전해 달래요."},c={"페슬저그는 질지빈이 보내서 왔다는 걸 알았대요.","실리시드와 싸워 본 경험이 아주 소중하대요.","운고로 분화구가 그들의 심장일지도 모른대요."},nx=4496,nt="Bungle in the Jungle"},
[4496]={a={"연금술사 페슬저그가 실리시드를 조사해 보니 벌과 비슷하대요.","여왕을 없애면 나머지도 혼란에 빠진대요.","운고로 분화구 소굴에서 미끼 재료를 구해 달래요."},c={"향낭과 토양 모두 상태가 아주 좋대요.","이제 미끼를 만들 테니 잠시 기다려 달래요.","실리시드가 가젯잔을 덮치기 전에 막을 수 있을지도 모른대요."},nx=4507,nt="Pawn Captures Queen"},
[4501]={a={"운고로 분화구에 테러닥스 수가 늘어 행인이 위험해요.","그래서 실력 있는 투사를 찾는 현상수배가 붙었어요.","테러닥스를 줄인 뒤 스프래글 프록을 찾아가라고 해요."},c={"스프래글 프록은 테러닥스가 아주 무서웠대요.","테러닥스를 줄여 줘서 고맙다고 해요.","이제 마샬의 야영지 밖으로 나가도 안전할 것 같대요."}},
[4502]={a={"리브 리즐픽스는 마본 리벳시커의 수습생이에요.","스승이 오래 자리를 비워서 직접 실험을 하려 해요.","운고로 분화구에서 불의 정령의 재를 구해다 달래요."},c={"리브 리즐픽스는 재가 연구에 딱 맞는다며 기뻐해요.","연구 결과를 가장 먼저 알려 주겠대요."}},
[4503]={a={"쉬즐이 여기서 길을 잃고 발이 묶였대요.","그리핀이나 박쥐는 무서워서 못 타겠대요.","테러닥스와 디메트로돈의 갈퀴 비늘을 구해 달래요."},c={"쉬즐은 비늘이 딱 맞는다며 좋아해요.","이걸로 비행선을 띄울 수 있을 거래요."}},
[4504]={a={"트란렉이 초강력 접착제를 만들어 돈을 벌려 해요.","일반 타르는 끈적임이 부족해서 쓸모가 없대요.","잿구덩이 근처 송진괴물의 타르를 구해 달래요."},c={"트란렉은 타르가 딱 맞다며 기뻐해요.","그런데 손이 붙어서 떨어지지 않는대요.","끈적임을 지우는 약이 진짜 돈이 된대요."}},
[4505]={a={"위나 해저드는 콘스텔라스 폐허의 달샘에 관심이 많아요.","샘이 오염돼 사티로스 서식지가 됐대요.","고양이에게 먹일 샘물을 조금 가져다 달래요."},c={"위나 해저드는 이 오염을 적에게 쓸 방법을 찾겠대요."},nx=4506,nt="Corrupted Sabers"},
[4506]={a={"위나 해저드의 고양이가 샘물을 먹고 몸집이 크게 불었대요.","그 힘을 써 보려고 고양이를 달샘 옆에 풀어 달래요.","그다음 고양이를 위나에게 다시 데려와 달래요."}},
[4507]={a={"페슬저그가 여왕을 불러낼 미끼를 건넸어요.","소굴 부화장의 수정에 미끼를 바르면 여왕이 나온대요.","여왕을 처치한 뒤 그 뇌를 가져다 달래요."},c={"페슬저그는 이번 승리가 대단하다고 해요.","실리시드가 이게 전부는 아닐 것 같대요."}},
[4509]={a={"연금술사 페슬저그는 가젯잔의 힘만으로는 부족하대요.","오그리마의 질지빈 드럼로어가 호드 고위층과 친구래요.","질지빈 드럼로어에게 최신 보고서를 전해 달래요."},c={"질지빈 드럼로어는 보고서가 고맙지만 도움이 될지 모르겠대요.","호드는 얼라이언스 말고는 위협을 무시한대요.","그래도 실리시드를 무찌르는 데 힘써야 한대요."},nx=4511,nt="Calm Before the Storm"},
[4511]={a={"질지빈 드럼로어가 도와준 덕분에 여기까지 왔대요.","실리시드의 근원은 운고로가 아닐지도 모른대요.","쪽지를 은행의 카루스에게 전하면 감사 선물을 준대요."}},
[4521]={a={"트룰 페일베인이 여명의 설원에 나이트 엘프의 비밀이 숨어 있대요.","그곳의 올빼미야수들이 그 비밀을 지키고 있대요.","올빼미야수를 처치해 길을 열어 달라고 부탁해요."},c={"트룰 페일베인은 이제 여명의 설원 깊이 들어갈 수 있다고 좋아해요.","더 해 볼 준비가 됐냐고 물어요."},nx=4741,nt="Wild Guardians"},
[4542]={a={"용사 문혼은 켄타우로스 침략이 늘었다고 걱정해요.","이 소식을 빨리 알려야 한다고 다급해해요.","높새바람 봉우리의 절벽파수꾼 롱혼에게 전갈을 전해 달래요."},c={"켄타우로스가 보급 상단을 습격해 일행을 모두 죽였대요.","롱혼은 이 일을 그냥 두지 않겠다고 해요."},nx=4841,nt="Pacify the Centaur"},
[4621]={a={"함장 피랠론은 무법항 지도층 때문에 붉은해적단이 답답하대요.","함장 시혼과 남작 레빌가즈를 처치하면 명예 제독이 된대요.","두 사람을 처치하고 함장 피랠론에게 돌아와 달래요."},c={"함장 피랠론은 제독이 됐다며 기뻐해요.","이 모자는 어디서도 구할 수 없는 거래요.","보는 사람마다 붉은해적단 제독으로 알아볼 거래요."}},
[4641]={a={"칼툰크가 이제 호드를 위해 싸워도 된대요.","처음엔 덜 위험한 일부터 하는 게 좋대요.","서쪽 동굴 막사에 있는 고르넥을 찾아가 보래요."},nx=788,nt="Cutting Teeth"},
[4642]={a={"연금술사 퓰리가 악령의 숲 샘플로 수액괴물을 만들었대요.","상자를 들고 운고로 분화구에서 순수한 수액괴물을 찾래요.","둘이 어떻게 반응하는지 보고 남은 것을 가져다 달래요."},c={"연금술사 퓰리는 그렇게 반응할 줄은 몰랐다며 놀라요.","환경이 이런 변화를 일으키는지 더 살펴보겠대요."}},
[4721]={a={"정찰꾼이 여명의 설원 남부에 동굴들을 봤대요.","올빼미야수들이 귀한 걸 지키는 것 같대요.","더 사나워진 광포한 올빼미야수를 처치해 달래요."},c={"트룰 페일베인은 열심히 해 준 것에 고마워해요.","이제 여명의 설원 계획을 진행할 수 있대요."}},
[4724]={a={"명사수 갈라마브가 검은늑대 무리 이야기를 꺼내요.","도끼부대 검은늑대들의 어미는 할리콘이래요.","그 어미를 처치해 달라고 부탁해요."}},
[4726]={a={"팅키 스팀보일이 불타는 평원의 용혈족을 연구해 왔대요.","새끼용 속박장치 900으로 정수를 뽑을 수 있을 거래요.","새끼용을 처치해 정수를 가져다 달래요."},c={"팅키는 정수를 얻어서 기뻐하며 잘했다고 해요.","이 정수가 연구에 아주 큰 도움이 될 거래요.","언젠가 새끼용이나 그 알을 잡는 법을 배우고 싶대요."},nx=4808,nt="Felnok Steelspring"},
[4729]={a={"키블러는 애완동물을 파는 고블린 상인이에요.","검은늑대를 길들여 준다고 해요.","검은바위 첨탑에서 새끼 검은늑대를 우리에 담아 달래요."},c={"키블러는 딱 좋은 때에 데려왔다며 기뻐해요.","더 늦었으면 길들일 수 없었을 거래요."}},
[4734]={a={"팅키 스팀보일이 알껍질급속냉각기를 만들었대요.","검은용의 알을 얼리는 기계래요.","검은바위 첨탑 둥지에서 시험하고 결과를 알려 달래요."},c={"팅키는 기계가 잘 됐다며 기뻐해요.","더 멀리 닿는 새 버전을 만들고 있었대요.","검은바위 첨탑에 다시 갈 때 쓰라고 줘요."},nx=4735,nt="Egg Collection"},
[4735]={a={"팅키 스팀보일이 용의 알을 모을 준비가 됐대요.","알을 얼린 뒤 수집전자 모듈로 모으면 된대요.","모은 알을 화염 마루의 팅키 스팀보일에게 가져다 달래요."},nx=5522,nt="Leonid Barthalomew"},
[4737]={a={"제브로스트는 당신이 결국 타락에 빠질 거라고 봐요.","하지만 다들 그 말에 찬성하는 건 아닌 것 같아요.","미네라 보이드렌더가 더 강해질 도구를 만들어 준대요."},c={"제브로스트가 보냈다니 반갑다고 해요.","원한다면 실력에 맞는 도구를 만들어 준대요."},nx=1796,nt="Components for the Enchanted Gold Bloodrobe"},
[4739]={a={"카알 소울리퍼는 당신에게서 자신감이 느껴진다고 해요.","미네라 보이드렌더는 비전 마법을 가르친대요.","준비됐다면 스트라드의 탑으로 찾아가라고 해요."},c={"카알 소울리퍼가 보냈군요. 반갑다고 해요.","원한다면 실력에 맞는 도구를 만들어 준대요."},nx=1796,nt="Components for the Enchanted Gold Bloodrobe"},
[4741]={a={"여명의 설원 북부에 더 사나운 올빼미야수가 나타났대요.","달빛 깃든 올빼미야수가 호드를 성가시게 한대요.","그 야수들을 처치하고 서식지를 살펴봐 달래요."},nx=4721,nt="Wild Guardians"},
[4742]={a={"승천의 인장에는 빈 홈이 파여 있대요.","홈마다 사령관을 상징하는 보석을 넣어야 한대요.","하부 요새 장군들의 보석을 찾아 밸란에게 가져다 달래요."},c={"밸란의 모습이 잠시 흐려졌다가 돌아와요.","모은 보석들은 사라지고 벼려지지 않은 승천의 인장이 준비됐대요.","이제 마지막 단계만 남았대요."},nx=4743,nt="Seal of Ascension"},
[4743]={a={"승천의 인장은 검은용의 불꽃으로 벼려야 한대요.","웜타라크의 의지는 누구도 꺾을 수 없다고 해요.","엠버스트라이프의 의지를 꺾고 용력의 보주를 쓰라고 해요."},c={"밸란이 마지막 주문을 외우고 인장이 완성됐대요.","인장에 보호 주문을 걸어 두었대요.","가장 힘든 순간에는 붉은용군단의 힘을 쓸 수 있대요."}},
[4767]={a={"엘루는 와이번 조련사들을 위해 와이번을 모으고 있어요.","와이번이 늘었지만 수요를 따라가지 못한대요.","마루둥지에서 와이번 알을 구해다 달래요."},c={"이 알로 와이번 조련사가 될 다음 단계를 밟고 싶대요.","감사의 표시로 선물을 주고 행운을 빌어요."}},
[4768]={a={"어둠마법사 비비안 라그레이브가 서판을 찾고 있대요.","이미 죽은 드워프 우르헬트 다크스톤의 글이 적혀 있대요.","위험해도 검은바위 첨탑에서 서판을 가져다 달래요."},c={"서판의 공식은 연구에 며칠은 걸릴 거래요.","이 연구가 좋은 결실을 맺을 거라고 믿는대요.","큰 도움을 받았다며 고마워해요."}},
[4769]={a={"연금술사 진게가 카르가스의 비비안 라그레이브에게서 소식을 들었대요.","검은바위 첨탑 안에 옛 기록이 있을 거래요.","카르가스에 가서 비비안과 얘기해 보래요."},c={"비비안은 검은바위 첨탑에 옛 연금술 비법이 적힌 서판이 있대요.","서판을 가져올 도움이 필요해서 와 줘서 기쁘대요.","편히 앉으라며 자세히 설명해 준대요."},nx=4768,nt="The Darkstone Tablet"},
[4770]={a={"파오카 스위프트마운틴은 마루둥지에서 길을 잃었어요.","모테가 파이어메인은 그가 없어진 줄 모른대요.","백사장 야영지까지 데려다 달래요."},c={"모테가는 파오카를 토템에 묶어 뒀어야 했다고 해요.","그동안 생긴 피해를 이걸로 조금이나마 갚고 싶대요."}},
[4771]={a={"베티나 비글징크가 용의 알을 담던 용기에 여명의 계략을 넣었대요.","언데드 마법사 벡투스가 스칼로맨스에서 무리를 이끌어요.","스칼로맨스 강당 문 근처에 두고 벡투스를 처치하래요."},c={"벡투스가 쓰러졌다고 베티나가 기뻐해요.","여명의 계략이 효과가 있었는지는 잘 모르겠대요.","그래도 잘 해결해 줘서 고맙다고 해요."}},
[4781]={a={"미네라 보이드렌더는 마법의 황금 혈로브를 만들려고 해요.","금빛 실타래는 구하기 어렵고 만들 줄 아는 이도 적대요.","무법항의 시즈크 굿스티치에게 금괴를 가져가래요."},c={"시즈크 굿스티치는 금괴가 딱 좋다고 해요.","실타래는 만드는 데 시간이 걸려서 다시 와야 한대요."},nx=4782,nt="Components for the Enchanted Gold Bloodrobe"},
[4782]={a={"시즈크 굿스티치는 실타래를 아직 만드는 중이래요.","미네라 보이드렌더에게 시간이 좀 걸린다고 전해 달래요.","재료를 다 모은 뒤 다시 와서 실타래를 받으래요."},c={"실타래가 없지만 이해한다고 해요.","그럼 다음 단계를 준비할 수 있겠냐고 물어요."},nx=4783,nt="Components for the Enchanted Gold Bloodrobe"},
[4783]={a={"미네라 보이드렌더는 혈로브에 쓸 재료가 더 필요해요.","잊혀진 땅은 지금도 혼돈이 지배하는 곳이래요.","서릿발분노 사티로스의 피와 하급 지옥정령석을 가져다 달래요."},c={"재료가 딱 좋다며 기뻐해요.","지금 준비하는 동안 남은 재료를 구하러 가래요."},nx=4784,nt="Components for the Enchanted Gold Bloodrobe"},
[4784]={a={"미네라 보이드렌더가 로브를 마무리하려고 해요.","무법항의 시즈크 굿스티치에게 고급 금빛 실타래를 받아 오래요.","아라시 고원의 이글거리는 석탄과 직접 만든 영혼의 조각을 가져오래요."},c={"재료가 다 모여서 이제 준비가 됐대요.","당신이 기뻐할 거라고 믿는대요."},nx=4786,nt="The Completed Robe"},
[4786]={a={"미네라 보이드렌더가 지금 로브를 만들어 준대요.","잠깐이면 되니 멀리 가지 말래요.","로브를 완성하면 다시 찾아가 받으래요."},c={"로브가 완성됐어요. 자랑스럽게 입으래요.","타락에 맞서려면 강한 의지가 있어야 한대요.","당신의 의지가 당신 것이면 크게 성공한대요."}},
[4787]={a={"예킨야가 모쉬아루의 예언서에 나온 알을 찾고 있어요.","이 알은 학카르의 정수를 담을 수 있대요.","진타알로 원형 극장 뒤 동굴에 있으니 가져다 달래요."},c={"예킨야가 고개를 숙여 감사를 표해요.","힘과 용기는 오래 기억될 거래요."},nx=3528,nt="The God Hakkar"},
[4788]={a={"발굴조사단장 아이언부트가 모쉬아루 서판을 살피고 있어요.","나머지 서판은 검은바위 첨탑의 가시불꽃부족 트롤이 갖고 있대요.","험한 검은바위 첨탑에서 서판을 찾아 가져다 달래요."},c={"아이언부트는 서판을 찾았다니 믿을 수 없다며 놀라요.","정말 영웅이라고 칭찬해요.","앞으로 닥칠 일을 막으려면 영웅이 필요하대요."},nx=8181,nt="Confront Yeh'kinya"},
[4808]={a={"팅키 스팀보일은 새끼용의 알도 얼려 보관할 수 있을 것 같대요.","그걸 시험하려면 특별한 기계 부품이 필요하대요.","눈망루 마을의 펠노크 스틸스프링에게 편지를 전해 달래요."},c={"펠노크는 팅키가 불타는 평원에서 연구 중이래요.","편지에 기계 부품이 필요하다고 적혀 있대요."},nx=4809,nt="Chillwind Horns"},
[4809]={a={"펠노크 스틸스프링이 팅키 스팀보일의 부품을 거의 다 갖췄대요.","중요한 부품인 서리바람 키메라의 뿔이 모자라대요.","온전한 서리바람 키메라의 뿔을 가져다 달래요."},nx=4810,nt="Return to Tinkee"},
[4810]={a={"펠노크 스틸스프링이 소포를 다 준비했대요.","이 소포를 불타는 평원의 팅키 스팀보일에게 전해 달래요.","팅키가 자기에게 신세 졌다는 말도 전해 달래요."},c={"팅키는 소포를 가져왔다며 바로 일하겠다고 해요.","많이 도와줘서 고맙다고 해요.","나중에 더 중요한 일도 부탁할 수 있대요."},nx=4907,nt="Tinkee Steamboil"},
[4821]={a={"버섯구름 봉우리에 괴상한 알이 있다는 소문이 돌아요.","뱀들이 자기 알처럼 지켜서 가까이 가기 어렵대요.","뱀 동굴에서 그 알을 가져와 달래요."},c={"드디어 그 신비한 알이 손에 들어왔다며 반가워해요.","그런데 알을 보고 깜짝 놀라 말을 잇지 못해요."},nx=4865,nt="Serpent Wild"},
[4841]={a={"절벽파수꾼 롱혼은 켄타우로스 때문에 분노에 차 있어요.","우리 쪽 사람들이 복수를 하고 싶대요.","높새바람 봉우리 북쪽 켄타우로스 야영지를 공격해 달래요."},c={"절벽파수꾼 롱혼이 고마움의 뜻으로 보상을 건네요."},nx=5064,nt="Grimtotem Spying"},
[4842]={a={"도노바 스노우덴은 여명의 설원 온천이 이상하다고 생각해요.","남쪽 끝까지 가면 공기가 텁텁해지고 하늘이 어두워진대요.","그곳을 직접 보고 돌아와 달라고 부탁해요."},c={"검은속삭임 협곡의 악마들 때문이라고 도노바 스노우덴이 말해요.","그 악마들이 땅에 영향을 주는 것 같대요.","더 강해진 뒤에 깊이 들어가라고 해요."}},
[4862]={a={"키블러는 길들인 흉악한 괴물을 사려는 사람이 있대요.","비쥬를 검은바위 첨탑에 보냈는데 소식이 끊겼대요.","첨탑 거미알을 모아다 달라고 부탁해요."},c={"알이 정말 많다며 좋아해요.","약속대로 길들인 괴물 한 마리를 줘요.","물리지 않게 조심하라고 당부해요."}},
[4865]={a={"하가르 라이트닝후프가 직접 보고도 믿기 힘들대요.","버섯구름 봉우리에 복수의 물결이 닥쳤대요.","백사장 야영지의 모테가 파이어메인을 서둘러 찾아가래요."},c={"복수라니! 아리카라 전설이 사실이었군요.","이 문제는 당장 해결해야 한대요."},nx=5062,nt="Sacred Fire"},
[4866]={a={"털보 존은 세상에서 가장 강한 독 중 하나래요.","검은바위 부족이 그 독을 '여왕의 독'이라 부른대요.","독에 중독된 채 돌아오면 그 독을 짜내겠대요."}},
[4881]={a={"카나티 그레이클라우드가 버섯구름 봉우리에 야영지를 세웠어요.","그를 없애려고 작은 전초기지에 모인대요.","카나티 그레이클라우드에게 가서 암살 음모를 알려 달래요."},c={"카나티는 그들이 자기를 죽이려 한다니 발끈해요.","타우렌이 어떻게 싸우는지 보여 주겠대요."},nx=4966,nt="Protect Kanati Greycloud"},
[4882]={a={"쓰러뜨린 올빼미야수의 목에서 목걸이가 떨어졌어요.","목걸이가 빛났다 흐려져서 중요한 건지 몰라요.","피멍울 초소의 트룰 페일베인에게 가져가 보래요."},nx=4883,nt="Guarding Secrets"},
[4883]={a={"트룰 페일베인은 올빼미야수는 알아도 마법은 몰라요.","목걸이가 무엇인지 알려 줄 사람을 안대요.","썬더 블러프의 나라 와일드메인을 찾아가 보래요."},c={"목걸이의 기운은 한 곳에서 나온대요.","올빼미야수들은 원래 신성한 곳을 지키던 존재래요.","더 깊이 알아보라고 당부해요."}},
[4903]={a={"고어투스 장군이 검은바위 첨탑 주민들을 처단하래요.","대군주 오모크와 대장군 부네 같은 자들이 대상이래요.","처단하고 중요한 문서도 가져와 달라고 해요."},c={"장군 고어투스의 얼굴이 잠시 창백해졌어요."},nx=4941,nt="Eitrigg's Wisdom"},
[4904]={a={"라코타 윈드송은 아르낙의 청혼을 거절했어요.","그날 밤 아르낙이 그녀를 납치해 동생이 목숨을 잃었대요.","먹구름 봉우리에서 빠져나가게 도와 달래요."},c={"탈리아 앰버하이드는 라코타가 무사히 돌아와 기뻐해요.","당신이 도운 덕분에 라코타가 탈출했대요."}},
[4907]={a={"펠노크 스틸스프링은 팅키 스팀보일의 심부름을 왔어요.","팅키가 또 도움이 필요한 것 같대요.","용 연구에 관한 일이니 팅키를 만나 보래요."},c={"펠노크의 말이 맞았다며 도움을 또 청해요.","이번에는 정말 위험한 일이래요.","준비됐냐고 물어요."},nx=4734,nt="Egg Freezing"},
[4921]={a={"만크릭은 전투 중에 아내와 떨어졌어요.","아내는 혼자 적을 막다가 에워싸였대요.","아내의 흔적을 찾아 돌아와 달래요."},nx=95774,nt="Her Name Is Olgra"},
[4941]={a={"장군 고어투스가 렌드가 살아 있다는 말을 믿지 못해요.","렌드는 몇십 년 전에 죽은 줄 알았대요.","오그리마의 아이트리그를 만나고 스랄과 상의해 달래요."},c={"스랄은 전해 준 소식에 당황한 모습이래요."},nx=4974,nt="For The Horde!"},
[4961]={a={"타베사는 소환사의 보주가 오염의 출처라고 봐요.","보주를 쓰려면 안의 악마를 쫓아내야 한대요.","강한 주문을 준비하고 친구가 있으면 데려가래요."},c={"악마에게 잊지 못할 교훈을 줬다며 칭찬해요.","이제 정화된 보주를 가지고 돌아가래요."},nx=4976,nt="Returning the Cleansed Orb"},
[4962]={a={"수행사제 위툴라는 지옥사냥개의 영혼을 잡으려는 당신을 반겨요.","지옥의 루비로 지옥사냥개의 영혼을 가둘 수 있대요.","잊혀진 땅의 지옥사냥개에게 루비를 써 보래요."},c={"미네라 보이드렌더는 영혼을 보고 잘했다고 해요.","영혼과 보주가 모이면 합쳐 준대요."}},
[4963]={a={"수행사제 마가즈는 지옥불정령의 영혼을 잡으려는 당신을 반겨요.","지옥불 에메랄드로 지옥불정령의 영혼을 가둘 수 있대요.","잊혀진 땅의 지옥불정령에게 에메랄드를 써 보래요."},c={"미네라 보이드렌더는 영혼을 보고 잘했다고 해요.","영혼과 보주가 모이면 합쳐 준대요."}},
[4964]={a={"미네라 보이드렌더가 다르오라힐의 보주를 만들고 있어요.","새로 얻은 악마를 그 보주에 넣는대요.","완성되면 지팡이나 구 중에서 고를 수 있대요."},c={"완성됐으니 지팡이와 구 중에 고르라고 해요.","지옥사냥개를 잡은 건 대단한 업적이래요."}},
[4966]={a={"카나티 그레이클라우드가 암살자들에게 노림을 당하고 있어요.","켄타우로스가 생각보다 많을지도 모른대요.","사악한 암살자들을 물리치게 도와 달래요."},c={"카나티 그레이클라우드가 고마워하며 인사해요.","당신이 없었다면 막아 내지 못했을 거래요."}},
[4967]={a={"제브로스트는 당신을 한심하다고 여겨요.","그래도 힘 있는 이들은 당신이 더 받을 만하다고 봐요.","톱니항 위 탑의 미네라 보이드렌더를 찾아가 보래요."},c={"지식이 아닌 힘을 찾는 당신이 반갑대요.","준비가 됐다면 도와줄 수 있다고 해요."},nx=1799,nt="Fragments of the Orb of Orahil"},
[4969]={a={"카알 소울리퍼는 당신이 잘하고 있다고 칭찬해요.","아직은 다른 종족이 만든 무기에 기대야 한대요.","준비가 되면 미네라 보이드렌더를 찾아가래요."},c={"지식이 아닌 힘을 찾는 당신이 반갑대요.","정말 준비가 됐다면 도와줄 수 있대요."},nx=1799,nt="Fragments of the Orb of Orahil"},
[4971]={a={"크로미가 안돌할에서 시간이 조작되고 있다고 해요.","기생충 때문에 크로미의 작업이 더뎌졌대요.","시간의 재배열기로 기생충을 없애 달래요."},nx=4972,nt="Counting Out Time"},
[4972]={a={"크로미는 피해를 계속 고치려고 해요.","그러려면 멈춘 시간의 장식품이 필요하대요.","폐허의 잠긴 상자에서 찾아 가져다 달래요."},c={"크로미가 바로 이거라며 고마워해요.","이 물건은 나중에 쓸모가 있을 수도 있대요.","쓸지 말지는 당신에게 달렸대요."}},
[4974]={a={"스랄은 렌드가 검은용군단만 믿고 큰 짓을 꾸민다며 화났어요.","검은바위 첨탑에서 대족장 렌드를 찾아 처치하래요.","처치하고 오그리마로 돌아오래요."},c={"검은바위 세력에 큰 타격을 입혔대요.","대족장이 쓰러져서 검은바위 군단이 혼란에 빠졌어요."},nx=6566,nt="What the Wind Carries"},
[4975]={a={"미네라 보이드렌더가 노오라힐의 보주를 만들고 있어요.","새로 얻은 악마를 그 보주에 넣는대요.","완성되면 지팡이나 구 중에서 고를 수 있대요."},c={"완성됐으니 지팡이와 구 중에 고르라고 해요.","지옥불정령을 잡은 건 큰 업적이래요."}},
[4976]={a={"타베사가 정화된 지옥의 보주를 당신에게 맡겼어요.","톱니항의 미네라 보이드렌더에게 가져가 달래요.","유혹과 타락을 이겨 내라는 당부도 해요."},c={"미네라 보이드렌더는 보주가 딱 좋다며 칭찬해요.","이제 어떤 악마를 가둘지 골라야 한대요."}},
[4981]={a={"렉스로트는 고블린을 믿지 말라고 경고해요.","요원 비쥬가 키블러의 사주로 우리를 배신했대요.","비쥬를 찾아 살려서 데려오래요."},nx=4982,nt="Bijou's Belongings"},
[4982]={a={"비쥬는 밤마다 몰래 도시를 돌며 정보를 적었대요.","경보가 울려 물건을 숨기고 도망쳤대요.","숨겨 둔 물건을 찾아 가져다주면 돌아가겠대요."},c={"비쥬는 해냈다며 기뻐해요.","렉스로트가 자기를 혼내려던 일을 잊을 거래요.","당신을 자기 영웅이라고 불러요."},nx=4983,nt="Bijou's Reconnaissance Report"},
[4983]={a={"비쥬는 이 보고서로 오명을 씻고 싶대요.","오크를 상대하는 데 큰 도움이 될 거래요.","카르가스의 렉스로트에게 전해 달래요."}},
[4984]={a={"멀그리스 딥리버는 역병 때문에 짐승들이 고통받는다고 해요.","자비로운 해방만이 짐승들을 구할 방법이래요.","근처의 역병 걸린 늑대를 찾아 처치해 달래요."},c={"멀그리스 딥리버는 늑대들의 영혼이 쉬게 됐대요.","편안하게 보내 줘서 고맙다고 해요.","이곳에는 고통받는 짐승이 더 있어서 또 도움을 청해요."},nx=4985,nt="The Wildlife Suffers Too"},
[4985]={a={"멀그리스 딥리버는 불곰들이 역병에 걸렸다고 해요.","근육이 굳고 살이 썩어 고통받고 있대요.","직접 손으로 편히 보내 달라고 부탁해요."},c={"멀그리스 딥리버는 불곰들의 고통이 끝났다고 해요.","가지에 무언가를 적어 남겼대요.","그 말을 마치고 멀그리스는 숨을 거뒀어요."}},
[4987]={a={"숨진 타우렌 드루이드의 손에 떡갈나무 가지가 있었어요.","가지 껍질에 드루이드 문자가 새겨져 있고 따뜻해요.","썬더 블러프 세나리온 의회에서 도움을 받으래요."},c={"나라 와일드메인은 멀그리스 딥리버가 떠나서 슬퍼해요.","가지에 적힌 역병에 대한 지식을 연구하겠대요.","당신 덕분에 그의 노력이 헛되지 않았대요."}},
[5021]={a={"재니스 펠스톤은 유령이 되어 집에 머물러 있어요.","소포를 꼭 전해야 한다며 애태우고 있어요.","말 옆에 있을 소포를 찾아 전해 달래요."},c={"헛간에 있던 소포 하나가 눈에 띄었어요.","재니스 펠스톤의 유령이 찾던 소포일지도 모른대요."}},
[5023]={a={"소포는 로데론의 제레미어 펠스톤에게 보낸 것이에요.","제레미어가 살아 있는지는 확실하지 않대요.","언더시티의 왕실감독원에게 행방을 물어보래요."},c={"바우하우스는 제레미어가 역병 전 도시에 살았다고 해요.","지금은 제레미어 페이슨이라는 이름을 쓴대요.","그 사람이 바퀴벌레 장수가 아니냐고 되물어요."},nx=5049,nt="The Jeremiah Blues"},
[5041]={a={"크로스로드에 필요한 보급품 운반차가 습격을 당했대요.","그동안 서슬갈기일족과 맞서 온 걸 보고 부탁하대요.","서슬갈기일족 진영에서 크로스로드 보급상자를 찾아 달래요."}},
[5047]={a={"Pip Quickwit은 괴수 뱃속에서 살덩이를 훔쳐 왔대요.","말리퍼스가 이런 걸로 뭘 할지 보여줄 거래요.","눈망루 마을의 말리퍼스에게 가져다 달래요."},c={"말리퍼스가 Pip Quickwit이 살아 있냐고 놀라 물어요.","옷이 잘 작동했냐며 이 물건을 살펴봐요."}},
[5049]={a={"왕실감독원 바우하우스가 소포의 주인을 알아냈어요.","주인은 언더시티의 바퀴벌레 상인 제레미어 페이슨이래요.","은행 근처에서 구걸하고 있으니 찾아가 보래요."},nx=5050,nt="Good Luck Charm"},
[5050]={a={"올엠마는 사람을 잘못 봤다며 사과해요.","여동생이 쓰던 행운의 부적 조각을 갖고 있대요.","재니스 펠스톤에게 조각을 갖다 달래요."},c={"재니스 유령이 조각을 받고 당신을 바라봐요.","당신에게 부적 반쪽은 어디 있냐고 물어요.","두 조각이 모여야 함께할 수 있대요."},nx=5051,nt="Two Halves Become One"},
[5051]={a={"재니스 펠스톤의 유령이 너무 춥다고 해요.","남편 존의 부적 조각이 있어야 다시 만날 수 있대요.","펠스톤 농장에서 나머지 조각을 찾아 붙여 달래요."},c={"재니스 유령은 부적을 받고 자기가 풀려났다고 해요.","이제 부적은 필요 없으니 당신이 가지래요.","이 부적이 당신에게도 위로가 되길 바란대요."}},
[5052]={a={"뾰족털일족은 땅에서 캔 혈석 파편을 부적처럼 써요.","뻐드렁니는 그 물건의 비밀을 안다고 해요.","많이 가져가면 아감마간의 축복을 준대요."},c={"뻐드렁니는 당신이 이해했다며 반가워해요.","그의 부족은 뻐드렁니를 등졌다고 해요."},nx=879,nt="Betrayal from Within"},
[5054]={a={"눈 덮인 산에 톱니이빨곰 우르시우스가 있대요.","재빠르고 영리해서 도전한 자들은 모두 쫓기는 사냥감이 됐대요.","눈망루 마을 북서쪽 언덕에서 찾아 처치해 달래요."},c={"스톰 섀도후프는 쉽지 않았는데 잘 해냈다고 해요.","그래도 자기를 감동시켰다고 너무 빨리 생각하지 말래요."},nx=5055,nt="Brumeran of the Chillwind"},
[5055]={a={"스톰 섀도후프는 브룸랜이 남부 설원을 조용히 돌아다닌대요.","우아해 보여도 마주친 자들은 큰 대가를 치렀대요.","서리바람 키메라들 사이에서 브룸랜을 처치하래요."},nx=5056,nt="Shy-Rotam"},
[5056]={a={"여명의 설원 북부 눈호랑이 바위에 호랑이들이 모여요.","그 우두머리 샤이로탐을 쓰러뜨리면 자랑거리래요.","눈호랑이 고기를 구해 샤이로탐을 불러내 달래요."},c={"스톰 섀도후프는 당신이 힘과 끈기를 증명했다고 해요.","내가 할 수 있는 건 다 보여 줬대요.","행운을 빈다고 해요."},nx=5057,nt="Past Endeavors"},
[5057]={a={"스톰 섀도후프는 당신의 활약을 전해 들었대요.","실력을 증명하려는 의지가 대단하대요.","썬더 블러프의 멜로르 스톤후프에게 표식을 전해 달래요."},c={"스톰 섀도후프는 경험에서 배우는 거라고 말해요.","표식을 보니 당신이 더 강하고 현명해졌대요.","이걸 받고 당신을 늘 존경하겠다고 해요."}},
[5060]={a={"잠긴 사물함 앞면에 긁힌 자국이 많대요.","누군가 안을 열려고 여러 번 실패한 흔적이래요.","열려면 열쇠를 찾아야 한대요."},c={"열쇠는 농부 달슨의 유해에서 나온 것이래요.","열쇠가 딱 맞아서 사물함 문이 열렸대요.","안에는 아직 멀쩡한 값진 물건이 여럿 있대요."}},
[5062]={a={"모테가 파이어메인은 아리카라가 아주 위험하대요.","아리카라는 신성한 생명의 불을 밝혀야 나타나요.","썬더 블러프의 마가타 그림토템에게 도움을 청하래요."},c={"불꽃 용설란은 버섯구름 봉우리에만 나는 귀한 약초래요.","이 약초로 잠든 신성한 생명의 불을 밝힌대요."},nx=5088,nt="Arikara"},
[5064]={a={"롱혼은 그림토템부족이 뭔가 꾸미는 것 같다고 해요.","소속을 모르는 첩자들이 그들을 찾아갔대요.","먹구름 봉우리 궤짝 속 비밀 쪽지를 찾아 달래요."},c={"롱혼은 정말 큰일이라며 깜짝 놀라요.","약속한 대로 보상을 건네요."}},
[5065]={a={"발굴조사단장 아이언부트는 트롤이 진실을 숨겼다고 해요.","모쉬아루 서판은 두 개가 아니라 여섯 개래요.","나머지 서판을 찾아 가져다 달래요."},c={"아이언부트는 서판을 찾아 줘서 기뻐해요.","이 글을 해독하겠다고 해요.","그런데 당신에게 또 할 일이 있다고 해요."},nx=4788,nt="The Final Tablets"},
[5082]={a={"도노바 스노우덴은 얼음불꽃 온천을 조사하러 왔어요.","눈사태일족 펄볼그들이 온천을 막아 어려워요.","조사를 계속하게 도와 달라고 부탁해요."},c={"도노바가 도와줘서 고맙다고 해요.","이제 다시 연구를 할 수 있게 됐대요.","눈사태일족 야영지에서 흥미로운 걸 찾았냐고 물어요."}},
[5083]={a={"눈사태일족 펄볼그에게서 찾은 물병이 거의 비었어요.","남은 녹색 액체 몇 방울이 빛나는 것 같아요.","도노바 스노우덴에게 가져가 보래요."},c={"도노바는 이게 눈사태일족에게서 나온 거냐고 물어요."},nx=5084,nt="Falling to Corruption"},
[5084]={a={"도노바 스노우덴은 녹색 액체가 악령의 숲 녹괴물과 닮았대요.","눈사태일족 정찰꾼들도 나무구렁 요새로 갔대요.","악령의 숲 마른가지일족 야영지에서 단서를 찾아 달래요."},c={"가마솥 안에서 썩는 냄새가 나는 물질이 끓어요."},nx=5085,nt="Mystery Goo"},
[5085]={a={"마른가지 가마솥 속 녹색 액체는 병 속 것과 비슷해요.","눈사태일족이 쓴다면 그들도 타락할지 모른대요.","액체를 담아 도노바 스노우덴에게 알려 달래요."},nx=5086,nt="Toxic Horrors"},
[5086]={a={"도노바는 가져온 액체에 독 성분이 있는 것 같대요.","비교하려면 강철나무 숲의 맹독 정령에게서 견본이 필요해요.","위험하지만 맹독 정령의 수액을 구해 와 달래요."},c={"도노바는 가마솥에서 찾은 물질과 비교해 봐야 한대요.","그러면 더 많은 걸 알게 될 거래요."},nx=5087,nt="Winterfall Runners"},
[5087]={a={"도노바는 온천수를 섞으면 독 성분이 사라진대요.","눈사태일족 정찰꾼들이 마을과 악령의 숲을 오가요.","정찰꾼들을 처치하고 물건을 빼앗아 달래요."},c={"도노바는 상자 속 물건을 살펴봐요.","이걸 먹으면 펄볼그가 더 사나워지는지 궁금해해요.","펄볼그들이 훨씬 커진 것 같다고 해요."},nx=5121,nt="High Chief Winterfall"},
[5088]={a={"마가타 그림토템이 곱게 빻은 불꽃 가루를 건네요.","버섯구름 봉우리의 신성한 생명의 불에 가루를 던지래요.","아리카라를 처치하고 증거를 모테가 파이어메인에게 가져가래요."},c={"모테가 파이어메인은 이상하다며 고개를 저어요.","그래도 공을 인정하며 보상을 하나 고르래요."}},
[5093]={a={"징집관 고를라취가 건강한 사람은 모두 싸우라고 해요.","동부 왕국 폐허에서 새 위협이 온다는 소문이 있대요.","티리스팔 숲 동쪽 보루의 델링턴을 찾아가 보래요."},c={"델링턴은 역병지대에 온 걸 환영한대요.","아제로스에서 가장 위험한 변경 중 하나래요.","몸을 던질 용사라면 할 일이 많대요."},nx=5096,nt="Scarlet Diversions"},
[5094]={a={"선구자 발타자드가 호드에 힘을 보태라고 해요.","건강한 사람은 모두 스컬지와 싸우라는 징집령이 떨어졌대요.","티리스팔 숲 동쪽 보루의 델링턴을 찾아가래요."},c={"델링턴은 역병지대에 온 걸 환영한대요.","아제로스에서 가장 위험한 변경 중 하나래요.","몸을 던질 용사라면 할 일이 많대요."},nx=5096,nt="Scarlet Diversions"},
[5095]={a={"포고꾼 윈드스트라이더가 호드에 힘을 보태라고 해요.","언더시티 동쪽 역병지대에 새 위협이 떠오른대요.","티리스팔 숲 동쪽 보루의 델링턴을 찾아가래요."},c={"델링턴은 역병지대에 온 걸 환영한대요.","아제로스에서 가장 위험한 변경 중 하나래요.","몸을 던질 용사라면 할 일이 많대요."},nx=5096,nt="Scarlet Diversions"},
[5096]={a={"델링턴은 하스글렌의 붉은십자군을 먼저 막으려 해요.","붉은십자군이 펠스톤 농장과 달슨의 눈물 사이에 진을 쳤어요.","지휘 막사를 부수고 스컬지 깃발을 꽂아 달래요."},c={"델링턴은 붉은십자군을 공격한 걸 잘했다고 칭찬해요.","이제 안돌할에 들어갈 중요한 임무를 부탁하고 싶대요.","정찰병을 보내 야영지를 지켜본대요."},nx=5098,nt="All Along the Watchtowers"},
[5098]={a={"델링턴은 스컬지가 안돌할 감시탑으로 우리를 살핀다고 해요.","신호 횃불로 다음 목표를 표시할 수 있대요.","감시탑 모두에 횃불을 설치해 달래요."},c={"델링턴의 사제들이 신호가 아주 강하다고 보고했대요.","당신이 또 임무를 완벽히 해냈다고 칭찬해요.","이제 스컬지에게 싸움을 걸 때가 왔대요."},nx=838,nt="Scholomance"},
[5103]={a={"인간 해골 주변에는 까맣게 탄 뼈만 남았대요.","그는 쫓던 판금 건틀릿 바로 옆에서 죽은 것 같대요.","이 건틀릿을 어떻게 써야 할지 알아봐 달래요."},nx=5124,nt="Fiery Plate Gauntlets"},
[5121]={a={"도노바는 눈사태일족이 이상한 물질을 먹는 걸 걱정해요.","사납지 않던 눈사태일족이 사나워진 건 족장 탓인 것 같대요.","눈사태일족 마을의 대족장 눈사태를 쓰러뜨려 달래요."}},
[5123]={a={"대족장에게서 찾은 일지의 글씨를 읽을 수 없어요.","글씨가 너무 허술해서 아무도 못 읽을 것 같대요.","도노바 스노우덴에게 가져가 뜻을 알아봐 달래요."},c={"도노바가 이게 무슨 뜻일지 궁금해해요.","그런데 아무것도 알아볼 수 없대요."},nx=5128,nt="Words of the High Chief"},
[5124]={a={"말리퍼스 다크해머가 불타지 않은 건틀릿을 보고 놀랐어요.","그 건틀릿을 주면 나만의 세트 만드는 법을 가르쳐 준대요.","필요한 재료를 모아 말리퍼스에게 가져다 달래요."}},
[5127]={a={"로락스는 보통 사람과는 거래하지 않는대요.","그런데도 악의 기운이 깃든 창을 건네요.","고랄루크 앤빌크랙을 처치하고 창을 꽂아 달래요."},c={"약속을 지켰다고 인정해요.","고랄루크의 영혼은 로락스가 가져갔대요.","보상은 로락스가 알아서 준대요."}},
[5128]={a={"도노바 스노우덴은 눈사태일족이 더는 위협이 아니래요.","그런데 화주를 왜 만들어 마셨는지 궁금하대요.","에메랄드 의회의 켈레크 스카이키퍼를 찾아가 보래요."},c={"켈레크는 일지를 살펴보고 번역해 볼 수 있대요.","눈사태일족에 대해서는 알려진 게 거의 없대요."}},
[5142]={a={"말레네 레드패스는 다로우샤이어 전투에서 가족을 많이 잃었대요.","조카 파멜라를 숨겨 두었는데 소식을 모른대요.","다로우샤이어에 가서 파멜라를 찾아 달래요."},c={"파멜라 레드패스가 나타나 인사를 건네요.","그러고는 당신의 이름을 물어봐요."},nx=5149,nt="Pamela's Doll"},
[5145]={a={"토르카프 드래곤아이는 용비늘 가죽세공을 가르쳐 준대요.","단, 원소와 부족 가죽세공은 배울 수 없는 조건이 있대요.","전갈 갑옷으로 실력을 먼저 보여 달래요."},c={"토르카프는 어려운 결정을 내린 당신을 칭찬해요.","용비늘 가죽세공은 보람 있고 돈도 된대요.","배울 준비가 되면 말을 걸면 된대요."}},
[5146]={a={"부룸 윈터후프는 원소 가죽세공을 안다고 해요.","자연의 원소와 어울리는지 증명해야 한대요.","불, 물, 흙, 바람의 가장 순수한 정수를 가져다 달래요."},c={"부룸 윈터후프는 원소들이 당신을 받아들였대요.","이제 가장 좋은 가죽 갑옷을 만들 수 있을 거래요."}},
[5147]={a={"아르낙 그림토템은 살인과 납치 죄로 현상수배됐어요.","마지막으로 먹구름 봉우리에서 목격됐대요.","그를 처치하고 증거를 절벽파수꾼 롱혼에게 가져가래요."},c={"롱혼은 드디어 정의가 실현됐다며 기뻐해요.","아르낙의 악행 소식에 화가 치밀었대요."}},
[5148]={a={"세지브는 당신이 야생 가죽 방어구를 완벽히 익혔다고 해요.","그 기술을 완성시켜 주겠대요.","가장 나은 야생 가죽 방어구를 가져오라고 해요."},c={"세지브는 당신의 최고 작품을 받았다고 해요.","이제 자연이 당신의 뜻에 따를 거래요.","당신의 작품이 자연의 힘이 될 거래요."}},
[5149]={a={"파멜라 레드패스는 말레네 고모 말대로 여기서 아빠를 기다려요.","가끔 나쁜 사람들이 와서 귓속말을 걸어와요.","마을에 두고 온 인형을 찾아 달래요."},c={"파멜라는 인형을 찾아 줘서 기뻐해요.","고맙다고 인사해요."}},
[5151]={a={"위즐로 베어링샤이너는 켄타우로스의 습격에서 혼자 살아남았어요.","힘센 퓨마가 아끼는 장치를 목에 걸고 있대요.","퓨마를 처치하고 초전도 장치를 가져다 달래요."},c={"위즐로는 초전도 장치를 찾아서 정말 기뻐해요.","이게 뭘 하는지 알아낼 때까지 바쁘겠대요."}},
[5152]={a={"파멜라 레드패스는 너무 외롭대요.","아빠는 아직 안 오고, 말레네 고모는 알지도 모른대요.","안돌할 폐허 남쪽의 말레네 고모에게 물어봐 달래요."},c={"말레네는 파멜라 소식에 놀라 살아 있는지 물어요.","조셉 오빠 이야기는 파멜라에게 차마 못 하겠대요."},nx=5153,nt="A Strange Historian"},
[5153]={a={"말레네 레드패스의 오빠 조셉은 스컬지에게 망가졌대요.","그래도 운명을 바꿀 방법이 있을지 모른대요.","무덤 비석 아래의 반지를 크로미에게 전해 달래요."},c={"크로미는 반지를 보고 큰 비극이 있던 남자의 것이라 해요.","과거에 그를 도울 수 있을지도 모른대요."},nx=5154,nt="The Annals of Darrowshire"},
[5154]={a={"크로미는 조셉 레드패스를 구하려면 과거를 알아야 한대요.","다로우샤이어 연대기가 안돌할 마을회관에 있대요.","그 책을 찾아 조셉의 운명을 함께 알아보자고 해요."},c={"크로미는 책에 조셉이 스컬지 편에 섰다고 나와 있대요.","운명을 바꿔 볼 수 있다면 해 봐야 한대요."}},
[5155]={a={"그레타 모스후프는 당신이 누구 편인지 알아야겠대요.","어둠의 의회가 여기저기 악을 퍼뜨린다고 해요.","어둠의 의회를 무찌르고 돌아오면 믿겠대요."},c={"그레타는 적들의 세력이 약해지고 있다고 해요.","나중에 자세한 이야기를 나누자고 해요."},nx=5157,nt="Collection of the Corrupt Water"},
[5156]={a={"타론 레드페더는 지옥불정령들이 떨어졌던 땅을 살펴보려 해요.","그 땅에 혼돈의 존재와 악취 나는 물이 남았는지 궁금하대요.","불벼락 골짜기에 가서 직접 확인해 달래요."},c={"타론은 당신이 살아 돌아와 다행이래요.","깨끗한 물을 찾으려던 계획은 실패했대요."}},
[5157]={a={"그레타 모스후프는 어둠의 요새에 대해 알고 싶어해요.","요새 화로를 끄면 적의 우두머리를 알 수 있대요.","자에데나르 중심부의 달샘 물을 떠 와 달래요."},c={"그레타는 이 물이면 충분하다고 해요.","이제 물을 정화하기만 하면 된대요."},nx=5158,nt="Seeking Spiritual Aid"},
[5158]={a={"그레타 모스후프가 부패한 달샘 물을 건네요.","톱니항 남쪽에 사는 주술사 이슬렌이 물의 정령들과 친하대요.","이슬렌을 설득해 정령들의 도움을 받아 달래요."},c={"이슬렌은 물의 정령들에게 이 일을 전해 보겠대요.","정령들이 정당한 일인지 보고 정하겠대요."},nx=5159,nt="Cleansed Water Returns to Felwood"},
[5159]={a={"이슬렌 워터시어가 정화된 물을 내주어요.","고마움은 정령들에게 전하라고 해요.","그레타에게 안부를 전하고 물을 가져다 달래요."},c={"그레타는 이 정도면 충분한 물이라고 해요.","이슬렌과 정령들이 도와줘서 다행이래요.","정령들이 축복해 줘서 희망이 생겼대요."},nx=5165,nt="Dousing the Flames of Protection"},
[5160]={a={"용 아우비는 저주받은 곳에서 본 것이 있대요.","헬레가 그 기억을 점쳐 볼 수 있대요.","여명의 설원의 헬레에게 비늘을 전해 달래요."},c={"헬레는 용족이 인간사에 끼지 말아야 한다고 해요.","하지만 같은 용이 그 명령을 무시해 어쩔 수 없대요."},nx=5161,nt="Wrath of the Blue Flight"},
[5161]={a={"헬레는 데스윙의 졸개들이 나쁜 짓을 꾸민다고 해요.","네파리안은 검은바위 산의 보호를 받아 막기 힘들대요.","힘을 빌려줄 수 있지만 위험해서 직접 고르래요."},nx=5162,nt="Wrath of the Blue Flight"},
[5162]={a={"헬레는 마법으로 당신을 다음 목적지로 보낸대요.","제지바는 고대 신들만큼 지혜로운 사람이래요.","서부 역병지대 안돌할에서 그를 찾아가 보래요."},nx=5164,nt="Catalogue of the Wayward"},
[5163]={a={"우미 럼플스니커는 친구들을 놀라게 할 계획이에요.","친구들에게 편지로 놀라게 해 준다고 알렸대요.","기계설인을 데리고 친구들을 찾아가 달래요."},nx=8798,nt="A Yeti of Your Own"},
[5164]={a={"제지바는 헬레가 훌륭한 정의의 도구를 골랐대요.","임무를 견디고 살아남으면 영웅이 될 거래요.","무법의 시대 일람을 읽어 보라고 해요."},c={"책은 뒤죽박죽인 글과 기호로 가득해요."}},
[5165]={a={"그레타 모스후프는 이제 자에데나르로 다시 가야 한대요.","화로의 불이 꺼지면 어둠의 요새 방어막이 사라진대요.","요새의 화로 불을 꺼 달라고 부탁해요."},c={"그레타는 마지막 화로의 불이 꺼지자 당신이 보였대요.","어둠의 의회 마법사들이 다시 걸기 전에 알아냈대요.","지금은 쉬고, 알아낸 것은 잠시 뒤에 말해 준대요."},nx=5242,nt="A Final Blow"},
[5166]={a={"오색용군단의 공격을 막을 흉갑을 만들어야 한대요.","늙은 용의 껍질은 이제 존재하지 않는대요.","재료를 모아 조각사 제지바에게 가져다 달래요."},c={"제지바는 여정 자체가 목적이었다고 해요.","시련을 견뎌 당신이 더 강해졌대요.","이 흉갑은 당신의 타고난 능력을 비춘 것일 뿐이래요."}},
[5167]={a={"오색 파멸자의 다리갑옷을 만들려면 재료가 많대요.","성숙한 오색 비룡의 껍질로 기초를 잡는대요.","재료를 모아 제지바에게 가져다 달래요."}},
[5168]={a={"카를린 레드패스는 다로우샤이어 연대기를 읽었대요.","책에는 성기사 다빌 라이트파이어 이야기가 있대요.","다빌의 성서와 레드패스의 방패를 찾아 달래요."}},
[5181]={a={"카를린 레드패스는 연대기에서 악당들 이야기를 읽었대요.","호르구스의 해골은 호수에, 마르두크의 검은 골짜기에 있대요.","그 물건들을 찾아 희망의 빛 예배당으로 가져다 달래요."},c={"카를린은 유물을 찾아 줘서 잘했다고 해요.","이 유물에는 그도 다 알지 못하는 힘이 있대요.","다로우샤이어의 마지막 밤에 대한 기억이 떠올랐대요."}},
[5202]={a={"작은 붉은 열쇠는 뼈로 만들어진 것 같아요.","왜 어둠의 의회가 이런 열쇠를 가졌는지 궁금해요.","자에데나르 어딘가에서 이 열쇠의 쓰임을 찾아 달래요."},c={"아르코나린이 열쇠를 찾아 줘서 기뻐해요.","열쇠를 주면 이제 탈출할 수 있대요."},nx=5203,nt="Rescue From Jaedenar"},
[5203]={a={"사로잡힌 아르코나린이 어둠의 요새에서 도움을 청해요.","먼저 트레이의 검, 라이트포지를 찾아야 한대요.","탈출한 뒤 제시 문보우에게 소식을 전해 달래요."},c={"제시 문보우는 아르코나린을 탈출시킨 게 당신이냐고 물어요.","아르코나린은 라이트포지를 들고 다르나서스로 떠났대요.","트레이의 끔찍한 운명에 아르코나린이 속으로 많이 아파할 거래요."},nx=5204,nt="Retribution of the Light"},
[5204]={a={"제시 문보우는 아르코나린이 괜찮은 척한다고 해요.","트레이의 죽음이 그녀를 오래 괴롭힐 거래요.","어둠의 요새에서 트레이를 고문한 자를 찾아 달래요."},c={"트레이 라이트포지의 유해를 조심스럽게 거뒀어요.","그의 영혼은 고통에서 벗어났을 거래요."},nx=5385,nt="The Remains of Trey Lightforge"},
[5206]={a={"크로미는 가져온 유물이 강한 마법에 반응한대요.","스컬지 용사의 해골도 더 필요하대요.","수정을 대 보고 소리가 나는 해골을 가져다 달래요."},c={"카를린은 해골을 찾아 줘서 크게 기뻐해요.","유물의 힘을 느끼며 다로우샤이어와 이어져 있다고 해요."},nx=5941,nt="Return to Chromie"},
[5210]={a={"크로미의 마법으로 연대기 뒷장이 더 생겼대요.","그 뒷장에 조셉의 배신에서 살아남은 카를린 이야기가 있대요.","책을 가져가 카를린과 얘기해 보래요."},c={"카를린은 이 책이 자기 고향의 연대기라며 놀라요.","뒷장에 자기와 조셉 이야기가 있어 진실을 알아야겠대요."},nx=5181,nt="Villains of Darrowshire"},
[5211]={a={"다로우샤이어의 병사들이 스컬지의 하수인이 되었대요.","그들 중 많은 이가 원래 다로우샤이어의 착한 주민이었대요.","그 불쌍한 영혼들의 고통을 끝내 달래요."},c={"카를린은 동료들의 영혼을 풀어 줘서 고맙대요.","일부 병사들이 더는 스컬지에 묶여 있지 않아 마음이 덜 아프대요."}},
[5212]={a={"베티나 비글징크는 역병을 오래 연구해 왔대요.","최근 역병이 점점 강해지고 있다고 해요.","스트라솔름에서 역병에 걸린 살덩어리 견본을 가져다 달래요."},c={"베티나는 역병 성분의 화학 구조가 바뀐 걸 발견했대요.","더 많은 자료가 필요하다고 해요."},nx=5213,nt="The Active Agent"},
[5213]={a={"베티나 비글징크는 스트라솔름 지구라트를 조사하고 싶대요.","스컬지가 지구라트에서 큰 힘을 얻는대요.","지구라트를 살펴보고 스컬지 자료를 가져다 달래요."},c={"베티나는 놀랍다며 분석에 몇 달이 걸린다고 해요.","여명의 문장이나 여명의 룬 중 하나를 고를 수 있대요.","잃어버리면 베티나에게 다시 말하면 된대요."}},
[5214]={a={"스트라솔름이 약탈당했는데 프라스는 가게를 두고 떠나지 못했대요.","스모키 라루는 그날 프라스를 두고 몸을 피했대요.","혹시 남은 담배가 있는지 찾아 달래요."},c={"스모키는 그리웠던 담배를 다시 보게 돼 감격했대요."}},
[5228]={a={"고위집행관 델링턴은 옛 로데론 땅의 가마솥을 무력화하려 해요.","가마솥이 독을 뿜어 스컬지를 위해 역병을 퍼뜨린대요.","부관 어둠의여사제 반디스에게 자세히 들어 보래요."},c={"반디스가 가마솥을 방해할 계획을 맡아 조율한대요.","역병의 성분을 바꿔 스컬지에게 해롭게 만들 거래요.","서부 역병지대의 가마솥들을 차례로 열어야 한대요."},nx=5229,nt="Target: Felstone Field"},
[5229]={a={"펠스톤 농장의 가마솥이 접근하기 가장 쉽대요.","그곳 스컬지 부대를 얕보면 안 된대요.","가마솥 안의 독 견본을 병에 담아 달래요."},c={"가마솥군주 창자아귀의 열쇠가 자물쇠에 딱 맞았대요.","열쇠는 사라졌지만 패널은 열렸대요.","병을 대고 독 견본을 뜨면 된대요."},nx=5230,nt="Return to the Bulwark"},
[5230]={a={"가마솥의 독성 혼합물을 병에 채워 견본을 얻었대요.","이제 보루의 반디스에게 돌아가야 한대요.","반디스에게 견본을 가져가 임무를 마치래요."},c={"반디스는 견본이 연구하기 충분하다며 칭찬해요.","연금술사 디더스에게 찾아가 넣는 방법을 물어보래요.","대응 물질은 가마솥 안에 직접 넣어야 한대요."},nx=5231,nt="Target: Dalson's Tears"},
[5231]={a={"달슨의 눈물이라 불리는 옛 농장에 가마솥이 있대요.","이번에도 가마솥군주의 열쇠로 안에 들어가야 한대요.","가마솥마다 독이 달라서 병에 견본을 따 오래요."},c={"가마솥군주의 해골 열쇠가 자물쇠에 쏙 들어갔대요.","이제 가마솥에 언제든 접근할 수 있게 됐대요.","안에서는 진한 독액이 관을 따라 흐른대요."},nx=5232,nt="Return to the Bulwark"},
[5232]={a={"가마솥의 고름 같은 액체를 병에 조심스럽게 채웠대요.","이제 달슨의 눈물 혼합물을 들고 보루로 가야 해요.","반디스에게 견본을 가져가 임무를 마치래요."},c={"반디스는 견본이 충분하다며 칭찬해요.","이제 대응 물질 목록을 만들어 가마솥에 넣어야 한대요.","연금술사 디더스가 방법을 알려 줄 거래요."},nx=5233,nt="Target: Writhing Haunt"},
[5233]={a={"이미 가마솥 문들을 열었대요.","남은 가마솥은 고통의 흉가에 있대요.","가마솥군주의 열쇠로 열고 견본을 병에 담아 달래요."},c={"가마솥군주의 열쇠가 문을 열고 곧 사라졌대요.","가마솥 밑에서 썩은 냄새 나는 물질이 소용돌이쳐요.","병을 대고 견본을 떠서 반디스에게 가져가면 된대요."},nx=5234,nt="Return to the Bulwark"},
[5234]={a={"스컬지 가마솥에서 독극물을 병에 가득 담았어요.","깨지기 쉬운 유리병 안에서 독이 꿈틀거린대요.","보루의 어둠의여사제 반디스에게 가져다 달래요."},nx=5235,nt="Target: Gahrron's Withering"},
[5235]={a={"마지막 가마솥은 서부 역병지대 가론의 흉가에 있어요.","스컬지 졸개 중에서도 망령과 유령이 특히 강하대요.","가마솥군주를 물리치고 빈 병을 가득 채워 오래요."},c={"가마솥군주 성난망령의 열쇠가 자물쇠에 닿자 사라졌어요.","가마솥 아래 판이 열리며 독이 드러나요.","작은 꼭지에 병을 대고 샘플을 담을 수 있어요."},nx=5236,nt="Return to the Bulwark"},
[5236]={a={"가마솥의 제어판 꼭지를 조심스럽게 잠가요.","빈 병에 썩은 고름 같은 독이 한 방울씩 떨어져요.","보루의 어둠의여사제 반디스에게 가져다 달래요."}},
[5241]={a={"파멜라 레드패스는 밤에 카를린 삼촌이 우는 소리를 들어요.","동쪽 멀리서 우는 것 같고, 자기 때문일까 걱정해요.","삼촌을 찾아 괜찮다고 전하고 기다린다고 해 달래요."},c={"카를린 레드패스는 파멜라 소식에 슬퍼하며 자기가 대신 죽고 싶대요.","복수를 향한 마음은 여전히 뜨겁대요."},nx=5211,nt="Defenders of Darrowshire"},
[5242]={a={"그레타 모스후프가 악령의 숲의 위협을 걱정해요.","어둠의 요새로 가는 길은 아래로 뻗은 길 하나뿐이래요.","어둠의 군주 펠단과 부하들을 처치하고 돌아와 달래요."},c={"그레타 모스후프가 큰 날이라며 기뻐해요.","어둠의 회의는 예전 세력을 되찾기 힘들 거래요."}},
[5243]={a={"존경받는 리어니드 바돌로매는 언데드 몸을 병으로 여겨요.","은빛 여명회에 도움이 된다며 명예에는 관심이 없대요.","스트라솔름 보급품 상자에서 남은 성수를 찾아 달래요."}},
[5251]={a={"즈바른호프 공작은 붉은십자군의 광신을 못마땅하게 여겨요.","스트라솔름의 기록관 갈포드가 십자군 문서를 맡고 있대요.","갈포드를 처치하고 문서를 모두 불태워 달래요."},c={"즈바른호프 공작이 훌륭하다며 칭찬해요.","수년 치 정보가 사라져 붉은십자군이 큰 타격을 받을 거래요."},nx=5262,nt="The Truth Comes Crashing Down"},
[5262]={a={"붉은십자군 사령관이 악마였다는 걸 알게 됐어요.","그 악마는 언더시티 바리마트라스의 형제래요.","증거로 발나자르의 혼을 공작에게 가져가래요."},c={"즈바른호프 공작이 이 일이 십자군에게 어떤 의미일지 고민해요.","십자군이 악마에게 조종당했을지도 모른대요."},nx=5263,nt="Above and Beyond"},
[5263]={a={"즈바른호프 공작이 당신의 파괴력과 순종을 칭찬해요.","켈투자드의 졸개가 스트라솔름을 다스리고 있대요.","남작 리븐데어를 처치하고 그 혼을 가져오래요."},nx=5264,nt="Lord Maxwell Tyrosus"},
[5264]={a={"즈바른호프 공작이 당신에게 큰 영광을 주려 해요.","맥스웰 티로서스 경이 여명회를 위한 공을 치하하고 싶대요.","몇 년 만에 외부인을 만나시는 분이니 가서 대화해 달래요."},nx=5265,nt="The Argent Hold"},
[5265]={a={"여명회의 궤는 몇 년간 잠겨 있었어요.","지금까지 아무도 그 안에 들어가지 못했대요.","이제 당신이 여명회의 궤를 열고 보상을 받으래요."}},
[5281]={a={"관리인 알렌이 스트라솔름에서 죽은 이들을 걱정해요.","스컬지가 되기 싫어 불길에 뛰어든 이들이 원혼이 됐대요.","그들을 돕는 에간이라는 친구를 찾아 달래요."},nx=5282,nt="The Restless Souls"},
[5282]={a={"에간은 스컬지에 대한 증오로 살아갈 힘을 얻는대요.","붉은십자군이 언데드를 무참히 쓸어버리는 게 싫대요.","에간의 제령포로 원혼들을 자유롭게 해 달래요."}},
[5301]={a={"오코토스 아이언레이저는 망치와 모루에서 큰 보람을 얻는대요.","방어구 제작자가 되려면 먼저 해야 할 일이 있대요.","화려한 미스릴 방어구를 만들어 가져다 달래요."},c={"이게 방어구 제작자가 되기 전 마지막 단계래요.","그만두려면 지금이 마지막 기회라고 해요.","이제 평생의 영광을 준비하라고 해요."}},
[5302]={a={"보르고쉬 코어벤더는 언젠가 전설의 망치를 만들고 싶어 해요.","당신에게 무기 제작자가 될 재능이 있다고 봐요.","간단한 무기들을 만들어 그에게 가져가래요."},c={"이제 무기 제작자의 새 길을 시작할 마지막 단계래요.","그만두려면 지금이 마지막 기회라고 해요."}},
[5305]={a={"진홍십자군 대장장이가 비법을 목숨 걸고 지키고 있대요.","호리호리한 릴리스가 그를 물리치고 작업복을 가져오래요.","그 대가로 마법 전투망치를 만드는 법을 알려 준대요."}},
[5306]={a={"킬램 얼굴의 흉터는 어둠사냥꾼 보쉬가진이 낸 거래요.","장난삼아 친 거라는데 이제 복수할 때래요.","검은바위 첨탑의 보쉬가진을 처치하고 뱀돌을 가져오래요."}},
[5307]={a={"세릴 스컬지베인은 부패의 검 설계도를 도둑맞았대요.","도둑은 남작 리븐데어의 정예 해골 부대, 검은호위대래요.","스트라솔름에 있는 검은호위대 검제작자를 처치하고 휘장을 가져오래요."},c={"세릴 스컬지베인이 검이야말로 최고의 선택이라고 말해요."}},
[5341]={a={"알렉시 바로브는 바로브 가의 마지막 상속자 중 한 명이에요.","형 웰던이 땅문서를 찾아 유산을 차지하려 한대요.","형보다 먼저 스칼로맨스에서 땅문서를 찾아 달래요."},c={"알렉시 바로브는 잘했다며 이제 자기 유산을 지키겠대요."},nx=5342,nt="The Last Barov"},
[5342]={a={"알렉시 바로브는 형 웰던이 살아 있어 상속이 걱정돼요.","웰던은 동쪽 서리바람 야영지에서 얼라이언스의 보호를 받아요.","웰던을 처치하고 증거를 가져오래요."},c={"알렉시가 이제 바로브 가의 힘과 재산을 혼자 가졌다고 좋아해요.","큰 자루를 던지며 거스름돈은 가지라고 해요."}},
[5361]={a={"나타카 롱혼은 잊혀진 땅의 침묵의 초소에 있대요.","소식을 못 전한 사이 켄타우로스가 수상해졌대요.","이 보고서를 나타카에게 전해 달래요."}},
[5381]={a={"불타는칼날단이 악마의 상자를 가지고 있대요.","상자 속 이룩소스의 손으로 만노로크 소굴에 악마 문을 열어요.","악마의 곡괭이로 상자를 열어 타이가 와이즈메인에게 가져가래요."},c={"타이가 와이즈메인은 악마의 상자를 보고 반가워해요.","상자를 열어 이룩소스의 손을 보여 준대요."},nx=5581,nt="Portals of the Legion"},
[5382]={a={"에바 사크호프는 수많은 사람을 죽인 학자 테올렌 크라스티노브를 원망해요.","에바 부부는 죽어서 유해로 남았대요.","크라스티노브를 처치하고 두 사람의 유해를 잿더미로 만들어 달래요."},c={"에바가 영혼이 치유되는 것을 느낀대요.","남편과 자신을 위해 큰일을 했지만 할 일이 더 남았대요."},nx=5515,nt="Krastinov's Bag of Horrors"},
[5384]={a={"에바 사크호프가 순결한 피가 든 병을 보여 줘요.","이 피로 사자 키르토노스를 불러 처치해야 한대요.","피를 화로에 올려 키르토노스와 싸워 달래요."},c={"키르토노스가 죽어 스칼로맨스의 끔찍한 이야기가 한 장 끝났대요.","용감한 행동이 다른 이들에게도 알려졌대요.","카엘 다로우의 다른 영혼들과 대화할 수 있는 조각을 줘요."},nx=5461,nt="The Human, Ras Frostwhisper"},
[5385]={a={"성기사 트레이 라이트포지의 유해를 조심스럽게 메고 가요.","친구들에게 넘기면 제대로 장례를 치러 줄 거래요.","악령의 숲의 제시 문보우에게 가져다 달래요."},c={"제시 문보우가 해냈다며 기뻐해요.","아르코나린도 친구를 괴롭힌 괴물을 물리쳐 기뻐할 거래요.","더 해 줄 수 없어 아쉬워하며 선물을 줘요."}},
[5386]={a={"나타카 롱혼은 침묵의 초소에서 생선 요리가 그리대요.","켄타우로스 때문에 그늘수렵 마을에 갈 틈이 없대요.","그늘수렵 마을의 지나르질렌에게 붉은복어를 얻어 달래요."},c={"나타카는 붉은복어를 보고 군침을 흘려요.","고맙다며 물건 하나를 대가로 고르래요."}},
[5441]={a={"작업반장 타즈릴은 일꾼들의 게으름에 골머리를 앓아요.","그래서 감시할 적임자로 보고 몽둥이를 건네요.","자는 일꾼을 깨운 뒤 몽둥이를 돌려 달래요."},c={"타즈릴이 흡족해하며 고맙다고 해요.","일꾼들이 다음엔 게으름 피우기 전에 한 번 더 생각할 거래요."},nx=6394,nt="Thazz'ril's Pick"},
[5461]={a={"집정관 마르듀크는 언데드가 전생의 흔적을 없앤다고 해요.","라스 프로스트위스퍼를 사람으로 되돌릴 유물이 필요하대요.","폐허가 된 스트롬가드에서 그의 추억의 유품을 찾아 달래요."},c={"집정관 마르듀크는 그런 물건이 있을 줄 몰랐대요.","이제 지옥 같은 곳까지 가야 할 일을 부탁하려 한대요."},nx=5462,nt="The Dying, Ras Frostwhisper"},
[5462]={a={"유품은 더럽혀진 땅에서 맞춰야 한대요.","프로스트위스퍼가 리치가 된 곳은 스트라솔름이라고 하대요.","희망의 빛 예배당의 존경받는 리어니드 바돌로매를 찾아가 달래요."},c={"존경받는 리어니드 바돌로매가 유품을 보고 잊고 싶던 기억이 떠올랐대요."},nx=5463,nt="Menethil's Gift"},
[5463]={a={"존경받는 리어니드 바돌로매가 이 일을 직접 봤대요.","라스 프로스트위스퍼는 리치 왕에게 영혼을 바치고 리치가 됐대요.","스트라솔름에서 메네실의 선물을 찾아 달래요."},c={"추억의 유품이 더럽혀진 땅 위에 놓여요."},nx=5464,nt="Menethil's Gift"},
[5464]={a={"망자의 영혼이 이 물건에 붙어 유품으로 바뀌어요.","그 유품을 집어 가방에 넣어요.","동부 역병지대의 존경받는 리어니드 바돌로매에게 가져가래요."},c={"영혼이 유품에 붙었듯이 라스 프로스트위스퍼의 몸에도 붙을 거래요."},nx=5465,nt="Soulbound Keepsake"},
[5466]={a={"마지막 임무가 남았다고 집정관 마르듀크가 말해요.","리치 라스 프로스트위스퍼는 스칼로맨스에 있대요.","유품을 써서 사람으로 되돌린 뒤 처치하래요."},c={"수많은 영혼이 한목소리로 외쳐요.","스컬지와 그 주인들에게 치명타를 입혔대요."}},
[5481]={a={"고르도는 주인님이 잡초를 원한다고 해요.","손이 커서 풀을 잘 뽑지 못한대요.","어둠풀을 뽑아 브릴 공동묘지의 초보연금술사 홀랜드에게 가져가래요."},c={"홀랜드는 어둠풀은 필요 없다며 놀라요.","고르도에겐 설명도 귀찮으니 죽음풀을 모아 달래요."},nx=5482,nt="Doom Weed"},
[5482]={a={"홀랜드는 밖에 있는 녀석이 엉뚱한 풀을 모은다며 답답해해요.","그래서 필요한 죽음풀을 모아 오면 보상을 한대요.","브릴 무덤 북쪽 큰 무덤가에서 죽음풀을 찾아 달래요."},c={"홀랜드는 죽음풀을 받고 아주 기뻐해요.","레이디를 위해 큰 도움을 줬다며 약속한 보상을 줘요."},nx=99142,nt="Tomb Weed"},
[5501]={a={"비블리 푸츠버클은 코도 뼈로 큰돈을 벌 생각이에요.","뼈로 가구나 악기, 심지어 폭약도 만든대요.","코도 무덤의 뼈를 가져오면 보답한대요."},c={"비블리는 뼈를 받고 신이 나서 좋아해요.","언젠가 세계 최고 부자가 될 거라고 해요."}},
[5504]={a={"은빛병참장교 하사나는 당신의 여명회 공로를 높이 평가해요.","여명의 장막을 살 수 있게 허락받았대요.","명예 휘장을 가져오면 장막을 살 수 있대요."},c={"하사나가 당신의 공물을 잘 받았다며 기뻐해요.","지위를 유지하면 어느 병참장교에게서나 장막을 살 수 있대요."}},
[5513]={a={"병참장교 미란다 브리치락이 당신의 여명회 활약을 칭찬해요.","여명의 장막을 살 수 있게 상부에서 허락했대요.","명예 휘장을 가져오면 이 장막을 살 수 있대요."},c={"미란다 브리치락이 당신의 공물을 잘 받았다며 기뻐해요.","지위를 유지하면 어느 병참장교에게서나 장막을 살 수 있대요."}},
[5514]={a={"연금술사 디더스는 필요한 거푸집을 만들 사람을 찾고 있어요.","가젯잔의 크린클 굿스틸만 만들 수 있고 값도 비싸대요.","크린클 굿스틸에게 마력 깃든 뼈조각을 가져가래요."},c={"크린클 굿스틸은 디더스 말대로 물건을 가져와 좋아해요.","약속대로 뼈조각을 거푸집에 넣어 준대요.","디더스가 이미 마력을 불어넣었는지 묻고 있어요."},nx=5802,nt="Fire Plume Forged"},
[5515]={a={"에바 사크호프는 키르토노스가 아직 살아 있어 걱정해요.","키르토노스에게 갈 피는 잔다이스 바로브가 지킨대요.","스칼로맨스에서 잔다이스 바로브를 찾아 처치하고 단서를 가져오래요."},nx=5384,nt="Kirtonos the Herald"},
[5517]={a={"병참장교 미란다 브리치락이 당신의 여명회 공로에 감사해요.","여명의 오색 장막은 가장 위대한 영웅에게만 준대요.","명예 휘장을 많이 가져오면 가장 좋은 장막을 준대요."},c={"병참장교 미란다 브리치락이 여명의 오색 장막이 이제 당신 것이라고 해요.","최고 지위를 유지하면 장막을 더 살 수 있대요.","어느 병참장교에게서나 바로 살 수 있대요."}},
[5518]={a={"노트 팀블잭은 족쇄에 묶여 있지만 위장복을 만들 줄 알아요.","대장 크롬크러쉬를 피하려면 위장복이 필요하대요.","룬무늬 두루마리 등 재료를 가져다 달래요."},c={"노트 팀블잭은 이거면 됐다며 활짝 웃어요.","위장복은 10분쯤 쓸 수 있대요.","입으면 적이 당신을 아군으로 본대요."}},
[5522]={a={"팅키 스팀보일은 주인 벡투스의 이름으로 온 전갈을 받았대요.","전갈은 존경받는 리어니드 바돌로매가 보낸 거래요.","얼어붙은 알을 존경받는 리어니드 바돌로매에게 가져다 달래요."},c={"당신이 악한 세력을 위해 일한 줄 몰랐을 거래요.","자신은 그 주인을 섬기지 않는다고 밝혀요.","팅키를 속여 알을 자신에게 보내게 했대요."},nx=5531,nt="Betina Bigglezink"},
[5524]={a={"은빛병참장교 하사나가 당신의 여명회 공로에 감사해요.","여명의 오색 장막은 가장 위대한 영웅에게만 준대요.","명예 휘장을 많이 가져오면 가장 좋은 장막을 준대요."},c={"하사나가 여명의 오색 장막이 이제 당신 것이라고 해요.","최고 지위를 유지하면 장막을 더 살 수 있대요.","어느 병참장교에게서나 바로 살 수 있대요."}},
[5525]={c={"노트 팀블잭이 풀어 줘서 고맙다고 해요.","오우거의 간식이 될 운명은 아니었대요."}},
[5526]={a={"라빈 사투르나는 혈투의 전장에 있는 타락을 걱정해요.","칼날바람 알진이 동쪽에서 타락을 퍼뜨리고 있대요.","알진을 쓰러뜨리고 악령덩굴 조각을 가져오래요."},c={"라빈 사투르나가 큰 빚을 졌다고 해요.","전쟁은 끝나지 않았지만 큰 싸움에서 이겼대요.","감사의 표시로 선물을 주고 영웅으로 맞이한대요."}},
[5527]={a={"라빈 사투르나는 아주 타락한 물질을 담을 그릇을 찾고 있어요.","그런 것을 담을 그릇은 정화의 성물함 하나뿐이래요.","실리더스의 마파람 마을 폐허를 뒤져 찾아 달래요."},nx=5526,nt="Shards of the Felvine"},
[5529]={a={"베티나 비글징크는 스컬지가 용군단을 만들고 있다고 말해요.","다로미어 호수 한가운데 스칼로맨스에서 새끼용을 기른대요.","새끼용이 자라기 전에 되도록 많이 처치해 달래요."},c={"베티나 비글징크가 잘했다며 칭찬해요.","스컬지가 다시 용을 기르려면 오래 걸리길 바란대요."}},
[5531]={a={"존경받는 리어니드 바돌로매는 그 알이 스컬지 실험용이었대요.","이제 스컬지 연구를 끝낼 때래요.","얼어붙은 알을 베티나 비글징크에게 가져가 달래요."},c={"베티나 비글징크가 알을 담아 온 용기를 달라고 해요.","스칼로맨스의 언데드 학자들을 없애는 장치를 만들었대요.","장치 이름은 여명의 계략이고, 될지는 모르겠대요."},nx=4771,nt="Dawn's Gambit"},
[5534]={a={"킴야엘은 폭탄 값이 얼마나 비싼지 따지며 투덜대요.","먼저 쓸만한 일꾼인지 증명하면 보상을 준대요.","엘다라스 폐허에서 블러드 엘프들이 찾던 룬을 구해 오래요."},c={"킴야엘이 룬을 받고 잘했다며 좋아해요.","이 룬이 무엇에 쓰이는지, 학자 림토리가 왜 원했는지 알아내겠대요.","블러드 엘프에게 한 방 먹였다며 신나 해요."}},
[5535]={a={"로아투는 타락한 엘프 귀족들의 원혼을 풀어 주려 해요.","옛날 엘프 귀족들의 사악한 연구가 큰 해를 끼쳤대요.","섀도송 제단의 원혼들을 풀어 달라고 부탁해요."},c={"로아투는 당신을 칭찬하며 원혼들이 평안해졌대요.","양쪽 진영 모두 당신을 높이 평가할 거래요."}},
[5536]={a={"사티로스들이 세나리우스가 한때 활보하던 성지에 들끓고 있대요.","로아투는 대지모신께 맹세하고 나이트 엘프를 도우려 해요.","북동쪽 할다르 부족과 싸워 실력을 보여 달래요."},c={"로아투는 당신이 강할 뿐 아니라 꾀도 많다고 칭찬해요.","그런 적을 물리친 건 대지모신의 가르침에 충실하다는 증거래요.","작은 돈을 주며 고마움을 전해요."}},
[5542]={a={"티리온 폴드링은 이곳에 버릇없는 것들이 많다고 해요.","역병사냥개와 그 새끼들이 특히 말썽을 부린대요.","그러니 역병사냥개부터 군기를 잡아 달래요."},c={"티리온이 잘했다며 같이 쉬자고 해요.","함께 밥 먹고 옛날 이야기를 나누자고 해요."},nx=5742,nt="Redemption"},
[5543]={a={"이 숲에는 온갖 사악한 것들이 득실거린대요.","하늘에서 공격해 오는 역병박쥐들이 문제래요.","그러니 하늘의 역병박쥐를 처치해 달라고 부탁해요."},c={"당신은 올바른 본보기라며 티리온이 칭찬해요.","오랜만에 영웅의 피가 끓는 것 같다고 기뻐해요."},nx=5742,nt="Redemption"},
[5544]={a={"티리온 폴드링은 식량이 점점 떨어지고 있대요.","이 근처에서 역병에 안 당한 짐승은 청소부구더기뿐이래요.","그 구더기 고기를 구해 겨울을 나게 해 달래요."},c={"빛의 축복이 당신과 함께하기를 빌어 줘요."},nx=5742,nt="Redemption"},
[5561]={a={"스미드 스크래블스크류는 잊혀진 땅에서 장사를 해요.","늙은 코도를 길들이는 유인기로 짐마차 주인과 협력해요.","코도 유인기를 가져가 코도를 길들여 데려와 달래요."},c={"스미드가 코도를 다 세고는 아주 기뻐해요.","이제 부자가 될 거라며 비블리의 얼굴을 보고 싶대요."}},
[5581]={a={"타이가 와이즈메인은 악마의 위협이 커지는 게 걱정이에요.","문을 닫아야 악마가 이 세상으로 못 온대요.","만노로크 소굴의 차원문을 닫아 달래요."},c={"타이가 와이즈메인은 당신을 크게 칭찬해요.","그 덕분에 세상이 훨씬 안전해졌대요."}},
[5601]={a={"제시카 레드패스는 대전쟁 때 로데론에서 도망쳤어요.","가족들이 다로우샤이어 전투에서 죽었을까 걱정돼요.","다로우샤이어에 가서 동생 파멜라 레드패스를 찾아 달래요."},c={"파멜라는 언니 제시카가 어디 있냐고 물어요.","언니가 떠날 때 많이 울었다고 기억해요.","언니가 돌아오면 아빠도 돌아올 거라며 기다려요."},nx=5149,nt="Pamela's Doll"},
[5642]={a={"마일스 웰시는 오그리마에 중요한 일이 생겼다고 해요.","트롤 사제를 찾는 전령들이 평소보다 급해 보였대요.","썬더 블러프에 오래 머물지 말고 우르쿄를 만나래요."}},
[5643]={a={"애살리스테가 부족의 통과 의례 때가 왔다고 해요.","통과 의례에서 사제는 생존에 필요한 능력을 배운대요.","오그리마 영혼의 계곡에서 우르쿄와 대화해 달래요."}},
[5644]={a={"마일스 웰시는 이제 때가 됐다고 해요.","애살리스테만 가르칠 수 있는 것이 있대요.","언더시티에서 애살리스테를 찾아가래요."}},
[5646]={a={"우르쿄가 애살리스테에게 훈련을 받으러 가래요.","그녀가 종족의 방식을 더 가르쳐 줄 거래요.","언더시티로 서둘러 가서 그녀를 만나래요."},c={"제때 돌아왔다며 반가워해요.","할 얘기가 많다고 해요.","능력이 강해져서 준비됐는지 확인하겠대요."}},
[5648]={a={"타이진은 칼바위 언덕 남쪽의 다친 그런트를 걱정해요.","그런트 코르자가 싸우다 다쳐 상태가 좋지 않대요.","그녀를 치유하고 조상의 축복도 내려 달래요."}},
[5649]={a={"켄자이 말로는 우리 종족은 Horde에 합류했지만 옛 방식은 남았대요.","오크들이 다 반기진 않아도 몰래는 지킬 수 있대요.","칼바위 언덕의 타이진에게 가서 역사를 배우래요."},c={"타이진은 우리 부족이 예전과 다르다고 해요.","이제는 힘을 얻은 뒤에 적을 물리친대요.","부족이 기대하니 잘 배우래요."},nx=5648,nt="Garments of Spirituality"},
[5650]={a={"어둠의사제 베릴이 치유 마법 시험을 준비했대요.","묘지 북쪽에 다친 죽음의경비병 켈이 있대요.","치료 마법으로 켈을 치료하고 체력도 강화해 달래요."}},
[5651]={a={"어둠의사제 듀스텐이 경험으로 배운 것들을 들려줘요.","많은 것이 빛과 어둠 둘 모두에 기대고 있대요.","배울 준비가 되면 브릴의 어둠의사제 베릴을 찾아가래요."},c={"베릴은 드디어 왔다며 반겨요.","믿음만으로는 시험을 통과할 수 없대요.","서두르는 마음과 야망도 도움이 된대요."},nx=5650,nt="Garments of Darkness"},
[5652]={a={"우르쿄가 할 말이 있어 집으로 돌아오라고 해요.","가장 위대한 사제가 지금 기다리고 있대요.","정령의 계곡으로 가서 그를 만나래요."},c={"이 가르침을 잘 새겨 들으라고 해요.","Hex of Weakness는 전투에 큰 도움이 된대요.","나중에 시험을 줄 테니 부족에 가치를 증명하래요."}},
[5654]={a={"타이진은 이제 우르쿄를 만날 때라고 해요.","우르쿄는 오그리마의 정령의 계곡에 있대요.","옛 방식을 배워 부족의 진짜 사제가 되래요."},c={"이 가르침을 잘 새겨 들으라고 해요.","Hex of Weakness는 전투에 큰 도움이 된대요.","나중에 시험을 줄 테니 부족에 가치를 증명하래요."}},
[5655]={a={"바르준은 집에서 너무 멀리 가지 말라고 해요.","가장 위대한 사제 우르쿄가 할 말이 있대요.","오그리마의 정령의 계곡에서 그를 만나래요."},c={"이 가르침을 잘 새겨 들으라고 해요.","Hex of Weakness는 전투에 큰 도움이 된대요.","나중에 시험을 줄 테니 부족에 가치를 증명하래요."}},
[5656]={a={"마일스 웰시는 여러 문화의 사제들이 세상을 도는 게 반갑대요.","오그리마의 우르쿄가 찾고 있대요.","정령의 계곡에서 우르쿄와 만나래요."},c={"이 가르침을 잘 새겨 들으라고 해요.","Hex of Weakness는 전투에 큰 도움이 된대요.","나중에 시험을 줄 테니 부족에 가치를 증명하래요."}},
[5657]={a={"애살리스테가 영적 지도자 우르쿄가 찾는다고 해요.","우르쿄가 지금 걷는 길에 대해 얘기하고 싶대요.","오그리마 영혼의 계곡에서 우르쿄와 대화해 달래요."}},
[5658]={a={"애살리스테가 멀리 떠나 있는 사람을 찾고 있대요.","그녀에게서만 배울 것들이 있대요.","오래 머물지 말고 언더시티로 서둘러 가래요."},c={"애살리스테는 돌아와 줘서 기쁘다고 해요.","잊지 말아야 할 가르침을 주겠대요.","준비됐냐고 물어요."}},
[5660]={a={"타이진 말로는 지하 도시에서 누군가 필요하대요.","주인인 애살리스테가 기다린대요.","언더시티로 빨리 가서 그녀를 만나래요."},c={"또 다른 사람이 도착했다며 반가워해요.","배울 것이 많으니 가치를 증명하라고 해요.","잘 증명하면 큰 보상을 준대요."}},
[5661]={a={"바르준은 블러드후프 마을에서 사제를 찾고 있대요.","사제장이 모두 찾아오라고 했다는 소문이래요.","언더시티에서 애살리스테를 만나래요."},c={"또 다른 사람이 도착했다며 반가워해요.","배울 것이 많으니 가치를 증명하라고 해요.","잘 증명하면 큰 보상을 준대요."}},
[5662]={a={"우르쿄는 보통 자기 부족 사람만 가르친대요.","다른 신앙과 다른 능력은 애살리스테에게 배운대요.","언더시티로 가서 그녀를 찾아가래요."},c={"또 다른 사람이 도착했다며 반가워해요.","배울 것이 많으니 가치를 증명하라고 해요.","잘 증명하면 큰 보상을 준대요."}},
[5663]={a={"마일스 웰시 말로는 애살리스테가 모든 사제에게 소식을 보냈대요.","어린 사제들을 언더시티로 보내 훈련시키래요.","그러니 언더시티에서 애살리스테를 찾아가래요."},c={"또 다른 사람이 도착했다며 반가워해요.","배울 것이 많으니 가치를 증명하라고 해요.","잘 증명하면 큰 보상을 준대요."}},
[5679]={a={"애살리스테가 더 배울 것이 있으니 언더시티로 오래요.","그녀는 종족의 풍습을 가르칠 준비가 됐대요.","오래 기다리지 말고 빨리 가 달래요."}},
[5680]={a={"우르쿄 말로는 사제마다 치르는 통과 의례가 있대요.","그 때가 왔으니 오그리마 정령의 계곡으로 가래요.","앞날에 중요할 가르침을 받으래요."}},
[5721]={a={"크로미는 다로우샤이어 전투에 참전해 달라고 해요.","마을 광장에 유물 더미를 놓으면 영혼들이 깨어난대요.","조셉 레드패스를 구해 집의 파멜라에게 가 달래요."},c={"파멜라는 전투가 끝났다고 기뻐해요.","아빠가 유령들을 쫓아내고 곧 집에 온대요.","당신을 위해 차를 준비했다고 해요."},nx=5942,nt="Hidden Treasures"},
[5722]={a={"마가타님은 하인 마우르 그림토템이 뭔가 발견했다고 들었대요.","그 물건은 보여 주기도 전에 돌아오지 못했대요.","성난불길 협곡에서 마우르의 시체를 찾아 달래요."},c={"시체는 몽둥이나 주먹에 심하게 맞은 흔적이 있어요.","트로그는 재물에 관심이 없는 듯해서 장비가 대부분 남아 있어요."},nx=5724,nt="Returning the Lost Satchel"},
[5723]={a={"오그리마 지하의 트로그가 지상으로 올라오기 시작했대요.","트로그가 마가타님의 사신을 죽여 위협으로 여기게 됐대요.","성난불길 협곡의 트로그를 모두 없애 달래요."},c={"라하우로는 마가타님의 부탁을 진지하게 받아 줘서 기쁘대요.","트로그가 지상으로 올라오기 더 어려워질 거래요.","언젠가 트로그가 어디서 왔는지 알아보자고 해요."}},
[5724]={a={"마우르 그림토템의 시체 밑에서 가방을 찾았어요.","트로그의 공격 속에서도 가방을 꽉 쥐고 지키려 한 것 같아요.","썬더 블러프의 라하우로에게 그림토템 가방을 가져다 달래요."},c={"마가타님이 씨족원을 찾으면 이걸 주라고 했대요.","고마움의 뜻으로 받아 달래요."}},
[5725]={a={"바리마트라스가 어둠의 여왕을 위해 일을 맡겼어요.","이글거리는 칼날단이 강력한 마법책들을 얻었대요.","그 마법책들을 어둠의 여왕을 위해 가져다 달래요."},c={"바리마트라스가 어둠의 여왕을 잘 섬긴 것을 칭찬해요.","다음에 다시 찾아오면 다른 일을 맡길지 모른대요."}},
[5726]={a={"스랄은 우리 안의 배신자를 참을 수 없대요.","부관들이 못 가는 곳도 용감하다면 갈 수 있대요.","해골 바위굴에서 불타는칼날단 부관의 휘장을 찾아 달래요."},c={"스랄은 가장 큰 걱정을 덜어 줄 사람일지 모른대요.","젊은 나이에 용감하게 나선 모습이 예전의 자신 같대요.","앞으로 올 일에 비하면 좋은 출발이래요."},nx=5727,nt="Hidden Enemies"},
[5727]={a={"스랄은 네루 파이어블레이드가 불타는칼날단 지휘관이라고 봐요.","어둠의 틈에 있는 네루에게 휘장을 가져가 떠보래요.","확인이 끝나면 다시 스랄에게 돌아오래요."},c={"스랄은 아주 잘했다며 크게 칭찬해요.","네루가 한 말을 한마디도 빠짐없이 말해 달래요.","이 일이 큰 계획의 첫걸음이라고 해요."},nx=5728,nt="Hidden Enemies"},
[5728]={a={"스랄은 이글거리는 칼날단 우두머리들을 먼저 제거하려 해요.","사티로스 바잘란과 기원사 제로쉬를 없애야 한대요.","네루가 눈치채지 못하게 성난불길 협곡에서 처치하래요."},c={"칼날단 우두머리들이 쓰러져 지하가 혼란에 빠졌대요.","네루가 몹시 화가 났다는 소식도 들었대요.","작은 승리라도 스랄은 싫지 않대요."},nx=5729,nt="Hidden Enemies"},
[5729]={a={"네루 파이어블레이드가 몹시 흥분해 있대요.","그에게 칼날단 정보를 얻고 신뢰를 얻으라고 해요.","어둠의 틈에서 네루와 다시 대화해 달래요."},c={"네루가 버럭했다가 미안하다고 사과해요.","바잘란과 기원사 제로쉬가 스랄의 사람들에게 당했대요."},nx=5730,nt="Hidden Enemies"},
[5730]={a={"이글거리는 칼날단에 쏟은 노력이 허사가 될지도 몰라요.","그래도 다른 곳의 계획은 계속되니 부관으로 임명했대요.","오그리마의 스랄에게 돌아가 배운 것을 말하래요."},c={"스랄은 잿빛 골짜기에 칼날단이 있다는 말은 못 들었대요.","첩자를 보내 알아보겠다며 잘했다고 칭찬해요.","지금은 쉬면서 다른 일을 하라고 해요."}},
[5741]={a={"아조레 알다모트는 불타는칼날단을 걱정하고 있어요.","소문에 불타는칼날단이 빛의 홀을 얻었다고 해요.","빛의 홀을 직접 되찾아 달래요."},c={"드디어 빛의 홀을 찾았다며 기뻐해요.","큰 위협이 사라졌다고 칭찬해요."},nx=6027,nt="Book of the Ancients"},
[5761]={a={"네루 파이어블레이드는 도시를 해치는 자들을 없애라는 임무를 받았대요.","성난불길 협곡의 이글거리는 칼날단도 위험하대요.","우두머리 욕망의 타라가만을 처치하고 심장을 가져오래요."},c={"네루는 해냈다며 기뻐하고 스랄도 흐뭇해할 거래요.","심장은 잘 처리하고 스랄에게 성공을 알리겠대요."}},
[5762]={a={"크레이블 콜비어드는 오랜 단골 헤멧에게 온 소포를 맡았어요.","헤멧은 사냥하러 멀리 떠나 있대요.","가시덩굴 골짜기의 헤멧에게 상자를 전해 달래요."},c={"상자에는 특수 규격 탄약이 들어 있대요.","보수를 주며 크레이블의 안부도 물어봐요."}},
[5763]={a={"룬 와일드메인은 옛날 잊혀진 땅에서 헤멧과 함께 사냥했어요.","헤멧이 다시 돌아오면 함께 사냥하고 싶어 해요.","그래서 룬의 코도 뿔을 헤멧에게 전해 달래요."},c={"뿔을 보고 룬이 초대한 거냐며 반가워해요.","지금은 정글 한가운데라 바로 갈 수 없대요."}},
[5781]={a={"티리온 폴드링은 아들 탤런이 잃어버린 기억을 되찾게 하려 해요.","탤런은 아끼던 망치 장난감을 지하 납골당에 묻었대요.","동부 역병지대 남쪽 지하 납골당에서 망치를 찾아 달래요."},nx=5845,nt="Of Lost Honor"},
[5802]={a={"크린클 굿스틸은 해골 열쇠를 만들 방법을 알려 줘요.","해골 열쇠를 만들려면 뜨거운 용암이 필요하대요.","운고로 분화구 불기둥 마루에서 거푸집을 담가 달래요."},c={"연금술사 디더스는 열쇠가 아직 덜 완성됐다고 해요.","이제 안돌할의 소환사 아라즈와 맞서야 한대요."},nx=5804,nt="Araj's Scarab"},
[5804]={a={"연금술사 디더스는 소환사 아라즈가 안돌할을 지배한대요.","아라즈는 예전 스칼로맨스의 지도자였대요.","아라즈를 처치하고 그의 스카라베를 가져다 달래요."},c={"디더스는 스카라베를 찾았다며 기뻐해요.","특별한 용액으로 열쇠에 스카라베를 붙이겠대요.","그러면 스칼로맨스의 잠긴 문을 열 힘이 생긴대요."},nx=5511,nt="The Key to Scholomance"},
[5821]={a={"코르크 기젤톤은 짐마차 주인이에요.","콜카르 켄타우로스의 북소리가 들리면 짐마차가 멈춰 버려요.","짐마차를 콜카르 마을 너머까지 지켜 달래요."},c={"호위에 돈이 드는 게 아깝다고 투덜대요.","키가 더 컸다면 켄타우로스에게 본때를 보였을 거래요."}},
[5845]={a={"티리온 폴드링은 아들 탤런이 겪은 일을 말해 줘요.","탤런은 노스데일 마을에서 끝까지 버텼대요.","노스데일에 가서 잃어버린 명예의 상징을 찾아 달래요."},nx=5846,nt="Of Love and Family"},
[5846]={a={"티리온 폴드링은 가족과 함께 간 소풍 이야기를 해요.","소풍 때 화가 렌프레이가 가족 초상화를 그려 줬대요.","폐허가 된 카엘 다로우 섬에서 그림을 찾아 달래요."},c={"이 섬의 영혼들은 죽기 전 행복했던 기억을 되풀이한대요.","렌프레이 자신은 모든 걸 기억하는 몇 안 되는 영혼이래요."},nx=5848,nt="Of Love and Family"},
[5848]={a={"화가 렌프레이는 그림을 기사단 병영 작업장에 걸어 뒀대요.","티리온이 그림을 훔치려 해서 그림을 숨겼대요.","스트라솔름의 붉은십자군 성채에서 그림을 찾아 달래요."},nx=5861,nt="Find Myranda"},
[5861]={a={"티리온 폴드링은 탤런에게 물건을 전해 달라고 해요.","탤런과 붉은십자군은 당신을 보면 공격할 거래요.","남쪽 우서 경의 무덤에 가서 노파 미란다를 찾아 달래요."},c={"미란다는 티리온의 가장 믿음직한 조언자였대요.","그녀는 반대 의견을 말했다가 추방됐대요.","폴드링 가의 잘못을 바로잡을 준비가 됐냐고 물어요."},nx=5862,nt="Scarlet Subterfuge"},
[5862]={a={"노파 미란다는 환영을 만드는 환영술사래요.","하지만 환영은 멀리 가면 사라지고 짧게만 유지된대요.","환영을 받아 하스글렌에 선물을 전해 달래요."},c={"탤런은 상자를 열어 보고 믿을 수 없어 해요.","당신이 보여 준 것들을 보니 믿기 어렵다고 해요.","오랜 분노가 이 마을에 터질 것 같대요."},nx=5944,nt="In Dreams"},
[5863]={a={"가젯잔의 앤디 린은 떠돌이 오우거들 때문에 걱정이래요.","오우거들이 사막에 모래망치 주둔지를 세웠대요.","주둔지를 없애고 우두머리를 처치해 달래요."},c={"앤디 린이 당신이 해내서 정말 기쁘대요.","도와줘서 고맙다고 전해요."}},
[5881]={a={"마그그랜 어스바인더는 호드 병력을 챙기고 있어요.","그리쉬 롱러너는 오랫동안 휴가를 기다려 왔대요.","그에게 이 통지서를 전해 달래요."},c={"오랜 경비에서 벗어나게 돼 기뻐하고 있어요.","가족과 시간을 보내게 됐다며 신이 났대요."}},
[5887]={a={"메이베스 리버브리즈는 오염된 식물을 고칠 연고를 만든대요.","그 연고에는 오염된 짐승에게서 나오는 영혼 조각이 필요해요.","오염된 짐승을 처치하고 영혼 조각을 가져다 달래요."},c={"메이베스가 연고를 주며 오염된 식물을 찾으라고 해요.","악령의 숲 어디든 연고로 식물을 정화하라고 해요."}},
[5888]={a={"메이베스 리버브리즈는 오염된 식물을 고칠 연고를 만든대요.","광맥을 오염시키는 물질이 악령의 숲 광산에 있대요.","그 오염된 물질을 모아서 가져다 달래요."},c={"메이베스가 연고를 주며 광산에서 그 물질을 챙기라고 해요.","많이 모을수록 연고를 더 만들 수 있대요."}},
[5889]={a={"메이베스 리버브리즈는 약초를 연고로 바꾸는 일을 해요.","악령의 숲에서 약초를 캘 때 오염된 것이 보인대요.","그 오염된 것을 모아 가져다 달래요."},c={"메이베스는 잘했다며 이것들이 악령의 숲을 되찾는 데 도움 된대요.","연고를 주며 숲의 오염을 정화하러 가라고 해요."}},
[5890]={a={"메이베스 리버브리즈는 연고에 넣을 반죽을 만든대요.","짐승 가죽을 벗길 때 오염된 조각이 나온대요.","오염된 조각을 가져다 달래요."},c={"메이베스는 딱 필요한 것이라며 연고를 건네요.","이 연고로 악령의 숲을 오염에서 되찾으래요."}},
[5891]={a={"메이베스 리버브리즈는 마법 부여 재료로 연고를 만든대요.","마법 아이템을 분해하면 나오는 정수가 필요하대요.","정수 하나만 가져오면 연고를 준다고 해요."},c={"메이베스는 정수 하나면 충분했다며 연고를 줘요.","연고가 더 필요하면 자신을 찾아오라고 해요."}},
[5901]={a={"미키 레빈은 붉은십자군의 벌목지를 빼앗고 싶대요.","벌목지를 잃으면 붉은십자군이 큰 손해를 보게 된대요.","역병의 숲 흰개미집에서 흰개미를 병에 담아 달래요."},c={"미키 레빈은 흰개미가 충분하다며 고마워해요.","준비가 되면 다음 단계로 가자고 해요."},nx=5902,nt="A Plague Upon Thee"},
[5902]={a={"미키 레빈은 흰개미 통을 북마루 벌목지로 옮기라고 해요.","벌목지 가운데 높은 곳에 통을 놓고 열어야 한대요.","그 뒤는 흰개미에게 맡기고 돌아와 보상을 받으래요."},c={"상자 위에 통을 올리자 흰개미들이 몹시 안절부절못해요."},nx=6390,nt="A Plague Upon Thee"},
[5922]={a={"투락 룬토템은 새로 배우는 드루이드를 반긴대요.","발톱의 길을 배웠으니 달의 숲으로 가는 주문을 가르쳐 줘요.","달의 숲 나이트헤이븐에서 덴드리트를 찾아가래요."},c={"덴드리트 스타블레이즈는 이제 시작이라고 해요.","자연을 이해하는 첫 단계는 곰의 방식이래요.","그걸 받아들여 평생 실천하라고 해요."},nx=5930,nt="Great Bear Spirit"},
[5926]={a={"여관주인 팔라가 투락 룬토템이 찾는다고 전했대요.","드루이드 수련을 직접 맡아 가르치겠대요.","썬더 블러프 장로의 봉우리로 가서 만나래요."},c={"Cenarius의 자식들 안에는 자연을 섬기라는 부름이 있대요.","첫걸음은 곰의 길을 배워 몸과 마음을 단련하는 것이래요.","그러니 준비하라고 해요."},nx=5922,nt="Moonglade"},
[5927]={a={"여관주인 그리쉬카가 투락 룬토템이 찾는다고 전했대요.","드루이드 수련을 직접 맡아 가르치겠대요.","썬더 블러프 장로의 봉우리로 가서 만나래요."},c={"Cenarius의 자식들 안에는 자연을 섬기라는 부름이 있대요.","첫걸음은 곰의 길을 배워 몸과 마음을 단련하는 것이래요.","그러니 준비하라고 해요."},nx=5922,nt="Moonglade"},
[5928]={a={"제니아 룬토템이 투락 룬토템이 찾는다고 전해요.","드루이드 수련을 새로 시작할 때라며 직접 지도한대요.","썬더 블러프 장로의 봉우리로 가서 그를 만나래요."},c={"Cenarius의 자식들 안에는 자연을 섬기라는 부름이 있대요.","첫걸음은 곰의 길을 배워 몸과 마음을 단련하는 것이래요.","그러니 준비하라고 해요."},nx=5922,nt="Moonglade"},
[5930]={a={"덴드리트 스타블레이즈 말로는 곰에 관한 가르침을 얻어야 한대요.","달의 숲 북서쪽에 거대한 곰의 혼이 있대요.","가르침을 얻은 뒤 나이트헤이븐으로 돌아오래요."},c={"덴드리트 스타블레이즈는 지혜가 느껴진다며 미소 지어요.","이제 힘을 모아 곰의 본성을 일에 적용하라고 해요."},nx=5932,nt="Back to Thunder Bluff"},
[5932]={a={"덴드리트 스타블레이즈는 이제 헤어질 때라고 해요.","자신을 보낸 투락 룬토템에게 돌아가라고 해요.","썬더 블러프 장로의 봉우리에서 그의 가르침을 들으래요."},c={"투락 룬토템은 거대한 곰의 혼을 처음 만나면 다 당황한대요.","이제 목적을 확인할 첫 시험이 있다고 해요.","잘 들으라고 해요."},nx=6002,nt="Body and Heart"},
[5941]={a={"카를린 레드패스는 당신이 유물을 많이 모았다고 고마워해요.","그는 고향 다로우샤이어를 파멸에서 구하고 싶어 해요.","안돌할의 크로미에게 유물 자루를 가져다 달래요."},nx=5721,nt="The Battle of Darrowshire"},
[5942]={a={"파멜라 레드패스는 아빠가 보낸 열쇠를 당신에게 줘요.","열쇠는 집 뒤편의 상자를 여는 열쇠래요.","집 뒤의 조셉의 상자를 열어 달래요."},c={"열쇠가 자물쇠에 맞고 상자가 열려요."}},
[5943]={a={"리거 기젤톤은 코르크와 함께 짐마차 장사를 해요.","만노로크 소굴 앞에서 코도들이 뭔가에 놀랐대요.","짐마차가 소굴을 무사히 지나게 호위해 달래요."},c={"이렇게 큰돈을 들여 호위하는 건 남는 장사가 아니래요.","코도 값만 계속 내면 장사 방식은 상관없대요."}},
[5944]={a={"대영주 탤런 폴드링은 오랫동안 십자군의 꼭두각시였대요.","그는 아버지에 대한 기억 덕분에 살아 있었대요.","꿈에 나온 아버지에게 자신을 데려다 달래요."}},
[5961]={a={"여군주 실바나스 윈드러너는 당신에게 용기를 시험해 보라고 해요.","나타노스 블라이트콜러는 옛 용사로 마리스 농장에 살아요.","동부 역병지대에서 나타노스를 찾아가 만나 달래요."},c={"여군주가 당신을 자기 용사에게 어울린다고 여기지 않는 듯하대요.","사냥개 먹이로 왔냐며 방해라고 쏘아붙여요."}},
[6002]={a={"불모의 땅 서쪽, 멀고어 가기 전에 달빛야수 비석이 있대요.","초승달발톱은 세나리온 달가루를 쓰면 나타난대요.","그와 싸워 육체와 마음의 힘을 얻어 보래요."},c={"이제 더 큰 세상으로 한 걸음 내디뎠대요.","거대한 곰의 혼의 가르침이 느껴지고 힘도 얻었대요.","이제 발톱의 드루이드가 무엇인지 가르쳐 준대요."}},
[6004]={a={"키르스타 딥섀도는 하스글렌의 방어를 살피러 온 정찰병이래요.","그녀는 지쳐서 더 일하려면 쉬어야 한대요.","남쪽 붉은십자군 야영지부터 처치해 달래요."},c={"키르스타는 당신이 그들을 빨리 처리해 놀랐대요.","붉은십자군을 지지하는 사람은 본 적이 없대요.","충성하지 않으면 무고한 사람까지 죽이려 한대요."},nx=6023,nt="Unfinished Business"},
[6021]={a={"관리인 알렌은 역병지대의 도둑 때문에 골치가 아파요.","죽은 트롤 도둑들이 밤마다 구덩이에서 시체를 훔쳐 간대요.","서쪽 지하 납골당의 추방자 잴다르를 처치해 달래요."},c={"알렌은 잴다르를 해치운 걸 기뻐해요.","그 무리에게도 교훈을 줬기를 바란대요."}},
[6022]={a={"나타노스 블라이트콜러는 사냥개에게 먹이를 주려 해요.","그는 코린 삼거리의 스컬지에게서 살아있는 부패물을 얻으라고 해요.","막자 사발로 부패물을 갈아 가져다 달래요."},c={"나타노스는 실망했다며 당신을 사냥개 먹이로 쓰길 바랐대요.","그래도 사냥개가 먹을 것이 생겼다고 해요."}},
[6023]={a={"키르스타 딥섀도는 붉은십자군 병력을 약화시키려는 정찰병이래요.","그녀는 혼자라 도와줄 사람이 필요하대요.","사냥꾼 래들리와 기병 드루겐을 처치해 달래요."},c={"키르스타는 도와줘서 고맙다고 해요.","이 지역 공기 때문에 기운이 빠진다고 해요.","보답으로 이 돈을 받아 달라고 해요."},nx=6025,nt="Unfinished Business"},
[6024]={a={"첩보원 하메야는 줄마샤르 가는 길에 상한 고기를 먹었대요.","그 뒤로 리치의 명령이 들려 자신을 막을 수 없대요.","그러니 자신을 처치해 달라고 부탁해요."}},
[6025]={a={"키르스타 딥섀도는 당신이 이미 많이 도와줬다고 고마워해요.","하스글렌은 통로보다 훨씬 위험하대요.","높은 곳에서 붉은십자군 병력을 살펴 알려 달래요."},c={"키르스타는 해냈다며 고맙다고 해요.","작은 동전을 주며 당신은 자랑스러운 사람이라고 해요."}},
[6026]={a={"스모키 라루는 은빛 여명회의 폭파 일을 맡았대요.","그는 역병의 숲에서 부술 건물에 표시를 하러 간대요.","당신은 폭탄 재료를 모아 오라고 부탁해요."},c={"스모키는 일 값의 절반을 먼저, 나머지는 끝나면 준대요."},nx=6041,nt="When Smokey Sings, I Get Violent"},
[6027]={a={"아조레 알다모트는 나가의 비밀이 담긴 책을 찾고 있어요.","그 책은 라나즈자르 섬의 뱀 석상이 지키고 있대요.","뱀의 보석을 석상 손에 올려놓고 책을 가져다 달래요."}},
[6029]={a={"그레고르 그레이스톤은 은빛 여명회 대표로 눈망루 마을에 투자해요.","그는 눈망루 마을 보고서를 가루쉬 장교에게 전해야 해요.","보루의 가루쉬에게 보고서를 전해 달래요."},c={"가루쉬는 은빛 여명회가 당신의 노고를 인정한다고 해요.","고맙다는 뜻으로 보상을 건네요."}},
[6030]={a={"엄브런스가 쓴 긴 책을 은빛 여명회가 받았대요.","그레고르는 그 글을 도통 읽을 수가 없대요.","언어에 능한 공작 니콜라스 즈바른호프에게 전해 달래요."},c={"니콜라스 공작은 특별한 책이라며 해독해 보겠대요.","이 책이 유용할지는 두고 봐야 한대요.","은빛 여명회의 감사 선물도 건네요."}},
[6031]={a={"나무구렁의 메일로쉬는 낯선 자들을 별로 좋아하지 않아요.","그녀의 동족들이 룬무늬 옷감으로 옷을 만들고 싶대요.","룬무늬 옷감을 가져다 달라고 부탁해요."},c={"메일로쉬는 좋은 옷감이라며 기뻐해요.","고맙다며 보답을 건네요."}},
[6032]={a={"나무구렁 일족은 룬무늬 옷감보다 달빛 옷감을 신성하게 여겨요.","메일로쉬는 달빛 옷감을 가져오면 비밀 옷 기술을 가르쳐 줘요.","그러니 달빛 옷감을 조금 가져다 달래요."}},
[6041]={a={"스모키 라루는 부하들에게 스컬지 건물에 표시를 시켰대요.","그는 당신에게 특수혼합물을 줘서 표시된 건물에 붙이라고 해요.","역병의 숲에 가서 스컬지 건물을 폭파해 달래요."},c={"스모키는 당신이 그을렸다며 웃어요.","화상을 달래라고 보너스를 조금 더 챙겨 줘요."}},
[6042]={a={"나타노스는 농장 밖에 박쥐가 너무 많아 짜증이 나요.","박쥐 때문에 사냥개를 데리고 스컬지를 해치우기 어렵대요.","그러니 훈련 삼아 날아다니는 박쥐를 정리해 달래요."},c={"나타노스는 분노와 화가 이런 일을 해낸다며 감탄해요."}},
[6061]={a={"요 샤프메인은 조상의 전통을 따르라고 말해요.","짐승을 길들이면 자연과 하나가 되는 데 도움이 된대요.","조련용 막대로 다자란 초원타조를 길들여 보래요."},nx=6087,nt="Taming the Beast"},
[6062]={a={"소타르 말로는 사냥꾼은 짐승을 부리는 법을 익혀야 한대요.","첫 임무는 칼바위 언덕 근처의 멧돼지를 찾는 거래요.","막대로 길들이고 기술을 익혀 다시 오래요."},nx=6083,nt="Taming the Beast"},
[6065]={a={"캐리 썬더혼이 젊은 사냥꾼에게 말을 걸어요.","야수를 길들여 벗으로 삼을 솜씨가 있어 보인대요.","블러드후프 마을의 요 샤프메인을 만나 보래요."},c={"요 샤프메인은 준비가 된 것 같다고 말해요."},nx=6061,nt="Taming the Beast"},
[6066]={a={"시안두르가 젊은 사냥꾼에게 말을 걸어요.","야수를 길들여 벗으로 삼을 솜씨가 있어 보인대요.","블러드후프 마을의 요 샤프메인을 만나 보래요."},c={"요 샤프메인은 준비가 된 것 같다고 말해요."},nx=6061,nt="Taming the Beast"},
[6067]={a={"소타르는 야수를 길들일 실력이 있어 보인대요.","자기 야수를 얻는 길은 요 샤프메인이 열어 준대요.","블러드후프 마을로 가서 그를 만나래요."},c={"요 샤프메인은 준비가 된 것 같다고 해요."},nx=6061,nt="Taming the Beast"},
[6068]={a={"시안두르가 젊은 사냥꾼에게 인사를 건네요.","야수를 길들여 벗으로 삼을 솜씨가 좋아 보인대요.","칼바위 언덕의 소타르를 꼭 찾아가 보래요."},c={"소타르는 이제 훈련을 시작할 때라고 말해요."},nx=6062,nt="Taming the Beast"},
[6069]={a={"칼리 레믹이 젊은 사냥꾼에게 말을 걸어요.","야수를 길들여 벗으로 삼을 솜씨가 있어 보인대요.","칼바위 언덕의 소타르를 만나 보래요."},c={"소타르는 이제 훈련을 시작할 때라고 말해요."},nx=6062,nt="Taming the Beast"},
[6070]={a={"캐리 썬더혼이 젊은 사냥꾼에게 말을 걸어요.","야수를 길들여 벗으로 삼을 솜씨가 있어 보인대요.","칼바위 언덕의 소타르를 만나 보래요."},c={"소타르는 이제 훈련을 시작할 때라고 말해요."},nx=6062,nt="Taming the Beast"},
[6081]={a={"소타르는 이제 야수를 조련하는 기술이 필요하다고 해요.","오그리마의 존경받는 사냥꾼 오르막 그림샷이 가르쳐 준대요.","용사의 전당 근처에서 그를 찾아가래요."},c={"야수를 조련하고 이끄는 기술을 전수해 준대요.","야수에게 먹이를 주고, 쓰러지면 되살릴 수도 있대요."}},
[6082]={a={"소타르는 이제 마지막 짐승을 길들이라고 해요.","마지막 짐승은 빠르고 정확한 등껍질전갈이래요.","조련용 막대로 길들여 보고 돌아와 달래요."},c={"소타르는 가르칠 건 다 가르쳤다고 해요.","이제 짐승을 길들이고 부르고 해제하는 힘을 줬어요."},nx=6081,nt="Training the Beast"},
[6083]={a={"소타르가 야수를 부리면 싸움에 유리하대요.","다음 짐승은 바다에 사는 붉은톱니게예요.","센진 마을 건너편 메아리 섬 근처에서 찾아보래요."},c={"소타르가 빨리 배운다며 칭찬해요."},nx=6082,nt="Taming the Beast"},
[6087]={a={"요 샤프메인이 사냥꾼의 다음 도전을 준비했대요.","다음 상대는 빠르고 두려움 없는 긴발톱 초원늑대래요.","조련용 막대로 그 늑대를 길들여 보라고 해요."},nx=6088,nt="Taming the Beast"},
[6088]={a={"요 샤프메인이 사냥꾼에게 마지막 임무를 내렸대요.","하늘을 나는 검독수리를 길들이는 게 임무래요.","길들인 뒤 조련용 막대를 돌려주러 와 달래요."},c={"요 샤프메인이 가르칠 건 다 가르쳤대요.","이제 짐승을 길들이고 부르고 해제하는 힘을 줬어요."},nx=6089,nt="Training the Beast"},
[6089]={a={"요 샤프메인이 펫을 길들이는 힘은 이미 줬대요.","펫을 훈련하는 기술은 썬더 블러프에서 배워야 한대요.","수렵의 봉우리에서 홀트 썬더혼을 찾아가 달래요."},c={"홀트 썬더혼이 훈련 기술을 전수해 줬대요.","펫에게 먹이를 주고 쓰러지면 되살릴 수 있대요."}},
[6126]={a={"투락 룬토템이 이제 독 치료법을 배울 때래요.","독을 치료하는 힘은 쉽게 얻지 못하고 배워야 한대요.","달의 숲에서 덴드리트 스타블레이즈를 만나 달래요."},c={"덴드리트가 배우려는 의지를 반가워해요.","불모의 땅에서 동물 중독이 퍼져 도움 요청이 왔대요.","이번 일은 연습이 아니라 진짜라고 해요."},nx=6127,nt="The Principal Source"},
[6127]={a={"덴드리트 스타블레이즈는 독의 근원이 공포의 안개봉우리일 거래요.","정상 물웅덩이 물이 오염됐을 것 같대요.","가득 찬 공포의 안개봉우리 견본병을 통가 룬토템에게 가져다 달래요."},c={"통가 룬토템은 이 물이 끔찍하다고 해요.","불모의 땅 북부 가젤들이 병들었대요.","이 물로 치료법을 만들 수 있지만 물건이 더 필요하대요."},nx=6128,nt="Gathering the Cure"},
[6128]={a={"통가 룬토템이 가젤을 위한 약을 만들려고 해요.","약에는 뱀뿌리와 코도의 뿔이 필요하대요.","뱀뿌리를 찾고 코도를 잡아 뿔을 가져다 달래요."},c={"통가는 재료가 충분해서 연고를 넉넉히 만들 수 있겠대요.","이제 바로 연고 만들기에 들어간대요."},nx=6129,nt="Curing the Sick"},
[6129]={a={"통가 룬토템이 연고를 충분히 만들었대요.","북부 불모의 땅에 병든 가젤들이 많대요.","그 연고로 병든 가젤들을 치료해 달래요."},c={"병든 가젤들을 잘 돌봐 줘서 고맙다고 해요.","가젤들은 땅 전체에 번지는 오염의 피해자래요.","자연을 아끼는 친구라며 증표를 줘요."},nx=6130,nt="Power over Poison"},
[6130]={a={"덴드리트 스타블레이즈가 독 치료 수업을 잘 마쳤대요.","투락 룬토템이 중요한 주문을 가르쳐 줄 거래요.","썬더 블러프 장로의 봉우리로 돌아가 달래요."},c={"투락 룬토템은 불모의 땅 상황에 놀랐다고 해요.","독이 환경의 균형을 해쳐 더 조사해야 한대요.","잘 해내서 독을 다스리는 영구적인 힘을 줬어요."}},
[6132]={a={"멜릿자 브림버즐은 뾰족바위 골짜기에서 위험에 빠졌어요.","마라우딘일족이 거래는커녕 자기를 잡아먹으려 한대요.","그녀를 꺼내서 동생 호르니즈에게 데려다 달래요."},c={"호르니즈가 멜릿자를 구해 줘서 고맙대요.","그런데 멜릿자가 또 새 곤경에 빠졌을 거래요."}},
[6133]={a={"쿠엘리시엔 오두막의 하이 엘프가 쿠엘탈라스 기록부를 가졌대요.","나타노스는 그 기록부가 자기 것이라며 되찾고 싶어 해요.","기록부를 찾고 분쟁과 재난을 최대한 일으키라고 해요."},c={"나타노스는 기록부를 읽지 않았기를 바란대요.","그런 멍청한 짓은 하지 않았을 거라고 믿는대요."}},
[6134]={a={"호르니즈 브림버즐은 뼈의 골짜기 유령에 눈독을 들여요.","그 힘을 마그람일족에게 팔면 큰돈이 된대요.","유인기 상자를 놓고 유령을 잡아 플라스마를 가져다 달래요."},c={"드디어 찾았다며 반가워해요. 조금 끈적거리네요.","이게 뭔지 마그람일족을 설득하면 큰돈이 된대요."}},
[6135]={a={"나타노스가 이번에는 더 어려운 임무를 준대요.","마리스 농장 북쪽에 하얀 박쥐 그늘날개가 돌아다닌대요.","그놈을 없애고 하얀 털을 가져다 달라고 부탁해요."}},
[6136]={a={"노스데일 서쪽에 피고름구더기라는 괴물이 있대요.","나타노스는 그 괴물에게 연대원을 모두 잃었대요.","혼자보다 다른 사람과 함께 가서 물리치라고 해요."},c={"나타노스는 계속 그러면 더 심한 바보로 승진시키겠대요."}},
[6142]={a={"마이라힐은 평생 낚시를 해 온 낚시꾼이에요.","물고기가 좋아하는 미끼는 연갑 조갯살이래요.","북쪽 난파선 근처 조갯살을 가져다 달래요."}},
[6143]={a={"드룰제가르 스크락후크는 선원들을 잃고 괴로워해요.","나가들의 습격에 그만 혼자 살아남았대요.","뱀갈퀴일족 나가들을 대신 혼내 달래요."},c={"나가들이 쓰러져 소식은 반갑지만 마음은 비어 있대요.","앞으로도 나가를 모두 없애겠다며 보상을 줘요."}},
[6144]={a={"나타노스는 바리마트라스가 요원을 보내라고 했대요.","유능한 요원들은 3년 전에 죽고 애송이만 남았대요.","언더시티로 가서 바리마트라스에게 보고하라고 해요."},c={"바리마트라스는 십자군 사령관이 안전한 곳에 숨어 있대요.","그러는 동안 십자군은 우리 땅을 짓밟고 사람들을 죽인대요.","그러니 당신이 복수의 도구가 되라고 해요."},nx=6145,nt="The Crimson Courier"},
[6145]={a={"바리마트라스가 진홍십자군 급사를 쫓으라고 해요.","붉은십자군 지도부가 매일 티르의 손 수도원으로 명령서를 보내요.","그 명령서를 가져다 나타노스에게 주라고 해요."},c={"나타노스가 웃으며 드디어 붉은십자군 예언자를 칠 기회라고 해요."},nx=6146,nt="Nathanos' Ruse"},
[6146]={a={"나타노스가 명령서를 조금 조작해 두었대요.","티르의 손 수도원에서 썩은 사과를 먹으라고 해요.","십자군군주 발델마르에게 명령서를 직접 전하라고 해요."},c={"발델마르는 어디 있었냐며 스컬지에게 잡힌 줄 알았대요."},nx=6147,nt="Return to Nathanos"},
[6147]={a={"발델마르는 사령관이 평소답지 않은 부탁을 했대요.","곧 예언자를 호송하겠다고 나타노스에게 전하래요.","예언자가 무사히 스트라솔름까지 가도록 준비한대요."},c={"나타노스는 멍청한 자들이 속임수를 눈치채지 못했다고 해요.","차갑고 교활하게 공격할 준비를 하라고 해요."},nx=6148,nt="The Scarlet Oracle, Demetria"},
[6148]={a={"데메트리아는 십자군 사령관의 최고 조언가예요.","초자연적인 감각 때문에 예언자라고 불린대요.","지금 티르의 손 수도원을 떠났으니 쫓아가 처치하래요."},c={"이 일로 적들이 한동안 흔들릴 거라며 나타노스가 기뻐해요.","당신을 존경할 뿐 아니라 보상도 준대요."}},
[6161]={a={"랙모어의 기록에는 배가 바다 생물에게 습격당한 일이 있어요.","보물을 적에게 뺏기지 않으려고 라나즈자르 섬에 숨겼대요.","열쇠를 찾아 궤짝을 열어 달래요."},c={"궤짝이 열리며 랙모어의 보물이 나왔어요!"}},
[6162]={a={"드레카술의 남편은 일족의 명예를 위해 악령의 숲에 갔대요.","대군주 로르를 치러 간 뒤로 소식이 끊겼대요.","로르의 발톱을 가져다 달라고 부탁해요."},c={"드레카술은 약속을 지켜 명예를 가져왔다고 고마워해요.","남편은 싸우다 죽었지만 자랑스러워했을 거래요.","혼자 살게 만든 괴물이 값을 치러 안심된대요."}},
[6163]={a={"나타노스는 스컬지 군단에게 당해 스스로 스컬지가 됐대요.","자신을 쓰러뜨린 먹보 람스타인에게 복수하려 해요.","스트라솔름에서 먹보 람스타인을 처치하고 머리카락을 가져오래요."},c={"나타노스는 그 괴물이 자비를 구걸했을지 궁금해해요.","머리를 벽에 걸어 두겠다고 해요.","당신을 자기 용사 중 한 명으로 인정한대요."}},
[6164]={a={"정신나간 아우구스투스가 장사를 시작하려고 해요.","회계장부를 여관 방에 두고 와서 가게를 못 열고 있어요.","여관에서 회계장부를 찾아 가져다 달라고 부탁해요."},c={"아우구스투스는 드디어 찾았다며 기뻐해요.","장부가 가득 차 있던 걸 잊었다며 놀라워해요.","오늘은 정말 좋은 날이라며 신이 났어요."}},
[6282]={a={"마그그랜 어스바인더는 돌발톱 산맥의 하피가 걱정돼요.","혈폭풍일족 하피가 늘어 생물들을 해치고 있대요.","혈폭풍일족 하피들을 처치해 달래요."},c={"혈폭풍일족이 큰 타격을 입었대요.","하피들을 쫓아낸 이야기를 또 듣고 싶대요."},nx=6283,nt="Bloodfury Bloodline"},
[6283]={a={"마그그랜 어스바인더는 하피 수를 줄여도 부족하대요.","혈폭풍일족 갈퀴발톱이 하피 떼의 여왕 노릇을 한대요.","갈퀴발톱을 처치하고 증거를 가져와 달래요."},c={"이제 분노가 사라져 마음이 가볍대요.","선한 일에 집중하게 됐다며 보상을 줘요."}},
[6284]={a={"현상수배지에 베스셀레스가 올라 있어요.","시쉬르 협곡을 자기 둥지라고 우기며 지내요.","베스셀레스를 처치하고 송곳니를 마그그랜에게 가져가 달래요."},c={"베스셀레스는 오랫동안 이 지역의 포식자였대요.","이제 많은 사람이 두려움 없이 오갈 수 있대요."}},
[6301]={a={"탐라 윈드필드는 돌발톱 산맥을 살리려 해요.","개발 욕심과 전쟁으로 땅이 처참하게 망가졌대요.","땅을 살릴 가이아 씨앗을 구해 와 달래요."},c={"가이아 씨앗을 보고 탐라가 주문을 외기 시작해요.","땅을 살릴 수 있는 건 순수한 자뿐이냐고 물어요."},nx=6381,nt="New Life"},
[6321]={a={"고위집행관 하드렉이 공동묘지에 무기를 보내라고 했대요.","전쟁터에서 잃을 무기에 대비해 예비 무기가 더 있어야 한대요.","주문서를 들고 박쥐 조련사 카로스 라조크를 찾아가래요."},c={"카로스 라조크는 보급 주문서라며 언더시티에 가라고 해요.","공동묘지에 보급이 부족하면 안 되니 서두르래요."},nx=6323,nt="Ride to the Undercity"},
[6322]={a={"고든 웬드헴이 공동묘지 장비를 상자에 담았어요.","언더시티의 박쥐 조련사가 공동묘지행 박쥐를 준대요.","상자를 언더시티의 마이클 가레트에게 가져다 달래요."},c={"이 상자를 공동묘지로 보내야 한다고요? 쉬운 일이래요.","박쥐들이 매일 그곳으로 날아간대요."},nx=6324,nt="Return to Podrig"},
[6323]={a={"박쥐 조련사 카로스 라조크에게 언더시티행 박쥐가 있대요.","싼 값에 언더시티까지 데려다준대요.","상업 지구의 고든 웬드헴에게 주문서를 전하래요."},c={"공동묘지에서 온 주문서라니 알겠다고 해요.","어둠의 여왕을 섬기는 이를 돕는 건 영광이래요."},nx=6322,nt="Michael Garrett"},
[6324]={a={"마이클 가레트는 언더시티의 박쥐 조련사예요.","공동묘지의 카로스 라조크를 만났으니 박쥐를 탈 수 있대요.","고든의 상자를 죽음의경비병 포드리그에게 가져다 달래요."},c={"포드리그는 이 무기로 경비병들이 준비를 갖추게 됐대요.","어둠의 여왕을 위해 귀한 일을 했다고 칭찬해요."}},
[6361]={a={"자안 호크윙이 불모의 땅에서 벗긴 가죽 묶음이 있대요.","그 가죽은 썬더 블러프의 동료 아하누에게 가야 해요.","크로스로드의 와이번 조련사 데브락에게 가져가 달래요."},c={"썬더 블러프로 가려면 자기에게 오라고 해요."},nx=6362,nt="Ride to Thunder Bluff"},
[6362]={a={"와이번 조련사 데브락이 썬더 블러프행 와이번을 준비해요.","저렴한 요금으로 가장 빨리 데려다 준대요.","가죽 묶음은 헤와의 방어구점에서 아하누에게 전해 달래요."},c={"아하누는 새 가죽 묶음이라며 바로 작업하겠대요.","고맙다며 수고비와 여행비로 돈을 줘요."},nx=6363,nt="Tal the Wind Rider Master"},
[6363]={a={"아하누가 자안 호크윙에게 팔 가죽용품을 만들었어요.","가죽용품을 크로스로드로 보내야 한대요.","썬더 블러프의 와이번 조련사 탈에게 가져가 달래요."},c={"탈은 크로스로드로 가는 건 문제없다고 해요.","그곳에서 데브락을 만났다면 와이번을 태워 준대요."},nx=6364,nt="Return to Jahan"},
[6364]={a={"탈이 크로스로드행 와이번을 태워 줄 수 있대요.","요금만 내면 데브락이 있는 크로스로드로 갈 수 있대요.","아하누의 가죽용품을 자안 호크윙에게 전해 달래요."},c={"자안 호크윙은 아하누가 만든 완성품을 받고 기뻐해요.","크로스로드에는 손님이 많아 곧 잘 팔릴 거래요.","수고해 줘서 고맙다며 신세를 졌다고 해요."}},
[6365]={a={"자르그가 최상급 고기를 잘라 두었대요.","오그리마의 여관주인 그리쉬카에게 고기를 보내려 해요.","고기를 오그리마로 배달해 달래요."},c={"오그리마까지 고기를 가져가는 건 문제없대요.","작은 요금을 내면 와이번으로 데려다 준대요."},nx=6384,nt="Ride to Orgrimmar"},
[6381]={a={"탐라 윈드필드는 땅에 다시 생명을 틔우려 해요.","잿더미 계곡에는 아직 하피와 성난 불의 정령이 많대요.","가이아 씨앗을 가지고 가서 심어 달래요."},c={"땅에 큰 승리를 가져왔다며 기뻐해요.","언젠가 돌발톱 산맥에 평화가 찾아올 거래요."}},
[6382]={a={"조른 스카이시어는 당신의 사냥 실력에 감탄했대요.","잿빛 골짜기에는 야생동물이 많아 호드가 탐낸대요.","토막나무 주둔지의 세나니 썬더하트를 찾아가 보래요."},c={"잿빛 골짜기는 기회가 많은 새 땅이래요.","조람 해안에도 주둔지가 있으니 가 보래요."},nx=6383,nt="The Ashenvale Hunt"},
[6384]={a={"데브락이 요금만 받으면 오그리마까지 태워 준대요.","하늘탑 근처에 내려 줘서 힘의 골짜기 여관이 가깝대요.","자르그의 고기를 여관주인 그리쉬카에게 전해 달래요."},c={"그리쉬카는 좋은 고기라며 아주 기뻐해요.","자르그가 자기 마음을 잘 안다며 웃어요."},nx=6385,nt="Doras the Wind Rider Master"},
[6385]={a={"여관주인 그리쉬카가 자르그에게 줄 감사 편지를 썼어요.","이 편지를 오그리마의 와이번 조련사 도라스에게 가져가래요.","도라스에게 크로스로드로 가는 방법을 물어보래요."},c={"크로스로드까지 데려다 줄 수 있대요."},nx=6386,nt="Return to the Crossroads"},
[6386]={a={"도라스의 와이번은 다녀온 곳까지 데려다 줄 수 있대요.","크로스로드는 데브락을 만났으니 바로 갈 수 있대요.","그리쉬카의 편지를 크로스로드의 자르그에게 전해 달래요."}},
[6390]={a={"벌목지에서 흰개미 통을 열 쇠지렛대를 찾았어요.","통을 열면 흰개미가 덮치기 전에 빠져나가야 해요.","흰개미 통을 티리스팔 숲 보루의 미키 레빈에게 가져다 달래요."}},
[6393]={a={"츄나만은 해일의 심판장의 명을 받고 왔대요.","츄나만은 불의 정령들을 없애 신임을 얻고 싶어 해요.","잿더미 계곡의 정령을 처치하고 발화석을 가져다 달래요."},c={"해일의 심판장에 보고할 큰 승리래요.","보답으로 아끼던 물건 중에서 고르라고 해요."}},
[6394]={a={"작업반장 타즈릴이 곡괭이를 북쪽 동굴에 두고 왔대요.","그 동굴은 포악한 짐승들로 가득 찼대요.","불타는 칼날 소굴에서 타즈릴의 곡괭이를 가져다 달래요."}},
[6395]={a={"수련사제 엘레스의 친구 말라 핍스는 남편 사무엘의 손에 죽었대요.","말라는 사무엘과 함께 묻히길 바랐대요.","데스넬 북동쪽 길의 사무엘 핍스를 물리쳐 말라 곁에 묻어 달래요."},c={"엘레스는 좋은 일을 했다며 고마워해요.","두 사람이 함께 편히 쉬길 바란대요."}},
[6401]={a={"마을이 습격당한 뒤 카야가 실종된 줄 알았대요.","그런데 카야가 살아 있다는 기쁜 소식이 있대요.","해바위 야영지의 숙모 탐라 윈드필드에게 전해 달래요."},c={"탐라는 조카 카야가 살아 있다니 놀라며 기뻐해요.","소식을 전해 줘서 고맙다고 해요."}},
[6421]={a={"돌발톱 산맥에 뭔가 수상한 일이 벌어지는 것 같대요.","구릉바위 협곡 동굴에서 코볼트들이 리조나이트를 캐고 있대요.","표본을 가져오고 동굴 깊숙한 곳도 살펴 달래요."},c={"리조나이트에 흙 마법의 흔적이 있대요.","코볼트들이 깊이 파서 Earthen을 건드린 것 같대요.","표본에 마법을 걸어 코볼트에 맞서 볼 수 있대요."},nx=6481,nt="Earthen Arise"},
[6441]={a={"픽셀은 톱니항에서 사티로스 뿔을 찾고 있대요.","어둠의 터, 사티르나르, 사비안에 뿔을 가진 사티로스가 있대요.","사티로스의 뿔을 모아 픽셀에게 가져다 달래요."},c={"뿔이 아주 좋다며 기뻐해요.","도와줘서 고맙다며 수고비를 줘요."}},
[6442]={a={"조람 해안에 나가들이 다시 나타났대요.","그곳은 바다 밑에 가라앉은 옛 도시 조람이래요.","성난지느러미일족을 물리치고 머리를 가져오래요."},c={"마루카이는 이런 사람이 더 있었으면 좋겠다며 고마워해요."}},
[6461]={a={"말라카진의 트롤들은 이 땅에서 사냥하며 살아왔대요.","요즘 거미들이 밤에 사냥해 둔 음식을 노린대요.","돌발톱 산맥의 거미들을 없애 주면 보답하겠대요."},c={"젠질라는 오늘 밤 불청객이 줄 것 같아 기뻐해요.","도와줘서 고맙다며 평생 신세를 졌다고 해요."}},
[6462]={a={"미쑤와의 동족이 펄볼그들에게 몰살당했대요.","그들이 지니던 트롤 부적은 아주 값진 물건이래요.","엉겅퀴 마을 끝 동굴의 궤짝에서 부적을 찾아 달래요."},c={"부적을 찾아와 줘서 정말 고맙대요.","부적이 없는 트롤은 아무것도 아니래요."}},
[6481]={a={"모르로갈은 당신이 땅의 위협을 찾아냈다고 해요.","리조나이트 광석 안에 토석인 고게로크가 잠들어 있대요.","마력 깃든 수정으로 광석을 열고 고게로크를 처치해 달래요."},c={"고게로크를 처치한 건 영웅만 할 수 있는 일이래요.","돌발톱 산맥과 칼림도어 모두 당신에게 빚졌대요."}},
[6482]={a={"루울 스노우후프는 펄볼그들에게 잡혀 있어요.","곰으로 착각한 펄볼그들이 그를 굶기고 있대요.","탈출을 도운 뒤 누이 야마를 만나 달래요."},c={"루울을 구해 줘서 고맙다고 해요.","그를 잡은 펄볼그들이 못됐다고 화를 내요."}},
[6503]={a={"쿠레이빈은 정찰꾼들이 숲에 숨어든 걸 걱정해요.","그들이 우리 방어 정보를 캐 갈 수도 있대요.","숲에서 정찰꾼을 찾아 처치하고 돌아와 달래요."},c={"정찰꾼이 사라져 얼라이언스 정보가 줄었대요.","정보가 없으면 공격도 덜 할 거라며 칭찬해요."}},
[6504]={a={"구르다 레이지스카는 톱니항에서 벌목기를 샀대요.","바람에 설명서 책장이 흩어져 표지만 남았대요.","흩어진 설명서를 찾아 돌려 달래요."},c={"글 읽는 건 서툴지만 이제 일할 수 있대요."}},
[6521]={a={"바리마트라스는 사절 말킨이 가시덩굴 구릉 밖에 있대요.","가시멧돼지 중 일부가 무섭도록 강해졌대요.","사절 말킨을 처치해 머리카락을 가져다 달래요."},c={"사절 말킨이 죽어서 다행이래요.","레이디가 고마워하며 선물을 준대요."}},
[6522]={a={"이 두루마리에는 사절 말킨이 레이디에게 보낸 제안이 있어요.","불모의 땅을 차지할 큰 기회라고 적혀 있대요.","이 두루마리를 언더시티의 바리마트라스에게 가져다 달래요."},c={"이 문양은 가시덩굴 우리 노파의 것이래요.","말킨은 스컬지 편 사절이라 막아야 한대요."},nx=6521,nt="An Unholy Alliance"},
[6523]={a={"카야 플랫후프는 자유의 몸이 됐대요.","그들이 알아채기 전에 어서 떠나야 한대요.","아파라제 야영지까지 호위해 달래요."},c={"마카바는 카야가 살아 있다며 기뻐해요.","카야를 구해 준 덕분이라고 고마워해요."},nx=6401,nt="Kaya's Alive"},
[6541]={a={"톨크가 호드의 새 전선을 지킬 신병을 찾아요.","호드가 잿빛 골짜기 조람 해안에 전초기지를 세웠대요.","불모의 땅 북부 감시탑의 카드라크를 찾아가 보래요."},c={"잿빛 골짜기는 두 진영이 나뉜 땅이래요.","최근 조람 해안 말고 북쪽에도 기지를 세웠대요."},nx=6543,nt="The Warsong Reports"},
[6542]={a={"다른 탈론그립이 새 전선을 지킬 신병을 찾아요.","호드가 잿빛 골짜기 조람 해안에 전초기지를 세웠대요.","불모의 땅 북부 감시탑의 카드라크를 찾아가 보래요."},c={"잿빛 골짜기는 두 진영이 나뉜 땅이래요.","최근 조람 해안 말고 북쪽에도 기지를 세웠대요."},nx=6543,nt="The Warsong Reports"},
[6543]={a={"카드라크가 잿빛 골짜기에 부하들을 보냈어요.","그들의 정찰 소식을 들을 전령이 필요하대요.","보고서를 전하고 최신 소식을 받아 와 달래요."},c={"카드라크는 당신을 믿을 만하다고 칭찬해요.","이 소식이 잿빛 골짜기 작전에 아주 중요하대요.","이제 다음 작전을 세울 수 있대요."}},
[6544]={a={"토렉은 서쪽 은빛날개 전초기지를 공격하려고 해요.","지도자 두리엘 문파이어를 노리는데 방어가 철통같대요.","토렉을 도와 싸운 뒤 에르톡 레이지터스크에게 알려 달래요."},c={"토렉의 공격이 성공했대요. 잘했다고 칭찬해요.","나이트 엘프는 만만찮은 적이었대요."}},
[6548]={a={"마카바 플랫후프의 마을을 그림토템부족이 습격했어요.","겨우 아내와 함께 빠져나와 살아남았대요.","서쪽에 있는 그림토템부족을 찾아 복수해 달래요."},c={"고맙지만 그림토템부족이 한 일은 잊지 않겠대요."},nx=6629,nt="Kill Grundig Darkcloud"},
[6561]={a={"은빛경비병 타엘리드는 힘이 없어 도움을 청해요.","옛 엘룬의 신전이 타락한 기운에 무너졌대요.","황혼의 군주 켈리스를 처치해 머리카락을 가져다 달래요."},c={"켈리스를 없앤 덕분에 많은 목숨을 살렸대요.","사람을 바쳐 힘을 얻는 짓은 정말 끔찍하대요."}},
[6562]={a={"츄나만은 제네우 생크리가 도움이 필요하대요.","제네우 생크리는 잿빛 골짜기 조람가르 전초기지에 있대요.","그를 찾아가 얘기를 나눠 달래요."},c={"츄나만이 보냈냐며 반가워해요.","이제 함께 나눌 이야기가 많대요."},nx=6563,nt="The Essence of Aku'Mai"},
[6563]={a={"제네우 생크리는 나가들이 사파이어를 모으는 걸 걱정해요.","사파이어에는 정령의 힘이 깃들어 위험하대요.","사파이어를 모아 제네우에게 가져다 달래요."},c={"말한 그 수정이 맞다며 반가워해요.","이제 나가 손에 없으니 다행이래요."}},
[6564]={a={"축축한 쪽지에는 누군가의 계획이 적혀 있어요.","수정의 힘으로 아쿠마이를 달래고 다시 불러낼 거래요.","쪽지를 제네우 생크리에게 가져다 달래요."},c={"이 쪽지가 중요하다며 고마워해요.","이제 로구스 제트라는 이름을 알게 됐대요."},nx=6565,nt="Allegiance to the Old Gods"},
[6565]={a={"제네우 생크리는 몸이 약해 직접 나설 수 없대요.","황혼의망치단이 고대 신을 믿으며 계획을 꾸미고 있대요.","검은심연의 나락에 가서 로구스 제트를 처치해 달래요."},c={"황혼의망치단을 완전히 막진 못했대요.","그래도 고대 신을 되살리려는 계획 하나는 막았대요."}},
[6566]={a={"스랄이 다시 보게 되어 반갑다고 해요.","바람이 동부 왕국에서 온 소식을 가져왔대요.","앉아서 자기 이야기를 들으라고 해요."},nx=6567,nt="The Champion of the Horde"},
[6567]={a={"용의 소굴로 들어갈 길이 있을지도 모른대요.","그 일로 렉사르를 찾아가라고 해요.","렉사르는 돌발톱 산맥과 페랄라스 사이 잊혀진 땅에 있대요."},c={"렉사르는 용의 소굴에 들어가는 길은 하나뿐이라고 해요.","열쇠는 사령관 드라키사스가 직접 마법을 걸어요.","검은용군단이 아니라서 통과가 어려울 거래요."},nx=6568,nt="The Testament of Rexxar"},
[6568]={a={"검은용군단의 경비를 피하려면 환영술이 필요하대요.","환영술의 대가인 노파 미란다를 만나 보라고 해요.","서부 역병지대에 있는 미란다에게 쪽지를 전해 달래요."},c={"미란다는 쪽지를 들고 웃으며 렉사르는 잘 지내냐고 물어요.","렉사르의 유서는 일부러 비워 둔 거래요.","호드의 대족장에게 빚이 있어서 당신을 돕겠대요."},nx=6569,nt="Oculus Illusions"},
[6569]={a={"검은용군단으로 변신하려면 환영을 만들 재료가 필요하대요.","검은바위 첨탑 위층에서 검은용혈족의 눈동자를 모으래요.","재료를 다 모으면 노파 미란다에게 돌아오라고 해요."},c={"미란다는 재료를 보고 이 정도면 충분하다고 해요.","이 재료로 문지기를 속일 환영의 메달을 만들어 준대요."},nx=6570,nt="Emberstrife"},
[6570]={a={"노파 미란다가 환영을 만드는 아뮬렛에 마법을 걸어 줬어요.","엠버스트라이프는 네파리안의 오래된 문지기래요.","먼지진흙 습지대 용의 둥지로 가서 굴에 들어가라고 해요."},c={"엠버스트라이프는 네파리안이 어린 용을 보냈냐며 비웃어요.","너는 내 시험을 절대 통과하지 못할 거래요."}},
[6571]={a={"록케 오카르네 벌목기지에 보급품이 떨어졌대요.","밧줄은 펄볼그들이, 기름은 사티로스가 빼앗았대요.","보급품을 모아 록케에게 가져다 달래요."},c={"일을 많이 덜어 줘서 정말 기뻐하고 있어요.","고마움은 확실히 느끼고 있대요."}},
[6582]={a={"엠버스트라이프는 당신이 진급할 자격이 있는지 보려 해요.","여명의 설원에서 푸른용군단의 용사 스크라이어를 처치하래요.","그의 해골을 가져와 엠버스트라이프에게 주래요."}},
[6583]={a={"엠버스트라이프가 당신의 용맹을 시험해 보려 해요.","슬픔의 늪에서 녹색용군단의 우두머리 솜누스를 찾으래요.","솜누스를 처치하고 해골을 가져와 엠버스트라이프에게 주래요."}},
[6584]={a={"시간의 동굴을 지키는 노즈도르무의 자손이 있대요.","그의 이름은 크로날리스이고 타나리스 사막에 있대요.","크로날리스를 처치하고 해골을 가져와 엠버스트라이프에게 주래요."}},
[6585]={a={"그림 바톨을 지키는 붉은용군단 부관 악트로즈가 있대요.","그 악트로즈를 처치하라고 해요.","그의 해골을 엠버스트라이프에게 가져오래요."},nx=6601,nt="Ascension..."},
[6601]={a={"엠버스트라이프는 당신이 모은 해골로 아뮬렛을 만들었대요.","사령관 드라키사스에게 아뮬렛을 건네래요.","사령관이 마지막 마법을 걸어 영혼과 맞춰 준대요."},c={"렉사르는 그냥 용들의 말장난일 뿐이라고 해요.","내용 없는 허풍이고 용들은 원래 거만하다고 해요."},nx=6602,nt="Blood of the Black Dragon Champion"},
[6602]={a={"렉사르는 사령관 드라키사스를 처치하라고 해요.","이번엔 변장하지 말고 검은바위 첨탑에 가래요.","피를 가져오면 오닉시아의 둥지 열쇠를 켜 준대요."}},
[6603]={a={"메지 페핀로커가 여명의 설원에 문제가 생겼대요.","간헐천 근처에 도노바 스노우덴이 있대요.","그에게 가면 자세한 내막을 들을 수 있대요."},c={"도노바 스노우덴은 반갑다며 메지가 말해 줬냐고 물어요."},nx=5082,nt="Threat of the Winterfall"},
[6605]={a={"하를로 위글즈워스는 악령의 숲에서 막 돌아왔대요.","피멍울 초소에서 이상한 여자를 만났는데 도움이 필요할지도 몰라요.","위나 해저드를 찾아가 보라고 해요."},c={"위나 해저드는 아직 희망이 있다며 도우러 왔냐고 물어요."},nx=4505,nt="Well of Corruption"},
[6607]={a={"내트 페이글은 오랫동안 낚시를 해 온 낚시꾼이래요.","달인이 되려면 오래보다 한자리에 버티는 의지가 필요하대요.","희귀한 물고기를 잡아 오면 낚시 기술을 가르쳐 준대요."},c={"내트 페이글은 훌륭한 낚시라며 낚싯줄 거는 법을 알려 준대요."}},
[6608]={a={"루막은 당신을 더 이상 가르칠 수 없다고 해요.","낚시를 잘한다며 내트 페이글을 찾아가라고 해요.","먼지진흙 습지대 섬에서 낚시 중일 거래요."},c={"내트 페이글은 루막의 친구냐며 낚시라면 다 알려 주겠대요."},nx=6607,nt="Nat Pagle, Angler Extreme"},
[6610]={a={"더지 퀵클레이브가 새로 만든 조개 별미를 자랑해요.","재료가 없어서 구해 오면 요리 비법을 알려 준대요.","재료 목록을 알려 주고 조개 별미도 준대요."},c={"더지는 특별한 요리를 맛보게 해 주겠다고 해요.","잘 보라며 조개 별미를 만들기 시작해요."}},
[6611]={a={"잠자는 요리 비법을 다 알려 줬다고 해요.","더 가르칠 게 없으니 가젯잔의 더지 퀵클레이브를 찾아가래요.","그에게 배워 훌륭한 요리사가 되면 다시 오래요."},c={"더지 퀵클레이브는 가죽 샌들 조각을 뱉고 콜록거려요.","가죽은 단백질이 많고 탄수화물은 적다고 우겨요."},nx=6610,nt="Clamlette Surprise"},
[6621]={a={"카랑 아마카르는 썩은나무일족의 포악함을 걱정해요.","썩은나무 마을에 깃발을 꽂으면 펄볼그들이 부수려 든대요.","족장 머구트를 물리치고 토템을 가져다 달래요."},c={"썩은나무일족에게 강한 경고를 보냈대요.","그 부족이 한동안 말썽을 피우지 못할 거래요."}},
[6622]={a={"의사 그레고리 빅터가 치료 순서 시험을 한대요.","위독한 부상병부터 치료하고 가벼운 부상병은 마지막에 해요.","시험에 통과하면 호드 응급의학회에 들어갈 수 있대요."},c={"의사 그레고리 빅터는 호드 응급의학회에 온 걸 환영한대요."}},
[6623]={a={"아르녹은 의사를 다시 만나 반갑다고 해요.","의사 그레고리 빅터가 당신을 해머폴로 불렀대요.","그분 밑에서 배울 기회니 놓치지 말래요."},c={"의사 그레고리 빅터는 좋다며 당장 수술복을 입으라고 해요."},nx=6622,nt="Triage"},
[6626]={a={"미리암 문싱어는 가시덩굴 구릉의 무리가 걱정돼요.","그 주위로 어둠에서 무리가 매일 몰려든대요.","그 무리를 함께 처치해 달래요."},c={"큰 도움이 될 거라며 고마워해요.","친구들과 멧돼지 입 같은 동굴에 가 보래요."}},
[6627]={a={"브라우그 딤스피릿이 책을 가져온 당신에게 질문을 하려 해요.","시간은 상관없으니 부담 갖지 말라고 해요.","질문에 답한 뒤 다시 말을 걸어 달래요."},c={"시험을 통과했다며 잘했다고 칭찬해요.","그 책을 공부한 덕분이래요."},nx=1159,nt="Test of Lore"},
[6628]={a={"파쿠알 핀탈라스는 지혜를 쫓는 사람이에요.","맡긴 임무를 끈기 있게 해내서 이제 문제를 낸대요.","준비되면 다시 찾아가 답해 달래요."},c={"정답을 맞혔어요. 텍스트를 읽었을지 의심했었대요."},nx=1394,nt="Final Passage"},
[6629]={a={"마카바 플랫후프가 그림토템 처치를 칭찬해요.","그룬디히 다크클라우드가 마을을 잔인하게 침략했대요.","그를 처치해 주면 영원히 고마워하겠대요."},c={"그룬디히 다크클라우드가 쓰러졌대요.","오늘 해 준 일을 늘 고마워하겠대요."}},
[6641]={a={"머그래쉬는 조람가르 전초기지를 공격하는 괴수가 있대요.","채찍꼬리 보르샤가 전초기지를 번번이 공격해 왔대요.","머그래쉬를 도와 화로를 끌 때 함께해 달래요."},c={"나가 공격을 많이 봐 와서 이제 마음이 놓인대요.","보르샤가 더 이상 마음대로 못 다니게 됐어요."}},
[6681]={a={"라벤홀트가 당신에게 관심을 보인대요.","암살단의 일원이 될 각오가 있다면 시작하래요.","라벤홀트의 인장을 힐스브래드 구릉의 장원에 가져가래요."}},
[6804]={a={"군주 히드락시스는 정령 정찰대가 동부 역병지대에서 병들었다고 해요.","넵튤론의 상이 든 병을 주며 병든 정령을 치료하라고 해요.","정령이 미쳐 날뛰니 불협의 팔보호구를 가져오래요."},c={"히드락시스는 잘했다며 정령들을 치료한 것을 칭찬해요.","우리의 힘은 순수함에 있고, 전쟁에 이기려면 강해야 한대요."}},
[6805]={a={"군주 히드락시스는 물의 정령이 하급 원소들과 싸운다고 해요.","실리더스의 수정 골짜기에서 적들을 물리쳐 달라고 해요.","그들이 힘 있는 물건을 지키지 못하게 막아 달래요."},c={"히드락시스는 당신의 용기가 증명됐다며 인정해요.","앞으로 더 중요한 일도 맡길 수 있대요."}},
[6821]={a={"히드락시스는 지금까지는 쉬운 적만 상대했다고 해요.","검은바위 첨탑의 오크들이 불의수호자 엠버시어를 잡아 가뒀대요.","엠버시어를 가둔 자들을 치고 그의 눈을 가져오래요."},c={"히드락시스는 힘뿐 아니라 꾀도 있다며 칭찬해요.","검은바위 첨탑은 힘만으로는 이기기 어렵대요.","당신이 우리의 소중한 동맹이 될지도 모른대요."},nx=6822,nt="The Molten Core"},
[6822]={a={"히드락시스는 이제 진짜 시험을 치를 때라고 해요.","검은바위 나락 맨 아래에 있는 화산 심장부로 가라고 해요.","동료들이 있으면 군대처럼 불러 모으라고 해요."},c={"히드락시스는 불가능하다고 여긴 일을 해냈다고 해요.","작은 몸으로 화산 심장부의 적들을 이겼대요.","언젠가 종족과 물의 군주들이 진정한 동맹을 맺을 수도 있대요."},nx=6823,nt="Agent of Hydraxis"},
[6823]={a={"히드락시스는 바람과 대지, 불의 적들을 물리치라고 해요.","적을 하나씩 물리칠수록 그들의 기반이 약해진대요.","길지만 참고 버티면 큰 명예를 얻을 거래요."},c={"히드락시스는 당신의 활약이 물의 군주들 사이에 울린다고 해요.","몸이 작아서 못 싸울 거라 생각했지만 큰 공을 세웠대요.","모두에게 존경을 받을 만한 일이라고 해요."},nx=6824,nt="Hands of the Enemy"},
[6824]={a={"히드락시스는 당신을 잃을까 망설이면서 마지막 임무를 줘요.","화산 심장부의 부대장들을 처치하래요.","그들의 손을 가져가라고 해요."},nx=7486,nt="A Hero's Reward"},
[6844]={a={"라요 스타스트라이크는 이 딱딱한 실리시드 조각을 분석하려 해요.","이걸 달의 숲 나이트헤이븐의 기록관 움버에게 가져가래요.","움버는 약간 실성했지만 아주 똑똑해서 복구할 수 있대요."},c={"움버는 이게 책처럼 생겼다며 껍데기를 깨 보겠대요.","실리더스의 끔찍한 소문 때문에 벌레는 질색이라 여기 남겠대요."},nx=6845,nt="Uncovering Past Secrets"},
[6845]={a={"움버는 이 안에 뭐가 들었는지 아직 모른대요.","알아내면 알려 줄 테니 나중에 다시 오래요.","그동안 나이트헤이븐의 라빈 사투르나와 얘기해 보래요."},nx=1185,nt="Under the Chitin Was..."},
[6921]={a={"제네우 생크리가 황혼의망치단을 걱정하고 있어요.","그들이 검은심연의 나락 달의 제단 폐허에 들어갔대요.","물속 심연의 돌에서 심연의 핵을 가져다 달래요."},c={"이게 바로 필요했대요. 심연의 핵은 정보가 많아요.","호드 전체를 도왔으니 자랑스러워해도 된대요."}},
[6922]={a={"물의 정령이 쓰러지면서 이상한 물구슬을 남겼어요.","구슬은 끔찍한 느낌이 들지만 손상되지 않는 듯해요.","잿빛 골짜기의 제네우 생크리에게 가져다 달래요."},c={"군주 아쿠아니스는 타락한 정령으로 여겨져 왔대요.","이 구슬로 무엇이 그를 타락시켰는지 알아낼 거래요."}},
[6981]={a={"이 빛나는 조각은 밝은 녹색이에요.","수정 안에서 연기 같은 게 소용돌이쳐서 불길한 느낌이 들어요.","톱니항에서 이를 잘 아는 사람을 찾아 달래요."},c={"이런 건 처음 본다며 놀라워했어요."}},
[7003]={a={"조브린 팬대즐은 거인들 때문에 장사가 힘들어요.","조브린의 형상축소기를 고블린 기술로 만들었대요.","페랄라스의 거인 아무나 골라 시험해 달래요."},c={"조브린 팬대즐은 잔류물을 가져와 기뻐하대요.","몸도 성하게 돌아와서 다행이라고 해요."}},
[7028]={a={"윌로우는 마라우돈의 고대 역사를 차지하고 싶대요.","거대한 문 뒤에 고대 신의 유물이 숨어 있대요.","트라드릭 수정 조각상을 찾아 가져다 달래요."}},
[7029]={a={"바르크 배틀스카는 바일텅이 동굴을 오염시켰다고 해요.","식물들이 자라지 못해 큰일이래요.","약병에 치료제를 담아 식물에 부어 달래요."},c={"바르크는 돌아온 모험가에게 고마워하대요.","바일텅이 퍼뜨린 오염을 조금 치료했대요."}},
[7044]={a={"카빈드라의 형제 셀레브라스가 저주에 걸렸대요.","바일텅과 녹시온이 셀레브라스의 홀을 훔쳐 갔대요.","홀 조각을 찾아 형제에게 말을 전해 달래요."},nx=7046,nt="The Scepter of Celebras"},
[7046]={a={"회복된 셀레브라스는 홀이 큰 희망이었대요.","홀 조각을 다시 합치는 의식이 필요하대요.","의식 중에 자기 지시를 잘 따라 달래요."}},
[7064]={a={"셀렌드라는 재타르의 유골을 되찾고 싶어 해요.","재타르는 켄타우로스에게 살해돼 유골이 그들 손에 있대요.","공주 테라드라스를 물리쳐 달래요."},c={"셀렌드라는 가장 어려운 일을 끝내 기뻐해요.","보답으로 부족의 증표 중 하나를 고르래요."}},
[7066]={a={"재타르의 영혼은 켄타우로스 자식들을 걱정해요.","자신의 유골을 양분 삼아 씨앗이 자랐대요.","수호자 레물로스에게 그 씨앗을 전해 달래요."},c={"레물로스는 형제가 평안을 찾았다며 기뻐해요.","씨앗이 언젠가 중요해질 거라고 느껴요."}},
[7067]={a={"켄타우로스 추방자는 이단으로 쫓겨났대요.","그래도 자기 믿음은 확고해서 운명을 완성하려 해요.","외부인의 도움으로 성스러운 묘지에 들어가 달래요."}},
[7068]={a={"우텔나이는 마라우돈에서 강한 마력이 발견됐대요.","음영석으로 된 바위 생명체가 그곳에 있대요.","보라색 수정을 가져다 달래요."},c={"우텔나이는 이 조각이 마법에 딱 맞는다며 좋아해요.","보답으로 장신구 하나를 골라 가래요."}},
[7082]={a={"알터랙 계곡의 전선은 늘 움직인대요.","가장 치열한 싸움은 무덤에서 벌어진대요.","얼라이언스 깃발이 꽂힌 무덤을 공격해 달래요."}},
[7101]={a={"보초탑과 참호는 꼭 차지해야 한대요.","적이 차지한 보초탑이나 참호를 공격하래요.","안의 얼라이언스 깃발을 뽑아 달래요."},c={"하사관 티카 블러드스날이 임무 성공 소식에 기뻐해요.","이제 호드 병사들이 거침없이 진격할 수 있대요."}},
[7123]={a={"조테크는 서리늑대 병참장교가 신병을 찾는대요.","광산과 관련된 일이 있다고 해요.","참호 안에서 병참장교와 직접 얘기해 보래요."},c={"병참장교는 열정 있는 모험가를 반갑게 맞아요.","중요한 임무가 있으니 다시 얘기하자고 해요."},nx=7124,nt="Capture a Mine"},
[7124]={a={"얼음이빨 광산과 깊은무쇠 광산도 흔들리고 있대요.","두 광산은 광물이 많고 보급품도 쌓여 있대요.","적이 차지한 광산 하나를 점령해 달래요."},c={"하사관 티카 블러드스날은 광산을 차지한 일을 칭찬해요.","호드 병사들이 지키니 광물 캐기가 쉬워진대요."}},
[7142]={a={"스톰파이크 드워프와 동맹들이 알터랙 계곡을 침입했대요.","그 사령관 반다르 스톰파이크가 던 발다르에 있대요.","그를 처치하고 돌아와 보고하래요."},c={"보그가 데스그립은 잘했다고 칭찬해요.","스톰파이크는 사령관을 잃어 희망이 없대요."},nx=8272,nt="Hero of the Frostwolf"},
[7161]={a={"전투대장 락그론드는 신병이 먼저 의식을 치러야 한대요.","자갈발일족 놀의 동굴 깊숙한 곳에 서리늑대 깃발이 있대요.","그 깃발을 가져다 달래요."},c={"락그론드는 이제 당신이 서리늑대의 일원이라고 해요.","계급장을 항상 지니라고 당부해요."},nx=7163,nt="Rise and Be Recognized"},
[7163]={a={"전투대장 락그론드가 당신의 때가 왔다고 해요.","서리늑대를 위해 힘써서 병사로 인정받았대요.","입단 계급장을 내보여 달래요."},c={"새 계급장은 서리늑대 안에서의 당신 계급을 보여 줘요.","언제나 몸에 지니고 명예롭게 싸우라고 해요."},nx=7164,nt="Honored Amongst the Clan"},
[7164]={a={"전투대장 락그론드는 다시 찾아온 모험가를 반겨요.","서리늑대의 용감한 병사로 증명했대요.","새 계급을 얻었으니 계급장을 내보여 달래요."},nx=7165,nt="Earned Reverence"},
[7165]={a={"전투대장 락그론드는 적들이 당신을 두려워하는지 묻는대요.","병사들 사이에서 존경을 받게 됐대요.","계급장을 내보여 달래요."},c={"당신의 무용담이 벌써 퍼지고 있대요.","스톰파이크는 당신 이름만 들어도 떤대요."},nx=7166,nt="Legendary Heroes"},
[7166]={a={"전투대장 락그론드가 당신의 힘을 높이 칭찬해요.","서리늑대의 영웅이라 적들이 이름만 들어도 움츠린대요.","계급장을 내보여 달래요."},c={"곧 전장의 모든 것이 당신 눈 아래 놓인대요.","알터랙 계곡과 병사들을 지휘하게 된대요."},nx=7167,nt="The Eye of Command"},
[7167]={a={"드렉타르가 당신을 칭찬했대요.","칼림도어에 당신의 무공담이 퍼졌대요.","지휘관 계급장을 내보여 달래요."},c={"계급장의 힘을 끌어내 보라고 해요.","적들에게 당신의 말이 들리게 하래요."}},
[7181]={a={"알터랙 계곡에는 스톰파이크 말고도 위협이 있대요.","겨울도끼 트롤들도 권력을 두고 싸운대요.","우두머리 피의 광전사 콜라크를 처치해 달래요."}},
[7201]={a={"어둠마법사 비비안 라그레이브가 일을 맡기래요.","검은무쇠단은 강한 골렘을 만드는 법을 알아요.","검은바위 나락에서 원소의 정수를 찾아 달래요."},c={"비비안은 기뻐하며 언더시티로 바로 보내겠대요.","보수를 주며 거스름돈은 가지라고 해요."}},
[7224]={a={"대장장이 렉자르는 우리 부대에 쓸 방어구가 필요해요.","그 조각으로 새 방어구를 만들려고 한대요.","적과 싸우며 방어구 조각을 모아 가져다 달래요."}},
[7241]={a={"서리늑대 사절 로크스트롬이 도움을 청해요.","아이언포지의 스톰파이크 경비대가 서리늑대를 공격했대요.","타렌 밀농장 북쪽 알터랙 계곡에서 락그론드를 찾아 달래요."},c={"락그론드는 서리늑대 병사가 되려면 먼저 시험을 받아야 한대요."},nx=7161,nt="Proving Grounds"},
[7321]={a={"크리스토프 제프코트는 자기만의 비법 요리가 있어요.","요즘은 여기 일을 두고 떠날 수 없어 요리를 못 한대요.","거북이 고기와 독특한 양념을 가져오면 가르쳐 준대요."},c={"추운 밤에도 따뜻해질 비스크라고 자랑해요."}},
[7361]={a={"나자크 헥센은 나이트 엘프도 트롤에게서 나왔대요.","스태그헬름이 트롤을 없애려 한다고 화를 내요.","나이트 엘프를 쓰러뜨려 머리카락을 가져다 달래요."},c={"나자크는 수많은 것 중 하나라며 잘했다고 해요."}},
[7362]={a={"라바크 그림토템은 대모 마가타의 명을 받고 왔대요.","마가타는 노움의 생존력을 연구하고 싶어 해요.","노움 머리카락 뭉치를 가져다 달래요."},c={"라바크 그림토템은 확실한 노움이라며 칭찬해요.","아직 할 일이 더 남았대요."}},
[7363]={a={"지휘관 루이스 필립스는 인간을 몹시 싫어한대요.","언더시티 연금술 실험실을 위해 인간 뼈조각을 모은대요.","인간을 찾아 쓰러뜨리고 뼈조각을 가져다 달래요."},c={"필립스는 인간들이 치료의 손길에 순순히 따르면 좋겠대요.","어떤 방법으로든 치료하겠대요."}},
[7441]={a={"아즈토르딘은 임프 푸실린에게 마법서를 도둑맞았대요.","마법서는 아즈토르딘에게 꼭 필요한 물건이래요.","혈투의 전장 굽이나무 지구에서 마법서를 되찾아 달래요."},c={"아즈토르딘은 마법서를 찾아 기뻐하며 푸실린에게 저주를 퍼부어요.","가진 게 많지 않으니 하나 골라 가라고 해요."}},
[7461]={a={"셴드랄라 고대인은 이 광란을 끝내고 싶어 해요.","불멸의 시대는 오래전에 지나갔대요.","이몰타르를 처치해 도시의 영혼들을 쉬게 해 달래요."},nx=7877,nt="The Treasure of the Shen'dralar"},
[7463]={a={"현자 리드로스가 오랜만에 본 마법사를 반가워해요.","도서관 서고에 물의 정령 히드로스폰이 나타났대요.","굽이나무 지구에서 히드로스폰의 정수를 가져와 달래요."}},
[7481]={a={"카리엘 윈탈루스라는 엘프 스승이 유물을 들고 달아났대요.","현자 코로루스크는 그가 혈투의 전장에 숨었을 거라 짐작해요.","그를 찾아 유물을 꼭 되찾아 달래요."},c={"코로루스크는 유물을 잃었다니 안타까워해요.","그의 흔적도 전혀 없냐고 되묻대요."}},
[7486]={a={"군주 히드락시스는 당신의 충성이 기대 이상이었대요.","섬 남쪽 물속에 상이 든 궤짝이 있대요.","히드락시스의 궤짝에서 보상을 가져가 달래요."},c={"히드락시스가 물 위에서 말을 건네요.","당신에게 맞는 보상을 하나 고르라고 해요."}},
[7489]={a={"블러드 엘프 레스텐드리스가 도를 넘었대요.","타락한 마법을 빨아들이는 그물을 만들었대요.","그녀를 물리치고 그물을 가져다 달래요."},c={"탈로 쏜후프는 잘했다며 그물의 힘을 걱정해요.","그 그물은 더 책임감 있는 마법사들에게 보낸대요."}},
[7490]={a={"검은용군단의 여왕 오닉시아가 죽었대요.","호드의 승리 소식을 대족장에게 전해야 해요.","오그리마의 스랄에게 오닉시아의 머리를 가져다 달래요."},c={"스랄은 호드의 큰 승리라며 기뻐해요.","이제 대족장이 당신을 높이 기릴 차례래요."},nx=7491,nt="For All To See"},
[7491]={a={"대군주 룬탁이 힘의 골짜기에서 당신을 기다린대요.","스랄은 당신을 오그리마의 영웅이라 부르며 경례해요.","주민들을 오래 기다리게 하지 말래요."},nx=7493,nt="The Journey Has Just Begun"},
[7492]={a={"선구자 발타자드는 탈로 쏜후프가 도움을 청한대요.","민감하고 끔찍한 문제라 요원이 필요하대요.","모자케 야영지에서 탈로 쏜후프와 이야기해 보래요."},c={"탈로 쏜후프는 부름에 응해 줘서 반가워해요.","그 일은 위험한 혈투의 전장으로 이어진대요."},nx=7489,nt="Lethtendris's Web"},
[7507]={a={"노스트로의 용사냥 개론은 지금까지 본 책과 달라요.","누군가 도서관의 인장을 깨뜨린 것 같대요.","그 책을 도서관에 되돌려 달래요."},c={"리드로스가 이 책은 암시장에서 큰돈이 됐을 거래요.","인장이 깨져 용사냥 비법이 누구에게나 열렸대요.","그래서 큰 보상을 줄 테지만 얻기까지 큰 노력이 필요하대요."},nx=7508,nt="The Forging of Quel'Serrar"},
[7509]={a={"현자 리드로스가 고대의 검을 단련해 쓰려고 해요.","오닉시아의 불 숨결로 검을 달구는 게 관건이래요.","달궈진 고대의 검을 시신에 꽂아 리드로스에게 가져다 달래요."},c={"리드로스가 알아듣기 힘든 말을 중얼거려요.","약속대로 쿠엘세라 검을 건네요."}},
[7562]={a={"스파클 손베리는 당신의 흑마법 실력을 알아봤대요.","특별한 탈것을 길들이려면 큰 힘과 재료가 필요하대요.","폭풍의 제단 근처의 모르줄 블러드브링어와 대화해 보래요."},c={"모르줄 블러드브링어는 당신이 찾아온 이유를 알아챘대요.","특별한 탈것은 피와 땀, 돈이 많이 든대요."},nx=7563,nt="Rage of Blood"},
[7563]={a={"모르줄 블러드브링어는 특별한 잉크가 필요하대요.","흉포한 올빼미야수의 피가 잉크 재료래요.","그 피를 모아 모르줄 블러드브링어에게 가져다 달래요."},c={"모르줄 블러드브링어는 피를 잉크로 만들겠대요.","자기 몫으로 조금 남기겠다고 해요."},nx=7564,nt="Wildeyes"},
[7564]={a={"고르지키 와일드아이즈는 모르줄의 연금술 하인이래요.","그가 양피지에 쓸 잉크를 만들 수 있대요.","피가 담긴 상자를 가져다 달래요."},c={"고르지키는 이 피가 모르줄의 것이라고 알아봐요.","의식을 하려면 피보다 훨씬 많은 게 필요하대요."}},
[7581]={a={"노쇠한 다이오는 파멸의 수호병을 가둘 감옥을 만들려 해요.","재료는 하급 악마에게서 얻어야 한대요.","혈투의 전장에서 사티로스의 피를 구해 달래요."},c={"다이오는 훌륭하게 구했다며 기뻐해요.","이 피가 파멸의 수호병의 마법 방어를 누를 거래요."},nx=7583,nt="Suppression"},
[7582]={a={"노쇠한 다이오는 감옥 벽을 만들 재료가 필요하대요.","헤더린 악마의 독이 굳어 마법에 강한 수정이 된대요.","여명의 설원 검은속삭임 협곡에서 헤더린의 눈물을 구해 달래요."},c={"다이오는 이 수정을 사티로스의 피와 합치면 된대요.","그러면 감옥을 쓸 준비가 끝난대요."},nx=7583,nt="Suppression"},
[7583]={a={"노쇠한 다이오가 감옥 준비를 마쳤어요.","파멸의 수호병은 교활해서 거세게 저항할 거래요.","타락의 흉터에서 그를 찾아 빛나는 수정 감옥에 가둬 달래요."}},
[7601]={a={"전지전능한 나이비에게 소환법을 배우려면 조건이 있대요.","크로쉬우스는 거의 다 타 버려서 되살려야 한대요.","그의 지옥핵을 가져오면 임프시가 더 알려 준대요."},nx=7602,nt="Flawless Fel Essence"},
[7602]={a={"임프시는 지옥불을 만들려면 재료가 필요하대요.","재료는 서로 다른 지역의 적들이 가지고 있대요.","지역마다 정수를 모아 임프시에게 가져다 달래요."},c={"임프시가 잠깐 기다리면 정수를 합쳐 지옥불을 만든대요."},nx=7603,nt="Kroshius' Infernal Core"},
[7603]={a={"지옥의 불꽃을 건네며 임프시가 부탁해요.","크로쉬우스의 잔해는 불벼락 골짜기에 쌓여 있대요.","그 지옥핵을 꺼내 전지전능한 나이비에게 전해 달래요."}},
[7604]={a={"설퍼론 주괴가 진품이라고 밝히는 계약서예요.","서명하면 설퍼라스로 생긴 피해에 조합 책임이 없대요.","로크토스 다크바게이너에게 계약서를 내면 도면을 준대요."},c={"로크토스 다크바게이너는 거래가 즐거웠다며 행운을 빌어요.","설퍼라스 찾기에도 행운이 있기를 바란대요."}},
[7622]={a={"에리스 헤븐파이어는 자신이 못 한 일을 맡기려 해요.","스트라솔름에서 탈출하려던 인부들이 살해당했대요.","인부들이 살아남아 빛으로 가게 지켜 달래요."},c={"에리스 헤븐파이어가 당신의 끈기와 용기에 감탄해요.","이제 놀드랏실의 파편을 가질 자격을 얻었대요.","마지막으로 세상을 뒤져 어둠의 눈을 찾으라고 해요."}},
[7623]={a={"고르지키 와일드아이즈는 어둠의 물약을 파는 사람이에요.","자에데나르에 가려면 어둠의 물약으로 몸을 감춰야 한대요.","군주 베인할로우와 이야기해 보라고 해요."},c={"군주 베인할로우는 자기 인내심이 아주 길다고 해요.","그래도 잠깐 이상은 시간을 내주지 않는대요."},nx=7624,nt="Ulathek the Traitor"},
[7624]={a={"군주 베인할로우는 부하 울라텍을 의심하고 있어요.","울라텍은 군주 헬누라스의 첩자래요.","어둠의 요새에서 울라텍을 처치해 달래요."},c={"군주 베인할로우는 심장을 일주일쯤 썩히면 별미라고 해요.","당신 덕에 인내심이 조금 늘었다고 해요."},nx=7625,nt="Xorothian Stardust"},
[7625]={a={"군주 베인할로우는 당신이 별가루를 찾아왔다고 말해요.","별가루는 부하 우르단이 가지고 있는데 값을 치러야 해요.","별가루를 사서 고르지키에게 가져다 달래요."},c={"고르지키 와일드아이즈는 별가루를 구했다니 믿기지 않는대요.","공포의군주와 큰 거래를 했거나 큰돈을 냈겠대요."},nx=7629,nt="Imp Delivery"},
[7626]={a={"모르줄 블러드브링어는 대소환의 원을 준비하고 있어요.","데스무라의 종은 고르지키 와일드아이즈가 만들 수 있대요.","연금술사에게서 암흑 강화의 비약을 구해 가져다 달래요."}},
[7627]={a={"모르줄 블러드브링어는 대소환의 원에 쓸 바퀴가 필요해요.","눈부신 큰 결정과 검은무쇠 광석이 필요하대요.","그 재료를 모아 고르지키 와일드아이즈에게 가져다 달래요."},c={"고르지키 와일드아이즈는 검은무쇠 광석이 깊은 곳에서만 난다고 들었대요.","바퀴는 의식 때까지 만들어 보관해 준대요."}},
[7628]={a={"모르줄 블러드브링어는 의식에 쓸 심판의 양초를 준비해요.","양초의 불에 의식을 방해하는 악마들이 타 버린대요.","검은용 비늘을 얻어 고르지키 와일드아이즈에게 가져다 달래요."},c={"고르지키 와일드아이즈는 이 비늘로 불을 가둘 수 있대요.","양초를 만들어 의식 때까지 보관해 준대요."}},
[7629]={a={"고르지키 와일드아이즈는 여기서 양피지를 만들 장비가 없대요.","스칼로맨스에 연금술 실험실이 있대요.","단지 안에 든 임프를 그 실험실에서 풀어 달래요."},c={"고르지키 와일드아이즈는 지비가 양피지를 만들었다고 해요.","단지는 오래 쓴 물건이라 팔 수 없대요."}},
[7630]={a={"고르지키 와일드아이즈는 종, 바퀴, 양초를 다 만들었대요.","이제 의식이 실패할 때를 대비해 검은 자철석이 필요하대요.","자철석을 만들려면 아케이나이트를 구해 다시 와 달래요."},c={"고르지키 와일드아이즈는 아케이나이트를 가져와 잘했다고 해요.","이제 자철석을 만들어 의식이 실패하지 않게 해 준대요."}},
[7631]={a={"모르줄 블러드브링어는 모든 준비를 마쳤대요.","이제 의식을 치러 포탈을 열어야 한대요.","지시서대로 소로시안 공포마를 물리치고 영혼을 묶어 달래요."},c={"소로시안 공포마의 영혼이 쓰러졌대요.","그 영혼이 어둠의 마법을 속삭이며 공포마 소환법을 알려 준대요."}},
[7632]={a={"밝은 녹색에 표면이 아주 울퉁불퉁한 잎사귀예요.","맥과 주름이 보이고 아주 오래된 힘이 느껴져요.","이 잎의 원래 주인을 찾아보라고 해요."},c={"고대정령 바르투스는 자기 잎사귀를 알아봐요.","잎이 완벽한 상태라고 해요."}},
[7634]={a={"고대정령 하스타트는 오래전 잃어버린 지식을 가졌대요.","잎사귀 하나로 특별한 화살통을 만들 수 있대요.","다 자란 푸른용 힘줄을 가져다 달래요."}},
[7635]={a={"고대정령 스토마는 활시위에 마법을 부여할 수 있대요.","그 활시위 재료로 다 자란 검은용 힘줄이 필요해요.","그 힘줄을 가져오면 튼튼한 활시위로 만들어 준대요."},c={"스토마가 그 용은 몹시 사악했다고 해요.","힘줄을 정화하고 마법을 걸 동안 기다리래요."}},
[7636]={a={"바르투스는 불타는 군단이 아직 활동한다고 해요.","그들이 닿는 것은 모두 썩고 자연이 시든대요.","혼자서 그들을 찾아 처치하고 증거를 가져오래요."},c={"바르투스가 잘했다고 칭찬해요.","이 지팡이를 스토마의 활시위와 합치라고 해요.","둘이 합치면 강력한 무기가 된대요."}},
[7654]={a={"데로타인 머드시퍼가 판금 장화 설계도를 팔려 해요.","설계도 값으로 많은 재료를 요구한대요.","황제의 판금 장화 설계도 재료를 가져오래요."},c={"데로타인 머드시퍼가 거래해서 즐겁대요.","그리고 당신의 불쾌한 표정은 좀 지우라고 해요."}},
[7655]={a={"데로타인 머드시퍼가 팔보호구 설계도를 팔려 해요.","당신이 얼굴이 빨개졌다고 놀려요.","팔보호구 설계도 재료를 가져다 달래요."},c={"데로타인 머드시퍼가 거래해서 즐겁대요.","그리고 당신의 불쾌한 표정은 좀 지우라고 해요."}},
[7656]={a={"데로타인 머드시퍼가 황제의 판금 흉갑 설계도를 팔려 해요.","당신이 불평한다며 비웃고 재료를 요구해요.","황제의 판금 흉갑 설계도 재료를 가져오래요."},c={"데로타인 머드시퍼가 거래해서 즐겁대요.","그리고 당신의 불쾌한 표정은 좀 지우라고 해요."}},
[7658]={a={"데로타인 머드시퍼가 황제의 판금 다리보호구 설계도를 팔려 해요.","당신의 하소연은 듣기 싫다고 해요.","다리보호구 설계도 재료를 가져오래요."},c={"데로타인 머드시퍼가 거래해서 즐겁대요.","그리고 당신의 불쾌한 표정은 좀 지우라고 해요."}},
[7667]={a={"사고른 크레스트스트라이더가 급한 문제가 생겼대요.","대형 납골당의 어둠을 뚫을 장치를 완성해야 한대요.","아제로스 다이아몬드와 온전한 검은 다이아몬드를 구해 달래요."},c={"사고른이 당신의 너그러움에 감사해요.","이제 다이아몬드 없이도 탐지기를 더 만들 수 있대요.","그리고 탐지기 사용을 도와줄 수 있는지 묻는대요."},nx=8258,nt="The Darkreaver Menace"},
[7701]={a={"지명수배 공고에 감독관 말토류스의 현상금이 걸렸어요.","말토류스는 잿가루 채석장의 검은무쇠단 지휘관이래요.","잿가루 채석장에서 그를 처치하고 증거를 가져와 달래요."},c={"감시대장 롤로 롱스트라이커는 그 못생긴 얼굴을 다시 볼 줄 몰랐대요.","몸이 없으니 오히려 더 나아 보인다며 보상을 줘요."}},
[7702]={a={"드워프들은 쉬어야 하는데 베개 없이는 잠을 못 잔대요.","잿가루 채석장의 검은무쇠단 생산성을 떨어뜨리려는 거래요.","잿가루 채석장에 몰래 들어가 그들의 베개를 훔쳐 달래요."}},
[7703]={a={"대장 크롬크러쉬는 당신을 새 왕으로 여기고 있어요.","토르텔드린이라는 엘프가 옛 고르독 왕에게서 유물을 훔쳐 갔대요.","권력의 고르독 건틀릿을 찾아 크롬크러쉬에게 가져다 달래요."},c={"대장 크롬크러쉬는 당신이 진짜 왕이라며 감탄해요.","건틀릿의 마법 표식을 되살려 힘을 되찾아 준대요.","그러고는 건틀릿을 가지고 영원히 다스리라고 해요."}},
[7721]={a={"조브린 팬대즐은 잊혀진 해안에서 작업장을 운영한대요.","그 해안의 정령들은 형상축소기에 쓸 좋은 동력원이래요.","정령들을 처치하고 물의 정령 핵을 꼭 가져다 달래요."},c={"조브린은 이 핵들로 한동안 일할 수 있어 기뻐해요.","정령이 줄어 해안도 조금 나아졌다고 해요.","그러고는 감사의 뜻으로 전리품을 준대요."}},
[7722]={a={"감독관 말토류스가 떠나며 비밀 조제법을 가져갔대요.","그 조제법은 불꽃 융해촉진제를 만드는 방법이래요.","잿가루 채석장에서 찾아 수석대장장이 버니네이트에게 주래요."}},
[7723]={a={"한셀 헤비핸드는 손가락이 부어 예전처럼 못 싸운대요.","날씨 탓에 손가락이 텔사마 선지 소시지처럼 부었대요.","이글거리는 협곡의 육중한 전투골렘을 처치해 달래요."},c={"한셀 헤비핸드는 당신이 착한 친구라고 칭찬해요.","수고비로 작은 선물을 준대요."}},
[7724]={a={"한셀 헤비핸드는 쉬려는데 또 일이 떨어졌대요.","거대한 용암거미가 불을 뿜어 아이들을 놀래킨대요.","그 용암거미들을 처치해 달래요."}},
[7727]={a={"한셀 헤비핸드는 발에 물집이 잡혀 싸우기 힘들대요.","잿가루 채석장 용암 지대에서 인센도사우루스가 말썽이래요.","인센도사우루스가 멸종할 때까지 돌아오지 말래요."}},
[7728]={a={"토륨 대장조합의 도난 물건을 찾는 의뢰가 있어요.","이 물건들은 검은무쇠단 드워프들이 훔쳐 갔을 거래요.","도난 물건을 찾아 작업반장 스크랜지에게 가져다 달래요."},c={"작업반장 스크랜지는 잘했다며 기뻐해요.","이제 보상을 준대요."}},
[7729]={a={"작업반장 스크랜지는 경쟁자를 솎아 낼 사람을 찾는대요.","검은무쇠단 감독관과 노예상인을 처치해야 한대요.","옷이 피로 흠뻑 젖으면 스크랜지에게 돌아가래요."},c={"스크랜지는 옷에 묻은 피가 신기록감이라며 놀라요."}},
[7730]={a={"아도겐 스위프트스트라이더는 모자케 야영지에서 일해요.","놀들 남쪽의 곤충 주크애쉬가 놀들을 미쳐 날뛰게 한대요.","고통의 구덩이에 가서 녀석들을 줄이고 등껍질을 가져오래요."},c={"아도겐 스위프트스트라이더는 시간을 벌었다며 잘했다고 해요.","등껍질을 분석해 더 큰 위협에 대비하겠대요."}},
[7731]={a={"정찰병이 고통의 구덩이에서 아주 큰 곤충을 봤대요.","그 곤충에 채찍쐐기라는 이름을 붙였대요.","분비선을 잘라 아도겐 스위프트스트라이더에게 가져다 달래요."},c={"아도겐 스위프트스트라이더는 대단하다며 크게 감탄해요.","야영지 모두의 감사를 담아 보상으로 돈을 준대요."}},
[7732]={a={"아도겐 스위프트스트라이더가 호드를 위해 마지막 임무를 부탁해요.","주크애쉬 곤충에 대한 정보가 담긴 보고서가 있어요.","이 보고서를 오그리마 골목길의 질지빈 드럼로어에게 전해 달래요."},c={"질지빈 드럼로어는 주크애쉬가 silithid라는 생물이라고 해요.","이건 호드가 계속 외면해 온 오래된 위협이래요.","실력이 되면 이 위협을 알리는 일을 도와 달래요."}},
[7734]={a={"장도르 스위프트스트라이더는 가죽을 더 잘 구할 곳을 알아요.","페랄라스 북쪽 무쇠설인 소굴에 더 강한 설인들이 산대요.","그 설인들의 가죽을 모아 장도르에게 가져다 달래요."},c={"장도르 스위프트스트라이더는 가죽이 아주 좋다며 기뻐해요.","도움에 고맙다며 자기가 최근 만든 물건을 주대요."}},
[7761]={a={"대족장 렌드 블랙핸드가 보낸 명령서예요.","지배의 보주는 드라키사스의 낙인이 있어야 쓸 수 있대요.","사령관 드라키사스가 낙인을 지키니 찾아가 보래요."},c={"당신은 달군 낙인이 찍혀도 움찔하지 않았대요.","이제 드라키사스의 낙인을 가지게 됐대요."}},
[7783]={a={"전투로 상처 입은 네파리안의 머리가 놓여 있어요.","그 머리는 거대하고 흉터가 가득하대요.","오그리마의 스랄에게 이 머리를 가져다 달래요."},nx=7784,nt="The Lord of Blackrock"},
[7785]={a={"대영주 데미트리안이 환생의 관을 살펴보라고 해요.","이 관에서 바람추적자가 다시 태어날 거래요.","관을 조사해 데미트리안에게 가져다 달래요."},nx=7786,nt="Thunderaan the Windseeker"},
[7786]={a={"대영주 데미트리안은 알고 있던 걸 다 알려 줬대요.","엘레멘티움을 찾고 불의군주의 육체를 무너뜨려야 한대요.","이 일을 해내면 썬더란의 축복을 받는대요."},c={"데미트리안은 이런 날이 올 줄 꿈에도 몰랐대요.","존재보다 오래된 주인에게 족쇄를 깨라고 외쳐요."},nx=7787,nt="Rise, Thunderfury!"},
[7787]={a={"바람추적자를 물리쳐 잠든 성검을 얻었어요.","데미트리안은 배신해 우레폭풍을 깨운 자래요.","잠든 성검을 데미트리안 앞에 내놓아 죄를 깨우쳐 달래요."}},
[7810]={a={"검투사가 되는 일이 이렇게 간단할 리 없대요.","구루바시에서 행사를 운영하는 해적단원이 더 알 거래요.","가시덤불 골짜기의 땅딸보 존 미스릴을 찾아가 보래요."},c={"땅딸보 존 미스릴은 장신구 하나로는 부족하다고 해요.","이제 진짜 실력을 증명할 때래요."}},
[7813]={a={"랄스톤 판슬레이가 양털 천을 기부받고 있대요.","언더시티 창고에 양털 천이 부족하대요.","가진 양털 천을 기부해 달래요."}},
[7814]={a={"랄스톤 판슬레이가 비단 재고가 바닥났다고 해요.","다른 주민들의 도움으로 목표를 채우려 한대요.","가진 비단 천을 기부해 달래요."}},
[7815]={a={"낚시꾼 카툼은 레반터스크 마을에서 골머리를 앓아요.","무쇠턱바다거북이 미끼를 계속 훔쳐 낚싯줄을 끊어 먹는대요.","그 거북 무리를 모두 처치해 달래요."},c={"낚시꾼 카툼은 정말 고맙다며 낚싯대를 보상으로 줘요."}},
[7816]={a={"낚시꾼 카툼은 최고급 미끼를 잃어버렸대요.","감메리타라는 무쇠턱바다거북 우두머리가 미끼를 훔쳐 갔대요.","감메리타를 처치하고 미끼를 되찾아 카툼에게 가져다 달래요."},c={"카툼은 최고급 미끼를 되찾아 아주 기뻐해요.","무쇠턱바다거북이 줄었으니 고기도 많이 잡히겠대요."}},
[7817]={a={"랄스톤 판슬레이가 마법이 깃든 천이 부족하대요.","언더시티 창고가 비어 가서 기부가 필요하대요.","가진 마법이 깃든 천을 기부해 달래요."}},
[7818]={a={"랄스톤 판슬레이는 천 모금 운동을 하고 있어요.","룬무늬 옷감이 아주 부족해서 도움이 절실하대요.","가능하면 룬무늬 옷감을 기부해 달래요."},c={"랄스톤은 기부한 옷감을 바로 쓸 거라며 고마워해요.","앞으로 기부하면 좋은 일을 꼭 알아봐 주겠대요."}},
[7820]={a={"럼스태그 프라우드스트라이더가 기부를 받고 있어요.","썬더 블러프의 양모 천 재고가 부족하대요.","양모 천을 가지고 있다면 지금 기부해 달래요."}},
[7821]={a={"럼스태그 프라우드스트라이더가 기부를 받고 있어요.","비단 천 재고도 역대 가장 적대요.","비단 천을 가지고 있다면 지금 기부해 달래요."}},
[7822]={a={"럼스태그 프라우드스트라이더가 기부를 받고 있어요.","마법 천이 떨어져 가서 재고를 채워야 한대요.","마법 천을 가지고 있다면 지금 기부해 달래요."}},
[7823]={a={"럼스태그 프라우드스트라이더는 천 모금 운동을 하고 있어요.","룬무늬 옷감이 아주 부족해서 도움이 절실하대요.","가능하면 룬무늬 옷감을 기부해 달래요."},c={"럼스태그는 기부한 옷감을 바로 쓸 거라며 고마워해요.","앞으로 기부하면 좋은 일을 꼭 알아봐 주겠대요."}},
[7824]={a={"라쇼나 스트랙래쉬는 천 모금 운동을 하고 있어요.","룬무늬 옷감이 아주 부족해서 도움이 절실하대요.","가능하면 룬무늬 옷감을 기부해 달래요."},c={"라쇼나는 기부한 옷감을 바로 쓸 거라며 고마워해요.","앞으로 기부하면 좋은 일을 꼭 알아봐 주겠대요."}},
[7826]={a={"라쇼나 스트랙래쉬는 오그리마를 위해 양털 천을 모으고 있어요.","양털 천을 기부하면 오그리마에서 크게 인정받는대요.","지금 가진 양털 천을 기부해 달래요."}},
[7827]={a={"라쇼나 스트랙래쉬는 비단 재고가 바닥났대요.","다른 사람들 도움으로 부족한 양을 채우려 한대요.","가지고 있는 비단 천을 지금 기부해 달래요."}},
[7828]={a={"사냥꾼 마코르는 많은 트롤들이 야생 동물에게 죽었대요.","은빛갈기늑대는 숨어 있다가 기회를 노려 습격한대요.","은빛갈기늑대를 쫓아가 처치해 달래요."}},
[7829]={a={"사냥꾼 마코르는 레반터스크 전사들을 많이 잃었대요.","포악한 올빼미야수의 발톱과 부리에 당했대요.","눈에 띄는 올빼미야수를 모두 처치해 달래요."}},
[7830]={a={"사냥꾼 마코르가 동부 내륙지의 그리핀 이야기를 해요.","와일드해머 드워프들이 그리핀을 훈련해 트롤을 죽인대요.","우두머리 뾰족부리그리핀을 처치하고 깃털을 가져와 달래요."}},
[7831]={a={"라쇼나 스트랙래쉬는 마법 옷감 재고가 부족하대요.","여러 사람의 도움으로 재고를 채우려 한대요.","가지고 있는 마법 옷감을 지금 기부해 달래요."}},
[7833]={a={"비헤나는 양털 천을 모으고 있어요.","재고가 부족해서 다른 사람들에게도 받으려 해요.","가지고 있는 양털 천을 지금 기부해 달래요."}},
[7834]={a={"비헤나는 비단 재고가 바닥났대요.","다른 사람들 도움으로 부족한 양을 채우려 한대요.","가지고 있는 비단 천을 지금 기부해 달래요."}},
[7835]={a={"비헤나는 마법 옷감 재고가 부족하대요.","여러 사람의 도움으로 재고를 채우려 한대요.","가지고 있는 마법 옷감을 지금 기부해 달래요."}},
[7836]={a={"비헤나는 그동안 많이 기부해 준 모험가에게 부탁이 있대요.","룬무늬 옷감이 가장 많이 부족해요.","남는 룬무늬 옷감이 있으면 가져와 달래요."}},
[7839]={a={"대장장이 슬래그트리의 도구를 썩은가지부족이 훔쳐 갔어요.","어릴 때 목숨을 구해 준 노움이 준 선물이래요.","그 도구를 되찾아 달라고 부탁해요."},c={"슬래그트리는 도구를 찾아서 정말 기뻐해요."}},
[7840]={a={"라드는 소풍 중에 썩은가지부족 트롤에게 맞았대요.","도망치다 점심을 북쪽 섬의 비밀 장소에 두고 왔대요.","그 점심을 다시 가져다 달래요."},c={"라드는 큰 고깃덩이를 받아 먹어 치워요.","고마워서 특별한 소풍 바구니를 만들어 준대요."}},
[7841]={a={"오토 모지코는 와일드해머 드워프들을 경계해요.","그들이 하이 엘프들과 손을 잡았나 봐요.","깊은골짜기 하이 엘프를 만나면 모두 처치해 달래요."},nx=7842,nt="Another Message to the Wildhammer"},
[7842]={a={"와일드해머 드워프들은 그리핀과 아주 가까운 사이래요.","이 관계를 이용해 또 다른 통첩장을 보내려 해요.","동부 내륙지의 그리핀을 모조리 처치하고 깃털을 모아 달래요."},c={"오토 모지코는 이 일이 잘될 거라며 기뻐해요.","한 단계만 더 하면 와일드해머도 깨닫겠대요."},nx=7843,nt="The Final Message to the Wildhammer"},
[7843]={a={"오토 모지코는 피에 젖은 긴 창을 건네요.","이 창을 맹금의 봉우리 마을 중앙 우물 옆에 콱 박으래요.","와일드해머 드워프들에게 트롤이 장난이 아니라고 보여 달래요."}},
[7844]={a={"비술사 야요진은 동부 내륙지의 트롤 부족 이야기를 해요.","썩은가지부족은 다른 트롤과 인간형 생물을 잡아먹는대요.","이 지역의 썩은가지부족을 처리해 달래요."},c={"비술사 야요진은 줄진님도 이보다 잘하기 어려웠대요."}},
[7845]={a={"주술사 쏜터스크의 남편이 썩은가지부족에게 납치됐어요.","타락한 여사제 헥스가 학카르에게 제물로 바치려 한대요.","진타알로 꼭대기에 갇힌 남편을 구해 달래요."},c={"장로 쏜터스크는 서둘러야 한다고 해요.","경비병들이 이미 알아챘을 거래요."},nx=7846,nt="Recover the Key!"},
[7846]={a={"장로 쏜터스크는 족쇄에 묶여 있어요.","족쇄를 풀 열쇠를 수호자 히타야가 가지고 있대요.","그녀를 처치하고 열쇠를 가져와 달래요."},nx=7847,nt="Return to Primal Torntusk"},
[7847]={a={"장로 쏜터스크가 아내에게 전할 말이 있대요.","그의 아내는 레반터스크 마을의 주술사 쏜터스크예요.","나도 곧 돌아갈 거라고 전해 달래요."}},
[7848]={a={"로소스 리프트웨이커는 검은바위 산의 균열을 가리켜요.","그 균열이 불의군주에게 통하는 문이래요.","검은바위 나락에서 핵 조각을 가져와 달래요."},c={"로소스 리프트웨이커는 이제 화산 심장부로 데려다줄 수 있대요."}},
[7849]={a={"사냥꾼 마코르의 쌍둥이 동생 말코르가 죽었대요.","썩은가지부족의 수액괴물과 늑대들이 유골을 훼손하고 있대요.","동생의 유골을 수습해 달래요."},c={"사냥꾼 마코르는 동생이 많이 그리울 거래요.","도와줘서 고맙다며 영웅이라고 해요."}},
[7850]={a={"썩은가지부족이 유난히 사나운 이유가 있대요.","타락한 여사제 헥스가 만든 이상한 물건 때문이래요.","진타알로에서 얼룩진 피가 담긴 용기를 가져와 달래요."},c={"주술사 쏜터스크는 어둠의 기운이 지금은 걷혔대요.","여사제를 없애도 다른 자가 곧 그 자리를 채운대요."}},
[7861]={a={"주술사 쏜터스크의 명령으로 현상 수배가 붙었어요.","타락한 여사제 헥스와 그녀의 부하들이 대상이에요.","헥스와 아만자시 정예 경비병을 해치우면 큰 상금을 준대요."},c={"주술사 쏜터스크는 썩은가지부족에게 큰 타격이라고 해요.","큰 보상을 받을 거래요."}},
[7862]={a={"레반터스크 경비대장 말코르가 죽어 자리가 비었어요.","그 자리를 맡고 싶다면 시험을 통과해야 해요.","통과 후 주술사 쏜터스크에게 신청서를 내라고 해요."}},
[7877]={a={"셴드랄라 고대인이 도서관 이야기를 해요.","계단 밑에 오래된 궤짝이 있대요.","그 안에서 원하는 것을 골라 가래요."}},
[8042]={a={"파괴자 진로크가 당신의 부적을 강화해 준대요.","학카르는 줄구룹 밖으로 나오면 안 된대요.","부적을 맡겨 무감바의 힘을 더해 달래요."},nx=8043,nt="Strength of Mount Mugamba"},
[8043]={a={"파괴자 진로크가 돌아온 당신을 반가워해요.","몰소르가 당신의 활약을 왕에게 알렸대요.","부적을 맡겨 힘을 한 번 더 키워 달래요."},nx=8044,nt="The Rage of Mugamba"},
[8044]={a={"파괴자 진로크가 잔달라 밖 사람에겐 없던 영예래요.","왕이 당신에게 안부를 전했대요.","부적을 맡겨 무감바의 분노를 한 번 더 강화해 달래요."}},
[8050]={a={"천리안 알타빔이 줄다자르의 눈에 힘이 맥동한대요.","이제 다음 단계로 나아갈 준비가 됐대요.","부적을 맡기면 눈에 힘을 불어넣겠대요."},c={"알타빔이 굳건히 임하라고 해요.","적이 당신의 살려는 의지를 빨아들이려 할 거래요."},nx=8051,nt="The Eye of Zuldazar"},
[8051]={a={"천리안 알타빔이 구루바시와 싸운 당신 소문을 들었대요.","왕족들도 당신의 활약을 얘기하기 시작했대요.","이제 부적을 주면 눈에 힘을 불어넣겠대요."},nx=8052,nt="The All-Seeing Eye of Zuldazar"},
[8052]={a={"천리안 알타빔이 당신 같은 사람이 더 있었으면 한대요.","학카르의 군대도 눈 깜짝할 새 흩어질 거래요.","이제 줄다자르의 천리안을 알타빔에게 맡겨 달래요."},c={"알타빔이 적들을 모두 무찌르라고 해요."}},
[8056]={a={"줄다자르의 메이위키는 점술사의 통찰을 높이 평가해요.","점술사는 뼈나 잎을 읽어 통찰을 얻는대요.","줄구룹에서 고대 학카리 어깨갑옷을 가져다 달래요."},c={"메이위키가 당신에게 점술사의 기질이 있대요.","부족이 줄구룹 활약을 알고 친구로 여긴대요.","그 대가로 팔보호구를 건네요."}},
[8057]={a={"줄다자르의 메이위키는 제사장이 부족의 핵심이래요.","제사장은 동물과 교감해 하늘의 뜻을 전한대요.","줄구룹에서 고대 학카리 손목갑옷을 가져다 달래요."},c={"메이위키는 마력의 보물에서 힘이 느껴진대요.","당신은 부족이 친구로 부를 사람이 됐대요.","약속대로 제사장의 팔보호구를 건네요."}},
[8058]={a={"파괴자 진로크는 부족을 위해 응징할 구원자를 찾아요.","부족에게 적이 많아 어떤 죄도 그냥 넘기지 않는대요.","줄구룹에서 고대 학카리 어깨갑옷을 가져다 달래요."},c={"진로크가 오늘 많은 복수를 했다고 칭찬해요.","학카르의 졸개들을 무릎 꿇렸다고 해요.","잔달라의 친구가 됐다며 상을 줘요."}},
[8059]={a={"천리안 알타빔은 악마주의자의 힘에 대해 말해요.","악마를 노예로 삼는 건 소수만 해낼 수 있대요.","줄구룹에 가서 힘의 귀감을 찾아 오라고 해요."},c={"천리안 알타빔은 잘했다며 이걸 받으라고 해요.","악마를 불러내는 데 쓰는 강한 마력으로 만들었대요."}},
[8060]={a={"천리안 알타빔이 부족의 마법사를 환영술사라고 소개해요.","환영술사는 강한 마력으로 적을 혼란시킨대요.","줄구룹에서 고대 학카리 팔보호구를 가져다 달래요."},c={"알타빔이 마력이 흐르는 걸 느꼈냐고 물어요.","그 보물은 구루바시 제국 때 화폐처럼 쓰였대요.","학카르의 재림에 맞서 그 마력을 쓸 거래요."}},
[8061]={a={"천리안 알타빔은 사제가 단순한 치유사가 아니래요.","성자는 부족 사이에서 재판관 노릇을 하며 악을 막는대요.","줄구룹에서 고대 학카리 손목갑옷을 가져다 달래요."}},
[8062]={a={"장님 팔디르는 수렵꾼들이 부족을 먹여 살렸다고 해요.","줄구룹에서 사냥하면 당신의 실력이 드러난대요.","줄구룹에서 고대 학카리 팔보호구를 가져다 달래요."},c={"팔디르는 마력의 보물이 느껴진다고 해요.","당신의 성과에 부족 많은 이들이 감명받았대요.","그래서 수렵꾼의 팔보호구를 가질 자격이 있대요."}},
[8063]={a={"장님 팔디르는 잔달라 개혁가들이 적 사이에 혼란을 뿌렸대요.","개혁가들은 광기와 혼돈을 기꺼이 받아들인대요.","줄구룹에서 고대 학카리 어깨갑옷을 가져다 달래요."}},
[8064]={a={"줄다자르의 메이위키는 잔달라 부족 사람이에요.","자연과 가장 잘 맞는 건 제사장이라고 해요.","줄구룹의 마력 보물을 가져오면 허리띠를 준대요."},c={"메이위키는 가져온 것의 숨은 힘이 보물이래요.","부족에게 명예로운 사람이라고 칭찬해요.","약속대로 보상을 준대요."}},
[8065]={a={"줄다자르의 메이위키가 제사장의 옷을 말해요.","튜닉은 제사장을 천상의 지혜와 이어 준대요.","줄구룹의 마력 보물을 가져오면 튜닉을 준대요."},c={"메이위키는 필요한 보물을 다 모은 걸 놀랍다고 해요.","이제 잔달라 부족에게 존경받게 됐대요.","약속한 튜닉을 준대요."}},
[8066]={a={"장님 팔디르는 잔달라 포식자 이야기를 해요.","줄구룹에서 힘의 귀감 부품을 가져다 달래요.","그러면 잔달라 포식자의 허리띠를 준대요."},c={"팔디르는 가져온 것에서 힘이 느껴진대요.","그 힘이 학카르에 맞서는 데 쓰인대요.","존경받을 만하니 허리띠를 입으래요."}},
[8067]={a={"장님 팔디르는 잔달라 수렵꾼의 장비를 말해요.","어깨보호대는 몸을 숨기고 드러내게도 해 준대요.","줄구룹의 마력 보물을 가져오면 그걸 준대요."},c={"팔디르는 해냈다고 인정해요.","가장 무서운 포식자처럼 해냈으니 어깨보호대를 입으래요."}},
[8068]={a={"천리안 알타빔은 마력과 환영술에 대해 말해요.","환영술은 강한 마력을 다루는 한 방법이래요.","줄구룹의 마력 보물을 가져오면 어깨보호대를 준대요."},c={"알타빔은 이제 부족에게 명예롭대요.","줄구룹이 당신 덕에 잔달라의 힘을 맛봤대요.","잔달라 환영술사의 어깨보호대를 받아 가래요."}},
[8069]={a={"천리안 알타빔은 잔달라가 장비로 지위를 나타낸대요.","전설에 따르면 환영술사 로브는 늘 모습이 달라요.","줄구룹에서 마력 보물을 가져와 존경을 얻으래요."},c={"알타빔은 드디어 로브를 입을 자격이 있는 자가 나왔대요.","줄구룹에서 성공해 부족의 존경을 얻었대요.","자랑스럽게 입으라고 해요."}},
[8070]={a={"천리안 알타빔은 부족을 지킨 성자들 얘기를 해요.","성자들은 부족에 해를 끼치던 자들을 쫓아냈대요.","줄구룹에서 마력의 보물을 가져다 달래요."},c={"알타빔은 이 보물들이 큰 힘이 된다고 해요.","학카르가 부족을 무너뜨리지 못하게 됐대요.","감사의 뜻으로 이걸 받아 가래요."}},
[8071]={a={"천리안 알타빔은 잔달라 성자들을 말해요.","그 어깨보호대는 부족의 보호자임을 증명해요.","줄구룹에서 싸워 마력 보물을 가져오면 어깨보호대를 준대요."},c={"알타빔은 학카르의 졸개들이 벌을 받았대요.","당신은 부족에게 영원히 존경받게 됐대요.","성자의 어깨보호대를 받아 가래요."}},
[8072]={a={"장님 팔디르는 전설의 개혁가 카르바살을 말해요.","카르바살은 광기의 옷감으로 짠 어깨보호대를 썼대요.","줄구룹의 마력 보물을 가져오면 그런 어깨보호대를 준대요."},c={"팔디르는 당신이 퍼뜨린 광기 덕에 이겼대요.","잔달라에게 존경받게 됐대요.","그래서 광기의 어깨보호대를 준대요."}},
[8073]={a={"장님 팔디르는 눈이 멀었지만 아쉽지 않대요.","잔달라의 강한 장비는 눈에 안 보이는 힘을 내뿜어요.","줄구룹의 마력 보물을 가져오면 튜닉을 준대요."},c={"팔디르는 놀랍다고 칭찬해요.","당신의 존경은 평생 보장됐대요.","광기의 튜닉을 입을 자격이 생겼대요."}},
[8074]={a={"줄다자르의 메이위키는 잔달라 오거들을 말해요.","오거들은 원소의 마력으로 부족을 영광으로 이끈대요.","줄구룹의 마력 보물을 가져오면 허리띠를 준대요."},c={"메이위키는 쓰러뜨린 악의 냄새가 난다고 해요.","보물을 가져오는 게 쉬운 일이 아니었대요.","오거의 허리띠를 가져가래요."}},
[8075]={a={"줄다자르의 메이위키가 오거들의 호버크를 말해요.","호버크는 신성과 권위를 상징하는 옷이래요.","줄구룹의 마력 보물을 가져오면 호버크를 준대요."},c={"메이위키는 당신이 겪은 일을 안다고 해요.","악을 물리치고 잔달라에게 존경받게 됐대요.","오거의 호버크를 자랑스럽게 입으래요."}},
[8076]={a={"천리안 알타빔은 힘을 완전히 구현하려 해요.","적을 막으려면 그 힘은 치를 가치가 있대요.","줄구룹에서 힘의 보물을 얻어 오래요."},c={"천리안 알타빔은 구루바시가 힘에 삼켜졌다고 해요.","이걸 잔달라 부족의 명예 동맹으로 쓰면 도움이 된대요."}},
[8077]={a={"천리안 알타빔은 권력의 궁극적 상징인 전투 장비를 말해요.","그 로브는 룬무늬 옷감과 강한 마력을 합쳐 만든대요.","줄구룹에서 고대 학카리 조끼를 구해 달래요."},c={"천리안 알타빔은 줄구룹에서 이겨 학카르가 이기지 못할 거래요.","언젠가 혈신과 맞설 때 잔달라 부족에게 존경받을 거래요.","이 로브도 도움이 될 거래요."}},
[8078]={a={"파괴자 진로크는 트롤의 옛 영광이 학카르 탓이래요.","학카르가 구루바시 제국을 안에서 무너뜨렸대요.","줄구룹에서 마력 보물을 가져와 복수하래요."},c={"진로크는 당신이 부족과 자신에게 명예를 가져왔대요.","적에게 고통을 줘서 구원자의 길을 알게 됐대요.","구원자의 허리띠는 이제 당신 것이래요."}},
[8079]={a={"파괴자 진로크는 구원자의 흉갑을 권력의 상징이라 해요.","구원자가 된다는 건 곧 복수가 된다는 뜻이래요.","줄구룹의 마력 보물을 가져오면 흉갑을 준대요."},c={"진로크는 당신의 공을 존경한다고 해요.","줄구룹이 잔달라의 복수를 맛봤대요.","사람들이 당신을 복수의 상징으로 볼 거래요."}},
[8102]={a={"천리안 알타빔은 당신이 돌아와서 반가워해요.","당신 능력으로 적이 많이 쓰러져서 자갈이 많이 쓰였대요.","이제 자갈을 강하게 해야 해서 건네 달래요."},c={"알타빔은 카자로의 용암 전선처럼 막을 수 없게 되래요."},nx=8103,nt="The Pebble of Kajaro"},
[8103]={a={"학카리 사람들이 당신을 두려워한대요.","카자로의 힘으로 그들을 불태웠대요.","알타빔이 자갈을 더 강하게 하려고 부적을 달래요."},c={"알타빔은 줄구룹의 트롤들을 계속 쓰러뜨리래요.","학카르가 세상이 굴복하지 않는다는 걸 알게 하래요."},nx=8104,nt="The Jewel of Kajaro"},
[8107]={a={"잔달라 트롤들 사이에서는 명예를 얻어야 한대요.","명예에는 보상과 우정, 동맹이 따른대요.","알타빔이 부적의 힘을 높여 준다며 건네 달래요."},c={"알타빔은 어둠에서 힘을 끌어내라고 해요.","케잔의 타락이 당신의 어둠의 힘을 보태 준대요."},nx=8108,nt="Kezan's Taint"},
[8108]={a={"알타빔이 부적을 다시 강화해 준대요.","학카르와 그 졸개들을 계속 무찌르길 바란대요.","그러니 부적을 건네 달래요."},nx=8109,nt="Kezan's Unstoppable Taint"},
[8109]={a={"알타빔이 부적에 마지막 강화를 하려 해요.","케잔의 타락으로 악마를 불러 전장에서 부리래요.","그러니 부적을 건네 달래요."},c={"알타빔은 적의 공포에서 힘을 끌어내라고 해요.","그림자가 학카리를 삼키는 걸 보래요.","케잔의 타락이 그 힘을 키워 준대요."}},
[8111]={a={"메이위키가 당신을 다시 만나 반가워해요.","몰소르가 부적에 마력을 더하라고 했대요.","부적을 건네면 메이위키가 더 좋게 만든대요."},c={"메이위키는 부적을 피우지 말고 악과 싸우래요."},nx=8112,nt="Enchanted South Seas Kelp"},
[8112]={a={"메이위키가 부적을 살펴보고 마력을 더하려 해요.","시든 잎에 활기를 더해야 한대요.","부적을 건네면 메이위키가 고쳐 준대요."},c={"메이위키는 줄구룹의 악한 트롤들에게 자연의 힘을 보이래요."},nx=8113,nt="Pristine Enchanted South Seas Kelp"},
[8113]={a={"메이위키가 오랜만에 당신을 만나 반가워해요.","King Rastakhan이 마지막 마력을 더하라 명령했대요.","그러니 부적을 건네 달래요."},c={"메이위키는 좋은 여정이었다고 칭찬해요.","학카르와 그 졸개들을 계속 무찌르래요."}},
[8117]={a={"메이위키는 당신이 정령의 힘으로 싸웠다고 들었대요.","부드리스의 환영을 더 선명하게 해 준대요.","그러니 구슬을 건네 달래요."},nx=8118,nt="Vision of Voodress"},
[8118]={a={"몰소르가 요즘 당신을 칭찬한대요.","당신이 잔달라의 진짜 영웅이 되고 있대요.","구슬을 건네면 메이위키가 더 밝게 해 준대요."},c={"메이위키는 이제 환영이 더 또렷해질 거래요.","원시의 힘이 당신을 통해 흐르게 하래요."},nx=8119,nt="The Unmarred Vision of Voodress"},
[8119]={a={"메이위키가 당신의 구슬을 가리키며 말해요.","구슬이 살아난 것처럼 정령들이 주위를 돌아요.","마지막 손질을 위해 구슬을 건네 달래요."},c={"메이위키는 언젠가 이 구슬로 자기와 직접 대화할 수 있대요.","학카르와의 싸움이 끝나면 메이위키는 집에 간대요."}},
[8120]={a={"죽음의경비대장 드와이어는 아라소르 연맹이 대규모 병력을 보냈대요.","얼라이언스가 식량과 자원을 노린대요.","금광, 제재소, 대장간, 마구간을 공격해 달래요."}},
[8121]={a={"죽음의경비대장 드와이어가 자네 활약을 많이 들었대요.","연맹의 세력을 꺾을 때가 왔대요.","전략 요충지를 동시에 점령해 달래요."}},
[8122]={a={"죽음의경비대장 드와이어는 연맹 결의가 약해진 것 같대요.","아라시 분지에서 전면전을 시작하래요.","모든 전략 요충지를 점령해 달래요."}},
[8142]={a={"팔디르는 당신이 학카리를 셀 수 없이 쓰러뜨렸다고 해요.","그림자 부적이 도왔을 것 같대요.","부적을 건네면 힘을 높여 준대요."},c={"팔디르는 부적에 남은 강화가 하나뿐이래요.","때가 되면 그 강화를 해 주겠대요."},nx=8143,nt="Zandalarian Shadow Talisman"},
[8143]={a={"팔디르는 당신이 쓰러뜨리는 재주가 대단하다고 해요.","몰소르도 당신이 잔달라를 위해 한 일을 안대요.","부적을 건네면 힘을 한 번 더 높여 준대요."},nx=8144,nt="Zandalarian Shadow Mastery Talisman"},
[8144]={a={"팔디르는 부적이 더 강해지고 싶어 한대요.","줄구룹에 쓰러진 트롤들이 부적의 힘이 됐대요.","팔디르가 마지막 강화를 하니 부적을 건네 달래요."},c={"팔디르는 이번이 마지막 대화라고 해요.","부적을 가져가 계속 무찌르래요.","학카르는 줄구룹을 떠나선 안 된대요."}},
[8146]={a={"팔디르는 당신이 적에게 큰 고통을 줬다고 해요.","학카르의 무리가 당신 이름을 분노로 외친대요.","부적을 건네면 덩굴손을 더 엮어 준대요."},c={"팔디르는 이제 딱 한 번만 더 엮을 수 있대요.","그 뒤로는 더 엮을 수 없대요."},nx=8147,nt="The Maelstrom's Tendril"},
[8147]={a={"팔디르는 멀리서도 당신의 사격 소리가 들린대요.","잔달라 트롤들 사이에서 당신 이름이 유명해졌대요.","부적을 건네면 한 번 더 엮어 준대요."},c={"팔디르는 적들이 당신의 화력 끝에서 속죄하길 바란대요."},nx=8148,nt="Maelstrom's Wrath"},
[8148]={a={"몰소르가 King Rastakhan의 말을 전했대요.","왕실이 당신이 학카리 무리를 무찌른 일에 감탄했대요.","부적을 건네면 마지막으로 엮어 준대요."},c={"팔디르는 당신의 여정이 이제 막 시작됐대요.","언젠가 소용돌이에 가서 세상의 중심을 보래요.","힘과 인내를 빈대요."}},
[8151]={a={"아즈샤라의 오그틴크가 노련한 사냥꾼을 모집해요.","오그틴크는 부족을 떠나 세나리온 의회를 도왔대요.","그를 찾아가 얘기해 보래요."},c={"오그틴크는 이제 사냥보다 가르치는 게 목적이래요.","쓰러뜨린 사냥감의 전리품으로 부적을 함께 만들자고 해요.","부적은 자기가 갖고 대신 다른 걸 준대요."},nx=8153,nt="Courser Antlers"},
[8153]={a={"오그틴크는 순록의 뿔이 가장 강하다고 해요.","완전한 순록 뿔은 최고의 자신감의 증표래요.","덩치 큰 이끼발굽순록을 잡아 뿔을 가져오래요."},c={"오그틴크는 이걸 얻으려면 날카로운 눈과 인내가 필요했다고 해요.","잘했다고 칭찬해요."},nx=8231,nt="Wavethrashing"},
[8169]={a={"죽음의경비대장 드와이어는 아라소르 연맹이 대규모 병력을 보냈대요.","얼라이언스가 식량과 자원을 노린대요.","금광, 제재소, 대장간, 마구간을 공격해 달래요."},c={"죽음의경비대장 드와이어는 파멸단 정찰병에게서 성공 보고를 받았대요.","얼라이언스의 확장을 막으면 승리가 확실해진대요."}},
[8170]={a={"죽음의경비대장 드와이어가 해머폴에 있어요.","얼라이언스가 아라시 분지의 자원을 노리고 병력을 보낸대요.","금광, 제재소, 대장간, 마구간을 공격하고 오라 해요."},c={"정찰병이 와서 당신의 성공을 알려 줬대요.","아라시 분지를 지키려면 얼라이언스 확장을 막아야 한대요."}},
[8171]={a={"죽음의경비대장 드와이어가 해머폴에 있어요.","얼라이언스가 아라시 분지의 자원을 노리고 병력을 보낸대요.","금광, 제재소, 대장간, 마구간을 공격하고 오라 해요."},c={"정찰병이 와서 당신의 성공을 알려 줬대요.","아라시 분지를 지키려면 얼라이언스 확장을 막아야 한대요."}},
[8181]={a={"발굴조사단장 아이언부트가 모쉬아루 서판을 조사했대요.","학카르는 그 알을 통해 다시 태어날 수 있대요.","예킨야에게 가서 그 알을 내놓으라고 하래요."},c={"예킨야는 서판을 찾아낸 걸 알고 있대요.","이미 늦었고 학카르가 줄구룹에서 다시 태어났대요.","도움 덕에 영혼의 약탈자가 빨리 돌아왔대요."},nx=8182,nt="The Hand of Rastakhan"},
[8182]={a={"발굴조사단장 아이언부트는 우려하던 일이 벌어졌대요.","잔달라 부족 사절들이 요잠바 섬에서 야영하고 있대요.","지도자 몰소르를 찾아가 학카르를 물리칠 방법을 묻래요."},c={"몰소르는 아이언부트가 보냈냐고 물어요.","잔달라 트롤들이 영혼의 약탈자를 이길 방법을 알지도 모른대요."}},
[8183]={a={"학카르의 심장 안에서 열기가 타오르고 있어요.","영혼의 약탈자를 물리쳤지만 힘의 핵이 아직 남았대요.","이 심장을 요잠바 섬의 몰소르에게 가져가 달래요."},c={"몰소르는 영혼의 약탈자가 죽었다며 기뻐해요.","이 땅의 영웅이라고 해요."}},
[8193]={a={"리글 바스베이트는 매주 일요일에 낚시 대회를 열어요.","가장 먼저 Tastyfish를 가져오면 Master Angler가 돼요.","Tastyfish는 금방 상하니 다음 주까지 두지 말래요."},c={"리글은 몇 시간을 굶었다며 빨리 달래요.","Master Angler가 되고 싶다면 서두르래요."}},
[8201]={a={"엑잘은 학카르가 줄구룹에서 신들의 힘을 얻고 있대요.","매혹된 대사제들이 신성한 힘을 학카르에게 쏟아붓는대요.","그 대사제들의 머리카락을 신성한 굴레에 묶어 와 달래요."},c={"엑잘은 신들의 힘을 빼앗기는 걸 막았대요.","학카르의 힘도 약해졌대요."}},
[8227]={a={"미끼와 낚시 도구 사이에 비단 줄자가 있어요.","꼬리표에 내트 페이글과 먼지진흙 습지대가 적혀 있어요.","내트의 줄자를 내트 페이글에게 돌려줘 달래요."},c={"내트 페이글은 가장 아끼던 줄자를 찾아서 기뻐해요.","줄구룹에서 이 줄자를 잃어버렸고, 가즈란카를 봤냐고 물어요."}},
[8231]={a={"폭풍히드라는 아즈샤라에만 사는 강한 짐승이래요.","단단하고 반짝이는 비늘은 사냥꾼의 힘을 닮았대요.","아즈샤라 해안의 폭풍히드라를 사냥해 비늘을 가져다 달래요."},nx=8232,nt="The Green Drake"},
[8232]={a={"오그틴크가 녹색 비룡 몰파즈를 처치하라고 해요.","몰파즈는 슬픔의 늪 아탈학카르 신전 깊숙이 산대요.","혼자 가면 안 되니 함께 싸울 사람을 찾으래요."}},
[8234]={a={"조라크 라벤홀트 경이 작은 파란 가방을 잃어버렸대요.","도둑들이 가방을 못 열자 나무구렁일족 주술사에게 팔았대요.","아즈샤라에서 가방을 되찾아 대마법사 실렘에게 주래요."},nx=8235,nt="Encoded Fragments"},
[8235]={a={"라벤홀트 경이 가방의 마법을 없애 달라고 했대요.","실렘의 마법 무효화 책을 야만인들이 부숴 버렸대요.","숲수액괴물을 잡아 암호화 조각을 모아 오래요."},c={"실렘은 좋은 조각을 골라 왔다고 해요.","그래도 쓸모없진 않을지 모른대요."},nx=8236,nt="The Azure Key"},
[8236]={a={"대마법사 실렘이 가방에 걸린 마법을 풀고 있대요.","하늘색 열쇠는 몰파즈라는 녹색 용이 갖고 있대요.","동료와 함께 몰파즈의 소굴에 가서 열쇠를 얻어 달래요."}},
[8240]={a={"빈차샤는 학카리 장신구 파괴가 아주 중요하대요.","외부인도 이 일을 해 주면 환영한대요.","줄구룹의 장신구를 잔자의 제단에서 부숴 달래요."},c={"빈차샤는 장신구를 하나씩 부술수록 승리가 가까워진대요.","부술 때마다 명예 징표를 받을 수 있대요."}},
[8249]={a={"파라드는 제 도적들이 자물쇠 따는 실력을 키워야 한대요.","지금 자물쇠는 너무 쉬워서 훈련에 못 쓴대요.","무거운 상자를 가져오면 던지는 비수를 준대요."},c={"파라드는 비수가 누군가의 마음에 꽂히길 바란대요."}},
[8250]={a={"마지노르 뒤마는 대마법사 실렘이 사람을 찾는다고 전해요.","탑은 절벽 꼭대기라 순간이동으로만 올라간대요.","아즈샤라에서 사나스 림요를 찾아 달래요."},c={"사나스는 비웃으며 실렘이 당신을 기다린다고 해요."}},
[8251]={a={"대마법사 실렘은 블러드 엘프에게 화가 나 있어요.","보낸 수습생이 블러드 엘프에게 살해당했대요.","블러드 엘프에게서 반짝이는 가루를 얻어 오래요."},c={"실렘은 잘했다며 마법 화살의 위력을 칭찬해요."},nx=8252,nt="The Siren's Coral"},
[8252]={a={"대마법사 실렘의 연구에 쓸 산호가 거의 없대요.","원한의꼬리일족이 산호를 노리고 해변을 침략했대요.","세이렌에게서 마력 깃든 산호를 빼앗아 달래요."},c={"실렘은 산호가 훌륭하다며 당신 솜씨를 칭찬해요.","진짜 시험을 받을 자격이 있을지도 모른대요."},nx=8253,nt="Destroy Morphaz"},
[8253]={a={"대마법사 실렘의 수습생이 몰파즈에게 통째로 삼켜졌대요.","그 수습생은 크고 질 좋은 신비의 결정을 갖고 있었대요.","몰파즈를 쓰러뜨리고 결정을 꺼내 와 달래요."},c={"실렘은 결정이 용의 힘을 빨아들여 자랐다며 놀라요.","이제 실렘의 마법 제작 능력이 돌아왔대요.","첫 작품은 당신 것이니 고르라고 해요."}},
[8254]={a={"수사 조슈아는 세나리온 의회가 도움을 절실히 필요로 한대요.","도움을 줄 오그틴크는 아즈샤라 절벽 위에 있대요.","그를 찾아가 의회의 어려움을 도와 달래요."},c={"오그틴크는 당신이 와서 짐을 덜었다고 해요.","이제 할 일이 많다고 해요."},nx=8255,nt="Of Coursers We Know"},
[8255]={a={"아즈샤라의 이끼발굽순록은 한때 악령의 숲에 살았대요.","악령의 숲을 치유할 연고의 재료가 필요하대요.","건강한 순록의 분비샘을 구해 와 달래요."},nx=8256,nt="The Ichor of Undeath"},
[8256]={a={"오그틴크는 회복 연고를 만들 재료를 모으고 있대요.","독 재료는 강한 언데드의 불사의 영액이래요.","그 영액을 구해서 오그틴크에게 가져다 달래요."},c={"오그틴크는 끔찍한 물질이라 기쁘진 않지만 필요하대요.","필요한 악이라며 고맙다고 해요."},nx=8257,nt="Blood of Morphaz"},
[8257]={a={"오그틴크는 회복 연고의 마지막 재료를 구하고 있대요.","몰파즈는 모든 독과 병에 면역이라 그 피가 필요하대요.","몰파즈를 처치하고 그 피를 그레타에게 가져가 달래요."},c={"너무 기쁜 소식이라 그레타는 믿기지 않는대요.","이제 악령의 숲의 나무와 동물을 치유할 수 있대요.","평생 걸리겠지만 방법을 주었다며 고마워해요."}},
[8258]={a={"사고른 크레스트스트라이더는 다크리버를 막으려 해요.","다크리버가 영혼의 세계를 자기 뜻대로 비틀려 한대요.","스칼로맨스에서 다크리버를 쓰러뜨리고 증거를 가져와 달래요."},c={"다크리버가 쓰러지면 영혼의 세계가 안정될 거래요.","요구한 것보다 훨씬 많이 해 줬다고 칭찬해요.","작은 선물을 받아 달라고 해요."}},
[8276]={a={"세나리온 사절 블랙후프가 호드 용사들을 부르고 있어요.","실리시드 집 근처 땅이 떨려서 녀석들이 움직이는 것 같대요.","실리더스의 세나리온 요새에서 바람소환사 프라우드혼을 찾아가래요."},c={"바람소환사 프라우드혼은 새 용사가 왔다며 반겨요.","세나리온 요새에서 도울 일이 많대요."},nx=8280,nt="Securing the Supply Lines"},
[8277]={a={"비틱스 픽클스프라그의 사촌 노글이 독에 중독됐어요.","노글은 북쪽에서 돌아와 돌꼬리전갈이나 모래그물 바위거미에게 쏘였을 거래요.","그 독침과 송곳니를 가져다 달래요."},c={"비틱스는 노글을 살릴 수 있기를 바란대요."},nx=8278,nt="Noggle's Last Hope"},
[8278]={a={"비틱스 픽클스프라그의 해독약이 노글에게 효과가 없었대요.","노글은 남쪽의 더 독한 생물에게 물린 게 분명하대요.","이번에는 여러 종류의 독 견본을 가져다 달래요."},c={"비틱스는 노글이 정신을 차리고 있어서 기뻐해요.","큰 신세를 졌다고 고마워해요."},nx=8282,nt="Noggle's Lost Satchel"},
[8279]={a={"은둔자 오르텔은 황혼의망치단에서 탈영한 사람이에요.","황혼의망치단이 지금도 그를 쫓고 있대요.","황혼의 사전을 찾아 오르텔에게 가져다 달래요."},c={"오르텔은 사전 조각이 맞다며 반가워해요.","그런데 해독 순서를 거꾸로 썼는지 되묻고 있어요."},nx=8287,nt="A Terrible Purpose"},
[8280]={a={"바람소환사 프라우드혼은 세나리온 요새를 지키고 있어요.","수송대가 작살미늘벌레 떼에게 자꾸 습격당해요.","보급로를 지키려고 작살미늘벌레를 해치워 달래요."},c={"프라우드혼이 진심으로 고마워해요.","요새를 돕는 데 보인 용기를 칭찬해요."},nx=8281,nt="Stepping Up Security"},
[8281]={a={"바람소환사 프라우드혼은 보급로가 아직 불안하대요.","작살미늘벌레가 사라져도 망치미늘벌레가 올 거래요.","그래서 망치미늘벌레를 막는 일도 도와 달래요."},c={"프라우드혼이 든든한 동맹이라며 칭찬해요.","실리시드와의 전쟁을 준비하는 데 도움이 됐대요."}},
[8282]={a={"노글 픽클스프라그는 아직 몸이 회복되지 않았어요.","도망치다 가방을 잃어버렸는데 재료가 가득 들어 있어요.","가방을 찾아 세나리온 요새의 노글에게 가져다 달래요."},c={"노글이 가방을 되찾아서 기뻐해요.","희귀한 재료도 다 있어 오래 신세를 지겠대요."}},
[8283]={a={"난폭한 전갈 죽음의 갈고리가 현상 수배됐어요.","남부 산맥으로 옮겨 가 탐험하는 사람들이 위험해졌대요.","처치한 뒤 집게발을 경비대장 비쉬 코주스에게 가져가래요."},c={"죽음의 갈고리가 사라져 남부 산맥을 쓸 수 있게 됐대요.","실리시드 둥지를 피해 가는 길로 쓸 수 있어 고맙대요."}},
[8284]={a={"지질학자 락스베인은 옛 야영지에서 서판 조각을 찾았어요.","조각이 너무 적어서 서판을 맞출 수가 없대요.","남은 서판 조각을 찾아 달라고 부탁해요."},c={"낱말은 읽히는데 뜻이 통하지 않는대요.","황혼의망치단이 암호를 쓰기도 해서 전문가를 찾아야 한대요."},nx=8285,nt="The Deserter"},
[8285]={a={"지질학자 락스베인은 서판을 풀 방법을 찾고 있어요.","황혼의망치단에서 탈영한 오르텔이 숨어 산다는 소문이 있어요.","복원한 서판을 들고 오르텔을 찾아가 달래요."},c={"오르텔은 그대가 옛 조직을 안다며 말을 걸어요.","서로 도울 수 있을지도 모른다며 가까이 오래요."},nx=8279,nt="The Twilight Lexicon"},
[8286]={a={"흐르는 모래의 바리스톨스는 죽을 뻔하다 살아났어요.","주인이 살려 준 뒤로 그 곁을 지키는 감시자가 됐대요.","타나리스 시간의 동굴에서 주인이 돌아왔는지 봐 달래요."},c={"위대한 분이 깨어났다며 확인해 줘요.","이제 감시자의 임무가 끝났대요."},nx=8288,nt="Only One May Rise"},
[8287]={a={"은둔자 오르텔이 세나리온 의회 군대 소식을 봤대요.","그 군대가 실리더스에 와서 황혼의망치단을 쫓으려는 것 같대요.","이 양피지를 지휘관 마랄리스에게 전해 달래요."},c={"마랄리스는 이 정보가 흥미롭다며 고마워해요.","황혼의망치단과 싸우는 데 큰 도움이 될 거래요."}},
[8288]={a={"흐르는 모래의 바리스톨스는 영웅을 찾고 있어요.","검은바위의 지배자 소굴에 용기대장 래쉬레이어가 있대요.","그 머리를 가져다 주면 여정을 이어 갈 수 있대요."},c={"천 년 만에 청동 용혈족의 총애를 받을 사람이냐고 물어요."},nx=8301,nt="The Path of the Righteous"},
[8301]={a={"노즈도르무 혈족은 약한 종족을 쉽게 믿지 않아요.","하이브아쉬, 하이브조라, 하이브레갈에서 실리시드가 극성이래요.","실리시드 등껍질 조각을 가득 모아 오라고 해요."},c={"이제 그대는 혼자가 아니라며 힘을 실어 줘요.","다른 이에게 임무를 맡길 권한도 준대요."},nx=8303,nt="Anachronos"},
[8303]={a={"바리스톨스는 그동안 많은 것을 숨겨 미안하대요.","주위에 적이 많아서 함부로 말할 수 없었대요.","마법책을 익힌 뒤 아나크로노스를 찾아가 달래요."},c={"Kalimdor의 희망이라고 칭찬해요."},nx=8305,nt="Long Forgotten Memories"},
[8304]={a={"지휘관 마랄리스의 아내 여군주 나탈리아가 실종됐어요.","마지막으로 남쪽 브론즈비어드 야영지로 가는 걸 봤대요.","드워프들에게 그녀의 행방을 물어봐 달래요."},c={"마랄리스는 살았든 죽었든 그녀를 찾아야 한대요.","요새 임무 때문에 못 떠나서 다시 도와 달래요."},nx=8306,nt="Into The Maw of Madness"},
[8305]={a={"아나크로노스가 실리더스의 수정의 눈물을 말해 줘요.","흐르는 모래의 전쟁 때 입은 큰 피해를 보여 주는 상징이래요.","그 수정의 눈물을 찾아 깊이를 들여다보라고 해요."},c={"수정에서 엄청난 슬픔이 느껴져요.","힘이 너무 세서 슬픔에 쓰러질 것 같대요."},nx=8519,nt="A Pawn on the Eternal Board"},
[8306]={a={"마랄리스는 여군주 나탈리아 마랄리스를 찾아 달래요.","정보로는 그녀가 하이브레갈에 있대요.","그녀가 정말 미쳤다면 해야 할 일을 하래요."},c={"마랄리스는 가슴을 움켜쥐며 C'Thun이 뭐냐고 물어요.","그 악마가 나탈리아를 괴물로 바꿨냐며 충격에 빠졌어요."}},
[8307]={a={"캘랜드라스는 사막 생활이 힘들어 음식이 그리워요.","황혼의망치단이 미늘벌레를 먹는데 고기가 써서 요리법이 궁금하대요.","주둔지에 가서 조리법 정보를 알아 와 달래요."},c={"책에는 평범한 요리법과 특이한 요리법이 있어요.","그중 미늘벌레 고기 요리법이 눈에 띄어요."},nx=8313,nt="Sharing the Knowledge"},
[8308]={a={"브란 브론즈비어드가 남긴 편지예요.","브란의 동료 대부분이 죽고 그는 안퀴라즈로 가는 길을 찾았대요.","편지를 브론즈비어드 야영지의 친구에게 전해 달래요."},c={"이 편지로 많은 게 설명된대요.","안퀴라즈 길을 찾으면 브란을 살펴보라고 해요."}},
[8309]={a={"곤충 집에서 실리시드가 자꾸 쏟아져 나온대요.","상형 문자가 새겨진 수정과 관계가 있을 것 같대요.","각 곤충 집의 수정 탁본을 떠 와 달래요."}},
[8310]={a={"프랭칼 스톤브리지는 상형 문자를 쉽게 읽을 약을 만들려 해요.","그러려면 실리시드의 뇌가 필요하대요.","각 곤충 집의 실리시드 뇌를 가져다 달래요."},c={"프랭칼이 훌륭하다며 칭찬해요.","다른 일도 맡길 수 있으니 멀리 가지 말래요."}},
[8313]={a={"미늘벌레 고기 조리법에 낯선 약초와 양념이 나와요.","캘랜드라스는 사막 식물을 잘 알 테니 설명해 줄 거래요.","찢어낸 조리법 페이지를 캘랜드라스에게 가져다 달래요."},c={"캘랜드라스는 간단해 보인다며 페이지를 살펴봐요.","약초 이름을 풀어서 보여 주겠대요."},nx=8317,nt="Kitchen Assistance"},
[8314]={a={"탁본으로 수정 프리즘에 상형 문자를 복원했어요.","퀴라지가 이걸로 실리시드와 메시지를 주고받는대요.","지질학자 락스베인에게 프리즘을 가져다 달래요."},c={"애초에 풀 게 없어서 드워프들이 못 푼 거래요.","프리즘 겉에 단서가 하나 있는데 좋아 보이진 않대요."},nx=8315,nt="The Calling"},
[8315]={a={"락스베인은 이 상형 문자가 밀사를 부르는 암호라고 짐작해요.","그락카론드의 무덤 모래에 그리면 대군주가 올지 모른대요.","대군주를 물리치고 퀴라지 밀사의 장치를 되찾아 달래요."},c={"오래된 역사를 손에 쥐게 됐다며 기뻐해요."}},
[8317]={a={"캘랜드라스는 이 조리법으로 훈제 사막 경단을 준비해요.","좀 도와줄 수 있냐고 캘랜드라스가 물어요.","훈제 사막 경단 만드는 걸 도와 달래요."}},
[8318]={a={"황혼의망치단은 알 수 없는 글귀가 적힌 서류를 가지고 다녀요.","그 서류로 다른 집단과 비밀리에 정보를 주고받는대요.","암호화된 황혼의 문서를 빼내 가져다 달래요."},c={"보르가 잘했다며 문서를 잘 보관하겠대요.","나중에 쓸모가 있을지도 모른대요."}},
[8320]={a={"황혼의망치단이 실리더스 곳곳에서 수상한 의식을 치러요.","서쪽 주둔지에 황혼의 대지술사들이 있대요.","그 대지술사들을 처치하고 후움에게 돌아가 달래요."},c={"후움이 잘 해냈다며 칭찬해요.","황혼의망치단에 큰 타격이 됐을 거래요."},nx=8321,nt="Vyral the Vile"},
[8321]={a={"황혼의망치단은 북동쪽 동굴 황혼의 터에도 기지를 뒀대요.","그 동굴에 지휘부관 타락의 바이랄이 자주 나타난대요.","바이랄을 처치하고 그의 인장 반지를 가져다 달래요."},c={"바이랄을 처치해 해냈다며 기뻐해요.","황혼의망치단의 활동에 큰 타격이 될 거래요."}},
[8323]={a={"오르텔은 황혼의 사전을 얻은 뒤 작은 부탁을 해요.","황혼의망치단은 달마다 암호화된 소식지를 낸대요.","그 소식지에 실린 암호 문서를 구해다 달래요."},c={"오르텔이 문서를 최대한 빨리 풀겠대요.","쓸 만한 게 나오면 정보를 전해 준대요."}},
[8331]={a={"황혼의망치단을 공격해도 작전을 늦출 수 없었대요.","그 뒤에 심연의 의회가 바람의 돌로 그들을 조종한대요.","세나리온 요새의 아우렐 골드리프와 얘기해 보래요."},c={"아우렐이 심연의 의회와 맞설 거냐고 물어요.","그렇다면 다음 말을 잘 들어 보래요."},nx=8332,nt="Dukes of the Council"},
[8332]={a={"오렐은 바람의 돌로 심연의 군주를 기습할 방법을 생각했대요.","작전에는 황혼의 신도 계급장 모조품이 필요하대요.","눈부신 큰 결정과 심연의 문장을 모아 달래요."},c={"오렐이 계급장을 다 만들어 건네줘요.","이걸 차고 바람의 돌을 쓰면 부하로 여길 거래요."},nx=8349,nt="Bor Wildmane"},
[8341]={a={"심연의 군주는 바람의 돌로만 부를 수 있대요.","오렐은 군주를 속일 지휘관 반지를 만들려 해요.","눈부신 큰 결정과 심연의 인장을 모아 달래요."},c={"오렐이 반지를 완성해 건네줘요.","큰 바람의 돌을 쓸 때 이걸 차면 군주를 유인할 수 있대요."},nx=8351,nt="Bor Wishes to Speak"},
[8343]={a={"아우렐이 심연의 군주를 물리칠 방법을 찾은 것 같대요.","위험하지만 해낼 수 있을 거래요.","세나리온 요새에서 아우렐과 얘기해 보래요."},c={"아우렐은 심연의 군주를 부를 방법을 안다고 믿어요.","자세히 설명해 준다며 들어 보래요."},nx=8341,nt="Lords of the Council"},
[8348]={a={"보르는 군주를 부르는 법을 알아냈다는 말을 들었대요.","군주 하나를 해치우면 부하들이 크게 놀랄 거래요.","그 증거로 심연의 인장을 가져다 달래요."}},
[8349]={a={"오렐 골드리프는 이제 계급장으로 군주를 부를 수 있대요.","보르 와일드메인이 심연의 의회를 상대할 일을 맡길 거래요.","세나리온 요새의 보르 와일드메인을 만나 달래요."},c={"보르가 다시 만나서 반갑대요.","계급장을 만들었다니 다음 일에 꼭 필요하대요."},nx=8348,nt="Signet of the Dukes"},
[8351]={a={"이제 황혼의 의회 수장으로 변장할 수 있게 됐어요.","보르 와일드메인이 얘기를 나누고 싶어 할 거래요.","그를 만나러 가서 어려운 임무를 준비하래요."},c={"보르가 맞다며 앞으로 아주 어려운 일이 있대요."},nx=8352,nt="Scepter of the Council"},
[8352]={a={"보르는 심연의 군주에 맞설 준비가 됐대요.","아주 위험해서 최고의 정예 부대가 필요하대요.","이겨서 심연의 홀을 가져오면 큰 보상을 준대요."},c={"보르가 해냈다며 크게 놀라요.","가장 큰 상자에 좋은 물건을 가득 담아 줘요."}},
[8361]={a={"황혼의망치단이 고위 정령을 소환하는 의식을 봤대요.","황혼의망치단은 그 정령들에게 명령을 받는대요.","심연의 기사단을 해치우고 증거를 가져오래요."}},
[8365]={a={"거만한 의류상은 상류층에 최신 유행 옷을 공급해요.","상류층은 옷값을 터무니없이 비싸게 치러요.","해적단 소굴에서 남쪽바다 해적 모자를 구해 달래요."},c={"거만한 의류상이 칭찬하며 보상을 줘요.","그 돈 일부는 목욕에 쓰라고 권해요."}},
[8366]={a={"보안과장 빌지위즐이 해적을 혼내 줄 사람을 찾아요.","해적들은 상납금을 받고도 노략질을 한대요.","해적단 소굴에 가서 따끔한 맛을 보여 달래요."}},
[8367]={a={"호드 돌격대장은 모든 전장에서 싸운 용사를 높이 봐요.","얼라이언스를 조직적으로 싸워 섬멸하려 한대요.","전장의 명예 훈장을 모아 가져가 달래요."},c={"힘든 시련을 이겨 낸 용기가 대단하대요.","옛 승리의 증표는 이제 내려놓아도 된대요."}},
[8368]={a={"호드 돌격대장이 전쟁노래 협곡의 싸움을 걱정해요.","얼라이언스가 호드의 큰 목재 공급원을 빼앗으려 한대요.","명예 훈장을 가져와 호드 용사임을 증명해 달래요."},c={"호드 돌격대장이 당신의 활약을 크게 칭찬해요.","그 명성이 여러 곳에 널리 퍼지길 바란대요."}},
[8369]={a={"스톰파이크 원정대가 먼저 서리늑대 영토를 침략했대요.","얼라이언스가 호드 땅을 침략하는데 가만히 있을 수 없대요.","알터랙 계곡에 가서 침략자들을 몰아내 달래요."},c={"알터랙 계곡을 지킨 용기가 대단하대요.","그 일을 윗사람들에게 알리겠대요."}},
[8370]={a={"호드 돌격대장이 얼라이언스와의 전쟁이 커졌다고 해요.","아라시 분지 싸움은 결국 자원을 차지하는 싸움이래요.","자원이 끊기지 않게 아라시 분지 명예 훈장을 가져다 달래요."},c={"아라시에서 자원을 확보한 건 중요한 일이에요.","잘했어요."}},
[8410]={a={"베람 스카이체이서가 바람의감시자 바스라의 전갈을 전해요.","바스라는 원소를 가져와야 대화 상대로 인정한대요.","물, 불, 대지, 바람의 샘플을 모아 가져다 달래요."},c={"바스라는 잘했다며 이제 얘기를 나눌 수 있대요."},nx=8412,nt="Spirit Totem"},
[8411]={a={"바람의감시자 바스라가 당신의 지식을 시험하려 해요.","먼저 불, 공기, 물, 대지의 원소를 가져와야 신뢰한대요.","원소를 가져가면 그때 이야기를 나누자고 해요."},c={"바스라는 필요한 원소를 받았다며 이제 대화하자고 해요."},nx=8412,nt="Spirit Totem"},
[8412]={a={"바람의감시자 바스라는 자신을 지킬 정기의 토템이 필요해요.","더 원초적인 자연의 재료가 필요하다고 해요.","서부 역병지대에서 곰 발톱이나 거미 눈을 찾아 달래요."},c={"바스라는 좋다며 토템을 한번 써 보자고 해요."},nx=8413,nt="Da Voodoo"},
[8413]={a={"정기의 토템만으로는 부족하다고 바스라가 말해요.","가라앉은 사원의 트롤에게 부두 깃털이 있대요.","사원에 있는 트롤 여럿을 처치해 달래요."},c={"바스라는 이제 편히 쉴 수 있겠다며 기뻐해요.","정기의 토템이 자신을 지켜 줄 거래요.","당신도 원하는 게 있냐고 물어요."}},
[8417]={a={"소렉은 저주받은 땅에 있는 영혼이 문제래요.","그 영혼은 몸은 죽었지만 전사의 명예는 남아 있대요.","그와 대화해서 무슨 일인지 알아내 도와 달래요."},c={"영웅의 넋은 당신이 고통을 덜어 주러 왔다고 해요.","그냥 베어 주면 좋겠지만 그리 간단하지 않대요."},nx=8423,nt="Warrior Kinship"},
[8419]={a={"악령의 숲에 사는 임프시가 부탁이 있대요.","수상하지만 신뢰의 증표로 지옥 옷감을 가져오래요.","임프시에게 지옥 옷감을 가져다 달래요."},c={"임프시는 지옥 옷감을 얼굴에 대고 좋아해요.","옷감이 피부를 태우는 느낌이 좋대요."},nx=8421,nt="The Wrong Stuff"},
[8420]={a={"임프시는 자기만의 펫을 갖고 싶대요.","Niby만 펫이 있어서 불공평하다고 해요.","사티로스에게서 지옥 옷감을 구해 달래요."},nx=8421,nt="The Wrong Stuff"},
[8421]={a={"임프시는 이제 지옥 옷감으로 인형을 만들려 해요.","눈을 만들 나무와 악마의 기운을 심을 정수가 필요해요.","강철나무 숲과 수액괴물 근처에서 구해 달래요."},nx=8422,nt="Trolls of a Feather"},
[8422]={a={"임프시의 인형이 거의 완성됐대요.","속을 채울 부두 깃털은 트롤에게서 나온대요.","가라앉은 사원의 트롤들을 모두 해치워 달래요."},c={"임프시는 인형을 완성하고 악마처럼 꼭 껴안아요.","부두 깃털에는 이상한 부작용이 있대요."}},
[8423]={a={"호드 영웅의 넋은 당신에게 명예로운 일을 맡기려 해요.","렉사르가 한 칼에 지옥멧돼지를 잡았다며 실력을 재려 해요.","저주받은 땅의 지옥멧돼지를 잡고 돌아와 달래요."},c={"영웅의 넋은 증거가 없어도 해낸 걸 안다고 해요.","얼굴에 결연한 의지가 보인다고 해요."},nx=8424,nt="War on the Shadowsworn"},
[8424]={a={"호드 영웅의 넋은 어둠의혈맹 때문에 괴로워해요.","그들의 어둠의식과 마법이 살아 있을 때보다 큰 고통이래요.","그 분노를 전하러 어둠의혈맹을 처치해 달래요."},c={"영웅의 넋은 벌써 고통이 가라앉았다고 해요.","명예를 지켜 줘서 고맙다고 해요."},nx=8425,nt="Voodoo Feathers"},
[8425]={a={"호드 영웅의 넋은 당신의 명예에 보답하려 해요.","살아 있을 때 쓰던 무기와 갑옷을 당신에게 주고 싶대요.","가라앉은 사원의 트롤들에게서 부두 깃털을 얻어 달래요."},c={"영웅의 넋은 잠깐이라도 쇠의 차가운 감촉을 느꼈대요."}},
[8426]={a={"호드 돌격대장이 전쟁노래 협곡 싸움을 알려요.","얼라이언스가 숲을 지킨다는 핑계로 목재 공급원을 노린대요.","은빛날개 파수대와 싸운 증거를 가져다 달래요."},c={"훌륭해요! 전쟁노래 협곡을 지켜 가치를 증명했어요.","당신의 명예가 널리 알려질 거래요."}},
[8427]={a={"호드 돌격대장이 전쟁노래 협곡 싸움을 알려요.","얼라이언스가 숲을 지킨다는 핑계로 목재 공급원을 노린대요.","은빛날개 파수대와 싸운 증거를 가져다 달래요."},c={"훌륭해요! 전쟁노래 협곡을 지켜 가치를 증명했어요.","당신의 명예가 널리 알려질 거래요."}},
[8428]={a={"호드 돌격대장이 전쟁노래 협곡을 걱정해요.","얼라이언스가 호드의 목재 공급원을 빼앗으려 한대요.","명예 훈장을 가져다 호드의 용사임을 증명해 달래요."},c={"호드 돌격대장은 작전을 지킨 당신을 칭찬해요.","그 명예가 호드 땅 곳곳에 널리 퍼질 거래요."}},
[8429]={a={"호드 돌격대장이 전쟁노래 협곡을 걱정해요.","얼라이언스가 호드의 목재 공급원을 빼앗으려 한대요.","명예 훈장을 가져다 호드의 용사임을 증명해 달래요."},c={"호드 돌격대장은 작전을 지킨 당신을 칭찬해요.","그 명예가 호드 땅 곳곳에 널리 퍼질 거래요."}},
[8430]={a={"호드 돌격대장이 전쟁노래 협곡을 걱정해요.","얼라이언스가 호드의 목재 공급원을 빼앗으려 한대요.","명예 훈장을 가져다 호드의 용사임을 증명해 달래요."}},
[8436]={a={"호드 돌격대장이 얼라이언스와 전면전이 됐다고 해요.","아라시 분지 싸움은 자원을 두고 벌이는 싸움이래요.","포세이큰 파멸단에 힘을 보태 달래요."},c={"아라시에서 자원을 확보한 건 중요한 일이에요.","잘했어요."}},
[8437]={a={"얼라이언스와의 싸움이 전면전으로 번졌대요.","아라시 분지는 자원을 두고 다투는 곳이래요.","호드의 자원이 끊기지 않게 도와 달래요."},c={"호드 돌격대장은 아라시 분지 자원을 지킨 게 큰일이래요.","당신이 잘해 줬다고 칭찬해요."}},
[8438]={a={"얼라이언스와의 싸움이 이제 전면전이 됐대요.","아라시 분지는 결국 자원을 두고 다투는 곳이래요.","호드 자원이 끊기지 않게 힘을 보태 달래요."},c={"호드 돌격대장은 아라시 분지 자원을 지킨 게 큰일이래요.","당신이 잘해 줬다고 칭찬해요."}},
[8439]={a={"얼라이언스와의 싸움이 전면전으로 번졌대요.","아라시 분지는 자원을 두고 다투는 곳이래요.","호드의 자원이 끊기지 않게 도와 달래요."},c={"호드 돌격대장은 아라시 분지 자원을 지킨 게 큰일이래요.","당신이 잘해 줬다고 칭찬해요."}},
[8446]={a={"악몽이 깃든 물건이 세상을 오염시키고 있대요.","에메랄드의 꿈에 나타난 용들과 관련 있는 것 같대요.","물건의 숨은 뜻을 풀 드루이드를 찾아 달래요."},nx=8447,nt="Waking Legends"},
[8447]={a={"수호자 레물로스가 악몽이 깃든 물건을 정화하려 해요.","엘룬아라 호수의 물이 악몽을 녹일 거래요.","정화가 끝날 때까지 기다려 달래요."}},
[8460]={a={"나무구렁일족은 타락을 피한 유일한 펄볼그 부족이래요.","다른 종족들이 펄볼그를 마구 죽여 남을 잘 안 믿어요.","악령의 숲의 타락한 마른가지일족을 몰아내 달래요."},c={"그라즐은 나무구렁일족을 지켜 줘서 고맙대요.","우정의 표시로 작은 선물을 준대요."},nx=8462,nt="Speak to Nafien"},
[8461]={a={"마른가지 야영지에 사악한 기운이 스며들었대요.","마른가지일족은 악마 때문에 타락했을 뿐이래요.","그 야영지를 없애 달래요."},c={"나피엔은 당신이 승리한 걸 느꼈대요.","그래도 당신을 믿을 만하다고 인정했대요.","시간이 걸려도 요새에서 환영받을 수 있대요."},nx=8465,nt="Speak to Salfa"},
[8462]={a={"그라즐은 당신이 더 큰 위협도 막을 수 있다고 믿어요.","나무구렁 요새 입구에 나피엔이 지키고 있대요.","북쪽으로 가서 나피엔과 얘기해 달래요."},c={"나피엔은 동맹을 원하는 당신을 환영한대요.","다만 부족은 낯선 이를 몹시 경계한대요.","증명하지 못하면 요새에서 적대당한대요."}},
[8464]={a={"나무구렁일족 살파가 눈사태일족을 걱정해요.","눈사태일족이 최근 부쩍 공격적으로 변했대요.","눈사태일족 마을에 가서 그들을 막아 달래요."},c={"살파는 고맙지만 마음이 슬프다고 해요.","감사의 표시로 이걸 받아 달래요.","앞으로도 도와 달라고 부탁해요."}},
[8465]={a={"나피엔은 타락의 위협이 여러 곳에서 온다고 해요.","여명의 설원 눈사태일족도 타락했대요.","나무구렁 요새를 지나 살파와 얘기해 달래요."},c={"살파는 여명의 설원에서 나무구렁일족을 대변한대요.","눈사태일족도 악령의 숲 펄볼그처럼 타락했대요.","도움을 주겠다면 기꺼이 받겠대요."}},
[8470]={a={"마른가지일족의 의식 토템 하나를 찾았어요.","토템에서 절망감이 느껴진대요.","나무구렁 요새에 가져가 용도를 알아봐 달래요."},c={"케른다는 이 토템이 마른가지일족의 것이라고 알아봐요.","토템에 동족을 돌아서게 한 악이 있나 봐요.","고맙다며 선물도 건네요."}},
[8471]={a={"눈사태일족의 의식 토템 하나를 찾았어요.","토템에서 공포와 절망이 느껴져요.","나무구렁 요새에 가져가 용도를 알아봐 달래요."},c={"케른다는 이 토템이 뒤틀려 있다고 해요.","눈사태일족을 적대하게 만든 악이 깃든 것 같대요.","언젠가 눈사태일족이 진정하길 바란대요."}},
[8481]={a={"외눈 고른이 눈사태일족을 지배하는 악마를 불러낼 방법을 찾았대요.","악마 소환의 횃불을 대족장 눈사태의 동굴에 꽂아야 해요.","잔디비어스를 쓰러뜨려 정수를 가져다 달래요."},c={"외눈 고른은 당신이 나무구렁 요새를 구했다고 해요.","눈사태일족에게 살아남을 기회가 생겼대요.","싸움은 계속되지만 회복할 시간이 생겼대요."}},
[8485]={a={"나무구렁일족 외눈 고른이 평화를 원해요.","고른은 당신을 호드 평화의 열쇠로 여긴대요.","이 공물을 오그리마의 스랄에게 가져다 달래요."}},
[8519]={a={"수정 안에서 뭔가 꿈틀거리는 게 느껴져요.","자세히 보니 잊혀진 오래된 기억 속 과거가 보여요.","기억을 다 살핀 뒤 타나리스 시간의 동굴 아나크로노스를 찾아가래요."},c={"아나크로노스는 배신 뒤 부서진 지팡이 조각을 모아 여기 왔대요.","지팡이가 나쁜 데 쓰이지 않게 지키려 했대요.","그래서 용 군단의 임무가 생겼지만 지금은 그 군단에 쫓긴대요."},nx=8555,nt="The Charge of the Dragonflights"},
[8532]={a={"광부 크롬웰은 전쟁 준비를 도울 일손이 필요해요.","구리 광석이 아니라 구리 주괴가 필요하대요.","직접 제련해서 구리 주괴를 가져다 달래요."},c={"크롬웰은 이 주괴면 충분하다고 해요.","전쟁 물자로 쓸 거라 광을 내지 않은 게 고맙대요.","더 가져올 생각이 있으면 다시 오래요."}},
[8542]={a={"그런트 마우그가 주석 주괴를 모으는 일을 맡았대요.","안퀴라즈 전쟁을 준비하려고 주석이 필요하대요.","주석 주괴를 모아 그에게 가져다 달래요."}},
[8545]={a={"정예수호병 티키라는 전쟁을 준비하고 있대요.","호드 전쟁 물자에 쓸 미스릴 주괴가 부족해요.","미스릴 광석을 캐서 주괴로 제련해 달래요."},c={"티키라는 이 주괴가 좋은 시작이라고 해요.","전쟁 물자를 만드는 데 잘 쓰일 거래요.","미스릴이 더 필요하니 다시 찾아와 달래요."}},
[8549]={a={"약초채집사 프라우드페더가 전쟁용 물약을 준비해요.","호드 물약을 만들 평온초 꽃잎이 부족하대요.","평온초 꽃잎을 많이 가져다 달래요."},c={"프라우드페더는 쉽지 않은 일을 잘해냈다고 해요.","그렇다고 아직 감동한 건 아니래요."}},
[8551]={a={"선장 허클베리 스모츠는 한때 유명한 선장이었대요.","바다 거인들이 배를 부수고 부하들을 죽였대요.","고를라쉬에게서 스모츠의 상자를 되찾아 달래요."},c={"스모츠는 상자를 찾아 정말 기뻐해요.","상자를 되찾아 화가 조금 가라앉았대요.","하지만 복수는 아직 끝나지 않았대요."}},
[8552]={c={"스모츠가 머리띠를 찾아 줘서 놀라워해요.","그럼 모크라쉬를 해치운 거냐고 물어요.","모크라쉬는 배를 부순 거인 셋 중 하나래요."},nx=8553,nt="The Captain's Cutlass"},
[8553]={a={"선장 허클베리 스모츠는 두 번째 배도 거인에게 잃었대요.","이번엔 거인 네골라쉬가 그의 커틀라스를 훔쳤대요.","먼저 스프로거를 만나 얘기해 달래요."},c={"스프로거는 선장이 네골라쉬를 쫓는다고 들었대요."},nx=8554,nt="Facing Negolash"},
[8554]={a={"스프로거는 네골라쉬가 늘 배고픈 거인이라고 해요.","네골라쉬는 사람보다 와인과 바베큐를 원한대요.","구명정에 음식을 실어 그를 불러내 달래요."}},
[8556]={a={"퀴라지 부관들의 반지에 강한 힘이 있다는 소문이래요.","이론상 오염된 보석을 순수한 것으로 바꾸면 된대요.","반지와 우상을 가져다주면 강한 반지를 만들어 준대요."},c={"예센드라는 반지의 보석을 바꿔 준다고 해요.","효과가 훨씬 나아질 거래요."}},
