[8558]={a={"감시자 하로는 퀴라지 재료로 강한 무기를 만들어 준대요.","퀴라지 유물을 보니 무기를 만들고 싶어진대요.","퀴라지 자루와 우상, 스카라베를 가져와 달래요."},c={"하로는 자루의 균형이 완벽하다며 칭찬해요.","이제 무기를 가지고 적을 무찌르라고 해요."}},
[8575]={a={"아주어고스의 마법 장부는 한 글자도 읽을 수 없어요.","어떤 언어로 쓰였는지조차 알 수 없어요.","타나리스의 나라인 수스팬시에게 전해 달래요."},c={"나라인은 잘했다며 감탄하고 살펴봐요.","용의 언어는 전혀 읽지 못한대요."},nx=8576,nt="Translating the Ledger"},
[8577]={a={"나라인 수스팬시는 옛 친구 Stewvul에게 고글을 도둑맞았어요.","스튜불이 그의 마음을 크게 상처 줬대요.","스튜불을 찾아 수정점 고글을 되찾아 달래요."},c={"눈에 잘 띄지 않는 상자가 놀라 말해요.","나를 찾아낸 게 믿기지 않는대요.","아웃랜드에는 절대 안 돌아가겠대요."},nx=8578,nt="Scrying Goggles? No Problem!"},
[8578]={a={"나라인의 고글을 상자가 잃어버렸대요.","화산 심장부를 뒤지다 잃어버렸대요.","고글을 찾아 나라인 수스팬시에게 돌려 달래요."},c={"나라인은 고글을 찾아서 아주 기뻐해요.","작은 보답도 준비했대요."}},
[8579]={a={"칸드로스트라즈는 안퀴라즈 깊숙이 갇힌 동족을 느껴요.","가까이 가면 C'Thun의 지배를 받을까 두려워해요.","평범한 당신이 무엇을 바꿀 수 있겠냐고 물어요."},c={"칸드로스트라즈는 당신이 평범하지 않다고 해요.","Bronze Dragonflight의 신뢰를 얻으면 믿겠대요.","그때야 진정한 챔피언으로 키워 준대요."}},
[8580]={a={"박쥐기수 펠레케이키는 호드가 화염초 꽃잎을 찾는다고 해요.","그 꽃잎의 쓰임은 아무도 모른대요.","화염초 꽃잎을 많이 가져다 달래요."}},
[8582]={a={"연금술사 제젤은 보라 연꽃을 많이 원해요.","물약과 오일을 만드는 재료라고 해요.","보라 연꽃을 가능한 한 많이 모아 달래요."},c={"제젤은 훌륭한 노력이라고 칭찬해요.","보라 연꽃은 잘 보관해 둘 거래요.","더 필요하니 조금 뒤에 다시 와 달래요."}},
[8584]={a={"나라인 수스팬시는 자기 일은 묻지 말래요.","500파운드짜리 닭이 필요하대요.","가젯잔의 더지 퀵클레이브와 얘기해 달래요."},nx=8585,nt="The Isle of Dread!"},
[8585]={a={"더지는 공포의 섬에 키메로크의 아버지가 있대요.","그 녀석은 500파운드쯤 될 것 같대요.","지배자 라크마에란을 쓰러뜨려 시체와 키메로크 안심을 구해 달래요."},c={"더지는 안심 상태가 정말 좋다며 감탄해요.","닭 요리법을 짜려면 시간이 좀 걸린대요."},nx=8586,nt="Dirge's Kickin' Chimaerok Chops"},
[8586]={a={"더지가 요리법을 완성했대요.","향신료는 더지가 맡는대요.","고블린 로켓 연료와 깊은바다 소금을 가져다 달래요."},c={"더지는 요리가 완성됐다고 알려요.","이름은 더지의 기똥찬 키메로크 찹스테이크래요."},nx=8587,nt="Return to Narain"},
[8587]={a={"더지 퀵클레이브는 약속대로 닭을 가져왔어요.","나라인이 닭으로 뭘 하려는지는 모르겠대요.","그 닭을 나라인 수스팬시에게 가져다 달래요."},c={"나라인은 닭을 한입 가득 먹으며 좋아해요.","지금까지 먹어 본 닭 중 최고래요."}},
[8588]={a={"무두장이 자마니는 전쟁 물자를 모으고 있어요.","질긴 가죽은 방어구 만들 때 거의 다 쓰인대요.","질긴 가죽을 더 모아 달라고 부탁해요."},c={"자마니는 가죽 샘플이 아주 순수하대요.","고대 신들과 관련이 있을지 모른대요."}},
[8590]={a={"하사관 우말라가 호드의 전쟁 준비를 맡았대요.","두꺼운 가죽을 엄청 많이 모아야 한대요.","대신 두꺼운 가죽을 모아 달라고 부탁해요."},c={"우말라는 가죽을 비행선과 무기에 쓸 거래요.","호드를 대신해 고맙다고 인사해요."}},
[8597]={a={"나라인 수스팬시가 책을 안전한 곳에 숨겨 뒀대요.","거기 가려고 자이로콥터를 탔는데 해변에 추락했대요.","남쪽 바다에서 그 책을 찾아 달라고 해요."},c={"책이 없어졌대요.","흙더미 위에 쪽지가 남아 있대요."},nx=8598,nt="rAnS0m"},
[8598]={a={"누군가 나라인 수스팬시의 소중한 책을 훔쳐 갔대요.","협박장에는 책을 돌려받을 조건이 적혀 있대요.","그 협박장을 나라인에게 전해 달래요."},nx=8606,nt="Decoy!"},
[8599]={a={"인어공주 메리디스는 찾아오는 손님이 드물대요.","예전에 부서진 비행기에서 나라인을 구해 줬대요.","나라인에게 연애 편지를 전해 달래요."}},
[8600]={a={"의사 세라투스는 칼이 손에 잘 맞는 게 더 중요하대요.","호드를 위한 안퀴라즈 전쟁 준비에 튼튼한 가죽이 필요하대요.","튼튼한 가죽을 구해다 달라고 부탁해요."},c={"낡은 데가 좀 있지만 임무는 잘 끝냈대요.","튼튼한 가죽을 더 가져오라고 해요."}},
[8604]={a={"치료사 롱러너가 응급치료 물품을 모으고 있어요.","전쟁터에서 병사들이 사제만 믿을 수는 없대요.","양모 붕대를 많이 모아 달라고 부탁해요."}},
[8606]={a={"나라인 수스팬시가 책을 훔친 자들을 속이려 해요.","돌을 채운 가방을 여명의 설원 접선 장소에 가져가래요.","그곳에 나타난 도둑들을 해치워 달래요."},nx=8620,nt="The Only Prescription"},
[8607]={a={"귀부인 칼로는 마법 붕대를 많이 모으고 있대요.","새것이면 좋지만 헌것도 괜찮대요.","마법 붕대를 모아 자신에게 가져다 달래요."},c={"칼로는 생각보다 잘했다며 놀라워해요.","쉬운 일인데 보상이 과하다며 또 가져오래요."}},
