[8705]={a={"감시자 하로는 퀴라지 재료로 강한 무기를 만들어 준대요.","퀴라지 유물을 보니 무기를 만들고 싶어진대요.","퀴라지 자루와 우상, 스카라베를 가져와 달래요."},c={"하로는 자루의 균형이 완벽하다며 칭찬해요.","이제 무기를 가지고 적을 무찌르라고 해요."}},
[8706]={a={"감시자 하로는 퀴라지 재료로 강한 무기를 만들어 준대요.","퀴라지 유물을 보니 무기를 만들고 싶어진대요.","퀴라지 자루와 우상, 스카라베를 가져와 달래요."}},
[8707]={a={"감시자 하로는 퀴라지 재료로 강한 무기를 만들어 준대요.","퀴라지 유물을 보니 무기를 만들고 싶어진대요.","퀴라지 자루와 우상, 스카라베를 가져와 달래요."},c={"하로는 자루의 균형이 완벽하다며 칭찬해요.","이제 무기를 가지고 적을 무찌르라고 해요."}},
[8708]={a={"감시자 하로는 무기를 만드는 사람이에요.","퀴라지 유물을 보면 그 재료로 솜씨를 발휘하고 싶대요.","세나리온 의회에 대한 충성을 증명해 달래요."},c={"감시자 하로는 이 자루가 걸작이고 균형도 완벽하대요.","이제 무기를 가져가서 적을 무찌르라고 해요."}},
[8709]={a={"감시자 하로는 무기를 만드는 사람이에요.","퀴라지 유물을 보면 그 재료로 솜씨를 발휘하고 싶대요.","세나리온 의회에 대한 충성을 증명해 달래요."},c={"감시자 하로는 이 자루가 걸작이고 균형도 완벽하대요.","이제 무기를 가져가서 적을 무찌르라고 해요."}},
[8710]={a={"감시자 하로는 퀴라지 유물을 보면 솜씨를 뽐내고 싶대요.","퀴라지의 귀한 재료로 강한 무기를 만들 수 있대요.","세나리온 의회에 충성을 증명해 보라고 해요."},c={"화려한 퀴라지 자루의 균형이 완벽하대요.","이 무기로 적들을 물리치라고 해요."}},
[8712]={a={"감시자 하로는 무기를 만드는 사람이에요.","퀴라지 유물을 보면 그 재료로 솜씨를 발휘하고 싶대요.","세나리온 의회에 대한 충성을 증명해 달래요."},c={"감시자 하로는 이 자루가 걸작이고 균형도 완벽하대요.","이제 무기를 가져가서 적을 무찌르라고 해요."}},
[8728]={a={"나라인 수스팬시가 아케이나이트 부표를 만들 수 있대요.","단, 엘레멘티움 광석과 귀한 보석도 많이 필요해요.","재료를 가져다주면 부표를 만들어 준대요."},c={"약속은 약속이라며 받아 든대요.","낚시하는 데 이런 고생을 하다니 놀랍대요."},nx=8729,nt="The Wrath of Neptulon"},
[8729]={a={"나라인 수스팬시가 식인아귀라는 괴물 얘기를 해요.","폭풍의 만 소용돌이에 부표를 던져야 한대요.","성공하면 홀 파편을 아나크로노스에게 가져가 달래요."},c={"잘했다고 칭찬하며 곧 홀을 고칠 수 있대요."}},
[8730]={a={"타락한 밸라스트라즈가 오랫동안 맡아 온 홀 파편이 있대요.","네파리안이 그 파편을 가져가 부수려 한대요.","네파리안을 해치우고 파편을 되찾아 달래요."}},
[8733]={a={"말퓨리온 스톰레이지가 꿈의 폭군 에라니쿠스를 구하려 해요.","에라니쿠스는 고대 신들의 오염을 입었대요.","다르나서스 성벽 밖에서 말퓨리온의 대리인을 찾래요."},c={"숲 위습은 웅웅거리는 소리만 낸대요.","이상하게도 생각으로 말을 건넨대요."},nx=8734,nt="Tyrande and Remulos"},
[8734]={a={"숲 위습이 티란데에게 소식을 전한대요.","이제 달의 숲에서 수호자 레물로스를 만나야 한대요.","레물로스에게 에라니쿠스를 부르는 방법을 물어보래요."},c={"에라니쿠스가 거부하면 꿈에서 끌어낼 수 없대요.","그는 말퓨리온의 화신을 없애려고 이 세계에 오려 해요.","말퓨리온이 쓰러지면 나이트메어가 모든 걸 삼킬 거래요."},nx=8735,nt="The Nightmare's Corruption"},
[8735]={a={"수호자 레물로스가 오염된 악몽의 조각을 찾고 있어요.","에메랄드의 꿈의 차원문들을 돌아다녀야 한대요.","용혈족에게서 조각을 얻어 레물로스에게 돌아오래요."},c={"준비됐냐며 세상이 준비됐는지 모르겠대요.","말퓨리온을 향한 의무와 명예로 움직인대요."},nx=8736,nt="The Nightmare Manifests"},
[8736]={a={"에라니쿠스가 나이트헤이븐을 위협하고 있어요.","에라니쿠스는 죽이지 말고 구해야 한대요.","레물로스를 지키며 티란데가 올 때까지 버텨 달래요."},c={"에라니쿠스가 구원받았대요.","이제 말퓨리온에게 강력한 동맹이 될 거래요.","직접 준 무장이니 퀴라지와 싸울 때 쓰래요."},nx=8741,nt="The Champion Returns"},
[8741]={c={"당신의 업적이 모두에게 알려질 거래요.","오그리마에서 남쪽 바다까지 칭송이 퍼질 거래요."}},
[8742]={a={"아나크로노스는 당신이 새 시대를 이끌 거라고 해요.","쑨의 예언을 깨뜨려 달래요.","준비되면 알려 달라고 해요."},c={"흐르는 모래의 홀이 다시 온전해졌대요.","당신이 직접 그 홀을 써야 한대요.","호드와 얼라이언스 군대가 오면 그때 징을 울리래요."}},
[8743]={a={"왕쇠똥구리 징이 당신 앞에 놓여 있어요.","징을 치면 안퀴라즈의 문이 열린대요.","그 뒤 혼란이 오니 백성을 지켜 달래요."}},
[8748]={a={"아나크로노스는 당신이 Kalimdor의 아이들을 계속 지켜 왔다고 해요.","그 공을 인정해 인장 반지의 힘을 키워 준대요.","그러니 인장 반지를 건네 달래요."},nx=8749,nt="The Path of the Protector"},
