[8791]={a={"잔인했던 오시리안이 패했대요.","칼림도어 사람들이 이 소식에 안도할 거래요.","무적의 오시리안의 머리를 마랄리스에게 가져가래요."},c={"강력한 아이템 중 하나를 고르게 해 준대요.","칼림도어 사람들을 위해 큰일을 했대요."}},
[8792]={a={"정예수호병 타이가가 호드의 전쟁 준비를 도와 달래요.","안퀴라즈 전쟁을 위해 호드는 도움이 절실하대요.","장군 고르척을 찾아가 얘기해 보래요."},c={"호드를 돕겠다고 나선 당신을 반긴대요.","안퀴라즈 전쟁에서 실리시드를 이기기 위한 준비래요.","수집가들을 찾아가 맞는 물자를 모으라고 해요."}},
[8793]={a={"정예수호병 그림스포드가 호드의 전쟁 준비를 도와 달래요.","안퀴라즈 전쟁을 위해 호드는 도움이 절실하대요.","장군 고르척을 찾아가 얘기해 보래요."}},
[8794]={a={"정예수호병 카이진이 호드의 전쟁 준비를 도와 달래요.","안퀴라즈 전쟁을 위해 호드는 도움이 절실하대요.","장군 고르척을 찾아가 얘기해 보래요."}},
[8800]={a={"바람소환사 칼돈이 전쟁 임무를 알려 줘요.","전쟁에 기여한 만큼 전투장비를 준대요.","휘장을 들고 세나리온 요새의 바르구스를 찾아가래요."},c={"칼돈이 보냈냐며 뭘 해 줄지 살펴보겠대요."}},
[8801]={a={"안퀴라즈의 벽이 흔들리고 있대요.","쑨이라는 거대한 악이 무너졌대요.","쑨의 눈을 옆방의 용족에게 가져가래요."},c={"용족들은 악이 완전히 사라지면 스스로 떠나겠대요.","당신의 전설 같은 여정이 거의 끝났대요."},nx=8802,nt="The Savior of Kalimdor"},
[8802]={a={"캘레스트라즈가 시간의 동굴로 가라고 해요.","아나크로노스가 당신을 기다리고 있대요.","쑨의 눈을 그에게 건네 달래요."},c={"주인이 당신을 위해 유물들을 남겼대요.","유물 중 하나를 고를 수 있대요."}},
