[8918]={a={"모크바르는 당신이 못 본 특별한 방어구가 있대요.","실리더스 거미와 전갈의 독 견본이 많이 필요하대요.","독 견본과 약간의 금화를 가져다 달래요."},nx=8923,nt="A Supernatural Device"},
[8919]={a={"모크바르는 특별한 방어구를 내놓을 생각이래요.","실리더스 거미와 전갈의 독을 많이 원한대요.","독 샘플과 골드를 가져가 달라고 해요."},nx=8923,nt="A Supernatural Device"},
[8920]={a={"모크바르는 당신이 못 본 특별한 방어구가 있대요.","실리더스 거미와 전갈의 독 견본이 많이 필요하대요.","독 견본과 약간의 금화를 가져다 달래요."},c={"모크바르는 Mux가 아주 기뻐할 거래요.","이 팔보호구는 더 큰 방어구 세트의 일부였대요.","더 도와주면 나머지 세트도 생각해 보겠대요."},nx=8923,nt="A Supernatural Device"},
[8921]={a={"먹스 마나스크램블러가 4차원 유령 탐색기를 만들려 해요.","돈과 일손이 부족해서 도움이 필요하대요.","심령체 추출기에 쓸 재료를 가져다 달래요."},c={"먹스가 딱 필요한 재료라며 기뻐해요.","곧 추출기를 완성해 준대요.","도와준 보상으로 뭔가 준대요."},nx=8924,nt="Hunting for Ectoplasm"},
[8923]={a={"계속 도와주면 방어구 나머지를 준대요.","모은 독 견본은 먹스 마나스크램블러를 위한 거래요.","봉인된 독액 용기를 가젯잔의 먹스에게 가져가래요."},c={"먹스가 딱 떨어질 때였다며 기뻐해요.","모크바르가 보냈냐고 물어요."},nx=8921,nt="The Ectoplasmic Distiller"},
[8924]={a={"먹스가 만든 추출기를 아주 잘 만들었다고 칭찬해요.","언데드마다 심령체가 달라서 여러 곳을 다녀야 해요.","언데드 근처에 추출기를 놓고 심령체를 모아 오래요."},c={"먹스가 심령체가 아주 좋다며 기뻐해요.","아직 이 세상을 떠나지 못한 영혼과 닿을 수 있대요."},nx=8925,nt="A Portable Power Source"},
[8925]={a={"먹스가 장치를 계속 돌릴 에너지원을 찾고 있어요.","용암 군주 보크의 심장에 용암 핵이 있다는 소문이 있대요.","용암 핵을 구해 먹스에게 가져다 달래요."},c={"이 정도면 유령 탐색기를 켤 에너지가 충분하대요."},nx=8928,nt="A Shifty Merchant"},
[8927]={a={"모크바르는 당신이 아주 믿을 만한 사람이래요.","도와준 만큼 성과에 따라 보상하겠다고 해요.","자연의정수 허리띠와 장갑을 가져다 달래요."},nx=8930,nt="In Search of Anthion"},
[8928]={a={"먹스는 용암 핵의 힘을 전할 제어봉이 필요하대요.","여명의 설원의 임프가 악령의 제어봉을 팔고 있었대요.","검은속삭임 협곡 입구 동굴에서 임프를 찾아 사 오래요."},c={"이 제어봉이면 딱 맞는다며 기뻐해요.","이제 전부 합쳐 장치를 완성한대요."}},
[8930]={a={"모크바르는 남은 일이 고블린 발명품을 시험하는 것뿐이래요.","소문으로는 안시온이 성문에서 언데드에게 죽었대요.","4차원 유령 탐색기로 안시온의 유령과 대화해 달래요."},c={"안시온 하몬은 모크바르가 보냈냐고 물어요.","도와주겠지만 먼저 큰 부탁을 하나 해야 한대요."},nx=8945,nt="Dead Man's Plea"},
