[8939]={a={"모크바르는 당신이 아주 믿을 만한 사람이래요.","도와준 만큼 성과에 따라 보상하겠다고 해요.","마법학자의 허리띠와 장갑을 가져다 달래요."},c={"모크바르는 둘의 약속이 그대로라고 해요.","이건 앞으로 올 것의 맛보기일 뿐이래요.","저주받은 운명에서 풀어 주면 아주 강한 물건을 준대요."},nx=8930,nt="In Search of Anthion"},
