[8942]={a={"모크바르는 당신이 아주 믿을 만한 사람이래요.","도와준 만큼 성과에 따라 보상하겠다고 해요.","원소의 끈과 건틀릿을 가져다 달래요."},c={"모크바르는 둘의 약속이 그대로라고 해요.","이건 앞으로 올 것의 맛보기일 뿐이래요.","저주받은 운명에서 풀어 주면 아주 강한 물건을 준대요."},nx=8930,nt="In Search of Anthion"},
[8943]={a={"모크바르는 당신이 믿을 만하다는 걸 알았대요.","그래서 성과에 맞게 보상해 주려고 해요.","공포의안개 허리띠와 장갑을 가져오라고 해요."},nx=8930,nt="In Search of Anthion"},
[8944]={a={"모크바르는 당신이 아주 믿을 만한 사람이래요.","도와준 만큼 성과에 따라 보상하겠다고 해요.","용맹의 허리띠와 건틀릿을 가져다 달래요."},c={"모크바르는 둘의 약속이 그대로라고 해요.","이건 앞으로 올 것의 맛보기일 뿐이래요.","저주받은 운명에서 풀어 주면 아주 강한 물건을 준대요."},nx=8930,nt="In Search of Anthion"},
[8945]={a={"안시온 하몬의 아내 이시다가 남작 리븐데어에게 붙잡혔대요.","안시온은 아내가 은빛 여명회에 드는 걸 크게 반대했었대요.","남작 리븐데어에게서 이시다 하몬을 구해 달래요."},nx=8946,nt="Proof of Life"},
[8946]={a={"이시다 하몬은 사랑하는 사람이 자신을 구하려다 죽었대요.","당신이 그와 대화할 수 있다고 들었대요.","이 펜던트를 가져가 내가 건강하다고 전해 달래요."},nx=8947,nt="Anthion's Strange Request"},
[8947]={a={"안시온은 군주 발타라크의 아뮬렛 조각을 텔드렌에게 빼앗겼대요.","텔드렌은 안시온을 거의 죽일 뻔했다고 해요.","필요한 재료들을 모아다 달라고 부탁해요."},c={"안시온은 재료를 보고 잘했다며 좋아해요.","이 재료들로 필요한 물건을 만들겠대요."},nx=8948,nt="Anthion's Old Friend"},
[8948]={a={"텔드렌은 정정당당하게 싸우는 사람이 아니래요.","안시온은 텔드렌 가문 문장을 넣은 깃발을 만들었대요.","혈투의 전장 도서관의 팔린에게 깃발을 가져가 달래요."},c={"팔린은 안시온이 보냈다니 죽은 줄 알았다며 놀라요.","그래도 이상한 일은 많이 겪었다며 깃발 일을 묻네요."},nx=8949,nt="Falrin's Vendetta"},
[8949]={a={"팔린 트리셰이퍼는 이웃 오우거들을 몹시 미워한대요.","오모크와 왕 고르독의 추종자들도 똑같이 싫어한대요.","오우거를 해치우고 전투 목걸이를 가져오면 얘기하겠대요."},nx=8950,nt="The Instigator's Enchantment"},
[8950]={a={"팔린 트리셰이퍼는 깃발에 마법을 걸어 줄 수 있대요.","그런데 필요한 재료가 드물어서 지금은 없대요.","엘드레스 영혼의 정수와 어둠의 룬, 눈부신 큰 결정을 가져다 달래요."},c={"재료가 충분하다며 팔린이 마법을 걸겠대요.","마법이 끝나면 상대는 도전을 피할 수 없대요."},nx=9015,nt="The Challenge"},
[8957]={a={"안시온 하몬은 욕심에 목걸이를 세 조각 냈대요.","저주를 멈추려면 목걸이를 다시 맞춰야 한대요.","모크바르에게 보들리가 유일한 희망이라 전해 달래요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[8961]={a={"보들리는 군주 발타라크를 부르려면 화로가 필요하대요.","불의 귀족들이 그 재료를 가지고 있대요.","성스러운 화로와 재료를 보들리에게 가져다 달래요."},c={"보들리는 잘했다면서도 시간이 없다고 해요.","더 필요한 재료가 있어서 다음 일을 주겠대요."},nx=8962,nt="Components of Importance"},
[8962]={a={"보들리는 화로를 채울 다른 재료가 아직 필요하대요.","그레이후프의 친구 일부가 실리시드에게 넘어갔대요.","하이브레갈의 실리시드에게서 드루이드 유물을 구해 달래요."},c={"보들리는 유물의 정수를 화로에 넣었대요.","이제 검은바위 첨탑 아래층에서 그레이후프의 영혼을 불러내래요.","그레이후프는 목걸이 조각을 빼앗겨야 쉴 수 있대요."},nx=8966,nt="The Left Piece of Lord Valthalak's Amulet"},
[8963]={a={"보들리는 여사제 이살리엔이 별바람 마을에서 자랐대요.","화로에 넣을 또 다른 재료가 필요하대요.","서리속삭임 골짜기의 거인에게서 별바람 마을 유물을 구해 달래요."},c={"보들리는 잘했다며 유물의 힘을 화로에 불어넣겠대요.","혈투의 전장 동쪽 날개로 가서 화로로 이살리엔을 부르래요."},nx=8966,nt="The Left Piece of Lord Valthalak's Amulet"},
[8964]={a={"보들리는 죽은 옛 동료들의 유골을 불러내려 해요.","자리엔과 소도스는 Scarlet Crusade를 따랐대요.","동부 역병지대 티르의 손 수도원에서 검을 구해 달래요."},c={"보들리는 검의 정수를 화로에 넣었대요.","이제 스트라솔름에서 화로로 자리엔과 소도스를 불러내래요.","자리엔과 소도스의 영혼은 목걸이 때문에 더 뒤틀렸대요."},nx=8966,nt="The Left Piece of Lord Valthalak's Amulet"},
[8965]={a={"보들리의 옛 동료 코르모크는 오우거 강령술사였대요.","그는 속죄의 섬 추방자들의 영혼을 즐겨 불러냈대요.","속죄의 섬에서 추방된 자의 영혼재를 구해 달래요."},c={"보들리는 영혼재의 힘을 화로에 넣겠다고 해요.","이제 스칼로맨스 라스 프로스트위스퍼의 방에서 코르모크를 부르래요."},nx=8966,nt="The Left Piece of Lord Valthalak's Amulet"},
[8966]={a={"모르 그레이후프는 아뮬렛 조각에 홀린 첫 희생자래요.","그는 대장군 부네에게 붙잡혀 고문을 당했대요.","부름의 화로로 모르의 영혼을 불러내 쓰러뜨려 달래요."},c={"한 영혼이 편히 쉬게 됐다며 보들리가 고마워해요.","오른쪽 조각을 가진 자의 행방은 모른대요.","살아 있을 때 점술을 익혔다며 다음 일을 주겠대요."},nx=8970,nt="I See Alcaz Island In Your Future..."},
[8967]={a={"여사제 이살리엔은 조각의 비밀을 풀려고 혈투의 전장에 갔대요.","그런데 칼날바람 알진과 그 무리에게 기습을 당했대요.","부름의 화로로 이살리엔의 영혼을 불러내 쓰러뜨려 달래요."},c={"이살리엔의 영혼을 편히 쉬게 해 줘서 고맙대요.","오른쪽 조각을 가진 자의 행방은 모른대요.","살아 있을 때 점술을 익혔다며 다음 일을 주겠대요."},nx=8970,nt="I See Alcaz Island In Your Future..."},
[8968]={a={"자리엔과 소도스는 용병단이 해산되자 떠났대요.","그들이 목걸이 왼쪽 조각을 가져갔대요.","그 조각을 되찾아 달래요."},c={"보들리는 둘의 영혼이 드디어 쉬게 돼 다행이래요.","오른쪽 조각을 지니고 죽은 자의 행방은 모른대요.","살아 있을 때 점술을 조금 했다며 다른 일을 맡긴대요."},nx=8970,nt="I See Alcaz Island In Your Future..."},
[8969]={a={"코르모크는 강령술에 빠진 뒤로 다들 무서워했대요.","그는 아뮬렛 조각을 들고 스칼로맨스로 돌아갔대요.","부름의 화로로 코르모크의 영혼을 불러내 처치해 달래요."},c={"보들리는 코르모크가 오우거치고 나쁘지 않았다며 아쉬워해요.","오른쪽 조각을 가진 자의 행방은 모른대요.","살아 있을 때 점술을 익혔다며 다음 일을 주겠대요."},nx=8970,nt="I See Alcaz Island In Your Future..."},
[8970]={a={"보들리는 살아 있을 때 점술가가 되려고 했대요.","그 점술로 마지막 조각과 옛 동료의 영혼을 찾을 수 있대요.","알카즈 섬 스트라샤즈 나가에게서 붉은물풀을 구해 달래요."},c={"보들리는 무사히 돌아온 걸 보고 놀랐대요.","점술은 바로 답이 나오지 않는대요.","잠깐 기다려 달라고 해요."},nx=8985,nt="More Components of Importance"},
[8978]={a={"먹스 마나스크램블러는 함께 일해서 좋았다고 해요.","완성된 장치를 건네며 도움이 되길 바란대요.","이 장치를 들고 오그리마의 모크바르에게 돌아가 달래요."}},
[8985]={a={"사제 이살리엔은 별바람 마을에서 자랐대요.","보들리는 이살리엔의 영혼을 부를 재료가 필요하대요.","서리속삭임 골짜기 거인에게서 유물을 구해 달래요."},c={"보들리는 유물의 정수를 화로에 넣었대요.","이제 혈투의 전장에서 이살리엔을 불러내래요.","보들리는 남은 bloodkelp로 물약을 만들어 줬대요."},nx=8989,nt="The Right Piece of Lord Valthalak's Amulet"},
[8986]={a={"보들리는 마지막 조각이 어디 있는지 찾았다고 해요.","모르 그레이후프의 세나리온 의회 친구들이 실리시드에게 넘어갔대요.","하이브레갈 근처 실리시드에게서 드루이드의 유골을 구해 달래요."},c={"잘했다며 유골의 힘을 화로에 불어넣겠대요.","이제 검은바위 첨탑 아래층에서 모르 그레이후프를 불러내래요.","남은 붉은물풀로 만든 물약도 골라 가래요."},nx=8989,nt="The Right Piece of Lord Valthalak's Amulet"},
[8987]={a={"보들리의 옛 동료 자리엔과 소도스는 남매래요.","둘은 붉은 십자군에서 기사가 되기를 꿈꿨대요.","티르의 손 수도원에서 번쩍이는 열광의 검을 구해 달래요."},c={"보들리는 검을 잘 가져왔다며 힘을 불어넣겠대요.","이제 스트라솔름에서 자리엔과 소도스를 불러내래요.","남은 붉은물풀로 만든 물약도 골라 가래요."},nx=8989,nt="The Right Piece of Lord Valthalak's Amulet"},
[8988]={a={"보들리의 옛 동료 코르모크는 오우거 강령술사였대요.","그는 속죄의 섬 추방자들의 영혼을 즐겨 불러냈대요.","속죄의 섬에서 추방된 자의 영혼재를 구해 달래요."},c={"보들리는 영혼재의 힘을 화로에 불어넣겠대요.","이제 스칼로맨스 라스 프로스트위스퍼의 방에서 코르모크를 불러내래요.","남은 붉은물풀로 만든 물약도 골라 가래요."},nx=8989,nt="The Right Piece of Lord Valthalak's Amulet"},
[8989]={a={"모르 그레이후프는 아뮬렛 오른쪽 조각에 홀린 첫 희생자래요.","그는 대장군 부네에게 붙잡혀 고문을 당했대요.","부름의 화로로 모르의 영혼을 불러내 쓰러뜨려 달래요."},c={"보들리는 모르 그레이후프가 편히 쉬게 됐다며 고마워해요.","이제 아뮬렛이 다시 합쳐졌대요.","하지만 가장 어려운 시험이 남아서 재료를 더 가져오래요."},nx=8994,nt="Final Preparations"},
[8990]={a={"이살리엔은 목걸이 조각의 비밀을 풀러 혈투의 전장에 갔대요.","그녀는 칼날바람 알진의 무리에게 매복당했대요.","이살리엔의 영혼을 불러내 처치해 달래요."},c={"보들리는 이살리엔의 영혼을 쉬게 해 줘서 고맙대요.","목걸이도 다시 맞췄대요.","군주 발타라크를 부르려면 더 모을 게 있대요."},nx=8994,nt="Final Preparations"},
[8991]={a={"자리엔과 소도스는 용병단이 해산하자 붉은 십자군에 들어갔대요.","들은 바로는 십자군사령관 다스로한에게 죽임을 당했대요.","부름의 화로로 두 사람을 불러내고 오른쪽 조각을 되찾아 달래요."},c={"보들리는 두 사람이 편히 쉬게 된 게 다행이래요.","이제 아뮬렛이 다시 합쳐졌대요.","그래도 가장 어려운 시험이 남아서 재료를 더 가져오래요."},nx=8994,nt="Final Preparations"},
[8992]={a={"코르모크는 강령술에 빠진 뒤로 다들 무서워했대요.","그는 아뮬렛 조각을 들고 스칼로맨스로 돌아갔대요.","부름의 화로로 그를 불러내 처치해 달래요."},c={"보들리는 코르모크가 편히 쉬기를 바란대요.","이제 아뮬렛이 완성됐대요.","하지만 가장 어려운 시험이 남아서 재료를 더 가져오래요."},nx=8994,nt="Final Preparations"},
[8994]={a={"보들리는 거의 다 왔다며 마지막 재료를 찾고 있대요.","필요한 금속은 검은바위 첨탑 오크들의 팔보호구에 있대요.","검은바위 팔보호구와 강력한 마력의 영약을 가져다 달래요."},c={"보들리는 팔보호구에서 금속을 뽑아 화로에 넣겠대요.","그러면 군주 발타라크를 부를 준비가 끝난대요.","그다음 발타라크의 영혼에게 아뮬렛을 돌려줄 수 있대요."},nx=8995,nt="Mea Culpa, Lord Valthalak"},
[8995]={a={"보들리는 모든 준비가 끝났다며 발타라크를 부르라고 해요.","발타라크가 예전에 살던 방은 검은바위 첨탑 위층이래요.","부름의 화로로 발타라크를 불러내 다시 쓰러뜨려 달래요."},c={"당신은 원래 도둑 무리가 아니라서 다행이래요.","내 것을 되찾겠다며 아뮬렛을 달라고 해요."},nx=8996,nt="Return to Bodley"},
[8996]={a={"발타라크의 영혼은 당신이 고귀한 일을 했다고 인정했대요.","무례는 이번만 눈감아 준대요.","보들리에게 돌아가 지금은 안전하다고 전해 달래요."}},
[8998]={a={"보들리는 이제 작별이라며 아쉬워해요.","검은바위 첨탑 습격 동료를 기다릴 때 찾아와도 된대요.","오그리마의 모크바르에게 무슨 일이 있었는지 전해 달래요."}},
[9007]={a={"모크바르는 당신의 이야기가 정말 놀랍대요.","당신 덕분에 과거의 실수에서 벗어났대요.","자연의정수 두건과 조끼를 달래요."},c={"모크바르는 당신이 정말 그리울 거래요.","갚을 수 없을지도 모를 빚을 졌대요.","새 머리 방어구와 가슴 방어구를 잘 쓰라고 해요."}},
[9008]={a={"모크바르는 당신의 이야기가 정말 놀랍대요.","당신 덕분에 과거의 실수에서 벗어났대요.","야수추적자 모자와 튜닉을 달래요."},c={"모크바르는 당신이 정말 그리울 거래요.","갚을 수 없을지도 모를 빚을 졌대요.","새 머리 방어구와 가슴 방어구를 잘 쓰라고 해요."}},
[9009]={a={"모크바르는 당신의 이야기가 정말 놀랍대요.","당신 덕분에 과거의 실수에서 벗어났대요.","기원의 관과 기원의 로브를 달래요."},c={"모크바르는 당신이 정말 그리울 거래요.","갚을 수 없을지도 모를 빚을 졌대요.","새 머리 방어구와 가슴 방어구를 잘 쓰라고 해요."}},
[9010]={a={"모크바르는 큰일을 해낸 당신에게 고마워하고 있어요.","당신 덕분에 과거의 실수에서 벗어날 수 있었대요.","당신이 받을 만한 보상을 준비했으니 와 달래요."},c={"모크바르는 당신이 그리울 거래요.","갚기 어려운 큰 빚을 졌다고 해요.","새 방어구가 오래 지켜 주기를 바란대요."}},
[9011]={a={"모크바르는 큰일을 해낸 당신에게 고마워하고 있어요.","당신 덕분에 과거의 실수에서 벗어날 수 있었대요.","당신이 받을 만한 보상을 준비했으니 와 달래요."},c={"모크바르는 당신이 그리울 거래요.","갚기 어려운 큰 빚을 졌다고 해요.","새 방어구가 오래 지켜 주기를 바란대요."}},
[9012]={a={"모크바르는 정말 놀라운 이야기라며 고마워해요.","당신 덕분에 과거의 실수에서 벗어났다고 해요.","공포의안개 복면과 로브를 가져다 달래요."},c={"모크바르는 당신을 많이 그리워할 거래요.","당신에게 진 빚은 갚기 어려울지도 모른대요.","받은 머리와 가슴 방어구가 오래 지켜 주길 바란대요."}},
[9013]={a={"모크바르는 큰일을 해낸 당신에게 고마워하고 있어요.","당신 덕분에 과거의 실수에서 벗어날 수 있었대요.","당신이 받을 만한 보상을 준비했으니 와 달래요."},c={"모크바르는 당신이 그리울 거래요.","갚기 어려운 큰 빚을 졌다고 해요.","새 방어구가 오래 지켜 주기를 바란대요."}},
[9014]={a={"모크바르는 큰일을 해낸 당신에게 고마워하고 있어요.","당신 덕분에 과거의 실수에서 벗어날 수 있었대요.","당신이 받을 만한 보상을 준비했으니 와 달래요."},c={"모크바르는 당신이 그리울 거래요.","갚기 어려운 큰 빚을 졌다고 해요.","새 방어구가 오래 지켜 주기를 바란대요."}},
[9015]={a={"팔린은 깃발을 쓰려면 검은바위 나락의 법의 심판장에 가라고 해요.","대법관 그림스톤에게 선고를 받고 깃발을 땅에 꽂으래요.","목적을 이루면 안시온에게 돌아가라고 해요."},c={"안시온은 아뮬렛 조각을 되찾았냐고 물어요."}},
[9016]={a={"안시온 하몬은 이 목걸이에 군주 발타라크의 영혼이 담겼대요.","욕심에 목걸이를 세 조각 냈는데 저주가 따라왔대요.","모크바르에게 가서 보들리가 남은 조각을 찾을 희망이라 전해 달래요."},c={"모크바르는 고작 목걸이 하나 때문에 저주를 받았대요.","군주 발타라크는 원한을 오래 품는다고 해요.","남은 조각은 찾아보겠지만 먼저 보상부터 챙겨 준대요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9017]={a={"안시온 하몬은 이 목걸이에 군주 발타라크의 영혼이 담겼대요.","욕심에 목걸이를 세 조각 냈는데 저주가 따라왔대요.","모크바르에게 가서 보들리가 남은 조각을 찾을 희망이라 전해 달래요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9018]={a={"안시온 하몬은 이 목걸이에 군주 발타라크의 영혼이 담겼대요.","욕심에 목걸이를 세 조각 냈는데 저주가 따라왔대요.","모크바르에게 가서 보들리가 남은 조각을 찾을 희망이라 전해 달래요."},c={"모크바르는 고작 목걸이 하나 때문에 저주를 받았대요.","군주 발타라크는 원한을 오래 품는다고 해요.","남은 조각은 찾아보겠지만 먼저 보상부터 챙겨 준대요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9019]={a={"안시온 하몬은 이 목걸이에 군주 발타라크의 영혼이 담겼대요.","욕심에 목걸이를 세 조각 냈는데 저주가 따라왔대요.","모크바르에게 가서 보들리가 남은 조각을 찾을 희망이라 전해 달래요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9020]={a={"안시온 하몬은 이 목걸이에 군주 발타라크의 영혼이 담겼대요.","욕심에 목걸이를 세 조각 냈는데 저주가 따라왔대요.","모크바르에게 가서 보들리가 남은 조각을 찾을 희망이라 전해 달래요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9021]={a={"안시온은 아뮬렛에 발타라크의 영혼이 담겼다고 해요.","욕심에 조각내서 나눴고, 다시 맞춰야 저주가 멈춘대요.","모크바르에게 공포의안개 신발과 다리보호구, 어깨보호대를 가져가래요."},c={"모크바르는 고작 아뮬렛 하나 때문에 저주를 받았다고 해요.","발타라크는 원한을 오래 품는다고 해요.","나머지 조각을 찾겠지만 먼저 보상을 챙겨 주겠대요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9022]={a={"안시온 하몬은 이 목걸이에 군주 발타라크의 영혼이 담겼대요.","욕심에 목걸이를 세 조각 냈는데 저주가 따라왔대요.","모크바르에게 가서 보들리가 남은 조각을 찾을 희망이라 전해 달래요."},nx=9032,nt="Bodley's Unfortunate Fate"},
[9023]={a={"더크 썬더우드는 형제와 함께 라벤홀트에서 독을 다룬대요.","라벤홀트 경이 새 독을 찾으라고 시켰대요.","쿠린낙스와 베녹시스의 독주머니를 가져다 달래요."}},
[9032]={a={"아뮬렛에 발타라크의 영혼이 있어서 저주가 강했대요.","보들리는 검은바위 첨탑에 간 뒤로 소식이 없대요.","초차원 유령 계시기로 검은바위 산에서 보들리를 찾래요."},c={"드디어 말할 상대가 생겼다며 보들리가 반가워해요.","잘못을 바로잡도록 도와 달라고 부탁해요.","가운데 조각을 가졌다면 나머지 두 조각을 알려 주겠대요."},nx=8961,nt="Three Kings of Flame"},
[9033]={a={"사령관 엘리고르 돈브링어는 마지막 전쟁 뒤에도 위협이 남았대요.","리치 왕이 다시 움직여 켈투자드가 군대를 모으고 있대요.","낙스라마스에 들어가 스컬지를 없애 달라고 부탁해요."},c={"잘했다며 희망의 빛 예배당에서 보상해 준대요."},nx=9229,nt="The Fate of Ramaladni"},
[9051]={a={"토르와 패스파인더는 당신과 함께 독을 만들었대요.","분화구의 데빌사우루스 때문에 사냥이 위험하대요.","독이 묻은 가시로 데빌사우루스를 진정시켜 달래요."},nx=9053,nt="A Better Ingredient"},
[9052]={a={"토르와 패스파인더가 분화구의 큰 짐승을 진정시킬 독을 만들려 해요.","독은 죽이지 않고 재료는 분화구 곳곳에 있대요.","필요한 재료를 모아 다시 와 달래요."},nx=9051,nt="Toxic Test"},
[9053]={a={"토르와 패스파인더는 독이 너무 약하다고 걱정해요.","재료는 가라앉은 사원 하층부 수호병이 가진 썩은 덩굴이래요.","위험하니 동료와 함께 가서 썩은 덩굴을 구해 와 달래요."}},
[9063]={a={"투락 룬토템은 사냥꾼 토르와 패스파인더의 부탁을 전해요.","자연을 존중하는 드루이드만 그를 도울 수 있대요.","운고로 분화구로 가는 길 근처에서 그를 찾아보래요."},c={"토르와 패스파인더는 멀리서 찾아와 줬다고 해요.","때맞춰 와서 다행이라고 해요."},nx=9052,nt="Bloodpetal Poison"},
[9085]={a={"사령관 토마스 헬러랜은 소환 마법진을 지키는 수행사제가 있대요.","사실 이들은 사람이 아니라 리치 왕의 그림자래요.","파멸의 망령을 찾아 처치하고 헬러랜에게 돌아가 달래요."},c={"헬러랜은 그림자들이 사라졌다며 잘했다고 칭찬해요.","리치 왕이 언젠가 손을 거두면 평화가 올 거래요."}},
[9120]={a={"이 성물함은 낙스라마스 주인이 남긴 유일한 물건이래요.","이걸 부수면 리치가 다시 살아나지 못한대요.","동부 역병지대 희망의 빛 예배당에 가져가면 큰 보상이 있대요."}},
[9121]={a={"역병의 숲 속에 낙스라마스로 가는 입구가 있대요.","비전 은신 마법으로 들어갈 수 있지만 비용이 많이 든대요.","재료를 가져오면 그 은신 마법을 걸어 주겠대요."},c={"안젤라는 마법이 걸리면 약간 저릿한 느낌이 날 거래요.","그 뒤로는 역병의 숲 룬 차원문을 밟아 낙스라마스에 들어갈 수 있대요."},nx=9033,nt="Echoes of War"},
[9122]={a={"역병의 숲 속에 낙스라마스로 가는 입구가 있대요.","은빛 여명회에 헌신한 덕에 비용 일부를 내 준대요.","재료를 가져오면 은신 마법을 걸어 주겠대요."},c={"안젤라는 마법이 걸리면 약간 저릿한 느낌이 날 거래요.","그 뒤로는 역병의 숲 룬 차원문을 밟아 낙스라마스에 들어갈 수 있대요."},nx=9033,nt="Echoes of War"},
[9123]={a={"역병의 숲 속에 낙스라마스로 가는 입구가 있대요.","은빛 여명회에 헌신한 당신에게 비용을 받지 않겠대요.","비전 은신 마법을 공짜로 받으러 와 달래요."},c={"안젤라는 마법이 걸리면 약간 저릿한 느낌이 날 거래요.","그 뒤로는 역병의 숲 룬 차원문을 밟아 낙스라마스에 들어갈 수 있대요."},nx=9033,nt="Echoes of War"},
[9124]={a={"사냥꾼 레오폴드는 지하추적자 갑옷을 만들어 준대요.","그런데 늘 지하마귀 발톱이 모자란대요.","지하마귀 발톱을 가져오면 병참장교에게 쓸 휘장을 주겠대요."},c={"레오폴드는 이 정도면 됐다며 발톱을 받았대요.","발톱은 언제든 더 받으니 가져오래요."}},
[9126]={a={"암살자 로한은 돈 훌리오의 해골사신 갑옷에 뼈 조각이 필요하대요.","낙스라마스에 가는 이들이 재료는 주지만 스컬지 해골 조각이 부족하대요.","스컬지를 해치우면서 해골 조각을 모아 달래요."}},
[9128]={a={"대마법사 안젤라는 고용한 사람들에게 휘장을 대가로 줘요.","휘장은 병참장교에게 가져가면 귀한 물건을 살 수 있대요.","세계 곳곳의 정령에게서 정령의 정수를 최대한 가져다 달래요."},c={"안젤라는 잘했다며 약속한 휘장을 줬대요.","휘장은 얼마든지 더 있다며 또 오라고 해요."}},
[9131]={a={"빛의 용사 코팩스는 우리 용사들에게 줄 장비가 필요해요.","그 장비에는 검은무쇠 조각이 많이 필요하대요.","검은무쇠 조각을 가져다주면 보상을 하겠대요."},c={"빛의 용사 코팩스는 이 정도면 됐대요.","더 구해 오면 자기를 찾아오라고 해요."}},
[9136]={a={"레이네는 낙스라마스로 가는 용사들에게 방어구를 만들어 줘요.","그런데 방어구에 쓸 야생 잎사귀가 늘 부족하대요.","이 세계 식물에서 야생 잎사귀를 구해 와 달래요."},c={"레이네가 고맙다며 고개를 숙여요.","야생 잎사귀는 언제든 더 필요하대요."}},
[9141]={a={"파견사령관 메츠는 최전선의 작업 주문을 맡고 있어요.","장인들이 서로 일을 맡으려고 경쟁이 치열해요.","작업 주문을 받으려면 명예 휘장을 가져오래요."},c={"휘장을 가져오면 메츠가 주문서를 다시 준대요.","그 주문서의 일은 짐말주인 스톤브루저에게 전하래요."}},
[9153]={a={"사령관 토마스 헬러랜은 하늘을 떠다니는 죽음의 요새를 걱정해요.","요새가 호드와 얼라이언스의 땅에 역병을 퍼뜨리고 있대요.","요새에 힘을 대는 마법진 주변의 스컬지를 물리쳐 달래요."},c={"사령관 토마스 헬러랜은 잘했다며 칭찬했어요.","앞으로도 전선에 나가 싸워야 한대요.","죽음의 룬을 더 가져오면 특별한 물건과 바꿔 준대요."}},
[9154]={a={"은빛 여명회 징병관이 땅을 지킬 사람을 모집해요.","스컬지가 전보다 더 많이 돌아와서 사람이 필요해요.","징병 통지서를 희망의 빛 예배당 기록 보관원에게 전해 달래요."},c={"기록 보관원은 나도 부름에 응한 사람 중 하나래요.","기록 보관원은 훈련할 시간은 없지만 실력을 믿는대요."}},
[9229]={a={"빛의 용사 코팩스가 옛 전사 Ramaladni의 이야기를 해요.","Ramaladni는 복수심에 휩싸여 낙스라마스로 들어갔대요.","낙스라마스에 가서 Ramaladni에게 무슨 일이 있었는지 알아 달래요."},c={"코팩스는 Ramaladni의 반지를 찾았지만 망가졌대요.","다른 흔적은 못 찾아서 상황이 좋지 않대요.","그래도 반지는 고칠 수 있을지도 모른대요."},nx=9230,nt="Ramaladni's Icy Grasp"},
[9230]={a={"빛의 용사 코팩스는 Ramaladni의 반지를 고치려 해요.","이 반지는 낙스라마스 같은 스컬지 건물의 룬으로 만들어졌대요.","얼어붙은 룬 같은 재료를 가져오면 고쳐 주겠대요."}},
[9232]={a={"기능공 빌헬름은 낙스라마스에서 버틸 수 있을지 걱정해요.","오마리온에게 받은 바지 제작법은 이것 하나뿐이래요.","재료만 가져오면 바지를 몇 가지 만들어 주겠대요."},c={"기능공 빌헬름은 힘든 작업이었다며 땀을 닦아요.","바지를 잘 입으라고 해요."}},
[9233]={a={"오마리온은 죽어 가면서도 빌헬름의 실력을 걱정했대요.","이 안내서에는 오마리온 비법의 나머지가 적혀 있대요.","안내서를 기능공 빌헬름에게 가져다 달래요."},c={"빌헬름은 오마리온이 이 글을 쓸 때 제정신이 아니었다고 해요.","이제 더 많은 물건을 만들 수 있게 됐대요.","대신 수수료와 재료비는 따로 받는대요."}},
[9234]={a={"기능공 빌헬름은 이제 얼음막이 건틀릿을 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9235]={a={"기능공 빌헬름은 이제 얼음막이 팔보호구를 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9236]={a={"기능공 빌헬름은 이제 얼음막이 흉갑을 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9237]={a={"기능공 빌헬름이 빙하의 망토를 만들 수 있게 됐어요.","오마리온이 남긴 비법 덕분이래요.","재료와 제작비를 가져오면 만들어 준대요."},c={"기능공 빌헬름이 주문한 망토를 약속대로 내줘요."}},
[9241]={a={"기능공 빌헬름은 이제 북극의 팔보호구를 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9242]={a={"기능공 빌헬름은 이제 북극의 장갑을 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9243]={a={"기능공 빌헬름은 이제 북극의 튜닉을 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9244]={a={"기능공 빌헬름은 이제 얼어붙은 미늘 팔보호구를 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9245]={a={"기능공 빌헬름은 이제 얼어붙은 미늘 건틀릿을 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9246]={a={"기능공 빌헬름은 이제 얼어붙은 미늘 흉갑을 만들 수 있게 됐대요.","당신과 Omarion 덕분에 만들 수 있게 됐대요.","재료와 수수료를 가져와 달래요."},c={"빌헬름이 약속한 주문품을 건네줬대요."}},
[9248]={a={"오렐 골드리프는 심연의 군주가 죽었다는 증거를 원해요.","증거를 보여 주면 퀴라지와 싸울 때 도울 물건을 준대요.","심연의 홀을 가져다 달래요."}},
[9250]={a={"아티쉬의 몸통이 거의 완성됐어요.","지팡이의 나머지 부분이 아직 없어요.","나머지 조각을 찾고 악마를 쫓아낼 조력자를 찾아 달래요."},c={"아나크로노스는 대마법사들이 죽었다며 애도하지 말래요.","모든 일은 운명이었다고 해요.","수호자의 지팡이를 든 것도 운명이래요."},nx=9251,nt="Atiesh, the Befouled Greatstaff"},
[9251]={a={"아나크로노스는 지팡이가 아주 사악한 물건이라고 해요.","켈투자드가 낙스라마스에서 지팡이를 노린대요.","아티쉬의 밑동이 안퀴라즈에 있으니 찾아 달래요."},c={"아나크로노스는 지팡이 안에 이 세상의 것이 아닌 존재가 있대요."}},
[9257]={a={"시간의 동굴의 아나크로노스가 마지막 부탁을 해요.","지팡이를 조종하는 악마는 살게라스의 손이래요.","스트라솔름의 봉헌된 땅에 지팡이를 놓아 달래요."},c={"아나크로노스는 불가능해 보이던 일을 당신이 해냈다고 해요.","운명이었다며 지팡이가 스스로 선택을 했대요."}},
[9263]={a={"부관 다겔이 오그리마 코앞의 스컬지를 걱정해요.","바깥에 이상한 마법진이 빛나는데 역할을 모른대요.","마법진을 알아보고 스컬지도 처치해 달래요."},c={"부관 다겔은 마법진 속 목소리가 소통용인 것 같대요.","당신이 무사하고 정신도 멀쩡해 보인대요."}},
[9264]={a={"부관 리산데가 썬더 블러프 코앞의 스컬지를 걱정해요.","바깥에 이상한 마법진이 빛나는데 역할을 모른대요.","마법진을 알아보고 스컬지도 처치해 달래요."},c={"부관 리산데는 마법진 속 목소리가 소통용인 것 같대요.","당신이 무사하고 정신도 멀쩡해 보인대요."}},
