[9362]={a={"대마법사 실렘은 탑에서 나갈 수 없어 부탁해요.","크렐리안 장군이 강한 마력의 유물을 가졌대요.","진말로의 신전에서 그를 처치하고 프리즘 껍질을 가져와 달래요."},c={"대마법사 실렘은 이 껍질에서 이상한 기운이 느껴진대요.","껍질의 마력을 시험해 보는 게 보상이라고 해요."},nx=9364,nt="Fragmented Magic"},
