[65593]={a={"고드릭 파선은 악마를 꾈 미끼를 찾고 있어요.","Avelina Lilly와 Isaac Pearson은 서로 그리워해요.","두 사람의 마음을 카렌딘 할가르에게 가져다 달래요."},c={"역시 예상대로래요. 잘해 줬어요, 모험가 씨.","둘 다 바보라고 하네요."},nx=65597,nt="The Binding"},
[65597]={a={"카렌딘 할가르가 드디어 소환 준비를 마쳤어요.","심장을 소환진 가운데 놓으면 악마가 나온대요.","악마를 제압해야 속박 주문을 가르쳐 준대요."},c={"시련에도 무너지지 않았으니 대단하다고 해요.","이제 악마를 부르는 주문을 가르쳐 준대요."}},
[65601]={a={"사랑과 헌신이 담긴 물건으로 악마를 꾀어야 한대요.","오그리마에 사는 마가르는 짝 Krilge가 돌아오길 바라요.","마가르를 찾아가 소중한 물건을 찾아 달래요."},c={"마가르는 Krilge 얘기를 누구한테 들었냐고 물어요.","소식이 있냐고 묻고, 놀리지 말라고 경고해요."},nx=65610,nt="Wish You Were Here"},
