[77669]={a={"데이비드 트리아스가 도적은 기회를 놓치지 않는다고 해요.","동쪽에서 싸우는 적들이 신비로운 룬을 받았대요.","룬 하나를 훔쳐 마법을 익혀 데이비드에게 돌아오래요."}},
[77670]={a={"어둠의사제 듀스텐이 산 자의 기억을 떠올려 준대요.","교회 옆 묘지에서 한기가 가장 강한 곳을 찾으래요.","그곳에 무릎 꿇고 죽음의 신비에 대해 명상해 달래요."}},
[77671]={a={"이자벨라가 마법 연구를 도와 달라고 해요.","데스넬 근처에 진 친 적 견습생들이 마법 노트를 갖고 있대요.","그 노트를 빼앗아 마법을 익혀 이자벨라에게 돌아오래요."}},
[77672]={a={"맥시밀리언이 새로운 마법 룬을 실험하고 있대요.","견습생이 검은그물 거미굴에 갔다가 돌아오지 않았대요.","거미줄에서 룬을 찾아 익힌 뒤 맥시밀리언에게 보고하래요."}},
[78150]={c={"Owen Thadd는 기부 덕분에 도서관이 잘된다고 해요.","보답으로 이걸 받으라고 해요."}},
[78261]={a={"쪽지에 C라는 사람이 의뢰를 적어 뒀어요.","그 뿔은 그림자송곳니 성채 안에 있대요.","혼자 가서 뿔을 장작나무 마을 근처 은밀한 장소에 두래요."},nx=78307,nt="The Horn of Xelthos"},
[78676]={a={"쪽지에 C가 또 새 의뢰를 적어 뒀어요.","이번 물건은 붉은십자군 수도원 안에 있대요.","혼자 몰래 들어가 가져와 장작나무 마을에 두래요."}},
[78681]={a={"Des'Altek이 감옥을 벗어났지만 아직 묶여 있대요.","악마를 불러내 그 영혼을 다시 사로잡아야 한대요.","잿빛 골짜기 악마들에게서 특별한 피를 모아 오래요."}},
[78684]={a={"낯선 사람이 비틀거리며 여기가 어디냐고 물어요.","그는 무슨 일이 있었는지 함께 알아보자고 해요.","도안 카르한에게 가서 얘기해 보자고 권해요."}},
[78823]={a={"이 그림은 거친 선으로 큰 사나운 새를 그렸어요.","그린 사람은 두려움과 경외심을 함께 느꼈던 것 같대요.","가시덤불 골짜기의 헤멧 네싱워리에게 가져가 달래요."},nx=78830,nt="Terror of the Desert Skies"},
[78830]={a={"헤멧 네싱워리가 큰 새 Gharrik 이야기를 들었대요.","그 새를 꾀려면 살아 있는 미끼가 필요하대요.","미끼를 구해 Gharrik의 깃털을 얻어 와 달래요."}},
[78917]={a={"아쿠마이라는 무서운 짐승이 죽었어요.","그 몸속에 공허의 힘이 가득한 거대한 진주가 있었대요.","진주를 썬더 블러프의 바샤나 룬토템에게 가져가 달래요."},c={"옛 신들의 종 아쿠마이가 죽었대요.","진주는 공허를 이해할 열쇠일지 모른대요."}},
[79007]={a={"불씨가 꺼져 가는 자리에서 쪽지를 찾았어요.","쪽지에는 타도 다 잃은 건 아니라고 적혀 있어요.","쌍둥이 땅에서 그곳을 찾으라고 해요."},c={"또 다른 불탄 시신 옆 나무판에 메모가 있었어요."},nx=79192,nt="Stepping Stones"},
[79079]={a={"가엾은 사제 우르쿄가 함께할 신을 못 찾았어요.","그와 거래해 줄 신을 찾기가 어려운 것 같대요.","대신 축복을 내려 줄 수 있을지 물어요."}},
[79080]={a={"신부 랭커스터가 죽음을 생각하는 트롤 이야기를 해요.","트롤은 죽음에 대해 잘 아는 편이 아니래요.","무릎 꿇은 트롤의 이해를 도와 달래요."}},
[79192]={a={"쪽지에는 두 사람이 배달을 하다 사고를 당했대요.","쓴 사람은 단순한 약사 사고로 보인대요.","불모의 땅과 잊혀진 땅 사이 산으로 오라고 해요."},nx=79980,nt="Scramble"},
[79229]={a={"야영지에 사람 둘과 드워프 한 명이 죽어 있었어요.","약탈 흔적이 있어 동물 짓은 아니래요.","잊혀진 땅에서 이 일을 아는 사람을 찾아 달래요."},c={"아, 또 하나 찾았군요."},nx=79235,nt="On the Lam"},
[79235]={a={"비블리 푸츠버클이 비슷한 야영지도 찾았대요.","소문에는 호드 약탈자들이 저질렀대요.","무법항에서 그들을 찾아보래요."},nx=79236,nt="Cherry for Your Thoughts?"},
[79236]={a={"Tokal은 떠도는 소문이 절반만 맞다고 해요.","사람과 드워프의 야영지를 털었지만 호드 때문은 아니래요.","체리 그로그주를 사 주면 전부 들려준대요."},nx=79242,nt="No Honor Among Thieves"},
[79242]={a={"Tokal의 우두머리는 호드가 아니었대요.","정보를 주고 전리품도 대부분 가지게 했대요.","아라시 고원 해안의 은신처를 찾아보래요."},c={"창고 안에서 작은 상자와 동전을 찾았어요."}},
[79360]={a={"라우 클리프러너는 원소에게 받은 은혜를 갚을 때래요.","quilboar가 원소를 비틀어 세력을 넓히고 있대요.","가시덩굴 우리에 가서 그 계획을 막아 달래요."},c={"바스라는 쪽지 말대로 준비가 들키지 않았대요.","centaur와 harpies 때문에 순찰을 못 했대요.","알려 줘서 고맙지만 도움이 더 필요하대요."},nx=79364,nt="Eyes on the Sky"},
[79361]={a={"quilboar가 버섯구름 봉우리를 물에 잠기게 하려 한대요.","이 땅의 생명들이 그런 일을 겪으면 안 된대요.","그래서 뒤틀린 원소 토템들을 모아 달래요."},nx=79366,nt="Heed My Call"},
[79362]={a={"Grant Valor의 유령이 남긴 방패가 있대요.","그를 다치게 한 적이 까마귀 언덕 묘지에 있대요.","해골 중 하나에 박힌 mace를 찾아 달래요."},c={"시라 본인디는 Grant Valor도 하찮은 적에게 당했대요.","한 번 실수하면 평생 불구가 될 수 있대요.","무기는 주인에 대해 많은 걸 말해 준대요."}},
[79363]={a={"Silvia Valor의 유령이 남긴 검이 있대요.","그녀의 못다 한 일은 Defias를 쫓는 것일지도 모른대요.","그러니 그 Defias 무리를 몰아내 달래요."},c={"시라 본인디는 Silvia Valor가 훌륭했지만 시야가 좁았대요.","그녀가 무엇을 원했을지는 확실하지 않대요.","Defias를 물리친 건 좋은 시작이래요."}},
[79364]={a={"쪽지에 Razormane가 버섯구름 봉우리에 숨었대요.","물에 잠기게 하려면 엄청난 원소 힘이 필요하대요.","프레이트 클라우드시어에게 가서 답을 찾아봐 달래요."},nx=79361,nt="Storm, Earth, and Fire"},
[79365]={a={"바스라가 Squall-breakers Potion을 줬대요.","그 효과는 잠깐이지만 폭풍에서 몸을 지켜 준대요.","도움이 필요한 라우 클리프러너에게 돌아가 달래요."},c={"라우 클리프러너는 wind riders가 뭔가 찾았지만 못 다가갔대요.","도움 될 만한 걸 찾았는지 묻는대요."}},
[79366]={a={"라우 클리프러너는 이제 뒤틀린 토템을 쓸 때라고 해요.","quilboar가 부른 타락한 원소들을 물리쳐야 한대요.","서쪽 증기 웅덩이에서 원소를 정화해 달래요."},c={"높새바람 봉우리로 돌아가 결과를 보고해 달래요."},nx=79442,nt="The Tempest's Weapons"},
[79442]={a={"라우 클리프러너는 이 눈을 쓸 데가 없대요.","알터랙 산맥의 늙은 주술사가 폭풍 마법에 밝대요.","바스라에게 눈을 전해 달래요."},c={"바스라는 이제 속임수는 그만두자고 해요.","그 눈을 주면 새 기술을 가르칠 룬을 주겠대요.","어떻게 할 거냐고 묻대요."}},
[79483]={a={"케이말드 코퍼핀치네 Smokywood Pastures가 간식을 잃었대요.","조사하러 나간 직원도 알터랙 산맥에서 사라졌대요.","눈 덮인 곳에서 둘 다 무사한지 찾아 달래요."},nx=79485,nt="You're a Mean One..."},
[79495]={a={"케이말드 코퍼핀치의 순록 멧젠이 납치됐대요.","몸값을 요구하는 편지가 왔대요.","멧젠을 찾아 순록 가루를 뿌려 풀어 달래요."}},
[79501]={a={"겨울 명절에 holly는 금방 상해 버린대요.","보관 기계로 오래 두면 여름에도 팔 수 있대요.","요리 고수라면 deeprock salt와 금을 가져와 보래요."}},
[79502]={a={"겨울 명절에 holly는 금방 상해 버린대요.","보관 기계로 오래 두면 여름에도 팔 수 있대요.","요리 고수라면 deeprock salt와 금을 가져와 보래요."}},
[79624]={a={"알아볼 수 없는 요리법이 손에 들어왔어요.","당신이 모르는 언어로 적힌 고기 요리법이에요.","Ogre라면 읽을 수 있을지 모른대요."},nx=79677,nt="A Quick Grocery Run"},
[79677]={a={"Skonk은 덩치가 작다고 놀림받았대요.","그래서 요리를 배웠는데 놀림만 더 받았대요.","요리를 하려면 재료가 필요하니 구해 달래요."},nx=79678,nt="Taste Testing"},
[79678]={a={"Skonk은 새 요리를 새 친구와 나누고 싶대요.","불을 피워 놓고 기다리고 있대요.","맛보기 준비가 되면 알려 달래요."}},
[79731]={a={"고대 두루마리에 글이 떠올라 수수께끼가 보여요.","Zul'Kunda의 샘물이 성스러운 물로 차면 축복이 내린대요.","그 수수께끼를 풀어 헤멧 네싱워리에게 알려 달래요."},c={"헤멧 네싱워리는 정글 속 샘 이야기에 신이 났대요.","그의 책에 넣을 새 장의 아이디어가 떠올랐대요.","원고를 어디 뒀는지 찾고 있대요."}},
[79974]={a={"흙무더기가 비상용 물자를 숨겨 뒀대요.","산비탈에 독수리 둥지가 있다고 해요.","독수리 둥지 근처에서 숨긴 물건을 찾아 달래요."},nx=79975,nt="Eagle's Fist"},
[79975]={a={"도구 상자 안에 접힌 편지가 있었어요.","여긴 낙하산 활공하기 좋은 곳이래요.","이 방벽을 끝까지 지키겠다고 적혀 있어요."},nx=79976,nt="This Must Be The Place"},
[79976]={a={"가방 주인은 일을 땅속으로 다시 가져가기로 했대요.","잘못된 손에 넘어가지 않게 하려는 거래요.","이 쪽지가 다음 은신처 힌트일지도 모른대요."},c={"여러 장비 위에 무거운 천이 덮여 있었어요.","배낭을 챙겼어요."}},
[79980]={a={"쪽지를 읽었다면 숨겨 둔 물자가 아직 있대요.","곧장 북쪽으로 가면 물자가 있대요.","가파른 절벽을 조심해 내려가라고 해요."},c={"땅에서 메신저 가방을 꺼냈어요.","물자 사이에 더러운 양피지가 끼어 있었어요."},nx=79974,nt="Wet Job"},
[80325]={a={"낡고 찢어진 공책을 주웠어요.","설계도가 빼곡한데 만들면 큰 피해가 날 수 있대요.","오그리마의 Nogg에게 가져다 달래요."}},
[80411]={a={"가로챈 편지에 Caius가 원하는 마지막 유물이 있대요.","그 부적은 줄파락 안에 있대요.","혼자 가서 찾아 먼저 파라드에게 가져오래요."}},
[80453]={a={"파라드가 Caius를 노리는 장치를 준비했대요.","마법 에너지를 넣거나 빼려 하면 터진대요.","Talisman of Kazdor를 잰 쉬브스프로켓에게 가져다 달래요."}},
[80454]={a={"잰 쉬브스프로켓은 미끼가 준비됐다고 해요.","파라드의 지시대로 부적을 개조했대요.","장작나무 마을 근처 Caius의 비밀 전달함에 넣어 달래요."}},
[80526]={a={"파라드는 'C'가 Caius Blackwood라고 알아냈대요.","Caius Blackwood는 Syndicate와 손잡은 마법사래요.","Caius를 막을 계획이 있으니 들으러 오래요."},nx=80411,nt="The Talisman of Kazdor"},
[81570]={a={"\"늪지눈알\" 자를은 칼이 꼭 필요하대요.","꼭 달의 강철 브로드소드여야 한대요.","먼지진흙 습지대의 \"늪지눈알\" 자를에게 가져다 달래요."},c={"좋은 칼이래요. 정말 고맙대요!","지금은 못 쓰고 나중에 휘둘러 봐야겠대요."}},
[81730]={a={"Field Captain Palandar가 그늘숲에서 급한 일을 맡겼어요.","Emerald Dream이 나이트메어로 변하고 있대요.","Rotting Orchard에서 싸우고 돌아와 달래요."}},
[81731]={a={"Field Captain Palandar가 그늘숲에서 급한 일을 맡겼어요.","Emerald Dream이 나이트메어로 변하고 있대요.","Vul'gol Ogre Mound에서 싸우고 돌아와 달래요."}},
[81732]={a={"Field Captain Palandar가 그늘숲에서 급한 일을 맡겼어요.","Emerald Dream이 나이트메어로 변하고 있대요.","Yorgen Farmstead에서 싸우고 돌아와 달래요."}},
[81733]={a={"Field Captain Palandar가 그늘숲에서 급한 일을 맡겼어요.","Emerald Dream이 나이트메어로 변하고 있대요.","Dreamwarden Thalinar에게 정보를 받아 오래요."}},
[81734]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Emerald Dream이 악몽으로 변하고 있대요.","Dreamwarden Dorilar에게 정보 보고서를 받아 달래요."}},
[81735]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Emerald Dream이 악몽으로 변하고 있대요.","Dreamwarden Amalia에게 정보 보고서를 받아 달래요."}},
[81736]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Emerald Dream이 악몽으로 변하고 있대요.","강력한 유물 Shadowscythe를 가져다 달래요."}},
[81737]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Emerald Dream이 악몽으로 변하고 있대요.","Ogre Magi Text을 찾아 가져다 달래요."}},
[81738]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Emerald Dream이 악몽으로 변하고 있대요.","아직 부화하지 않은 녹색 용의 알을 가져다 달래요."}},
[81739]={a={"Field Captain Palandar가 악마들과 싸우고 있대요.","그 사이 꿈의 세계가 악몽으로 물들고 있대요.","그늘숲 나이트메어 구역에서 나이트메어 Moss를 모아 달래요."}},
[81740]={a={"Field Captain Palandar가 악마들과 싸우고 있대요.","그 사이 꿈의 세계가 악몽으로 물들고 있대요.","광부의 도움을 받아 그늘숲에서 철 광석을 모아 달래요."}},
[81741]={a={"Field Captain Palandar가 악마들과 싸우고 있대요.","그 사이 꿈의 세계가 악몽으로 물들고 있대요.","그늘숲 나이트메어 구역 용족에게서 비늘을 모아 달래요."}},
[81742]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Yorgen Farmstead에 드래곤 Ylanthrius가 있대요.","그 드래곤을 쓰러뜨려 달래요."}},
[81743]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Vul'gol Ogre Mound 깊은 곳에 오우거 군주가 있대요.","오우거 군주 Vvarc'zul을 쓰러뜨려 달래요."}},
[81744]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Rotting Orchard 캠프에 늑대인간 우두머리가 있대요.","늑대인간 우두머리 Amokarok을 쓰러뜨려 달래요."}},
[81745]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Rotting Orchard에 잠든 드루이드가 있대요.","잠든 드루이드 Kroll Mountainshade를 찾아 호위해 달래요."}},
[81746]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Yorgen Farmstead에 잠든 드루이드가 있대요.","잠든 드루이드 Alara Grovemender를 찾아 호위해 달래요."}},
[81747]={a={"Field Captain Palandar는 악마들에 맞서 싸우고 있어요.","Vul'gol Ogre Mound 근처에 잠든 드루이드가 있대요.","잠든 드루이드 Elenora Marshwalker를 찾아 호위해 달래요."}},
[81885]={a={"도와준 덕분에 큰 위기를 넘겼대요.","옛 친구를 빛의 편으로 되돌릴 수 있을지 모른대요.","Gregory가 의식을 마치도록 도와 달래요."}},
[81900]={a={"오래된 조각에 지옥불을 뿜는 두 머리 짐승이 새겨져 있어요.","광신도들이 이 괴수의 힘을 노리는 것 같대요.","저주받은 땅에서 짐승을 잘 아는 사람을 찾아 달래요."},nx=81917,nt="Chains That Bind"},
[81917]={a={"혈법사 린노어는 Calefactus를 여러 번 본 적이 있대요.","남동쪽의 Shadowsworn은 펠 생명체를 길들이는 의식을 해요.","그 무리에 괴수를 약하게 할 단서가 있을지도 모른대요."}},
[81919]={a={"혈법사 린노어는 네가 찾은 사슬 고리로 올가미를 만들었대요.","이 사슬의 힘은 악마를 묶기에 맞는대요.","Calefactus를 잡고 fel lifeblood를 가져다 달래요."}},
[81924]={a={"Tyrisius는 Kaldorei 지식이 폐허에는 없다고 해요.","대신 아즈샤라, Hinterlands, 페랄라스의 수호 영혼이 남았대요.","그 신당에서 자신을 증명하고 지혜를 받아 오래요."}},
[82062]={a={"믿을 만한 사람인지 확인해야 했대요.","호드와 얼라이언스 모르게 어두운 세력이 자라고 있대요.","곧 힘을 모아 보여 줄 때가 온대요."}},
[82084]={a={"Owen Thadd는 마법 솜씨가 훌륭하다고 해요.","이제 직접 마법서를 쓸 준비가 됐다고 봐요.","마법서에 쓸 재료를 구해 달라고 해요."}},
[83934]={a={"Pix Xizzix는 형제들과 Kezan에서 왔대요.","해적들이 창업 자금을 훔쳐 가서 돈이 없대요.","잃어버린 코인을 찾아 무법항으로 가져다 달래요."}},
[84135]={a={"해변에 기계 하나가 반쯤 묻혀 있어요.","기계 옆면에 D.E.L.T.A. 소유라고 적혀 있대요.","돌 같은 것으로 기계 일부를 떼어 내면 된대요."}},
[84137]={a={"이 기계가 왜 여기 떨어졌는지 궁금해요.","이 액체로 근처 섬과 석유 시추선에 갈 수 있을지도 모른대요.","이 액체의 쓸 곳을 찾아보래요."}},
[84138]={a={"Sebastian Jurgens는 수석 기술자래요.","자원이 풍부한 차원을 찾는 장치를 만들고 있대요.","여명의 설원에 있는 Nami에게 빌려준 책을 찾아 달래요."}},
[84146]={a={"Nami는 눈망루 마을에서 중요한 도구를 다뤄요.","그 가방을 비행선 사고로 불타는 평원에 잃어버렸대요.","그 빨간 가방을 찾아 가져다 달래요."}},
[84153]={a={"특별한 팔보호구를 일반 팔보호구와 바꿔 준다고 해요.","대신 여명의 설원 짐승들의 피를 가져다 달래요.","팔보호구와 골드를 아이언포지 델리아나에게 가져가래요."}},
