[84171]={a={"믿음직한 사람이라고 칭찬해요.","이 일을 함께 끝까지 하면 나머지도 줄 거래요.","허리띠와 장갑을 가져오면 먼저 바꿔 준대요."}},
[84211]={a={"가방을 주웠는데 거의 비어 있어요.","Nami는 빈 가방만으로는 책과 바꿔 주지 않을 거래요.","캠프에 남은 물건을 더 찾아 눈망루 마을의 Nami에게 가져다 달래요."}},
[84212]={a={"Nami가 Jurgens의 책을 건네줬대요.","그 책을 들고 세상 반대편으로 긴 길을 떠나요.","책을 D.E.L.T.A 연구소로 가져다 달래요."}},
[84318]={a={"Orthas는 부서진 몸을 떠나지 못한 영혼이에요.","아직 끝내지 못한 일이 남아 있대요.","그래서 자기 망치를 찾아 달라고 부탁해요."}},
[84319]={a={"Orthas는 예전에 산 아래의 높은 영주였대요.","조상 대대로 내려온 갑옷이 누더기골렘 뱃속에서 녹고 있대요.","역병의 숲에서 누더기골렘 시체의 갑옷을 찾아 달래요."}},
[84332]={a={"작은 상자에 손을 대니 목소리가 들려요.","쓸모없어진 물건을 주니 서운해하지 말래요.","떠다니는 거대한 죽은 자의 도시를 보면 도망치래요."}},
[84377]={a={"어둠의 무리 대족장 렌드 블랙핸드가 쓰러졌어요.","그 머리만 베어 가져오면 된대요.","단장 마티아스 쇼에게 바치래요."}},
[84414]={a={"Orthas의 목소리가 머릿속에 들려와요.","이제 떠날 준비가 됐다고 해요.","Orthas가 떠나는 것을 지켜봐 달래요."}},
[84546]={a={"불타는 군단의 요원들이 아직 세상에 남아 있어요.","그들이 가는 곳마다 자연이 시들고 있대요.","혼자서 맞서 그들의 머리를 가져오래요."}},
[84590]={a={"스트라솔름에서 도망치던 농민들이 쓰러졌대요.","남은 농민들이 빛을 향해 걸어갈 거래요.","그들이 살아남도록 지켜 달래요."}},
[86576]={a={"마그그랜 어스바인더는 Bloodfury 하피들 얘기를 꺼냈어요.","하피들이 장식용으로 모은 태양석을 모르로갈이 쓴대요.","Glittering Sunstones를 찾아 모르로갈에게 가져다 달래요."},c={"하피들은 반짝이는 것을 좋아하지만 돌의 가치는 몰라요.","이 돌로 태양을 기리며 신전과 집을 꾸며요.","밤에는 달빛을 받아 은빛으로 빛나요."}},
[86577]={a={"켈레크 스카이키퍼는 이 지역의 오염을 연구하고 있어요.","하이잘 산의 오염이 물을 타고 흘러 동물들이 병들었대요.","곰과 늑대의 썩은 장기 샘플을 구해 달래요."}},
[86612]={a={"사슴 석상이 초록빛 메달을 목에 걸고 있어요.","썩은 늪물에 깎여 어떻게 여기 왔는지 모른대요.","역사를 아는 사람에게 가져가 보라고 해요."}},
[86746]={a={"Ekkal의 부족은 지금 많이 힘들대요.","레가쉬 사티로스가 굴을 점령해 동맹과 갈라놓았대요.","북동쪽 폐허에 숨은 그들을 물리쳐 달래요."}},
[86752]={a={"Ekkal은 아직 할 일이 많다고 해요.","힘을 더 보태고 싶다면 북쪽 우르솔란으로 가래요.","문지기 레이지로어가 어디에 힘을 쓸지 알 거래요."}},
[86777]={a={"Korsa의 부족은 사티로스들에게 집을 빼앗겼어요.","우르솔란까지 약탈당할까 걱정하고 있어요.","남쪽 캠프의 군주 피어드레드를 처치하고 목걸이를 가져다 달래요."}},
[86784]={a={"서쪽 언덕에서 야영 중인 동료가 있대요.","그녀는 땔감을 넉넉히 모으라고 조언했대요.","나뭇가지를 주워 그녀의 야영지에 가져다 달래요."},c={"Eleanor Shackleton은 땔감이 늘 반갑다고 해요.","자기 나무 끈이 있으니 바구니는 가지래요."}},
[86791]={a={"문지기 레이지로어가 보낸 정찰대가 아직 안 돌아왔어요.","살아 있다면 근처에 있을 거래요.","동쪽에서 정찰대를 찾아 달래요."}},
[86792]={a={"Korsa의 정찰대가 레가쉬 요새에서 사티로스에게 밀렸어요.","한 명은 죽고 한 명은 붙잡혔고, Korsa만 겨우 도망쳤대요.","혼자서는 맞설 수 없으니 요새의 사티로스를 처치해 달래요."}},
[86796]={a={"Graal은 사티로스들에게 붙잡혀 우리에 갇혔어요.","우르솔란으로 돌아가고 싶은데 적이 많아 혼자선 힘들대요.","탈출을 도와 달래요."}},
[86797]={a={"레가쉬 요새가 약해져서 우르솔란으로 당당히 돌아갈 수 있대요.","Korsa는 뒤따라갈 테니 먼저 가 달래요.","문지기 레이지로어에게 요새 상황을 알려 달래요."}},
[86798]={a={"문지기 레이지로어가 반격할 때가 왔대요.","나무구렁 요새와 끊겨서 병력이 부족하대요.","외눈 고른을 찾아가 병력을 부탁해 달래요."}},
[86799]={a={"Furze가 알 수 없는 병에 걸려 쓰러졌어요.","피가 불타듯 아프고 몸이 흩어지는 느낌이래요.","Elder Bramblesnap이 해결책을 알 테니 찾아가래요."}},
[86804]={a={"Elder Bramblesnap은 같은 병에 걸린 사람이 많다고 걱정해요.","병에 걸리면 정신을 잃고 난폭해진대요.","동쪽 레가쉬 야영지에서 화주를 구하거나 만들 방법을 찾아 달래요."}},
[86812]={a={"Elder Bramblesnap이 화주로 약을 만들었대요.","우르솔란 동쪽의 짐승들이 오염돼 있대요.","짐승을 약하게 만든 뒤 약을 먹여 시험해 달래요."}},
[86813]={a={"Elder Bramblesnap이 약을 하나 만들었어요.","이 약이 부패를 고쳐 줄지도 모른대요.","Furze에게 이 약을 전하고 와서 알려 달래요."}},
[86814]={a={"외눈 고른이 우르솔란에 지원군을 보내기로 했어요.","Halanox의 악마 소환진에 군기를 꽂아 그를 자극하래요.","Halanox를 물리친 뒤 문지기 레이지로어에게 알려 달래요."}},
[86925]={a={"이 가마솥으로 화주를 끓일 수 있대요.","Elder Bramblesnap이 원하는 화주예요.","레가쉬 야영지의 사티로스에게서 제조법을 찾아 달래요."}},
[86927]={a={"가마솥에 재료를 넣으니 독한 가스가 피어올라요.","그 틈에 샘플을 재빨리 담아야 한대요.","샘플을 Elder Bramblesnap에게 가져다 달래요."}},
[87346]={a={"외눈 고른은 나무구렁 요새를 지키느라 병력이 부족해요.","Deadwood 부족도 그들을 위협해서 싸움이 이어진대요.","대족장 블러드모우를 처치하고 철퇴를 가져오면 도와준대요."}},
[87451]={a={"오거가 가지고 있던 작은 돌 조각을 발견했어요.","Rockard에 살던 오크의 기념품일지도 모른대요.","스토나드의 파견사령관 루아그에게 가져다 달래요."}},
[87494]={a={"이 비늘은 보통 것보다 빛을 더 반사하고 무지갯빛이 나요.","작은 수정 알갱이가 박혀 있대요.","토르와 패스파인더에게 가져다 달래요."}},
[89341]={a={"도와준 덕분에 신 아발론 사람들이 따뜻한 밥을 먹게 됐대요.","마지막 일 하나만 남았다고 해요.","한 번만 더 도와주면 유명한 요리법을 가르쳐 준대요."}},
[90487]={a={"Ketharas는 더 해 줄 게 없대요.","하이잘 산 기슭에 옛 수호자들이 남긴 전초기지가 있대요.","그곳의 Fraxinus가 도와줄 수 있대요."}},
[90518]={a={"요리사가 파이를 만들고 싶은데 사과가 조금 모자라요.","Johnny의 파이에는 사과를 아끼겠대요.","과수원에서 사과를 조금 따 와 달래요."}},
[90519]={a={"요리사는 생선을 정말 싫어한대요.","그래도 병사들이 오늘 밤 생선 요리를 원한대요.","지금 당장 생선을 빨리 가져다 달래요."}},
[90520]={a={"식량 창고에 고기가 또 떨어지고 있대요.","전에 가져온 고기 때문인지 식사 후 탈 난 사람이 많았대요.","믿을 만한 사람이 고기를 배달해 주면 좋겠대요."}},
[90647]={a={"Ketharas가 지팡이에 새 마법을 불어넣었대요.","이 지팡이로 Ve'han이 훔쳐 간 야생 신들의 마법을 막을 수 있대요.","드루이드 Tiala Whitemane에게 가져가 시험해 달래요."}},
[90789]={a={"대마법사 실렘이 강한 마력의 근원을 감지했어요.","그 마력은 폭풍의 만 동굴의 비늘수염이 갖고 있대요.","탑을 떠날 수 없으니 그 괴수를 처치해 달래요."}},
[90854]={a={"Zet'gan은 오랫동안 야생에서 지내며 물자가 닳았대요.","텐트와 건물을 고치고 갑옷도 손봐야 한대요.","거친 경화 가죽을 가져오면 특별한 물건으로 만들어 준대요."}},
[90865]={a={"Eluneth는 북쪽 옛 전투의 폐허에 언데드가 남았대요.","언데드가 줄었지만 감시자들이 지켜봐서 치우기 어렵대요.","감시자들이 가장 아끼는 것을 빼앗아 달래요."}},
[90902]={a={"Aramis Hammerhand는 막 되살아난 성기사를 반갑게 맞았어요.","빛의 힘을 쓰면 아프지만, 근육처럼 참고 써야 돌아온대요.","그러니 부상한 병사들을 빛으로 치료해 보래요."},c={"Aramis Hammerhand는 죽음을 겪은 자들이 고통에 강하다고 해요.","고통은 정화의 힘도 있으니 명예의 표식으로 여기래요."}},
[91208]={a={"Aramis Hammerhand는 되살아난 성기사들의 마음을 걱정해요.","겁에 질린 성기사 한 명이 교회 서쪽 언덕으로 도망쳤대요.","그 성기사를 찾아 손을 내밀고 빛으로 돌아오게 해 달래요."},c={"Aramis Hammerhand는 되살아난 뒤 광기에 빠지는 동료가 있대요.","적응하지 못한 이는 편히 보내 주는 게 최선일 때도 있대요.","그녀를 위해 기도하며 해야 할 일을 해 줘서 고맙대요."},nx=91209,nt="Continue Your Training"},
[91209]={a={"Aramis Hammerhand는 성기사의 훈련을 이어 가라고 해요.","데스넬에서 동쪽 길을 따라 브릴 마을로 가야 한대요.","브릴에서 Shari Stilwell를 만나 훈련을 받으래요."},c={"Shari Stilwell가 새 모험가를 반긴대요.","브릴에는 도움이 필요한 사람이 많아서 일을 찾아보래요.","실력을 증명하면 다음 여정을 알려 주겠대요."}},
[91282]={a={"Shari Stilwell는 여기 근처에 새 성기사단이 생겼다고 해요.","더 알고 싶다면 Bandarion Keep이라는 수도원을 찾아가래요.","솔리덴 농장 북서쪽 절벽 위에 있으니 찾아가 보래요."},c={"Breton Samuels가 새 신병을 반기며 환영한대요."},nx=90902,nt="Rediscovering the Light"},
[91285]={a={"Breton Samuels는 murloc 때문에 골치를 앓고 있어요.","원래 murloc들의 산란지였는데 요즘 점점 심해졌대요.","동쪽 절벽과 서쪽 호수 야영지의 놈들을 몰아내 달래요."},c={"Breton Samuels가 도와줘서 고맙대요.","완전히 막진 못해도 공격이 조금은 줄 거래요.","재건도 힘든데 murloc이 창으로 등을 노리기까지 하대요."},nx=91294,nt="Touring the Grounds"},
[91294]={a={"Breton Samuels는 murloc 공격이 이제 진정됐대요.","아직 작지만 여기가 우리 집이니 요새 구경을 해 보래요.","구경을 마치면 리더인 Danitha Morr를 찾아가 달래요."},c={"Danitha Morr가 Breton이 보냈다니 반가워해요.","자신은 요새의 사실상 지휘관이래요.","할 일이 많으니 일손을 보태 주면 고맙겠대요."}},
[91316]={a={"Jorin Croge는 요새를 고칠 건축 자재가 부족해요.","언더시티에서 멀어서 보급이 어렵대요.","남서쪽 Shadowvale 마을 지하 창고에서 자재를 찾아오래요."},c={"Jorin Croge는 Shadowvale 다녀온 성과가 있어 기뻐해요.","나중에 Breton과 신병들을 보내 창고를 마저 치우겠대요."}},
[91317]={a={"Danitha Morr는 일부 성기사들의 폭력 때문에 걱정이 커요.","일부 성기사가 언데드 동족을 공격해 불신이 커졌대요.","Shadowvale의 타락한 무리를 없애고 우두머리 머리를 가져오래요."},c={"Danitha Morr가 잘했다며 칭찬해요.","이들이 동족을 죽일 때마다 우리를 향한 불신이 커진대요.","이들을 없애면 성기사들이 이곳에 자리 잡는 데 도움이 된대요."}},
[91488]={a={"Kurll은 blood elves와 싸운 뒤 천막이 망가졌대요.","여러 밤을 비바람에 그대로 맞으며 잠을 못 잤대요.","천막을 고칠 Mosshoof 가죽을 구해 달래요."}},
[91497]={a={"Sin'dorei Tome of Summoning에 봉인이 세 개 쓰인대요.","학자 림토리의 부하들이 봉인을 나눠 갖고 있대요.","그 봉인을 뺏으면 림토리가 곤란해진대요."},nx=91500,nt="An Explosive Gambit"},
[91500]={a={"봉인을 부수면 수정도 폭발할 것 같대요.","그 폭발은 학자 림토리의 화를 돋울 거예요.","그녀가 당황한 틈에 공격할 기회래요."},nx=91531,nt="Revenge Exacted"},
[91531]={a={"아그토르 블러드피스트가 기뻐하고 있어요.","벨그롬 록마울이 림토리 머리를 직접 보고 싶대요.","오그리마의 벨그롬에게 그 머리를 가져가래요."}},
[91538]={a={"학자 림토리의 책이 아직 받침대 위에 놓여 있대요.","책 속 비밀이 뭔지 아무도 모른대요.","야생에 두기엔 위험하니 제디가에게 가져다 달래요."},nx=91547,nt="Sin'dorei Tome of Summoning"},
[91547]={a={"제디가는 이 책을 챙긴 게 현명했다고 해요.","블러드 엘프 손에 없어야 보복을 못 한대요.","오그리마의 흑마법사 제브로스트에게 가져가 달래요."},nx=91548,nt="Vek'zol"},
[91548]={a={"제브로스트가 소환서의 그림을 알아봤어요.","블러드 엘프는 마나에 중독돼 악마를 불러 힘을 뽑으려 했대요.","저주받은 땅 폭풍의 제단에서 그 악마를 불러 달래요."}},
[91568]={a={"Izvi Gildfizz가 해변 모래 아래 보물이 많다고 해요.","유적은 거의 털렸지만 모래 밑에 아직 남은 게 있대요.","동쪽 해안을 파서 찾은 걸 나눠 갖자고 해요."}},
[91569]={a={"Izvi Gildfizz는 모두가 옛 마법의 힘을 노린대요.","blood elves 마법사들이 특별한 지팡이를 들고 다닌대요.","Mana-Siphoning Wand를 가져오면 큰돈 벌 곳을 알려 준대요."},nx=91685,nt="Ley of the Land"},
[91608]={a={"Kurll은 좋은 술이 있으면 캠프 사기가 오를 거래요.","술 재료인 꿀은 서쪽 말벌 둥지에 가득하대요.","Kurll의 Pellet Gun으로 둥지를 떨어뜨려 꿀을 모아 달래요."}},
[91609]={a={"고기도 좋지만 식단이 다양해야 몸이 튼튼해진대요.","여름 농어가 제철이라 아즈샤라 해안에서 낚을 수 있대요.","직접 낚거나 구해 오면 크게 고마워한대요."}},
[91610]={a={"Kurll은 식단이 다양해야 몸이 튼튼해진대요.","겨울오징어는 아즈샤라 해안에서 낚을 수 있대요.","낚은 겨울오징어를 Kurll에게 가져다 달래요."}},
[91611]={a={"Kurll은 더 큰 물고기를 원하면 도전해 보라고 해요.","맘모스 상어는 바다 깊은 곳에 아주 크게 숨어 산대요.","맘모스 상어 고기를 Kurll에게 가져다 달래요."}},
[91685]={a={"Izvi Gildfizz는 멘나르 호수 위에 큰 틈이 떠 있었대요.","그게 열린 leyline일지도 모른대요.","Mana-Siphoning Wand로 그 틈의 마법을 빼내 달래요."}},
[91696]={a={"Deadwood 놈들이 새끼와 그 아비를 덮쳤대요.","그 아비는 우리를 지키려고 끝까지 싸우다 죽었대요.","어둡고 위험한 길을 집까지 같이 지켜 달래요."}},
[91697]={a={"Osi Mistpaw가 곰 열매를 모아 준 걸 고마워해요.","열매 수지 향이 몸에 배면 장로들이 더 반길 거래요.","두 장로를 찾아가 말을 걸어 달래요."}},
[91698]={a={"Barkskin Matriarch가 새끼와 함께 우리에 갇혔어요.","Deadwood Warden 허리에 열쇠가 달려 있대요.","그 열쇠를 가져와 우리를 열어 달래요."},nx=91696,nt="Open Season"},
[91734]={a={"안드론 건트가 비틀거리며 부탁을 해요.","아즈샤라에서 중요한 배달을 기다린다고 하네요.","제디가에게 그 말을 전해 달래요."}},
[91735]={a={"제스리몬이 이곳에 오래 있으면 안 좋다고 해요.","제디가가 보낼 물건을 제스리몬이 기다리고 있대요.","제디가에게 제스리몬이 보냈다고 전해 달래요."}},
[91737]={a={"마가타 그림토템은 썬더 블러프를 떠날 수 없어 일손을 구한대요.","아즈샤라의 제디가에게서 물건이 올 예정이래요.","제디가의 캠프에 가서 언제 도착하는지 물어봐 달래요."}},
[91754]={a={"Hyacinth의 친구 Fraxinus가 많이 아파요.","찜질약을 만들 흙이 필요하대요.","남동쪽 오염되지 않은 땅에서 흙을 구해 달래요."}},
[91755]={a={"Hyacinth는 오염된 덤불 중에 독이 다 있지는 않대요.","그런 덤불의 잎에는 약효가 있을 수 있대요.","Verdant Leaves를 따서 가져다 달래요."},nx=91770,nt="Bark Bite"},
[91770]={a={"Hyacinth는 친구 Fraxinus가 늙고 전쟁에서 크게 다쳤대요.","나무껍질이 갈라져 몸이 많이 아프대요.","갈라진 곳마다 이 약을 넉넉히 발라 달래요."}},
[91794]={a={"Kal'tinzan은 Scourge와 오래 싸우며 버텨 왔대요.","동쪽 Dae'gun에 전쟁 때 남은 호드 깃발이 있대요.","호드 깃발과 문장 조각을 가져다 달래요."}},
[91858]={a={"Danitha Morr는 은빛소나무 숲에서 생긴 사건을 걱정해요.","타렌 밀농장으로 가던 Earthen Ring 사절 둘이 실종됐대요.","공동묘지에 있는 Trevan Rol을 찾아가 보래요."},c={"Trevan Rol이 Danitha Morr가 보냈냐며 이유를 안다고 해요.","지금 꽤 골치 아픈 일에 휘말렸대요."},nx=91859,nt="A Curious Pair"},
[91859]={a={"Trevan Rol은 실종된 사절들이 평범한 외교관이 아니래요.","한 명은 Tauren이고 다른 한 명은 high elf로 보인대요.","마을 입구 근처의 Deathguard Baldren에게 물어보래요."},c={"Deathguard Baldren이 성기사는 싫지만 타이밍은 완벽하대요.","잘하기보다 운이 좋은 편이 낫겠대요."},nx=91860,nt="A Grim Fate"},
[91860]={a={"Deathguard Baldren이 어젯밤 순찰 중 이상한 일을 봤대요.","펜리스 섬 해안에서 gnoll들이 큰 시체를 장작에 올리고 있었대요.","위험하지만 펜리스 섬에 가서 무슨 일인지 알아봐 달래요."},c={"Deathguard Baldren은 시체가 타우렌이고 많이 뜯겼대요.","엘프 여인의 흔적은 없지만 요새 안쪽에 살아 있을지도 모른대요.","위험하지만 확인하려면 가 봐야 한대요."},nx=91861,nt="Into Fenris Keep"},
[91861]={a={"탄 시신이 발견됐어요.","Trevan과 Hadrec이 말한 하이엘프가 살아 있을지도 몰라요.","펜리스 요새 안쪽을 더 살펴봐 달래요."},c={"갇혀 있던 사람이 Forsaken이냐고 물어요.","풀어 달라며 시간이 얼마 없다고 해요."},nx=91862,nt="Lumina Windsinger"},
[91862]={a={"Lumina Windsinger는 이 땅에 온 손님이에요.","아라시 고원으로 가던 중 우리에 갇혔대요.","근처 gnoll을 쓰러뜨리고 열쇠를 찾아 구해 달래요."},c={"Lumina Windsinger는 고맙지만 아직 위험하대요."},nx=96204,nt="The Windshaper's Wrath"},
[91877]={a={"로라무스 탈리뻬데스의 동료가 하이잘 산으로 떠났대요.","전쟁 때의 악마가 다 물러가지 않았을지도 모른대요.","하이잘 산에서 Maerion Thaelemaches를 찾아 달래요."}},
[91882]={a={"대사 알달란은 옛날 Legion과 싸운 일을 말해요.","산에서 물러날 때 뒤에 남겨진 용사들이 있었대요.","하이잘 산에서 Grand Alliance의 흔적을 찾아 달래요."}},
[91883]={a={"Zarrat가 내 창을 낚아채 달아났대요.","그 창은 우리 가문 대대로 내려온 소중한 물건이래요.","Zarrat를 찾아 처치하고 창을 되찾아 달래요."}},
[91920]={a={"쿠인 요릭은 연금술사 렌퍼럴의 약 효과를 못 느꼈대요.","렌퍼럴은 요즘 심장에 푹 빠져 있대요.","호숫가 생물의 눈을 몇 개 가져다 달래요."},c={"연금술사 렌퍼럴은 심장이 모자라서 약이 안 들었대요.","그래도 호숫가 생물의 부위도 쓸 데가 있겠대요."},nx=91921,nt="Return to Quinn (Again)"},
[91921]={a={"연금술사 렌퍼럴이 쿠인 요릭을 위한 새 약을 만들었어요.","온전한 심장에서 뽑은 것으로 만든 약이래요.","쿠인 요릭에게 이 약을 전해 달래요."},c={"쿠인 요릭은 약이 효과를 내는 걸 느낀대요.","곧 다시 여행할 수 있겠대요."},nx=425,nt="Ivar the Foul"},
[91923]={a={"Thylaen은 산이 야생 식물로 뒤덮였다고 해요.","동쪽 비탈에 Celastrus라는 큰 가시덤불이 동물을 해친대요.","Celastrus를 없애고 부러진 줄기를 가져다 달래요."}},
[91952]={a={"그레타 모스후프는 악령의 숲에 부패가 위에서 쏟아진대요.","하이잘 산의 물이 불면 오염이 땅에 스며 나무가 병든대요.","하이잘 산의 은둔자 Ketharas를 찾아가 달래요."}},
[92008]={a={"Kaylaena Springwhisper는 몇 주째 작업장에 있었대요.","높은 곳이라 부품과 재료 구하기가 어렵대요.","눈망루 마을의 Nami에게 맡긴 부품 주문을 받아 달래요."},nx=92009,nt="Crate Expectations"},
[92009]={a={"Nami가 상자 바닥에 위험한 물건을 감싸 넣었대요.","부딪히면 쉽게 터지고 두 시간 뒤엔 힘이 빠진대요.","하이잘 산까지 상자를 살살 옮겨 달래요."},nx=92011,nt="Rubble Rummage"},
[92011]={a={"Kaylaena는 어떤 걸 먼저 만들지 아직 정하지 못했대요.","산 위 옛 호드 진지의 잔해에서 쓸 만한 것을 찾고 싶대요.","금속 조각, 전선, 박쥐 똥을 챙겨 가져다 달래요."},nx=92328,nt="Siegecraft"},
[92016]={a={"Marn Euhorn은 하이잘 산의 흙이 악마의 독에 오염됐대요.","뿌리가 오염을 너무 빨아들였는지 알아야 한대요.","Well of Eternity 깊은 곳에 내려가 뿌리를 살펴 달래요."}},
[92017]={a={"Marn Euhorn은 정화 향을 만들 재료가 필요하대요.","정상 근처 높은 바람에 깃털과 털이 떠다닌대요.","그 깃털과 털을 모아 가져다 달래요."}},
[92020]={a={"홀라니에 마샬은 운고로 분화구의 생물을 그려 왔어요.","그 스케치북을 하이잘 산의 드루이드들에게 보내려 해요.","하이잘 산에 가신다면 이 책을 같이 가져가 달래요."}},
[92065]={a={"문지기 레이지로어가 마지막 싸움을 도와 달래요.","Varrox Bleakhoof가 Blackmaw의 굴을 짓밟고 있대요.","Blackmaw Hold에 가서 그를 쓰러뜨려 달래요."}},
[92066]={a={"Lorekeeper Nok은 Legashi 침입 때 물건을 잃었대요.","그중 쌍둥이 신 Ursoc과 Ursol을 그린 토템이 있대요.","옛 거처에서 찾아 우르솔란에 돌려 달래요."}},
[92069]={a={"오그틴크의 사람들은 고향으로 돌아가야 해요.","Withermaw와 Bonesnout가 옛 고향을 지켜요.","그 짐승들을 쓰러뜨려 유해를 가져다 달래요."}},
[92070]={a={"깃털과 조약돌로 꾸민 목걸이가 있어요.","Furbolg 아이가 직접 만든 것 같대요.","그 목걸이 주인을 찾아 돌려 달래요."}},
[92094]={a={"로켓 시험을 마친 뒤 형제 Fenwick이 돌아오지 않았어요.","낙하산을 타고 남쪽으로 떠가다 하이잘 산에 떨어진 것 같대요.","그가 빠져나갈 길을 찾도록 도와 달래요."}},
[92100]={a={"Veteran of the Third War의 영혼이 나타났어요.","그는 오래전 칼집을 서쪽 전망대에 두고 왔대요.","칼집을 찾아 전망대에서 이야기하자고 해요."}},
[92101]={a={"Veteran of the Third War는 악몽에 시달려요.","친구 Tobin과 함께 버섯구름 봉우리에 이름을 새겼대요.","그 이름이 아직 남아 있는지 확인해 달래요."}},
[92102]={a={"Veteran of the Third War가 고맙다고 해요.","예전 기억이 점점 또렷해졌대요.","Mourning's Rest의 부서진 대포 옆에서 만나자고 해요."}},
[92111]={a={"Brerufa는 당신이 애쓰는 모습을 알아봤대요.","같이 노력하면 시간이 지나 호의를 준대요.","굴에 들어가 Osi에게 말을 걸어 달래요."},nx=93831,nt="Sweetpaw Jam"},
[92147]={a={"Phoebe Highfeather는 남은 일족 중 한 명이에요.","하이잘 산 고원 곳곳을 Wormwing 하르피가 점령했대요.","그 하르피들에게 피의 대가를 치르게 해 달래요."}},
[92169]={a={"Tiala Whitemane은 산 정상의 무리를 걱정해요.","말퓨리온 스톰레이지가 불사를 빼앗았다고 해요.","지팡이로 그들의 보호 마법을 풀어 달래요."}},
[92171]={a={"Ketharas는 Ve'han을 이기려면 하늘의 힘이 필요하대요.","Skylord Omnuron이 도울 수 있대요.","하이잘 산의 Aviana 성소에 가서 그를 찾아 달래요."},nx=92500,nt="A Bit of the Sky"},
[92317]={a={"Marrosis는 은둔 드루이드가 찾는 힘을 알고 있대요.","그 땅의 언데드는 훔친 힘으로 움직인대요.","언데드를 처치해 훔친 생명의 방울을 찾아 달래요."}},
[92328]={a={"Kaylaena가 Glaive Thrower를 고치고 있어요.","Yaely가 남긴 설계를 마무리하려고 일손이 부족해요.","같이 도와주면 훨씬 빨리 끝난대요."},nx=92329,nt="Drum Up Trouble"},
[92329]={a={"Ghansurok이라는 키메라가 언덕 일대를 휩쓸고 있어요.","Kaylaena는 괴물이 가까이 와야 쏠 수 있대요.","절벽 옆 북에서 소란을 피워 달래요."}},
[92335]={a={"Renalard는 마법에 쓸 재료를 알고 있대요.","Archimonde의 부하 Azgalor가 이곳에서 쓰러졌대요.","Azgalor의 잿가루를 조금만 가져다 달래요."}},
[92343]={a={"나라 와일드메인은 굴이 Blackmaw Hold와 이어진다고 해요.","새 뿌리는 땅속 깊은 곳에서만 찾을 수 있대요.","뿌리 샘플을 모아 가져다 달래요."}},
[92346]={a={"제디가는 퍼볼그와 사티로스가 굴을 두고 싸우는 걸 봤대요.","그 굴은 세계수 아래로 이어진대요.","썬더 블러프의 나라 와일드메인에게 전해 달래요."},nx=92343,nt="Get to the Roots of It"},
[92401]={a={"Tabitha Heartweaver는 남편을 몹시 걱정해요.","남편 에드워드가 로데론의 폐허 묘지에 간 뒤 며칠째 소식이 없대요.","남편이 어떻게 됐는지 알아봐 달래요."},c={"제 부탁이 공평하지 않았는데 도와줘서 고마워요.","보답은 못 하지만 이 중 하나를 받아 주세요.","다음엔 이런 슬픔 없이 다시 만났으면 좋겠어요."}},
[92421]={a={"Morbin Lightbane은 Forsaken 성기사예요.","언더시티 위로 언데드가 아직 많이 돌아다녀요.","우리 편을 치료하려면 온전한 팔다리를 모아 달래요."}},
[92422]={a={"Deathguard Kristof는 로데론의 폐허 소식을 전해요.","불길한 안개 속에서 언데드가 숨어 움직인대요.","네크로맨서 Rath'mael을 몰아내 달래요."},c={"그와 같은 자들은 또 나타나겠지만 당분간 줄어들기를 바라요."}},
[92434]={a={"학자 워딘 보이드글레어는 달라란 상황을 알려 줘요.","보호막이 내려가 도시가 혼란에 빠졌대요.","로다미어 호수 쪽에서 달라란 안으로 가는 길을 찾아 달래요."},c={"Horde가 이 혼란한 때에 달라란에 관심을 가진 건 우연이 아니에요.","사실 저는 그걸 기대하고 있었어요.","그래서 제안할 게 있어요."},nx=96984,nt="Heart of Disruption"},
[92446]={a={"Head Scratcher라는 곰이 남쪽 숲에서 사냥꾼을 습격해요.","그 곰은 Zet'gan을 경계하지만 당신 냄새는 몰라요.","토끼 고기를 들고 숲에 가서 곰을 꾀어내 달래요."}},
[92454]={a={"수집가 에디션을 사 준 감사 선물이 있어요.","Dalia Windbreeze에게 선물 상품권을 전해 달래요.","그러면 여행을 함께할 작은 동료를 받을 수 있대요."}},
[92460]={a={"Ailee Farheart가 당신의 도착을 오래 기다렸대요.","당신이 긴장되고 설렐 거라며 반가워해요.","마을 지도자 Rorian the Dayseeker를 찾아가래요."},c={"Rorian은 성인식을 맞은 당신에게 유물을 줘서 영광이래요.","이 유물은 선조들이 물려준 여러 유물 중 하나래요.","고향의 바람이 어디를 가든 함께할 거래요."},nx=92461,nt="Harmony in Balance"},
[92461]={a={"Rorian the Dayseeker가 마을 숲의 균형을 걱정해요.","Vuldren 수가 너무 빨리 늘어났대요.","동쪽에 가서 일부를 솎아 내 달래요."},c={"Rorian은 당신의 노고에 고마워한대요.","바람의 마법이 어긋나면 동물들이 위험해질 수 있대요."}},
[92462]={a={"Elatrell Featherlight가 벌레 떼 번짐을 걱정해요.","Cirrusfly 떼가 커지면 위험하대요.","숲 동쪽 끝에서 최대한 많이 잡아 달래요."},c={"Elatrell Featherlight는 벌레 잔해를 보고 심각하다고 해요."},nx=92463,nt="The Cirrusfly Queen"},
[92463]={a={"Elatrell Featherlight가 숲의 벌레 떼를 걱정해요.","일꾼 벌레만 잡아서는 떼가 줄지 않는대요.","깊이 들어가 Cirrusfly 여왕을 찾아 처치해 달래요."},c={"Elatrell Featherlight가 당신을 훌륭하다고 칭찬해요.","모험가 일이 안 되면 레인저가 어울리겠대요."}},
[92464]={a={"Rorian the Dayseeker가 정령들이 떠난 뒤 걱정이 많대요.","북동쪽 선돌 근처 바람 정령들이 사나워졌대요.","제자 Yala Windwatcher를 찾아가 알아봐 달래요."},nx=92465,nt="Agitators"},
[92465]={a={"Al'Aketh 교단이 바람 정령들을 자극하고 있대요.","사나워진 바람이 누군가를 해치기 전에 흩어야 한대요.","교단에 이곳이 환영받지 못한다고 알려 달래요."},nx=92469,nt="Return to Rorian"},
[92466]={a={"Windshaper Boro가 원소의 시련을 시작하라고 해요.","동쪽 선돌 근처에 Al'Aketh 신도들이 나타났대요.","그들을 쫓고 인장을 가져오라고 해요."},c={"Windshaper Boro가 당신의 끈기를 인정했어요.","Harten, 이제 다음 단계로 갈 준비가 됐대요."},nx=92467,nt="Call of Earth"},
[92467]={a={"Windshaper Boro가 대지의 정기라는 음료를 알려 줘요.","이 음료는 영혼을 원소에 묶어 준대요.","Rise of Spirits라는 곳에서 마셔야 한대요."},c={"하급 대지의 현신은 바람이 떠난 이유를 모른대요.","대신 땅의 힘과 굳건함을 가르쳐 준대요.","바람의 정령과 다시 대화하려면 이 길을 가야 한대요."},nx=92468,nt="Call of Earth"},
[92468]={a={"하급 대지의 현신이 천연 석영을 건네줘요.","이걸 Windshaper Boro에게 가져가면 토템을 만들어 줘요.","이 돌이 토템의 심장이 된대요."}},
[92469]={a={"Yala Windwatcher가 숲에 남아 남은 무리를 정리한대요.","마을로 돌아가 Rorian에게 교단의 흔적을 알려 달래요.","Rorian은 이 소식을 반기지 않을 것 같대요."},c={"Rorian은 교단 움직임을 오래전부터 알고 있었지만 지켜만 봤대요.","정령을 자극한 건 분명 상황이 더 나빠진 거래요.","힘든 일을 해 줘서 고맙대요."},nx=92470,nt="Foul Matriarch"},
[92470]={a={"Aetheen of the Gales가 당신을 지켜봤대요.","각오를 보는 시험이라 위험하대요.","Ursera 무리 우두머리 Urs'anah를 처치해 달래요."},nx=92472,nt="The Next Step"},
[92471]={a={"Rorian은 지금까지 한 일이 모두 시험이었대요.","Zephras 섬에는 젊은 모험가가 필요하대요.","Aetheen of the Gales를 찾아가 과제를 들어 보래요."},c={"Aetheen은 Rorian에게 당신 이야기를 들었대요.","장로회 일원이며 젊은이들을 평가하러 왔대요.","다음 단계로 나아갈 준비가 됐냐고 물어요."},nx=92470,nt="Foul Matriarch"},
[92472]={a={"Al'Aketh 교단이 Shen'dar 마을을 위협하고 있대요.","교단은 Al'Akir를 섬기는 잔인한 무리래요.","Constable Aonda에게 Aetheen이 보냈다고 전해 달래요."},c={"Constable Aonda는 Aetheen이 보냈냐고 묻대요.","겉보기엔 별로 강해 보이지 않지만 도움은 환영이래요."}},
[92473]={a={"Valreaa Valewind가 남서쪽 Ursera 굴을 걱정해요.","마을 근처까지 내려온 Ursera가 아이를 공격하려 했대요.","남쪽에서 비쩍 마른 Ursera를 잡아 발톱을 가져오래요."}},
[92474]={a={"Myriaal Mistwake가 재미있는 놀이를 제안해요.","망대 위에서 뛰어내려 공중 걷기로 천천히 떨어지래요.","Rorian을 놀라게 하면 점수를 더 준대요."},c={"Rorian은 Myriaal이 무모한 장난을 부추긴다며 투덜대요.","그래도 마을에서 조금 연습하는 건 괜찮대요.","능력은 아껴 써야 정말 필요할 때 쓸 수 있대요."}},
[92480]={a={"쓰러뜨린 교도가 교단 고위 여사제의 명령서를 떨어뜨렸어요.","명령서에 Shen'dar 마을의 간첩 얘기가 적혀 있대요.","Shen'dar 마을 책임자에게 전해 달래요."}},
[92482]={a={"Rorian the Dayseeker가 당신이 없는 사이 소식을 전해요.","모험가 트레이너 Tai'ree Farsight가 쪽지를 남겼대요.","마을 가운데에서 그녀를 찾아가 쪽지를 읽으래요."},c={"Tai'ree Farsight가 당신을 보니 옛날 자신이 떠오른대요.","모험가의 길은 위험하지만 당신에게 자질이 있대요.","다음 단계는 다시 찾아와 말하라고 해요."}},
[92483]={a={"Rorian the Dayseeker가 당신에게 소식을 전해요.","도적 트레이너 Akeri Duskblade가 당신을 찾는대요.","쪽지를 읽고 망루 안에서 그를 만나래요."},c={"Akeri Duskblade가 당신이 다가온 걸 거의 놓칠 뻔했대요.","살아남으려면 날렵하고 늘 경계해야 한대요.","Zephras에선 목이 베일 수도 있다고 경고해요."}},
[92484]={a={"Rorian the Dayseeker가 귀환 수정을 전해요.","이 수정을 살펴본 뒤 Boro를 찾아가래요.","마을 가운데에서 Boro를 만나 보래요."},c={"Windshaper Boro가 바람의 속삭임이 들리냐고 물어요.","정령들이 떠난 뒤로 대화가 끊겼대요.","원소를 깊이 익히고 싶다면 다시 와 달래요."}},
[92500]={a={"Skylord Omnuron은 Aviana의 성소가 낡았다고 해요.","Wormwing 하르피가 마지막 유물을 훔쳐 갔대요.","하이잘 산에서 보석을 찾아 Ketharas에게 가져다 달래요."}},
[92514]={a={"Constable Aonda가 당신에게 Windshaper 기운이 있대요.","마을 중앙에서 Illaya Amberwind를 먼저 만나래요.","여관의 Coriella Calmbreeze에게도 들러 보래요."},nx=92517,nt="The Criminal Element"},
[92515]={a={"Indari Sunseam이 언덕의 Prideclaw를 걱정해요.","마을 경계까지 다가와 점점 대담해진대요.","Prideclaw 가죽을 가져오면 마을 물건을 만들 수 있대요."}},
[92516]={a={"Shen'dar 마을 남동쪽에 Hippogryph 무리가 둥지를 틀었대요.","길 가는 여행자들을 자주 습격해 골칫거리래요.","그 무리를 솎아 내 줄 사람을 찾대요."},c={"Teeri Wellwind는 빨리 해냈다며 꽤 잘했다고 칭찬해요."}},
[92517]={a={"Constable Aonda가 북쪽 폭포 뒤 동굴의 도적들을 걱정해요.","예전엔 골칫거리였는데 이제는 정말 무서운 존재래요.","우두머리 Badwind Bennic을 처치해 달래요."},c={"Constable Aonda는 도적들이 흩어져 골칫거리가 하나 줄었대요.","살아남은 도적들이 교단에 기대어 세력을 키울까 걱정이래요."},nx=93036,nt="Infiltrating the Cult"},
[92519]={a={"의사 그레고리 빅터는 치료 물품을 기다리고 있어요.","연금술사 조렐이 며칠 전 약을 가져오기로 했는데 안 왔대요.","Go'shek 농장에 가서 약 상자를 받아 달래요."},c={"그레고리 빅터는 깨진 병 없이 와서 조렐의 부하들보다 낫대요.","이 약으로 환자들을 한동안 더 돌볼 수 있대요.","다치는 건 어쩔 수 없으니 물자는 골라 가래요."}},
[92528]={a={"Missionary Jasaan은 Al'Akir를 믿는 신도가 늘었대요.","북쪽 여관의 손님 때문에 그쪽은 피하래요.","Falaath 마을을 둘러보며 교단의 속셈을 알아 달래요."},c={"Constable Aonda는 Lorthuna가 직접 거기 있었냐며 놀라요.","교단이 마을과 서쪽 망루를 노린다면 대비해야 해요.","망루는 큰 쓸모가 없는데 왜 노리는지 궁금해해요."},nx=92550,nt="Havoc in the Highlands"},
[92529]={a={"Sania가 Al'Akir를 섬기려는 당신을 반긴대요.","자만과 정체 때문에 바람 정령이 우리를 떠났대요.","Falaath 마을의 Jasaan을 찾아가래요."},c={"Jasaan은 Sania가 보낸 새 신도라며 반가워해요.","오늘은 네 바람의 축복을 받은 날이래요.","Al'Akir의 축복을 바라는 모두를 환영한대요."},nx=92528,nt="Among the Faithful"},
[92532]={a={"Rorian the Dayseeker가 전사 트레이너의 소식을 전해요.","전사 트레이너 Blademaster Ren이 쪽지를 남겼대요.","구겨진 쪽지를 읽고 망루 안에서 그녀를 찾으래요."},c={"Blademaster Ren이 위험한 여정을 앞두고 있대요.","세상이 변해서 이끌고 지킬 사람이 필요하대요.","강해지면 다시 찾아와 달래요."}},
[92533]={a={"Toron Rockhoof은 쇠를 다뤄 온 대장장이예요.","Blackthorne 교단이 땅을 해치는 도구를 만든대요.","교단원을 쓰러뜨리고 지팡이와 의식용 단검을 가져다 달래요."}},
[92544]={a={"Hanaa Nightwind는 여행자들에게 위험을 알리는 초소를 지켜요.","남서쪽 신전 폐허에 Al'Aketh 무리가 자리 잡았대요.","우두머리 Malduko Cloudcrush까지 처치해 달래요."},c={"Hanaa Nightwind는 같이 싸우고 싶은 마음을 참았대요.","건달들이 경고를 알아듣고 떠나길 바란대요.","레인저들이 당신에게 고마워한대요."}},
[92550]={a={"Constable Aonda가 교단이 곧 공격해 올 거라 예상해요.","먼저 Falaath 마을로 가서 교도를 최대한 쓰러뜨리래요.","Commander Cyclas의 머리를 가져와 달래요."},c={"Constable Aonda는 당신이 돌아와 고마워해요.","Sania Silverstream은 마을이 무장하자 도망쳤을 거래요.","교단이 돌아오면 Shen'dar는 쉬운 상대가 아닐 거래요."},nx=92579,nt="To Valanaar"},
[92551]={a={"Danarii Bellowveil이 당신이 Falaath에 간다고 들었대요.","교단이 몇 달째 보급 수레를 털고 도적 탓으로 돌렸대요.","Falaath에 남은 보급품이 있으면 되찾아 달래요."}},
[92553]={a={"Zerril Softbreeze는 마을에 먹을 게 필요해요.","위험해서 아무도 사냥이나 채집을 못 한대요.","신선한 알과 타조 고기를 구해 달라고 부탁해요."},c={"Zerril Softbreeze는 알이 구하기 어렵지만 정말 맛있대요.","요리를 좋아하면 비법을 가르쳐 주겠대요."}},
[92579]={a={"Constable Aonda는 이 마을의 치안을 맡고 있어요.","사이비 집단이 빠르게 세력을 키우고 있대요.","보고서를 Valennia Stormfist에게 전해 달래요."},c={"Valennia Stormfist는 편지를 읽고 표정이 어두워졌어요.","Aonda가 당신을 믿었으니 자기도 믿어 보겠대요.","남은 대원들과 대책을 세운 뒤 다시 말하자고 해요."},nx=92700,nt="The Grand Skyseer"},
[92592]={a={"Zet'gan 무리는 산을 떠나려 해도 Scourge에게 막혀요.","리치가 쓰러진 자들을 되살린대요.","횃불을 들고 폐허의 뼈 더미를 태워 달래요."}},
[92594]={a={"Kaylaena는 언덕을 덮은 관목이 걱정이에요.","그 관목은 잘 타지만 톱니에 엉키면 위험하대요.","산을 내려가며 관목을 좀 줄여 달래요."}},
[92595]={a={"Illaya Amberwind는 돌아온 당신을 반갑게 맞아요.","당신이 바람을 느끼는 힘이 강하다고 해요.","Windshapers의 사명과 섬의 어려움을 들어 달래요."},c={"Illaya Amberwind는 사명이 얼마나 중요한지 알겠대요.","바람의 정령과 대화하려면 이 힘을 가진 사람이 꼭 필요하대요.","그래서 Windshapers가 힘을 써서 고향을 지켜야 한대요."},nx=94411,nt="Meddlesome Mages"},
[92598]={a={"Ventaari Brightwish가 바람의 힘을 알려 줘요.","그 힘은 정령들이 내려준 신성한 힘이래요.","마을 북동쪽 선돌이 있는 곳에서 힘을 써 보래요."},c={"Ventaari Brightwish는 근육처럼 써야 강해진대요.","이 힘으로 사람과 정령의 세계를 잇는 게 도움이 된대요.","정령의 말을 듣는 힘이 살길이 될 수 있대요."}},
[92609]={a={"Zet'gan 무리는 동료를 지키느라 떠나지 못했대요.","방어가 약해져서 이제 화살을 채워야 해요.","크고 아름다운 새의 긴 깃털을 가져다 달래요."}},
[92612]={a={"Ketharas가 이 가지의 비밀은 자기도 모르겠대요.","그래도 무언가 느껴진다고 해요.","달의 숲 나이트헤이븐의 덴드리트 스타블레이즈에게 가져가래요."},nx=96209,nt="The Ancient, Orokai"},
[92640]={a={"Talaanis Shadowsong은 사이비 집단과 맞서기 어렵대요.","그래서 신전을 공격해 Lorthuna를 막을 계획이래요.","그러려면 도움이 필요하니 Valennia에게 가 보래요."},nx=93065,nt="Prepare for Battle"},
[92642]={a={"Yorana Windyreed의 사람들이 오래 버티기 힘들대요.","적의 치료사들이 계속 공격대를 보내고 있어요.","내려가서 보급을 끊고 치료사들을 처치해 달래요."}},
[92643]={a={"Talaanis Shadowsong은 배신한 신도가 있다고 해요.","그는 보호를 약속받으면 정보를 주겠다고 해요.","마을 북서쪽 외딴집에 숨은 그를 데려와 달래요."},c={"죽은 신도는 집 밖에서 암살자들에게 이미 죽어 있었어요.","몸을 살피다 반짝이는 것을 봤어요."},nx=92644,nt="Unfortunate News"},
[92644]={a={"배신한 신도의 몸 아래에서 빛나는 수정을 찾았어요.","수정이 망가졌지만 중요한 물건일지도 모른대요.","Talaanis Shadowsong에게 전해 달래요."},c={"Talaanis Shadowsong은 배신자가 이미 죽었다니 안타깝대요.","그래도 흥미롭다며 생각에 잠겼어요."},nx=94568,nt="The Cult's True Plans"},
[92645]={a={"Yorana Windyreed는 이번 공격을 막기 어렵다고 해요.","사이비 지휘관 Belguilos는 예전 평화 유지대였대요.","언덕 아래 별장에 있는 그녀를 처치해 달래요."},c={"Yorana Windyreed는 Belguilos가 죽었냐며 놀라요.","이제 다 같이 살아남을지도 모른대요."}},
[92646]={a={"Valennia Stormfist는 많이 다쳐서 여기 남았어요.","Lorthuna가 포털로 위쪽 Rohashi Spires로 도망쳤대요.","포털로 가서 Ayessa를 도와 Lorthuna를 막아 달래요."},c={"Ayessa Dawnsinger는 치료사를 보내 일행을 챙겼대요.","Muln은 아제로스로 떠났고, 섬은 더 위험해졌대요.","그래서 Zephras를 지킬 계획이 필요하다고 해요."},nx=93836,nt="The Fate of Zephras"},
[92679]={a={"Alvarion Windfield는 농장을 지킬 전사를 찾고 있어요.","그는 Valanaar에서 사람을 모집하러 왔대요.","서쪽 저지대 과수원의 아내 Aamelia를 찾아가 달래요."},c={"Aamelia Windfield는 남편이 안전해서 다행이래요.","남편이 당신을 헛되이 죽게 보낸 것 같대요.","이건 당신 싸움이 아니니 지금 떠나라고 해요."},nx=92682,nt="Make Yourself Useful"},
[92682]={a={"Aamelia Windfield는 당신에게 일을 시키려 해요.","Stormapple 나무 근처에 도적들이 숨어 있대요.","오늘 Stormapple을 따 오고 그 도적들도 처치해 달래요."},c={"Aamelia Windfield는 창밖으로 도적들과 싸우는 걸 봤대요.","꽤 잘하더라며 칭찬해요."},nx=92685,nt="The Hills Have Eyes"},
[92683]={a={"Aamelia가 밭에 큰 Flutterfly가 많대요.","그 날개 가루는 집안일에 쓸모가 많대요.","Flutterfly를 쳐서 가루를 모아 달래요."},c={"Aamelia는 가루가 옷에 오래 묻을 거래요.","도적이 많아 혼자 멀리 나가기 힘들었대요.","그래도 가져와 줘서 고맙대요."}},
[92684]={a={"Aamelia Windfield는 과수원 농장에서 살고 있어요.","수확도 적은데 Galestrider가 사과를 훔쳐 간대요.","Galestrider를 잡아 고기를 가져다 달래요."},c={"Aamelia Windfield는 고기 덩어리가 아주 크다며 놀라요.","밖에서 제법 큰 괴물들을 잡았겠다고 해요."},nx=92685,nt="The Hills Have Eyes"},
[92685]={a={"Aamelia Windfield는 북쪽 언덕 도적들이 걱정이래요.","도적들이 쳐들어오기 전에 먼저 기습하자고 해요.","도적들의 피 묻은 가면을 가져다 달래요."},c={"Aamelia Windfield는 피 묻은 가면을 보고 만족해요.","다시 희망이 생겼다며 고맙다고 해요.","Ferauu 일당이 곧 올 테니 같이 맞서자고 해요."},nx=92693,nt="Standing Our Ground"},
[92693]={a={"Aamelia Windfield는 여기까지 도와준 것에 고마워해요.","돌아가도 아무도 탓하지 않을 거래요.","준비되면 도적 두목과 맞서러 가자고 해요."},c={"Aamelia Windfield는 이제 끝났다는 게 믿기지 않대요.","심장이 튀어나올 것 같아 마음을 가라앉혀야 한대요."},nx=92703,nt="Deliver the News"},
[92700]={a={"Valennia가 Valanaar에 온 당신을 챙기려 해요.","Windshapers와 High Order는 사이가 나빠 멀리하래요.","마을 중앙 숙소로 가서 Ayessa를 찾아가래요."},c={"Ayessa는 Shen'dar 마을 활약 소식을 들었대요.","당신에게 정령과 통하는 기운이 있대요.","재능 있는 사람이 줄어서 당신을 반긴대요."}},
[92703]={a={"Aamelia Windfield는 당신이 도와준 일에 고마워해요.","남편 Alvarion에게 여기 일어난 일을 알려 달래요.","남편이 일어나면 Windshaper를 데려와 장치를 보래요."},c={"Alvarion은 희망을 찾아왔는데 영웅을 만났대요.","당신이 한 일을 절대 잊지 않겠대요.","언제든 Windfield 집에 와도 된대요."}},
[92706]={a={"가즈로가 현상수배 공고를 냈어요.","선착장 근처에서 거대한 상어가 뱃사람을 공격한대요.","Bruuz의 등지느러미를 가져오면 큰 보상을 준대요."},c={"드디어 누군가 그 괴물을 잡았네요!","마을 사람들이 늘 상어가 나왔다고 외쳐서 선원 구하기가 힘들었어요.","그 지느러미를 오늘 저녁 수프에 넣을까 해요."}},
[92707]={a={"goliath의 팔 보호대가 엄청 커요.","드럼 펠은 무엇과 맞서는지 알아야 해요.","경고의 뜻으로 해머폴에 가져다 달래요."}},
[92708]={a={"Ayessa는 Windshapers가 섬의 위기에 대응하고 있대요.","사라진 바람의 정령을 찾다가 놀라운 것을 발견했대요.","섬을 살릴 방법을 찾는 데 모험가가 필요하대요."},c={"Ayessa는 Skywall 밖에도 넓은 세상이 있다고 해요.","섬을 구할 힘을 얻으려면 Azeroth로 가야 한대요.","함께 떠날 용기가 있냐고 물어요."}},
[92743]={a={"와루그는 가장 강한 켄타우로스 부족에 속해요.","그는 투구 대신 정복자의 왕관을 원한대요.","황야의 땅 무덤에서 왕관을 찾아 달래요."},nx=92841,nt="Valley of Bones"},
[92754]={a={"Mirda의 부족은 뼈의 골짜기 너머까지 가고 있어요.","그들이 살아남으려면 물약이 많이 필요하대요.","마그람 마을에서 Mirda에게 물약을 가져다 달래요."}},
[92814]={a={"Molkar는 아내 Halea에게 옷을 주고 싶대요.","Halea는 맡은 일이 밀려 있는데 잘못은 없대요.","모래폭풍 속 하얀 산적 복면을 구해 달래요."},c={"Molkar가 낡고 실밥이 풀렸지만 품질이 좋대요.","Halea가 매일 받는 찢긴 장비보다 훨씬 낫대요."}},
[92817]={a={"Talra는 Gelkis 동족에게 입힐 조끼를 만들고 있대요.","가죽이 귀해서 함부로 쓸 수 없다고 해요.","야만전사의 멜빵을 가져와 기술을 배우고 싶대요."},c={"Talra가 요청이 부족했다고 반성해요.","그래도 이걸 보면 배울 게 있을지 모른대요.","겔키스를 도운 일을 다른 이들에게 알리겠대요."}},
[92833]={a={"Tiala Whitemane은 Ve'han을 걱정해요.","Ve'han은 세계수 가지 아래를 소굴로 삼았대요.","지팡이로 그를 지키는 마법을 풀고 처단해 달래요."}},
[92842]={a={"은빛장교 퓨어하트의 사촌이 하이잘 산에 가 보겠다고 했대요.","사촌에게 편지가 닿으려면 몇 달이 걸릴지 몰라요.","혹시 그쪽에 가면 사촌이 잘 있는지 살펴봐 달래요."}},
[92859]={a={"에비 휠브루가 하이잘 산에 가려는 사람들을 도우려 해요.","검은속삭임 협곡의 악마들 때문에 길이 막혔대요.","여명의 설원에 섞여 숨는 약을 시험해 보고 싶대요."}},
[92871]={a={"Ayessa는 Valennia Stormfist에게 소식을 전하려 해요.","사이비 집단이 움직인다는 소문이 있대요.","Windshapers가 도울 거라고 Valennia에게 전해 달래요."},c={"Valennia Stormfist는 바로 돕겠다는 말이 반갑대요.","자세한 상황은 함께 얘기하자고 해요."},nx=93320,nt="Tower Defense"},
[92878]={a={"블라이즈 몽고메리는 싸움에서 턱을 잃어 말을 못 해요.","Grimtotem 무리를 드루이드 Namida가 이끌었대요.","그녀가 벌을 받아야 한다고 적었어요."}},
[92880]={a={"Yorana Windyreed는 아직 적을 정리하는 중이래요.","상황이 훨씬 나아져서 도움이 아주 컸대요.","Valanaar에 돌아가 안정됐다고 전해 달래요."},nx=92881,nt="The High Elder's Request"},
[92881]={a={"Valennia Stormfist는 감시탑 공격이 우연이 아니래요.","사이비 집단이 anchor pylons에 손을 대려는 것 같대요.","Talaanis Shadowsong에게 가서 단서를 들어 달래요."},c={"Talaanis Shadowsong은 모험가의 도움이 필요한 일이 있대요."},nx=92643,nt="The Turncoat"},
[92914]={a={"Shen'dralar Pylon이 낡은 받침대 위에 서 있어요.","마력이 거의 다 빠져서 쓰임은 아직 수수께끼예요.","Shen'dralas를 둘러보며 다른 기둥을 찾아 달래요."},nx=96010,nt="Fragments of the Pylons"},
[92947]={a={"Valennia Stormfist는 신전 앞으로 대원을 보냈대요.","Windshapers와 High Order가 옆에서 밀고 들어간대요.","소란을 피운 뒤 Hyusaa Quickbreeze를 찾아가래요."},c={"Hyusaa Quickbreeze는 힘들게 왔지만 끝나지 않았대요."},nx=93958,nt="The Inner Sanctum"},
[92959]={a={"Fraxinus는 타락이 뿌리까지 스며들었대요.","오랜 친구 Sunderbark도 분노만 남은 괴물이 됐대요.","동쪽 타락한 웅덩이에서 그를 불러 씨앗을 심어 달래요."}},
[92960]={a={"Elaena Moonwhisper는 악마 기운을 걱정해요.","악마 짐승들이 동족의 힘을 빨아 아군을 공격한대요.","짐승들을 쓰러뜨리고 남은 샘플을 챙겨 달래요."},nx=96003,nt="Drawing Down the Malevolent"},
[93016]={a={"Mordent Evenshade는 설명 없이 일을 시킨 걸 사과해요.","하늘이 이상해서 더 수상해 보였을 것 같대요.","궁금한 걸 물어보면 기꺼이 답해 주겠대요."},nx=93394,nt="Meeting the Magister"},
[93030]={a={"Knight of Mourning은 예전에 당신처럼 빛을 섬긴 기사였대요.","죽은 뒤에도 이곳에 남은 건 끝내지 못한 맹세 때문이래요.","그의 못다 한 임무와 실패 이야기를 들어 달래요."}},
[93034]={a={"현자 우텍의 정찰병이 돌아와 소식을 전했어요.","Magram이 뼈의 골짜기에서 사악한 것을 찾은 듯해요.","남쪽 입구의 정찰병 Nerlokh를 찾아가래요."},c={"Nerlokh가 뼈의 골짜기는 영원히 저주받은 곳이래요.","훈련이 부족해서 여기까지만 간다고 해요.","겔키스를 위해 싸워 달래요."},nx=93035,nt="Ravaging Ravagers"},
[93035]={a={"Nerlokh가 두 발로 걷는 언데드를 가리켜요.","Magram이 오래전 죽은 자들의 시신을 더럽힌대요.","그 언데드를 잠재워 달라고 부탁해요."},c={"Nerlokh가 당신이 지쳤지만 꺾이진 않았다고 해요.","골짜기의 혼란은 오히려 더 커졌대요.","그러니 계속 밀고 나아가야 한대요."},nx=93041,nt="Facing the Truth"},
[93036]={a={"Aonda는 Sania Silverstream이 전도사라고 해요.","마을은 충돌을 피하려고 그녀를 그냥 두고 있어요.","새로 온 당신이 그녀를 통해 계획을 알아 달래요."},c={"Sania Silverstream은 자신을 젊은 여사제라고 소개해요.","Windlord Al'Akir를 더 알고 싶냐고 물어요."},nx=92529,nt="Falaath Village"},
[93037]={a={"Nerlokh은 뼈의 골짜기에서 당신을 기다리고 있어요.","그는 자신의 의심이 맞는지 확인하고 싶대요.","약해 보이는 네크로맨서의 의식복을 가져다 달래요."},c={"Nerlokh은 옷을 보고 표정이 싸늘해졌어요.","이 하급 네크로맨서들은 Gelkis 소속이래요.","일부는 Magram에게 잘 보이려고 편을 바꾼 것 같대요."},nx=93041,nt="Facing the Truth"},
[93041]={a={"Nerlokh는 충격적인 발견을 했대요.","이 일은 현자 우텍이 알아야 한대요.","최근 저주받은 해골을 찾아 우텍에게 가져다 달래요."},nx=93044,nt="A Cleansing Cry"},
[93044]={a={"현자 우텍은 Magram의 네크로맨서에 맞설 무기를 만들려 해요.","재료는 적지만 그게 가장 큰 희망이래요.","마을 동굴 속 Mulara에게 크리스털을 받아 달래요."},c={"현자 우텍은 Mulara가 도와줘서 고맙대요.","남는 크리스털이 없을까 봐 걱정했대요.","곧 계획을 설명해 준대요."},nx=93045,nt="Test Your Theory"},
[93045]={a={"현자 우텍이 해골을 옛 뼈들 곁에 놓아 봤대요.","해골에서 병든 빛이 퍼져 뼈를 물들였대요.","draenethyst 결정으로 저주를 풀어 달래요."}},
[93058]={a={"Nerlokh는 잃은 Gelkis 중 일부가 포로로 잡혔다고 해요.","Magram 괴물이 달려드는 바람에 자세히 살피지 못했대요.","뼈의 골짜기에 다시 들어가 포로들을 구해 달래요."},nx=93122,nt="Checking Things Out"},
[93062]={a={"Nerlokh는 이 지팡이가 Uthek의 것이라고 했어요.","흙 속 해골은 실패한 소환물이래요.","뼈의 골짜기에서 저주를 풀어 편히 쉬게 해 달래요."},nx=93122,nt="Checking Things Out"},
[93065]={a={"Valennia Stormfist는 평화 유지대를 소집하고 있어요.","떠나기 전에 모두를 마지막으로 점검한대요.","준비를 마치고 마을 동쪽 길에서 만나자고 해요."},c={"Valennia Stormfist는 이제 준비가 다 됐다고 해요."},nx=92947,nt="Making Our Move"},
[93066]={a={"Orgrul은 골짜기 건너편에 거점을 세웠대요.","가는 길에 Bristleback이 침입해서 막고 있대요.","가시와 돼지를 마구 처치하고 Hagiak에게 보고해 달래요."},nx=93072,nt="Long-Term Solutions"},
[93072]={a={"Hagiak은 남서쪽에 Gelkis의 켄타우로스 마을이 있대요.","그는 당신이 피를 흘리고 오기를 바란대요.","Magram에 충성을 보이도록 그들을 공격해 달래요."},nx=93188,nt="Return to Orgrul"},
[93090]={a={"Talaanis Shadowsong은 Ayessa에게 고마워해요.","Windshapers의 샤먼들이 떠나는 계획에 축복을 줬대요.","그 해결책이 섬에 안정을 가져오길 바란대요."},c={"Ayessa는 Shadowsong의 축복을 받아 기뻐해요.","Muln이 멀고어와 섬을 잇는 교통편을 마련했대요.","벌써 건너편에서 기다리는 사람들도 있대요."},nx=95349,nt="The Earthen Ring"},
[93122]={a={"Nerlokh는 Magram 부족의 힘을 얕잡아 봤다고 해요.","그들의 마을이 허술해졌을지도 모른대요.","뼈의 골짜기 깊숙이 들어가 살펴봐 달래요."},nx=93128,nt="Khan Jehn"},
[93125]={a={"Rokren은 Gelkis 동족의 말을 믿고 이곳에 왔대요.","동족이 Magram에 붙으려고 네크로맨시에 손댔대요.","Rokren을 천막에서 빼내 Nerlokh에게 알려 달래요."}},
[93126]={a={"해골에게 이 phylactery를 주면 무언가 깨어날 거래요.","그게 무엇일지는 아무도 모른대요.","살아남으면 여기서 본 것을 누군가에게 알려 달래요."}},
[93127]={a={"Tiala Whitemane은 전략으로 Wild King을 이기자고 해요.","언덕 곳곳의 감시 돌들은 힘이 빠져 있대요.","Blackthorne 순찰을 피해 감시 돌을 되살려 달래요."}},
[93128]={a={"Nerlokh은 다른 부족 칸을 칠 기회가 짧다고 걱정해요.","뼈의 골짜기 일로 Khan Jehn을 지키는 병력이 적대요.","그러니 빨리 움직여 Khan Jehn을 쓰러뜨려 달래요."}},
[93129]={a={"Hagiak은 Magram 편에서 말하고 있어요.","Outcast Hideaway에서 적을 치면 보급품도 얻대요.","그 보급품을 Magram 전선의 Hagiak에게 가져다 달래요."},nx=93188,nt="Return to Orgrul"},
[93159]={a={"Strange Hermit은 오랫동안 누구와도 말하지 않았대요.","그래서 말이 어색하고 더듬거린대요.","당신에게 오늘 하루가 어땠는지 물어봐요."},c={"Strange Hermit은 예전엔 다른 곳에 있었다고 해요.","지금은 친구와 자기가 만든 물건이 있어 충분하대요.","말을 받아 주는 사람과 얘기해서 좋았대요."}},
[93160]={a={"Strange Hermit은 숲 바닥에서 도토리를 모으고 있어요.","숲에 큰 새들이 많아 혼자 가기 위험하대요.","도토리를 모아 주면 맛있는 걸 만들어 준대요."},c={"Strange Hermit은 도토리를 구우면 정말 맛있다고 해요.","양해를 구하고 바로 요리를 시작하겠대요."},nx=93161,nt="The Ancient Hilt"},
[93161]={a={"어두운 곳에서 부러진 고대 검 손잡이를 찾았어요.","칼날은 없지만 솜씨가 뛰어난 귀한 가보래요.","이 물건에 관심 있을 사람을 찾아 달래요."},nx=97029,nt="Eluvi'ana"},
[93165]={a={"Vayn Moongaze는 사이비 집단에게 큰 비극을 당했대요.","그래서 사이비 신도의 귀를 가져오면 보상을 줘요.","믿을 만하면 Nightclaw의 비밀도 준대요."},c={"Vayn Moongaze는 사이비 집단을 없애면 좋은 일만 생긴대요.","Nightclaw를 얕보면 안 된다는 뜻이 전해지길 바래요.","더 잡으면 다시 귀를 가져오라고 해요."}},
[93172]={a={"숲 북동쪽 옛 유적에 유령 같은 정령이 모여요.","밤이면 그 정령들이 슬프게 노래하는 게 들린대요.","용기가 있다면 그 정령들을 풀어 달라고 해요."},nx=93161,nt="The Ancient Hilt"},
[93176]={a={"Amaryllis Webb는 자기가 모은 작은 생물들을 자랑해요.","메모와 도구가 든 Entomology Starter Kit을 줘요.","그 도구로 타란툴라 등을 찾아 잡아 달래요."},c={"이 녀석의 앞다리와 턱을 보니 정말 멋져요.","곤충학자 같지는 않은데 눈썰미가 좋네요.","이 녀석이 마음에 들었나 봐요, 이건 가져가세요."}},
[93188]={a={"Hagiak은 당신이 전선에서 할 만큼 했다고 해요.","Magram 전선이 강해져서 이제 스스로 버틸 수 있대요.","Orgrul에게 맡은 일을 다 했다고 전해 달래요."},nx=93196,nt="Khan Jehn"},
[93196]={a={"Orgrul은 Khan Jehn이 외부인 무리에게 죽었다고 말해요.","Orgrul은 그 일을 Gelkis의 짓이라고 봐요.","Khan Jehn을 되살릴 의식을 마그람 마을에서 해 달래요."}},
[93197]={a={"Sebelia는 전투와 후퇴 때문에 일손이 많이 부족해요.","하이잘 산 정상 캠프의 우편물을 눈망루 마을로 보내야 해요.","여관주인 비지에게 소포를 전해 달래요."},nx=93406,nt="Unfrozen Deliveries"},
[93225]={a={"구르다 와일드메인은 켄타우로스들이 몰래 거래하는 걸 봤대요.","그들이 쓰는 돈은 조각된 토템이래요.","진짜 토템을 구해 침묵의 초소로 가져다 달래요."},c={"켄타우로스의 솜씨가 이렇게 뛰어날 줄은 몰랐어요.","이렇게 많은 이야기를 나무에 새길 만큼 인내심이 있을 줄은 몰랐어요.","준비되면 다시 와서 말해 달래요."}},
[93269]={a={"여관주인 비지가 우편물을 다 되찾았대요.","이제 그 우편물을 하이잘 산 정상까지 가져가야 해요.","정상의 Sebelia에게 전해 달래요."}},
[93317]={a={"Nyalah Brightfire는 호수의 게 고기가 필요해요.","이 게는 1년 중 잠깐만 잡을 수 있대요.","호숫가와 강가에서 게 고기를 구해 달래요."},c={"Nyalah Brightfire는 고기가 아주 좋아 보인다며 기뻐해요.","당신에게 고맙다고 인사해요."}},
[93318]={a={"Vulgara the Insatiable에게 현상금이 걸렸어요.","Shen'dar 마을 남서쪽에서 봤다는 날개 괴물이래요.","고지대를 휩쓰는 괴물이니 조심히 다가가래요."}},
[93319]={a={"Teeri Wellwind는 비상용 windstone을 따로 모아 둬요.","그런데 windstone이 자꾸 사라져 도적 짓 같대요.","북쪽 도적 굴에 가서 되찾아 달래요."},c={"Teeri Wellwind는 이걸로 당분간 버틸 수 있겠대요.","보급로를 빨리 정리하지 못하면 더 큰 문제가 온대요."}},
[93320]={a={"Valennia Stormfist는 동쪽 감시탑이 공격받고 있대요.","지원대를 보냈지만 추가 도움이 더 필요해요.","Yorana Windyreed에게 도울 방법을 물어 달래요."},c={"Yorana Windyreed는 적이 많아 아직 버티고 있대요.","싸움을 빨리 끝낼 방법을 찾아야 한대요."}},
[93341]={a={"Mithera는 이 정원을 돌보던 사람이에요.","목걸이의 힘으로 묘목을 나무 정령으로 바꿔 두었대요.","정원에 무슨 일이 있었는지 알아봐 달래요."}},
[93362]={a={"Mithera는 목걸이를 잃고 마음이 많이 아프대요.","정원의 식물들도 괴로워하고 있대요.","정원의 화난 식물을 빠르고 자비롭게 처리해 달래요."}},
[93394]={a={"Mordent Evenshade는 당신이 큰 건물로 가는 중이래요.","그곳의 Shen'dralar는 반기지 않을 것 같대요.","예의 바르게 굴며 옛 친구 Kirandis를 찾아 달래요."}},
[93404]={a={"Woodwyrd는 아직도 타오르는 불길에 시달리고 있어요.","오래전 실수 때문에 죽어서도 이곳에 묶였대요.","마라우돈의 맑은 물로 불을 꺼 달래요."},nx=93601,nt="Passing the Blame"},
[93406]={a={"며칠 전 누군가 나가는 우편물을 뒤졌대요.","눈망루 마을 북쪽 언덕으로 도망쳤대요.","그러니 우편물을 찾아와 달래요."}},
[93407]={a={"Tiala Whitemane은 방어 시설을 지을 자재가 부족해요.","자연의 힘으로 가시덤불을 키워 방어하려 한대요.","하이잘 산 숲에서 가시덤불 씨앗을 찾아 달래요."},nx=93547,nt="A Thorny Solution"},
[93422]={a={"Blackthorne 세력이 날이 갈수록 거칠어진대요.","Blackthorne 연락병이 주인에게 전하기 전에 막아야 해요.","그녀를 쓰러뜨리고 가진 서신을 가져와 달래요."}},
[93430]={a={"Pelluk은 아끼던 행운의 미끼를 도둑맞았어요.","미끼 없이는 생선을 잡을 수 없어 꼭 되찾아야 해요.","드레노어 난민 낚시꾼이 훔쳐 간 것 같으니 찾아 달래요."},c={"Pelluk은 미끼를 알아보고 기뻐했대요.","고맙다며 나중에 다시 오면 생선을 나눠 준대요."}},
[93444]={a={"Fayran Elthas는 하이잘 산의 괴수 때문에 걱정해요.","그 괴수가 짐승을 잡아먹어 하늘길 여행도 힘들어졌대요.","먼저 정상 그림자 속 표범을 잡고, 그 고기로 괴수를 유인해 달래요."}},
[93450]={a={"Vindael은 영혼이라 대장간 일이 어려워졌대요.","끝내지 못한 검이 모루 위에서 방해가 된대요.","그 검을 영혼의 세계로 보내 달래요."},nx=93546,nt="Spectral Iron Ore"},
[93464]={a={"막투르는 예전에 아조레 알다모트를 쫓아냈대요.","그는 그 힘이 잘못된 손에 들어가면 안 된다고 했대요.","잊혀진 땅에서 그를 찾아 무엇을 아는지 알아봐 달래요."},c={"아조레 알다모트는 그 힘에 대해 조금 알지도 모른대요."},nx=93465,nt="Notes on Draenethyst"},
[93465]={a={"아조레 알다모트는 draenethyst 연구자를 안대요.","Burning Blade 흑마법사들이 그걸 연구하고 있대요.","남동쪽 탑의 Gimashi에게 노트를 가져다 달래요."},nx=93678,nt="Abridged Notes on Draenethyst"},
[93510]={a={"3차 전쟁 참전용사는 하이잘 산이 슬픔으로 가득하대요.","어릴 적 친구 Tobin과 호숫가에서 물수제비를 했대요.","영원의 호수 기슭에 있는 닻을 찾아 추억을 기려 달래요."}},
[93521]={a={"책장에서 Ve'han의 연구 노트를 찾았어요.","Ve'han은 야생 왕을 따라 야생신의 힘을 훔치려 했대요.","이 노트를 Tiala Whitemane에게 가져가 달래요."}},
[93546]={a={"Vindael은 드디어 모루를 다시 쓰게 됐대요.","그런데 철이 떨어져 새로 구해야 한대요.","Shen'dralas에서 유령 철광석을 캐 와 달래요."},nx=96060,nt="Tempered Expectations"},
[93547]={a={"Tiala Whitemane은 적들 때문에 불안해해요.","가시덤불을 키워 캠프를 지키려 한대요.","길가 여관과 창고탑 근처에 가시 씨앗을 심어 달래요."}},
[93551]={a={"떠도는 영혼의 희미한 소원을 들어준 일에 고마워해요.","호숫가 영혼이 옛 친구들과 놀던 추억을 떠올렸대요.","하이잘 산의 부서진 대포 옆에서 만나자고 해요."}},
[93552]={a={"Dalia the Collector는 windstone을 모으고 있어요.","옛날 바람의 정령이 떠나서 섬의 마법이 약해졌대요.","숲 곳곳의 windstone 원석을 모아 달래요."},c={"Dalia는 windstone을 받고 무척 고마워해요.","마법이 점점 사라져 windstone이 더 귀해졌대요.","이 설명서도 받아 가라고 해요."}},
[93567]={a={"3차 전쟁 참전용사는 아직도 그날의 패배를 잊지 못해요.","남동쪽 절벽의 탑 잔해가 그의 마음에 깊이 남았대요.","Mourning's Rest 대포 옆에서 이야기를 들어 달래요."}},
[93568]={a={"짐승의 배 속에서 낡은 목줄이 나왔어요.","글씨가 있지만 알아보기 어려워요.","이 목줄의 주인을 아는 사람에게 전해 달래요."}},
[93572]={a={"Kum'isha는 동족들이 아웃랜드로 돌아가는 걸 도우려 해요.","구슬로 틈을 열면 동족들이 넘어가는데 위험하대요.","그 위험에 맞서 함께 싸워 달라고 부탁해요."}},
[93574]={a={"벌레의 껍데기 조각을 떼어냈어요.","평범하지만 수집가들이 좋아할 만한 물건이래요.","이 껍데기에 관심 있을 사람을 찾아 달래요."}},
[93584]={a={"Thisalee Crow는 우물 주변이 추종자로 가득해 걱정해요.","그들이 Nordrassil을 돌보는 일을 방해하고 있대요.","그 추종자들의 무리를 줄여 달래요."}},
[93594]={a={"Mithera는 목걸이로 깨어난 나무 정령들을 생각해요.","그중 Woodwyrd만 살아남았을지도 모른대요.","Forlorn Gardens에서 Woodwyrd를 찾아 달래요."},nx=93404,nt="Rot and Regret"},
[93601]={a={"Woodwyrd는 목걸이가 도둑맞는 걸 직접 봤대요.","범인은 quilboar라고 해요.","뼈의 골짜기로 북쪽으로 가 중요한 quilboar를 찾아 달래요."},nx=93604,nt="Agamaggan's Blood"},
[93604]={a={"Kog'thug the Brave는 아감마간이 죽은 구릉을 중요하게 여겨요.","가시덩굴 우리의 피는 안 되고 구릉의 좋은 피가 필요하대요.","구릉에서 좋은 아감마간의 핏덩이를 가져다 달래요."},nx=93606,nt="Not on Squealing Terms"},
[93606]={a={"Kog'thug the Brave의 짝과 사이가 틀어졌대요.","Quolga the Wise가 가진 목걸이를 Kog'thug이 원한대요.","꽃다발과 아감마간의 핏덩이를 전해 달래요."}},
[93609]={a={"오래 찾던 목걸이를 드디어 손에 넣었어요.","그런데 목걸이의 마법은 이미 다 빠져 버렸대요.","그래도 Mithera에게 가져다 주는 게 좋대요."}},
[93615]={a={"Shalla'kal은 자기 새끼들이 길을 잃었대요.","하이잘 산 정상 근처에 어두운 것들이 있대요.","야생에서 새끼들을 찾아봐 달래요."}},
[93617]={a={"Kala'th는 야생신들의 질서가 뒤틀렸다고 말해요.","이제 자기 종족이 포식자에게 당하지 않겠대요.","사슴들이 포식자 노릇을 하지 못하게 막아 달래요."}},
[93644]={a={"낡은 일기장을 Shen'dralas 근처에서 찾았어요.","글자가 많이 지워져 알아보기 힘들어요.","글쓴이 Evenshade를 Shen'dralas에서 찾아 달래요."},c={"Mordent Evenshade는 처음엔 아니라고 했어요.","찾은 게 맞지만 적혀 있던 내용은 모두 사라졌대요.","남은 페이지가 있다면 복원해 봐도 좋다고 허락해요."}},
[93663]={a={"Dar는 어부들과 가끔 물건을 주고받아요.","심부름꾼이 물건을 싣고 돌아오지 않았어요.","그 물건을 찾아서 무사히 전해 달래요."}},
[93678]={a={"아조레 알다모트가 옛 기록을 옮겨 적었어요.","기록에 포털과 악마 소환 얘기가 많대요.","이 기록을 막투르에게 가져다 달래요."},nx=93679,nt="Visions of Another"},
[93679]={a={"막투르가 당신이 가져온 기록을 읽어 봤대요.","가장 나이 많은 예언자 Onku가 환영을 봤대요.","그 환영을 같이 보자며 와 달래요."},nx=93684,nt="The Found One"},
[93680]={a={"학자 워딘 보이드글레어는 다시 세워진 달라란이 궁금해요.","도시가 무너진 뒤 마법사들이 달라란을 다시 세웠대요.","몰래 들어갈 방법을 찾아 달래요."},c={"하수도 열쇠네요. 제가 쓸 건 아니에요.","그래도 쓰기 전에 할 일이 아직 많대요."},nx=545,nt="Dalaran Patrols"},
[93684]={a={"막투르는 저주받은 땅 남쪽에서 적대적인 자들을 봤대요.","Onku의 환영이 맞다면 떠도는 draenei가 있을지도 모른대요.","저주받은 땅에서 그 draenei를 찾아 도와 달래요."},nx=93685,nt="To Serve Kum'isha"},
[93685]={a={"수집가 굼이샤는 완전무결한 드레니시스트 결정을 원해요.","draenei들이 그 결정을 찾다 끔찍하게 죽었대요.","저주받은 땅에서 그 결정을 찾아 가져다 달래요."}},
[93686]={a={"수집가 굼이샤의 균열은 일부만 성공했대요.","수집가 굼이샤는 계속 시도해야 한대요.","저주받은 땅에서 완전무결한 드레니시스트 결정을 또 찾아 달래요."}},
[93735]={a={"Ayessa Dawnsinger는 장치가 고장 났대요.","고치러 간 기술자가 도움이 필요할지도 몰라요.","마을 서쪽 끝으로 가서 도와 달래요."},c={"Riaani Nightwind는 장치 판 밑에 파묻혀 고치는 중이에요.","핵심 부품이 어디 갔냐고 화를 내요.","Gyrozephyr까지 누가 뺐냐며 투덜대요."},nx=93737,nt="The Broken Construct"},
[93736]={a={"Endaria Mistgaze는 바람의 정령이 왜 떠났는지 알고 싶어요.","북쪽 Shadowgale 숲에 hollow라는 바람 정령이 있대요.","그것들을 흩어 버리고 남은 것을 가져다 달래요."},c={"Endaria Mistgaze는 이 정수를 만지니 마음이 불안하대요.","나쁘고 후회하는 기운이 느껴져 정신이 아득하대요.","이걸 더 연구하고 싶지 않다고 해요."}},
[93737]={a={"Riaani Nightwind는 망가진 구조물을 고치는 중이에요.","구조물 속을 살피느라 지금은 바쁘대요.","잠시 기다리면 도울 일을 알려 준대요."},c={"Riaani Nightwind가 재료를 모아 줘서 고맙대요.","이 부품이면 구조물을 다시 움직일 수 있대요.","기억이 남아 있으면 누가 부품을 가져갔는지 알 수 있대요."},nx=93738,nt="The Broken Construct"},
[93738]={a={"Riaani는 High Order가 부품을 빼려 했다고 봐요.","High Order는 바람 정령 마법을 자꾸 건드려 골칫거리래요.","Ayessa에게 이 일을 보고하라고 해요."},c={"Ayessa는 High Order 탓이냐며 놀라요.","Belathaan은 Valennia Stormfist의 사촌이래요.","그가 연루됐다니 실망스럽고 잠시 생각을 정리하겠대요."},nx=93746,nt="A Firm Response"},
[93739]={a={"Thrall은 Horde의 수도들을 차례로 둘러보라고 해요.","언더시티, 오그리마, 썬더 블러프 모두 특색이 달라요.","먼저 자문관 나즈그렐에게 길을 물어보래요."},c={"Thrall은 돌아온 나를 반기며 많이 배웠기를 바란대요.","당신 쪽 사람들은 아직 멀고어에 자리 잡는 중이래요.","기다리는 동안 오그리마 근처 불모의 땅을 둘러보래요."}},
[93740]={a={"Windshaper 수련생 몇 명이 죽은 채 발견됐어요.","범인은 Al'Aketh일 가능성이 크대요.","북쪽의 Al'Aketh를 처치하고 부적을 가져오라고 해요."},c={"Ayessa는 얼이 빠진 듯 멍해 보여요.","오늘은 힘든 하루였다며 신경 쓰지 말래요.","지금까지 도와준 데 고맙다고 해요."}},
[93746]={a={"High Order는 이미 경고를 받았대요.","Belathaan이 Shrine of Akir 쪽으로 떠났대요.","길에서 따로 찾아가 겁을 주라고 해요."},c={"Belathaan이 죽었다는 말에 Ayessa가 놀라요.","High Order가 Al'Aketh와 평화를 논의하던 중이었냐고 물어요.","당신 잘못이 아니니 신경 쓰지 말래요."}},
[93747]={a={"Ketharas는 낡은 전쟁 무기들이 썩어 가는 걸 걱정해요.","마법을 살짝 넣은 씨앗으로 자연이 그 흔적을 덮게 하려 해요.","옛 무기 옆에 씨앗을 심어 달래요."}},
[93759]={a={"Ketharas는 지금 스튜를 끓이고 있어요.","짐승을 해치는 건 싫지만 먹을 것은 필요하대요.","하이잘 산의 사슴 고기와 뿌리를 모아 달래요."}},
[93773]={a={"덴드리트 스타블레이즈는 Ve'han이 야생 신의 힘을 훔쳤대요.","믿기 힘든 일이지만 사실인 듯하대요.","Ketharas에게 돌아가 이 얘기를 전해 달래요."},nx=96930,nt="The Capricious Corvid"},
[93786]={a={"Krom'rosh는 강 건너편 인간들의 농장에 화가 나 있어요.","인간들이 땅을 차지하고 세력을 넓혔대요.","농사를 방해하고 돌아와 소식을 전해 달래요."}},
[93787]={a={"Krom'rosh는 인간들이 이 땅에서 누리던 걸 빼앗으려 해요.","인간들의 농장에 식량이 쌓여 있대요.","닥치는 대로 가져와서 돌아와 달래요."}},
[93788]={a={"Kreza Darkthorn은 자원을 구하기가 힘들어졌대요.","적의 도끼를 가져다 무기를 만들려 해요.","강 따라 내려가 벌목꾼들의 도끼를 가져와 달래요."}},
[93825]={a={"Suma Mossmane은 하이잘 산의 나무들과 이야기를 나눠요.","Moonveil moss는 상처를 낫게 하고 뿌리를 축복해요.","안개 낀 오래된 나무에서 그 이끼를 가져다 달래요."}},
[93826]={a={"Elder Mistpaw는 Deadwood 때문에 숲이 흔들린대요.","Deadwood가 나무를 할퀴고 우리를 공격해 와요.","그들의 굴에 가서 뿌리를 더럽힌 자들을 처치해 달래요."}},
[93827]={a={"Thobon Sapclaw는 산바람에 나쁜 징조가 보인대요.","하피들은 높은 곳에 둥지를 틀고 힘 있는 보석을 지녀요.","하늘 마녀들의 부적을 가져다 달래요."}},
[93828]={a={"Fennar Mossmane은 습한 공기 때문에 약초가 잘 안 말라요.","동료들이 돌아와 약초를 굴 곳곳에 널어 두었대요.","말린 약초를 모아 가져다 달래요."}},
[93830]={a={"Fennar Mossmane은 이곳 샘물이 느려서 걱정이래요.","Deadwood 연못은 하이잘 산의 눈 녹은 물로 채워졌어요.","그 물을 물주머니에 담아 가져다 달래요."}},
[93831]={a={"Osi Mistpaw는 Bear Berries를 무척 좋아해요.","열매는 그늘에 있는데 위험한 것들이 많대요.","열매를 가져다주면 잼을 만들어 맛보여 줄게요."}},
[93832]={a={"Elder Mistpaw는 높은 비탈의 돌 괴물들이 걱정이래요.","누군가 깎아 만든 돌 괴물이라 가까이 가면 깨어나요.","돌 괴물을 부숴서 산이 다시 숨 쉬게 해 달래요."}},
[93833]={a={"Elder Pinespeaker는 부엉이 깃털과 뼈로 부적을 만들어요.","부엉이는 그냥 주지 않아서 직접 잡아야 해요.","잡은 부엉이 몸통을 통째로 가져다 달래요."}},
[93834]={a={"Dala Fairmaw의 굴을 딱정벌레들이 자꾸 파헤쳐요.","딱정벌레는 재빠르고 어둠에 숨어서 잡기 어려워요.","굴을 오를 때 보이면 밟아 잡아 달래요."}},
[93836]={a={"Ayessa는 Al'Akir를 두려워할 이유가 충분하대요.","Zephras를 숨기던 장벽이 사라져 무방비래요.","Talaanis Shadowsong에게 이 위험을 전해 달래요."},c={"Talaanis는 Ayessa가 섬을 떠날 계획을 들어요.","Lorthuna를 없앴으니 그나마 다행이래요.","Al'Akir가 올 때까지 몇 년, 어쩌면 수십 년 걸린대요."},nx=93090,nt="What Comes Next"},
[93848]={a={"Tiala Whitemane은 Ketharas의 마법 덕분에 이겼대요.","드루이드들이 그 마법을 익혀 적의 보호막을 풀 거래요.","Ketharas에게 하이잘 산 수호자의 감사를 전해 달래요."}},
[93926]={a={"Aonda는 탑 하나에 목숨을 걸 수 없대요.","교단이 그 감시탑을 공격하고 있대요.","남서쪽 감시탑 Vaaniel에게 마을로 오라 전해 달래요."},c={"여기 시신은 방금 죽은 것 같대요.","불에 탄 자국을 보니 교단 폭풍 마법사가 죽였대요."},nx=93927,nt="A Last Request"},
[93927]={a={"죽은 경비대원의 시신에서 피 묻은 쪽지가 떨어졌어요.","쪽지를 읽으면 다음 행동에 단서가 될 수 있대요.","그 쪽지를 읽고 다음에 할 일을 알아봐 달래요."}},
[93948]={a={"Aonda는 탑에서 찾은 인장 반지를 전해 달래요.","Talaanis는 조카의 소식을 알고 싶어 할 거래요.","그의 상실에 위로를 전해 달래요."},c={"Talaanis는 조카 소식에 몹시 안타까워해요.","반지를 찾아 와 줘서 고맙대요.","일이 필요하면 Valennia Stormfist를 찾아가래요."},nx=93949,nt="Bugged"},
[93949]={a={"Valennia는 Skyhopper 철이라 벌레가 많대요.","엿듣는 마법이 걸린 벌레를 교단이 첩자로 쓰는 것 같대요.","마법 걸린 벌레를 구별할 수 없으니 보이는 대로 다 잡아 달래요."},c={"Valanaar 주변엔 벌레가 더 있을 거래요.","마법 걸린 벌레를 하나 잡을 때마다 도시가 조금 안전해져요."}},
[93951]={a={"Taleen Shimmerthread는 머리 장식용 깃털을 원해요.","마을 남서쪽에 Hippogryph들이 살고 있대요.","둥지 근처에 떨어진 깃털을 주워 달래요."},c={"머리 장식 깃털 모으기가 겉치레처럼 보일 수 있대요.","그래도 힘든 때일수록 작은 기쁨을 누려야 한대요.","Zephras에 기쁨을 나눠 줘서 고마워해요."}},
[93952]={a={"Brerufa의 부족은 뿌리가 약해졌대요.","Deadwood가 땅을 할퀴고 굴의 경비병이 가장 강해요.","그 경비병들을 쓰러뜨려 하이잘 산을 지켜 달래요."}},
[93958]={a={"Valennia 쪽 병력이 안쪽 성소를 뚫었대요.","안에서 싸움이 치열했는데 지금은 이상하리만치 조용해요.","살아남은 병력이 있으면 Valennia와 합류해 달래요."}},
[93976]={a={"Kreza Darkthorn은 부두에 아는 사람이 있대요.","그 사람에게 줄 칼을 하나 만들어 뒀대요.","Kreza가 보냈다고 전하고 셈은 끝났다고 해 달래요."},nx=95288,nt="Smuggler's Paradise"},
[94003]={a={"Seena Skybreaker는 가문에서 살아남은 마지막 사람이에요.","광신도 Zaal Stormshield가 가문의 방패를 쥐고 있어요.","Shrine of Akir에서 방패를 되찾아 달래요."},c={"가문의 명예를 되찾아 줘서 고맙다고 해요.","보답으로 Skybreaker Defense의 비법을 가르쳐 준대요.","그 기술을 쓸 방패도 하나 줘요."}},
[94006]={a={"Lotheluum Starbreeze는 당신을 위대한 정령에게 소개해요.","Urs'endris의 영역이 시들어 하늘로 떨어지고 있대요.","북동쪽 폭포 근처로 찾아가 보래요."},nx=94638,nt="Strength and Mercy"},
[94007]={a={"Elayaa Easewind는 이제 짐승 친구를 찾을 때라고 해요.","Valanaar 항구의 Quel'ana Quickgale에게 가 보래요.","그가 짐승 길들이는 기술을 가르쳐 준대요."},c={"와 줘서 정말 반갑다고 해요.","이제 함께 시작해 보자고 해요."},nx=94978,nt="Taming the Beast"},
[94013]={a={"Quel'ana Quickgale은 마지막 시험을 준비했대요.","조련용 막대를 들고 Gustberry Lowlands로 가래요.","그곳의 Vuldren Alpha를 길들인 뒤 막대를 돌려주래요."},c={"빨리 배운다며 크게 칭찬해요.","이제 동물과 오래가는 유대를 맺는 법을 가르쳐 준대요."},nx=94050,nt="Training the Beast"},
[94050]={a={"Quel'ana Quickgale은 펫을 훈련하려면 기술도 배워야 한대요.","그 기술은 여동생 Quel'dora Quickgale에게 배우래요.","Valanaar에 있는 그녀를 찾아가 보래요."},c={"아직 초보라면서도 펫 훈련 기술을 알려 줘요.","펫에게 새 능력을 가르치고 먹이고 되살릴 수 있대요."}},
[94212]={c={"Muggol Breezebeard는 누가 직접 가져다줄 줄 몰랐대요.","고맙고 훌륭한 노력이라고 칭찬해요.","지혜의 비약으로 명상을 돕고, 여행 이야기도 듣고 싶대요."}},
[94213]={c={"Ash'alari는 주문한 하급 마나 물약을 제때 받아 기뻐해요.","고마움의 표시로 작은 선물을 주대요."}},
[94216]={c={"지즈 피직스는 새 직장에서 좋은 첫인상이 필요하대요.","남의 공을 자기 것처럼 말하라고 조언해요.","비약을 받고 자기가 만든 것처럼 말할 거래요."}},
[94217]={c={"땅딸보 존 미스릴이 주문한 게 딱 이거래요.","돈을 주며 꼭 품에 안고 나가라고 해요."}},
[94225]={c={"지즈 피직스는 이게 주문한 다리보호구가 맞대요.","며칠이라더니 몇 달이 걸렸다며 주문을 취소해요.","돈을 주며 얼른 가라고 해요."}},
[94226]={c={"\"바다늑대\" 맥킨리는 번역이 크게 잘못됐대요.","주문한 것과 다른 물건이 와서 화를 내요.","그래도 당분간은 쓸 데가 있을 거래요."}},
[94227]={c={"\"씩씩이\" 존슨은 말 대신 꼬꼬댁 울어요.","부리에 큰 청동 나이프를 물고 학자 틸스를 노려봐요."}},
[94230]={c={"Alyce는 양 폭탄이 생각보다 작다고 해요.","Alyce는 조심스럽게 양 폭탄을 받아 내려놓았대요.","이걸로 몇몇을 쫓아내기를 바란대요."}},
[94232]={c={"크직스는 저주 해제 장치를 주문했는데 이건 다르대요.","환불은 복잡하니 그냥 받아 가겠대요.","다음에는 주문을 더 자세히 적겠대요."}},
[94237]={c={"Kixxle은 제때 와 줘서 반가워해요.","탄환이 떨어져서 아직 못 떠났대요.","돈을 더 벌 게 남아서도 떠나지 않는대요."}},
[94239]={c={"Alyce는 주문을 쓴 뒤에 옷 전체가 필요한 걸 알았대요.","먼 길을 와 줘서 이 주문을 들어준대요.","어서 받고 가라며 손짓해요."}},
[94247]={c={"Alan Sneeks는 낮은 목소리로 속삭여요.","대낮에 고급 로브를 가죽옷 입은 남자에게 주면 수상하대요.","하지만 Kirin Tor를 대신해 왔으니 수상한 거래는 없대요."}},
[94253]={c={"Hekshi는 곧 줄구룹 성문에 몰래 들어갈 계획이래요.","그곳 의식 사제처럼 차려입으려고 이 킬트가 딱 필요하대요."}},
[94265]={c={"연금술사 페슬저그는 고블린 로켓 연료 냄새를 맡고 좋아해요.","Nixx가 조제법을 안 알려줘서 연료를 어디서 사 오는지 따라다닌대요.","Nixx에게는 비밀로 해 달래요."}},
[94399]={a={"모르벡은 라바사우루스가 고기만 먹는다고 해요.","운고로 분화구에도 먹이가 귀할 때가 있대요.","디메트로돈과 Pterrodax의 고기를 가져다 달래요."}},
[94411]={a={"Illaya는 북쪽 선돌에 High Order가 보였대요.","여러 번 경고했는데도 점점 대담해진대요.","선돌에서 그들을 쫓아내고 돌아와 보고해 달래요."},c={"shen'dorei끼리 싸우면 우리 힘만 약해진대요.","그래도 큰 비극을 막으려면 단호해질 때도 있대요.","High Order 마법사들은 결과를 전혀 신경 쓰지 않는대요."}},
[94414]={a={"Halaan은 anchor pylon을 자주 보러 온대요.","바람의 마법이 요즘 불안정해졌대요.","보려면 그의 선물을 빌려 가라고 해요."},c={"Halaan이 시간을 내 줘서 고맙다고 해요.","숲을 계속 지키며 고향의 상태를 생각해 보겠대요."}},
[94427]={a={"Danitha Morr는 선함을 좇는 것이 성기사의 핵심이라고 해요.","비극을 겪고 이곳에 온 사람은 그 은총을 잃기 쉽대요.","언더시티에 있는 Tanis Alderwood를 찾아가 도와 달래요."},c={"Tanis Alderwood가 성기사를 보고 겁에 질려 빌어요.","구걸하면 안 된다는 건 알지만 성기사와 다툴 생각은 없대요.","제발 그냥 내버려 달래요."},nx=94434,nt="A Lesson in Divinity"},
[94434]={a={"Tanis Alderwood의 아내는 말 그대로 몸이 무너지고 있대요.","약제사들은 레이디의 일로 바빠서 아내를 고칠 수가 없대요.","아내를 감싸게 깨끗한 리넨 옷감을 가져다 달래요."},c={"Tanis Alderwood가 정말 친절하다며 고마워해요."},nx=94435,nt="A Lesson in Divinity"},
[94435]={a={"Tanis Alderwood는 왜 도와주는지 궁금해하대요.","그래도 고마워하며 언제든 친구로 여기겠대요.","보내 준 사람에게도 고맙다고 전해 달래요."},c={"Danitha Morr가 작은 봉사도 빛과의 연결을 돕는대요.","동족이 다시 번영하도록 우리도 몫을 다하겠대요.","다음 일에 필요하니 이 상징을 받으래요."},nx=94436,nt="A Lesson in Divinity"},
[94436]={a={"Danitha Morr가 빛의 힘을 보여 줄 때라고 해요.","받은 생명의 징표는 만지면 조금 아플 수 있대요.","아래층의 Deathguard Billmuth를 찾아가 도와 달래요."},nx=94438,nt="A Lesson in Divinity"},
[94438]={a={"Deathguard Billmuth는 Falgan과 정찰을 갔대요.","scarlet이 브릴을 칠 계획을 엿듣다 들켰대요.","Falgan을 찾아 도울 수 있으면 도와 달래요."},c={"Falgan은 성기사에게 구해져 놀랐어요.","생명의 징표를 보고 도우러 왔다고 짐작했대요.","scarlet이 어떤 공격을 계획 중이라고 해요."},nx=94440,nt="A Lesson in Divinity"},
[94440]={a={"Deathguard Falgan은 Scarlet 병사들의 명령서를 원한대요.","Scarlet 병사들은 출동 명령서를 가방에 넣고 다닌대요.","Scarlet을 처치하고 명령서를 가져다 Billmuth에게 주래요."},nx=94441,nt="A Lesson in Divinity"},
[94441]={a={"Deathguard Billmuth는 성기사들의 도움을 높이 평가해요.","다른 동료들에게도 이 일을 알리겠대요.","Danitha Morr에게 이 소식과 감사를 전해 달래요."},c={"Danitha Morr가 당신에게 부활의 힘을 준대요.","생명의 징표는 준비된 성기사만 쓸 수 있대요.","동족의 마음을 얻는 일은 노력할 가치가 있대요."}},
[94479]={a={"녹슨 금속 조각 아래에서 더 반짝이는 부품을 찾았어요.","쓸 만한 것은 다 가져가고 이것만 남은 것 같대요.","이 부품을 알아보거나 쓸 만한 사람을 찾아 달래요."},nx=96796,nt="Woods Workshop"},
[94480]={a={"Krom'rosh는 적이 많아 걱정이 커요.","동맹들이 힘을 잃으면 Rog'mar가 위험해진대요.","모은 식량을 Gorg에게 가져다 달래요."},nx=94481,nt="A Serving of Strength"},
[94481]={a={"Gorg는 훈련생들을 먹일 든든한 스튜를 끓였어요.","든든히 먹어야 적을 멀리 막을 수 있대요.","이 스튜를 서쪽 훈련장에 가져다 달래요."}},
[94483]={a={"Krom'rosh는 강 남쪽에 인간들의 훈련 캠프가 있다고 들었어요.","인간들을 요새에 가둬 두면 시간이 생긴대요.","빨리 가서 그들을 물리쳐 달래요."}},
[94484]={a={"Lotheluum은 드루이드들의 소식을 기다려요.","소식이 늦어 무슨 큰일이 났나 걱정해요.","Elegael Thornpaw를 찾아가 안심시켜 달래요."},c={"Elegael Thornpaw는 지원군이 왜 안 왔냐며 의아해해요.","메시지가 전해지지 않았다는 걸 알게 돼요.","이제 스스로 해결하는 수밖에 없대요."}},
[94485]={a={"Elegael Thornpaw는 부상자를 위한 약재가 필요해요.","그 이끼는 나무 밑동에 자라고 상처를 붙여 준대요.","숲에서 레이디의 눈물 이끼를 구해 달래요."},c={"Elegael Thornpaw는 이게 바로 필요했다며 잘했다고 해요."}},
[94486]={a={"Elegael Thornpaw는 이끼 위에 덮을 깃털이 필요해요.","깃털이 진이 마르지 않게 막아 준대요.","사나워진 Shrieklings를 조심해서 깃털을 모아 달래요."},c={"Elegael은 깃털을 한 올도 허투루 쓰지 않겠대요.","그들의 희생이 헛되지 않게 하려는 거래요."}},
[94487]={a={"Elegael은 Al'Aketh 교단에게 기습을 당했대요.","왜 그랬는지는 아직 알 수 없대요.","교단원들을 쓰러뜨리고 유품을 가져다 달래요."},c={"젊은 목숨이 많이 사라졌다며 안타까워해요.","유품은 High Elder에게 가져갈 때까지 보관한대요.","다음 세대를 기다리며 수집품으로 둔대요."}},
[94488]={a={"드루이드 Haalien이 몇 달 전 사라졌대요.","교단과 한편이 된 것 같대요.","Haalien을 처치하고 머리를 가져오라고 해요."},c={"Elegael은 화가 나도 사촌을 베기는 힘들었을 거래요.","그는 무지와 악의로 많은 무고한 이들을 죽였대요.","그러니 그를 애도하지 말래요."}},
[94489]={a={"Elegael Thornpaw가 약을 다 만들었대요.","공터 너머 북쪽 동굴의 드루이드들에게 가져다 달래요.","짝인 Jorel이 살아 있다면 상처도 봐 달래요."}},
[94490]={a={"Haalien의 팔찌 뒤에 끼어 있던 쪽지예요.","교단의 속셈이 담긴 정보가 있는 것 같대요.","이 정보를 Elegael에게 전해 달래요."},c={"교단이 pylon을 노린 거냐고 되묻고 있어요.","우리는 방해물이라 죽임을 당했다며 분노해요.","명령이 Valanaar에서 나왔다면 내부 배신자가 있을 거래요."},nx=94491,nt="The Fate of the Den"},
[94491]={a={"Elegael은 몸 상태가 안 좋아 직접 갈 수 없대요.","Valanaar 어딘가에 교단에 정보를 흘리는 자가 있대요.","이 쪽지를 Lotheluum에게 전하고 일어난 일을 알려 달래요."},c={"Lotheluum은 잠시 말을 잇지 못해요.","쪽지가 사실이라면 공범이거나 더 나쁘게는 배신자래요.","이 쪽지를 High Elder에게 바로 가져가겠대요."}},
[94504]={a={"Elder Mistpaw는 지금 일부 부족민만 당신과 말을 나눌 수 있대요.","친해지려면 서두르지 말고 어린이와 노인들 곁에서 함께 일하래요.","부족을 해치려는 자들로부터 지켜 달래요."}},
[94532]={a={"Neza Bloodsnout는 남서쪽 언덕에 적이 많아 걱정해요.","그 적들 때문에 상인과 여행자들이 힘들어졌대요.","동맹들이 지나갈 길을 열어 달래요."}},
[94533]={a={"Neza Bloodsnout는 Snargl의 소리가 아주 거슬린대요.","그 소리에 주변 사람들이 겁먹어 곤란하대요.","Snargl을 처치하고 코를 가져다 달래요."}},
[94535]={a={"남쪽 언덕에서 광석을 캐던 동맹들이 습격을 당했대요.","적들이 훔친 광석이 야영지에 있대요.","남쪽으로 가서 광석을 되찾아 달래요."}},
[94559]={a={"Al'Aketh 안의 배신자가 보호를 받으면 넘어오려 한대요.","그는 Valanaar 북서쪽 집에 숨어 있대요.","조심히 찾아가 데려와 달래요."}},
[94568]={a={"Talaanis는 교단이 두려워 넘어온 배신자가 있었대요.","그 배신자는 죽었고 비밀도 함께 묻혀 버렸대요.","함께 대화를 나누고 다음 방향을 정하자고 해요."},c={"경비대를 보내 교단과 맞서 볼 수도 있대요.","하지만 정면 싸움에서는 이기기 힘들대요.","다른 방법이 필요하다고 해요."},nx=92640,nt="Desperate Times"},
[94638]={a={"Urs'endris의 짝 Ur'endra가 광기에 빠졌대요.","그녀가 제 동족들을 공격하고 있대요.","서쪽 동굴의 그녀를 찾아 고통을 끝내 달래요."},c={"짝을 잃은 고통이 헤아릴 수 없대요.","결의를 보였다며 동족의 모습이 될 축복을 내려 줘요."}},
[94668]={a={"Clugfist는 당신이 약한 Twilight 오우거를 부숴 버렸다고 해요.","오늘 Bloodmaster에게 당신이 여기 어울린다는 걸 보여 주래요.","Jezap Jinglesprocket에게 가 보라고 해요."},nx=94669,nt="Pay to Play"},
[94669]={a={"Jezap이 링에 들어가려면 안전 보증금을 내야 한대요.","안 내면 싸울 생각이 없었다고 Clugfist에게 말하겠대요.","그러니 보증금을 내 달래요."},nx=94670,nt="Bloodmaster's Ring"},
[94670]={a={"Jezap Jinglesprocket이 링 대결이 곧 시작된다고 외쳐요.","첫 상대는 쉬운 편이지만 날뛰는 괴물이래요.","링 안에 들어가서 명성을 얻어 보래요."},nx=94739,nt="Bloodmaster's Ring"},
[94672]={a={"Tran'gul은 광신도 집단이 이단을 공격하기 시작했대요.","서쪽 사람 마을은 무너졌고 다음은 Rog'mar래요.","Sunnyglade에 가서 그들의 수를 줄여 달래요."}},
[94680]={a={"Tran'gul은 광신도들이 예전보다 훨씬 많이 모였다고 걱정해요.","누가 그들을 부추기는지, 무엇을 노리는지 알고 싶대요.","광신도들의 시체에서 나온 물건을 가져다 달래요."},nx=94727,nt="Digging for Answers"},
[94727]={a={"Tran'gul은 Twilight's Hammer가 땅을 파고 있대요.","힘의 원천을 찾는 것 같지만 확실하진 않대요.","Sunnyglade의 광부 하나를 붙잡아 캐물어 달래요."}},
[94733]={a={"Jezap은 Chub'chob의 애완 멧돼지를 맡았대요.","그런데 일이 바빠서 먹이를 챙길 틈이 없대요.","멧돼지 먹이를 위해 Gobam을 찾아가 달래요."},nx=94734,nt="A Boar's Delight"},
[94734]={a={"Gobam은 Chub'chob의 돼지가 맛있는 간식을 좋아한대요.","강가의 식물과 바닷가 농장의 베리가 좋은 재료래요.","그 재료들을 모아 Gobam에게 가져다 달래요."},nx=94737,nt="A Treat for a Friend"},
[94737]={a={"Gobam이 돼지에게 줄 간식 꾸러미를 건네요.","돼지가 이걸 보면 좋아할 거래요.","그 꾸러미를 Jezap Jinglesprocket에게 전해 달래요."},nx=94965,nt="Bloodmaster's Ring"},
[94739]={a={"Jezap Jinglesprocket은 첫 라운드를 버틴 걸 인정해요.","다음 상대는 머리는 나빠도 힘이 아주 세대요.","링 안에 들어가 준비하라고 해요."},nx=94962,nt="Bloodmaster's Ring"},
[94744]={a={"Krom'rosh가 당신의 활약을 칭찬해요.","그의 동생 Da'grosh가 기다리지 않고 정찰대와 먼저 떠났대요.","서쪽 요새에서 그를 도와 싸워 달래요."}},
[94745]={a={"Da'grosh가 서쪽의 Twilight's Shroud 요새를 가리켜요.","요새는 Twilight's Hammer 광신도들로 가득하대요.","그들이 얼마나 약한지 보여 주래요."},nx=94768,nt="Bring Me His Head"},
[94748]={a={"Da'grosh의 전사들이 광신도 챔피언들에게 붙잡혔대요.","서쪽 요새 감옥에 갇혀 있다고 해요.","그들을 풀어 달래요."},nx=94768,nt="Bring Me His Head"},
[94768]={a={"Tran'gul의 기록에 따르면 요새에 우두머리가 있대요.","전사들이 풀려난 지금이 우두머리를 칠 때래요.","Overlord Kilgar를 쓰러뜨리고 그 머리를 가져오래요."}},
[94782]={a={"Curious Crow는 이 지역의 흑마법사들을 제압했대요.","북서쪽 길을 따라 옛 초소로 가 보래요.","그곳에서 기다리는 오랜 친구 Zet'gan을 만나 보래요."}},
[94872]={a={"구르다 와일드메인은 Magram 부족이 영토 싸움에서 이기고 있다고 해요.","그들 마을이 커지고 있어 걱정되지만 동맹으로는 쓸모가 있대요.","마그람 마을의 보급 담당자에게 토템 자루를 전해 달래요."}},
[94873]={a={"구르다 와일드메인은 Gelkis 부족이 밀리고 있다고 해요.","절박해지면 바깥 도움을 받을지도 모른대요.","겔키스 마을의 보급 담당자에게 토템 자루를 전해 달래요."}},
[94895]={a={"라벨에 Friz Frazzlespark의 물건이라고 적혀 있어요.","이 상자는 길을 잃으면 주인에게 돌아가야 한대요.","Friz Frazzlespark에게 돌려 달래요."}},
[94896]={a={"Ealaane은 Ban'aethal에서 급히 피란 왔대요.","한밤중에 마을이 하늘로 떨어지기 시작했대요.","남겨진 물건을 찾아 와 달라고 해요."},c={"피란민들을 도운 큰 은혜라며 고마워해요.","물건은 주인에게 돌려주겠대요.","그래도 새로 시작할 발판이 되겠대요."}},
[94897]={a={"Ealaane의 연인 Resaan이 물자를 구하러 돌아갔대요.","일주일이 넘도록 소식이 없어 최악을 걱정해요.","Resaan을 찾으면 데려오고, 아니면 유품을 가져다 달래요."},c={"Ealaane은 Resaan을 잃고 슬퍼해요.","이제 막 함께 시작한 것 같다며 안타까워해요.","그의 유품이 작은 위안이 되겠대요."}},
[94898]={a={"피난 가던 중 바람 정령들이 나타났대요.","정령들 때문에 많은 사람이 목숨을 잃었대요.","그 정령들을 달래 달라고 해요."}},
[94911]={a={"Muln Earthfury가 드루이드 재능이 많다고 해요.","썬더 블러프의 투락 룬토템을 찾아가 보래요.","그가 달의 숲으로 가는 길을 알려 준대요."}},
[94913]={a={"투락 룬토템은 달의 숲에 가는 주문을 가르쳐 준대요.","달의 숲에서 수호자 레물로스가 드루이드를 지킨대요.","나이트헤이븐의 덴드리트 스타블레이즈에게 지금의 길을 물어보래요."},nx=5930,nt="Great Bear Spirit"},
[94930]={a={"Friz Frazzlespark의 물건이 든 상자가 길을 잃었어요.","상자에는 열지 말라는 경고문이 붙어 있어요.","Powderfuse Port의 Friz에게 상자를 돌려 달래요."}},
[94961]={a={"Fuzzle이 금을 꺼내 보이며 거래를 제안해요.","금이 더 있으니 복수를 도우면 보여 주겠대요.","그 복수를 함께 해 달래요."},c={"그래요, 잘했어요! 이제 여기서 떠나 보물을 찾으러 가요."},nx=94963,nt="Biting the Hand"},
[94962]={a={"Jezap은 몇 번 이긴 걸로는 아직 멀었다고 해요.","다음 상대는 놀라운 상대일 거라고 귀띔해요.","그 상대 Bonegnaw와 링에서 싸워 달래요."},nx=94964,nt="Bloodmaster's Ring"},
[94963]={a={"Fuzzle이 이제 여기를 떠나자고 해요.","막는 자는 가만두지 않겠대요.","안전해지면 보상을 주겠다고 약속해요."},c={"Fuzzle이 꽤 많은 금을 모아 뒀대요.","이제 그 금은 받은 거예요."}},
[94964]={a={"Jezap은 링의 흥을 계속 살리고 싶대요.","이번 상대는 만만치 않은 강자래요.","링에 들어가 Mog'thar와 싸워 달래요."},nx=94733,nt="Our Ogre Friend"},
[94965]={a={"Jezap은 돼지 Snufflesnout에게 간식을 준다고 해요.","그런데 돼지가 간식을 보고 흥분할 수도 있대요.","링에 들어가서 그 돼지와 맞서 달래요."},nx=95063,nt="Bloodmaster's Ring"},
[94968]={a={"Krom'rosh는 굴에 들어간 사람 대부분이 죽었다고 해요.","Twilight 세력이 생각보다 훨씬 크다고 걱정해요.","그 요새에 들어가 우두머리가 죽었다는 증거를 가져오래요."}},
[94971]={a={"Danitha Morr는 팔라딘에게 전투마가 중요하다고 해요.","이제 당신도 자신의 말을 가질 때가 됐대요.","Danitha Morr에게 가서 전투마 소환법을 배우래요."}},
[94972]={a={"Tran'gul은 적들의 위치가 드러났대요.","이 요새 안에 숨겨진 비밀이 있을 것 같대요.","쓸모 있는 정보를 찾아 돌아와 달래요."}},
[94974]={a={"Kreza Darkthorn은 거친 틀로 열쇠를 만들 수 있을 것 같대요.","재료를 모으는 데 시간이 걸릴 것 같대요.","두꺼운 가죽과 철 주괴를 가져다 달래요."}},
[94975]={a={"Da'grosh는 광신도들이 동맹에게 큰 피해를 줬다고 해요.","북쪽 숨은 동굴에서 광신도들이 움직이는 걸 봤대요.","그 동굴을 찾아 그들을 혼내 달래요."}},
[94978]={a={"Quel'ana Quickgale은 짐승과의 유대를 먼저 배우라고 해요.","물가 근처에서 조련용 막대로 Windsong Crawler를 찾으래요.","그 짐승의 신뢰를 얻은 뒤 막대를 돌려주래요."},c={"잘 길들였다며 벌써 익숙해졌다고 칭찬해요."},nx=94979,nt="Taming the Beast"},
[94979]={a={"Quel'ana Quickgale은 이제 넓은 들판에서 시험하래요.","그곳에는 날개 달린 사냥꾼 Galestrider가 있대요.","조련용 막대를 들고 가서 그 신뢰를 얻으래요."},c={"벌써 돌아왔다며 빠른 속도에 놀라워해요."},nx=94013,nt="Taming the Beast"},
[95006]={a={"Orokai가 희미하게 빛나는 나뭇가지와 교감했대요.","그 나뭇가지가 들려줄 이야기가 많대요.","그가 알아낸 것을 같이 보자고 해요."},nx=93773,nt="The Pact"},
[95026]={a={"Zet'gan은 전쟁을 피했다고 안전한 건 아니라고 해요.","동쪽의 괴물들이 오랫동안 이 지역을 괴롭혔대요.","그 괴물들을 쓰러뜨려 달라고 부탁해요."}},
[95033]={a={"Tan'jani는 평원이 지겨우면 옛 친구 의술사 우제리를 찾아가래요.","우제리는 마법을 다루지만 사냥꾼이기도 하대요.","페랄라스의 모자케 야영지에 가서 Tan'jani가 보냈다고 전해 달래요."}},
[95034]={a={"Lumina Windsinger는 길에서 습격한 건 gnoll이 아니었대요.","worgen이 호위병들을 해치고 Banon이 몸으로 막았대요.","그 뒤 벌어진 끔찍한 일을 들어 달래요."},nx=95036,nt="A Moon-Kissed Blade"},
[95036]={a={"Trevan이 worgen이 큰 위협이라고 했대요.","그중 Old Fire-Eye는 죽어도 되살아난대요.","Trevan Rol에게 무기 재료 목록을 받아 달래요."},c={"Trevan Rol은 재료를 다 모았다고 해요.","이제 칼을 만들 대장장이만 있으면 된대요.","그런 대장장이를 알 것 같다고 해요."},nx=95111,nt="An Underrated Talent"},
[95062]={a={"Friz Frazzlespark가 특별한 짐을 맡기려 해요.","늙은 Krom'rosh가 Rog'mar에서 기다리고 있대요.","빨리 가되 조심히 가져다 달래요."}},
[95063]={a={"Jezap은 당신이 링에서 실력을 보여 줬다고 해요.","Chub'chob을 엄청 화나게 해서 큰일이래요.","이제 Clugfist에게 가서 새 챔피언이 됐다고 알리래요."}},
[95107]={a={"Deadwood의 족장 Deeproar가 소굴 깊이 울부짖어요.","어느 밤 그들의 주문에 넘어가 포효가 저주받았대요.","그를 없애고 지팡이를 가져와 달래요."}},
[95108]={a={"Elder Pinespeaker는 Deadwood의 탕이 걱정이래요.","그 탕을 어린 것들에게 먹여 나쁜 싸움법을 가르친대요.","어두운 자들을 없애고 솥을 부숴 달래요."}},
[95111]={a={"Trevan Rol은 타렌 밀농장의 무기 대장장이 Ott를 추천해요.","Ott는 평범해 보이는 칼을 팔지만 품질이 뛰어나대요.","그에게 재료를 가져가 맞춤 무기를 의뢰해 달래요."},c={"Ott는 맞춤 주문을 받아 본 적이 없다며 놀라요.","명예를 바라지 않고 정직하게 소박한 무기를 만든대요.","언더시티에도 대장장이가 많은데 왜 자기를 찾냐고 묻대요."},nx=95125,nt="Ott's Masterwork"},
[95118]={a={"Whizzbuzz는 Murloc 얘기만 듣는다며 짜증을 내요.","뱃사람과 어부들이 다 그 얘기를 한대요.","그것들을 좀 처치해 달라고 부탁해요."},c={"Whizzbuzz가 해냈냐고 묻고 잘됐다고 해요.","곧 더 올 것 같지만 당분간은 조용하겠대요."}},
[95119]={a={"Whizzbuzz는 Eastsea 선원들 때문에 장사가 망해 간대요.","그들은 짐을 훔치고 배를 가라앉혀 손해가 크대요.","북쪽 해변의 그들을 먼저 무찔러 달래요."}},
[95120]={a={"현상수배!에 오른 Old Rot-Chum은 남쪽 바다의 Murloc이에요.","작은 배들이 위험하다고 어부들이 걱정해요.","처치한 증거를 Whizzbuzz에게 가져가래요."},c={"Whizzbuzz는 걱정 하나가 줄었다고 안도해요.","덕분에 빚을 졌다며 보상을 건네요."}},
[95121]={a={"Fimbo Greasemitz는 물가에서 가게를 하고 있어요.","메뉴가 늘 같아서 새 해물 스튜를 만들고 싶대요.","해변에서 재료를 좀 구해다 달래요."},c={"맛있는 재료네요, 보조 요리사님!","이제 해물 스튜를 곧 끓일 거예요."}},
[95122]={a={"Whizzbuzz는 해적이 Windstead를 불태웠대요.","그들이 내륙으로 더 번지기 전에 막아야 한대요.","북쪽의 해적들 수를 줄여 달래요."},c={"Whizzbuzz가 험한 일도 마다하지 않는다며 좋아해요.","덕분에 해적들을 완전히 물리칠 준비가 됐대요."}},
[95123]={a={"Whizzbuzz는 Eastsea 배들을 없앨 계획이 있대요.","그러려면 화약이 아주 많이 필요하대요.","북쪽 Winstead 근처에 있는 해적들의 화약을 구해 달래요."},c={"Whizzbuzz가 화약통이 크다며 놀라 휘파람을 불어요.","이걸로 해적들을 날려 버릴 날이 기다려진대요."}},
[95124]={a={"Whizzbuzz는 Admiral Lamora가 죽기를 바란대요.","Lamora가 모은 재물로 손해를 메우고 싶대요.","그 재물을 찾아 Whizzbuzz에게 가져다 달래요."},c={"Whizzbuzz가 당신을 진짜 실력자라고 칭찬해요.","필요한 게 있으면 언제든 찾아오래요."}},
[95125]={a={"Ott는 당신의 검을 벼려 준다고 해요.","좋은 재료라며 기뻐하고 칼을 만들 준비를 해요.","뒤로 물러나 지켜봐 달래요."},c={"내 최고의 작품이라 잘 쓰이길 바란대요.","기회를 줘서 고맙다고 전해요."},nx=95126,nt="The Moonsilver Blade"},
[95126]={a={"Ott는 완성한 칼을 건네며 고마워해요.","이 칼은 팔라딘 Trevan Rol의 것이래요.","은빛소나무 숲의 Trevan Rol에게 가져다 주래요."},nx=95140,nt="Old Fire-Eye"},
[95140]={a={"Lumina Windsinger는 새 무기가 실패하지 않길 빌어요.","Old Fire-Eye는 Gilneas 문 근처에서 자주 보인대요.","그를 찾아 새 무기로 쓰러뜨리고 돌아와 달래요."},c={"Lumina Windsinger는 Banon이 편히 쉬겠다고 해요.","칼에 자신의 마법을 조금 불어넣었대요.","그 칼이 잘 쓰이길 바람에게 빌겠대요."}},
[95141]={a={"사령관 아그로고쉬가 Riverglades를 소개해요.","스토나드 너머 싸움터에 Rog'mar 전초기지가 버티고 있대요.","전투를 원하면 Krom'rosh를 찾아가 달래요."},c={"아그로고쉬가 보냈다고요? 그 뜻은 존중해요.","인간들과 Twilight's Hammer를 모두 물리칠 거래요.","호드를 위해 싸울 일은 많대요."}},
[95143]={a={"Tor'gan은 자기 동생 Tan'jani를 찾고 있어요.","모단 호수 남쪽에서 동생을 봤다는 소식이 왔어요.","Riverglades의 Rog'mar에서 동생을 찾아 달래요."}},
[95144]={a={"여관주인 피즈그림블이 옛 친구에게 줄 짐이 있대요.","짐은 열면 안 되고 천천히 옮겨야 해요.","배를 타고 Friz Frazzlespark에게 전해 달래요."}},
[95162]={a={"Na'zok의 목장은 오거들에게 식량을 대는 아주 드문 곳이래요.","오거들이 Paletusk 구이를 좋아해서 고기 수요가 늘었대요.","Rog'mar에 고기를 보내려고 수확을 도와 달래요."}},
[95163]={a={"Na'zok의 돼지들이 골짜기 여기저기 흩어졌어요.","어린 돼지들이 강 건너로 도망쳤대요.","막대기로 쳐서 우리로 돌려보내 달래요."}},
[95165]={a={"Whizzbuzz는 화약으로 시한 폭탄을 만들 계획이래요.","Eastsea 배의 대포 근처 선체에 폭탄을 심는 거래요.","그 배들에 폭탄을 설치하고 몸을 피해 달래요."}},
[95181]={a={"Azka가 조용히 하라고 날카롭게 주의를 줘요.","언덕을 지날 땐 소리를 낮추고 조심하래요.","동쪽 초소의 Krom'rosh에게 보고서를 전하래요."}},
[95183]={a={"Gorgegut은 당신이 작아서 큰 무기는 못 쓴다고 해요.","Hamur는 작은 무기를 만들어 주는데 좋은 돌이 필요하대요.","Bolder'ok 밖 강가에서 좋은 돌을 가져다 달래요."},nx=96026,nt="Step Two: More Rock"},
[95204]={a={"낡은 문장 하나에 로데론의 표식이 새겨 있어요.","왕국이 무너진 뒤 남은 유물이 거의 없대요.","언더시티의 오란 스네이크레이드에게 전해 달래요."},c={"이런, 우리 고향의 진짜 유물이네요. 거의 온전해요.","조심히 다뤄야겠어요. 역사를 되찾아 줘서 고마워요.","잘 보관할게요."}},
[95216]={a={"시어도어 그리프스는 언더시티 약학 연구소에서 일해요.","폐허에 독이 강한 벌레가 돌아다닌대요.","그 벌레의 독을 샘플로 구해 달래요."},c={"벌레를 잡았다고요? 흠, 운이 좋네요.","이 독이면 성분을 알아낼 만큼은 되겠어요.","당장 눈앞에서 사라져요!"}},
[95248]={a={"Zet'gan은 언데드를 많이 물리쳐 줘서 고마워해요.","여기서 오래 버텼는데 드루이드들이 연락 한 번 없었대요.","정상의 드루이드들에게 아직 살아 있다고 전해 달래요."}},
[95254]={a={"Fimbo Greasemitz가 낚시꾼들을 찾고 있어요.","부두 밑에 큰 게가 돌아다니며 미끼를 훔친대요.","그 녀석의 집게를 가져다 주면 보상을 준대요."},c={"Fimbo Greasemitz가 집게를 보고 감탄했어요.","버터와 비밀 양념으로 맛있는 요리를 만들겠대요."}},
[95260]={a={"생선 내장과 오징어 먹물로 그려진 가죽이에요.","긴 목을 가진 바다 괴물이 파도 위로 솟은 그림이에요.","Powderfuse Port에서 이 괴물이 뭔지 알아봐 달래요."},c={"Argo Brinewhistle은 바다 괴물 얘기에 깜짝 놀라요.","그도 그 괴물을 본 적이 있냐고 되물어요."},nx=95261,nt="It Takes Guts"},
[95261]={a={"Argo Brinewhistle은 긴 목 괴물을 섬 근처에서 봤대요.","사람들이 그를 술 취한 어부라며 믿지 않았대요.","미끼로 쓸 내장과 버섯을 모아 달래요."},c={"Argo는 냄새가 역겨운지 입을 막아요.","수고했다며 빨리 치워 달래요."},nx=95267,nt="The Monster Surfaces"},
[95267]={a={"Argo는 이제 마지막 단계만 남았다고 해요.","물에 떠 있는 새 난파선 근처에 미끼를 던지래요.","괴물이 머리를 내밀면 잘라서 배 장식으로 쓴대요."}},
[95273]={a={"Fennar Mossmane은 물이 직접 더럽혀지진 않았대요.","그들의 굴 안에 산의 눈물이라는 웅덩이가 있대요.","Deadwood Den 깊은 곳 웅덩이에 정화 물약을 부어 달래요."}},
[95278]={a={"Da'grosh는 적이 생각보다 훨씬 위험하다고 해요.","Rog'mar에 이 사실을 꼭 알려야 한대요.","가는 길에 멈추지 말고 Krom'rosh에게 편지를 전해 달래요."},nx=94968,nt="Eye of Mugg"},
[95283]={a={"아이트리그는 코르크론 정예병과 연락이 끊겼대요.","그들은 먼지진흙 습지대에 간 뒤 소식이 없대요.","담쟁이 마을의 나지르 블러드파이크를 찾아가 보래요."}},
[95284]={a={"나지르 블러드파이크는 며칠 전 코르크론 병사들이 들렀대요.","병사 하나가 해안 근처 Alcaz 섬 얘기를 했대요.","친구들과 함께 병사들에게 무슨 일이 있었는지 알아봐 달래요."},nx=95285,nt="Right Place, Wrong Time"},
[95285]={a={"Sergeant Ulka가 몸을 일으키려 애써요.","도와주려는 손을 뿌리치고 신병에게 상황을 알려 줘요.","Alcaz Isle의 상황을 함께 알아봐 달래요."},nx=95309,nt="No Orc Left Behind"},
[95288]={a={"Friz Frazzlespark가 부하 될 사람을 시험하려 해요.","Eastsea 해적들이 Friz가 훔친 물건을 가로챘대요.","해적들에게서 힘으로 물건을 되찾아 오래요."},nx=95293,nt="Smuggler's Special"},
[95293]={a={"Captain Bentcoin이 Friz의 구역을 넘본대요.","그래서 무역 전쟁을 일으킬 기세래요.","Captain Bentcoin에게 이 상자를 전해 달래요."},nx=95294,nt="Smuggler's Bargain"},
[95294]={a={"Captain Haynes는 Friz와 거래를 맺고 싶어 해요.","Friz가 모험가들을 보내 해적 일이 힘들대요.","Friz에게 새 선장이 왔다고 전해 달래요."},nx=95296,nt="Shipping and Handling"},
[95295]={a={"Friz Frazzlespark는 무법항에 있는 연락책을 만나 보래요.","그 연락책은 그곳 해적들에게서 물건을 받는대요.","먼저 행상 러즈고트를 찾아가 달래요."},c={"Powderfuse Port에서 먼 길을 왔네요.","여기까지 혼자 왔으면 행상이 필요 없나 봐요?","누가 보냈어요, Friz인가요?"},nx=95322,nt="Get the Goods"},
[95296]={a={"Friz Frazzlespark가 다음 심부름을 맡기려 해요.","Friz는 마을에서 협상할 일이 있어 바쁘대요.","배를 타고 스팀휘들 항구에 짐을 전해 달래요."},c={"짐을 먼저 확인하지 않으면 들여보낼 수 없어요.","그는 헛기침하며 눈을 똑바로 마주 봐요."},nx=95383,nt="Shipping and Handling"},
[95309]={a={"Sergeant Ulka가 Alcaz 감옥의 지하를 살펴보라고 해요.","Commander Folkar를 찾아 살아 있다면 구해 달래요.","그곳엔 적의 군대가 있어 혼자선 버티기 힘들대요."}},
[95312]={a={"Tazzik은 Friz Frazzlespark의 돈을 모두 경기에 걸었대요.","가젯잔 경기장에서 크게 이겼다고 해요.","그 당첨금을 받아다 달래요."},c={"어서 와요, 친구! 악명 높은 가젯잔 경기장에 오셨나요?"},nx=95321,nt="Tazzik's Dues"},
[95314]={a={"캐롤라이 아니즈에게 엘릭서를 원하는 손님이 많대요.","Shadowvale 유적에 엘릭서 병이 남아 있대요.","Shadowvale에서 병을 모아 브릴로 돌아와 달래요."},c={"캐롤라이 아니즈는 Shadowvale에 악이 있다니 놀랍지 않대요.","숲 사람들은 방문객을 싫어했대요.","엘릭서를 가져와 줘서 고맙다며 보수를 건네요."}},
[95316]={a={"솔방울과 점액을 섞은 건 역겹지만 아주 위험하대요.","솔방울을 들고 흑마법사 야영지로 조심히 가래요.","그곳 작업대를 망가뜨려 적을 늦춰 달래요."}},
[95317]={a={"Curious Crow는 산 위에 시끄러운 자들이 왔대요.","그들은 악마 마법으로 재 더미를 실험하고 있대요.","그들 캠프를 뒤져 메모를 가져다 달래요."}},
[95318]={a={"Felflick은 감옥 같은 우리에 갇혀 있대요.","강한 흑마법사들을 쓰러뜨려야 우리를 열 수 있대요.","그 전에 흑마법사들을 많이 잡아 실력을 보이래요."},nx=95319,nt="Crystalline Collection"},
[95319]={a={"Felflick에게는 펠 기운을 빨아들이는 결정이 골칫거리예요.","그래도 쓸모가 있어서 여러 종류의 결정을 모아 달래요.","어떤 게 필요한지는 보면 안다며 골라 와 달래요."}},
[95320]={a={"Curious Crow는 악마 술사 캠프 근처에 갇힌 악마가 있다고 해요.","그 악마는 자유를 외치며 복수를 말하고 있대요.","열쇠로 그 악마와 거래해 보래요."}},
[95321]={a={"Fizbuz Mithril은 Tazzik이 보낸 사람이라니 어이없어해요.","Tazzik의 챔피언이 금방 져 버렸대요.","스팀휘들 항구로 가서 Tazzik을 만나 보래요."},nx=95472,nt="Consolation Prize"},
[95322]={a={"행상 러즈고트는 물건을 받으러 가려던 참이래요.","해적들이 무법항 밖 언덕 상자에 물건을 맡겼대요.","그 상자에 가서 물건이 있는지 확인해 달래요."},c={"투자개발회사요? 상자가 비어 있었대요?","그 사기꾼들이 제 돈을 훔쳤어요!","러즈고트와 한 약속을 어기면 가만 안 둬요."},nx=95325,nt="We've Been Robbed!"},
[95325]={a={"행상 러즈고트는 상자 값을 이미 치렀대요.","배신한 자를 찾아내야 한대요.","북쪽 투자개발회사 야영지에 가서 장부를 찾아 달래요."},c={"기름때 묻은 장부에 투자개발회사 거래 기록이 있어요."},nx=95326,nt="The Big Payback"},
[95326]={a={"투자개발회사 장부에는 러즈고트의 배송 기록이 있어요.","마지막 기록엔 요원이 물건을 챙겼다고 적혀 있어요.","그 요원을 처치하고 러즈고트의 물건을 되찾아 달래요."},nx=95327,nt="All's Well That Ends Well"},
[95327]={a={"행상 러즈고트와의 거래가 잘 마무리됐어요.","투자개발회사는 벌을 받고 Friz는 물건을 얻었어요.","이제 Friz Frazzlespark에게 돌아가 보래요."}},
[95328]={a={"꿈틀거리는 괴물의 잔해를 주워 두었어요.","언더시티에 쓸모가 있을지도 모른대요.","신부 랭커스터에게 전해 달래요."},c={"신부 랭커스터는 잔해가 흥미로운 표본이라고 해요.","그 숲은 공허에 닿아 있다고 해요.","그림자의 비밀을 탐구할 기회가 반갑다며 보수도 줘요."}},
[95349]={a={"교단 사건 때문에 Ayessa의 계획이 늦어졌대요.","나와 Windshaper 몇 명이 먼저 Azeroth로 가야 해요.","부두의 배를 타고 멀고어에 가서 Alaana를 만나래요."},c={"Alaana는 Zephras에서 온 모험가들을 반긴대요.","자리 잡으려면 시간이 걸리니 새 땅을 둘러보래요.","Azeroth는 신나지만 위험하니 주변 땅을 미리 익히래요."},nx=95350,nt="Welcome to Azeroth"},
[95350]={a={"Alaana는 Earthen Ring이 Horde의 일원이래요.","썬더 블러프의 비행 조련사가 오그리마까지 데려다준대요.","오그리마에서 Thrall을 만나 Windshaper의 뜻을 전하래요."},c={"Windshaper가 온다고 전령이 알려 줬대요.","오그리마에서 하이엘프를 보게 될 줄은 몰랐대요.","그래도 Horde 땅을 지나도 좋다고 허락해 줘요."},nx=93739,nt="Exploring the Horde"},
[95378]={a={"Felflick은 지도자들을 쓰러뜨려야 우리 마법이 풀린대요.","그들을 없애면 이곳 작업도 늦어진대요.","지도자들의 뼈를 가져와 달래요."}},
[95379]={a={"Felflick을 여기 가둔 건 Brashann Grimdark의 짓이래요.","그는 영혼을 결정에 가두는 실험에 몰두했대요.","그를 쓰러뜨리고 그의 영혼석을 가져다 달래요."}},
[95380]={a={"Curious Crow가 큰 곤경에 빠졌대요.","악마 술사들 짓인데 생각보다 훨씬 나쁜 상황이래요.","지옥 피 웅덩이의 점액을 모아 가져다 달래요."}},
[95383]={a={"Steamfizzle은 돈을 확인하고 Friz를 칭찬해요.","짐 얘기는 모르지만 Tazzik이 관심 있을 거래요.","부두의 Tazzik에게 빨리 짐을 전해 달래요."},c={"Friz는 역시 물건을 제대로 보내 주네요.","법을 어기며 돈을 쓰라고 한 적은 없어요.","Friz의 돈은 문제가 될 수도 있대요."},nx=95312,nt="Coming to Collect"},
[95384]={a={"마법 두루마리에 낯선 기호가 적혀 있어요.","그래도 위험한 기운은 느껴지지 않아요.","무법항의 Dudd Fizzlescroll에게 가져가 보래요."},c={"이상한 두루마리라고요? 최고급 마법이에요.","가져와 줘서 고마워요. 이건 보상이에요.","이제 해독해서 기록에 옮겨 적을게요."}},
[95385]={a={"희미한 마법이 흐르는 두루마리 조각이에요.","글자는 낯설지만 위험하지는 않은 듯해요.","무법항의 수집가에게 가져가 달래요."},c={"Dudd Fizzlescroll은 운이 좋은 날이라며 기뻐해요.","두루마리 글자를 자기 작업에 옮겨 적겠대요.","너무 가까이 오면 다칠 수 있다며 걱정해요."}},
[95417]={a={"Clubtoe는 친구들이 사라지는 걸 보고 있어요.","몇은 돌아오지 않고, 돌아온 친구는 보라색이 됐대요.","Sunnyglade 아래 동굴에서 사라진 친구들을 찾아 달래요."},nx=95601,nt="The Purple Ones"},
[95418]={a={"Clubtoe는 이제 Twilight과 인연을 끊었대요.","가장 큰 친구 Clugfist가 많은 친구들을 데리고 떠났대요.","Chogg'Zac의 머리를 Tran'gul에게 가져다 달래요."},nx=95420,nt="Land of Giants"},
[95420]={a={"Tran'gul은 떠돌던 친구들이 Twilight 편이 아니래요.","북쪽 언덕에 그들의 마을이 있을지도 모른대요.","그 머리를 우호의 표시로 가져다 달래요."}},
[95424]={a={"Clugfist는 약한 오우거는 Bolder'ok을 떠나야 한대요.","Twilight's Hammer로 가서 약한 오우거들을 쓰러뜨리래요.","그래야 Clugfist에게 힘을 보여 줄 수 있대요."}},
[95425]={a={"Clugfist의 최고 챔피언이었던 Klunk이 떠났대요.","Klunk이 Clugfist가 준 강한 무기를 들고 갔대요.","그 무기 Skullbasher를 되찾아 Klunk을 쓰러뜨리래요."}},
[95427]={a={"Clubtoe의 친구들이 죽었다고 해요.","Chogg'Zac이 오우거를 강하게 해 준다더니 거짓말이래요.","Chogg'Zac을 쓰러뜨려 머리를 가져와 달래요."},nx=95418,nt="Spread the Word"},
[95428]={a={"Clugfist는 Twilight's Hammer를 잘 무찔렀다고 인정해요.","Clugfist는 네가 생각보다 강하다고 여기게 됐대요.","당분간 Bolder'ok에 머물러도 된대요."},nx=94744,nt="The Wayward Warrior"},
[95431]={a={"Da'grosh는 적 안의 오우거들이 반란을 시작했대요.","그들도 Bolder'ok 동족처럼 자유를 찾으려 한대요.","Bolder'ok 전사를 찾아 동족을 모으는 걸 도와 달래요."},nx=95432,nt="Rise Up!"},
[95432]={a={"Crag'rog는 오우거들을 풀어 준 소식을 들었대요.","그들도 자유를 원해서 Twilight을 함께 무찌르자고 해요.","오우거 광부들을 모아 자유를 주래요."},nx=95433,nt="Death to the Executioner"},
[95433]={a={"Clugfist가 떠날 때 Morg라는 오우거가 막아섰대요.","Morg는 Clugfist 못지않게 덩치가 크대요.","작은 자들을 여럿 데려가 Morg를 처치하고 철퇴를 가져오래요."}},
[95454]={a={"코르크론 병사는 팔이 부러지고 정예병 대부분이 죽었대요.","Stormwind 국왕 바리안 린을 오그리마로 데려오라는 명령이래요.","Alcaz 감옥에서 바리안 린을 찾아 달래요."}},
[95483]={a={"이곳에서 무슨 일이 있었는지 Thrall이 알아야 한대요.","그는 Ulka를 만나 몸이 괜찮은지 본 뒤 돌아간대요.","바리안 린에게 생긴 일을 Thrall에게 전해 달래요."}},
[95494]={a={"브랑 와일드고어는 다리를 다쳐 직접 사냥을 못 해요.","그래도 지켜야 할 약속이 있어 가죽이 필요해요.","큰 사자부터 잡아 좋은 가죽을 구해 달래요."},c={"브랑 와일드고어는 이 가죽이면 충분하다며 좋아해요.","동네 가죽 장인과의 약속을 한 번도 어긴 적 없대요.","다쳤어도 약속을 어길 생각은 없대요."},nx=95495,nt="The Hermit Tanner"},
[95495]={a={"브랑 와일드고어는 가죽 묶음 배달을 부탁해요.","가죽은 능선 위에 혼자 사는 은둔자 장인에게 가야 해요.","가파른 길이라 대신 전해 달래요."},c={"Walton은 브랑이 보냈냐며 가죽을 받아요.","브랑 와일드고어가 직접 못 와서 아쉽대요.","그에게 따로 할 얘기가 있대요."},nx=95621,nt="Trouble in the Valley"},
[95507]={a={"브랑 와일드고어는 골짜기 곳곳에 덫을 놓았대요.","덫에 걸린 작은 짐승을 가져다 달래요.","다른 야생동물도 조심하래요."},c={"브랑은 다리 상처 탓에 굶을까 걱정했대요.","도와줘서 고맙대요."},nx=95495,nt="The Hermit Tanner"},
[95508]={a={"Walton은 예전에 쿨 티라스 해군에 있었대요.","Lord Admiral이 민간인을 처형하는 방식에 반대했대요.","Walton이 무사하도록 도와 달래요."},c={"Walton은 모두 무사해서 다행이라고 해요.","언젠가 과거가 따라잡을 줄 알았대요.","도와준 보답으로 이걸 받으라고 해요."}},
[95534]={a={"쪽지 주인은 곧 자리를 비울 예정이에요.","스트란브래드의 낡은 풀무가 사람이 안 볼 때 저절로 움직인대요.","풀무의 비밀을 캐서 힐스브래드 마을에서 알려 달래요."},c={"스트란브래드의 낡은 풀무에 불의 정령이 살았대요.","어떻게 들어왔는지가 진짜 수수께끼인 것 같대요."}},
[95568]={a={"Ketharas는 하이잘 산이 오래된 전쟁으로 상처 입었다고 해요.","하이잘 산이 살려면 자연이 다시 피어나야 한대요.","동쪽 들판의 작은 빨강·노랑 꽃에서 씨앗을 모아 달래요."}},
[95569]={a={"Ketharas는 펠 오염 때문에 올빼미들이 위험하다고 해요.","둥지를 버린 올빼미도 많고 새끼를 지키다 죽은 올빼미도 있대요.","버려진 알을 찾아 Ketharas에게 가져다 달래요."}},
[95599]={a={"녹이 두껍게 슨 열쇠 하나가 있어요.","오랫동안 물속에 잠겨 있었던 열쇠인 것 같아요.","이 열쇠가 맞는 상자를 페랄라스에서 찾아 달래요."}},
[95601]={a={"Clubtoe가 찾던 친구 같은 오우거가 쓰러져 있어요.","Twilight's Hammer가 동료에게 의식을 치르는 듯해요.","퍼지기 전에 막아 달래요."},nx=95427,nt="Twilight No More!"},
[95602]={a={"Clubtoe는 온종일 바위를 부수는 일을 한대요.","그들이 빛으로 그림을 그려서 Clubtoe는 빛이 싫대요.","빛나는 그림들을 부숴 달래요."},nx=95427,nt="Twilight No More!"},
[95611]={a={"Ketharas 덕분에 산의 야생동물이 잘 살게 됐대요.","남은 유해를 땅에 돌려주는 의식을 하려 해요.","서쪽 성소에 꾸러미를 묻고 돌아와 달래요."}},
[95621]={a={"Walton은 오늘 아침 골짜기에서 사람들을 봤대요.","그들은 쿨 티라스 문장을 단 병사들이래요.","그들이 왜 왔는지 알아봐 달래요."},c={"그들은 탈영병을 찾고 있었대요.","결국 과거가 나를 따라잡았다고 해요."},nx=95508,nt="Unwelcome Guests"},
[95663]={a={"저습지에서 Dragonmaw가 무언가를 준비한다는 소문이 있대요.","죽음의 추적자는 확실하지 않은 소문에 움직일 수 없대요.","야영지 위 언덕에서 죽음의 추적자 요원을 만나 달래요."},c={"용감한 사람들이 왔냐고 묻네요.","말을 조심하래요."},nx=95682,nt="Open the Maw"},
[95664]={a={"Titan Relic은 빛을 프리즘처럼 흩뜨리는 조각이에요.","정체는 알 수 없지만 아주 오래된 힘이 느껴진대요.","썬더 블러프 장로의 봉우리에서 답을 줄 이를 찾아 달래요."},c={"낯선 이가 이렇게 찾아오면 좋은 징조래요.","가까이서 힘이 느껴진다며 이게 뭐냐고 물어요."},nx=98823,nt="Earthen Echo"},
[95682]={a={"Dragonmaw 잔당이 힘을 되찾을 무언가를 찾았대요.","추적자들이 들키지 않게 이들을 몰아내야 한대요.","중요한 물건은 가져오고 이 일은 비밀로 해 달래요."},c={"오크 글씨라 바로 알아봤어요.","Rend를 달래려는 헛수고래요.","물건은 두고 갈 테니 임무 얘기는 하지 말래요."}},
[95697]={a={"보르스탄은 고향 맛을 넘어서는 요리를 원해요.","사냥꾼이 Thicket Raptor의 큰 발톱을 가져왔대요.","저습지에서 Thicket Raptor 고기를 구해다 달래요."},c={"마블링 좀 보라며 감탄해요.","먼 길을 다녀와 줘서 고맙대요.","기다리면 서비스로 요리해 준대요."}},
[95748]={a={"킨윌레이는 조각에 적힌 I'lalai 이야기가 이상하대요.","Vile Reef 북쪽 언덕 유적에 석판이 하나 있대요.","가죽과 숯으로 석판 탁본을 떠 와 달래요."},c={"이 탁본이 바로 필요했다며 좋아해요.","예전에 이 석판을 읽었지만 어릴 때라 기억이 흐릿하대요."}},
[95753]={a={"Odd Totem이 야생의 마법으로 맥동하고 있어요.","유령 늑대의 환영이 나타나 도전을 걸어와요.","제한 시간 안에 커다란 해골 너머 토템까지 가 달래요."}},
[95766]={a={"Fraxinus는 자연이 다시 살아나기 시작했다고 해요.","당신 덕분에 더 심각한 일도 바꿀 수 있을지 모른대요.","서쪽 땅에서 이상한 새를 찾아 달래요."}},
[95769]={a={"Kal'tinzan은 거친 생활로 옷과 담요가 닳았다고 해요.","바느질을 할 줄 아느냐고 물어요.","룬무늬 옷감을 가져다 구멍을 메워 달래요."}},
[95770]={a={"킨윌레이는 잃어버린 도시를 제대로 찾고 있대요.","예전에 본 동굴이 Vile Reef 근처에 있었던 것 같대요.","Vile Reef 서쪽을 살펴보고 소식을 전해 달래요."},c={"나가들이 이 동굴 유적을 오가는 걸 봤냐고 물어요.","I'lalai와 관련이 있을지도 모른대요.","전설이 현실이 될 수도 있대요."}},
[95773]={a={"사령관 아그로고쉬는 해안에 나가가 나타났다는 보고를 받았어요.","지금도 Bloodscalp와 오우거를 막느라 힘들대요.","바다에서 기습당하지 않게 나가를 많이 처치해 달래요."},c={"잘했어요. 호드에 실력을 증명하고 있네요.","삼지창을 Grom'gol 문밖에 꽂으면 경고가 될 거래요."}},
[95774]={a={"만크릭을 살렸던 치유사도 Olgra는 살리지 못했대요.","Olgra는 다듬은 뼈 보석 장신구를 많이 달았대요.","그녀가 쓰러진 곳 근처 적을 처치하고 장신구를 찾아 달래요."},c={"이 장신구를 Olgra의 추모비에 놓겠대요.","적을 쓰러뜨릴 때마다 그녀의 이름을 걸겠대요.","큰 영광이라며 고마워해요."}},
[95775]={a={"킨윌레이는 너무 늙어서 직접 갈 수 없대요.","나가가 지키는 폐허가 잃어버린 I'lalai 도시일지도 몰라요.","석판의 탁본을 떠 와 달래요."},c={"킨윌레이는 떨리는 손으로 탁본을 살펴봐요.","네 석판은 옛 도시 이야기를 담고 있대요.","석판 가장자리 뱀이 조수의 로아일지도 모른대요."}},
[95776]={a={"사령관 아그로고쉬는 나가가 떼로 바다에 있어 걱정이래요.","킨윌레이는 나가들이 Drowned 도시에 숨어들었다고 봐요.","나가 우두머리를 쓰러뜨리고 돌아와 달래요."}},
[95789]={a={"크라젝은 남작 레빌가즈를 위해 마법 물건을 찾고 있어요.","가라앉았던 트롤 유적에 Saltseer 해적이 몰렸대요.","해적을 치우고 훔친 유물을 되찾아 달래요."},c={"잘했어요! 남작 레빌가즈에게 바로 알려 줄게요.","약속대로 보상의 몫을 드릴게요."}},
[95791]={a={"크라젝은 Saltseer 해적 때문에 골머리를 앓고 있어요.","특히 Captain Dreadrise가 경쟁자라서 싫대요.","Captain Dreadrise와 그 부하들을 완전히 없애 달래요."},c={"정말 고마워요! 이제 발 뻗고 잘 수 있겠어요.","남작 레빌가즈도 고마워할 거래요."}},
[95792]={a={"Gelinda Coppergleam은 뒤 동굴에 캐지 않은 광맥이 있대요.","다만 그 동굴에 용들이 살고 있대요.","용들을 치워 주면 크게 보상하겠대요."}},
[95803]={a={"Danitha Morr는 타락한 지휘관을 처치했대요.","여군주 실바나스 윈드러너는 성기사들을 믿지 않는대요.","그 머리를 언더시티에 가져가 스스로 단속한다는 걸 보여 달래요."},c={"여군주 실바나스 윈드러너는 Danitha Morr의 진심은 믿는대요.","하지만 성기사가 또 광기에 빠져 동족을 해칠 수 있다고 봐요.","그러니 동족을 열심히 섬기라며, 계속 지켜보겠대요."}},
[95805]={a={"예언자 그레이텅이 An'she와 Mu'sha를 기리려고 해요.","태양과 달의 빛은 생명과 희망을 준대요.","타고 있는 향을 남동쪽 언덕의 사당에 가져다 달래요."},c={"향을 불에 붓자 향기가 퍼지고 빈 주머니만 남아요."}},
[95819]={a={"광고 허가 신청서예요.","직업 광고 간판을 세울 허가를 주는 서류래요.","듀로타 물자 계약 담당자에게 가져가 처리해 달래요."}},
[95882]={a={"Neza Bloodsnout는 Alliance 정찰대장을 쫓고 있어요.","그 정찰대장 때문에 적의 움직임을 쫓기가 어려워졌대요.","정찰대장의 다른 한쪽 눈을 증거로 가져다 달래요."}},
[95883]={a={"Offering Stone 위에 급히 차린 의식 준비물이 있어요.","쪽지에 따르면 피 제물과 Tortured Soul만 남았대요.","근처 언데드에게서 Tortured Soul을 얻어 달래요."},c={"Offering Stone 앞에서 영혼이 불길한 기운을 내요.","의식에 한 걸음 더 가까워졌대요."},nx=95885,nt="The Offering of Blood"},
[95884]={a={"낡은 쪽지 조각은 대부분 알아볼 수 없어요.","남은 글에는 제물과 의식, Offering Stone이 적혀 있어요.","베렌의 동굴에서 그 돌을 찾아 달래요."},c={"돌 표면에 이상한 도구와 물건이 흩어져 있어요.","쪽지에 나온 바로 그 돌이 틀림없대요."},nx=95883,nt="The Tortured Soul"},
[95885]={a={"이제 남은 건 피 제물뿐이래요.","쪽지에는 자발적인 제물이 필요하다고 적혀 있대요.","Tortured Soul로 Offering Stone에 피를 바쳐 달래요."},c={"Offering Stone은 이제 힘을 잃었어요.","갈라져 부서진 돌 속에서 무언가 반짝여요."}},
[95926]={a={"수석 연금술사 파라넬이 수정 소식을 들었대요.","그 수정이 원소나 생명력을 빨아들이는 것 같대요.","Shaper's Terrace의 무색 수정 조각을 가져다 달래요."}},
[95928]={a={"Mayena Earthseeker는 수정을 연구하고 있어요.","기본 수정은 있는데 더 강한 수정은 Shaper's Terrace에 있대요.","Shaper's Terrace에서 색깔별 수정을 가져다 달래요."}},
[95934]={a={"Gelinda Coppergleam은 새 광물 흔적을 찾았어요.","사람들이 믿으려면 실물 결정을 보여 줘야 한대요.","드래곤을 피해 결정을 구해 달래요."},c={"Gelinda Coppergleam이 결정을 보고 크게 기뻐해요.","광산 팀에 자리가 있으니 관심 있으면 들어오래요."}},
[95936]={a={"드래곤의 머리를 전리품으로 얻었어요.","Scaldaron의 위협은 사라졌고 Rog'mar 전사들도 알아야 한대요.","Rog'mar의 Krom'rosh에게 그 머리를 가져다 달래요."}},
[95951]={a={"Tan'jani가 창으로 찌르는 사냥법을 가르쳐 주겠대요.","먼저 서쪽 인간 야영지에서 나무를 가져오래요.","그 나무로 창을 만들어 가져오래요."},nx=95955,nt="Stick 'Em"},
[95955]={a={"이제 창을 던지는 법을 배울 차례래요.","Riverglades에는 사나운 Crocolisk가 많아요.","Crocolisk에게 창을 던져 보고 돌아와 달래요."}},
[95981]={a={"어둠의사제 알리스터는 목걸이 반입을 막으려 해요.","달라란에서 Kirin Tor가 유물을 보낸다고 의심해요.","앰버밀 근처 길에서 달라란 마법사와 감시자를 쫓아 달래요."},c={"달라란 장벽이 무너진 뒤로 Kirin Tor가 길을 꽉 쥐고 있대요.","무언가를 몹시 경계한대요.","지금은 이유가 중요하지 않대요."},nx=480,nt="The Weaver"},
[95982]={a={"Jasper Geartoggle은 맡겨진 동물들 때문에 골치 아파요.","사람들은 동물이 죽거나 달아나면 그를 탓한대요.","동물들을 진정시킬 음식을 만들어 달래요."},c={"개가 먹을 만한 걸 잘 만드네요.","도와줘서 고마워요, 친구."}},
[95992]={a={"Tan'jani의 사냥꾼들이 강길을 치우고 있지만 위험해요.","강에 괴물이 있는데 사냥꾼들도 잡지 못했대요.","강을 도는 흰 악어의 이빨을 가져다 달래요."}},
[96003]={a={"Elaena Moonwhisper는 그릇들이 합쳐져 강해졌대요.","그 힘을 시험해 볼 때가 왔다고 해요.","두 악마에게 그 수정을 써 보래요."},nx=96025,nt="As the Crow Flies"},
[96010]={a={"기둥이 망가져서 그 조각들이 흩어졌대요.","Shen'dralas에는 Magram과 Gelkis 세력이 들어와 있대요.","조각을 찾아 Mordent Evenshade에게 돌려 달래요."},nx=96018,nt="Powering the Pylons"},
[96018]={a={"Shen'dralas 곳곳에 마나 불씨가 떠다니기 시작했대요.","기둥이 망가진 탓에 생긴 마나를 다시 굳혀야 한대요.","사원의 마나 거르개를 빌려 떠다니는 구슬을 모아 달래요."},nx=93016,nt="A Brief History Lesson"},
[96025]={a={"Elaena Moonwhisper가 도움에 고마워하고 있어요.","그녀의 소중한 친구가 정상에서 기다리고 있대요.","동쪽 길을 따라 하이잘 산 정상으로 가 달래요."}},
[96026]={a={"Hamur는 좋은 돌을 가졌지만 마무리가 더 필요하대요.","돌은 돌로만 강해진다며, 작은 이들이 무거운 돌을 만든대요.","무거운 돌을 가져다 달래요."}},
[96060]={a={"Vindael은 살아생전 뛰어난 검사였대요.","이 검과 사이가 복잡해서 쓸모가 있을지 확신이 없대요.","검을 시험해 보고 숲의 야생동물도 좀 솎아 달래요."}},
[96063]={a={"Sleebo Fizzlespout은 가스로 가는 엔진을 만들고 싶어해요.","남서쪽 늪 가스는 모으기가 까다롭대요.","물가 틈에서 나오는 가스를 모아 달래요."},c={"이거면 아주 제격이래요.","그리고 부탁이 하나 더 있대요."},nx=96067,nt="Rock 'em and Sock 'em"},
[96067]={a={"G45-B4G는 가스 엔진의 유일한 작동 시제품이래요.","Sleebo Fizzlespout는 엔진을 시험해 볼 필요가 있대요.","모은 가스를 넣고 한판 겨뤄 달래요."},c={"둘이 정말 치열하게 싸웠네요! 볼만했대요.","좋은 의견도 얻었으니 엔진을 고칠 거래요.","시험하고 고치고 또 시험한대요."}},
[96076]={a={"Pix Xizzix의 고용주들이 고대 엘프 유물을 찾고 있어요.","마법 연구에 쓰려는 것 같대요.","혈투의 전장에서 물건들을 구해 무법항으로 가져다 달래요."}},
[96078]={a={"킨윌레이의 다크스피어 부족은 이야기로 전통을 이어요.","가장 지혜로운 장로 가드린이 진실을 듣고 싶어 한대요.","센진 마을에 이 석판을 가져다 달래요."}},
[96101]={a={"Raan Wildwind는 야생법을 알려 준대요.","야생에서 살아남아야 모험가로 성공한대요.","모닥불 옆에 편히 앉아 함께 배우자고 해요."}},
[96102]={a={"Brakk는 재봉술이 아주 쓸모 있다고 해요.","야영지에 쓸 사기 깃발을 만들 수 있대요.","그 기술을 가르쳐 줄 사람에게 가 보래요."},c={"Snang은 이제 Rallying Banner를 만들 수 있대요.","사람들은 마을 한복판 야영지를 별로 안 좋아한대요.","캠프에는 모닥불이 꼭 있어야 하니 요리를 배우래요."}},
[96103]={a={"이빨과 발톱 자국이 난 해골이 햇볕에 바랬어요.","희생자가 누군지는 알 수 없대요.","Neza Bloodsnout에게 두개골을 가져다 달래요."},nx=96104,nt="Song of the Strider"},
[96104]={a={"Neza Bloodsnout은 큰 사자 무리의 우두머리를 노려요.","사자를 꾈 호루라기를 만들어 줄 수 있대요.","들판 Tallstrider의 부리를 하나 구해 달래요."},nx=96105,nt="King of the Wild Plains"},
[96105]={a={"Neza Bloodsnout이 호루라기를 완성했대요.","남쪽 언덕에 사자들이 살고 있대요.","호루라기로 사자 우두머리를 불러 가죽을 가져다 달래요."}},
[96107]={a={"Neza Bloodsnout은 화살을 직접 만들고 자기 솜씨만 믿어요.","근처 대머리수리의 거친 깃털이 화살에 아주 좋대요.","그 깃털을 모아 달래요."},nx=96108,nt="Poison Tips"},
[96108]={a={"Neza Bloodsnout은 화살에 바를 독이 필요하대요.","남쪽 연못가 독사가 아주 강한 독을 가졌대요.","그 독을 조금 모아 와 달래요."},nx=96109,nt="A Hunter's Quiver"},
[96109]={a={"Neza Bloodsnout은 좋은 화살통을 만들고 싶어해요.","화살통에는 사자 가죽이 최고래요.","남쪽 언덕에 모인 사자들의 가죽을 가져다 달래요."}},
[96130]={a={"요 샤프메인은 사나운 늑대 Chakuyak 때문에 걱정이에요.","황소바위 호수 서쪽 숲에서 여행자들을 위협해요.","그 늑대를 처치하고 가죽을 가져다 달래요."},c={"요 샤프메인은 그 짐승을 잃어 슬프지만 어쩔 수 없대요.","가죽은 낭비하지 않고 잘 챙기겠대요."}},
[96131]={a={"Curious Crow가 남쪽 동굴에 사는 Oldstone을 찾아가 보래요.","하이잘 산에 보이지 않는 그림자가 드리운 것 같대요.","지팡이와 깃털을 그에게 전해 달래요."},nx=92612,nt="Aid from Moonglade"},
[96136]={a={"Alaana Stormwalker는 여기 원소가 특별하다고 해요.","바람 토템 대신 다른 스승을 만나 보라고 해요.","버섯구름 봉우리의 프레이트 클라우드시어를 찾아 달래요."},nx=79360,nt="Elemental Aid"},
[96145]={a={"Lisbael Highfeather는 Aviana를 따르는 사람이에요.","Wormwing 부족의 harpies가 성소 앞길을 차지했대요.","사촌 Phoebe Highfeather를 찾아가 달래요."}},
[96204]={a={"Lumina Windsinger는 이제 풀려나 자유의 몸이 됐대요.","자신을 가둔 무리에게 후회를 안겨 주겠대요.","펜리스 요새를 함께 빠져나가자고 해요."},nx=95034,nt="The Debt"},
[96209]={a={"마을 바로 밖에 Orokai라는 고대 존재가 지키고 있대요.","가지가 나무에서 떨어진 지 오래되지 않았다면 이야기를 들을 수 있대요.","마을 남서쪽 가까이에 있으니 그에게 가져다 달래요."},nx=95006,nt="Stolen Power"},
[96222]={a={"Umarak는 Maraudine centaur가 걱정이래요.","다른 부족들이 모른 척하면 더 거칠어진대요.","칸 흐라사의 마라우돈 열쇠 파편을 가져다 달래요."}},
[96241]={a={"Gloomrise에 새로운 괴물이 돌아다니고 있대요.","그 괴물의 독에 특별한 성질이 있다고 해요.","Toxin Extractor로 시체에서 독을 뽑아 달래요."},c={"특별한 성질이 있다는 말은 농담이 아니었어요.","그래도 몸은 멀쩡해 보여서 다행이에요.","도와줘서 고마워요, 모험가."}},
[96252]={a={"Phoebe Highfeather는 자매들을 잃었대요.","Wormwing이 보석을 새끼 있는 둥지에 숨겼대요.","가능하면 알을 깨지 말고 보석을 되찾아 달래요."}},
[96255]={a={"Bone Pile 안에서 무언가 꿈틀거리고 있어요.","새로 쌓인 뼈 사이로 초록 점액이 새어 나와요.","깨어난 펠 잿더미 슬라임을 처치해야 해요."},nx=96322,nt="A Revenge Now Bitter"},
[96258]={a={"드워프가 직접 사인한 책을 건네줬어요.","Mazu'kon과의 지난 일을 아직 못 잊었대요.","Mazu'kon에게 가만두지 않겠다고 전해 달래요."}},
[96259]={a={"Muln Earthfury는 Gloomrise의 옛 묘지가 걱정돼요.","거미 떼가 들끓어 신성한 곳이 망가지고 있대요.","Gloomrise에 가서 거미들을 없애 달래요."},c={"이 땅 사람들을 위해 애써 줘서 고마워요.","완전히 없애기까지 시간이 걸리지만 든든한 발판이 생겼어요."},nx=96261,nt="The Broodmother"},
[96260]={a={"Yorn Grimtotem은 단단한 결정 같은 거미 실을 연구해요.","정찰병 하나가 그 실에 뒤덮여 돌아왔대요.","그 실을 더 가져오면 보상을 주겠대요."},c={"이 실이면 충분하대요. 정말 좋은 샘플이에요.","이미 가진 실로 짠 특별한 망토를 줘요.","여정에 도움이 되길 바란대요."}},
[96261]={a={"거미가 빨리 퍼지는 건 우두머리 어미 한 마리 때문이래요.","이 거미들은 평범한 거미가 아니래요.","Gloomrise의 어미를 동료와 함께 처치해 달래요."}},
[96262]={a={"Curious Crow가 솔방울이 여러모로 쓸모 있다고 해요.","자기 계획에 쓸 솔방울이 필요하대요.","오염된 나무 말고 건강한 나무 밑의 솔방울만 주워 달래요."}},
[96294]={a={"쓰러뜨린 거미 어미는 사실 night elf druid였대요.","옷자락 사이에 쪽지가 끼어 있었어요.","그 편지를 Muln Earthfury에게 가져다 달래요."},c={"정말 끔찍한 내용이에요. 왜 druid가 거미를 부렸을까요?","편지의 'Wild King'과 'Pact'가 무엇인지 모르겠대요.","Cenarion Circle에 물어보겠대요."}},
[96296]={a={"Corrupted Growth 혹이 나무에서 떨어져 진액이 흘러요.","부패가 나무 속 깊이 퍼졌지만 나무는 아직 살아 있어요.","부패한 혹을 최대한 많이 떼어 달래요."}},
[96301]={a={"키메라 Ghansurok의 독성 심장을 들고 준비하래요.","Well of Eternity 물에 담가 부패에 어떻게 반응하는지 보래요.","심장을 다시 가져가 함께 신호를 읽자고 해요."}},
[96302]={a={"Marn Euhorn이 진한 수지를 뭉쳐 향을 만들었대요.","그 연기가 마음을 달래 두려움을 막아 준대요.","쓰러진 The Defiler 앞에서 향을 피우고 주문을 외워 달래요."}},
[96303]={a={"Thisalee Crow가 혼령들의 사연을 들려줘요.","하이잘 산의 큰 전투 때 부름받은 혼령들이 남았대요.","마법 나뭇가지로 이 혼령들을 편히 보내 달래요."}},
[96321]={a={"죽어 가는 Velician은 시간이 별로 없대요.","이 지팡이는 세계수의 가지인데 오염됐대요.","Wild Gods에게 알리려고 지팡이를 전해 달래요."},nx=96131,nt="An Oldstone But An Old Friend"},
[96322]={a={"Felflick이 약속대로 자유를 달라고 해요.","Ashen Reign의 지도자들을 쓰러뜨리는 걸 도왔대요.","이제 자유를 얻을 자격이 있대요."}},
[96332]={a={"Sergeant Ulka는 Naga 무리가 요새로 몰려왔대요.","많은 전사들을 잃어서 마음이 편치 않대요.","요새 안 Naga 마법사의 머리를 가져다 달래요."}},
[96334]={a={"Sergeant Ulka는 싸운 인간들이 붉은 두건을 둘렀대요.","Defias Brotherhood라는 범죄 조직의 붉은 가면과 닮았대요.","마주친 자들을 처치해 오그리마의 아이트리그에게 가면을 가져다 달래요."}},
[96335]={a={"그 사람이 용을 쓰러뜨린 걸 보고 감탄했대요.","The Questioner라는 고문관이 족쇄 열쇠를 가졌을 거래요.","그 열쇠를 받아 와서 자기에게 가져다 달래요."}},
[96337]={a={"금은 없지만 더 값진 걸 준대요.","보물을 찾는 데 쓸 쪽지를 주는 거래요.","누가 묻거든 준 사람이 용의 불에 죽었다고 하래요."}},
[96369]={a={"왕이 죽었다는 소식을 알게 됐어요.","나가가 공격하기 직전 탈출하다 죽었대요.","이 소식을 Commander Folkar에게 알려 달래요."}},
[96376]={a={"서부 몰락지대에서 얻은 문서들이 있어요.","나즈그렐은 Warchief의 고문이래요.","문서 중 뜻이 통하는 게 있는지 물어봐 달래요."}},
[96379]={a={"서부 몰락지대에서 얻은 문서들이 있어요.","Rix Xizzix는 물건을 되찾는 goblin이래요.","문서가 무슨 뜻인지, 얼마를 쳐줄지 물어봐 달래요."}},
[96435]={a={"Felflick이 Ashen Reign 지도자들의 뼈를 보고 좋아해요.","그 뼈를 실패한 실험체가 쌓인 서쪽 뼈 더미에 버리래요.","모두에게 그들이 실패작이었다고 알려 달래요."},nx=96255,nt="Amalgamated Marrow"},
[96550]={a={"오래된 칼집에 조각 무늬가 새겨져 있어요.","참전 용사가 말한 것과 같다고 해요.","칼집을 들고 용사의 말을 떠올려 보래요."}},
[96558]={a={"참전 용사가 무너진 망루 밑에 보관함을 묻어 뒀대요.","하이잘 산에서 가져온 것들이 그 안에 남아 있대요.","그걸 가져가라며 고마워하고, 이제 편히 쉬겠대요."}},
[96561]={a={"Tobin이 Rowdy Redridge Rebels에게 보낸 편지예요.","전쟁이 끝나면 낚시 대결을 하자고 적혀 있어요.","Cradle of Tranquility의 연못을 찾아 달래요."}},
[96604]={a={"Brakk는 야생법을 알려 준대요.","야생에서 살아남아야 모험가로 성공한대요.","모닥불 옆에 편히 앉아 함께 배우자고 해요."},c={"Brakk는 기본을 마쳤다고 해요.","이제 마을 훈련사에게 직업 기술을 배우래요.","그 훈련사가 캠프 설비 만드는 법도 가르쳐 준대요."}},
[96605]={a={"Kaga Wildhoof는 야생법을 알려 준대요.","야생에서 살아남아야 모험가로 성공한대요.","모닥불 옆에 편히 앉아 함께 배우자고 해요."}},
[96607]={a={"Eleanor Shackleton은 야생법을 알려 준대요.","야생에서 살아남아야 모험가로 성공한대요.","모닥불 옆에 편히 앉아 함께 배우자고 해요."}},
[96616]={a={"Ortak Lomgok이 하이잘 산에 온 여행자에 놀라워해요.","동쪽 언데드 잔당의 습격으로 감염자가 많대요.","북쪽 계곡의 파란 꽃 약초를 캐 와 달래요."}},
[96622]={a={"Ortak Lomgok이 마지막 부탁을 하나 더 해요.","Enho는 많이 약해졌지만 회복하길 바란대요.","찜질약을 Enho와 Maruke에게 전해 달래요."}},
[96638]={a={"Aetheen of the Gales는 모험가가 늘었대요.","Shen'dar Village 근처에 야영하는 모험가가 있대요.","그 사람을 찾아가 배울 게 있는지 보래요."},nx=96101,nt="The Great Outdoors"},
[96646]={a={"Raan Wildwind는 캠핑을 더 알고 싶은지 물어요.","요리는 맛있는 음식만 만드는 게 아니라 캠프의 기초래요.","그러니 요리를 배워 보라고 권해요."},c={"Zerril Softbreeze는 이제 어디서든 야영지를 차릴 수 있대요.","기초라서 가구는 많이 놓지 못한대요.","요리 실력을 올리면 더 큰 모닥불도 피울 수 있대요."}},
[96652]={a={"잃어버린 일지 한 권이 있어요.","일지에는 캠핑 이야기가 많이 적혀 있대요.","칼바위 언덕의 Brakk에게 가져다 달래요."},c={"Brakk는 오래 잃어버렸던 일지를 찾아 고마워해요.","모험가 같다며 캠핑을 배워 보지 않겠냐고 권해요."},nx=96604,nt="The Great Outdoors"},
[96655]={a={"Brakk는 캠핑을 더 알고 싶냐고 물어요.","요리는 맛있는 음식만 만드는 게 아니라 캠프의 기초래요.","칼바위 언덕에서 요리사 토르카에게 배워 보래요."},c={"요리사 토르카는 이제 들판에 야영지를 차릴 수 있대요.","기초라서 가구는 많이 놓지 못한대요.","요리 실력을 올리면 더 큰 모닥불도 피울 수 있대요."}},
[96656]={a={"집행관 아렌은 Scarlet Crusade와 싸운 당신을 믿는대요.","브릴 근처에 새로 온 모험가가 있대요.","그 모험가가 무얼 하는지 가서 보래요."},c={"Eleanor Shackleton은 소속이 아니래요.","다음 모험 전에 잠깐 들른 모험가일 뿐이래요.","그리고 캠핑을 배워 보겠냐고 권해요."},nx=96607,nt="The Great Outdoors"},
[96658]={a={"Eleanor Shackleton은 캠핑을 더 알고 싶은지 물어요.","요리는 캠프의 기초라서 먼저 배워야 한대요.","브릴에서 요리를 가르치는 사람을 찾아가래요."},c={"패트릭은 이제 어디서든 야영지를 차릴 수 있대요.","기초라서 가구는 많이 놓지 못한대요.","요리 실력을 올리면 더 큰 모닥불도 피울 수 있대요."}},
[96659]={a={"족장 호크윈드는 Kaga Wildhoof에게 신세를 졌대요.","블러드후프 마을 근처에 야영지를 차렸대요.","은혜를 갚고 싶어 보급품을 전해 달래요."},c={"Kaga Wildhoof는 족장이 보냈냐며 놀라요.","보상은 필요 없다고 했는데 족장이 듣지 않았대요.","캠핑을 배워 보지 않겠냐고 권해요."},nx=96605,nt="The Great Outdoors"},
[96661]={a={"Kaga Wildhoof는 캠핑을 더 알고 싶은지 물어요.","요리는 캠프의 기초라서 먼저 배워야 한대요.","블러드후프 마을에서 요리를 배워 보래요."},c={"피알 사일런트스트라이드는 이제 야영지를 차릴 수 있대요.","기초라서 가구는 많이 놓지 못한대요.","요리 실력을 올리면 더 큰 모닥불도 피울 수 있대요."}},
[96774]={a={"구루바시는 옛날 어두운 피 마법의 대가였대요.","Mazu'kon은 truesilver 우상을 연구용으로 원해요.","Drowned 도시에서 가장 인상적인 사제를 처치해 달래요."}},
[96775]={a={"Mazu'kon이 의술사 줌라에게 원한이 있대요.","줌라는 타나리스의 줄파락에서 나쁜 주술을 부린대요.","그를 쓰러뜨려 머리를 가져다 달래요."}},
[96776]={a={"Olana Brighthoof가 환영을 봤대요.","마라우돈 깊숙이 거인이 지키는 수정 방이 있대요.","그 수정을 멀고어의 탁 트인 하늘 아래로 가져다 달래요."}},
[96779]={a={"미로코스 사일런트폼이 Syndicate의 핵심 인물을 지목해요.","Lord Tomas가 던홀드 요새 운영에 큰 역할을 한대요.","던홀드 요새에서 그를 빠르고 조용히 처치해 달래요."},c={"미로코스 사일런트폼은 요새가 크게 흔들릴 거래요.","우두머리 없는 부하들은 쉽게 흐트러진대요.","잘했다며 다음 임무도 맡길지 모른대요."}},
[96781]={a={"미로코스 사일런트폼이 Syndicate 정찰대를 알아챘대요.","Barton이 이끄는 정찰대가 무엇을 찾는지 알고 싶대요.","Barton을 죽이지 말고 주머니에서 보고서를 빼 달래요."},nx=96782,nt="Covert Extraction"},
[96783]={a={"스트롬가드 요새는 Syndicate의 큰 거점이래요.","아라시 고원의 거래 내용이 요새 안에 있을 거래요.","북부습곡 장원에서 Syndicate 제복을 훔쳐 달래요."},nx=96784,nt="Master of Disguise"},
[96784]={a={"스트롬가드 요새에서 큰 거래가 있다는 지시가 있었어요.","변장을 하면 Syndicate 사람들과 편하게 이야기할 수 있대요.","그중 비밀 거래를 아는 사람을 찾아 달래요."},c={"Anastasia Miller가 눈을 가늘게 뜨고 의심해요.","그 거래를 어떻게 알고 있냐고 캐물어요."},nx=96785,nt="Ain't No Telling"},
[96785]={a={"Anastasia Miller가 함부로 끼어들지 말라고 쏘아붙여요.","윗사람들의 일은 대가 없이 말해 줄 수 없대요.","스트롬가드 요새에서 값진 걸 찾아와 달래요."},c={"Anastasia Miller가 물건을 보고 놀라 어디서 찾았냐고 해요.","결국 거래 이야기를 해 주겠대요.","그 물건을 돌려주면 이번 일은 없던 걸로 하자고 해요."},nx=96786,nt="The Syndicate Sting"},
[96786]={a={"Anastasia Miller가 비밀 거래 장소를 알려 줘요.","Falconcrest 사람들이 성벽 남쪽에서 만난대요.","그 거래를 깨고 물건을 Syndicate에 가져다 달래요."}},
[96796]={a={"Ketharas가 수리공 Kaylaena에게 쓸모 있을 물건을 찾았대요.","Kaylaena는 스승 Yaely를 잃은 뒤 발길이 뜸하대요.","북쪽 언덕 작업장의 Kaylaena에게 가져가 달래요."}},
[96821]={a={"벨린 팡은 칼바위 언덕에서 오가는 여행자가 줄었대요.","길가에 거미들이 둥지를 틀었다고 들었대요.","거미를 처치하고 칼바위 언덕에 알려 달래요."},c={"가르톡은 일꾼들이 남쪽 길을 오래 무서워했대요.","이제 길이 뚫렸으니 일꾼들을 다시 일하게 할 수 있대요."}},
[96822]={a={"Turroc는 타이라가드 요새를 칠 때 전사를 많이 잃었대요.","인간들이 폐허를 막아서 유해를 거둘 수 없대요.","폐허 주변에서 전사들의 무기를 찾아 달래요."}},
[96825]={a={"요리사 토르카는 달콤한 간식을 맛보고 싶대요.","서쪽 언덕 선인장에 가시 달린 열매가 열린대요.","quilboars 사이를 지나 열매를 가져다 달래요."},c={"요리사 토르카는 이 열매로 맛있는 걸 만든대요.","씨앗은 따로 챙겨 심을 거래요.","언젠가 오그리마 곳곳에 선인장이 자라면 좋겠대요."}},
[96830]={a={"Thark Gorax는 높은 데서 떨어진 사람을 봤대요.","Thark는 그 사람을 그늘로 옮겨 편히 보내 줬대요.","하이잘 산 북서쪽에서 Horde를 찾아 달래요."}},
[96873]={a={"동쪽 트롤들은 잘라제인 주술사에게 휘둘리고 있대요.","잘라제인은 속박 주문이 감긴 목걸이를 씌운대요.","그 목걸이의 마법을 벗겨 가져다 달래요."},c={"Pa'zula는 잘했다고 칭찬해요.","죽은 트롤들은 안타깝지만 이제 영혼이 쉴 수 있대요."}},
[96874]={a={"오그톡은 짐승의 등 가시로 큰 도끼를 만들고 싶대요.","Saru는 그 말을 듣고 웃었대요.","대장일 수업 삼아 가시와 숫돌을 가져다 달래요."},c={"오그톡은 가시가 생각보다 훨씬 단단하대요.","가공하기가 쉽지 않지만 계속 연구하겠대요."}},
[96875]={a={"카마리는 오그리마가 계속 커져서 가죽이 필요하대요.","천둥 골짜기 도마뱀 가죽은 건물 재료로 좋대요.","두꺼운 가죽과 손질한 가벼운 가죽을 가져다 달래요."},c={"카마리는 당신의 일이 오그리마를 키운다고 해요.","도시 길을 걸을 때 이 일을 떠올려 보래요."}},
[96895]={a={"죽음의경비병 테렌스는 은빛 여명회 사절이 둘 왔대요.","사절 한 명이 남동쪽으로 갔고 그쪽에 광신도들이 있대요.","언더시티 입구 근처에서 그 사절을 찾아 달래요."},c={"Hadric Harlson은 몸을 낮추고 들키지 말래요.","그 광신도들은 얕보면 안 된대요."}},
[96896]={a={"존경받는 리어니드 바돌로매는 언더시티를 지켰대요.","그때 많은 친구를 잃었고 영웅 Garek Bandarion도 있대요.","Danitha Morr와 나누는 대화를 지켜봐 달래요."},c={"존경받는 리어니드 바돌로매는 한동안 여기 머문대요.","곧 동부 역병지대 희망의 빛 예배당으로 돌아간대요.","그쪽에 가면 인사해 달래요."},nx=98545,nt="Leonid's Letter"},
[96897]={a={"Hadric Harlson은 Scourge의 산 부하들이 제일 나쁘대요.","숲 사람들은 언데드와 Scarlet Crusade에 시달려요.","그 무리를 없애는 데 도와 달래요."},c={"Hadric Harlson은 도와줘서 고맙대요.","Lordaeron 역사가 되풀이되지 않게 경계하래요."}},
[96898]={a={"Hadric Harlson은 낙스라마스가 도시를 덮쳤대요.","낙스라마스 꼭대기 수정이 깨져 이 일대에 흩어졌대요.","그 조각을 모아 Scourge가 못 쓰게 해 달래요."},c={"Hadric Harlson은 Scourge가 느려질 거라고 해요.","주민들이 앞으로도 수정을 캘 거래요.","그래도 눈에 띄는 조각을 치우는 건 도움이 된대요."}},
[96899]={a={"Hadric Harlson은 당신이 큰일을 했다고 해요.","Bandarion Keep의 기사들을 만나러 가던 길이었대요.","북서쪽 성채의 지휘관을 찾아가 보래요."},c={"존경받는 리어니드 바돌로매는 추억이 많대요.","떠날 때 황폐해질까 걱정했는데 맞았대요.","다행히 Danitha가 맡아서 친구의 이름을 따 불렀대요."},nx=96896,nt="A Righteous Cause"},
[96930]={a={"Ketharas는 Ve'han의 힘을 막을 강한 마법이 필요하대요.","드루이드의 힘이 예전만 못해 신령들의 도움이 필요하대요.","산 위의 Curious Crow를 다시 찾아가 도움을 청해 달래요."},nx=96931,nt="Heading Up the Mountain"},
[96931]={a={"Curious Crow가 자기보다 현명한 Jereman을 소개해요.","Jereman은 옛 돌의 마법에 필요한 걸 안대요.","그 다리의 까마귀 조각을 만져 불러 달래요."}},
[96939]={a={"Jereman의 친구가 새로운 힘의 원천을 알 수도 있대요.","그 친구는 남쪽 언데드가 많은 Mourning's Rest에 있대요.","Jereman이 보냈다고 꼭 말해 달래요."},nx=92317,nt="Stolen Life"},
[96957]={a={"Marrosis의 생명들은 흙에 양분을 돌려줘요.","언데드가 그 순환을 깨서 쉴 곳을 잃었대요.","둥지를 다시 지을 뼈를 모아 달래요."}},
[96959]={a={"Yashiro는 싸움이 끝난 뒤에야 도착했대요.","악마들이 무덤을 더럽혔고, 함께 싸우기 전 실력을 보겠대요.","Dae'gun의 모닥불들을 밝히고 돌아와 달래요."},nx=96983,nt="Yashiro's Windwalk"},
[96964]={a={"Jereman이 은둔자의 계획에 강한 힘이 필요하대요.","북쪽 Dae'gun에 있는 여우 신 Renalard가 답을 알 것 같대요.","그 여우를 찾아가 해결책을 물어봐 달래요."},nx=92335,nt="Ashes of the Legion Ascent"},
[96971]={a={"Renalard의 새끼들이 쓸 물자가 필요하대요.","전쟁이 끝난 뒤 군대가 버린 물자가 악마 근처에 있대요.","털뭉치로 악마를 따돌리고 물자를 챙겨 달래요."}},
[96978]={a={"Jereman이 Kala'th가 자연의 질서를 해친다고 해요.","그 사슴은 자기와 무리를 포식자로 여긴대요.","Kala'th를 찾아가 제정신으로 돌아오게 해 달래요."}},
[96979]={a={"Galvinquam Leafsyre는 세계수를 모시는 드루이드예요.","산비탈엔 날개 달린 사냥꾼들이 있어 옛 유적에 머물러요.","폭포에서 물을 떠다 제 호리병을 채워 달래요."},nx=96991,nt="Trail Assist"},
[96982]={a={"할브 클로후프가 첫 탈것을 고르라고 해요.","kodo는 느리게 화내는 믿음직한 동료래요.","kodo들을 살펴보고 마음에 드는 걸 고르래요."}},
[96983]={a={"Yashiro가 당신은 실력도 빠르고 두렵지 않다고 해요.","불이 악마들을 끌어내면 우두머리들도 올 거래요.","Yashiro와 함께 Dae'gun의 악마들을 베며 나아가 달래요."}},
[96984]={a={"Image of Archmage Modera는 달라란이 위험하다고 해요.","달라란이 무너지면 언더시티도 함께 무너진대요.","열쇠로 달라란에 들어가 Violet Citadel에서 만나래요."},nx=97287,nt="Shrewd Negotiations"},
[96986]={a={"멜리사라는 달라란 지하에 배신자가 있대요.","그 배신자가 언데드 군대를 몰래 키운대요.","Atrexis the Grave Knight를 없애 달래요."},c={"잘했다며 멜리사라가 칭찬해 줘요.","그 괴물은 죽은 자들 사이에 설 자격도 없대요."}},
[96987]={a={"어떤 장사꾼이 달라란에서 기회를 찾고 있대요.","마법사들이 바쁜 틈에 귀한 물건을 챙기자고 해요.","비밀 서적 한 권을 가져오면 이익을 나눠 준대요."},c={"이 책은 관광 가게에서도 값이 얼마 안 된대요.","아무 책이나 집어 왔냐며 투덜거려요."}},
[96988]={a={"박사 마틴 펠벤은 달라란이 구조물에 포위됐다고 해요.","그 틈에 샘플을 빌려 오고 싶대요.","구조물의 핵을 달라란에서 구해 달래요."},c={"핵이 다 깨져서 쓸 수 없대요.","경계 구조물은 끄라고 했지 부수라고 안 했대요."}},
[96989]={a={"졸니르가 첫 탈것을 고를 날이라고 해요.","랩터도 사람을 골라야 해서 서로 선택한대요.","길들인 랩터들을 보고 와 달래요."}},
[96991]={a={"Galvinquam Leafsyre는 산길이 힘들어 지쳤대요.","나중에 Marn Euhron이 Nordrassil 근처 거점을 세운대요.","여분 짐을 Summit의 Marn Euhron에게 가져다 달래요."}},
[96994]={a={"오구나로 울프러너가 늑대와의 인연을 얘기해요.","늑대는 평생 함께할 친구라서 서로 고른대요.","어떤 늑대가 맞는지 찾아서 돌아와 달래요."}},
[96996]={a={"Genn Fairweather가 훈련을 마쳤으니 첫 탈것을 고르래요.","galestrider는 조상 대대로 타 온 든든한 탈것이래요.","가서 살펴보고 하나를 고른 뒤 돌아와 달래요."}},
[96997]={a={"자카리아 포스트는 언데드 말 마구간을 운영해요.","언데드 말과 좋든 나쁘든 함께 여행하게 된대요.","언데드 말들을 살펴보고 첫 탈것을 골라 와 달래요."}},
[96998]={a={"트롤 해골이 쥐고 있던 가죽 천을 찾았대요.","천에 Darkspear 색의 얼굴 물감 자국이 있대요.","그 글씨를 알아볼 누군가에게 가져다 달래요."},nx=96999,nt="Wrap Return"},
[96999]={a={"Zet'gan은 그걸 쓴 사람이 뜻을 품고 싸웠대요.","센진 마을에는 그 사람을 그리워할 가족이 있대요.","메아리 섬을 지나 센진 마을로 가져가 달래요."}},
[97000]={a={"아비게일 소우어는 아버지 Lawrence Sawyer를 찾고 있어요.","아버지는 전쟁 때 하이잘 산에 남아 무기를 만들었대요.","무너진 야영지에서 아버지의 흔적을 찾아 달래요."}},
[97001]={a={"오래된 옷장에서 Sawyer 가문의 장부가 나왔대요.","장부에 아비게일 소우어의 친척 이름도 적혀 있대요.","언더시티 War Quarter의 아비게일에게 가져다 달래요."}},
[97003]={a={"Gur'ak은 가시덩굴 언덕 동굴에 괴물이 산다고 해요.","다들 안 믿어도 그는 비슷한 놈과 싸워 봤대요.","Chol'aruk의 머리를 가져와 달래요."},c={"이 증거로 오그리마에서 아무도 의심 못 하겠대요.","공을 널리 알려 준대요."}},
[97006]={a={"아비게일 소우어가 쪽지와 서명을 덧붙였대요.","장부를 어디서 찾았는지 설명해 달래요.","언더시티 Census의 왕실감독원 바우하우스에게 가져가 달래요."}},
[97007]={a={"바우하우스가 장부의 해당 쪽에 도장을 찍었대요.","재산을 Forsaken 땅으로 옮기려면 먼저 알려야 한대요.","장부를 돌려주고 아직 기다려야 한다고 전해 달래요."}},
[97009]={a={"Maerion Thaelemaches는 버려져 저주를 받았대요.","이제 전쟁이 다시 시작되니 분노로 싸우겠대요.","Defiling Hounds 가시를 가져와 분노를 증명해 달래요."},nx=97010,nt="Blind Vengeance"},
[97010]={a={"Maerion이 룬이 새겨진 파편을 준비했대요.","높은 탑에서 던지면 파편이 산산이 부서진대요.","Horde Mage Tower에 올라 신호로 파편을 던져 달래요."}},
[97029]={a={"Ealaane Nimbuswalker가 당신의 칼을 보고 싶대요.","전에 준 손잡이와 짝을 이루는 쌍둥이 검인 것 같대요.","운명이라며 칼을 살펴봐도 되냐고 해요."},c={"Ealaane Nimbuswalker가 Eluvi'ana라고 확인해요.","수 세기 동안 사라졌던 칼이라 아주 귀하대요.","마법은 약하지만 여전히 날카로워 쓸 만하대요."}},
[97048]={a={"Wendel Mathers는 Captain Aransas 배의 요리사예요.","지금은 보답할 게 없지만 좋게 말해 준대요.","무법항에 있는 선장을 만나 보래요."},c={"선장은 Mathers가 과장했다며 웃어요.","그래도 선원을 구해 줘서 고맙다고 해요."}},
[97049]={a={"연금술사 퓰리가 부탁을 하나 해요.","Shaper's Terrace의 무색 수정 옆 웅덩이에 점액이 있대요.","그 점액의 정수를 실험용으로 가져다 달래요."}},
[97119]={a={"Ortak Lomgok은 이곳 사람들에게 음식도 챙겨 줘요.","눈망루 마을 고블린이 팔던 작은 사슴고기 요리를 그리워해요.","산에 사슴이 많으니 그 요리를 만들어 줄 수 있냐고 물어요."}},
[97174]={a={"Garen Largo가 이제 때가 왔다고 해요.","Forsaken 성기사는 복수의 영혼인 돌격마와 짝을 맺어야 완성된대요.","티리스팔 숲에서 Danitha Morr를 찾아가래요."}},
[97175]={a={"Danitha Morr가 큰일에는 희생이 따른다고 해요.","오그리마의 제이우스에게서 퇴마 향로를 받아야 해요.","제이우스가 향로 값으로 기부금을 요구할 거래요."}},
[97176]={a={"Danitha Morr가 테러데일 흙을 넣은 퇴마 향로를 줬대요.","동부 역병지대에서 괴로운 원혼들이 모여 있대요.","향로로 원혼을 찾아 괴로움에서 풀어 달래요."}},
[97177]={a={"제이우스가 퇴마 향로를 건네줘요.","나쁜 부두 영혼을 쫓을 때 여러 번 썼대요.","티리스팔 숲의 Danitha Morr에게 향로를 가져가래요."}},
[97178]={a={"성기사의 군마에게 좋은 마갑이 필요하대요.","타렌 밀농장 밖에 솜씨 좋은 오크 대장장이가 있대요.","그 대장장이 Ott에게 마갑을 맡겨 달래요."}},
[97179]={a={"Ott이 마갑을 만들려면 재료가 필요하대요.","룬무늬 옷감과 아서스의 눈물이 필요하대요.","힐스브래드 구릉지의 Ott에게 재료와 수고비를 가져가래요."}},
[97180]={a={"Ott이 마갑을 완성했대요.","Ott은 이 마갑이 자기 최고 작품 중 하나래요.","아케이나이트 마갑을 Danitha Morr에게 가져가 보여 달래요."}},
[97182]={a={"타락한 굽이나무 텐드리스가 고대 준마의 영혼을 가뒀대요.","풀려나면 마갑에 축복을 줄지도 모른대요.","동부 역병지대의 나타노스 블라이트콜러에게 특별한 사료를 구해 달래요."}},
[97183]={a={"고대 준마의 영혼이 마갑에 축복을 내렸대요.","마갑은 빛나며 당신의 가방 안에 들어갔대요.","티리스팔 숲의 Danitha Morr에게 돌아가 달래요."}},
[97184]={a={"예언의 탐지기를 만들려면 다이아몬드가 필요하대요.","흰색과 검은색 다이아몬드가 필요하대요.","두 다이아몬드를 Danitha Morr에게 가져다 달래요."}},
[97185]={a={"스칼로맨스 지하에서 예언의 탐지기로 영혼을 불러내야 해요.","영혼들을 물리치면 죽음의 기사 다크리버가 나타난대요.","다크리버를 쓰러뜨리고 군마의 영혼을 되찾아 달래요."}},
[97186]={a={"나타노스 블라이트콜러는 영혼 말을 돌보는 법을 안대요.","영적인 비스킷은 Argent Dawn에서만 파는 것이래요.","비스킷과 얼마간의 금화를 가져와 달래요."}},
[97194]={a={"킬다르가 늑대 타기 기술을 가르쳐 준대요.","배우고 나면 오구나로가 무료 탈것을 준대요.","돈을 충분히 모아서 다시 오래요."}},
[97196]={a={"Sutara Plainstalker는 Scourge 첩자를 잡고 싶대요.","가시덩굴 구릉 깊숙이 Lich King의 부하가 살대요.","혹한의 암네나르의 구슬을 가져와 달래요."}},
[97197]={a={"Alaana Stormwalker는 원소 생물을 연구하고 싶어 해요.","검은바위 산 깊은 곳에서 원소 생물들이 빠져나온대요.","검은바위 나락에 가서 조각을 하나 구해 달래요."}},
[97198]={a={"Muln Earthfury는 Blackmaw 무리를 알고 싶어 해요.","Blackmaw 무리가 어두운 마법에 오염됐대요.","Blackmaw Hold에 가서 의식 토템을 가져다 달래요."}},
[97200]={a={"Xar'Ti가 랩터 타기를 가르쳐 준대요.","배우고 나면 졸니르가 무료 탈것을 준대요.","돈을 모아서 다시 와 달래요."}},
[97203]={a={"벨마 워넘은 해골 말 타는 법을 돈을 받고 가르쳐요.","훈련을 마치면 자카리아 포스트가 무료로 탈것을 준대요.","돈이 모이면 벨마 워넘을 찾아가 배워 달래요."}},
[97204]={a={"카르 스톰싱어가 kodo 타기를 가르쳐 준대요.","배우고 나면 할브 클로후프가 무료 탈것을 준대요.","돈이 충분하면 다시 오래요."}},
[97205]={a={"Genn Fairweather는 모험가로 충분히 성장했다고 반겨요.","galestrider 타는 법을 수수료를 받고 가르쳐 준대요.","돈을 충분히 모으면 다시 찾아와 달래요."}},
[97223]={a={"Xar'Ti는 직접 길들인 랩터들을 키운대요.","사나운 Bloodtalon Matriarch가 사람을 많이 죽였대요.","그 암컷을 쓰러뜨리고 알을 가져와 달래요."},c={"Xar'Ti는 그 혈통을 지켜 동맹으로 키우게 돼 기쁘대요.","당신이 부족을 위해 큰일을 해냈대요."}},
[97225]={a={"장로 보르날은 메아리 섬에 흩어진 loa 우상을 걱정해요.","잘라제인의 무리가 우상을 흩어 놓았대요.","흩어진 우상을 최대한 많이 찾아 달래요."},c={"장로 가드린은 큰일을 했다고 칭찬해요.","Darkspear가 loa의 마음을 잃으면 안 된대요.","우리는 loa를 공경하고 존중한대요."}},
[97235]={a={"반지를 새로 만드는 일을 맡은 사람이 있어요.","보석은 있지만 마법 금속이 없으면 소용없대요.","Enchanted Thorium Bars를 구해 달라고 부탁해요."}},
[97242]={a={"옐마크의 견습생은 자존심이 세서 도움을 청하지 않는대요.","옐마크는 그에게 집에서 만든 조제법을 맛보여 주려 해요.","Valley of Honor 물가의 풀을 꺾어 달래요."},nx=97275,nt="Whuut's the Rush"},
[97243]={a={"Sessaria Skystride는 정령들의 목소리를 듣는 사람이에요.","불과 가장 잘 맞는 사람은 Olariaan Swiftburn이래요.","Shrine of Flames에 있는 그에게 이것을 전해 달래요."},c={"Olariaan Swiftburn은 불의 부름을 가르쳐 주겠대요.","그래도 쉽지는 않을 거래요."},nx=97244,nt="Call of Fire"},
[97244]={a={"Olariaan Swiftburn은 배신자 Faladiel을 원망해요.","Faladiel은 힘을 좇아 옛 동료들을 죽였대요.","그 배신자를 처단하고 심장을 가져와 달래요."},c={"Olariaan Swiftburn은 피는 피로 갚는다고 해요.","배신자에게 이 교훈을 전해 줘서 기쁘대요.","심장 말고도 할 일이 하나 더 있대요."},nx=97245,nt="Call of Fire"},
[97245]={a={"Olariaan Swiftburn이 옛 숲의 정령 이야기를 들려줘요.","Kuramaa라는 정령이 언덕 위 뒤틀린 그루터기에 산대요.","그 정령을 이기고 나무 가면을 가져다 달래요."},c={"Olariaan Swiftburn은 이제 필요한 것을 다 모았대요.","영원의 불꽃을 밝혀 불의 정령들과 교감하겠대요."},nx=97257,nt="Call of Fire"},
[97246]={a={"Thatog의 아들 Migi는 늘 배고파 돌아온대요.","Thatog는 아들이 점심을 잘 안 찾아가서 걱정해요.","Migi에게 점심을 전해 달래요."},c={"보르스탄은 Migi의 도시락을 매일 준비해 둔대요.","다만 Migi가 직접 와야 밥을 챙길 수 있대요.","그렇게 놀 힘이 어디서 나는지 궁금하대요."}},
[97249]={a={"보르스탄은 Migi의 부모가 식사를 걱정한다는 걸 알았어요.","남은 바삭한 가루를 샌드위치에 얹어 주려고 해요.","이 점심을 Migi에게 가져다 달래요."},c={"Migi는 진한 가루 맛이 마음에 든대요.","매일 이 맛이면 게임을 멈추고 같이 먹어야겠대요."},nx=97326,nt="Rocks to Rests"},
[97250]={a={"그런트 로그마르가 먼지진흙 습지대 국경 소식을 전해요.","사람 병사들이 우리 땅의 표지를 무너뜨렸대요.","처치하고 타우라조 야영지에 돌아와 달래요."},c={"소문이 사실이었대요.","우리가 술집을 불태웠을 것 같지 않대요.","그래도 오늘 승리는 우리 쪽이래요."}},
[97253]={a={"비운의 레닉스가 보낸 사람들은 살아 돌아오지 못했대요.","기계를 보냈지만 해적 야영지에서 부서져 흩어졌대요.","흩어진 부품을 되찾아 와 달래요."},c={"비운의 레닉스는 고맙다며 기뻐해요.","객스프로켓의 금속 값 잔소리에서 구해 줬대요.","보상은 없지만 상자를 좋아하냐고 물어요."}},
[97257]={a={"Olariaan Swiftburn이 불의 의식을 치르려고 해요.","재료를 제단에 올리면 정령들이 영원의 불꽃을 밝힌대요.","불이 꺼지기 전에 Valanaar 화로까지 빨리 옮겨 달래요."},c={"Sessaria Skystride는 영원의 불꽃이 다시 타올랐대요.","그리고 불의 토템을 선물로 준대요.","정령의 힘은 존중하는 이를 돕고 무시하는 이는 해친대요."}},
[97264]={a={"사르 바라운아이의 캠프는 사나워진 톱니이빨곰 때문에 힘들어요.","곰들이 먹이를 두고 다투다 캠프까지 쳐들어온대요.","가장 나이 든 덩치큰 톱니이빨곰을 솎아 달래요."}},
[97265]={a={"Aka'rai는 satyr와 거래했다가 버려졌대요.","이제 Hatefury에게 복수하고 싶대요.","북동쪽 진영을 습격해 달래요."},c={"그 satyr가 아직 잊혀진 땅을 떠돌아요.","그가 영혼석을 가져가서 밖에 못 나간대요."}},
[97275]={a={"옐마크는 Whuut이 재능은 있지만 경험이 적대요.","Whuut은 기초 연습 없이 귀한 재료만 쓰고 있대요.","Whuut에게 이 물약을 전해 달래요."},c={"Whuut은 흔한 풀로만 물약을 만들었냐며 놀라요.","흔한 풀이 쓸모 있을 줄 몰랐대요.","Drakath에게 물약 하나를 골라 가라고 해요."}},
[97279]={a={"고르넥은 신병이 많이 와서 무기가 모자란대요.","크잔 손슬래시에게 훈련용 무기가 거의 떨어졌대요.","땅에 버려진 훈련용 무기를 주워 와 달래요."},c={"크잔 손슬래시는 무기를 가져다 줘서 고맙대요.","다음 신병들을 위해 무기를 고칠 거래요."}},
[97281]={a={"이상한 구슬 하나가 놓여 있어요.","안에 검은 안개가 돌고 가끔 전기 불꽃이 튀어요.","모래바람 협곡의 레즐락이 관심을 가질지도 모른대요."},c={"레즐락은 이런 신기한 물건을 어디서 찾았냐고 놀라요.","보스 가즈로가 늘 하던 말이 떠오른대요."},nx=97282,nt="Stormy Potential"},
[97282]={a={"레즐락은 가즈로에게 배운 대로 기회를 잡으려 해요.","구슬은 망가진 게 아니라 전기만 다 빠졌대요.","서쪽 협곡 번개 도마뱀의 전기 기관을 구해 와 달래요."},c={"레즐락은 도와줘서 고맙다며 기뻐해요.","이 기관으로 구슬이 다시 충전되길 바란대요.","하피들이 캐러밴 공격을 망설일 거래요."}},
[97287]={a={"학자 워딘 보이드글레어가 협상을 제안해요.","달라란의 오래된 지혜를 얻고 싶대요.","얻은 물건을 들고 Archmage Celindra를 만나 달래요."},c={"물건을 순순히 주다니 뭘 노리는지 모르겠대요.","대신 달라란 출입을 허락하고 계속 감시하겠대요."}},
[97288]={a={"쓰러진 괴물의 머리가 굴러 떨어졌대요.","머리는 여러 번 다시 붙인 흔적이 있대요.","그 머리를 아는 사람이 언더시티에 있대요."},c={"이 머리를 알아본대요. 누군가의 잔인한 장난이래요.","그 머리를 쓸 데가 있을 것 같대요."},nx=97289,nt="Unending Torment"},
[97289]={a={"수석 연금술사 파라넬은 이 머리가 특별하대요.","이 머리는 Othmar라는 원수의 것이었대요.","옆 방의 몸 옆에 두되 아직 붙이지 말래요."},nx=97290,nt="Unending Torment"},
[97291]={a={"수석 연금술사 파라넬이 재료를 부탁해요.","머리를 레이디의 뜻에 따르게 할 약을 만든대요.","타우니 그리제트 등에게 재료를 구해 달래요."},c={"재료가 쓸 만하다며 좋아해요.","그 손님이 실험을 얼마나 버틸지 보겠대요."},nx=97292,nt="Unending Torment"},
[97292]={a={"파라넬이 새 혈청을 만들었대요.","그 혈청을 Othmar 위쪽 장치에 넣으래요.","그를 충성하게 만들 거니 떨어뜨리지 말래요."},c={"파라넬은 Othmar를 잠시 두고 지켜보겠대요.","Othmar를 어떻게 쓸지 계획이 많대요."}},
[97319]={a={"은빛장교 가루쉬의 사촌이 Kalimdor에서 모험 중이래요.","마지막으로 들은 소식으론 하이잘 산으로 가는 중이래요.","하이잘 산에 가면 살아 있는지 알려 달래요."}},
[97326]={a={"Thra와 친구들이 Grommash Hold 뒤에서 게임을 하고 있어요.","그런데 앉을 만한 돌이 부족해서 불편하대요.","매끈하고 적당한 크기의 돌을 날라 달래요."},c={"Thra는 돌을 어떻게 다 들었냐며 놀라워해요.","대부분 한쪽이 평평해서 좋대요.","이제 흙바닥에서 원하는 자리로 옮기면 된대요."}},
[97327]={a={"Ekkal의 형제들은 Blackmaw Hold에서 타락했대요.","Ekkal은 가족에게 기억할 물건을 주고 싶대요.","Blackmaw Hold에서 소지품 주머니를 가져다 달래요."}},
[97328]={a={"비행선이 떨어진 잔해 속에서 물자를 찾았어요.","물자는 이미 털렸고 무법항이라는 글씨만 보여요.","줄쿤다의 폐허에서 물자를 되찾아 무법항에 가져가래요."},c={"이 물자는 몇 주 전에 도착했어야 했대요.","트롤들이 빼돌렸다니 이제 보험 청구를 해야 한대요."},nx=97332,nt="Twice Misplaced Trust"},
[97331]={a={"Zimmix Sputterspark가 다시 잡힐까 봐 겁내요.","트롤이 아주 많아서 혼자는 못 나간대요.","줄쿤다의 폐허에서 함께 나가 달래요."},c={"Zimmix를 구해 준 분이라니 타이밍이 최악이래요.","그가 또 실수할까 봐 걱정된대요.","다음엔 철창에 갇힌 고블린은 그냥 두래요."},nx=97332,nt="Twice Misplaced Trust"},
[97332]={a={"부두주임 로즈길이 급한 배달을 맡을 사람을 찾아요.","Zimmix는 믿을 수 없고 당신은 믿을 만해 보인대요.","Powderfuse Port의 Whizzbuzz에게 이 물건을 전해 달래요."},c={"Whizzbuzz가 상자를 들여다보고 깜짝 놀라 웃어요.","로즈길이 드디어 해냈다고 좋아해요.","고생했다며 당신에게 보상을 준대요."}},
[97378]={a={"멜로르 스톤후프가 당신의 용기를 높이 산대요.","페랄라스 해안 길에서 wind serpent가 여행자를 해쳤대요.","폭포 아래 Mirrorscale의 날개를 가져와 달래요."}},
[97386]={a={"사령관 아그로고쉬는 Grom'gol을 지키는 데 도움을 고마워해요.","동쪽 먼 곳에 ogre들이 굴을 차지했대요.","친구와 함께 가서 다시는 위협하지 못하게 해 달래요."}},
[97403]={a={"릴란 하워드는 이 빈터에 정착하려고 애쓰고 있어요.","Chillwind Ravagers가 우리 주변을 계속 맴돌아요.","그 짐승들을 없애 달라고 부탁해요."}},
