[98215]={a={"용들 때문에 우리가 불에 잘 탄다는 게 문제래요.","용들은 자기 불에 타지 않는 비늘이 있대요.","떨어진 용 비늘을 주워 오면 보상해 준대요."}},
[98231]={a={"Gizzix가 Miss Melly의 화상을 걱정해요.","Miss Melly는 겁을 먹어 움직이려 하지 않는대요.","이 근처에서 자라는 Wyrmtail을 찾아다 달래요."}},
[98248]={a={"찢어진 배송 라벨이 물건 상자에 붙어 있었대요.","수령인은 찢겨 나갔지만 보낸 곳 정보는 남아 있대요.","듀로타 Supply and Logistics 거점에 전해 달래요."},c={"맞는 곳에 찾아와서 새 동료로 등록해 준대요.","문제 있는 배송을 도우면 Merchant's Favor를 얻는대요.","이 라벨이 달린 상자를 갖고 있냐고 물어요."}},
[98251]={a={"Va'xug Firefure는 잿빛 골짜기 협곡에 갇혀 있대요.","잿빛 골짜기가 쉽다더니 길을 잃었다고 화가 났대요.","근처 야생동물을 좀 줄여 달래요."},c={"짐승들이 혼쭐났다며 속이 시원하대요.","이미 도움이 된 것 같대요."},nx=98252,nt="A Void Path"},
[98252]={a={"Va'xug Firefure는 협곡에 머물고 있대요.","킬로그의 눈에게 잿빛 골짜기 큰길을 보여 달래요.","시야가 끊기기 전에 큰길에 닿으래요."}},
[98284]={a={"Raan Wildwind는 마법 부여사가 캠프에 도움 된다고 해요.","야영 중 즐길 거리가 있으면 여행에 도움이 된대요.","마법 류트 만드는 법을 배우러 가 보라고 해요."},c={"Nasalanna Windsinger가 이제 마법 류트를 만들 줄 안대요.","캠프는 마을 한가운데 말고 야생에서 시험해 보래요.","캠프에 필요한 모닥불은 요리사에게 배우래요."}},
[98285]={a={"Strange Hermit는 혼자 야생에 있을 때 공학이 쓸모 있대요.","좋은 캠프에는 도움 되는 장치도 몇 개 있어야 한대요.","공학 실력이 좀 쌓이면 다시 찾아오래요."},c={"Strange Hermit가 이제 시약 로봇을 만들 줄 안대요.","캠프는 마을 한가운데 말고 야생에서 시험해 보래요.","캠프에 필요한 모닥불은 요리사에게 배우래요."}},
[98298]={a={"달라 던위버는 아루갈이 worgen을 만들 힘이 없었다고 해요.","저주가 다른 방식으로 퍼졌을 거래요.","worgen을 처치해 찾은 걸 가져다 달래요."},c={"달라 던위버는 아루갈이 사기꾼이었다는 걸 밝혔다고 좋아해요.","이 조각들이 저주는 아루갈과 상관없다는 증거래요.","그래서 아루갈의 치료법도 쓸모없게 됐대요."}},
[98299]={a={"달라 던위버는 아루갈 탓에 생긴 저주를 막으려 해요.","Greymane Wall 앞에 난민들이 모여 있대요.","그들이 아루갈의 하인이 되기 전에 처치해 달래요."},c={"벽 안 사람들은 누구도 들이지 않으려 했대요.","그래서 저주가 그들의 도시로 퍼질 일은 없대요."}},
[98325]={a={"장군 고어투스는 호드 최고의 전사만 찾는대요.","용기가 필요한 일이라 겁쟁이는 필요 없대요.","용기가 있으면 먼저 이야기해 보래요."}},
[98340]={a={"투락 룬토템이 이제 다음 단계를 준비할 때라고 해요.","덴드리트 스타블레이즈가 달의 숲에서 다시 만나자고 불렀대요.","드루이드 수련을 이으려면 서둘러 달의 숲으로 가래요."},c={"덴드리트 스타블레이즈가 다시 만나 반가워해요.","이제 자연의 다음 모습인 살쾡이를 배울 때래요.","곰처럼 이 배움도 스스로 익혀야 한대요."},nx=98341,nt="The Great Windborne Cat Spirit"},
[98341]={a={"덴드리트 스타블레이즈는 고향의 정령이 나타났다고 해요.","Windborne Cat Spirit가 고양이 모습을 가르쳐 줄 스승이래요.","달의 숲 남쪽에 있는 그 정령을 찾아가 달래요."},c={"Avatar of Saeyleenan은 시험을 치를 준비가 된 것 같대요.","같은 Zephras 출신이라 직접 지켜보겠대요.","먼저 거대한 살쾡이의 혼의 시험을 치르래요."},nx=98404,nt="The Great Windborne Cat Spirit"},
[98342]={a={"거대한 살쾡이의 혼은 자신의 힘을 쓰려면 시험이 필요하대요.","교활함, 은신, 사나움을 보여야 한대요.","동쪽 Barrow Dens의 유물들을 가져다 달래요."},c={"거대한 살쾡이의 혼은 고양이의 참뜻을 이해했다고 칭찬해요.","그 모습을 취할 자격이 있다며 축복을 내려요."},nx=98739,nt="Blessings of the Great Cat Spirit"},
[98362]={a={"덴드리트 스타블레이즈는 이제 헤어질 때라고 해요.","투락 룬토템이 좋은 제자를 얻었대요.","썬더 블러프 장로의 봉우리에 있는 투락 룬토템을 찾아가 달래요."},c={"투락 룬토템은 시험을 마치고 돌아온 모험가를 반겨요.","거대한 살쾡이의 혼의 시험을 잘 통과해 자랑스럽대요.","이제 고양이의 모습을 취하는 법을 가르쳐 준대요."}},
[98389]={a={"Aramis Hammerhand는 일부 동료가 성기사를 두려워한대요.","Night's Web Hollow에서 거미에 갇힌 이들을 구해 주래요.","다른 이들에게 우리의 본모습을 보여 주는 걸 도와 달래요."}},
[98404]={a={"Avatar of Saeyleenan은 힘을 쓰려면 시험이 필요하대요.","교활함, 은신, 사나움을 보여야 한대요.","동쪽 Barrow Dens의 유물들을 가져다 달래요."},c={"Avatar of Saeyleenan은 참뜻을 이해했다고 칭찬해요.","그 모습을 취할 자격이 있다며 축복을 내려요."},nx=98738,nt="Blessings of the Great Windborne Cat Spirit"},
[98405]={a={"덴드리트 스타블레이즈가 고양이의 스승을 소개해요.","달의 숲 남쪽 언덕에 거대한 살쾡이의 혼이 있대요.","그 영혼을 찾아가 고양이의 가르침을 배워 달래요."},c={"거대한 살쾡이의 혼은 배우러 온 것을 알아봤대요.","이제 고양이 모습을 취할 준비가 됐는지 보겠대요."},nx=98342,nt="The Great Cat Spirit"},
[98424]={a={"감독관 피즈스프로켓의 주머니에서 낡은 종이가 나왔대요.","투자개발회사에 맞설 중요한 정보가 적혀 있는 것 같대요.","투자개발회사 광산에서 나머지 쪽지를 찾아 와 달래요."},c={"모린 클라우드스토커는 이 정보가 아주 귀하다고 해요.","도와줘서 고맙다고 했대요.","이제 다음 할 일이 분명해졌대요."},nx=98427,nt="Ceasing Operations"},
[98427]={a={"모린 클라우드스토커는 숲을 빠르게 베는 벌목 기계를 걱정해요.","이 마을 근처 숲이 그렇게 사라지는 걸 두고 볼 수 없대요.","다른 사람들과 북동쪽 광산에 가서 나무를 더 못 베게 해 달래요."},c={"블러드후프 마을이 오늘 당신에게 큰 빚을 졌대요.","대지의 어머니의 은총이 늘 함께하길 바란대요."}},
[98430]={a={"Perith Stormhoof는 대족장 케른 블러드후프의 명을 받고 왔어요.","대화하려다 gnoll들에게 폭력을 당해 목숨이 위험하대요.","회색갈기일족 바위굴에서 탈출하게 도와 달래요."}},
[98435]={a={"멀 썬더혼은 썬더 블러프의 장로들에게 소식을 전하려 해요.","이 일은 모험가의 도움 덕분에 진전됐대요.","대드루이드 하뮬 룬토템에게 보고서를 전해 달래요."},c={"대드루이드 하뮬 룬토템은 멀고어에 기쁨이 흐른다고 해요.","우물은 사람과 야생동물 모두에게 중요하대요.","고마움의 선물도 준다고 해요."}},
[98462]={a={"에비 휠브루는 다시 찾아온 사람을 반갑게 맞아요.","주변 짐승들의 눈을 피하게 해 줄 물약을 만들려고 해요.","서리바람 키메라의 털과 여명의설원 올빼미 깃털을 가져다 달래요."}},
[98477]={a={"정령계로 넘어갈 때 이상한 뒤틀림이 느껴진대요.","그 정체를 알아보려고 모험가가 필요하대요.","강한 마법사에게서 불안정한 마력 알갱이를 모아 달래요."}},
[98512]={a={"Fendaal Windstone은 이상한 낌새를 챘어요.","북쪽 언덕 위 집 주변에 Al'Aketh가 몰래 숨어 있대요.","가서 그들을 물리쳐 달라고 부탁해요."},nx=92644,nt="Unfortunate News"},
[98517]={a={"정령들이 당신이 불의 부름에 응할 준비가 됐다고 해요.","하지만 그 길은 자기가 열어 주지 않는대요.","원소 세계의 스승들에게 돌아가 물어보래요."}},
[98545]={a={"존경받는 리어니드 바돌로매에게는 언더시티에 옛 친구가 있어요.","예전 일 때문에 직접 가기 곤란하대요.","언더시티 무역 구역의 Glix Xizzix에게 편지를 전해 달래요."},c={"Glix Xizzix는 편지 전달에 고맙다고 해요.","팁을 주겠다는 말은 자기가 동의한 적 없대요.","대신 유실물 보관함의 잡동사니 중에 골라 가래요."}},
[98575]={a={"고르넥은 흑마법사와 엮이는 걸 피하는 편이래요.","당신이 없을 때 석판이 하나 도착했대요.","석판을 읽고 나르톡을 찾아가 보래요."},c={"나르톡은 당신이 힘의 일부를 엿봤다고 해요.","약하고 어리석은 사람들은 이 길을 두려워한대요.","이제 우리 편이 됐고, 주문을 배우려면 다시 오래요."}},
[98576]={a={"고르넥은 없던 사이 편지가 왔다고 알려 줘요.","편지는 마법사 교관 마이아가 보낸 것이래요.","시험의 골짜기 입구 근처의 마이아를 찾아가래요."},c={"마이아는 마법이 큰 힘이라도 참을성이 있어야 한대요.","잘 살피고 알맞게 대응하면 뭐든 해낼 수 있대요.","준비가 되면 마이아에게 돌아가 훈련을 받으래요."}},
[98601]={a={"어둠의사제 사비스가 당신에게 온 두루마리를 전해 줬대요.","두루마리에서 빛의 기운이 짙어 성기사에게 중요한 것 같대요.","읽고 나서 데스넬 교회의 Aramis Hammerhand를 만나 달래요."},c={"Aramis Hammerhand는 이제 본격적으로 훈련하라고 해요.","잠시도 빛을 등지지 말고 그 고통도 받아들이래요.","그 고통이 시련이 되어 전생보다 강해질 거래요."}},
[98738]={a={"Avatar of Saeyleenan은 이미 축복을 내려 줬대요.","가르칠 것이 지금은 많지 않아 아쉬워한대요.","이제 덴드리트 스타블레이즈에게 돌아가 달래요."},c={"덴드리트 스타블레이즈는 몸속 고양이의 교활함과 사나움이 느껴진대요.","은밀함과 빠름을 이해했으니 고양이의 본성을 익힐 수 있대요.","이제 그 정령의 힘을 부를 수 있대요."}},
[98739]={a={"거대한 살쾡이의 혼이 축복을 내려 줬대요.","언젠가 다시 만나자고 해요.","덴드리트 스타블레이즈에게 돌아가 달래요."},c={"덴드리트 스타블레이즈는 몸속 고양이의 교활함과 사나움이 느껴진대요.","은밀함과 빠름을 이해했으니 고양이의 본성을 익힐 수 있대요.","이제 그 정령의 힘을 부를 수 있대요."},nx=98362,nt="To Thunder Bluff"},
[98823]={a={"바샤나 룬토템이 이 유물을 보고 놀랐대요.","단순한 조각이 아니라고 해요.","Muln Earthfury에게 직접 가져가래요."},c={"이 조각에서 세상의 목소리가 울린대요.","메시지를 받으면 그 진실을 나누겠대요."}},
[98887]={a={"호드 돌격대장이 Darkspear Islands 싸움을 알려요.","Theramore 원정대가 병력을 계속 보내고 있대요.","싸움의 증거를 가져오면 큰 보상을 준대요."},c={"Darkspear Islands 모래가 적의 피로 물들었대요.","잘했다고 칭찬해 줘요."}},
[98889]={a={"Theramore 원정대가 계속 병력을 보낸대요.","호드의 힘을 보여 주라고 해요.","승리의 증표를 가져오면 보상을 듬뿍 준대요."}},
[98891]={a={"Theramore 원정대가 계속 병력을 보낸대요.","호드의 힘을 보여 주라고 해요.","승리의 증표를 가져오면 보상을 듬뿍 준대요."}},
[98893]={a={"Theramore 원정대가 계속 병력을 보낸대요.","호드의 힘을 보여 주라고 해요.","승리의 증표를 가져오면 보상을 듬뿍 준대요."}},
[98906]={a={"Nizook Boof는 이 전투가 교착 상태래요.","Alliance에게 누가 강한지 보여 주래요.","승리한 뒤 무역 해안으로 돌아와 달래요."},c={"Darkspear Islands에서 힘과 헌신을 보여 줬대요.","전투 실력이 대단해서 칭찬할 만하대요."}},
[98907]={a={"Darkspear Islands 싸움이 교착 상태래요.","Alliance 녀석들에게 누가 강한지 보여 주래요.","전장에서 이기고 무역 해안의 Nizook Boof에게 돌아가 달래요."}},
[98908]={a={"Darkspear Islands 싸움이 교착 상태래요.","Alliance 녀석들에게 누가 강한지 보여 주래요.","전장에서 이기고 무역 해안의 Nizook Boof에게 돌아가 달래요."}},
[98916]={a={"Darkspear Islands의 싸움이 여러 번 있었대요.","아직 너무 가까워서 마음에 안 든대요.","모든 거점을 차지하고 Alliance를 이기래요."}},
[98917]={a={"Darkspear Islands에서 호드를 크게 꺾었대요.","이제 그들의 사기까지 완전히 꺾어야 한대요.","모든 거점을 차지하고 Theramore 원정대의 힘을 보여 주래요."}},
[99048]={a={"오르그닐 소울스카는 Shattered Hand 요원의 보고가 끊겨 걱정해요.","그 요원은 타이라가드 요새를 멀리서 지켜보고 있었대요.","타이라가드 요새 북쪽에서 Heglan Shadeeye를 찾아봐 달래요."},c={"Heglan Shadeeye의 시신이 오두막 잔해 속에 있었대요.","그녀를 죽인 건 사람이 아닌 것 같대요.","근처에 무슨 일이 있었는지 단서가 있을지도 모른대요."},nx=99049,nt="Threat from Below"},
[99049]={a={"근처 땅이 싸움으로 완전히 망가져 있대요.","Heglan Shadeeye를 습격한 자들도 무사하진 못했대요.","오르그닐 소울스카에게 줄 증거를 찾아봐 달래요."},c={"오르그닐 소울스카는 이 깃발과 칼날이 naga의 것이라고 해요.","naga들이 북쪽 해안을 따라 내려온 것 같대요.","양쪽에서 밀려오면 칼바위 언덕이 버티기 어렵대요."},nx=99051,nt="Threat from Below"},
[99051]={a={"오르그닐 소울스카는 naga들이 또 귀찮게 굴었다고 해요.","그들에게 이곳에 머물 수 없다는 걸 알려 줘야 한대요.","정찰병 야영지를 찾아 처치하고 지느러미를 가져오래요."},c={"오르그닐 소울스카는 naga들이 북쪽으로 돌아가길 바란대요.","남은 자들은 부하들이 감시하겠대요."},nx=99052,nt="Threat from Below"},
[99052]={a={"오르그닐 소울스카는 sea giant가 naga를 따라 왔다고 해요.","어려도 방심하면 orc도 찢을 수 있을 만큼 위험하대요.","도움을 줄 사람과 함께 그 녀석을 처치해 달래요."},c={"오르그닐 소울스카는 바다 거인이 쓰러지는 소리가 들렸대요.","바다 거인과 싸워 살아남은 사람은 많지 않대요."}},
[99079]={a={"용사 와일드러너는 정찰병 Malah가 돌아오지 않아 걱정해요.","Malah는 동쪽 국경 근처로 떠났는데 소식이 없대요.","블러드후프 마을 동쪽에서 Malah를 찾아 달래요."},c={"Malah가 자연사한 게 아니라는 게 분명하대요.","등과 주변 땅에 화살이 가득 꽂혀 있대요."},nx=99081,nt="Grim Tidings"},
[99080]={a={"바인 블러드후프는 centaur에게 땅을 내줄 수 없다고 해요.","그들이 마을로 오기 전에 막아야 한대요.","야영지로 가서 그들을 모두 처치해 달래요."},c={"바인 블러드후프는 당신이 centaur 피를 뒤집어썼다고 해요.","마지막 놈이 쓰러지자 발굽 소리가 멎었대요.","마을이 안전해졌다며 깊이 고마워해요."},nx=99082,nt="The High Chieftain"},
[99081]={a={"Malah Longwind의 손에 보고서가 쥐여 있대요.","화살이 날아온 쪽에 새 centaur 야영지가 생겼대요.","용사 와일드러너에게 이 보고서를 전해 달래요."},c={"용사 와일드러너는 이 소식이 아주 심각하다고 해요.","바로 Baine에게 알려야 한대요."},nx=99101,nt="Our Ancient Enemy"},
[99082]={a={"바인 블러드후프는 당신의 용기를 인정해 줘야 한대요.","그의 아버지 케른 블러드후프가 앞장서서 centaur를 몰아냈대요.","썬더 블러프에 가서 대족장 케른 블러드후프를 만나 달래요."},c={"케른 블러드후프는 centaur가 멀고어에 나타난 걸 놀라워해요.","당신이 centaur를 몰아내 조상들에게 자랑이 됐대요.","선물을 주며 앞으로 여행에 도움이 되길 바란대요."}},
[99101]={a={"용사 와일드러너는 침입 소식을 바인 블러드후프에게 알려야 한대요.","지금 당장 알려야 할 만큼 급한 일이래요.","Malah의 보고서를 바인 블러드후프에게 가져가 달래요."},nx=99080,nt="Drive Them Out"},
[99108]={a={"크랑 스톤후프는 전사가 아니어도 배울 게 있다고 해요.","투기장에서는 누구나 직접 싸우며 실력을 키운대요.","투기장에 들어가 상대와 겨뤄 보래요."}},
[99123]={a={"Pal'juh는 혼자 정찰을 나갔다가 마법이 떨어졌대요.","그 뒤로 콜카르 바윗골에 숨어 빠져나오지 못했대요.","빠져나가게 도와 달래요."},c={"장로 보르날은 Pal'juh가 또 말썽을 부렸다고 해요.","도와줘서 고마워하며, 이번엔 혼자 나선 걸 깨달았으면 좋겠대요.","유망한 사냥꾼인데 성격이 너무 급하대요."}},
[99134]={a={"집행관 자이건드는 당신이 아직 실망시키지 않았대요.","능력을 지나치게 뽐낸 Deathguard가 있대요.","그런 Deathguard를 벌하러 가래요."},c={"집행관 자이건드는 죽음에서 얻는 기쁨은 고통뿐이래요.","당신이 기쁘게 해 줘서 레이디도 기뻐한대요.","앞으로 또 쓸모가 있을지도 모른대요."}},
[99141]={a={"집행관 자이건드는 Deathguard들의 보고서가 늦어 화가 났대요.","보고서를 늦춘 자들이 여럿 있대요.","그들의 보고서를 받아 집행관 자이건드에게 가져가래요."},c={"집행관 자이건드는 고르도가 쓸모 있는 글을 쓸 거라 믿은 게 실수래요.","이 일은 둘만의 비밀로 하자고 해요.","당신이 기쁘게 해 줘서 희망이 있을지 모른대요."}},
[99142]={a={"초보연금술사 홀랜드는 동쪽 발니르 농장에 일을 더 맡기려 해요.","홀랜드는 doom weed를 손봐서 농장에 심고 있대요.","농장에서 tomb weed를 모아 가져다 달래요."},c={"초보연금술사 홀랜드는 아주 훌륭하다며 기뻐해요.","풀이 더 사납게 자라길 바랐는데 아쉬워해요.","많은 사람이 이 일 때문에 죽을 거라고 해요."}},
[99144]={a={"Bareth Dawnstone은 메시지를 들고 가다 붙잡혔대요.","붙잡은 자들은 빛의 힘을 증오로 쓰는 자들이래요.","빠져나가게 도와 달래요."}},
[99152]={a={"Hilda the Breaker는 교육생들을 실전에 맞게 키우려 해요.","마을 아래 지하실이 Scourge 봉기로 번질까 걱정이래요.","Shadowvale 아래에서 희미하게 빛나는 뼈를 가져다 달래요."}},
[99153]={a={"Ephram Barbaro는 당신의 활약을 들었대요.","도망친 cultist가 집중 수정 조각을 가지고 있대요.","Shadowvale 아래에서 그 조각을 찾아 달래요."}},
[99156]={a={"죽음의경비병 리니아는 새 보고에 크게 화가 났대요.","독그물 골짜기 근처에서 떠돌이 괴물이 나타났대요.","동료와 함께 처치하고 심장을 가져오래요."},c={"죽음의경비병 리니아는 Forsaken다운 교활함을 보였다고 해요.","생각 없는 Scourge는 절대 가질 수 없는 것이래요.","약속한 대로 고마움의 보상을 준대요."},nx=92422,nt="The Wrath of Rath'mael"},
[99187]={a={"Knight of Mourning은 맹세를 끝내야 영혼이 떠날 수 있대요.","Blackmaw가 Reliquary of Tyr를 아직 갖고 있을 거래요.","Reliquary of Tyr를 티리스팔 숲으로 가져다 달래요."}},
[99196]={a={"Windshapers가 양털 천을 기부받고 있대요.","기부하면 Windshapers에게 정식으로 인정받는대요.","가지고 있다면 지금 바로 건네 달래요."}},
[99197]={a={"Windshapers가 지금 비단 천이 필요하대요.","기부하면 Windshapers 사이에서 명예가 높아진대요.","비단 천을 가지고 있다면 지금 바로 건네 달래요."}},
[99198]={a={"Windshapers는 Mageweave에 큰 관심이 많대요.","Mageweave 천을 기부하면 단체가 꼭 기억한대요.","가지고 있다면 지금 바로 건네 달래요."}},
[99201]={a={"Xar'ti가 다시 온 것을 반겨요.","훈련을 마치면 졸니르가 갑옷 탈것을 무료로 준대요.","돈이 충분하면 raptor 타는 법을 가르쳐 준대요."}},
[99202]={a={"카르 스톰싱어가 armored kodo 타기를 권해요.","훈련을 마치면 Harb가 무료 탈것을 준대요.","돈이 모이면 다시 말을 걸라고 해요."}},
[99203]={a={"Genn Fairweather가 돌아온 것을 반겨요.","갑옷 galestrider 타기를 배울 준비가 됐냐고 물어요.","돈이 충분하면 다시 찾아와 달래요."}},
[99204]={a={"돌아온 나를 보고 이제 다음 단계로 가자고 해요.","마지막 훈련을 마치면 Ogunaro가 탈것을 무료로 준대요.","돈이 모이면 다시 와서 훈련을 끝내 달래요."}},
[99206]={a={"긁힌 자국과 흙먼지를 보니 세상을 많이 본 것 같대요.","마지막 훈련을 마치면 Katie가 탈것을 무료로 준대요.","돈이 모이면 무장한 말 타는 법을 가르쳐 준대요."}},
[99208]={a={"벨마 워넘은 당신이 돌아와서 반갑다고 해요.","이제 해골 전투마를 다루는 법을 배울 때래요.","돈이 모이면 벨마 워넘에게 마지막 훈련을 받아 달래요."}},
[99210]={a={"작은 마구간 주인이 나를 보고 많이 컸다며 반가워해요.","이제 가장 빠르고 사나운 ram을 탈 만하대요.","무장한 ram들을 보고 고른 뒤 다시 와 달래요."}},
[99211]={a={"마구간 주인이 당신이 금방 다시 찾아와 반가워해요.","이제 가장 무시무시한 전투마를 탈 만큼 강해졌대요.","무장한 언데드 전투마들을 살펴보고 골라 와 달래요."}},
[99212]={a={"오늘 mechanostrider에 내 생체 정보를 등록한다고 해요.","스트라이더를 타 본 경험이 충분해서 최고의 한 대를 탈 만하대요.","업그레이드된 mechanostrider들을 보고 골라서 다시 와 달래요."}},
[99213]={a={"다시 와 줘서 반갑대요.","가장 빠르고 사나운 말을 탈 만큼 경험이 쌓였대요.","무장한 말들을 살펴보고 골라서 다시 와 달래요."}},
[99214]={a={"다시 온 나를 반기며 saber와 맺어질 자격이 있대요.","saber는 똑똑하고 주인에게 충성스러워 좋은 짝이래요.","무장한 saber들을 살펴보고 골라서 다시 와 달래요."}},
[99215]={a={"예전에 만났던 사람이 다시 만나 반가워한대요.","이제 가장 빠르고 사나운 늑대를 탈 만큼 경험이 쌓였대요.","갑옷 늑대 중 마음에 드는 것을 골라 오래요."}},
[99216]={a={"galestrider 타기를 완전히 익힌 것을 축하해요.","이제 가장 빠르고 용맹한 갑옷 strider를 내줄 수 있대요.","갑옷 strider 중 골라서 다시 와 달래요."}},
[99217]={a={"다시 찾아온 사람을 기다렸다고 반가워해요.","이제 가장 빠르고 강한 kodo를 탈 수 있대요.","갑옷 kodo 중 마음에 드는 것을 골라 오래요."}},
[99218]={a={"오늘은 큰 날이라며 기뻐해요.","이제 가장 빠르고 사나운 raptor를 탈 준비가 됐대요.","갑옷 raptor 중 하나를 고른 뒤 다시 돌아와 달래요."}},
[99257]={a={"Historian Biraxas는 당신이 유령 숲을 헤매는 걸 봤대요.","기둥 수호자를 몇 세기 동안 새로 만들지 못했대요.","거의 무너진 기둥 수호자의 Crystal Heart를 가져다 달래요."},nx=99258,nt="Mana Mania"},
[99258]={a={"Biraxas는 마나가 아직 남았는지 알고 싶대요.","그 심장을 불안정한 틈에 던져 보라고 해요.","운이 좋으면 싸움이 날 테니 망설이지 말래요."}},
[99366]={a={"다시 와 줘서 반갑대요.","가장 빠르고 사나운 말을 탈 만큼 경험이 쌓였대요.","무장한 말들을 살펴보고 골라서 다시 와 달래요."}},
[99367]={a={"다시 와 줘서 반갑대요.","가장 빠르고 사나운 말을 탈 만큼 경험이 쌓였대요.","무장한 말들을 살펴보고 골라서 다시 와 달래요."}},
[99411]={a={"Ahab Wheathoof의 강아지 Kyle이 사라졌대요.","블러드후프 마을 어딘가에서 배고파하고 있을 거래요.","동쪽에서 타조 고기를 구해 Kyle에게 먹여 달래요."},c={"Ahab Wheathoof는 정말 잘했다고 기뻐해요.","Kyle은 먹자마자 집에 돌아와 바로 잠들었대요.","도와줘서 고맙다고 해요."}},
[99670]={a={"Jereman은 다행히 살아 있대요.","급히 빠져나와 곤경에서 벗어났대요.","Jereman이 당신과 얘기하고 싶어 하니 찾아가 달래요."}},
} }
